export default [{"id":37,"title":"إسلام عبد الله بن سلَام رَضي اللهُ عنه .","date":["العام الهجري :1","العام الميلادي :622"],"text":"كان عبدُ الله بن سلامٍ رَضي اللهُ عنه حَبْرًا من أحبارِ يَهودَ، عالِمًا، قال: لمَّا سَمِعتُ برسولِ الله صلَّى اللهُ عليه وسلَّم عَرَفتُ صِفَتَه واسمَه وزَمانَه الذي كنا نتوقَّعُ له، فكنتُ مُسِرًّا لذلك، صامِتًا عليه، حتى قَدِمَ رسولُ الله صلَّى اللهُ عليه وسلَّم المدينةَ، فلمَّا نزل بقُباءٍ، في بني عَمرِو بنِ عَوفٍ، أقبل رجلٌ حتى أخبَرَ بقُدومِه، وأنا في رأسِ نَخلةٍ لي أعمَلُ فيها، وعمَّتي خالِدةُ بنتُ الحارِثِ تحتي جالِسةٌ، فلما سمعتُ الخبرَ بقُدومِ رسولِ الله صلَّى اللهُ عليه وسلَّم كَبَّرتُ، فقالت لي عَمَّتي حين سَمِعَت تكبيري: خيَّبَك اللهُ! واللهِ لو كُنتَ سَمِعتَ بموسى بنِ عِمرانَ قادِمًا ما زِدتَ! قال: فقلتُ لها: أيْ عمَّةُ، هو واللهِ أخو موسى بنِ عِمرانَ، وعلى دينِه، بُعِث بما بُعِث به. قال: فقالت: أيِ ابنَ أخي، أهوَ النبيُّ الذي كُنَّا نُخبَرُ أنه يُبعَثُ مع نَفَسِ السَّاعةِ؟ قال: فقلتُ لها: نعم. قال: فقالت: فذاك إذن. قال: ثم خرجتُ إلى رسولِ الله صلَّى اللهُ عليه وسلَّم، فأسلَمتُ، ثم رَجَعتُ إلى أهلِ بيتي، فأمرتُهم فأسلموا. قال: وكَتمتُ إسلامي من يهودَ، ثم جِئتُ رسولَ الله صلَّى اللهُ عليه وسلَّم، فقلتُ له: يا رسولَ الله، إنَّ يهودَ قومٌ بُهتٌ، وإنِّي أُحِبُّ أن تُدخِلَني في بعضِ بُيوتِك، وتُغيِّبَني عنهم، ثم تَسألَهم عني، حتى يُخبِروك كيف أنا فيهم، قَبْلَ أن يعلَموا بإسلامي؛ فإنَّهم إنْ عَلِموا به بَهَتوني وعابوني. قال: فأدخَلَني رسولُ الله صلَّى اللهُ عليه وسلَّم في بعضِ بُيوتِه، ودَخَلوا عليه، فكلَّموه وساءَلوه، ثم قال لهم: \"أيُّ رجلٍ عبدُ الله بنُ سَلامٍ فيكم؟\" قالوا: سيِّدُنا وابنُ سيِّدِنا، وحَبرُنا وعالِمُنا. قال: فلمَّا فَرَغوا من قولِهم خرجتُ عليهم، فقلتُ لهم: يا مَعشرَ يهودَ، اتَّقوا اللهَ واقبَلوا ما جاءكم به، فواللهِ إنَّكم لَتعلمون إنَّه لَرسولُ الله، تَجِدونَه مَكتوبًا عِندكُم في التَّوراةِ باسمِهِ وصِفَتِه، فإنِّي أشهَدُ أنَّه رسولُ الله صلَّى اللهُ عليه وسلَّم، وأُومِن به وأُصدِّقُه وأعرِفُه. فقالوا: كَذَبْتَ. ثم وَقَعوا بي، قال: فقلتُ لرسولِ الله صلَّى اللهُ عليه وسلَّم: ألَمْ أُخبِرْك يا رسولَ الله أنهم قومٌ بُهتٌ، أهلُ غدرٍ وكذبٍ وفُجورٍ! قال: فأظهَرتُ إسلامي وإسلامَ أهلِ بيتي، وأسلَمَت عمَّتِي خالِدةُ بنتُ الحارِثِ، فحَسُن إسلامُها."},{"id":38,"title":"معاهدة النبي صلَّى اللهُ عليه وسلَّم مع يهود .","date":["العام الهجري :1","العام الميلادي :622"],"text":"قال ابن إسحاق: «كتب رسول الله- صلى الله عليه وسلم- كتابًا بين المهاجرين والأنصار وادع فيه يهود وعاهدهم وأقرّهم على دينهم وأموالهم واشترط عليهم وشرط لهم» . أي لمّا امتنعوا من إتباعه، وذلك قبل الإذن بالقتال وأخذ الجزية ممن أبى الإسلام، وقد أبى عامَّتُهم إلا الكفر. وكانوا ثلاث قبائل: بنو قينقاع، وبنو النضير، وبنو قريظة، وحاربه الثلاثة، فمنَّ على بني قينقاع، وأجلى بني النضير، وقتل بني قريظة، وسبى ذريتهم، ونزلت (سورة الحشر) في بني النضير، و (سورة الأحزاب) في بني قريظة."},{"id":39,"title":"مَشروعِيَّةُ الأَذانِ .","date":["العام الهجري :1","العام الميلادي :622"],"text":"عنِ ابنِ عُمَرَ قال: كان المسلمون حين قَدِموا المدينةَ يجتَمِعون فيتَحيَّنون الصَّلواتِ، وليس يُنادي بها أحدٌ، فتَكلَّموا يومًا في ذلك فقال بعضُهم: اتَّخِذوا ناقوسًا مِثلَ ناقوسِ النَّصارى، وقال بعضُهم: قَرْنًا مِثْلَ قَرْنِ اليَهودِ. وقال عبدُ الله بنُ زيدٍ: (لمَّا أَمَر رسولُ الله صلى الله عليه وسلم بالنَّاقوسِ يُعملُ لِيُضرَبَ به للنَّاسِ لِجَمْعِ الصَّلاةِ طاف بي وأنا نائمٌ رجلٌ يَحمِلُ ناقوسًا في يَدِه فقلتُ: يا عبدَ الله أَتبيعَ النَّاقوسَ؟ قال: وما تصنعُ به؟ فقلتُ: نَدعو به إلى الصَّلاةِ قال: أفلا أَدُلُّك على ما هو خيرٌ مِن ذلك؟ فقلتُ له: بلى. قال: فقال: تقولُ: الله أَكبرُ، الله أَكبرُ، الله أَكبرُ، الله أَكبرُ، أَشهدُ أن لا إلَه إلَّا الله، أَشهدُ أن لا إلَه إلَّا الله، أَشهدُ أنَّ محمَّدًا رسولُ الله، أَشهدُ أنَّ محمَّدًا رسولُ الله، حَيَّ على الصَّلاةِ، حَيَّ على الصَّلاةِ، حَيَّ على الفَلاحِ، حَيَّ على الفَلاحِ، الله أَكبرُ، الله أَكبرُ، لا إلَه إلَّا الله. قال: ثمَّ اسْتأخَر عَنِّي غيرَ بَعيدٍ، ثمَّ قال: وتقولُ إذا أَقمتَ الصَّلاةَ: الله أَكبرُ، الله أَكبرُ، أَشهدُ أن لا إلَه إلَّا الله، أَشهدُ أنَّ محمَّدًا رسولُ الله، حَيَّ على الصَّلاةِ، حَيَّ على الفَلاحِ، قد قامتِ الصَّلاةُ، قد قامتِ الصَّلاةُ، الله أَكبرُ، الله أَكبرُ، لا إلَه إلَّا الله. فلمَّا أَصبحتُ أَتيتُ رسولَ الله صلى الله عليه وسلم فأخبرتُه بما رأيتُ، فقال إنَّها لَرُؤْيا حَقٌّ إن شاء الله، فقُمْ مع بلالٍ فَأَلْقِ عليه ما رَأيتَ فَلْيُؤَذِّنْ به؛ فإنَّه أَندى صوتًا منك. فقمتُ مع بلالٍ فجعلتُ أُلْقِيهِ عليه ويُؤذِّنُ به، قال فسمِع ذلك عُمَرُ بنُ الخطَّابِ وهو في بيتِه، فخرج يَجُرُّ رِداءَهُ ويقولُ: والذي بعثَك بالحقِّ يا رسولَ الله، لقد رأيتُ مِثلَ ما رَأى. فقال رسولُ الله صلى الله عليه وسلم: فللهِ الحمدُ)."},{"id":40,"title":"هِجرةُ الصَّحابةِ إلى المدينةِ .","date":["العام الهجري :1","الشهر القمري : محرم","العام الميلادي :622"],"text":"لمَّا تَمَّتْ بَيعةُ العَقبةِ أمرَ رسولُ الله صلى الله عليه وسلم مَن كان معه بالهِجرةِ إلى المدينةِ، فخرجوا أَرسالًا، كان مِنَ السَّابقين للهِجرةِ بعدَ العَقبةِ الثَّانيةِ مُصعبُ بنُ عُميرٍ, ثمَّ عامرُ بنُ رَبيعةَ حَليفُ بن بني عَدِيِّ بنِ كعبٍ، معه امرأتُه ليلى بنتُ أبي حَثْمَةَ بنِ غانمٍ، ثمَّ عبدُ الله بنُ جَحْشٍ بأهلِهِ وأخيهِ عبدِ بنِ جَحْشٍ أبي أحمدَ، وكان ضَريرًا، وكان منزلُهما ومنزلُ أبي سَلمةَ بقُباءٍ في بني عَمرِو بنِ عَوفٍ، فلمَّا هاجر جميعُ بني جَحْشٍ بنِسائهِم فعَدا أبو سُفيانَ على دارِهم فتَمَلَّكَها، فذكر ذلك عبدُ الله بنُ جَحْشٍ لمَّا بَلَغَهُ لِرسولِ الله صلى الله عليه وسلم، فقال له رسولُ الله صلى الله عليه وسلم: \"ألا تَرضى يا عبدَ الله أن يُعطِيَك الله بها دارًا في الجنَّةِ خيرًا منها؟ قال: بلى. قال: فذلك لك\". فلمَّا افتتح رسولُ الله صلى الله عليه وسلم مكَّةَ كَلَّمَهُ أبو أَحمدَ في دارِهم، فأبطأَ عليه رسولُ الله صلى الله عليه وسلم فقال النَّاسُ لأبي أَحمدَ: يا أبا أَحمدَ، إنَّ رسولَ الله صلى الله عليه وسلم يَكرهُ أن تَرجِعوا في شيءٍ أُصيبَ منكم في الله، فأَمْسَكَ عن كلامِ رسولِ الله صلى الله عليه وسلم. وكان بنو غَنْمِ بنِ دُودانِ أهلَ إسلامٍ قد خرجوا كُلُّهم إلى المدينةِ، ثمَّ خرج عُمَرُ بنُ الخطَّابِ، وعيَّاشُ بنُ أبي رَبيعةَ في عِشرين راكبًا فقَدِموا المدينةَ، وكان هشامُ بنُ العاصِ بنِ وائلٍ قد أَسلمَ، وواعد عُمَرَ بنَ الخطَّابِ أن يُهاجِرَ معه، وقال: تَجِدُني أو أَجِدُك عند أَضاءةِ بني غِفارٍ، ففَطِنَ لهشامٍ قومُه فحبسوه عن الهِجرةِ. ثمَّ إنَّ أبا جهلٍ والحرثَ بنَ هشامٍ خرجا حتَّى قَدِما المدينةَ ورسولُ الله صلَّى الله عليه وسلَّم بمكَّةَ، فكَلَّما عيَّاشَ بنَ أبي رَبيعةَ وكان أخاهُما لِأُمِّهِما وابنَ عَمِّهِما، وأَخبراهُ أنَّ أمَّهُ قد نَذرتْ أن لا تَغسِلَ رأسَها ولا تَسْتَظِلَّ حتَّى تَراهُ، فَرَقَّتْ نَفْسُهُ وصدَّقهُما وخرج راجعًا معهُما، فكَتَّفاهُ في الطَّريقِ وبلغا به مكَّةَ، نهارًا مُوثَقًا، ثمَّ قالا: يا أهلَ مكَّةَ هكذا فافعلوا بسُفهائِكُم كما فعلنا بسَفيهِنا هذا. فحَبَساهُ بها إلى أن خَلَّصَهُ الله تعالى بعد ذلك بدُعاءِ رسولِ الله صلى الله عليه وسلم له في قُنوتِ الصَّلاةِ: \"اللَّهمَّ أَنْجِ الوليدَ بنَ الوليدِ، وسَلمةَ بنَ هشامٍ، وعيَّاشَ بنَ أبي رَبيعةَ\". ولمَّا أراد صُهيبُ بنُ سِنانٍ الهِجرةَ قال له كُفَّارُ قُريشٍ: أَتَيْتَنا صُعلوكًا حَقيرًا فكَثُرَ مالُك عندنا، وبلغتَ الذي بلغتَ، ثمَّ تُريدُ أن تَخرُجَ بمالِك ونَفسِك، لا والله لا يكونُ ذلك. فقال لهم صُهيبٌ: أَرأيتُم إن جَعلتُ لكم مالي أَتُخَلُّون سَبيلي؟ قالوا: نعم، فقال: فإنِّي قد جَعلتُ لكم، فبلغ ذلك رسولُ الله صلى الله عليه وسلم فقال: \"رَبِحَ صُهيبٌ، رَبِحَ صُهيبٌ\". ثمَّ تتابع المهاجرون بالهِجرةِ إلى المدينةِ إلى أن هاجر رسولُ الله صلى الله عليه وسلم."},{"id":41,"title":"اجتماعُ المُشركين في دارِ النَّدوَةِ واتِّفاقُهم على قَتلِ النَّبيِّ صلَّى الله عليه وسلَّم .","date":["العام الهجري :1","الشهر القمري : صفر","العام الميلادي :622"],"text":"لمَّا رَأى المُشركون أنَّ أصحابَ رسولِ الله صلى الله عليه وسلم قد تَجهَّزوا وخرجوا، وحملوا وساقوا الذَّراريَّ والأطفالَ والأموالَ إلى الأوسِ والخزرجِ في يَثْرِبَ، أصابتهُم الكآبةُ والحزنُ، وساوَرهُم القلقُ والهَمُّ، فاجتمع طواغيتُ مكَّةَ في دارِ النَّدوَةِ لِيتَّخِذوا قرارًا حاسمًا في هذا الأمرِ. وكان اجتماعُهُم بعدَ شَهرينِ ونصفِ تقريبًا مِن بَيعةِ العَقبةِ، وتوافد إلى هذا الاجتماعِ جميعُ نُوَّابِ القبائلِ القُرشيَّةِ؛ لِيتَدارسوا خُطَّةً حاسِمةً, تَكفُلُ القضاءَ سريعًا على النَّبيِّ صلى الله عليه وسلم ودَعوتِهِ, ولمَّا جاءوا إلى دارِ النَّدوةِ حَسْبَ الميعادِ، اعترضهُم إبليسُ في هَيئةِ شيخٍ جليلٍ، ووقف على البابِ، فقالوا: مَن الشَّيخُ؟ قال: شيخٌ مِن أهلِ نجدٍ, سمِع بالذي اتَّعَدْتُم له فحضر معكم لِيسمعَ ما تقولون، وعسى ألَّا يُعْدِمَكُم منه رأيًا ونُصْحاً. قالوا: أجلْ، فادْخُلْ. فدخل معهم. وبعد أن تَكامل الاجتماعُ, ودار النِّقاشُ طويلًا. قال أبو الأَسودِ: نُخرِجُهُ مِن بين أَظْهُرِنا ونَنْفيهِ مِن بلادِنا، ولا نُبالي أين ذهب، ولا حيث وقع، فقد أَصلَحنا أَمْرَنا, وأُلْفَتَنا كما كانت. قال الشيخُ النَّجديُّ: لا والله ما هذا لكم برأيٍ، ألم تَرَوْا حُسْنَ حَديثهِ، وحَلاوةَ مَنْطِقِهِ، وغَلَبَتْهُ على قلوبِ الرِّجالِ بما يأتي به، والله لو فعلتُم ذلك ما أَمِنْتُم أن يَحِلَّ على حَيٍّ مِن العربِ، ثمَّ يَسيرُ بهِم إليكم - بعد أن يَتَّبِعوهُ - حتَّى يَطأَكُم بهِم في بلادِكُم، ثمَّ يفعلُ بكم ما أراد، دَبِّروا فيه رأيًا غيرَ هذا. قال أبو البَخْتريِّ: احْبِسوه في الحديدِ وأَغلِقوا عليه بابًا، ثمَّ تَربَّصوا به ما أصاب أمثالَهُ مِن الشُّعراءِ الذين كانوا قبله - زُهيرًا والنَّابِغةَ - ومَن مضى منهم، مِن هذا الموتِ، حتَّى يُصيبَهُ ما أصابهم. قال الشَّيخُ النَّجديُّ: لا والله ما هذا لكم برأيٍ، والله لَئِن حَبَستُموه -كما تقولون- لَيَخرُجنَّ أَمرُهُ مِن وراءِ البابِ الذي أغلقتُم دونَه إلى أصحابهِ، فلأَوْشَكوا أن يَثِبوا عليكم، فيَنزِعوه مِن أَيديكُم، ثمَّ يُكاثِروكُم به حتَّى يَغلِبوكُم على أَمرِكُم، ما هذا لكم برأيٍ، فانظروا في غيرِهِ. بعد ذلك تَقدَّم كبيرُ مُجرِمي مكَّةَ أبو جهلِ بنِ هشامٍ بِاقتِراحٍ آثمٍ وافق عليه جميعُ مَن حضر, قال أبو جهلٍ: والله إنَّ لي فيه رأيًا ما أَراكُم وقعتُم عليه بعدُ. قالوا: وما هو يا أبا الحكمِ؟ قال: أَرى أن نَأخُذَ مِن كُلِّ قَبيلةٍ فَتًى شابًّا جَليدًا نَسِيبًا وَسِيطًا فِينا، ثمَّ نُعطي كُلَّ فَتًى منهم سَيفًا صارمًا، ثمَّ يَعمِدوا إليه، فيَضرِبوه بها ضربةَ رجلٍ واحدٍ فيَقتُلوه، فنَستَريحَ منه، فإنَّهم إذا فعلوا ذلك تَفرَّق دَمُهُ في القبائلِ جميعًا، فلمْ يَقدِرْ بنو عبدِ منافٍ على حربِ قومِهم جميعًا، فَرَضوا مِنَّا بالعَقْلِ، فَعَقَلْناهُ لهم. قال الشَّيخُ النَّجديُّ: القولُ ما قال الرَّجلُ، هذا الرَّأيُ الذي لا رأيَ غيرُهُ. ووافقوا على هذا الاقتراحِ الآثمِ بالإجماعِ."},{"id":42,"title":"هِجرةُ الرَّسولِ صلَّى الله عليه وسلَّم وأبي بكرٍ رضِي الله عنه إلى المدينةِ .","date":["العام الهجري :1","الشهر القمري : صفر","العام الميلادي :622"],"text":"عن عائشةَ رضي الله عنها قالت: قال النَّبيُّ صلى الله عليه وسلم للمُسلمين: «إنِّي أُريتُ دارَ هِجرتِكُم ذاتَ نَخلٍ بين لابَتَيْنِ». وهُما الحَرَّتانِ، فهاجر مَن هاجر قِبَلَ المدينةِ، ورجع عامَّةُ مَن كان هاجر بأرضِ الحَبشةِ إلى المدينةِ، وتَجهَّز أبو بكرٍ قِبَلَ المدينةِ، فقال له رسولُ الله صلى الله عليه وسلم: «على رِسْلِكَ، فإنِّي أرجو أن يُؤذنَ لي». فقال أبو بكرٍ: وهل ترجو ذلك بأبي أنت؟ قال: «نعم». فحبَس أبو بكرٍ نَفْسَهُ على رسولِ الله صلى الله عليه وسلم لِيصحبَهُ، وعلَف راحِلتينِ كانتا عنده وَرَقَ السَّمُرِ -وهو الخَبَطُ- أربعةَ أَشهُرٍ. قال ابنُ شهابٍ: قال عُروةُ: قالت عائشةُ: فبينما نحن يومًا جُلوسٌ في بيتِ أبي بكرٍ في نَحْرِ الظَّهيرةِ، قال قائلٌ لأبي بكرٍ: هذا رسولُ الله صلى الله عليه وسلم مُتقنِّعًا، في ساعةٍ لم يكن يأتينا فيها، فقال أبو بكرٍ: فِداءٌ له أبي وأمِّي، والله ما جاء به في هذه السَّاعةِ إلَّا أَمْرٌ، قالت: فجاء رسولُ الله صلَّى الله عليه وسلَّم فاسْتأذَن، فأُذِنَ له فدخل، فقال النَّبيُّ صلى الله عليه وسلم لأبي بكرٍ: «أَخْرِجْ مَن عندك». فقال أبو بكرٍ: إنَّما هُم أَهلُك، بأبي أنت يا رسولَ الله. قال: «فإنِّي قد أُذِنَ لي في الخُروجِ». فقال أبو بكرٍ: الصُّحبة بأبي أنت يا رسولَ الله؟ قال رسولُ الله صلى الله عليه وسلم: «نعم». قال أبو بكرٍ: فَخُذْ -بأبي أنت يا رسولَ الله- إحدى راحِلَتي هاتينِ، قال رسولُ الله صلى الله عليه وسلم: «بالثَّمنِ». قالت عائشةُ: فجَهَّزناهُما أَحَثَّ الجِهازِ، وصنعنا لهُما سُفْرَةً في جِرابٍ، فقطعتْ أسماءُ بنتُ أبي بكرٍ قِطعةً مِن نِطاقِها فربطتْ به على فَمِ الجِرابِ، فبذلك سُمِّيت: ذاتَ النِّطاقينِ. قالت: ثمَّ لَحِقَ رسولُ الله صلى الله عليه وسلم وأبو بكرٍ بِغارٍ في جبلِ ثَوْرٍ، فَكَمَنَا فيه ثلاثَ ليالٍ، يَبيتُ عندهما عبدُ الله بنُ أبي بكرٍ، وهو غلامُ شابٌّ، ثَقِفٌ لَقِنٌ، فَيُدْلِجُ مِن عندهِما بِسَحَرٍ، فيُصبحُ مع قُريشٍ بمكَّةَ كَبائِتٍ، فلا يسمعُ أمرًا، يُكتادانِ به إلَّا وعاهُ، حتَّى يأتيَهُما بخبرِ ذلك حين يَختلِطُ الظَّلامُ، ويَرعى عليهِما عامرُ بنُ فُهيرةَ، مولى أبي بكرٍ مِنْحَةً مِن غَنَمٍ، فيُريحُها عليهِما حين تَذهبُ ساعةٌ مِنَ العِشاءِ، فيَبيتانِ في رِسْلٍ، وهو لبنُ مِنْحَتِهِما ورَضِيفِهِما، حتَّى يَنْعِقَ بها عامرُ بنُ فُهيرةَ بِغَلَسٍ، يفعلُ ذلك في كُلِّ ليلةٍ مِن تلك اللَّيالي الثَّلاثِ، واسْتأجر رسولُ الله صلى الله عليه وسلم وأبو بكرٍ رجلًا مِن بني الدِّيلِ، وهو مِن بني عبدِ بنِ عَدِيٍّ، هادِيًا خِرِّيتًا -والخِرِّيتُ الماهرُ بالهِدايةِ- قد غَمَسَ حِلْفًا في آلِ العاصِ بنِ وائلٍ السَّهميِّ، وهو على دينِ كُفَّارِ قُريشٍ، فأَمِناهُ فدَفعا إليه راحِلَتَيْهِما، وواعَداهُ غارَ ثَوْرٍ بعدَ ثلاثِ ليالٍ، بِراحِلَتيهِما صُبْحَ ثلاثٍ، وانطلق معهما عامرُ بنُ فُهيرةَ والدَّليلُ، فأخذ بهم طريقَ السَّواحلِ. قال: سُراقةُ بنُ جُعْشُمٍ: جاءنا رُسُلُ كُفَّارِ قُريشٍ، يجعلون في رسولِ الله صلى الله عليه وسلم وأبي بكرٍ، دِيَةَ كُلِّ واحدٍ منهما، مَن قَتلهُ أو أَسَرهُ، فبينما أنا جالسٌ في مجلسٍ مِن مجالسِ قَومي بني مُدْلِجٍ، أقبل رجلٌ منهم حتَّى قام علينا ونحن جُلوسٌ، فقال يا سُراقةُ: إنِّي قد رأيتُ آنفًا أَسْوِدَةً بالسَّاحلِ، أُراها محمَّدًا وأصحابَه، قال سُراقةُ: فعرَفتُ أنَّهم هُم، فقلتُ له: إنَّهم لَيسوا بهِم، ولكنَّك رأيتَ فُلانًا وفُلانًا، انطلَقوا بِأَعْيُنِنا، ثمَّ لَبِثْتُ في المجلسِ ساعةً، ثمَّ قمتُ فدخلتُ فأمرتُ جاريتي أن تَخرُجَ بفَرسي، وهي مِن وراءِ أَكَمَةٍ، فتَحبِسَها عليَّ، وأخذتُ رُمحي، فخرجتُ به مِن ظَهرِ البيتِ، فَحَطَطْتُ بِزُجِّهِ الأرضَ، وخَفضتُ عالِيَهُ، حتَّى أتيتُ فَرسي فركِبتُها، فرفَعتُها تُقَرِّبُ بي، حتَّى دَنوتُ منهم، فعَثَرَتْ بي فَرسي، فخَررتُ عنها، فقمتُ فأَهويتُ يدي إلى كِنانتي، فاسْتخرجتُ منها الأَزلامَ فاسْتقسَمتُ بها: أَضرُّهُم أم لا، فخرج الذي أَكرهُ، فركِبتُ فَرسي، وعصيتُ الأَزلامَ، تُقَرِّبُ بي حتَّى إذا سمعتُ قِراءةَ رسولِ الله صلى الله عليه وسلم، وهو لا يَلتفتُ، وأبو بكرٍ يُكثِرُ الالتِفاتَ، ساختْ يَدا فَرسي في الأرضِ، حتَّى بَلغتا الرُّكبَتينِ، فخررتُ عنها، ثمَّ زجرتُها فنهَضتْ، فلم تكدْ تُخرِجُ يدَيها، فلمَّا استوت قائمةً إذا لِأثَرِ يدَيها عُثانٌ ساطعٌ في السَّماءِ مِثلُ الدُّخانِ، فاسْتقسَمتُ بالأَزلامِ، فخرج الذي أَكرهُ، فنادَيتُهم بالأَمانِ فوقفوا، فركِبتُ فَرسي حتَّى جِئتُهم، ووقع في نفسي حين لَقِيتُ ما لَقِيتُ مِنَ الحَبسِ عنهم أن سَيظهرُ أَمْرُ رسولِ الله صلى الله عليه وسلم، فقلتُ له: إنَّ قومَك قد جعلوا فيك الدِّيةَ، وأخبرتُهم أخبارَ ما يُريدُ النَّاسُ بهِم، وعرضتُ عليهم الزَّادَ والمتاعَ، فلم يَرْزآني ولم يَسألاني، إلَّا أن قال: «أَخْفِ عَنَّا». فسألتُه أن يَكتُبَ لي كتابَ أَمْنٍ، فأمر عامرَ بنَ فُهيرةَ فكتب في رُقعةٍ مِن أَديمٍ، ثمَّ مَضى رسولُ الله صلى الله عليه وسلم. وعن عُروةَ بنِ الزُّبيرِ: أنَّ رسولَ الله صلى الله عليه وسلم لَقِيَ الزُّبيرَ في رَكْبٍ مِنَ المسلمين، كانوا تُجَّارًا قافِلين مِن الشَّأْمِ، فكَسا الزُّبيرُ رسولَ الله صلى الله عليه وسلم وأبا بكرٍ ثِيابَ بَياضٍ، وسمِع المسلمون بالمدينةِ مَخرجَ رسولِ الله صلى الله عليه وسلم مِن مكَّةَ، فكانوا يَغدون كُلَّ غَداةٍ إلى الحَرَّةِ، فيَنتظِرونَهُ حتَّى يَرُدَّهُم حَرُّ الظَّهيرةِ، فانقلبوا يومًا بعد ما أطالوا انتظارَهُم، فلمَّا أَوَوْا إلى بُيوتِهم، أَوفى رجلٌ مِن يَهودَ على أُطُمٍ مِن آطامِهِم، لِأَمْرٍ يَنظرُ إليه، فبصر برسولِ الله صلى الله عليه وسلم وأصحابِه مُبَيَّضِين يَزولُ بهِم السَّرابُ، فلم يملِك اليَهوديُّ أن قال بأعلى صوتِه: يا مَعاشِرَ العربِ، هذا جَدُّكُم الذي تَنتظِرون، فثار المسلمون إلى السِّلاحِ، فتَلَقَّوْا رسولَ الله صلى الله عليه وسلم بظَهْرِ الحَرَّةِ، فعَدل بهِم ذاتَ اليمينِ، حتَّى نزل بهِم في بني عَمرِو بنِ عَوفٍ، وذلك يومَ الاثنينِ مِن شهرِ ربيعٍ الأوَّلِ، فقام أبو بكرٍ للنَّاسِ، وجلس رسولُ الله صلى الله عليه وسلم صامتًا، فطَفِقَ مَن جاء مِنَ الأنصارِ -ممَّن لم يَرَ رسولَ الله صلى الله عليه وسلم- يُحَيِّي أبا بكرٍ، حتَّى أصابتِ الشَّمسُ رسولَ الله صلى الله عليه وسلم، فأقبل أبو بكرٍ حتَّى ظَلَّلَ عليه بِردائِه، فعرَف النَّاسُ رسولَ الله صلى الله عليه وسلم عند ذلك."},{"id":43,"title":"بِناءُ مَسجدِ قُباءٍ .","date":["العام الهجري :1","الشهر القمري : ربيع الأول","العام الميلادي :622"],"text":"لَبِثَ رسولُ الله صلى الله عليه وسلم في بني عَمرِو بنِ عَوفٍ بِقُباءٍ بِضعَ عشرةَ ليلةً، وأسَّسَ فيها المسجدَ الذي أُسِّسَ على التَّقوىَ، وصلَّى فيه رسولُ الله صلى الله عليه وسلم."},{"id":44,"title":"بِناءُ المسجدِ النَّبوِيِّ .","date":["العام الهجري :1","الشهر القمري : ربيع الأول","العام الميلادي :622"],"text":"ركِب رسولُ الله صلى الله عليه وسلم راحِلتَه مِن قُباءٍ فسار يمشي معه النَّاسُ حتَّى برَكتْ عند مسجدِ الرَّسولِ صلى الله عليه وسلم بالمدينةِ، وهو يُصلِّي فيه يَومئذٍ رجالٌ مِنَ المسلمين، وكان مِرْبَدًا للتَّمرِ، لِسُهيلٍ وسَهلٍ غُلامَينِ يَتيمَينِ في حَجْرِ أَسعدَ بنِ زُرارةَ، فقال رسولُ الله صلى الله عليه وسلم حين بَركتْ به راحِلتُه: «هذا إن شاء الله المنزِلُ». ثمَّ دَعا رسولُ الله صلى الله عليه وسلم الغُلامَينِ فَساوَمَهُما بالمِرْبَدِ، لِيَتَّخِذَهُ مسجدًا، فقالا: لا، بل نَهَبُهُ لك يا رسولَ الله، فأبى رسولُ الله أن يَقبلَهُ منهُما هِبَةً حتَّى ابتاعَهُ منهُما، ثمَّ بناهُ مسجدًا، وطَفِقَ رسولُ الله صلى الله عليه وسلم يَنقُلُ معهم اللَّبِنَ في بُنيانِهِ ويقولُ، وهو يَنقُلُ اللَّبِنَ: \"هذا الحِمالُ لا حِمالَ خَيبرْ، هذا أَبَرُّ رَبَّنا وأَطهرْ. ويقول: اللَّهمَّ إنَّ الأجرَ أجرُ الآخِرهْ، فارْحَمِ الأنصارَ، والمُهاجِرهْ\" وعن أنسٍ رضي الله عنه قَالَ: قَدِمَ النَّبيُّ صلى الله عليه وسلم المدينةَ فنزل أعلى المدينةِ في حَيٍّ يُقالُ لهم: بنو عَمرِو بنِ عَوفٍ. فأقام النَّبيُّ صلى الله عليه وسلم فيهِم أربعَ عشرةَ ليلةً، ثمَّ أرسل إلى بني النَّجَّارِ، فجاءوا مُتَقَلِّدي السُّيوفِ كأنِّي أنظرُ إلى النَّبيِّ صلى الله عليه وسلم على راحِلتِهِ، وأبو بكرٍ رِدْفُهُ ومَلَأُ بني النَّجَّارِ حولَه حتَّى أَلقى بفِناءِ أبي أيُّوبَ، وكان يُحِبُّ أن يُصلِّيَ حيث أدركتهُ الصَّلاةُ، ويُصلِّي في مَرابضِ الغَنَمِ، وأنَّه أَمَرَ ببِناءِ المسجدِ، فأرسل إلى مَلإٍ مِن بني النَّجَّارِ فقال: «يا بَني النَّجَّارِ ثامِنوني بحائِطِكُم هذا». قالوا: لا والله لا نطلبُ ثَمَنَهُ إلَّا إلى الله. فقال أنسٌ: فكان فيه ما أقولُ لكم: قُبورُ المشركين، وفيه خَرِبٌ وفيه نَخلٌ، فأَمَر النَّبيُّ صلى الله عليه وسلم بقُبورِ المشركين فنُبِشَتْ، ثمَّ بالخَرِبِ فسُوِّيَتْ، وبالنَّخلِ فقُطِعَ، فصَفُّوا النَّخلَ قِبلةَ المسجدِ، وجعلوا عِضادَتَيْهِ الحِجارةَ، وجعلوا يَنقُلون الصَّخرَ وهُم يَرتَجِزون والنَّبيُّ صلى الله عليه وسلم معهم، وهو يقول: «اللَّهمَّ لا خيرَ إلَّا خيرُ الآخرهْ، فاغْفِرْ للأنصارِ والمُهاجِرهْ».  قال عبدُ الله بنُ عُمَرَ، \" إنَّ المسجدَ كان على عهدِ رسولِ الله صلى الله عليه وسلم مَبْنِيًّا باللَّبِنِ، وسَقْفُهُ الجَريدُ، وعُمُدُهُ خَشبُ النَّخلِ."},{"id":45,"title":"المُؤاخاةُ بين المُهاجِرين والأنصارِ .","date":["العام الهجري :1","الشهر القمري : ربيع الأول","العام الميلادي :622"],"text":"كان مِن آثارِ هِجرتِه صلى الله عليه وسلم وأصحابِه إلى المدينةِ تلك المُؤاخاةُ التي حَدثت بين المُهاجرين والأنصارِ رضي الله عنهم، حتَّى كان يَرِثُ بعضُهم بعضًا في أوَّلِ الأمرِ. فعنِ ابنِ عبَّاسٍ رضِي الله عنهما: {وَلِكُلٍّ جَعَلْنَا مَوَالِيَ} قال: «وَرَثَةً»: {وَالَّذِينَ عَاقَدَتْ أَيْمَانُكُمْ} قال: \" كان المُهاجِرون لمَّا  قَدِموا المدينةَ يَرِثُ المُهاجِرُ الأنصاريَّ دون ذَوِي رَحِمِهِ؛ لِلأُخُوَّةِ التي آخى النَّبيُّ صلى الله عليه وسلم بينهم، فلمَّا نزلت: {{وَلِكُلٍّ جَعَلْنَا مَوَالِيَ} نسَختْ\". ثمَّ قال: {وَالَّذِينَ عَاقَدَتْ أَيْمَانُكُمْ} «إلَّا النَّصرَ، والرِّفادَةَ، والنَّصيحةَ، وقد ذهب الميراثُ، ويوصي له».وعن أنسٍ قال: لمَّا قَدِمَ النَّبيُّ صلى الله عليه وسلم المدينةَ أتاهُ المُهاجرون فقالوا: يا رسولَ الله، ما رَأينا قومًا أَبْذَلَ مِن كثيرٍ، ولا أحسنَ مُواساةً مِن قليلٍ مِن قومٍ نزلنا بين أَظهُرهِم، لقد كَفَوْنا المُؤنَةَ وأشرَكونا في المَهْنَإِ حتَّى لقد خُفْنا أن يَذهبوا بالأجرِ كُلِّهِ. فقال النَّبيُّ صلى الله عليه وسلم: «لا ما دَعَوتُم الله لهم، وأَثْنَيْتُم عليهِم».وقال عبدُ الرَّحمنِ بنُ عَوفٍ رضي الله عنه: لمَّا قَدِمْنا المدينةَ آخى رسولُ الله صلى الله عليه وسلم بيني وبين سعدِ بنِ الرَّبيعِ، فقال سعدُ بنُ الرَّبيعِ: إنِّي أَكثرُ الأنصارِ مالًا، فَأَقْسِمُ لك نِصفَ مالي، وانْظُرْ أيَّ  زَوجتيَّ هَوِيتَ نَزلتُ لك عنها، فإذا حَلَّتْ تَزوَّجتَها. قال: فقال له عبدُ الرَّحمنِ: لا حاجةَ لي في ذلك، هل مِن سوقٍ فيه تِجارةٌ؟ قال: سوقُ قَيْنُقاعٍ. قال: فغَدا إليه عبدُ الرَّحمنِ، فأتى بأَقِطٍ وسَمْنٍ، قال: ثمَّ تابع الغُدُوَّ، فما لَبِثَ أن جاء عبدُ الرَّحمنِ عليه أثرُ صُفْرَةٍ، فقال رسولُ الله صلى الله عليه وسلم: «تَزوَّجتَ؟». قال: نعم. قال: «ومَن؟»، قال: امرأةً مِنَ الأنصارِ. قال: «كَم سُقْتَ؟»، قال: زِنَةَ نَواةٍ مِن ذَهبٍ -أو نَواةً مِن ذَهبٍ- فقال له النَّبيُّ صلى الله عليه وسلم: «أَوْلِمْ ولو بِشاةٍ»."},{"id":46,"title":"سرية عبيدة بن الحارث بن المطلب إلى بطن رابغ .","date":["العام الهجري :1","الشهر القمري : شعبان","العام الميلادي :623"],"text":"بَعَث النبيُّ صلَّى اللهُ عليه وسلَّم عُبيدةَ بنَ الحارِثِ بن عبد المطلب في سريَّةٍ إلي بطنِ رابِغٍ -هيَ ميقاتُ أهلِ الشامِ ومِصرَ وتركيا ومَن سَلَك طَريقَهم- في شعبان على رأسِ ثمانيةِ أشهُرٍ من الهجرةِ، وعَقَد له لواءً أبيضَ، وحَمَله مِسْطَحُ بن أُثاثةَ بن المطلبِ بن عبد مَنافٍ، وكانوا في ستِّين من المُهاجِرين ليس فيهم أنصاريٌّ، فلَقيَ أبا سُفيانَ بنَ حربٍ، وهو في مائتينِ على بطنِ رابِغٍ، على عشرةِ أميالٍ من الجُحفةِ، وكان بينهم الرَّميُ، ولم يَسُلُّوا السُّيوفَ، ولم يَصطَفُّوا للقتالِ، وإنَّما كانت مُناوشةً، وكان سعدُ بن أبي وقَّاصٍ فيهم، وهو أوَّلُ مَن رَمَى بسهمٍ في سبيل الله، ثم انصَرَف الفريقانِ إلى حاميَتِهم."},{"id":47,"title":"سرية حمزة إلى سيف البحر .","date":["العام الهجري :1","الشهر القمري : رمضان","العام الميلادي :623"],"text":"أرسل النبيُّ صلَّى اللهُ عليه وسلَّم سَريَّةً إلى سِيفِ -ساحِلِ- البحرِ، أمَّر عليها حمزةَ بنَ عبد المطلب، وبعثه في ثلاثين راكبًا مِن المُهاجِرين، وكان لِواءُ حَمزةَ أولَ لواءٍ عَقَده رسولُ الله صلَّى اللهُ عليه وسلَّم، وكان أبيضَ، وكان حامِلُه أبا مِرثَدٍ كَنَّازَ بنَ حُصينٍ الغَنويَّ رَضي اللهُ عنه، وكان هدفُ هذه السَّريَّةِ اعتِراضَ عِيرٍ لقُريشٍ جاءتْ من الشامِ، وفيها أبو جهلِ بنُ هشامٍ في ثلاثِ مئةِ رجلٍ، فبَلَغوا سِيفَ البحرِ من ناحيةِ العيصِ -اسمُ موضِعٍ قُربَ المدينةِ على ساحِلِ البحرِ- فالْتَقَوا واصطَفُّوا للقتالِ، فمَشَى مَجْديُّ بن عَمرٍو الجُهنيُّ -وكان حليفًا للفَريقَينِ جميعًا- بين هؤلاءِ وهؤلاءِ، حتى حَجَز بينهم، فلم يَقتَتِلوا. وقد كانتْ سريَّةُ حمزةَ رَضي اللهُ عنه في وَقتٍ واحدٍ مع سريَّةِ عُبيدةَ بنِ الحارِثِ رَضي اللهُ عنه إلى رابِغٍ."},{"id":48,"title":"سرية سعد بن أبي وقاص رضي الله عنه إلى الخَرّار .","date":["العام الهجري :1","الشهر القمري : ذي القعدة","العام الميلادي :623"],"text":"بَعثَ رسولُ الله صلَّى اللهُ عليه وسلَّم على رأسِ تِسعةِ أشهُرٍ من الهِجرةِ سعدَ بنَ أبي وقَّاصٍ رَضي اللهُ عنه في عِشرين من المُهاجِرين. وقيل: ثَمانيةٍ إلى الخَرَّارِ. وعَقَد له لواءً أبيضَ حَمَلَه المِقدادُ بنُ عَمرٍو رَضي اللهُ عنه. والخَرَّارُ: وادٍ يُتَوَصَّلُ منه إلى الجُحفةِ، وقد عَهِدَ صلَّى اللهُ عليه وسلَّم إليه ألَّا يُجاوِزَه؛ ليَعتَرِضَ عيرًا لقُريشٍ تَمرُّ بِهِم، فخَرَجوا يَمشون على أقدامِهِم، يَكمُنون النَّهارَ ويَسيرون اللَّيلَ حتى صَبَّحوا المكانَ المَذكورَ في صُبحِ خمسٍ؛ فوَجدوا العِيرَ قد مرَّت بالأمسِ؛ فضَرَبوا راجِعين إلى المدينةِ من غيرِ حربٍ."},{"id":49,"title":"غَزوةُ الأَبْواءِ (وَدَّانَ) ومُوادَعةُ بني ضَمْرَةَ .","date":["العام الهجري :2","الشهر القمري : صفر","العام الميلادي :623"],"text":"أوَّلُ ما غَزا النَّبيُّ صلَّى الله عليه وسلَّم الأَبْواءَ ثمَّ بُواطَ ثمَّ العُشَيْرَةَ. وهي قريةٌ مِن عَمَلِ الفُرْعِ، بينها وبين الجُحْفَةِ مِن جِهَةِ المدينةِ ثلاثةٌ وعِشرون مِيلًا. قِيلَ سُمِّيتْ بذلك لِما كان فيها مِنَ الوَباءِ، وهي غَزوةُ وَدَّانَ بِتَشديدِ الدَّالِ، قال إسحاقُ: خرج النَّبيُّ صلَّى الله عليه وسلَّم غازِيًا بِنَفْسِهِ حتَّى انتَهى إلى وَدَّانَ، وهي الأَبْواءُ. خرج مِنَ المدينةِ على رأسِ اثنيْ عشرَ شهرًا مِن مَقْدَمِهِ المدينةَ يُريدُ قُريشًا، فَوادَعَ بني ضَمْرَةَ بنِ بكرِ بنِ عبدِ مَناةَ، مِن كِنانةَ، وادَعَهُ رَئيسُهم مَجْدِيُّ بنُ عَمرٍو الضَّمْريُّ، ورجع بغيرِ قِتالٍ. وكان النَّبيُّ صلَّى الله عليه وسلَّم قد استعمل على المدينةِ سعدَ بنَ عُبادةَ. وقِيلَ: إنَّ النَّبيَّ صلَّى الله عليه وسلَّم لمَّا وصل إلى الأَبْواءِ بعَث عُبيدةَ بنَ الحارثِ في سِتِّينَ رجلًا فَلَقوا جمعًا مِن قُريشٍ فتَراموا بالنَّبْلِ، فَرَمى سعدُ بنُ أبي وقَّاصٍ بِسَهمٍ، وكان أوَّلَ مَن رَمى بِسَهمٍ في سَبيلِ الله."},{"id":50,"title":"غزوة بدر الأولى (وادي سفوان) .","date":["العام الهجري :2","الشهر القمري : ربيع الأول","العام الميلادي :623"],"text":"غزا رسولُ الله صلَّى اللهُ عليه وسلَّم غزوةَ بدرٍ الأولَى حتى بَلَغ واديَ سَفَوانَ؛ حيث خَرَج رسولُ الله صلَّى اللهُ عليه وسلَّم على رأسِ ثلاثةَ عَشَرَ شهرًا من مُهاجَرِه يَطلُب كُرزَ بنَ جابِرٍ الفِهريَّ، وحَمَل لِواءَه عليُّ بنُ أبي طالِبٍ رَضي اللهُ عنه، وكان أبيضَ، واستَخلَفَ على المدينةِ زيدَ بنَ حارِثةَ، وكان كُرزٌ قد أغار على سَرحِ المدينةِ -الإبِلِ والمَواشي التي تَسرَحُ للرَّعيِ بالغَداةِ- فاستاقَه، وكان يَرعَى بالحِمَى، فطَلَبه رسولُ الله صلَّى اللهُ عليه وسلَّم حتى بَلَغ واديًا يُقالُ له: \"سَفَوانُ\" من ناحيةِ بَدرٍ، وفاتَه كُرزٌ ولم يَلحَقْه، فرَجَع إلى المَدينةِ."},{"id":51,"title":"غَزوةُ بُواطٍ بِقُربِ يَنْبُعَ .","date":["العام الهجري :2","الشهر القمري : ربيع الآخر","العام الميلادي :623"],"text":"عن جابرٍ رضي الله عنه قال: سِرْنا مع رسولِ الله صلى الله عليه وسلم في غَزوةِ بَطْنِ بُواطٍ، وهو يَطلُبُ المَجْدِيَّ بنَ عَمرٍو الجُهَنيَّ، وكان النَّاضِحُ يَعْتَقِبُهُ مِنَّا الخمسةُ والسِّتَّةُ والسَّبعةُ، فَدارتْ عُقْبَةُ رجلٍ مِنَ الأنصارِ على ناضِحٍ له، فأناخَهُ فركِبَهُ، ثمَّ بَعثَهُ فتَلَدَّنَ عليه بَعضَ التَّلَدُّنِ، فقال له: شَأْ، لَعنَك الله. فقال رسولُ الله صلى الله عليه وسلم: «مَن هذا اللَّاعِنُ بَعيرَهُ؟». قال: أنا، يا رسولَ الله. قال: «انْزِلْ عنه، فلا تَصْحَبْنا بِمَلعونٍ، لا تَدعوا على أَنفُسِكُم، ولا تَدعوا على أَولادِكُم، ولا تَدعوا على أَموالِكُم، لا تُوافِقوا مِنَ الله ساعةً يُسأَلُ فيها عَطاءٌ، فَيسْتَجيبُ لكم». وبُواطٌ: جبلٌ مِن جبالِ جُهَينةَ، بِقُربِ يَنْبُعَ."},{"id":52,"title":"غَزوةُ العُشَيْرَةِ (الْعُسَيْرَةِ) .","date":["العام الهجري :2","الشهر القمري : جمادى الأولى","العام الميلادي :623"],"text":"قِيلَ لِزيدِ بنِ أَرقمَ: \" كم غَزا النَّبيُّ صلى الله عليه وسلم مِن غَزوةٍ؟ قال: تِسعَ عشرةَ. قِيلَ: كم غَزوتَ أنت معه؟ قال: سبعَ عشرةَ. قِيلَ: فأَيُّهم كانت أوَّلَ؟ قال: الْعُسَيْرَةُ، أَوِ الْعُشَيْرُ. وقعت غَزوةُ العُشَيْرَةِ قبلَ وَقعةِ بدرٍ، سَلَكَ النَّبيُّ صلَّى الله عليه وسلَّم على نَقْبِ بني دِينارٍ، ثمَّ على فَيْفاءِ الخَبارِ فنزل تحت شجرةٍ ببَطْحاءَ ابنِ أَزهرَ يُقالُ لها: ذاتُ السَّاقِ. فصَلَّى عندها... وصُنِعَ له عندها طعامٌ فأكل منه وأكل النَّاسُ معه... واسْتُقِيَ له مِن ماءٍ به يُقالُ له: المُشْتَرِبُ، ثمَّ ارْتَحل رسولُ الله صلى الله عليه وسلم فترك الخلائقَ بيَسارهِ وسلك شُعبةً يُقالُ لها: شُعبةُ عبدِ الله... ثمَّ صَبَّ لليَسارِ حتَّى هبَط يَلْيَلَ فنزل بِمُجتَمعِه ومُجتمعِ الضَّبُوعَةِ، واسْتَقى مِن بئرٍ بالضَّبُوعَةِ، ثمَّ سلك الفَرْشَ فَرْشَ مَلَلٍ حتَّى لَقِيَ الطَّريقَ بصحيرات بِصُخَيْراتِ اليَمامِ، ثمَّ اعتدل به الطَّريقُ حتَّى نزل العُشَيْرَةَ مِن بطنِ يَنْبُعَ فأقام بها جُمادى الأُولى ولياليَ مِن جُمادى الآخرةِ، وادَع فيها بني مُدْلِجٍ وحُلفاءَهُم مِن بني ضَمْرَةَ ثمَّ رجع إلى المدينةِ ولمْ يَلْقَ كَيْدًا."},{"id":53,"title":"سرية سعد بن أبي وقاص رضي الله عنه إلى رابغ .","date":["العام الهجري :2","الشهر القمري : رجب","العام الميلادي :624"],"text":"أخرَجَ ابنُ عَساكِرَ عن الزُّهريِّ قال: \"بَعَثَ رَسولُ الله صلَّى اللهُ عليه وسلَّم سَريَّةً فيها سعدُ بنُ أبي وقَّاصٍ رَضي اللهُ عنه إلى جانِبٍ مِن الحِجازِ يُدعَى (رابِغ)، فانكَفَأ المُشرِكون على المسلمين، فجاءَهم سعدُ بن أبي وقَّاصٍ رَضي اللهُ عنه يومَئذٍ بسِهامِهِ، وكان أوَّلَ مَن رَمَى في سبيلِ الله، وكان هذا أوَّلَ قِتالٍ في الإسلامِ\"."},{"id":54,"title":"سرية عبد الله بن جحش الأسدي إلى نخلة .","date":["العام الهجري :2","الشهر القمري : رجب","العام الميلادي :624"],"text":"بَعثَ رسولُ الله صلَّى اللهُ عليه وسلَّم رسولَه عبدَ الله بنَ جَحشٍ الأسَديَّ إلى نَخلةَ في رَجبٍ على رأسِ سَبعةَ عَشَرَ شَهرًا من الهِجرةِ في اثنَيْ عَشَرَ رَجلًا من المُهاجِرين، كلُّ اثنَينِ يَعتَقِبان على بَعيرٍ، فوَصَلوا إلى بَطنِ نَخلةَ يَرصُدون عيرًا لقُريشٍ، وفي هذه السَّريَّةِ سُمِّيَ عبدُ الله بنُ جَحشٍ أميرَ المؤمنين، وكان رسولُ الله كَتَب له كِتابًا، وأمرَه ألَّا يَنظُرَ فيه حتى يَسيرَ يَومَين ثم يَنظُرَ فيه، ولمَّا فَتَح الكِتابَ وَجَد فيه: \"إذا نَظَرْتَ في كِتابي هذا، فامْضِ حتى تَنزِلَ نَخلةَ بينَ مكَّةَ والطَّائِفِ فتَرصُدَ بها قُريشًا، وتَعلَمَ لنا من أخبارِهِم\"، فقال: سَمعًا وطاعةً، وأخبَرَ أصحابَه بذلك، وبأنَّه لا يَستَكرِهُهم، فمَن أحبَّ الشَّهادةَ فليَنهَض، ومَن كَرِهَ الموتَ فليَرجِع، وأمَّا أنا فناهِضٌ. فمَضَوا كلُّهم. فلمَّا كان في أثناء الطَّريقِ أضلَّ سعدُ بن أبي وقَّاصٍ وعُتبةُ بن غَزوانَ بعيرًا لهما كانا يَعتَقِبانِه، فتَخَلَّفا في طَلَبِه، وبَعُدَ عبدُ الله بنُ جَحشٍ حتَّى نزل بنخلةَ، فمَرَّت به عيرٌ لقُرَيشٍ تَحمِلُ زَبيبًا وأُدمًا وتجارةً فيها عَمرُو بنُ الحَضرَميِّ، وعُثمانُ ونَوفَلُ بنُ عبدِ الله بن المُغيرةَ، والحَكَمُ بنُ كَيسانَ مَولَى بني المُغيرةِ فتَشاوَرَ المسلمون، وقالوا: نحنُ في آخِرِ يَومٍ من رَجَبٍ الشَّهرِ الحَرامِ، فإنْ قاتلناهم، انتَهَكْنا الشَّهرَ الحرامَ، وإن تَرَكناهمُ اللَّيلةَ دَخَلوا الحرمَ، ثمَّ أجمَعوا على مُلاقاتِهم فرَمَى أحدُهم عمرَو بنَ الحَضرَميِّ فقَتَلَه، وأسَروا عُثمانَ والحَكَمَ، وأفلتَ نَوفَلٌ، ثم قَدِموا بالعيرِ والأسيرَينِ، وقد عَزَلوا من ذلك الخُمُسَ، وهو أوَّلُ خُمُسٍ كان في الإسلامِ، وأوَّلُ قتيلٍ في الإسلامِ وأوَّلُ أسيرَينِ في الإسلامِ، وأنكرَ رسولُ الله صلَّى اللهُ عليه وسلَّم عليهم ما فعلوه، واشتَدَّ تَعنُّتُ قُريشٍ وإنكارُهم ذلك، وزَعَموا أنَّهم قد وَجَدوا مَقالًا، فقَالوا: قد أحلَّ مُحمَّدٌ الشَّهرَ الحرامَ، واشتدَّ على المسلمين ذلك، حتى أنزلَ اللهُ تعالى: {يَسْألُونَكَ عَنِ الشَّهْرِ الْحَرَامِ قِتَالٍ فيهِ قُلْ قِتَالٌ فيهِ كَبيرٌ وَصَدٌّ عَنْ سَبيلِ اللَّهِ وَكُفْرٌ بِهِ وَالْمَسْجِدِ الْحَرَامِ وَإخْرَاجُ أهْلِهِ مِنْهُ أكْبَرُ عِنْدَ اللَّهِ وَالْفِتْنةُ أكْبَرُ مِنَ الْقَتْلِ} [البقرة: 217]."},{"id":55,"title":"تَحويلُ القِبلَةِ إلى الكعبة .","date":["العام الهجري :2","الشهر القمري : شعبان","العام الميلادي :624"],"text":"عنِ البَراءِ بنِ عازبٍ رضِي الله عنهما قال: \"لمَّا قَدِمَ رسولُ الله صلى الله عليه وسلم المدينةَ صلَّى نحوَ بيتِ المَقدسِ سِتَّةَ عشرَ أو سَبعةَ عشرَ شهرًا، وكان يُحِبُّ أن يُوَجَّهَ إلى الكعبةِ، فأنزل الله تعالى: {قَدْ نَرَى تَقَلُّبَ وَجْهِكَ فِي السَّمَاءِ فَلَنُوَلِّيَنَّكَ قِبْلَةً تَرْضَاهَا} [البقرة: 144]، فَوُجِّهَ نحوَ الكعبةِ، وصلَّى معه رجلٌ العصرَ، ثمَّ خرج فمَرَّ على قومٍ مِنَ الأنصارِ فقال: هو يَشْهَدُ أنَّه صلَّى مع النَّبيِّ صلى الله عليه وسلم، وأنَّه قد وُجِّهَ إلى الكعبةِ، فانحرفوا وهُم ركوعٌ في صلاةِ العصرِ."},{"id":56,"title":"نزول فَرْضِيَّة صِيامِ شَهرِ رَمضانَ .","date":["العام الهجري :2","الشهر القمري : شعبان","العام الميلادي :624"],"text":"في هذه السَّنَةِ فُرِضَ صِيامُ شهرِ رمضانَ، وقِيلَ: إنَّ فَريضةَ صِيامِ شهرِ رمضانَ كانت قبلَ غَزوةِ بدرٍ."},{"id":57,"title":"نزول فَرْضية زكاةِ الفِطرِ .","date":["العام الهجري :2","الشهر القمري : رمضان","العام الميلادي :624"],"text":"شرع الله سُبحانه وتعالى زكاةَ الفِطرِ, وهي واجبةٌ على كُلِّ مُسلمٍ حُرٍّ أو عبدٍ، ذَكَرٍ أو أُنثى، صغيرٍ أو كبيرٍ مِنَ المسلمين قادرٍ عليها. والحِكمةُ منها تَطهيرُ الصَّائمِ ممَّا عسى أن يكونَ قد وقع فيه أثناءَ الصِّيامِ مِن لَغْوٍ أو رَفَثٍ، وإعانةٌ للفقراءِ على إدخالِ السُّرورِ عليهم في يومِ العيدِ."},{"id":58,"title":"سرية عمير بن عدي رضي الله عنه لقتل عصماء بنت مروان .","date":["العام الهجري :2","الشهر القمري : رمضان","العام الميلادي :624"],"text":"كانت عَصماءُ بِنتُ مَرْوانَ مِن بني أُمَيَّةَ بنِ زَيدٍ، زَوجةُ يَزيدَ بنِ زَيدِ بنِ حِصنٍ الخَطْميِّ، تَعيبُ الإسلامَ وتُؤذي رسولَ اللَّه صلَّى اللهُ عليه وسلَّم، وتُحرِّضُ عليه.وكانت تَطرَحُ المَحايِضَ في مسجِدِ بني خَطْمةَ؛ فأهدَرَ رسولُ اللَّه صلَّى اللهُ عليه وسلَّم دَمَها، فنَذَر عُمَيرُ بنُ عَديٍّ لئن رَجَعَ رسولُ اللَّه صلَّى اللهُ عليه وسلَّم من بَدرٍ إلى المدينة ليَقتُلَنَّها، وقد فعل رضي الله عنه وأرضاه.فلمَّا رَجَع عُميرٌ وَجَد بَنيها في جماعةٍ يَدفِنونَها. فقالوا: يا عُمَيرُ، أنتَ قَتَلْتَها؟ قال: \"نَعَم، فكيدوني جَميعًا ثم لا تُنظِرونِ، فَوَالَّذي نَفسي بيَدِه لو قلتُم بأجمَعِكُم ما قالَت لضَرَبتُكُم بسَيفي هذا حتَّى أموتَ أو أقتُلَكُم\". فيومَئذٍ ظَهَر الإسلامُ في بني خَطْمةَ، وكان يَستخفي بإسلامِه فيهم مَن أسلَمَ، فكان أولُ مَن أسلَمَ مِن بني خَطْمةَ عُمَيرَ بنَ عَديٍّ، وهو الذي يُدعَى القارِئَ."},{"id":59,"title":"غَزوةُ بدرٍ (الكُبرى) وانْتصارُ المُسلمين .","date":["العام الهجري :2","الشهر القمري : رمضان","العام الميلادي :624"],"text":"ندَب رسولُ الله صلى الله عليه وسلم نَفرًا مِنَ المسلمين لاعتراضِ قافلةِ قُريشٍ القادمةِ مِنَ الشَّامِ التي كان يرأَسُها أبو سُفيانَ الذي عَلِمَ بعدَ ذلك بِخُروجِ المُسلمين، فأَرسل إلى قُريشٍ يَسْتَنْفِرُها لاسْتِنقاذِ تِجارتِهم كما غَيَّرَ طريقَهُ لإنقاذِ التِّجارةِ، ثمَّ الْتَقى المسلمون والمشركون عند ماءِ بدرٍ، وهي مكانٌ بين مكَّةَ والمدينةِ وهو أَقربُ إليها مِن مكَّةَ، وكان عددُ المشركين يُقارِبُ الألفَ، وعددُ المسلمين أَكثرُ مِن ثلاثمائةٍ، وبدأتِ المعركةُ بالمُبارزَةِ المَشهورةِ، ثمَّ بدأ القِتالُ وكان شديدًا، وقُتِلَ فيها صَناديدُ قُريشٍ كأبي جهلٍ، وأُميَّةَ بنِ خَلفٍ، وغَيرِهِما، حتَّى بلَغ قَتلاهُم سبعون رجلًا ومِثلُهم مِنَ الأَسرى، وقُتِلَ أربعةَ عشرَ مِنَ المسلمين، وقِيلَ: سِتَّةَ عشرَ. فكان النَّصرُ الكبيرُ حَليفَ المسلمين. حيث نَصرهُم الله تعالى وأَرسل ملائكةً تُقاتلُ معهم، أمَّا الأَسرى فأشار عُمَرُ بِقتلِهم، وأشار أبو بكرٍ بِفِدائِهم، فأخذ النَّبيُّ صلى الله عليه وسلم برأيِ أبي بكرٍ، ولكنَّ الوَحيَ نزل مُوافقًا لرأيِ عُمَرَ، أمَّا الغَنائمُ فنزلت فيها سورةُ الأَنفالِ."},{"id":60,"title":"وفاةُ رُقَيَّةَ رضِي الله عنها .","date":["العام الهجري :2","الشهر القمري : رمضان","العام الميلادي :624"],"text":"هي رُقَيَّةُ بنتُ سَيِّدِ البَشرِ صلَّى الله عليه وسلَّم، وهي زوجُ عُثمانَ بنِ عفَّانَ رضِي الله عنهما، وكانت رُقَيَّةُ أوَّلًا عند عُتْبَةَ بنِ أبي لَهبٍ، فلمَّا بُعِثَ النَّبيُّ صلَّى الله عليه وسلَّم أَمَرَ أبو لَهبٍ ابنَهُ بِطلاقِها، فتَزوَّجها عُثمانُ وهاجر بها إلى الحَبشةِ. ولمَّا نَدَبَ رسولُ الله النَّاسَ للخُروجِ لاعتراضِ قافلةِ أبي سُفيانَ أَمَرَ عُثمانَ أن يَبقى عند رُقَيَّةَ يُمَرِّضُها ويَعتَني بها، وكان هذا هو سببُ تَخَلُّفِهِ، وقد أَسهمَ له النَّبيُّ صلى الله عليه وسلم كما أَسهمَ لمن حضَر بدرًا، ثم ما لَبِثَتْ رُقَيَّةُ في مَرضِها حتَّى تُوفِّيتْ رضي الله عنها."},{"id":61,"title":"سرية سالم بن عمير رضي الله تعالى عنه إلى أبي عفك اليهودي .","date":["العام الهجري :2","الشهر القمري : شوال","العام الميلادي :624"],"text":"كانت سريَّةُ سالِمِ بنِ عُمَيرٍ رَضي اللهُ عنه إلى أبي عَفَكٍ اليَهوديِّ في شوَّالٍ على رأسِ عشرين شهرًا من مُهاجَرِ رسولِ الله صلَّى اللهُ عليه وسلَّم، وكان أبو عَفَكٍ من بني عمرِو بن عوفٍ شَيخاً كبيرًا قد بلغ عشرين ومئةَ سنةٍ، وكان يَهوديًّا، عَظيمَ الكُفرِ، شديدَ الطَّعنِ على المسلمين، قد امتَلَأ قلبُه بالحقدِ والحسدِ للمسلمين، وهو يرى الْتِفافَ الأوسِ والخزرجِ على نُصرةِ رسولِ الله صلَّى اللهُ عليه وسلَّم، وازدادَ كيدُه بالإسلامِ وأهلِهِ بعد أنْ رَأى رسولَ الله صلَّى اللهُ عليه وسلَّم يزداد قوَّةً وتَمكينًا في المدينةِ وما حولَها بعد غزوةِ بدرٍ، فلم يُطِقْ لذلك صَبرًا، فأخذ يُنشِدُ الشِّعرَ يَهجو به رسولَ الله صلَّى اللهُ عليه وسلَّم ويُحرِّضُ على عداوَتِه، ويُسَفِّهُ رأيَ الأنصارِ لمُتابَعَتِهم رسولَ الله صلَّى اللهُ عليه وسلَّم ومُناصَرَتِه. فقال سالِمُ بنُ عُمَيرٍ وهو أحدُ البَكَّائين -أي: في غَزوةِ تَبوكَ- ومِمَّن شَهِد بَدرًا: \"عليَّ نَذرٌ أن أقتُلَ أبا عَفَكٍ أو أموتَ دُونَه\"، فأمهَلَ يَطلُبُ له غِرَّةً، حتى كانت ليلةٌ صائِفةٌ، فنام أبو عَفَكٍ بالفِناءِ، وسَمِعَ به سالِمُ بنُ عُميرٍ، فأقبَلَ فوَضَعَ السَّيفَ على كَبِدِه، ثم اعتَمَدَ عليه حتى خَشَّ في الفراشِ، وصاح عدوُّ اللهِ، فثاب إليه ناسٌ مِمَّن هم على قَولِه، فأدخَلوه منزلَه وقَبَروه. وكان أبو عَفَكٍ مِمَّن نَجَم نِفاقُه حين قَتَلَ رسولُ الله صلَّى اللهُ عليه وسلَّم الحارِثَ بنُ سُويدِ بنِ الصَّامِتِ، وشَهِدَ سالِمٌ بَدرًا، وأُحدًا، والخَندَقَ، والمَشاهِدَ كُلَّها مع رسول الله صلَّى اللهُ عليه وسلَّم، وتوُفِّي في خِلافةِ مُعاويةَ بن أبي سُفيانَ رَضي اللهُ عنهما."},{"id":62,"title":"غَزوةُ بني قَينُقاعٍ .","date":["العام الهجري :2","الشهر القمري : شوال","العام الميلادي :624"],"text":"ذكَر مُعظمُ أهلِ المَغازي والسِّيَرِ أنَّها وقعت بعدَ بدرٍ، ورجَّحهُ ابنُ حَجَرٍ، وقد كانت يومَ السَّبتِ للنِّصفِ مِن شَوَّالٍ. وخَبرُ إجلاءِ بني قَينُقاعٍ ثابتٌ في الصَّحيحينِ، فعنِ ابنِ عُمَرَ رضِي الله عنهما قال: \"حاربَتِ النَّضيرُ وقُرَيْظةُ، فأَجْلى بني النَّضيرِ، وأَقَرَّ قُرَيْظَةَ ومَن عليهم، حتَّى حاربتْ قُرَيْظَةُ، فقَتَلَ رِجالَهم، وقَسَمَ نِساءَهُم وأَولادَهُم وأَموالَهُم بين المسلمين، إلَّا بعضَهُم لَحِقوا بالنَّبيِّ صلى الله عليه وسلم فآمَنَهُم وأَسلَموا، وأَجْلى يَهودَ المدينةِ كُلَّهم: بني قَيْنُقاعٍ -وهُم رَهْطُ عبدِ الله بنِ سَلامٍ- ويَهودَ بني حارِثةَ، وكُلَّ يَهودِ المدينةِ\""},{"id":63,"title":"غزوة السويق أو غزوة بني سليم (قرقرة الكدر) .","date":["العام الهجري :2","الشهر القمري : شوال","العام الميلادي :624"],"text":"بعد هَزيمةِ المُشرِكين في بدْرٍ، نَذَر أبو سُفيانَ ألَّا يَمَسَّ رَأسَه ماءٌ من جَنابةٍ حتى يَغزوَ مُحمَّدًا صلَّى اللهُ عليه وسلَّم وأصحابَه ويَنتقِمَ من المسلمين؛ فخَرَج في مِائتَي راكِبٍ من قُريشٍ، ليَبَرَّ بيَمينِه، ووَصَل إلى أطرافِ المَدينةِ لَيلًا، ولَجَأ إلى بني النَّضيرِ، فأتَى حُيَيَّ بنَ أخطَبَ، فضَرَب عليه بابِه، فأبَى أن يَفتَحَ له بابَه وخافَهُ؛ فانصَرَف عنه إلى سَلَّامِ بنِ مِشكَمٍ -وكان سيِّدَ بني النَّضيرِ في زَمانِه ذلك، وصاحِبُ كَنزِهِم- فاستَأذَنَ عليه؛ فأذِنَ له، فضيَّفَه وسَقاهُ خَمرًا، وأخبَرَه من أخبارِ رسولِ الله صلَّى اللهُ عليه وسلَّم، ثم خَرَج أبو سُفيانَ في عَقِبِ لَيلَتِه حتى أتى أصحابَه، فبَعَث رجالًا من قُرَيشٍ، فأتَوا ناحيةً من المَدينةِ يُقالُ لها: العَريضُ -وادٍ بالمدينةِ-، فأشعَلوا النَّارَ في أشجارِ ونَخيلِ المُسلمين المُثمِرةِ، ووَجَدوا رجلًا من الأنصارِ وحَليفًا له في حَرثٍ لهما، فقَتَلوهما، ثمَّ وَلَّوا مُدبِرين. فبَلَغ ذلك رسولَ الله صلَّى اللهُ عليه وسلَّم، فخَرَج في أثَرِهِم يَطلُبُهم في مِائتَينِ من المُهاجِرين والأنصارِ، واستَعمَلَ على المدينةِ أبا لُبابةَ بَشيرَ بنَ عبدِ المُنذِرِ رَضي اللهُ عنه، فجَعَل أبو سُفيانَ وأصحابُه يُلْقون جِرَبَ -أوعيةَ- السَّويقِ -قَمحٍ أو شَعيرٍ يُقلَى ثمَّ يُطحَنُ، فيُتزَوَّدُ به، مَلْتوتًا بماءٍ أو سمنٍ أو عسلٍ-، وهي عامَّةُ أزوادِهِم، يتَخفَّفون منها للنَّجاءِ، حتى بَلغَ رسولُ الله -صلَّى اللهُ عليه وسلَّم- قَرقَرةَ -القَرقَرُ: الأرضُ المُستَويةُ- الكَدْرِ -ماءٌ لبني سُلَيمٍ، وأصلُ الكُدْرِ: طَيرٌ في ألوانِها كُدْرةٌ، سُمِّيَ المَوضِعُ أو الماءُ به-، ثم انصَرَف راجِعًا إلى المدينةِ، وقد فاتَه أبو سُفيانَ وأصحابُه، وكانت غَيبةُ الرسولِ -صلَّى اللهُ عليه وسلَّم خمسةَ أيَّامٍ، فقال المسلمون حينَ رَجَع بهم رسولُ الله صلَّى اللهُ عليه وسلَّم: يا رسولَ الله، أتطمَعُ لنا أن تَكونَ غزوةً؟ قال: \"نعم\". وتُسمَّى هذه الغَزوةُ أيضًا بـ\"غزوةِ السَّويقِ\"؛ لأنَّ أكثَرَ ما طَرَح القَومُ مِن أزوادِهِمُ السَّويقُ، فرَجَع المسلمون بسَويقٍ كثيرٍ. وكان ذلك في شوَّالٍ في السَّنةِ الثَّانيةِ من الهجرةِ."},{"id":64,"title":"غَزوةُ السَّوِيقِ (قَرْقَرَةِ الكُدْرِ) .","date":["العام الهجري :2","الشهر القمري : ذي الحجة","العام الميلادي :624"],"text":"كان أبو سُفيانَ حين رجع إلى مكَّةَ مِن بدرٍ قد نذَر أن لا يَمَسَّ رأسَهُ ماءٌ مِن جَنابَةٍ، حتَّى يغزو محمَّدًا، فخرج في مِائتي راكبٍ مِن قُريشٍ لِتَبرَّ يَمينَه فسلك النَّجْدِيَّةَ حتَّى نزل بصَدرِ قناةٍ إلى جبلٍ يُقالُ له: نَيْبٌ مِنَ المدينةِ على بَريدٍ أو نحوهِ، ثمَّ خرج من اللَّيلِ حتَّى أتى بني النَّضيرِ تحت اللَّيلِ فأتى حُيَيَّ بنَ أَخْطَبَ فضرَب عليه بابَهُ، فأبى أن يفتحَ له وخافَهُ، فانصرف عنه إلى سَلَّامِ بنِ مِشْكَمٍ، وكان سَيِّدَ بني النَّضيرِ في زمانِه، فاستأَذن عليه فأَذِنَ له، فَقَراهُ وسَقاهُ، وبَطَنَ له مِن خبرِ النَّاسِ، ثمَّ خرج في عَقِبِ ليلتِه حتَّى أتى أصحابَه فبعث رِجالًا مِن قُريشٍ فأتَوْا ناحيةً منها يُقالُ لها: العُرَيْضُ فحَرقوا في أَصْوارٍ مِن نَخلٍ بها، ووجدوا رجلًا مِنَ الأنصارِ وحليفًا له في حَرْثٍ لهما فقَتلوهُما وانصَرفوا راجِعين، فنَذَرَ بِهم النَّاسُ، فخرج رسولُ الله صلى الله عليه وسلم في طَلَبِهم, فبلغ قَرْقَرَةَ الكُدْرِ، ثمَّ انصرف راجعًا وقد فاتَهُ أبو سُفيانَ وأصحابُه، ووجد أصحابُ رسولِ الله صلى الله عليه وسلم أَزوادًا كثيرةً قد أَلقاها المشركون يتَخفَّفون منها، وعامتُها سَوِيقٌ، فسُمِّيتْ غَزوةَ السَّوِيقِ."},{"id":65,"title":"مَقتَلُ كعبِ بنِ الأَشرفِ .","date":["العام الهجري :3","العام الميلادي :624"],"text":"كعبُ بنُ الأَشرفِ رجلٌ مِن طَيِّءٍ وأمُّهُ مِن يَهودِ بني النَّضيرِ. كان شاعرًا يَهجو النَّبيَّ صلى الله عليه وسلم وأصحابَه ويُحرِّضُ عليهم ويُؤذيهِم، فلمَّا كانت وقعةُ بدرٍ كُبِتَ وذُلَّ وقال: بطنُ الأرضِ خيرٌ مِن ظَهرِها اليومَ. فخرج حتَّى قَدِمَ مكَّةَ فبَكى قَتلى قُريشٍ وحَرَّضهُم بالشِّعرِ، قال جابرُ بنُ عبدِ الله: قال: رسولُ الله صلى الله عليه وسلم: «مَن لِكعبِ بنِ الأَشرفِ؟ فإنَّه قد آذى الله ورسولَهُ». فقال محمَّدُ بنُ مَسلمةَ: يا رسولَ الله، أَتُحِبُّ أن أَقتُلَهُ؟ قال: «نعم». قال: ائْذَنْ لي فَلْأَقُلْ. قال: «قُلْ». فأَتاهُ فقال له، وذَكَر ما بينهما، وقال: إنَّ هذا الرَّجلَ قد أراد صَدقةً وقد عَنَّانا. فلمَّا سمِعَه قال: وأيضًا والله لَتَمَلُّنَّهُ. قال: إنَّا قد اتَّبعناهُ الآنَ، ونَكرهُ أن نَدعَهُ حتَّى ننظُرَ إلى أيِّ شيءٍ يَصيرُ أَمرُهُ. قال: وقد أردتُ أن تُسلِّفَني سَلفًا. قال: فما تَرْهَنُني؟ قال: ما تريدُ؟ قال: تَرهَنُني نِساءَكُم. قال: أنت أَجملُ العربِ، أَنَرهنُك نِساءَنا! قال له: تَرهَنُوني أولادَكُم. قال: يُسَبُّ ابنُ أَحدِنا، فيُقالُ: رُهِنَ في وَسَقَينِ مِن تمرٍ، ولكنْ نَرهَنُك اللَّأْمَةَ -يعني السِّلاحَ- قال: فنعم. وواعَدهُ أن يَأتِيَهُ بالحارثِ، وأبي عَبْسِ بنِ جَبْرٍ، وعبَّادِ بنِ بِشْرٍ، قال: فجاءوا فَدَعَوْهُ ليلًا فنزل إليهِم، قال سُفيانُ: قال غيرُ عَمرٍو: قالت له امرأتُه: إنِّي لأَسمَعُ صوتًا كأنَّه صوتُ دَمٍ. قال: إنَّما هذا محمَّدُ بنُ مَسلمةَ، ورَضيعُهُ، وأبو نائِلَةَ، إنَّ الكريمَ لو دُعِيَ إلى طَعنَةٍ ليلًا لأَجابَ. قال محمَّدٌ: إنِّي إذا جاء فسَوف أَمُدُّ يَدي إلى رأسِهِ، فإذا اسْتمكَنتُ منه فَدُونَكُم. قال: فلمَّا نزل نزل وهو مُتوَشِّحٌ، فقالوا: نَجِدُ منك ريحَ الطِّيبِ. قال: نعم تَحْتِي فُلانةُ هي أَعطرُ نِساءِ العربِ. قال: فتأذنُ لي أن أَشُمَّ منه، قال: نَعم فَشُمَّ. فتناوَل فَشَمَّ، ثمَّ قال: أَتأذنُ لي أن أَعودَ، قال: فاسْتمكَنَ مِن رأسِهِ، ثمَّ قال: دُونَكُم. قال: فقَتلوهُ\". (....ثمَّ أَتَوْا النَّبيَّ صلى الله عليه وسلم فأَخبَروهُ)."},{"id":66,"title":"غزوة غطفان إلى نجد (غزوة ذي أمرّ) .","date":["العام الهجري :3","الشهر القمري : صفر","العام الميلادي :624"],"text":"وهي غزوةُ ذي أمَرَّ بناحيةِ نَجدٍ. وسَبَبُها: أنَّ رسولَ الله صلَّى اللهُ عليه وسلَّم بَلَغه أنَّ جَمعًا من بني ثَعلَبَة بنِ سَعيدِ بن ذُبْيانَ بن بَغيضٍ بنِ رَيثِ بن غَطَفانَ، وبني مُحارِبِ بن خَصَفةَ بن قَيسٍ بذي أمَرَّ قد تَجَمَّعوا يُريدون أن يُصيبوا مِن أطرافِ رسولِ الله صلَّى اللهُ عليه وسلَّم، وجَمَعهم رجلٌ منهم يُقال له: دُعْثورُ بن الحارِثِ بن مُحارِبٍ، فنَدَب رسولُ الله صلَّى اللهُ عليه وسلَّم المسلمين، وخرج في أربعِمِئةٍ وخَمسين، معهم عِدَّةُ أفراسٍ، واستَخلَف على المدينةِ عُثمانَ بنَ عفانَ، فأصابوا بالمدينةِ رجلًا منهم بذي القَصَّةِ يُقال له: جَبَّارٌ من بني ثَعلَبةَ، فقال له المسلمون: أين تُريد؟ فقال: أُريدُ يَثرِبَ لأرتاَد لنَفسي وأنظُرَ، فأُدخِلَ على رسولِ الله صلَّى اللهُ عليه وسلَّم فأخبَرَه مِن خَبَرِهم، قال: لن يُلاقوك ولو سَمِعوا بسَيرِك هَرَبوا في رؤوسِ الجبالِ وأنا سائِرٌ معك، فدعاه رسولُ الله صلَّى اللهُ عليه وسلَّم إلى الإسلامِ وأسلم، وضمَّه رسولُ الله صلَّى اللهُ عليه وسلَّم إلى بلالٍ، فأخَذَ به جبَّارٌ طَريقًا، وهَبَط به عليهم، وسَمِع القومُ بمَسيرِ رسول الله صلَّى اللهُ عليه وسلَّم، فهَرَبوا في رؤوسِ الجِبالِ، فبَلَغ ماءً يقال له: ذو أمَرَّ، فعَسكرَ به، وأصاب رسولَ الله صلَّى اللهُ عليه وسلَّم وأصحابَه مطرٌ كثيرٌ، فابتَلَّت ثيابُ رسولِ الله صلَّى اللهُ عليه وسلَّم وثيابُ أصحابِهِ؛ فنزل رسولُ الله صلَّى اللهُ عليه وسلَّم تحتَ شجرةٍ ونَشَر ثيابَهُ لتَجِفَّ، واضطَجَع، وذلك بمَرأًى من المُشرِكين، واشتَغَل المسلمون في شؤونِهم. فبَعَث المشركون رَجلًا شُجاعًا منهم يقال له: دُعْثورُ بنُ الحارث، وكان سيِّدَها وأشجَعَها، ومعه سيفٌ متقلِّدٌ به، فبادَرَ دُعْثورٌ وأقبَلَ مُشتَمِلًا على السَّيفِ، حتى قام على رأسِ رسولِ الله صلَّى اللهُ عليه وسلَّم بالسَّيفِ مشهورًا، فقال: يا مُحمَّدُ، مَن يَمنَعُك مِنِّي اليَومَ؟ فقال رسول الله صلَّى اللهُ عليه وسلَّم: \"اللهُ\". ودَفَع جِبريلُ في صدرِه، فوقَع السَّيفُ من يدِه؛ فأخَذه رسولُ الله صلَّى اللهُ عليه وسلَّم، وقال له: \"مَن يَمنَعُك مِنِّي؟!\" فقال: لا أحَدَ، وأنا أشهَدُ أن لا إله إلا اللهُ وأنَّ محمدًا رسولُ الله، والله لا أُكثِّرُ عليك جَمعًا أبدًا، فأعطاهُ رسول الله صلَّى اللهُ عليه وسلَّم سيفَه.ثم أتى قَومَه فقالوا: ما لك؟ وَيلَكَ! فقال: نَظرتُ إلى رجلٍ طَويلٍ، فدَفَع في صَدري، فوَقَعتُ لظَهري، فعَرَفتُ أنَّه مَلَك، وشَهِدتُ بأنَّ مُحَمَّدًا رسول الله، واللهِ لا أُكثِّرُ عليه جَمعًا. وجَعَل يَدعو قومَه إلى الإسلامِ. وأنزل الله تعالى: {يَا أيُّهَا الَّذينَ آمَنُوا اذْكُرُوا نِعْمَتَ اللَّهِ عَلَيْكُمْ إِذْ هَمَّ قَوْمٌ أن يَبْسُطُوا إِلَيْكُمْ أيْدِيَهُمْ فَكَفَّ أيْدِيَهُمْ عَنْكُمْ} [المائدة 11]. وعاد رسولُ الله صلَّى اللهُ عليه وسلَّم إلى المدينةِ، ولم يَلْقَ كَيدًا، وكانت غَيبَتُه خمسَ عشرةَ ليلةً، وقيل: قام رسولُ الله صلَّى اللهُ عليه وسلَّم بنَجدٍ صَفَرَ كُلَّه."},{"id":67,"title":"غزوة بحران بين الفُرْعِ والمدينة .","date":["العام الهجري :3","الشهر القمري : ربيع الآخر","العام الميلادي :624"],"text":"غزا رسولُ الله صلَّى اللهُ عليه وسلَّم يُريدُ قُريشًا، واستَعمَلَ على المدينةِ عبدَ الله بنَ أُمِّ مَكتومٍ رَضي اللهُ عنه، حتى بَلَغ بُحرانَ مِن ناحيةِ الفُرْعِ. وسَبَبُها: أنَّه بَلَغَ النبيَّ صلَّى اللهُ عليه وسلَّم أنَّ بها جَمعًا كثيرًا من بني سُلَيمِ بنِ مَنصورٍ؛ فخَرَج في ثَلاثِمئةِ رجلٍ من أصحابِه، ولم يُظهِر وَجهًا للسَّيرِ؛ حتى إذا كان دونَ بُحرانَ بليلةٍ لَقيَ رجلًا من بني سُلَيمٍ فأخبَرَهم أنَّ القَومَ افتَرَقوا فحَبَسَه مع رَجلٍ، وسار حتى وَرَد بُحرانَ وليس به أحدٌ، فأقام أيامًا ثم رَجَع ولم يَلْقَ كيدًا وأرسل الرَّجُلَ. ثم انصرف راجعًا إلى المدينةِ."},{"id":68,"title":"سَرِيَّةُ زيدِ بنِ حارِثةَ .","date":["العام الهجري :3","الشهر القمري : جمادى الأولى","العام الميلادي :624"],"text":"أَصبحَ مُشرِكو مكَّةَ بعدَ هَزيمَتِهم في غَزوةِ بدرٍ، يَبحَثون عن طريقٍ أُخرى لِتِجارتِهم للشَّامِ، فأشارَ بعضُهم إلى طريقِ نَجْدِ العِراقِ، وقد سَلكوها بالفعلِ، وخرج منهم تُجَّارٌ، فيهم أبو سُفيانَ بنُ حَربٍ، وصَفوانُ بنُ أُميَّةَ، وحُوَيْطِبُ بنُ عبدِ العُزَّى، ومعهم فِضَّةٌ وبضائعُ كثيرةٌ، بما قيمتُه مائةُ ألفِ دِرهمٍ؛ فبلغ ذلك رسولُ الله صلى الله عليه وسلم بواسطةِ سَليطِ بنِ النُّعمانِ رضي الله عنه، فبعَث زيدَ بنَ حارِثةَ في مائةِ راكبٍ لِاعتِراضِ القافلةِ، فلَقِيَها زيدٌ عند ماءٍ يُقالُ له: القَرَدَةُ، وهو ماءٌ مِن مِياهِ نَجْدٍ، فَفَرَّ رجالُها مَذعورين، وأصاب المسلمون العِيرَ وما عليها، وأَسَروا دَليلَها فُراتَ بنَ حيَّانَ الذي أَسلمَ بين يَدي النَّبيِّ صلى الله عليه وسلم، وعادوا إلى المدينةِ، فخَمَّسَها رسولُ الله صلى الله عليه وسلم ووَزَّعَ الباقيَ بين أَفرادِ السَّرِيَّةِ."},{"id":69,"title":"غَزوةُ أُحُدٍ وسبب هزيمة المسلمين .","date":["العام الهجري :3","الشهر القمري : شوال","العام الميلادي :625"],"text":"كان سببُها أنَّ المشركين حين قُتِلَ مَن قُتِلَ مِن أَشرافِهِم يوْمَ بَدْرٍ، وسَلمَت العِيرُ بما فيها مِنَ التِّجارةِ التي كانت مع أبي سُفيانَ، فلمَّا رجع فَلُّهُم إلى مكَّةَ قال أبناءُ مَن قُتِلَ، ورُؤساءُ مَن بَقِيَ لأبي سُفيانَ: ارْصُدْ هذه الأموالَ لِقتالِ محمَّدٍ، فأَنفَقوها في ذلك، وجمعوا الجُموعَ والأَحابيشَ وأَقبلوا في قَريبٍ مِن ثلاثةِ آلافٍ، حتَّى نزلوا قريبًا مِن أُحُدٍ تِلْقاءَ المدينةِ، فصلَّى رسولُ الله صلى الله عليه وسلم يومَ الجُمعةِ، فلمَّا فَرَغَ منها صلَّى على رجلٍ مِن بني النَّجَّارِ، يُقالُ له: مالكُ بنُ عَمرٍو، واسْتَشار النَّاسَ: أَيخرُجُ إليهِم، أمْ يَمكُثُ بالمدينةِ؟ فأشار عبدُ الله بنُ أُبَيٍّ بالمقامِ بالمدينةِ، فإن أقاموا أقاموا بِشَرِّ مَحْبسٍ وإن دخلوها قاتلَهُم الرِّجالُ في وُجوهِهم، ورَماهم النِّساءُ والصِّبيانُ بالحِجارةِ مِن فوقِهم، وإن رجعوا رجعوا خائِبين. وأشار آخرون مِنَ الصَّحابةِ ممَّن لم يَشهدْ بدرًا بالخُروجِ إليهم، فدخل رسولُ الله صلى الله عليه وسلم فلَبِسَ لَأْمَتَهُ وخرج عليهم... فسار في ألفٍ مِن أصحابِهِ، فلمَّا كان بالشَّوطِ رجع عبدُ الله بنُ أُبَيٍّ في ثُلُثِ الجيشِ مُغْضَبًا؛ لِكَونِه لم يُرجَعْ إلى قولِه، وقال هو وأصحابُه: لو نعلمُ اليومَ قِتالًا لاتَّبَعناكُم، ولكِنَّا لا نَراكُم تُقاتلون اليومَ. واستَمرَّ رسولُ الله صلى الله عليه وسلم سائرًا حتَّى نزل الشِّعْبَ مِن أُحُدٍ في عَدْوَةِ الوادي. وجعل ظَهرَهُ وعَسكرَهُ إلى أُحُدٍ، وتَهيَّأَ رسولُ الله صلى الله عليه وسلم للقِتالِ وهو في سبعمائةٍ مِن أصحابِهِ، وأمَّرَ على الرُّماةِ عبدَ الله بنَ جُبَيْرٍ أخا بني عَمرِو بنِ عَوفٍ، والرُّماةُ يَومئذٍ خمسون رجلًا. فقال: انْضَحْ الخَيْلَ عَنَّا بِالنَّبْلِ، لا يَأتونا مِن خَلفِنا، إن كانت لنا أو علينا، فاثْبُتْ مكانَك لا نُؤْتَيَنَّ مِن قِبَلِكَ، وظاهَر رسولُ الله صلى الله عليه وسلم بين دِرعَينِ، وأَعطى اللِّواءَ مُصعبَ بنَ عُميرٍ أخا بني عبدِ الدَّارِ، وأجاز رسولُ الله صلَّى الله عليه وسلَّم بعضَ الغِلْمانَ يَومئذٍ وأَرجأَ آخرين، وتَعبَّأتْ قُريشٌ وهُم ثلاثةُ آلافٍ، ومعهم مائتا فَرَسٍ قد جَنَبُوها، فجعلوا على مَيْمَنةِ الخَيْلِ خالدَ بنَ الوليدِ، وعلى المَيسَرةِ عِكْرِمةَ بنَ أبي جَهْلٍ، ودفعوا إلى بني عبدِ الدَّارِ اللِّواءَ... ثمَّ كان بين الفَريقين ما كان، وكانت بَوادرُ النَّصرِ تَلوحُ لِصالحِ المسلمين، فلمَّا رَأى المسلمون تَقَهْقُرَ المشركين أَهملَ الرُّماةُ وَصِيَّةَ نَبِيِّهِم لهم ونزلوا يَحصُدون الغَنائمَ، فانْتهَز خالدُ بنُ الوليدِ الفُرصةَ فالْتَفَّ خَلفَهم وأَعملَ الحربَ فيهم، ممَّا أَدَّى لِقَلْبِ الموازينِ وانْجَلَتِ المعركةُ عن مَقْتَلِ سبعين رجلًا مِن المسلمين مِنهم حمزةُ بنُ عبدِ المُطَّلبِ، ومُصعبُ بنُ عُميرٍ، وعبدُ الله بنُ حَرامٍ والدُ جابرٍ، وعبدُ الله بنُ جُبيرٍ أَميرُ الرُّماةِ...."},{"id":70,"title":"اسْتِشهادُ حَمزةَ رضِي الله عنه في غَزوةِ أُحُدٍ .","date":["العام الهجري :3","الشهر القمري : شوال","العام الميلادي :625"],"text":"عن عُبيدِ اللهِ بنِ عَدِيِّ بنِ الخِيارِ أنَّه سألَ وَحْشِيًّا قاتلَ حَمزةَ، ألا تُخبِرُنا بِقتلِ حَمزةَ؟ قال: نعم، إنَّ حَمزةَ قَتَلَ طُعَيْمَةَ بنَ عَدِيِّ بنِ الخِيارِ ببَدرٍ، فقال لي مولايَ جُبيرُ بنُ مُطْعِمٍ: إن قَتلتَ حَمزةَ بِعَمِّي فأنت حُرٌّ، قال: فلمَّا أن خرج النَّاسُ عامَ عَيْنَيْنِ، وعَيْنَيْنُ جبلٌ بِحِيالِ أُحُدٍ، بينه وبينه وادٍ، خرجتُ مع النَّاسِ إلى القِتالِ، فلمَّا أن اصْطَفُّوا للقِتالِ، خرج سِباعٌ فقال: هل مِن مُبارِزٍ؟ قال: فخرج إليه حَمزةُ بنُ عبدِ المُطَّلبِ، فقال: يا سِباعُ، يا ابنَ أُمِّ أَنْمارٍ مُقَطِّعَةِ البُظورِ، أَتُحادُّ الله ورسولَهُ صلى الله عليه وسلم؟ قال: ثمَّ شَدَّ عليه، فكان كأَمسِ الذَّاهبِ، قال: وكَمَنْتُ لِحَمزةَ تحتَ صَخرةٍ، فلمَّا دَنا مِنِّي رَميتُهُ بِحَربَتي، فأضعُها في ثُنَّتِهِ حتَّى خَرجتْ مِن بين وَرِكَيْهِ، قال: فكان ذاك العهدُ به، فلمَّا رجع النَّاسُ رجعتُ معهم، فأَقمتُ بمكَّةَ حتَّى فَشا فيها الإسلامُ، ثمَّ خَرجتُ إلى الطَّائفِ، فأَرسلوا إلى رسولِ الله صلى الله عليه وسلم رسولًا، فقِيلَ لي: إنَّه لا يَهيجُ الرُّسُلَ. قال: فخَرجتُ معهم حتَّى قَدِمتُ على رسولِ الله صلى الله عليه وسلم، فلمَّا رآني قال: «آنت وَحْشِيٌّ؟». قلتُ: نعم. قال: «أنت قَتلتَ حَمزةَ؟». قلتُ: قد كان مِنَ الأمرِ ما بَلغكَ. قال: «فهل تَستَطيعُ أن تُغَيِّبَ وَجهَك عَنِّي» قال: فَخرجتُ فلمَّا قُبِضَ رسولُ الله صلى الله عليه وسلم فخرج مُسَيْلِمَةُ الكذَّابُ، قلتُ: لأَخرُجَنَّ إلى مُسَيْلِمَةَ، لَعَلِّي أقتُلُه فأُكافِئَ به حَمزةَ، قال: فخرجتُ مع النَّاسِ، فكان مِن أَمرهِ ما كان، قال: فإذا رجلٌ قائمٌ في ثَلْمَةِ جِدارٍ، كأنَّهُ جَمَلٌ أَوْرقُ ثائِرُ الرَّأسِ، قال: فَرمَيْتُه بِحَربَتي، فأَضعُها بين ثَدييهِ حتَّى خَرجتْ مِن بين كَتِفَيْهِ، قال: ووثبَ إليه رجلٌ مِنَ الأنصارِ فضَربهُ بالسَّيفِ على هامَتِهِ."},{"id":71,"title":"غَزوةُ حَمراءِ الأَسدِ .","date":["العام الهجري :3","الشهر القمري : شوال","العام الميلادي :625"],"text":"قال ابنُ كَثيرٍ في تَفسيرِ قولِه تعالى: {الَّذِينَ اسْتَجَابُوا لِلَّهِ وَالرَّسُولِ مِنْ بَعْدِ مَا أَصَابَهُمُ الْقَرْحُ} هذا كان يومَ حَمراءِ الأسدِ، وذلك أنَّ المشركين لمَّا أصابوا ما أصابوا مِن المسلمين -أي يومَ أُحُدٍ-كَرُّوا راجِعين إلى بلادِهم، فلمَّا استَمرُّوا في سَيْرهِم تَنَدَّمُوا لِمَ لا تَمَّموا على أهلِ المدينةِ وجعلوها الفَيْصلةَ. فلمَّا بلغ ذلك رسولَ الله صلى الله عليه وسلم نَدَبَ المسلمين إلى الذِّهابِ وراءَهُم ليُرْعِبَهم ويُرِيَهُم أنَّ بهِم قُوَّةً وجَلَدًا، ولم يأذنْ لأَحَدٍ سِوَى مَن حضر الوَقعةَ يومَ أُحُدٍ، سِوَى جابرِ بنِ عبدِ الله رضي الله عنه فانْتدبَ المسلمون على ما بهِم مِنَ الجِراحِ والإثْخانِ طاعةً لله عزَّ وجلَّ ولِرسولِه صلى الله عليه وسلم. عن عائشةَ رضي الله عنها أنَّها قالت في قولِه تعالى: {الَّذِينَ اسْتَجَابُوا لِلَّهِ وَالرَّسُولِ مِنْ بَعْدِ مَا أَصَابَهُمُ الْقَرْحُ لِلَّذِينَ أَحْسَنُوا مِنْهُمْ وَاتَّقَوْا أَجْرٌ عَظِيمٌ} قالت لِعُروةَ: يا ابنَ أُختي، كان أَبَواكَ منهم: الزُّبيرُ، وأبو بكرٍ، لمَّا أصابَ رسولَ الله صلى الله عليه وسلم ما أصابَ يومَ أُحُدٍ، وانصرف عنه المشركون، خاف أن يَرجِعوا، قال: «مَن يَذهبُ في إثْرِهِم» فانْتدَبَ منهم سبعون رجلًا، قال: كان فيهم أبو بكرٍ، والزُّبيرُ\". قال ابنُ كُثيرٍ عَقِبَ ذِكرِ هذا الحديثِ: (وهذا السِّياقُ غريبٌ جِدًّا، فإنَّ المشهورَ عند أصحابِ المغازي أنَّ الذين خرجوا مع رسولِ الله صلَّى الله عليه وسلَّم إلى حَمراءِ الأسدِ كُلُّ مَن شَهِدَ أُحُدًا، وكانوا سبعمائةٍ، قُتِلَ منهم سبعون، وبَقِيَ الباقون). والظَّاهرُ أنَّه لا تَخالُف بين قولي عائشةَ وأصحابِ المغازي؛ لأنَّ معنى قولِها: فانْتدَبَ لها سبعون. أنَّهم سبَقوا غيرَهُم، ثمَّ تلاحَق الباقون. وموقعُ حمراءِ الأسدِ على بُعْدِ ثمانيةِ أَميالٍ مِنَ المدينةِ."},{"id":72,"title":"سرية عبد الله بن عبد الأسد رضي الله عنه إلى قطن .","date":["العام الهجري :4","الشهر القمري : محرم","العام الميلادي :625"],"text":"كانت سَريَّةُ أبي سَلَمةَ عبدِ الله بنِ عبدِ الأسَدِ، وهو ابنُ عمَّتِه صلَّى اللهُ عليه وسلَّم بَرَّةَ بنتِ عبد المطلب، وأخوه من الرَّضاعةِ، أرضَعَتهما ثُوَيبةُ. وقَطَنٌ: هو جبلٌ، وقيل: ماءٌ مِن مياهِ بني أسَدٍ. وسَبَبُها: أن رجلًا مِن طيِّئٍ اسمُه الوليدُ بن زُهَيرِ بن طَريفٍ قَدِم المدينةَ زائرًا ابنةَ أخيه زَينَبَ، وكانت تَحتَ طُلَيبِ بنِ عُمَيرِ بن وَهبٍ، فأُخبِرَ أنَّ طُليحةَ وسَلَمةَ ابنَي خوَيلِدٍ تَرَكَهما قد سارا في قَومِهِما ومَن أطاعَهما لحَربِ رسولِ اللَّه صلَّى اللهُ عليه وسلَّم، فنَهاهم قَيسُ بن الحارِثِ فعَصَوه؛ فلمَّا بَلَغ ذلك رسولَ اللَّه صلَّى اللهُ عليه وسلَّم دعا أبا سَلَمةَ رضي اللَّه تعالى عنه وقال: \"اخرُج في هذه السَّريَّةِ فقدِ استَعمَلتُكَ عليها\". وعَقَد له لِواءً وقال: \"سِر حتَّى تَرِدَ أرضَ بَني أسَدِ بنِ خُزَيمةَ، فأغِرْ عليهم قبلَ أن يَتلاقَى عليك جُموعُهم\". وأوصاه بتقوى اللَّه تعالى وبمَن معه من المسلمين خيرًا.فخَرَج معه في تلك السَّريَّةِ خمسون ومئةُ رجلٍ، ومعه الرَّجلُ الطَّائيُّ دَليلًا، فأسرَعَ السَّيرَ وعَدَل بهم عن سَيفِ الطَّريقِ، وسار بهم ليلًا ونهارًا، فسَبَقوا الأخبارَ وانتَهَوا إلى ذي قَطَنٍ -ماءٍ من مياهِ بني أسَدٍ وهو الذي كان عليه جَمعُهم-، فأغاروا على سَرحٍ لهم، وأسَروا ثلاثةً من الرُّعاةِ وأفلَتَ سائِرُهم، فجاؤوا جَمْعَهم فأخبَروهم الخَبَرَ وحَذَّروهم جَمْعَ أبي سَلَمةَ، وكثَّروه عندهم، فتَفرَّق الجمعُ في كُلِّ وَجهٍ، ووَرَدَ أبو سَلَمةَ الماءَ، فوَجَد الجَمْعَ قد تَفرَّق. فعَسكَرَ وفرَّق أصحابَه في طَلَبِ النَّعَمِ والشَّاءِ؛ فجَعَلهم ثلاثَ فِرَقٍ: فِرقةٌ أقامت معه، وفِرقَتان أغارَتا في ناحيَتينِ شتَّى، وأوعَزَ إليهما ألا يُمعِنوا في الطلب، وألَّا يَبيتوا إلَّا عنده إن سَلِموا، وأمَرَهم ألَّا يَفتَرِقوا، واستَعمَل على كلِّ فِرقةٍ عامِلًا منهم فآبوا إليه جَميعًا سالِمين قد أصابوا إبِلًا وشاءً، ولم يَلْقَوا أحدًا، فانحَدَر أبو سَلَمةَ بذلك كُلِّه راجعًا إلى المدينةِ ورَجَع معه الطَّائيُّ.فلمَّا ساروا ليلةً قسَّمَ أبو سَلَمةَ الغنائِمَ، وأخرَجَ صَفيَّ رسول اللَّه صلَّى اللهُ عليه وسلَّم عبدًا وأخرَجَ الخُمُسَ وأعطَى الطائيَّ الدليلَ رِضاهُ من المَغنَمِ، ثم قَسَّم ما بَقي بين أصحابِه فأصاب كلُّ إنسانٍ سبعةَ أبعِرةٍ، وقَدِم بذلك إلى المدينةِ ولم يَلْقَ كَيدًا."},{"id":73,"title":"سرية عبد الله بن أنيس الجهني إلى سفيان بن خالد ببطن عُرْنة .","date":["العام الهجري :4","الشهر القمري : محرم","العام الميلادي :625"],"text":"خَرَج عبدُ اللَّه بنُ أُنيسٍ رَضي اللهُ عنه من المدينةِ يومَ الإثنَينِ لخمسٍ خَلَونَ من المُحرَّمِ على رأس خمسةٍ وثلاثين شهرًا من مُهاجَرِ رسولِ اللَّه صلَّى اللهُ عليه وسلَّم، وبَلَغَ رسولَ اللَّه صلَّى اللهُ عليه وسلَّم أنَّ سُفيانَ بنَ خالِدِ بن نُبَيحٍ الهُذليَّ ثم اللِّحيانيَّ -وكان يَنزِل عُرْنةَ وما والاها في أُناسٍ من قومِه وغيرِهم- يُريد أن يَجمَعَ الجُموعَ إلى رسولِ اللَّه صلَّى اللهُ عليه وسلَّم فضَوَى إليه بَشَرٌ كثيرٌ من أفناءِ الناسِ. قال عبدُ اللَّه بنُ أُنيسٍ رضي اللَّه تعالى عنه: دَعاني رسولُ اللَّه صلَّى اللهُ عليه وسلَّم فقال: \"إنَّه بَلَغني أنَّ سفيانَ بنَ خالدِ بنِ نُبَيحٍ يَجمَع لي الناسَ ليَغزوَني وهو بنَخلةَ أو بعُرْنةَ فأْتِه فاقْتُلْه\". فقلتُ: يا رسول اللَّه، صِفْهُ لي حتى أعرِفَه. فقال: \"آيةُ ما بَينَك وبَينَه أنَّك إذا رَأيتَه هِبتَه وفَرِقْتَ منه، ووَجَدْتَ له قُشَعْريرةً، وذَكَرْتَ الشَّيطانَ\". قال عبد اللَّه: كنتُ لا أهابُ الرِّجالَ، فقلت: يا رسول اللَّه، ما فَرِقتُ من شيءٍ قطُّ. فقال: \"بَلَى؛ آيةُ ما بَينَك وبَينَه ذلك: أن تَجِدَ له قُشَعْريرةً إذا رَأيتَه\". قال: واستَأذَنتُ رسولَ اللَّه صلَّى اللهُ عليه وسلَّم أن أقولَ. فقال: \"قُلْ ما بَدا لَكَ\". وقال: \"انتَسِبْ لخُزاعةَ\". فأخَذتُ سَيفي ولم أزِدْ عليه وخرجتُ أعتَزي لخُزاعةَ حتى إذا كنتُ ببَطنِ عُرْنةَ لَقيتُه يمشي ووراءه الأحابيشُ. فلمَّا رَأيتُه هِبتُه وعَرَفتُه بالنَّعتِ الذي نَعَت لي رسولُ اللَّه صلَّى اللهُ عليه وسلَّم. فقلتُ: صَدَقَ اللَّهُ ورسولُه، وقد دخل وقتُ العَصرِ حين رَأيتُه، فصَلَّيتُ وأنا أمشي أُومي برَأسي إيماءً. فلمَّا دَنَوتُ منه قال: \"مَنِ الرَّجلُ؟\". فقلتُ: \"رجلٌ من خُزاعةَ سَمِعتُ بجَمعِكَ لمُحمَّدٍ فجِئتُكَ لأكونَ مَعَك عليه\". قال: \"أجلْ؛ إنِّي لَفي الجَمعِ له\". فمَشَيتُ معه وحدَّثتُه فاستَحلَى حديثي وأنشَدتُه وقلتُ: \"عَجَبًا لِمَا أحدَثَ مُحمَّدٌ مِن هذا الدِّينِ المُحدَثِ، فارَقَ الآباءَ وسَفَّه أحلامَهم\". قال: \"لم ألْقَ أحَدًا يُشبِهُني ولا يُحسِنُ قِتالَه\". وهو يتوكَّأُ على عصًا يَهُدُّ الأرضَ، حتى انتَهَى إلى خِبائِه وتفرَّق عنه أصحابُه إلى منازِلَ قَريبةٍ منه، وهم يُطيفون به. فقال: هَلُمَّ يا أخا خُزاعةَ. فدَنَوتُ منه. فقال: اجلِسْ. فجَلَستُ معه حتى إذا هَدَأ الناسُ ونامَ اغتَرَرْتُه. وفي أكثرِ الرِّواياتِ أنه قال: فمَشَيتُ معه حتَّى إذا أمكَنني حَمَلتُ عليه السَّيفَ فقَتَلتُه وأخذتُ رأسَه. ثم أقبلتُ فصَعِدتُ جَبَلًا، فدَخَلتُ غارًا وأقبَلَ الطلبُ من الخيلِ والرجالِ تَمعَجُ في كلِّ وجهٍ وأنا مُكتَمِنٌ في الغارِ، وأقبل رجلٌ معه إداوَتُه ونعلُه في يدِهِ وكنتُ خائفًا، فوضع إداوَتَه ونعلَه وجلس يَبولُ قَريبًا من فَمِ الغارِ، ثم قال لأصحابِه: ليس في الغارِ أحدٌ، فانصَرَفوا راجِعين، وخرجتُ إلى الإداوةِ فشَرِبتُ ما فيها وأخذتُ النَّعلَين فلَبِستُهما. فكنتُ أسير الليلَ وأكمُنُ النهارَ حتى جِئتُ المدينة، فوَجَدتُ رسولَ اللَّه صلَّى اللهُ عليه وسلَّم في المسجد، فلمَّا رآني قال: \"أفلَحَ الوَجهُ\". فقلت: وأفلَحَ وَجهُكَ يا رسول اللَّه\". فوَضَعتُ الرَّأسَ بين يَدَيه وأخبَرتُه خَبَري، فدَفَع إليَّ عصًا وقال: \"تَخَصَّرْ بِها في الجَنَّةِ؛ فإنَّ المُتخَصِّرين في الجَنَّةِ قَليلٌ\".فكانتِ العصا عند عبدِ اللَّه بن أُنَيسٍ حتى إذا حضَرَته الوفاةُ أوصى أهلَه أن يُدرِجوا العصا في أكفانِه. ففَعَلوا ذلك. قال ابنُ عُقبةَ: \"فيَزعُمون أنَّ رسولَ اللَّه صلَّى اللهُ عليه وسلَّم أخبَرَ بقتلِ عبدِ اللَّه بنِ أُنيسٍ سُفيانَ بنَ خالِدٍ قبلَ قُدومِ عبدِ اللَّه بنِ أُنَيسٍ رضي اللَّه تعالى عنه\"."},{"id":74,"title":"سرية يَوم الرَّجيعِ .","date":["العام الهجري :4","الشهر القمري : صفر","العام الميلادي :625"],"text":"عن أبي هُريرةَ رضي الله عنه قال: «بعَث رسولُ الله صلى الله عليه وسلم عشرةَ رَهْطٍ سَرِيَّةً عينًا، وأَمَّرَ عليهم عاصمَ بنَ ثابتٍ الأَنصاريَّ، جَدَّ عاصمِ بنِ عُمَرَ بنِ الخطاَّبِ، فانطلقوا حتَّى إذا كانوا بالهَدَأَةِ، وهو بين عُسْفانَ ومكَّةَ، ذُكِروا لِحَيٍّ مِن هُذيلٍ يُقالُ لهم: بنو لَحْيانَ، فنَفَروا لهم قريبًا مِن مائتي رجلٍ كُلُّهم رامٍ، فاقْتَصُّوا آثارَهُم حتَّى وجدوا مَأكلَهُم تمرًا تَزوَّدوهُ مِنَ المدينةِ، فقالوا: هذا تمرُ يَثْرِبَ. فاقْتَصُّوا آثارَهُم، فلمَّا رآهُم عاصمٌ وأصحابُه لَجَئُوا إلى فَدْفَدٍ وأحاط بهم القومُ، فقالوا لهم: انزلوا وأَعْطونا بِأَيديكُم، ولكم العهدُ والميثاقُ، ولا نقتُل منكم أحدًا، قال عاصمُ بنُ ثابتٍ أَميرُ السَّرِيَّةِ: أمَّا أنا فَوَالله لا أنزِلُ اليومَ في ذِمَّةِ كافرٍ، اللَّهمَّ أَخبِرْ عَنَّا نَبِيَّكَ، فرَمَوْهُم بالنَّبْلِ فقَتلوا عاصمًا في سَبعةٍ، فنزل إليهِم ثلاثةُ رَهْطٍ بالعهدِ والميثاقِ، منهم خُبَيْبٌ الأَنصاريُّ، وابنُ دَثِنَةَ، ورجلٌ آخرُ، فلمَّا اسْتمكَنوا منهم أطلقوا أَوتارَ قِسِيِّهِم فأَوثَقوهُم، فقال الرجلُ الثَّالثُ: هذا أوَّلُ الغَدْرِ، والله لا أَصحَبُكُم، إنَّ لي في هؤلاءِ لِأُسْوَةً يُريدُ القَتلى، فجَرَّروهُ وعالَجوهُ على أن يَصحبَهُم فأَبى فقَتلوهُ، فانطلقوا بخُبَيْبٍ، وابنِ دَثِنَةَ حتَّى باعوهُما بمكَّةَ بعدَ وَقعةِ بدرٍ، فابتاع خُبَيْبًا بنو الحارثِ بنِ عامرِ بنِ نَوفلِ بنِ عبدِ مَنافٍ، وكان خُبَيْبٌ هو قَتَلَ الحارثَ بنَ عامرٍ يومَ بدرٍ، فلَبِثَ خُبَيْبٌ عندهم أَسيرًا، فأخبرني عُبيدُ الله بنُ عِياضٍ، أنَّ بنتَ الحارثِ أخبرتْهُ: أنَّهم حين اجتمعوا اسْتَعار منها موسى يَسْتَحِدُّ بها، فأعارتْهُ، فأخذ ابنًا لي وأنا غافلةٌ حين أتاهُ قالت: فوجدتُه مُجْلِسَهُ على فَخِذِهِ والموسى بيدِه، ففَزِعْتُ فَزْعَةً عرَفها خُبَيْبٌ في وجهي، فقال: تَخْشَيْنَ أن أَقتُلَهُ؟ ما كنتُ لأَفعلَ ذلك. والله ما رأيتُ أَسيرًا قَطُّ خيرًا مِن خُبَيْبٍ، والله لقد وجدتُهُ يومًا يأكلُ مِن قِطْفِ عِنَبٍ في يدِه، وإنَّه لَمُوثَقٌ في الحديدِ، وما بمكَّةَ مِن ثَمَرٍ، وكانت تقولُ: إنَّه لَرزقٌ مِنَ الله رَزَقَهُ خُبَيْبًا، فلمَّا خرجوا مِنَ الحَرَمِ لِيقتُلوه في الحِلِّ، قال لهم خُبَيْبٌ: ذَروني أَركعُ رَكعتينِ. فتركوه، فركَع رَكعتينِ، ثمَّ قال: لولا أن تَظنُّوا أنَّ ما بي جَزَعٌ لَطَوَّلْتُها، اللَّهمَّ أَحْصِهم عددًا، ثمَّ ارْتَجز يقولُه: لا أُبالي حين أُقتَلُ مُسلمًا... على أيِّ شِقٍّ كان لله مَصرعي، وذلك في ذاتِ الإلهِ وإن يشأْ... يُبارِك على أَوصالِ شِلْوٍ مُمَزَّعِ. فقتَله ابنُ الحارثِ، فكان خُبَيْبٌ هو سَنَّ الرَّكعتينِ لِكُلِّ امرئٍ مُسلمٍ قُتِلَ صَبرًا، فاستجاب الله لعاصمِ بنِ ثابتٍ يومَ أُصيبَ، فأَخبرَ النَّبيُّ صلى الله عليه وسلم أصحابَه خبرَهُم، وما أُصيبوا، وبعَث ناسٌ مِن كُفَّارِ قُريشٍ إلى عاصمٍ حين حُدِّثوا أنَّه قُتِلَ، لِيُؤْتَوْا بشيءٍ منه يُعرفُ، وكان قد قتَل رجلًا مِن عُظمائهِم يومَ بدرٍ، فبُعِثَ على عاصمٍ مِثْلُ الظُّلَّةِ مِنَ الدَّبْرِ، فحَمَتْهُ مِن رسولهِم، فلم يَقدِروا على أن يَقطعَ مِن لَحمِه شيئًا."},{"id":75,"title":"سرية بِئر مَعونةَ .","date":["العام الهجري :4","الشهر القمري : صفر","العام الميلادي :625"],"text":"عن أنسِ بنِ مالكٍ رضي الله عنه قال:  أنَّ رِعْلًا، وذَكْوانَ، وعُصَيَّةَ، وبني لَحْيانَ، اسْتمَدُّوا رسولَ الله صلى الله عليه وسلم على عَدُوٍّ، فأَمدَّهُم بسبعين مِنَ الأنصارِ، كُنَّا نُسمِّيهم القُرَّاءَ في زمانِهم، كانوا يَحْتَطِبون بالنَّهارِ، ويُصلُّون باللَّيلِ، حتَّى كانوا ببِئرِ مَعونةَ قَتلوهُم وغَدَروا بهم، فبلَغ النَّبيَّ صلى الله عليه وسلم فقَنَتَ شهرًا يَدعو في الصُّبحِ على أَحياءٍ مِن أَحياءِ العربِ، على رِعْلٍ، وذَكْوانَ، وعُصَيَّةَ، وبني لَحْيانَ. قال أنسٌ: فقَرأنا فيهم قُرآنًا، ثمَّ إنَّ ذلك رُفِعَ: بَلِّغوا عَنَّا قَومَنا أَنَّا لَقِينا رَبَّنا فَرَضِيَ عَنَّا وأَرضانا. وجاء في ِروايةٍ عند البُخاريِّ: أنَّ أولئك السَّبعين مِنَ الأنصارِ قُتِلوا ببِئرِ مَعونةَ. وعن أنسِ بنِ مالكٍ، قال: جاء ناسٌ إلى النَّبيِّ صلى الله عليه وسلم، فقالوا: أَنِ ابْعَثْ معنا رجالًا يُعلِّمونا القُرآنَ والسُّنَّةَ، فبعَث إليهم سبعين رجلًا مِنَ الأنصارِ، يُقالُ لهم: القُرَّاءُ، فيهم خالي حَرامٌ، يَقرءون القُرآنَ، ويَتدارَسون باللَّيلِ يَتعلَّمون، وكانوا بالنَّهارِ يَجيئون بالماءِ فيضَعونَهُ في المسجدِ، ويَحْتَطِبون فَيَبيعونَهُ ويَشْتَرون به الطَّعامَ لأَهلِ الصُّفَّةِ وللفُقراءِ، فبعثَهُم النَّبيُّ صلَّى الله عليه وسلَّم إليهم، فعَرَضوا لهم فقَتَلوهُم قبلَ أن يَبلُغوا المكانَ، فقالوا: اللَّهمَّ، بَلِّغْ عَنَّا نَبِيَّنا أَنَّا قد لَقِيناك فَرَضينا عنك، ورَضيتَ عَنَّا. قال: وأَتى رجلٌ حَرامًا -خالَ أنسٍ- مِن خَلفِه، فطَعنَهُ برُمحٍ حتَّى أَنْفَذَهُ، فقال حَرامٌ: فُزْتُ ورَبِّ الكعبةِ. فقال رسولُ الله صلى الله عليه وسلم لأصحابِه: إنَّ إخوانَكُم قد قُتِلوا، وإنَّهم قالوا: اللَّهمَّ بَلِّغْ عَنَّا نَبِيَّنا أَنَّا قد لَقِيناك فَرَضينا عنك، ورَضيت عَنَّا."},{"id":76,"title":"غَزوةُ بني النَّضيرِ .","date":["العام الهجري :4","الشهر القمري : ربيع الأول","العام الميلادي :625"],"text":"كان سببُها أنَّه لمَّا قُتِلَ أصحابُ بِئرِ مَعونةَ مِن أصحابِ رسولِ الله صلى الله عليه وسلم، وكانوا سبعين، وأَفْلَتَ منهم عَمرُو بنُ أُميَّةَ الضَّمريُّ، فلمَّا كان في أَثناءِ الطَّريقِ راجعًا إلى المدينةِ قَتَلَ رجُلينِ مِن بني عامرٍ، وكان معهما عهدٌ مِن رسولِ الله صلى الله عليه وسلم وأَمانٌ لم يَعلَمْ به عَمرٌو، فلمَّا رجَع أَخبرَ رسولَ الله صلى الله عليه وسلم... فخرج رسولُ الله صلى الله عليه وسلم إلى بني النَّضيرِ يَستَعينُهم في دِيَةِ ذَيْنِكَ الرَّجلينِ، وكانت مَنازِلُ بني النَّضيرِ ظاهِرَ المدينةِ على أَميالٍ منها شَرقِيَّها. قال محمَّدُ بنُ إسحاقَ بنِ يَسارٍ في كتابِه السِّيرة: ثمَّ خرج رسولُ الله إلى بني النَّضيرِ، يَستَعينُهم في دِيَةِ ذَيْنِكَ القَتيلَينِ مِن بني عامرٍ، اللَّذينِ قَتَلَ عَمرُو بنُ أُميَّةَ الضَّمريُّ؛ للجِوارِ الذي كان رسولُ الله صلى الله عليه وسلم عقَد لهما.... فلمَّا أتاهُم رسولُ الله صلى الله عليه وسلم يَستَعينُهم في دِيَةِ ذَيْنِكَ القَتيلينِ قالوا: نعم، يا أبا القاسمِ، نُعينُك على ما أَحببتَ، ممَّا اسْتعَنتَ بِنا عليه. ثمَّ خلا بعضُهم ببعضٍ فقالوا: إنَّكم لن تَجِدوا الرَّجلَ على مِثلِ حالِه هذه -ورسولُ الله صلى الله عليه وسلم إلى جَنبِ جِدارٍ مِن بُيوتِهم- فَمَن رجلٌ يَعلو على هذا البيتِ، فيُلقي عليه صَخرةً، فيُريحُنا منه؟ فانْتدَب لذلك عَمرُو بنُ جَحَّاشِ بنِ كعبٍ أحدُهم، فقال: أنا لذلك. فصعَدَ ليُلقِيَ عليه صَخرةً كما قال، ورسولُ الله صلى الله عليه وسلم في نَفَرٍ مِن أصحابِه، فيهم أبو بكرٍ وعُمَرُ وعليٌّ رضي الله عنهم. فأتى رسولَ الله صلى الله عليه وسلم الخبرُ مِن السَّماءِ بما أراد القومُ، فقام وخرج راجعًا إلى المدينةِ، فلمَّا اسْتَلْبَثَ النَّبيَّ صلى الله عليه وسلم أصحابُه قاموا في طَلبِه فلَقوا رجلًا مُقبِلًا مِنَ المدينةِ، فسألوهُ عنه، فقال: رأيتُه داخلًا المدينةَ. فأقبل أصحابُ رسولِ الله صلى الله عليه وسلم حتَّى انتهوا إليه، فأخبرَهُم الخبرَ بما كانت يَهودُ أرادت مِنَ الغَدْرِ به، وأمَر رسولُ الله صلى الله عليه وسلم بالتَّهَيُّؤِ لِحربِهم والمَسيرِ إليهم. ثمَّ سار حتَّى نزل بهم فتَحصَّنوا منه في الحُصون، فأمَر رسولُ الله صلى الله عليه وسلم بقطعِ النَّخلِ والتَّحريقِ فيها. فنادوهُ: أن يا محمَّدُ، قد كنتَ تَنهى عن الفسادِ وتَعيبُه على مَن صنَعه، فما بالُ قطعِ النَّخلِ وتَحريقِها؟! وقد كان رَهْطٌ مِن بني عَوفِ بنِ الخَزرجِ، منهم عبدُ الله بنُ أُبَيٍّ بن ابنُ سَلولَ، ووَديعَةُ، ومالكُ بنُ أبي قَوْقَلٍ، وسُوَيدٌ، وداعِسٌ، قد بعثوا إلى بني النَّضيرِ: أنِ اثْبُتوا وتَمَنَّعوا فإنَّا لن نُسْلِمَكُم، إن قوتِلْتُم قاتلنا معكم، وإن أُخرِجتُم خَرَجنا معكم فتَرَبَّصوا ذلك مِن نَصرِهم، فلم يفعلوا، وقذف الله في قلوبهم الرُّعبَ، فسألوا رسولَ الله صلى الله عليه وسلم أن يُجْلِيَهم ويَكُفَّ عن دِمائهِم، على أنَّ لهم ما حمَلتِ الإبلُ مِن أموالهِم، إلَّا الحَلَقَةَ، ففعَل، فاحتملوا مِن أموالهم ما اسْتقلَّتْ به الإبلُ، فكان الرَّجلُ منهم يَهدِم بيتَه عن نِجافِ بابِه، فيضَعُه على ظهرِ بَعيرهِ فينطلِقُ به، فخرجوا إلى خيبر، ومنهم مَن سار إلى الشَّامِ، وخَلَّوْا الأموالَ إلى رسولِ الله صلى الله عليه وسلم، فكانت لِرسولِ الله خاصَّةً)، وقد ثبَت في البُخاريِّ أنَّ النَّبيِّ صلى الله عليه وسلم قد أَجلى بني النَّضيرِ. وفيهم نزلت سورةُ الحَشْرِ."},{"id":77,"title":"غزوة بدر الموعد (بدر الثانية) .","date":["العام الهجري :4","الشهر القمري : شعبان","العام الميلادي :626"],"text":"تُسمَّى هذه الغزوةُ ببدرٍ الآخِرةِ، وبَدرٍ الصُّغرى، وبدرٍ الثانيةِ، وبدرٍ المَوعِدِ؛ للمواعَدةِ عليها مع أبي سُفيانَ بنِ حربٍ يومَ أُحدٍ؛ وذلك أن أبا سفيان لمَّا انصَرَف منِ أُحدٍ نادى: \"إنَّ مَوعِدَكم بَدرٌ، العامَ المُقبِلَ\". فلمَّا كانتِ السَّنةُ الرابِعةُ من الهِجرةِ، خَرَج الرسولُ صلَّى اللهُ عليه وسلَّم بألفٍ وخَمسِمئةٍ من أصحابِه إلى بدرٍ ومعه عَشَرةُ أفراسٍ، وحَمَل لِواءَه عليُّ بن أبي طالِبٍ رَضي اللهُ عنه، وذلك في انتِظارِ قُدومِ قُرَيشٍ حَسَبَ المَوعِدِ المُحدَّدِ منذ وَقعةِ أُحُدٍ مع أبي سُفيانَ زعيمِ قُريشٍ. وانتَظَرَ المسلمون ثمانيةَ أيَّامٍ دونَ أن تَقدَمَ قُرَيشٌ، وكان أبو سُفيانَ قد خَرَج بألفينِ ومعهم خمسون فرسًا، فلمَّا وَصَلوا مرَّ الظَّهرانِ على أربعينَ كَيلًا مِن مكةَ عادوا بحُجَّةِ أنَّ العامَ عامُ جَدبٍ، وكان لإخلافِهِمُ المَوعِدَ أثرٌ في تقويةِ مكانةِ المسلمين وإعادةِ هَيبَتِهم. وقد واصَلَ المسلمون إرسالَ سَراياهم إلى الأنحاءِ المُختَلِفةِ من نَجدٍ والحِجازِ لتَأديبِ الأعرابِ، فقاد أبو عُبيدةَ بنُ الجرَّاحِ سَريَّةً إلى طيِّئٍ وأسَدٍ بنَجدٍ، فتَفَرَّقوا في الجبالِ دونَ أن يقعَ قتالٌ.وقاد الرسولُ صلَّى اللهُ عليه وسلَّم جَيشًا من ألفِ مُقاتِلٍ في شهرِ ربيعٍ الأوَّلِ من سنةِ خَمسٍ باتِّجاهِ دُومةِ الجَندَلِ، وقد بَلَغه وُجودُ تَجمُّعٍ للمُشرِكين بها، ولكِنَّ الجَمعَ تفرَّق عندما عَلِموا بقُدومِ المسلمين الذين أقاموا أيَّامًا في المِنطَقةِ بَثُّوا خِلالَها السَّرايا، فلم يَلقَوا مُقاومةً ورَجَعوا إلى المدينةِ بعد أن وادَعَ في العَودةِ عُيينةَ بنَ حِصنٍ الفَزاريَّ."},{"id":78,"title":"حادِثةُ الإفْكِ .","date":["العام الهجري :5","العام الميلادي :626"],"text":"لمَّا خرَج النَّبيُّ صلى الله عليه وسلم إلى بني المُصطلِقِ لِغَزوِهِم أَقرعَ بين نِسائِه مَن يَخرُج معه، فكانت القُرعَةُ على عائشةَ الطَّاهرةِ رضي الله عنها وأَرضاها، وفي طريقِ العَودةِ كانت تُحمَلُ على هَودجٍ، فقدَّرَ الله في ذلك اليومِ أن تكونَ خارجَ هَودَجِها لِتبحثَ عن عِقْدٍ سقَط منها، فلمَّا أرادوا الرَّحيلَ لم يَشعُروا بعدمِ وُجودِها ورَحلوا؛ فقد كانت صَغيرةً خَفيفةَ الوَزنِ، فلمَّا رجعت لم تَرَهُم. قالت عائشةُ رضِي الله عنها: (فتَيَمَّمْتُ مَنزلي الذي كنتُ فيه، وظَننتُ أنَّ القومَ سَيفْقِدوني فيَرجِعون إليَّ، فبينا أنا جالسةٌ في مَنزلي غَلبتْني عَيني فنِمْتُ، وكان صَفوانُ بنُ المُعَطَّلِ السُّلميُّ ثمَّ الذَّكْوانيُّ قد عَرَّسَ مِن وَراءِ الجيشِ فأَدْلَجَ، فأصبحَ عند مَنزلي فرَأى سَوادَ إنسانٍ نائمٍ، فأتاني فعَرفَني حين رآني، وقد كان يَراني قبلَ أن يُضرَبَ الحِجابُ عَليَّ، فاسْتيقَظتُ بِاسْتِرجاعِه حين عَرفَني، فخَمَّرتُ وجهي بِجِلبابي، ووالله ما يُكلِّمُني كَلمةً، ولا سمِعتُ منه كَلمةً غيرَ اسْتِرجاعِه، حتَّى أناخ راحلتَه، فوَطِئَ على يَدِها فرَكِبتُها، فانطلق يَقود بي الرَّاحلةَ، حتَّى أَتينا الجيشَ، بعدما نزلوا مُوغِرين في نَحْرِ الظَّهيرةِ، فهلَك مَن هلَك في شأني، وكان الذي تَولَّى كِبْرَهُ عبدُ الله بنُ أُبَيٍّ بن ابنُ سَلولَ،...) فاتَّهموها مع صَفوانَ وبدَأ هذا الإفكُ المُبينُ يَنتشِرُ في المدينةِ، وبَقِيتْ عائشةُ شهرًا لا تعلمُ شيئًا عن ذلك، حتَّى عَلِمتْ بذلك صَراحةً مِن أمِّ مِسْطَحٍ، وكُلُّ ذلك ولم تَتَبيَّنْ الحقيقةُ، ثمَّ نزلت آياتٌ تُتْلى إلى يومِ القيامةِ مِن قولِه تعالى: {إِنَّ الَّذِينَ جَاءُوا بِالْإِفْكِ عُصْبَةٌ مِنْكُمْ لَا تَحْسَبُوهُ شَرًّا لَكُمْ بَلْ هُوَ خَيْرٌ لَكُمْ} [النور: 11] إلى قوله: {وَلَكِنَّ اللَّهَ يُزَكِّي مَنْ يَشَاءُ وَاللَّهُ سَمِيعٌ عَلِيمٌ} [النور: 21] آياتٌ تُبرِّئُ الطَّاهرةَ المُطَهَّرةَ ممَّا افْتَراهُ المُفتَرون."},{"id":79,"title":"غزوة دومة الجندل .","date":["العام الهجري :5","الشهر القمري : ربيع الأول","العام الميلادي :626"],"text":"كانت غزوةُ دُومةِ الجَندلِ -موضِعٍ على طَرَفِ الشَّامِ بينها وبين دمشقَ خمسَ لَيالٍ، وبينها وبين المدينةِ خمسَ عشرةَ أو سِتَّ عشرةَ لَيلةً- في ربيعٍ الأوَّلِ من السَّنةِ الخامسةِ للهِجرةِ.وسَبَبُها: أنَّ رسولَ الله صلَّى اللهُ عليه وسلَّم بَلَغه أنَّ بدُومةِ الجَندَلِ جَمعًا كثيرًا من القبائِلِ، وأنَّهم يَظلِمون مَن مرَّ بِهِم، ويَنهَبون ما معهم، وأنَّهم يُريدون أن يَدْنوا من المدينةِ لمُهاجَمَتِها؛ فنَدَب رسولُ الله صلَّى اللهُ عليه وسلَّم النَّاسَ، واستَخلَف على المدينةِ سِباعَ بنَ عُرفُطةَ الغِفاريَّ، وخَرَج رسولُ الله صلَّى اللهُ عليه وسلَّم في ألفٍ مِن المسلمين، فكانوا يَسيرون اللَّيلَ، ويَكمُنون -يَستَتِرون- النَّهارَ، ومعه صلَّى اللهُ عليه وسلَّم دليلٌ له من بني عُذْرةَ يقال له: (مَذكورٌ)؛ فلمَّا دَنَوا من دُومةِ الجَندلِ، هَجَموا على ماشيَتِهِم ورُعاتِهم، فأصابوا ما أصابوا منهم، وهَرَب مَن هَرَب في كلِّ وَجهٍ؛ فلمَّا عَلِمَ أهلُ دُومةِ الجَندَلِ تَفرَّقوا، ونَزَل رسولُ الله صلَّى اللهُ عليه وسلَّم بساحَتِهِم فلم يَجِد بها أحدًا؛ فأقام بها أيامًا وبثَّ السَّرايا وفَرَّقَها، فرَجَعَت ولم تُصِب منهم أحدًا، وأُخِذ منهم رجلٌ؛ فسَأله رسولُ الله عنهم، فقال: هَرَبوا حين سَمِعوا أنَّك أخذْتَ نَعَمَهم؛ فعَرَض عليه الإسلامَ فأسلَمَ، ثم رَجَع رسولُ الله صلَّى اللهُ عليه وسلَّم إلى المَدينةِ، ولم يَلْقَ كَيدًا."},{"id":80,"title":"غزوة بني المصطلق (المريسيع) .","date":["العام الهجري :5","الشهر القمري : شعبان","العام الميلادي :627"],"text":"بَلَغ رسولَ الله صلَّى اللهُ عليه وسلَّم أن بني المُصطَلِقِ -وهم بَطنٌ من قَبيلةِ خُزاعةَ الأزديَّةِ اليَمانيَّةِ- يَجمَعون لقِتالِه، وقائِدُهمُ الحارِثُ بن أبي ضِرارٍ؛ فلمَّا سَمِع رسولُ الله صلَّى اللهُ عليه وسلَّم بهم خَرَج إليهم حتَّى لَقيَهم على ماءٍ لهم يُقال له: (المُرَيسيعُ)، ولذلك تُسَمَّى هذه الغَزوةُ أيضًا: بغَزوةِ المُرَيسيعِ. فتَزاحَفَ النَّاسُ واقتَتَلوا، فهَزَمَ اللهُ بني المُصطَلِقِ وقُتِلَ مَن قُتِلَ منهم، ونَفَلَ رسولَ الله صلَّى اللهُ عليه وسلَّم أبناءَهم ونِساءَهم وأموالَهم فأفاءَهم عليه، وكان فيمَن سُبي جُوَيريةُ رَضي اللهُ عنها بنتُ الحارِثِ بنِ أبي ضِرارٍ سيِّدِ بني المُصطَلِقِ، التي تزوَّجَها رسول الله صلَّى اللهُ عليه وسلَّم حين جاءَته تَستَعينُه في كِتابَتِها، وجَعَل صَداقَها رَضي اللهُ عنها أربَعينَ أسيرًا مِن قَومِها، فأعتَقَ النَّاسُ ما بأيديهِم من الأسرَى؛ لمَكانِ جُويريةَ رَضي اللهُ عنها. وأثناءَ الرُّجوعِ من هذه الغَزوةِ تكلَّم أهلُ الإفكِ بما تَكَلَّموا به في حقِّ أُمِّ المؤمنين عائِشةَ رَضي اللهُ عنها، الصِّدِّيقةِ بنتِ الصِّدِّيقِ المُبَرَّأةِ من فَوقِ سَبعِ سمواتٍ. وفيها أيضًا قال ابنُ أبيٍّ ابنُ سَلولَ قَوْلَتَه: \"لَئِن رَجَعنا إلى المَدينةِ ليُخرِجَنَّ الأعَزُّ منها الأذَلَّ!\"، فسَمِعَه زيدُ بن أرقَمَ، ونَزَلت سورةُ \"المنافقون\"."},{"id":81,"title":"غَزوةُ الخَندَقِ (الأَحزابِ) .","date":["العام الهجري :5","الشهر القمري : شوال","العام الميلادي :627"],"text":"كان سببُ هذه الغَزوةِ هو إجلاءُ يَهودِ بني النَّضيرِ مِنَ المدينةِ؛ حيثُ إنَّ الحسدَ والحِقدَ قد تَمكَّنا مِن قُلوبهِم، ممَّا جعَلهم يُضمِرون العَداءَ ويَتَحَيَّنون الفُرصَ للتَّشفِّي ممَّن طَردَهم مِنَ المدينةِ وما حولها. ولمَّا لم يَستطِعْ يَهودُ خَيبرَ وخاصَّةً بني النَّضيرِ مَجابهةَ المسلمين لَجأوا إلى أُسلوبِ المكرِ والتَّحريشِ. وقد ذكَر ابنُ إسحاقَ بِسَندِهِ عن جماعةٍ: أنَّ الذين حَزَّبوا الأحزابَ نفرٌ مِنَ اليَهودِ، وكان منهم: سَلَّامُ بنُ أبي الحُقَيْقِ، وحُيَيُّ بنُ أَخْطَبَ النَّضْريُّ، وكِنانةُ بنُ أبي الحُقَيْقِ النَّضْريُّ، وهَوْذَةُ بنُ قَيسٍ الوائليُّ، وأبو عَمَّارٍ الوائليُّ، في نَفرٍ مِن بني النَّضيرِ، فلمَّا قَدِموا على قُريشٍ، دَعَوْهُم إلى حربِ رسولِ الله صلى الله عليه وسلم وقالوا: إنَّا سَنَكون معكم عليه حتَّى نَسْتَأْصِلَهُ، فقالت لهم قُريشٌ: يا مَعشرَ يَهودَ، إنَّكم أهلُ الكتابِ الأوَّلِ والعِلْمِ بما أصبحنا نَختلِفُ فيه نحن ومحمَّدٌ، أَفَدينُنا خيرٌ أم دينُه، قالوا: بل دينُكم خيرٌ مِن دينِه، وأنتم أَولى بالحقِّ منه !!! واختلف العُلماءُ في زمنِ وُقوعِ هذه الغَزوةِ، فمال البُخاريُّ إلى قولِ موسى بنِ عُقبةَ: إنَّها كانت في شوَّالٍ سنةَ أَربعٍ، بينما ذَهبتْ الكثرةُ الكاثرةُ إلى أنَّها كانت في سنةِ خمسٍ، قال الذَّهبيُّ: وهو المقطوعُ به. وقال ابنُ القَيِّمِ: وهو الأصحُّ. قام النَّبيُّ صلى الله عليه وسلم وأصحابُه رضي الله عنهم بِحَفرِ خَندقٍ في المنطقةِ المكشوفةِ أمامَ الغُزاةِ، وذكَر ابنُ عُقبةَ: أنَّ حَفرَ الخندقِ استغرقَ قريبًا مِن عِشرين ليلةً. وعن أنسٍ رضي الله عنه قال: خرَج رسولُ الله صلى الله عليه وسلم إلى الخندقِ، فإذا المهاجرون والأنصارُ يَحفُرون في غَداةٍ باردةٍ، فلم يكنْ لهم عَبيدٌ يعملون ذلك لهم، فلمَّا رأى ما بهم مِنَ النَّصَبِ والجوعِ قال: اللَّهمَّ إنَّ العَيْشَ عَيْشَ الآخِرهْ، فاغْفِرْ للأنصارِ والمُهاجِرهْ، فقالوا مُجِيبينَ له: نحن الذين بايَعوا محمَّدًا... على الجِهادِ ما بَقِينا أبدًا. وعن البَراءِ رضي الله عنه قال: لمَّا كان يومُ الأحزابِ، وخَنْدَقَ رسولُ الله صلى الله عليه وسلم، رأيتُه يَنقُلُ مِن تُرابِ الخَندقِ، حتَّى وارى عَنِّي الغُبارُ جِلدةَ بَطنِه، وكان كَثيرَ الشَّعرِ، فسَمِعتُه يَرتجِزُ بِكلماتِ ابنِ رَواحةَ، وهو يَنقُلُ مِنَ التُّرابِ يقولُ: اللَّهمَّ لولا أنت ما اهْتَدَيْنا... ولا تَصدَّقْنا ولا صَلَّيْنا، فأَنْزِلَنْ سَكينةً علينا... وثَبِّتِ الأَقدامَ إن لاقَيْنا، إنَّ الأُلى قد بَغَوْا علينا... وإن أرادوا فِتنةً أَبَيْنا. قال: ثمَّ يَمُدُّ صوتَهُ بآخِرها. وعن عائشةَ رضي الله عنها أنَّها قالت في قوله تعالى: {إِذْ جَاؤُوكُمْ مِنْ فَوْقِكُمْ وَمِنْ أَسْفَلَ مِنْكُمْ وَإِذْ زَاغَتِ الأَبْصَارُ} كان ذاك يومَ الخَندقِ. وعندما وصلتِ الأَحزابُ المدينةَ فوجِئوا بوُجودِ الخَندقِ، فقاموا بِعدَّةِ مُحاولاتٍ لاقْتِحامهِ، ولكنَّهم فَشلوا. واسْتمرَّ الحِصارُ أربعًا وعِشرين ليلةً. وثَقُلَ الأمرُ على قُريشٍ بسببِ الرِّيحِ التي أَكْفَأَتْ قُدورَهُم وخِيامَهُم، كما قام المسلمون بالتَّخْذيلِ بين اليَهودِ والمشركين، فأُرْغِموا على الرَّحيلِ وهَزمهُم الله تعالى، وكف شَرَّهُم عنِ المدينةِ."},{"id":82,"title":"نُزولُ آيةِ الحِجابِ .","date":["العام الهجري :5","الشهر القمري : ذي القعدة","العام الميلادي :627"],"text":"وكان سببُ نُزولِها أنَّ عُمَرَ رضي الله عنه كان يَقولُ لِرسولِ الله صلى الله عليه وسلم: لو أَمرتَ نِساءَك أن يَحْتَجِبْنَ، فإنَّه يُكلِّمُهُنَّ البَرُّ والفاجرُ، فنزَل قولُه تعالى: {يَا أَيُّهَا الَّذِينَ آمَنُوا لا تَدْخُلُوا بُيُوتَ النَّبِيِّ إِلَّا أَن يُؤْذَنَ لَكُمْ... إلى قوله تعالى:..وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِن وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ\"."},{"id":83,"title":"غَزوةُ يَهودِ بني قُرَيْظَةَ .","date":["العام الهجري :5","الشهر القمري : ذي القعدة","العام الميلادي :627"],"text":"وقعَت هذه الغَزوةُ بعدَ غَزوةِ الأحزابِ مُباشرةً، وكان سببُها نقضَ بني قُريظةَ العهدَ الذي بينهم وبين النَّبيِّ صلى الله عليه وسلم بتَحريضٍ مِن حُيَيِّ بنِ أَخطبَ النَّضْريِّ. وكان النَّبيُّ صلَّى الله عليه وسلَّم قد أَرسلَ الزُّبيرَ لِمعرفةِ نِيَّتِهم، ثمَّ أَتبَعهُ بالسَّعدَيْنِ –سَعدِ بنِ عُبادةَ وسَعدِ بنِ مُعاذٍ- وابنِ رَواحةَ، وخَوَّاتِ بنِ جُبيرٍ لِذاتِ الهدفِ ليَتأكَّدَ مِن غَدرِهم. وقد أمَر الله تعالى نَبِيَّهُ صلى الله عليه وسلم، بقِتالِهم بعدَ عَودتِه مِنَ الخَندقِ ووَضْعِهِ السِّلاحَ، فأَوْصى عليه الصَّلاةُ والسَّلامُ أصحابَهُ أن يَتوجَّهوا إلى بني قُريظةَ، وقال لهم: (لا يُصَلِّيَنَّ أَحدُكم العَصرَ إلَّا في بني قُريظةَ). كما في رِوايةِ البُخاريِّ، أو (الظُّهرَ) كما في رِوايةِ مُسلمٍ. فضرَب الرَّسولُ صلى الله عليه وسلم الحِصارَ على بني قُريظةَ لمُدَّةِ خمسٍ وعِشرين ليلةً على الأرجحِ، حتَّى نزلوا على حُكمِ الرَّسولِ صلى الله عليه وسلم، فأَحَبَّ أن يَكِلَ الحُكمَ عليهم إلى واحدٍ مِن رُؤساءِ الأَوْسِ؛ لأنَّهم كانوا حُلفاءَ بني قُريظةَ، فجعل الحُكمَ فيهم إلى سعدِ بنِ مُعاذٍ، فلمَّا دَنا مِنَ المسلمين قال الرَّسولُ صلى الله عليه وسلم للأنصارِ: قوموا إلى سَيِّدِكُم -أو خَيرِكُم- ثمَّ قال: إنَّ هؤلاءِ نزلوا على حُكمِك. قال -أي سعدُ بنُ مُعاذٍ-: تُقْتَلُ مُقاتِلَتُهم، وتُسْبى ذَرارِيُّهُم، وتُقْسَمُ أَموالُهم. فقال له النَّبيُّ صلى الله عليه وسلم: قَضيتَ بحُكمِ الله تعالى. ونَفَّذَ الرَّسولُ صلى الله عليه وسلم هذا الحُكمَ فيهم، وكانوا أَربعمائةٍ على الأرجحِ. ولم يَنْجُ إلَّا بعضُهم، ثمَّ قَسَّمَ الرَّسولُ صلى الله عليه وسلم أَموالَهم وذَراريَّهُم بين المسلمين."},{"id":84,"title":"مَقتلُ سَلَّامِ بنِ أبي الحُقَيْقِ اليَهوديِّ .","date":["العام الهجري :6","العام الميلادي :627"],"text":"هو أبو رافعٍ سَلَّامُ بنُ أبي الحُقَيْقِ شاعرٌ وفارسٌ يَهوديٌّ، أحدُ الذين حَزَّبوا الأحزابَ ضِدَ المسلمين في غزوةِ الأحزابِ، وأَعانَهُم بالمُؤَنِ والأَموالِ الكَثيرةِ، ولمَّا قتَل الله كعبَ بنَ الأشرفِ على يدِ رجالٍ مِنَ الأَوسِ بعدَ وقعةَ بدرٍ كان أبو رافعٍ سَلَّامُ بنُ أبي الحُقيقِ ممَّن أَلَّبَ الأحزابَ على رسولِ الله صلى الله عليه وسلم ولم يُقتلْ مع بني قُريظةَ كما قُتِلَ صاحبُه حُيَيُّ بنُ أَخطبِ، رَغِبتِ الخَزرجُ في قتلِه طلبًا لِمُساواةِ الأَوسِ في الأَجرِ. وكان الله سُبحانه قد جعَل هذين الحَيَّيْنِ يَتَصاولانِ بين يدي رسولِ الله صلى الله عليه وسلم في الخيراتِ، فاسْتأذَنوا رسولَ الله في قتلِه فأَذِن لهم، فعنِ البَراءِ بنِ عازبٍ قال: بعَث رسولُ الله صلى الله عليه وسلم إلى أبي رافعٍ اليَهوديِّ رِجالًا مِنَ الأنصارِ، فأَمَّرَ عليهم عبدَ الله بنَ عَتيكٍ، وكان أبو رافعٍ يُؤذي رسولَ الله صلى الله عليه وسلم ويُعينُ عليه، وكان في حِصنٍ له بأرضِ الحجازِ، فلمَّا دَنَوْا منه وقد غَربتِ الشَّمسُ، وراح النَّاسُ بِسَرْحِهِم، فقال عبدُ الله لأصحابِه: اجْلِسوا مَكانَكُم، فإنِّي مُنطلِقٌ، ومُتَلَطِّفٌ للبَوَّابِ، لَعلِّي أن أَدخُلَ، فأقبل حتَّى دَنا مِنَ البابِ، ثمَّ تَقَنَّعَ بِثَوبهِ كأنَّه يَقْضي حاجةً، وقد دخل النَّاسُ، فهتَف به البَوَّابُ: يا عبدَ الله، إن كُنتَ تُريدُ أن تَدخُلَ فادخُلْ، فإنِّي أُريدُ أن أُغلقَ البابَ، فدخلتُ فكَمَنْتُ، فلمَّا دخَل النَّاسُ أَغلقَ البابَ، ثمَّ عَلَّقَ الأَغاليقَ على وَتَدٍ، قال: فقمتُ إلى الأقاليدِ فأَخذتُها، ففتحتُ البابَ، وكان أبو رافعٍ يُسْمَرُ عنده، وكان في عَلالِيَّ له، فلمَّا ذهَب عنه أهلُ سَمَرِهِ صَعدتُ إليه، فجعلتُ كلمَّا فتحتُ بابًا أَغلقتُ عليَّ مِن داخلٍ، قلتُ: إن القومَ نَذِروا بي لم يَخْلُصوا إليَّ حتَّى أَقتُلَه، فانتهيتُ إليه، فإذا هو في بيتٍ مُظلمٍ وسطَ عِيالهِ، لا أَدري أين هو مِنَ البيتِ، فقلتُ: يا أبا رافعٍ، قال: مَن هذا؟ فأَهويتُ نحوَ الصَّوتِ فأَضرِبُه ضَربةً بالسَّيفِ وأنا دَهِشٌ، فما أَغنيتُ شيئًا، وصاح، فخرجتُ مِنَ البيتِ، فأَمكثُ غيرَ بَعيدٍ، ثمَّ دَخلتُ إليه، فقلتُ: ما هذا الصَّوتُ يا أبا رافعٍ؟ فقال: لِأُمِّكَ الوَيْلُ، إنَّ رجلًا في البيتِ ضَربَني قبلُ بالسَّيفِ. قال: فأَضرِبُه ضَربةً أَثْخَنَتْهُ ولم أَقتُلْه، ثمَّ وَضعتُ ظِبَةَ السَّيفِ في بَطنِه حتَّى أخَذ في ظَهرهِ، فعَرفتُ أنِّي قَتلتُه، فَجعلتُ أَفتحُ الأبوابَ بابًا بابًا، حتَّى انْتهَيتُ إلى دَرجةٍ له، فوَضعتُ رِجلي، وأنا أَرى أنِّي قد انْتهَيتُ إلى الأرضِ، فوقعتُ في ليلةٍ مُقْمِرَةٍ، فانكَسرتْ ساقي، فعَصَبْتُها بِعِمامةٍ، ثمَّ انطَلقتُ حتَّى جَلستُ على البابِ، فقلتُ: لا أخرجُ اللَّيلةَ حتَّى أَعلمَ: أَقتلتُه؟ فلمَّا صاح الدِّيكُ قام النَّاعي على السُّورِ فقال: أَنْعى أبا رافعٍ تاجرَ أهلِ الحِجازِ. فانطَلقتُ إلى أصحابي، فقلتُ: النَّجاءَ، فقد قتَل الله أبا رافعٍ، فانتهَيتُ إلى النَّبيِّ صلى الله عليه وسلم فحَدَّثتُه، فقال: «ابْسُطْ رِجْلَكَ». فبَسطتُ رِجلي فمسَحها فكأنَّها لم أَشْتَكِها قَطُّ."},{"id":85,"title":"غَزوةُ ذي قَرَدٍ .","date":["العام الهجري :6","الشهر القمري : محرم","العام الميلادي :627"],"text":"أَغار عُيَيْنَةُ بنُ حِصْنٍ -في بني عبدِ الله بنِ غَطَفانَ- على لِقاحِ النَّبيِّ صلى الله عليه وسلم التي بالغابةِ، فاسْتاقَها وقتَل راعيَها، وهو رجلٌ مِن غِفارٍ، وأخذوا امْرأتَهُ، فكان أوَّلَ مَن نذَر بهم سَلمةُ بنُ عَمرِو بنِ الأَكْوَعِ الأَسلميُّ رضي الله عنه، يقول سَلمةُ: خَرجتُ قبلَ أن يُؤذَّنَ بالأولى، وكانت لِقاحُ رسولِ الله صلى الله عليه وسلم تَرعى بِذي قَرَدٍ، قال: فلَقِيَني غُلامٌ لِعبدِ الرَّحمنِ بنِ عَوفٍ فقال: أُخِذَتْ لِقاحُ رسولِ الله صلى الله عليه وسلم. فقُلتُ: مَن أخَذها؟ قال: غَطَفانُ. قال: فصَرختُ ثلاثَ صَرخاتٍ، يا صَباحاهُ. قال: فأَسمَعتُ ما بين لابَتَيِ المدينةِ، ثمَّ اندَفعتُ على وجهي حتَّى أدركتُهم بِذي قَرَدٍ، وقد أخَذوا يَسقون مِنَ الماءِ، فجَعلتُ أَرميهِم بِنَبْلي، وكنتُ راميًا، وأقولُ: أنا ابنُ الأكوعِ... واليومُ يومُ الرُّضَّعِ، فأَرتَجِز حتَّى اسْتنقَذتُ اللِّقاحَ منهم، واسْتلَبتُ منهم ثلاثين بُردةً، قال: وجاء النَّبيُّ صلى الله عليه وسلم والنَّاسُ، فقلتُ: يا نَبيَّ الله، إنِّي قد حَمَيْتُ القومَ الماءَ وهُم عِطاشٌ، فابعثْ إليهم السَّاعةَ. فقال: «يا ابنَ الأَكوعِ مَلَكْتَ فأَسْجِحْ». ثمَّ قال: «إنَّهم الآنَ ليُقْرَوْنَ في غَطَفانَ». وذهَب الصَّريخُ بالمدينةِ إلى بني عَمرِو بنِ عَوفٍ، فَجاءتِ الأَمدادُ ولم تَزلْ الخيلُ تأتي، والرِّجالُ على أَقدامِهم وعلى الإبلِ حتَّى انْتَهَوْا إلى رسولِ الله صلى الله عليه وسلم بِذي قَرَدٍ. وبلغ النَّبيُّ صلى الله عليه وسلم ماءً يُقالُ له: ذو قَرَدٍ. فنحَر لِقْحَةً ممَّا اسْتَرجَع، وأقام هناك يومًا وليلةً، ثمَّ رجَع إلى المدينةِ. وقُتِلَ في هذه الغَزوةِ الأَخْرَمُ، وهو مُحْرِزُ بنُ نَضْلَةَ رضي الله عنه، قتَلهُ عبدُ الرَّحمنِ بنُ عُيينةَ، وتَحوَّل على فَرسِه، فحمَل عليه أبو قَتادةَ فقَتلهُ، واسْتَرجَع الفَرسَ، وكانت لِمحمودِ بنِ مَسلمةَ، وأَقبلتِ المرأةُ المَأسورةُ على ناقةٍ لِرسولِ الله صلى الله عليه وسلم، وقد نَذرتْ: إنِ الله أَنجاها عليها لَتَنْحَرَنَّها، فقال رسولُ الله صلى الله عليه وسلم: بِئسَ ما جَزَتْها، لا نذرَ لابنِ آدمَ فيما لا يَملِك، ولا في مَعصيةٍ. وأخَذ ناقتَهُ. وقد رَوى مُسلمٌ في صَحيحِه عن سَلمةَ بنِ الأَكوعِ في هذه القِصَّةِ قال: فرجَعنا إلى المدينةِ، فلم نَلبثْ إلَّا ثلاثَ ليالٍ، حتَّى خرَجنا إلى خَيبرَ."},{"id":86,"title":"سرية محمد بن مسلمة رضي الله عنه إلى القرطاء .","date":["العام الهجري :6","الشهر القمري : محرم","العام الميلادي :627"],"text":"بَعَثَ رسولُ الله صلَّى اللهُ عليه وسلَّم مُحمَّدَ بن مَسلَمةَ رَضي اللهُ عنه في ثلاثين راكِبًا إلى القُرْطاءِ -بينها وبين المدينةِ سَبعُ ليالٍ-، وهم بَطنٌ من بني بَكرٍ، واسمُه: عُبَيدُ بنُ كِلابٍ.فخَرَج محمدُ بنُ مَسلَمةَ رَضي اللهُ عنه وأصحابُه فسار اللَّيلَ واستَتَر النَّهارَ، فلمَّا أغار عليهم هَرَب سائِرُهم بعد أن قَتَل نَفَرًا منهم، واستاقَ المسلمون نَعَمًا وشاءً، وقَدِموا المدينةَ لِلَيلةٍ بَقيَت من المُحرَّمِ ومعهم ثُمامةُ بنُ أُثالٍ الحَنفيُّ سيِّدُ بني حَنيفةَ، كان قد خَرَج مُتنَكِّرًا لاغتيالِ النبيِّ صلَّى اللهُ عليه وسلَّم بأمرِ مُسيلِمةَ الكَذَّابِ، فأخَذَه المسلمون، فلمَّا جاؤوا به رَبَطوه بساريةٍ من سَواري المَسجِدِ، فخَرَج إليه النبيُّ صلَّى اللهُ عليه وسلَّم فقال: \"ما عِندَكَ يا ثُمامةُ؟\" فقال: عِندي خَيرٌ يا مُحمَّدُ، إنْ تَقتُلْ تَقتُلْ ذا دَمٍ، وإنْ تُنعِمْ تُنعِمْ على شاكِرٍ، وإنْ كُنتَ تُريدُ المالَ فسَلْ تُعطَ منه ما شِئتَ، فتَرَكَه. ثم مرَّ به مرَّةً أُخرَى، فقالَ له مِثلَ ذلك، فرَدَّ عليه كما ردَّ عليه أولًا، ثم مرَّ مرَّةً ثالِثةً فقال بعدما دار بينهما الكَلامُ السَّابِقُ: \"أطلِقوا ثُمامةَ\"، فأطلَقوه، فذَهَب إلى نَخلٍ قَريبٍ من المسجِدِ، فاغتَسَل، ثم جاءه فأسلَمَ، وقال: \"واللهِ ما كان على وَجهِ الأرضِ وَجهٌ أبغَضَ إليَّ من وَجهِك، فقد أصبَحَ وَجهُك أحبَّ الوُجوهِ إليّ، وواللهِ ما كان على وَجهِ الأرضِ دينٌ أبغَضَ إلَيَّ من دِينِك، فقد أصبَحَ دينُك أحَبَّ الأديانِ إليَّ، وإنَّ خَيلَك أخذَتْني وأنا أُريدُ العُمرةَ، فبَشَّرَه رسول الله صلَّى اللهُ عليه وسلَّم، وأمَره أن يَعتَمِرَ؛ فلمَّا قَدِم على قُرَيشٍ قالوا: صَبَأتَ يا ثُمامةُ، قال: لا واللهِ، ولكنِّي أسلَمتُ مع مُحمَّدٍ صلَّى اللهُ عليه وسلَّم، ولا واللهِ لا يأتيكُم من اليَمامةِ حَبَّةُ حِنطةٍ حتى يأذنَ فيها رسولُ الله صلَّى اللهُ عليه وسلَّم\". وكانت يَمامةُ ريفُ مكةَ؛ فانصَرَف إلى بلادِه، ومَنَع الحَمْلَ إلى مكةَ، حتى جَهِدَت قُريشٌ، وكَتَبوا إلى رسولِ الله صلَّى اللهُ عليه وسلَّم يَسألونه بأرحامِهِم أن يَكتُبَ إلى ثُمامةَ يُخلِّي إليهِم حَمْلَ الطَّعامِ؛ ففَعَل رسولُ الله صلَّى اللهُ عليه وسلَّم."},{"id":87,"title":"سرية عُكَّاشة بن مِحصَن رضي الله عنه إلى الغَمر (ماء بني أسد) .","date":["العام الهجري :6","الشهر القمري : ربيع الأول","العام الميلادي :627"],"text":"بَعَث رسولُ الله صلَّى اللهُ عليه وسلَّم عُكَّاشةَ بنَ مِحصَنٍ رَضي اللهُ عنه إلى الغَمْرِ -ماءٍ لبني أسَدٍ- في أربعين رَجلًا، فيهم: ثابِتُ بنُ أقرَمَ، وشُجاعُ بنُ وَهبٍ؛ فخَرَج سَريعًا ونَذِرَ به القَومُ فهَرَبوا فنَزَلوا عَلياءَ بلادِهِم، ووَجَد ديارَهم خُلوفًا -أي: أهلُها غائِبون-، فبَعَث شُجاعَ بنَ وَهبٍ طَليعةً؛ فرَأى أثَرَ النَّعَمِ، فتَحمَّلوا فأصابوا مَن دَلَّهم على بَعضِ ماشيَتِهِم، فأمَّنوه، فدَلَّهم على نَعَمٍ لبني عمٍّ له، فأغاروا عليها، فاستاقوا مِائتَي بَعيرٍ؛ فأرسَلوا الرَّجلَ، وساقوا النَّعَمَ إلى المدينةِ، وقَدِموا على رسولِ الله صلَّى اللهُ عليه وسلَّم ولم يَلقَوا كَيدًا."},{"id":88,"title":"سرية محمد بن مسلمة رضي الله عنه إلى بني ثعلبة وبني عوال بذي القَصَّةِ .","date":["العام الهجري :6","الشهر القمري : ربيع الآخر","العام الميلادي :627"],"text":"بَعَث رسولُ الله صلَّى اللهُ عليه وسلَّم مُحمَّدَ بنَ مَسلَمةَ رَضي اللهُ عنه، ومعه عَشَرةُ نَفَرٍ إلى بني ثَعلَبةَ من غَطَفانَ وبني عَوالٍ من ثَعلَبةَ، وهم بذي القَصَّةِ، فوَرَدوا عليهم ليلًا، فأحدَق به القومُ، وهم مئةُ رجلٍ، فتَرامَوا ساعةً من اللَّيلِ، ثم حَمَلتِ الأعرابُ عليهم بالرِّماحِ فقَتَلوهم جميعًا، ووَقَع محمدُ بنُ مَسلَمةَ جَريحًا، فضَرَبوا كعبَه فلم يتحرَّك فظَنُّوا مَوتَه، فجَرَّدوه من الثيابَ وانطَلَقوا، ومر بمُحمَّدٍ وأصحابِه رجلٌ من المسلمين فاستَرجَعَ، فلمَّا سَمِعه مُحمَّدٌ يَستَرجِعُ تَحرَّك له، فأخَذه وحَمَله إلى المدينةِ؛ فعند ذلك بَعَث رسولُ الله صلَّى اللهُ عليه وسلَّم أبا عُبيدةَ بنَ الجرَّاحِ في أربعين رجُلًا إلى مَصارِعِهم فلم يَجِدوا أحدًا، ووَجَدوا نَعَمًا وشاءً فانحدَروا بها إلى المَدينةِ."},{"id":89,"title":"سرية أبي عبيدة بن الجراح إلى ذي القصة .","date":["العام الهجري :6","الشهر القمري : ربيع الآخر","العام الميلادي :627"],"text":"أرسل رسولُ الله صلَّى اللهُ عليه وسلَّم أبا عُبَيدةَ بنَ الجَرَّاحِ رَضي اللهُ عنه إلى ذي القَصَّةِ -موضِعٍ قريبٍ من المدينةِ- على إثرِ مَقتَلِ أصحابِ مُحمَّدِ بنِ مَسلمةَ رَضي اللهُ عنه في أربعين رجلًا من المسلمين حين صَلَّوُا المَغرِبَ، فسار إليهم مُشاةً حتى وافَوا ذي القَصَّةِ مع عَمايةِ الصُّبحِ -بقيَّةِ ظُلمةِ اللَّيلِ- فأغاروا عليهم، فأعجَزوهم هَرَبًا في الجبالِ، وأصابوا رجلًا فأسلم فتَرَكوه، وغَنِموا نَعَمًا من نَعَمِهِم فاستاقوه، ورِثَّةً -السَّقَطَ من مَتاعِ البَيتِ- من مَتاعِهم، وقَدِموا بذلك المدينةَ، فخَمَّسَه رسولُ الله صلَّى اللهُ عليه وسلَّم وقسَّم ما بَقيَ عليهم. وعند ابنِ سعدٍ في طَبَقاتِه: أنَّ سببَ بَعثِه صلَّى اللهُ عليه وسلَّم أبا عُبيدةَ رَضي اللهُ عنه إلى ذي القَصَّةِ: هو ما بَلَغه مِن أنَّ بني مُحارِبِ بنِ خَصَفةَ، وثَعلبةَ وأنمارٍ -وهما من غَطَفانَ- أجمَعوا أن يُغيروا على سَرحِ المَدينةِ، وهو يَرعَى بهَيفا -موضِعٍ على سَبعةِ أميالٍ من المدينةِ-، فلَعلَّ الرسولَ -صلَّى اللهُ عليه وسلَّم- بَعَث أبا عُبيدةَ رَضي اللهُ عنه مرَّتَين إلى ذي القَصَّةِ، أو أن يَكونَ البَعثُ مرَّةً واحِدةً، ولكنْ له سَبَبانِ: الأخذُ بثَأرِ أصحابِ مُحمَّدِ بن مَسلَمةَ رَضي اللهُ عنه المَقتولين، ودَفْعُ مَن أراد الإغارةَ على سَرحِ المَدينةِ."},{"id":90,"title":"سرية زيد بن حارثة رضي الله عنه إلى الجموم (ماءٌ على طَريقِ مكةَ) .","date":["العام الهجري :6","الشهر القمري : ربيع الآخر","العام الميلادي :627"],"text":"بَعَث رسولُ الله صلَّى اللهُ عليه وسلَّم زيدَ بنَ حارِثةَ رَضي اللهُ عنه إلى بني سُلَيمٍ؛ فسار حتى وَرَد الجَمومَ -وهو ماءٌ على طَريقِ مكةَ- ناحيةَ بَطنِ نَخلٍ عن يَسارِها، فأصابوا عليه امرَأةً من مُزَينةَ يقال لها: حَليمةُ، فدَلَّتهم على مَحَلَّةٍ من مَحالِّ بني سُلَيمٍ؛ فأصابوا في تلك المَحَلَّةِ نَعَمًا وشاءً وأسرى، فكان فيهم زوجُ حَليمةَ المُزنيَّةِ، فلمَّا قَفَل زيدُ بنُ حارِثةَ رَضي اللهُ عنه إلى المَدينةِ بما أصاب، وَهَب رسولُ الله صلَّى اللهُ عليه وسلَّم للمُزَنيَّةِ نَفسَها وزَوجَها."},{"id":91,"title":"غزوة بني لحيان (الذين غدروا يوم الرجيع) .","date":["العام الهجري :6","الشهر القمري : جمادى الأولى","العام الميلادي :627"],"text":"بنو لِحيانَ: هم الذين غدروا بخُبَيبِ بنِ عَديٍّ رَضي اللهُ عنه وأصحابِه يومَ الرَّجيعِ، ولمَّا كانت ديارُهم مُتوغِّلةً في بلاد الحِجازِ إلى حدودِ مكةَ، ولوُجودِ ثاراتٍ بين المسلمين من جهةٍ، وقُريشٍ والأعرابِ من جهة أُخرَى، رأى رسولُ الله صلَّى اللهُ عليه وسلَّم ألَّا يَتوغَّلَ في البلادِ القريبةِ من العَدوِّ الأكبَرِ والرَّئيسيِّ قُريشٍ، فلمَّا تَخاذَلَتِ الأحزابُ، وانكَسَرَت عزائِمُهم، رأى أنَّ الوقتَ قد حان لغَزوِ بني لِحيانَ وأخذِ الثَّأرِ لأصحابِ الرَّجيعِ؛ فخَرَج إليهمُ الرَّسولُ صلَّى اللهُ عليه وسلَّم طالِبًا بدِماءِ أصحابِه في مِائَتين من أصحابِه، ومعهم عِشرون فَرَسًا، واستَخلَف على المدينةِ عبدَ اللهِ بنَ أُمِّ مَكتومٍ رَضي اللهُ عنه، وأظهَر رسولُ الله صلَّى اللهُ عليه وسلَّم أنَّه يُريدُ الشَّامَ ليُصيبَ بني لِحيانَ غِرَّةً، ثم أسرَع السَّيرَ حتى انتَهَى إلى وادي غُرانَ بين أمَجَّ -مَوضِعٍ بين مكةَ والمدينةِ- وعُسفانَ -قريةٍ بين مكةَ والمدينةِ-، وهي منازِلُ بني لِحيانَ، وفيها كان مُصابُ أصحابِه، فتَرَحَّم عليهم ودعا لهم. وسَمِعت به بنو لِحيانَ، فهَرَبوا واحتَمَوا في رؤوسِ الجِبالِ؛ فلم يَقدِر رسولُ الله صلَّى اللهُ عليه وسلَّم على أحدٍ منهم؛ فأقام رسولُ الله صلَّى اللهُ عليه وسلَّم بأرضِهم يَومًا أو يومَين، وبَعَث السَّرايا في كلِّ ناحيةٍ فلم يَقدِروا على أحدٍ. ثم سار رسولُ الله صلَّى اللهُ عليه وسلَّم بأصحابِه إلى عُسفانَ لتَسمَعَ به قُرَيشٌ فيُداخِلَهمُ الرُّعبُ، وليُريَهم من نَفسِه قُوَّةً؛ فبَعَث أبا بكرٍ الصِّدِّيقَ رَضي اللهُ عنه في عَشَرةِ فَوارِسَ إلى كُراعِ الغَميمِ -مَوضِعٍ بين مكةَ والمدينةَ-، ثم رَجَع أبو بَكرٍ الصِّدِّيقُ رَضي اللهُ عنه ولم يَلْقَ أحدًا."},{"id":92,"title":"سرية زيد بن حارثة رضي الله عنه إلى العيص .","date":["العام الهجري :6","الشهر القمري : جمادى الأولى","العام الميلادي :627"],"text":"بَعَث رسول الله صلَّى اللهُ عليه وسلَّم زيدَ بنَ حارِثةَ رَضي اللهُ عنه في سَريَّةٍ في سبعين ومئةِ راكِبٍ إلى العيصِ -اسمِ مَوضِعٍ قُربَ المدينةِ على ساحِلِ البحرِ- بهَدفِ اعتِراضِ عيرٍ لقُريشٍ أقبلَت مِن الشامِ بقيادةِ أبي العاصِ بنِ الرَّبيعِ، فأدرَكوها، فأخَذوها وما فيها، وأخَذوا يومئذٍ فِضَّةً كَثيرةً لصَفوانَ بنِ أُميَّةَ، وأسَروا ناسًا ممَّن كان في العيرِ، منهم: أبو العاصِ بنُ الرَّبيعِ، وقَدِموا بهم إلى المدينةِ. وكان أبو العاصِ من رجالِ مكة المعدودين تِجارةً ومالًا وأمانةً، وهو زوجُ زَينبَ بنتِ رسولِ الله صلَّى اللهُ عليه وسلَّم، وأمُّه هالةُ بِنتُ خويلدٍ أُختِ خَديجةَ رَضي اللهُ عنها. فأتى أبو العاصِ زينبَ رَضي اللهُ عنها في اللَّيلِ، وكانت زينبُ هاجَرَت قَبلَه وتَرَكَته على شِركِه فاستَجارَ بها فأجارَته، وأجازَ رسولُ الله صلَّى اللهُ عليه وسلَّم جِوارَها."},{"id":93,"title":"سرية زيد بن حارثة إلى بني ثعلبة بالطَّرف (ماء قرب المدينة) .","date":["العام الهجري :6","الشهر القمري : جمادى الآخرة","العام الميلادي :627"],"text":"بَعَث رسولُ الله صلَّى اللهُ عليه وسلَّم زيدَ بنَ حارِثةَ رَضي اللهُ عنه إلى الطَّرَفِ -هو ماءٌ على ستَّةٍ وثلاثين ميلًا من المدينةِ-، فخَرَج إلى بني ثَعلبةَ في خَمسةَ عَشَرَ رَجُلًا، فهَرَبتِ الأعرابُ وخافوا أن يكونَ رسولُ الله صلَّى اللهُ عليه وسلَّم سار إليهم، وأنَّ هؤلاءِ مُقدِّمةٌ؛ فأصابَ مِن نَعَمِهم عِشرين بَعيرًا، ورَجَع إلى المدينةِ، ولم يَلْقَ كيدًا، وغابَ أربَعَ لَيالٍ. وكان شِعارُهم: \"أمِتْ أمِتْ\"."},{"id":94,"title":"سرية عبد الرحمن بن عوف رضي الله عنه إلى دومة الجندل .","date":["العام الهجري :6","الشهر القمري : شعبان","العام الميلادي :628"],"text":"دعا رسولُ الله صلَّى اللهُ عليه وسلَّم عبدَ الرَّحمنِ بنَ عوفٍ رَضي اللهُ عنه، فقال له: \"تَجهَّزْ؛ فإنِّي باعِثُك في سَريَّةٍ مِن يَومِك هذا، أو مِن الغَدِ إن شاءَ اللهُ تعالى\"، فأصبَحَ عبدُ الرَّحمنِ فغَدا إلى رسولِ الله صلَّى اللهُ عليه وسلَّم، فأقعَدَه بين يَدَيه وعمَّمَه بيَدِهِ، ثمَّ عَقَد له رسولُ الله صلَّى اللهُ عليه وسلَّم اللواءَ بيَدِه، أو أمرَ بلالًا يَدفَعُه إليه، ثم قال له: \"خُذه باسمِ اللهِ وبَرَكَتِه\"، ثم حَمِد الله تعالى، ثم قال صلَّى اللهُ عليه وسلَّم: \"اغزُ باسمِ الله، وفي سَبيلِ الله، فقاتِل مَن كَفَر بالله! ولا تَغُلَّ -الغُلولُ: هو الخيانةُ في المَغنَمِ والسَّرِقةُ من الغَنيمةِ قَبْلَ القِسمةِ-، ولا تَغدِرْ، ولا تَقتُلْ وَليدًا\"، ثم أمَرَه رسولُ الله أن يَسيرَ إلى بني كَلْبٍ بدُومةِ الجَندَلِ، فيَدعوَهم إلى الإسلامِ، وقال له: \"إنِ استَجابوا لَكَ فتَزَوَّجِ ابنةَ مَلِكِهِم\". فسار عبدُ الرَّحمنِ رَضي اللهُ عنه بأصحابِه وكانوا سَبعَمِئةِ رَجلٍ، حتى قَدِمَ دُومةَ الجَندَلِ؛ فمَكَث ثلاثةَ أيَّامٍ يَدعوهم إلى الإسلامِ؛ فلمَّا كان اليومُ الثالِثُ أسلَمَ رأسُهم ومَلِكُهمُ الأصبَغُ بنُ عَمرٍو الكَلبيُّ، وكان نَصرانيًّا، وأسلَمَ معه ناسٌ كَثيرٌ من قَومِه؛ فبَعَث عبدُ الرحمنِ رافِعَ بنَ مَكيثٍ بَشيرًا إلى النبيِّ صلَّى اللهُ عليه وسلَّم يُخبِرُه بما فَتَح الله عليه وكَتَب له بذلك، وتزوَّجَ عبدُ الرحمنِ تُماضِرَ بِنتَ الأصبَغِ وقَدِمَ بها المدينةَ، فوَلَدَت له بعد ذلك أبا سَلَمةَ بنَ عبدِ الرَّحمنِ بنَ عَوفٍ."},{"id":95,"title":"سرية أبي بكر الصديق رضي الله عنه  إلى بني فزارة بوادي القرى .","date":["العام الهجري :6","الشهر القمري : رمضان","العام الميلادي :628"],"text":"كان بَطنُ فَزارةَ يُريدُ اغتيالَ النبيِّ صلَّى اللهُ عليه وسلَّم؛ فبَعَث رسولُ الله صلَّى اللهُ عليه وسلَّم سَريَّةً على رَأسِها: أبو بَكرٍ الصِّدِّيقُ رَضي اللهُ عنه فأغار عليهم، وقَتَل وأسَر وسَبَى، وكان مِن شَياطينِهم أُمُّ قِرْفةَ التي جهَّزَت ثلاثين فارِسًا من أهلِ بَيتِها لاغتيالِ رسولِ الله صلَّى اللهُ عليه وسلَّم، فقُتِلوا وسُبيَتِ ابنَتُها، ففَدَى بها رسولُ الله صلَّى اللهُ عليه وسلَّم بعضَ أُسارَى المسلمين في مكةَ.أخرج الإمامُ مسلمٌ في «صَحيحِه» عن سَلَمةَ بنِ الأكوَعِ رَضي اللهُ عنه قال: غَزَونا فَزارةَ، وعلينا أبو بَكرٍ؛ أمَّرَه رسول الله صلَّى اللهُ عليه وسلَّم علينا؛ فلمَّا كان بيننا وبين الماءِ ساعةٌ أمَرَنا أبو بَكرٍ فعَرَّسنا ثم شنَّ الغارةَ، فوَرَدَ الماء، فقَتَل مَن قَتَل عليه، وسَبَى، وأنظُرُ إلى عُنُقٍ من النَّاسِ، فيهِمُ الذَّراري فخَشيتُ أن يَسبِقوني إلى الجبلِ، فرَمَيتُ بسهمٍ بينهم وبين الجبلِ. فلمَّا رَأوُا السَّهمَ وَقَفوا، فجِئتُ بهم أسوقُهم. وفيهمُ امرَأةٌ من بني فَزارةَ عليها قَشْعٌ من أدَمٍ -أي: ثَوبٌ من الجِلدِ-، معها ابنةٌ من أحسَنِ العَرَبِ، فسُقتُهم حتى أتيتُ بهم أبا بَكرٍ، فنَفَلَني أبو بكرٍ ابنَتَها. فقَدِمنا المدينةَ، وما كَشَفتُ لها ثَوبًا، فلَقيَني رسولُ الله صلَّى اللهُ عليه وسلَّم في السُّوقِ، فقال: \"يا سَلَمةُ، هَبْ لي المَرأةَ\". فقلتُ: \"يا رسولَ الله، والله لقد أعجَبَتني، وما كَشَفتُ لها ثَوبًا\"، ثم لَقيَني رسولُ الله صلَّى اللهُ عليه وسلَّم من الغَدِ في السُّوقِ، فقال لي: \"يا سَلَمةُ، هَبْ لي المَرأةَ للهِ أبوكَ!\" فقلتُ: هي لك يا رسولَ الله، فوالله ما كَشَفتُ لها ثَوبًا. فبَعَث بها رسولُ الله صلَّى اللهُ عليه وسلَّم إلى أهلِ مكةَ، ففَدَى بها ناسًا من المسلمين، كانوا أُسِروا بمكةَ."},{"id":96,"title":"سرية كُرز بن جابر الفهري إلى العرنيين .","date":["العام الهجري :6","الشهر القمري : شوال","العام الميلادي :628"],"text":"في هذا العام كانت سَريَّةُ كُرْزِ بنِ جابِرٍ الفِهريِّ إلى العُرَنيِّين، الذين قَتَلوا راعيَ رسولِ الله صلَّى اللهُ عليه وسلَّم، واستاقوا النَّعَمَ؛ فبَعَث رسولُ الله صلَّى اللهُ عليه وسلَّم في آثارِهِم كُرْزَ بنَ جابِرٍ رَضي اللهُ عنه في عِشرين فارِسًا.عن أنس رَضي اللهُ عنه: أنَّ رهطًا من عُكلٍ وعُرَينةَ أتَوا رسولَ الله صلَّى اللهُ عليه وسلَّم فقالوا: إنَّا أُناسٌ من أهل ضَرعٍ، ولم نَكُن أهلَ ريفٍ، فاستَوخَمنا المَدينةَ -لم يُوافِقهم جَوُّها- فأمَر لهم رسولُ الله صلَّى اللهُ عليه وسلَّم بذَودٍ -إبلٍ- وراعٍ، وأمَرَهم أن يَخرُجوا فيها فيَشرَبوا من أبوالِها وألبانِها؛ فانطَلَقوا حتى إذا كانوا في ناحيةِ الحَرَّةِ قَتَلوا راعيَ رسولِ الله صلَّى اللهُ عليه وسلَّم واستاقوا الذَّودَ، وكَفَروا بعد إسلامِهِم؛ فبَعَث النبيُّ صلَّى اللهُ عليه وسلَّم في طَلَبِهم، فأمر فقَطَع أيديَهم وأرجُلَهم وسَمَرَ أعيُنَهم -كَحَلَها بمَساميرَ مَحميَّةٍ-، وتَرَكَهم في ناحيةِ الحَرَّةِ حتى ماتوا وهم كذلك. وإنَّما سَمَرَ أعينهم لأنهم سمروا أعين الرعاء."},{"id":97,"title":"بَيعةُ الرِّضْوانِ .","date":["العام الهجري :6","الشهر القمري : ذي القعدة","العام الميلادي :628"],"text":"كان رسولُ الله صلَّى الله عليه وسلَّم قبلَ عَقْدِ صُلحِ الحُديبيةِ بعَث خِراشَ بنَ أُميَّةَ الخُزاعيَّ إلى مكَّةَ، وحمَلهُ على جَملٍ له يُقالُ له: الثَّعلبُ. فلمَّا دخَل مكَّةَ عَقَرَتْ به قُريشٌ وأرادوا قَتْلَ خِراشٍ فمنَعهُم الأَحابيشُ (هم: بنو الحارث بن عبد مناة بن كنانة ، والهون بن خزيمة بن مدركة، وبنو المصطلق من خزاعة) حتَّى أتى رسولَ الله صلى الله عليه وسلم فدَعا عُمَرَ لِيَبعثَهُ إلى مكَّةَ، فقال: يا رسولَ الله إنِّي أَخافُ قُريشًا على نَفْسي، وليس بها مِن بني عَدِيٍّ أحدٌ يَمنعُني، وقد عَرفتْ قُريشٌ عَداوتي إيَّاها وغِلْظَتي عليها؛ ولكنْ أَدلُّك على رجلٍ هو أَعزُّ مِنِّي عُثمانَ بنِ عفَّانَ. فدَعاهُ رسولُ الله صلَّى الله عليه وسلَّم فبعَثهُ إلى قُريشٍ يُخبِرُهم أنَّه لم يأتِ لحربٍ، وأنَّه جاء زائرًا لهذا البيتِ مُعَظِّمًا لِحُرمَتِه، فخرج عُثمانُ حتَّى أتى مكَّةَ ولَقِيَهُ أَبانُ بنُ سَعيدِ بنِ العاصِ، فنزَل عن دَابَّتِه وحمَله بين يَديه ورَدِف خلفَه وأَجارهُ حتَّى بلَّغَ رِسالةَ رسولِ الله صلَّى الله عليه وسلَّم، فانطلق عُثمانُ حتَّى أتى أبا سُفيانَ وعُظماءَ قُريشٍ فبَلَّغهُم عن رسولِ الله صلَّى الله عليه وسلَّم ما أَرسلهُ به، فقالوا لِعُثمانَ: إن شِئتَ أن تَطوفَ بالبيتِ فَطُفْ به. فقال: ما كنتُ لأفعلَ حتَّى يَطوفَ به رسولُ الله صلَّى الله عليه وسلَّم. فاحْتبسَتهُ قُريشٌ عندها، فبلَغ رسولَ الله صلَّى الله عليه وسلَّم والمسلمين أنَّ عُثمانَ قد قُتِلَ).قال ابنُ عُمَرَ رضِي الله عنهما:كانت بَيعةُ الرِّضوانِ بعدَ ما ذهَب عُثمانُ إلى مكَّةَ، فقال رسولُ الله صلى الله عليه وسلم بيدِه اليُمنى: «هذه يدُ عُثمانَ». فضرَب بها على يدِه، فقال: «هذه لِعُثمانَ».وقال جابرُ بنُ عبدِ الله: كُنَّا يومَ الحُديبيةِ ألفًا وأربعَ مائةٍ، فبايَعْنا رسولَ الله صلى الله عليه وسلم وعُمَرُ آخِذٌ بيدِه تحت الشَّجرةِ، وهي سَمُرَةٌ.  وقال لنا النَّبيُّ صلى الله عليه وسلم: «أنتم اليومَ خيرُ أهلِ الأرضِ». ثم قال جابرٌ: لو كنتُ أُبصِرُ لأَرَيْتُكُم مَوضِعَ الشَّجرةِ. وعن مَعقِلِ بنِ يَسارٍ قال: لقد رَأيتُني يومَ الشَّجرةِ، والنَّبيُّ صلى الله عليه وسلم يُبايِعُ النَّاسَ، وأنا رافعٌ غُصنًا مِن أَغصانِها عن رَأسِه، ونحن أربعَ عشرةَ مائةً. وقدِ اخْتلفتِ الرِّواياتُ في عَددِهم، فقال ابنُ حَجَرٍ: (والجمعُ بين هذا الاختلافِ أنَّهم كانوا أكثرَ مِن ألفٍ وأربعمائةٍ، فمَن قال: ألفًا وخمسمائةٍ جبَر الكَسرَ، ومَن قال: ألفًا وأربعمائةٍ أَلغاهُ)."},{"id":98,"title":"صُلْحُ الحُدَيبيةِ .","date":["العام الهجري :6","الشهر القمري : ذي القعدة","العام الميلادي :628"],"text":"خرَج رسولُ الله صلى الله عليه وسلم ومعه قُرابةُ ألفٍ وأربعمائةٍ مِن أصحابِه يُريدون العُمرةَ فلمَّا وصلوا إلى الحُديبيةِ - وهي تَبعُد عن مكَّةَ قُرابةَ 22 كم - وَصلَهُ الخبرُ أنَّ هناك مَن يُريدُ أن يُقاتِلَهُ، فقال: إنَّه لم يَجِئْ لقِتالٍ؛ بل جاء مُعتمِرًا. وأَرسل رسولُ الله صلى الله عليه وسلم عُثمانَ بنَ عفَّانَ إلى مكَّةَ لِيُخبِرَهم بذلك، ثمَّ شاع الخبرُ أنَّ عُثمانَ قُتِلَ، فأمَر رسولُ الله صلى الله عليه وسلم الصَّحابةَ رضي الله عنهم أن يُبايِعوه على القِتالِ، فبايَعوهُ وهي بَيعةُ الرِّضوانِ، ثمَّ جاء المشركون إلى الحُديبيةِ وحَصَلت عِدَّةُ مُفاوضاتٍ بين رُؤساءٍ مِنَ المشركين وبين النَّبيِّ صلى الله عليه وسلم حتَّى جاء سُهيلُ بنُ عَمرٍو فصالَحهُ النَّبيُّ صلى الله عليه وسلم على أن تُوضَعَ الحربُ عشرَ سنين يأمنُ فيها النَّاسُ، ويَكُفُّ بعضُهم عن بعضٍ، وعلى أنَّ مَن أتى رسولَ الله مِن أصحابِه مِن غيرِ إذنِ وَلِيِّهِ رَدَّهُ رسولُ الله عليهم، ومَن أتى قُريشًا مِن أصحابِه لم يَردُّوه، وأنَّ بينهم عَيْبَةً مَكفوفَةً، أي: لا غِشَّ فيها، وأنَّه لا إسْلالَ -يعني لا سَرِقةَ- ولا إغْلالَ -يعني لا خِيانةَ- وأن يَرجِعَ في عامِه هذا دون أن يَدخُلَ مكَّةَ وله ذلك في العامِ القابلِ، يَدخلُها ثلاثةَ أيَّامٍ معه سِلاحُ الرَّاكبِ لا يَدخلُها بغيرِ السُّيوف في القُرُبِ... ثمَّ أمَر النَّبيُّ صلى الله عليه وسلم أصحابَه أن يَنحَروا ويَحلِقوا؛ ولكنَّهم لم يفعلوا حتَّى أَشارت عليه أمُّ سَلمةَ رضي الله عنها أن يَقومَ هو بذلك دون أن يُكلِّمَ أحدًا فلمَّا رَأَوْهُ نَحَرَ تَواثَبوا إلى الهَدْيِ وفعلوا مِثلَ ما فعَل, ثم عاد النَّبيُّ صلى الله عليه وسلم إلى المدينة دون عُمرةٍ ودون قِتالٍ."},{"id":99,"title":"غَزوةُ خَيبرَ .","date":["العام الهجري :7","الشهر القمري : محرم","العام الميلادي :628"],"text":"اختلَف أهلُ السِّيَرِ في وقتِها على قولين، فقِيلَ: في السَّنةِ السَّابعةِ. وهو قولُ ابنِ إسحاقَ وغيرِه، وقِيلَ: في السَّنةِ السَّادسةِ. وهو قولُ مالكٍ وغيرِه. قال ابنُ القَيِّمِ: والجُمهورُ على أنَّها في السَّابعةِ. وقال ابنُ حَجَرٍ: وهذه الأقوالُ مُتقاربةٌ، والرَّاجحُ منها ما ذكَرهُ ابنُ إسحاقَ، ويُمكنُ الجمعُ بينهما بأنَّ مَن أطلق سَنَةَ سِتٍّ بِناءً على أنَّ ابتداءَ السَّنةِ مِن شهرِ الهِجرةِ الحقيقيِّ وهو ربيعٌ الأوَّلُ. عن أنسٍ: أنَّ رسولَ الله صلى الله عليه وسلم غَزا خَيبرَ، قال: فصلَّينا عندها صلاةَ الغَداةِ بِغَلَسٍ، فرَكِبَ نَبيُّ الله صلَّى الله عليه وسلَّم ورَكِبَ أبو طلحةَ، وأنا رَديفُ أبي طلحةَ، فأَجرى نَبيُّ الله صلى الله عليه وسلم في زُقاقِ خَيبرَ، وإنَّ رُكبتِي لَتَمَسُّ فَخِذَ نَبيِّ الله صلى الله عليه وسلم، وانْحسَر الإزارُ عن فَخِذِ نَبيِّ الله صلى الله عليه وسلم، فإنِّي لأَرى بَياضَ فَخِذِ نَبيِّ الله صلى الله عليه وسلم، فلمَّا دخَل القريةَ قال: «الله أكبرُ خَرِبتْ خَيبرُ، إنَّا إذا نزَلنا بِساحةِ قومٍ فَساءَ صباحُ المُنذَرين». قالها ثلاثَ مرَّاتٍ، قال: وقد خرَج القومُ إلى أعمالِهم، فقالوا: محمَّدٌ، والله -قال عبدُ العَزيزِ: وقال بعضُ أصحابِنا: محمَّدٌ، والخَميسُ- قال: وأَصَبناها عَنْوَةً، وجُمِعَ السَّبْيُ، فجاءَهُ دِحْيَةُ فقال: يا رسولَ الله، أَعطِني جاريةً مِنَ السَّبْيِ. فقال: «اذهَبْ فخُذْ جاريةً». فأخَذ صَفِيَّةَ بنتَ حُيَيٍّ، فجاء رجلٌ إلى نَبيِّ الله صلى الله عليه وسلم فقال: يا نَبيَّ الله، أَعطيتَ دِحيةَ صَفيَّةَ بنتَ حُيَيٍّ سَيِّدِ قُريظةَ والنَّضيرِ! ما تَصلُحُ إلَّا لك، قال: «ادْعوهُ بها». قال: فجاء بها، فلمَّا نظَر إليها النَّبيُّ صلى الله عليه وسلم، قال: «خُذْ جاريةً مِنَ السَّبْيِ غيرَها». قال: وأَعتقَها وتَزوَّجَها...\" عن أنسٍ رضي الله عنه: أنَّ النَّبيَّ صلى الله عليه وسلم خرَج إلى خَيبرَ، فجاءَها ليلًا، وكان إذا جاء قومًا بِليلٍ لا يُغيرُ عليهم حتَّى يُصبِحَ، فلمَّا أَصبح خرجَت يَهودُ بمَساحيهِم ومَكاتِلهِم، فلمَّا رَأَوْهُ قالوا: محمَّدٌ والله، محمد والخَميسُ. فقال النَّبيُّ صلى الله عليه وسلم: «الله أَكبرُ، خَرِبَتْ خَيبرُ إنَّا إذا نزلنا بِساحةِ قومٍ، فَساءَ صَباحُ المُنذَرين». وقد جعَل الله تعالى فتحَ خَيبرَ على يَدِ عليِّ بنِ أبي طالبٍ رضي الله عنه. وعن عبدِ الله بنِ عُمَرَ رضِي الله عنهما قال: أَعطى رسولُ الله صلى الله عليه وسلم خَيبرَ اليَهودَ: أن يَعمَلوها ويَزرَعوها، ولهم شَطْرُ ما يَخرُجُ منها\". فأَبقاهم النَّبيُّ صلى الله عليه وسلم في أَرضِهم ولهم النِّصفُ."},{"id":100,"title":"تَحريمُ لُحومِ الحُمُرِ الأَهْلِيَّةِ ومُتعةِ النِّساءِ يوم خيبر .","date":["العام الهجري :7","الشهر القمري : محرم","العام الميلادي :628"],"text":"في أثناءِ غَزوةِ خَيبرَ حَرَّمَ رسولُ الله صلى الله عليه وسلم لُحومَ الحُمُرِ الأَهلِيَّةِ، وأَخبرَ أنَّها رِجْسٌ، وأمَر بالقُدورِ فأُلقِيتْ وهي تَفورُ بِلُحومِها، وأمَر بغَسلِ القُدورِ بعدُ، وأَحَلَّ حِينئذٍ لُحومَ الخَيْلِ وأَطعَمهُم إيَّاها, كما نَهى صلى الله عليه وسلم عن مُتعةِ النِّساءِ."},{"id":101,"title":"هجرة أبي موسى الأشعري وأصحابه رضي الله عنهم إلى المدينة مروراً بالحَبشةِ .","date":["العام الهجري :7","الشهر القمري : محرم","العام الميلادي :628"],"text":"عن أبي موسى رضي الله عنه قال: بلغَنا مَخرجُ النَّبيِّ صلى الله عليه وسلم ونحن باليَمنِ، فخرَجْنا مُهاجرين إليه، أنا وأَخَوانِ لي أنا أَصغرُهم، أَحدُهما أبو بُردةَ، والآخرُ أبو رُهْمٍ -إمَّا قال: في بِضْعٍ، وإمَّا قال: في ثلاثةٍ وخمسين، أو اثنين وخمسين رجلًا مِن قومي- فرَكِبْنا سَفينةً، فأَلقَتْنا سَفينتُنا إلى النَّجاشيِّ بالحَبشةِ، ووافَقْنا جَعفرَ بنَ أبي طالبٍ وأصحابَه عنده، فقال جَعفرٌ: إنَّ رسولَ الله صلى الله عليه وسلم بعَثنا هاهنا، وأمَرنا بالإقامةِ، فأقيموا معنا. فأَقمنا معه حتَّى قَدِمنا جميعا، فوافَقْنا النَّبيَّ صلى الله عليه وسلم حين افتَتَح خَيبرَ، فأَسهَم لنا -أو قال: فأعطانا منها- وما قَسَمَ لأحدٍ غاب عن فَتحِ خَيبرَ منها شيئًا، إلَّا لمن شَهِدَ معه، إلَّا أصحابَ سَفينتِنا مع جَعفرٍ وأصحابِه، قَسَمَ لهم معهم."},{"id":102,"title":"مُحاوَلةُ اليَهودِ تَسميمِ رسولِ الله صلَّى الله عليه وسلَّم .","date":["العام الهجري :7","الشهر القمري : محرم","العام الميلادي :628"],"text":"لمَّا اطْمأنَّ رسولُ الله صلى الله عليه وسلم بخَيبرَ بعدَ فَتحِها أَهدَتْ له زَينبُ بنتُ الحارثِ -امرأةُ سَلاَّمِ بنِ مِشْكَمٍ- شاةً مَصْلِيَّةً، وقد سَألتْ أيَّ عُضْوٍ أَحَبُّ إلى رسولِ الله صلى الله عليه وسلم؟ فقِيلَ لها: الذِّراعُ، فأَكثرتْ فيها مِنَ السُّمِّ، ثمَّ سَمَّتْ سائرَ الشَّاةِ، ثمَّ جاءت بها، فلمَّا وَضعتْها بين يَدي رسولِ الله صلى الله عليه وسلم تناوَلَ الذِّراعَ، فَلاكَ منها مُضغةً فلم يسغْها، ولَفَظَها، ثمَّ قال: (إنَّ هذا العَظمُ لَيخبِرُني أنَّه مَسمومٌ). ثم دَعا بها فاعْترَفتْ، فقال: (ما حمَلكِ على ذلك؟). قالتْ: قلتُ إن كان مَلِكاً استَرحتُ منه، وإن كان نَبِيًّا فسيُخبَرُ، فتجاوَز عنها. وكان معه بِشْرُ بنُ البَراءِ بنِ مَعْرورٍ، أخَذ منها أَكلةً فأَساغَها، فمات منها, واخْتلفَتِ الرِّواياتُ في التَّجاوُزِ عنِ المرأةِ وقَتْلِها، وأجمعوا بأنَّه تَجاوَز عنها أوَّلًا، فلمَّا مات بِشْرُ قَتَلَها قِصاصًا."},{"id":103,"title":"مراسلة النبي صلى الله عليه وسلم إلى المُلوكِ يَدعوهُم إلى الإسلامِ .","date":["العام الهجري :7","الشهر القمري : محرم","العام الميلادي :628"],"text":"بعدَ رُجوعِ رسولِ الله صلى الله عليه وسلم مِنَ الحُديبيةِ كتَب إلى المُلوكِ يَدعوهُم إلى الإسلامِ, ولمَّا أراد أن يُكاتِبَهُم قِيلَ له: إنَّهم لا يَقرءون كِتابًا إلَّا وعليه خاتمٌ، فاتَّخذَ النَّبيُّ صلى الله عليه وسلم خاتمًا مِن فِضَّةٍ، نَقْشُهُ: محمَّدٌ رسولُ الله، وكان هذا النَّقْشُ ثلاثةَ أَسطُرٍ: محمَّدٌ سطرٌ، ورسولُ سطرٌ، والله سطرٌ. وعن أنسِ بنِ مالكٍ رضي الله عنه قال: « فَكأنِّي بِوَبِيصِ -أو بِبَصِيصِ- الخاتمِ في إصبعِ النَّبيِّ صلى الله عليه وسلم -أو في كَفِّهِ-». واختار مِن أصحابِه رُسُلًا لهم مَعرفةٌ وخِبرةٌ، وأَرسلَهُم إلى المُلوكِ فبعَث دِحيةَ بنَ خَليفةَ الكَلبيَّ إلى قَيصرَ مَلِكِ الرُّومِ، فقَرأ الكِتابَ ولم يُسْلِمْ, وبعَث عبدَ الله بنَ حُذافةَ السَّهميَّ إلى كِسرى مَلِكِ الفُرْسِ، فلمَّا قُرِئَ الكِتابُ عليه مَزَّقَهُ، ولمَّا بلَغ ذلك رسولَ الله صلى الله عليه وسلم قال: (مَزَّقَ الله مُلْكَهُ). وقد كان كما قال, وبعَث عَمرَو بنَ أُميَّةَ الضَّمْريَّ إلى النَّجاشيِّ مَلِكِ الحَبشةِ، فلمَّا أَعطاهُ كِتابَ رسولِ الله صلى الله عليه وسلم أَخَذهُ ووَضعَهُ على عَينِه، ونزَل عن سَريرهِ على الأرضِ، وبعَث حاطِبَ بنَ أبي بَلْتَعَةَ إلى المُقَوْقِسِ مَلِكِ الإسكندريَّةِ, فأخَذ كِتابَ النَّبيِّ صلى الله عليه وسلم فجَعلهُ في حُقِّ مِن عاجٍ، وختَم عليه، ثم كتَب إلى رسولِ الله صلى الله عليه وسلم كِتابًا, ولم يُسْلِمْ, وأَهداهُ جاريتين هُما مارِيَةُ، وشيرين وسِيرينُ، وبَغلةً تُسمَّى دُلْدُلَ. وبعَث عَمرَو بنَ العاصِ السَّهميَّ إلى جَيْفَرٍ وعياد عَبَّادٍ ابْنَي الجُلُنْديِّ الأَزديِّين مَلِكَي عُمانَ، فأجابا إلى الإسلامِ جميعًا، وصدَّقا النَّبيَّ صلى الله عليه وسلم, وبعَث سَليطَ بنَ عَمرٍو أَحَدَ بني عامرِ بنِ لُؤَيٍّ إلى هَوذةَ بنِ عليٍّ الحَنفيِّ مَلِكِ اليَمامةِ, فرَدَّ عليه رَدًّا دون رَدٍّ، وكتَب إلى النَّبيِّ صلى الله عليه وسلم: (ما أحسنَ ما تدعو إليه وأَجملَهُ، والعربُ تَهابُ مَكاني، فاجعلْ لي بعضَ الأمرِ أَتَّبِعُكَ). وبعَث العَلاءَ بنَ الحَضرميِّ إلى المُنذِرِ بنِ ساوى العَبديِّ مَلكِ البَحريْنِ فلمَّا أَتاهُ كِتابُ رسولِ الله صلى الله عليه وسلم أَسلمَ, وبعَث شُجاعَ بنَ وَهْبٍ الأَسَديَّ إلى الحارثِ بنِ أبي شِمْرٍ الغسَّانيِّ مَلِكِ تُخومِ الشَّامِ, فلمَّا بلَغهُ الكِتابُ رَمى به وقال: مَن يَنزِعُ مُلكي مِنِّي؟ أنا سائرٌ إليه, ولم يُسْلِمْ. واسْتأذنَ قَيصرَ في حربِ رسولِ الله صلى الله عليه وسلم فثَنَّاهُ عن عزمِه، فأَجازَ الحارثُ شُجاعَ بنَ وَهْبٍ بالكِسْوَةِ والنَّفَقةِ، ورَدَّهُ بالحُسنى, وبعَث المُهاجرَ بنَ أبي أُميَّةَ المَخزوميَّ إلى الحارثِ بنِ عبدِ كُلالٍ الحِمْيَريِّ مَلِكِ اليَمنِ وقد أَسلمَ هو وأَخواهُ جميعًا."},{"id":104,"title":"غَزوةُ ذاتِ الرِّقاعِ .","date":["العام الهجري :7","الشهر القمري : ربيع الأول","العام الميلادي :628"],"text":"قال جابرُ بنُ عبدِ الله رضي الله عنه: خرج النَّبيُّ صلى الله عليه وسلم إلى ذاتِ الرِّقاعِ مِن نخلٍ، فلَقِيَ جمعًا مِن غَطَفانَ، فلم يكن قِتالٌ، وأخاف النَّاسُ بعضُهم بعضًا، فصَلَّى النَّبيُّ صلى الله عليه وسلم ركعتي الخوفِ، وعن أبي موسى رضي الله عنه قال: خرجنا مع النَّبيِّ صلى الله عليه وسلم في غَزوةٍ ونحن سِتَّةُ نفرٍ، بيننا بَعيرٌ نَعْتَقِبُه، فنَقِبَتْ أَقدامُنا، ونَقِبَتْ قَدمايَ، وسقَطت أَظفاري، وكُنَّا نَلُفُّ على أَرجُلِنا الخِرَقَ، فسُمِّيت غزوةَ ذاتِ الرِّقاعِ، لِما كُنَّا نَعصِبُ مِنَ الخِرَقِ على أَرجُلِنا. وحدَّث أبو موسى بهذا ثمَّ كَرِهَ ذاك، قال: ما كنتُ أصنعُ بأن أذكُرَهُ، كأنَّه كَرِهَ أن يكونَ شيءٌ مِن عملِه أَفشاهُ. وعن صالحِ بنِ خَوَّاتٍ، عمَّن شَهِدَ رسولَ الله صلى الله عليه وسلم يومَ ذاتِ الرِّقاعِ صلَّى صلاةَ الخوفِ: أنَّ طائفةً صَفَّتْ معه، وطائفةٌ وِجاهَ العَدُوِّ، فصلَّى بالتي معه ركعةً، ثمَّ ثبَت قائمًا، وأتمُّوا لأَنفُسِهم ثمَّ انصرفوا، فصَفُّوا وِجاهَ العَدُوِّ، وجاءتِ الطَّائفةُ الأُخرى فصَلَّى بهم الرَّكعةَ التي بَقِيتْ مِن صلاتِه ثمَّ ثبَت جالسًا، وأتمُّوا لأَنفُسِهم، ثمَّ سلَّم بهم. وهي غَزوةُ مُحارِبِ خَصَفَةَ وبني ثَعلبةَ مِن غَطَفانَ، وعن جابرِ بنِ عبدِ الله رضِي الله عنهما: أنَّ النَّبيَّ صلى الله عليه وسلم صلَّى بأصحابهِ في الخوفِ في غَزوةِ السَّابعةِ، غَزوةِ ذاتِ الرِّقاعِ.  وعن جابرٍ قال: صلَّى النَّبيُّ صلى الله عليه وسلم بهم يومَ مُحارِبٍ، وثَعلبةَ."},{"id":105,"title":"سَرِيَّةُ غالبِ بنِ عبدِ الله اللَّيثيِّ إلى بني المُلَوَّحِ بُقدَيْدٍ .","date":["العام الهجري :7","الشهر القمري : ربيع الأول","العام الميلادي :628"],"text":"بعَث رسولُ الله صلى الله عليه وسلم سَرِيَّةَ غالبِ بنِ عبدِ الله اللَّيثيِّ إلى بني المُلَوَّحِ بِقُدَيْدٍ، وكان بنو المُلَوَّحِ قد قَتلوا أصحابَ بشيرِ بن سُوَيْدٍ، فبُعِثت هذه السَّرِيَّةُ لأَخذِ الثَّأرِ، فشَنُّوا الغارةَ في اللَّيلِ فقَتلوا مَن قَتلوا، وساقوا النَّعَمِ، وطاردَهُم جيشٌ كَبيرٌ مِنَ العَدُوِّ، حتَّى إذا قرب مِنَ المسلمين نزل مَطَرٌ، فجاء سَيلٌ عَظيمٌ حال بين الفَريقين. ونجَح المسلمون في بَقِيَّةِ الانسِحابِ."},{"id":106,"title":"سرية زيد بن حارثة إلى أرض حِسْمى .","date":["العام الهجري :7","الشهر القمري : جمادى الآخرة","العام الميلادي :628"],"text":"أرسل الرَّسولُ صلى الله عليه وسلم بكِتابٍ إلى قَيصرِ الرُّومِ وكان حاملَ الكِتابِ هو دِحيةُ بنُ خَليفةَ الكَلبيُّ، فلمَّا كان مِن قَيصرَ ما كان أجاز دِحيةَ بنَ خَليفةَ الكَلبيَّ بمالٍ وكِسوَةٍ، ولمَّا كان دِحيةُ بحِسْمَى في الطَّريقِ لَقِيَهُ ناسٌ مِن جُذَامَ، فقَطعوها عليه، فلم يتركوا معه شيئًا، فجاء دِحيةُ إلى رسولِ الله صلى الله عليه وسلم قبلَ أن يَدخُلَ بيتَه فأخبرَهُ، فبعَث رسولُ الله صلى الله عليه وسلم زيدَ بنَ حارثةَ إلى حِسْمَى، وهي وَراءَ وادي القُرى، في خمسمائةِ رجلٍ، فشَنَّ زيدٌ الغارةَ على جُذامَ، فقَتل فيهم قتلًا ذَريعًا، واسْتاقَ نَعَمَهُم ونِساءَهُم، فأخذ مِنَ النَّعَمِ ألفَ بَعيرٍ، ومِنَ الشَّاةِ خمسةَ آلافٍ، والسَّبْيِ مائةً مِنَ النِّساءِ والصِّبيانِ. وكان بين النَّبيِّ صلى الله عليه وسلم وبين قَبيلةِ جُذامَ مُوادَعةٌ، فأسرعَ زيدُ بنُ رِفَاعةَ الجُذاميُّ أَحَدُ زُعماءِ هذه القَبيلةِ بتَقديمِ الاحْتِجاجِ إلى النَّبيِّ صلى الله عليه وسلم، وكان قد أَسلمَ هو ورِجالٌ مِن قومِه، ونَصَروا دِحيةَ حين قُطِعَ عليه الطَّريقُ، فقَبِلَ النَّبيُّ صلى الله عليه وسلم احْتِجاجَهُ، وأَمَر بِرَدِّ الغَنائمِ والسَّبْيِ."},{"id":107,"title":"سَرِيَّةُ عُمَرَ بنِ الخطَّابِ رضِي الله عنه إلى (تُرَبَةَ) طائفةٍ مِن هَوازِنَ .","date":["العام الهجري :7","الشهر القمري : شعبان","العام الميلادي :628"],"text":"بعَث رسولُ الله صلى الله عليه وسلم عُمَرَ بنَ الخطَّابِ رضِي الله تعالى عنه في ثلاثين رجلًا إلى عَجُزِ هَوازِنَ -مَحِلٌّ بينه وبين مكَّةَ أربعُ ليالٍ بطَريقِ صَنعاءَ يُقالُ له: تُرَبَةُ-. وأَرسلَ صلى الله عليه وسلم دليلًا مِن بني هِلالٍ فكان يَسيرُ اللَّيلَ ويَكْمُنُ النَّهارَ، فأتى الخبرُ لِهَوازنَ فهَربوا، فجاء عُمَرُ بنُ الخطَّابِ رضِي الله تعالى عنه مَحالَّهُم فلم يَجِدْ منهم أحدًا فانصرَف راجعًا إلى المدينةِ فلمَّا كان بِمَحِلٍّ بينه وبين المدينةِ سِتَّةُ أميالٍ قال له الدَّليلُ هل لك جَمْعٌ آخرُ مِن خَثْعَمَ؟ فقال له عُمَرُ رضِي الله تعالى عنه: لم يَأمُرْني رسولُ الله صلى الله عليه وسلم بهم، إنَّما أَمرَني بقِتالِ هَوازِنَ."},{"id":108,"title":"سَرِيَّةُ بَشيرِ بنِ سعدٍ الأَنصاريِّ إلى بني مُرَّةَ بِناحِيةِ فَدَكٍ .","date":["العام الهجري :7","الشهر القمري : شعبان","العام الميلادي :628"],"text":"بعَث رسولُ الله صلى الله عليه وسلم سَرِيَّةَ بَشيرِ بنِ سعدٍ الأَنصاريِّ إلى بني مُرَّةَ بِناحِيةِ فَدَكٍ، في ثلاثين رجلًا. وخرَج إليهم واسْتاقَ الشَّاءَ والنَّعَمَ، ثمَّ رجَع فأَدْركَهُ الطَّلَبُ عند اللَّيلِ، فرَمَوْهُم بالنَّبْلِ حتَّى فَنِيَ نَبْلُ بَشيرٍ وأصحابِه، فقُتِلوا جميعًا إلَّا بَشيرًا، فإنَّه حُمِلَ وبه رَمَقٌ إلى فَدَكٍ، فأقام عند يَهودَ حتَّى بَرَأَتْ جِراحُهُ، فرجَع إلى المدينةِ."},{"id":109,"title":"سَرِيَّةُ غالبِ بنِ عبدِ الله اللَّيثيِّ إلى بني عُوَالٍ .","date":["العام الهجري :7","الشهر القمري : رمضان","العام الميلادي :629"],"text":"بعَث رسولُ الله صلى الله عليه وسلم سَرِيَّةَ غالبِ بنِ عبدِ الله اللَّيثيِّ، إلى بني عُوَالٍ وبني عبدِ بنِ ثَعلبةَ بالمَيْفَعَةِ، وقِيلَ إلى الحُرَقَاتِ مِن جُهَيْنَةَ في مائةٍ وثلاثين رجلًا؛ فهجَموا عليهم جميعًا، وقتَلوا مَن أَشرفَ لهم، واسْتاقوا نَعَمًا وشَاءً، وفي هذه السَّرِيَّةِ قَتَلَ أُسامةُ بنُ زيدٍ نَهِيكَ بن مِرْدَاسٍ بعدَ أن قال: لا إلَه إلَّا الله. فلمَّا قَدِموا وأُخْبِرَ النَّبيُّ صلى الله عليه وسلم، كَبُرَ عليه وقال: (أَقَتلتَهُ بعدَ ما قال: لا إلَه إلَّا الله؟!). فقال: إنَّما قالها مُتَعَوِّذًا قال: (فَهَلَّا شَققتَ عن قَلبِه فتَعلمُ أَصادِقٌ هو أم كاذبٌ؟)."},{"id":110,"title":"سَرِيَّةُ عبدِ الله بنِ رَواحةَ إلى خَيبرَ لِقَتلِ يَسيرِ بنِ رِزامٍ اليَهوديِّ .","date":["العام الهجري :7","الشهر القمري : شوال","العام الميلادي :629"],"text":"بلَغ رسولَ الله صلى الله عليه وسلم أنَّ يَسيرَ بنَ رِزامٍ اليَهوديَّ يَجمعُ غَطَفانَ لِيَغزو بهم المدينةَ، فبعَث رسولُ الله صلى الله عليه وسلم عبدَ الله بنَ رَواحةَ في ثلاثين راكبًا إلى يَسيرِ بنِ رِزامٍ حتَّى أَتَوْهُ بِخَيبرَ، فقالوا: أَرسلَنا إليك رسولُ الله صلى الله عليه وسلم لِيَستعمِلَك على خَيبرَ, فلم يزالوا به حتَّى تَبِعَهُم في ثلاثين رجلًا مع كُلِّ رجلٍ منهم رَديفٌ مِنَ المسلمين، فلمَّا بلغوا قَرْقَرَةَ نِيارٍ نَدِمَ يَسيرُ بنُ رِزامٍ فأَهوى بيدِه إلى سَيفِ عبدِ الله بنِ رَواحةَ، ففَطِنَ له عبدُ الله بنُ رَواحةَ فزَجَر بَعيرَهُ ثمَّ اقْتَحَم يَسوقُ بالقَومِ، حتَّى اسْتمكَن مِن يَسيرٍ فضرَب رِجلَهُ فقطَعها، واقْتحَم يَسيرٌ وفي يدِه مِخْراشٌ مِن شَوْحَطٍ فضرَب به وَجْهَ عبدِ الله بنِ رَواحةَ فشَجَّهُ شَجَّةً مَأمومةً, وانْكفَأ كُلُّ رَجُلٍ مِنَ المسلمين على رَديفِه فقَتلهُ، غَيرَ رَجُلٍ واحدٍ مِنَ اليَهودِ أعَجزَهُم شَدًّا ولم يُصِبْ مِنَ المسلمين أحدًا، فبَصَقَ رسولُ الله صلى الله عليه وسلم في شَجَّةِ عبدِ الله بنِ رَواحةَ فلم تُقَيَّحْ ولم تُؤْذِهِ حتَّى مات."},{"id":111,"title":"سَرِيَّةُ أبي حَدْرَدٍ الأَسلميٍّ إلى الغابةِ .","date":["العام الهجري :7","الشهر القمري : ذي القعدة","العام الميلادي :629"],"text":"بعَث رسولُ الله صلى الله عليه وسلم سَرِيَّةَ أبي حَدْرَدٍ الأسلميِّ إلى الغابةِ، وسببُ ذلك أنَّ رجلًا مِن جُشَمِ بنِ مُعاويةَ أَقبلَ في عددٍ كبيرٍ إلى الغابةِ، يُريدُ أن يَجمعَ قَيسًا على مُحارَبةِ المسلمين، فبعَث رسولُ الله صلى الله عليه وسلم أبا حَدْرَدٍ مع رَجلينِ ليأتوا منه بِخَبرٍ وعِلْمٍ، فوصلوا إلى القومِ مع غُروبِ الشَّمسِ، فكَمَنَ أبو حَدْرَدٍ في ناحيةٍ، وصاحِباهُ في ناحيةٍ أُخرى، وأَبطأَ على القومِ رِاعيهِم حتَّى ذهَبتْ فَحْمَةُ العِشاءِ، فقام رَئيسُ القومِ وَحدَهُ، فلمَّا مَرَّ بأبي حَدْرَدٍ رَماهُ بِسَهمٍ في فُؤادِه فسقَط ولم يَتكلَّمْ، فاحْتَزَّ أبو حَدْرَدٍ رَأسَهُ، وشَدَّ في ناحيةِ العَسكرِ وكَبَّرَ، وكَبَّرَ صاحِباهُ وشَدَّا، فما كان مِنَ القومِ إلَّا الفِرارُ، واسْتاقَ المسلمون الثلاثةُ الكَثيرَ مِنَ الإبلِ والغَنَمِ."},{"id":112,"title":"عُمرَةُ الحُديبيةِ وتُسَمَّى (عُمرَةَ القَضاءِ) .","date":["العام الهجري :7","الشهر القمري : ذي القعدة","العام الميلادي :629"],"text":"قال ابنُ عبَّاسٍ رضِي الله عنهما: قَدِمَ رسولُ الله صلى الله عليه وسلم وأصحابُه مكَّةَ، وقد وَهَنَتْهُم حُمَّى يَثْرِبَ، قال المشركون: إنَّه يَقدُمُ عليكم غَدًا قومٌ قد وَهَنَتْهُم الحُمَّى، ولَقوا منها شِدَّةً، فجلسوا ممَّا يَلِي الحِجْرَ، وأَمرَهُم النَّبيُّ صلى الله عليه وسلم أن يَرمُلوا ثلاثةَ أَشواطٍ، ويَمشوا ما بين الرُّكنَينِ، لِيَرى المشركون جَلَدَهُم، فقال المشركون: هؤلاء الذين زَعمْتُم أنَّ الحُمَّى قد وَهَنَتْهُم، هؤلاء أَجلدُ مِن كذا وكذا. قال ابنُ عبَّاسٍ: ولم يَمنعْهُ أن يَأمُرَهُم أن يَرمُلوا الأشواطَ كُلَّها إلَّا الإبْقاءُ عليهم. وفي هذه العُمرَةِ تَزوَّجَ النَّبيُّ صلى الله عليه وسلم بمَيمونَةَ بنتِ الحارثِ رضي الله عنها."},{"id":113,"title":"سَرِيَّةُ ابنِ أبي العَوجاءِ إلى بني سُلَيْمٍ .","date":["العام الهجري :7","الشهر القمري : ذي الحجة","العام الميلادي :629"],"text":"بعَث رسولُ الله صلى الله عليه وسلم إلى بني سُلَيْمٍ سَرِيَّةِ ابنِ أبي العَوجاءِ، في خمسين رجلاً، وذلك لِيَدعُوَهُم إلى الإسلامِ؛ فقالوا: لا حاجةَ لنا إلى ما دَعوتَنا، ثمَّ قاتَلوا قِتالًا شَديدًا. جُرِحَ فيه أبو العَوجاءِ، وأُسِرَ رَجُلان مِنَ العَدُوِّ."},{"id":114,"title":"وَفاةُ زَينبَ رضِي الله عنها بنتِ رسولِ الله صلَّى الله عليه وسلَّم .","date":["العام الهجري :8","العام الميلادي :629"],"text":"هي زينبُ بنتُ رسولِ الله صلى الله عليه وسلم، وأَكبرُ أَخواتِها، تَزوَّجَها في حياةِ أمِّها ابنُ خالتِها أبو العاصِ بنُ الرَّبيعِ، فوَلدتْ له أُمامَةَ التي تَزوَّجَ بها عليُّ بنُ أبي طالبٍ بعدَ فاطمةَ، ووَلدتْ له عليَّ بنَ أبي العاصِ، أَسلمتْ زَينبُ وهاجرتْ قبلَ إسلامِ زَوجِها بسِتِّ سنين، قالت أمُّ عَطيَّةَ: لمَّا ماتتْ زَينبُ بنتُ رسولِ الله صلى الله عليه وسلم قال لنا رسولُ الله صلَّى الله عليه وسلَّم: «اغْسِلْنَها وِترًا ثلاثًا، أو خمسًا، واجْعَلْنَ في الخامسةِ كافورًا، أو شيئًا مِن كافورٍ، فإذا غَسَّلْتُنَّها، فأَعْلِمْنَني». قالت: فأَعلَمْناهُ، فأعطانا حِقْوَهُ وقال «أَشْعِرْنَها إيَّاهُ»."},{"id":115,"title":"سريَّة أَوْطاسٍ (وادٍ بين مكة والطائف) .","date":["العام الهجري :8","العام الميلادي :629"],"text":"لمَّا فرَغ النَّبيُّ صلى الله عليه وسلم مِن حُنينٍ بعَث أبا عامرٍ على جيشٍ إلى أَوْطاسٍ، فلَقِيَ دُرَيْدَ بنَ الصِّمَّةِ، فقُتِلَ دُريدٌ وهزَم الله أصحابَهُ، قال أبو موسى الأَشعريُّ: وبعَثني مع أبي عامرٍ عُبيدٍ الأَشعريِّ، فرُمِيَ أبو عامرٍ في رُكْبَتِهِ، رَماهُ جُشَمِيٌّ بِسَهمٍ فأَثْبَتَهُ في رُكبتِهِ، فانتَهيتُ إليه فقلتُ: يا عمِّ مَن رَماك؟ فأَشار إليه فقال: ذاك قاتِلي الذي رَماني. فقصدتُ له فلَحِقْتُهُ، فلمَّا رَآني وَلَّى، فاتَّبَعْتُه وجعلتُ أقولُ له: ألا تَسْتَحْيِي، ألا تَثْبُتُ، فكَفَّ، فاخْتلَفْنا ضَربتين بالسَّيفِ فقَتلتُه، ثمَّ قلتُ لأبي عامرٍ: قتَل الله صاحِبَك. قال: فانْزَعْ هذا السَّهمَ. فنَزعْتُه فنَزا منه الماءُ قال: يا ابنَ أخي أَقْرِئْ النَّبيَّ صلى الله عليه وسلم السَّلامَ، وقُلْ له: اسْتَغْفِرْ لي. واسْتخلَفني أبو عامرٍ على النَّاسِ، فمكَث يَسيرًا ثمَّ مات، فرجعتُ فدخلتُ على النَّبيِّ صلى الله عليه وسلم في بيتِه على سَريرٍ مُرْمَلٍ وعليه فِراشٌ، قد أَثَّرَ رِمالُ السَّريرِ بِظَهْرِهِ وجَنْبَيْهِ، فأَخبرتُه بخَبرِنا وخَبرِ أبي عامرٍ، وقال: قُلْ له اسْتَغْفِرْ لي. فدَعا بماءٍ فتَوضَّأَ، ثمَّ رفَع يَديهِ فقال: «اللَّهمَّ اغْفِرْ لعُبيدٍ أبي عامرٍ». ورَأيتُ بَياضَ إِبْطَيْهِ، ثمَّ قال: «اللَّهمَّ اجْعَلْهُ يومَ القِيامةِ فوقَ كَثيرٍ مِن خَلقِك مِنَ النَّاسِ». فقلتُ: وَلِي فَاسْتَغْفِرْ. فقال: «اللَّهمَّ اغْفِرْ لعبدِ الله بنِ قَيسٍ ذَنْبَهُ، وأَدْخِلْهُ يومَ القِيامةِ مُدخَلًا كَريمًا» قال أبو بُردةَ: إحداهُما لأبي عامرٍ، والأُخرى لأبي موسى."},{"id":116,"title":"إِسلامُ عَمرِو بنِ العاصِ وخالدِ بنِ الوليدِ وعُثمانَ بنِ طلحةَ رضِي الله عنهم .","date":["العام الهجري :8","الشهر القمري : صفر","العام الميلادي :629"],"text":"قال خالدُ بنُ الوليدِ: لمَّا أراد الله عزَّ وجلَّ ما أَراد مِنَ الخيرِ قذَف في قلبي الإسلامَ وحضَرني رُشدي, وقلتُ قد شَهِدتُ هذه المواطِنَ كُلَّها على محمَّدٍ صلَّى الله عليه وسلَّم فليس مَوطنٌ أَشهدُه إلَّا أَنصرِفُ وأنا أَرى في نَفْسي أنِّي في غيرِ شيءٍ وأنَّ محمَّدًا سيَظهرُ، فلمَّا خرَج رسولُ الله صلَّى الله عليه وسلَّم إلى الحُديبيةِ خَرجتُ في خيلِ المشركين فقمتُ بإزائِه في عُسْفانَ وتَعرَّضتُ له، فصلَّى بأصحابِه الظُّهرَ أمامَنا فهَمَمْنا أن نُغِيرَ عليه فلم نُمَكَّنْ منه, فصلَّى بأصحابِه صلاةَ العَصرِ صلاةَ الخَوفِ فوقع ذلك مِنَّا مَوقِعًا، وقلتُ: الرَّجلُ ممنوعٌ. فافْتَرقنا, فلمَّا صالح قُريشًا بالحُديبيةِ, ثمَّ دخَل رسولُ الله صلَّى الله عليه وسلَّم مكَّةَ في عُمرَةِ القَضاءِ طَلبَني فلم يَجِدْني، وكتَب إليَّ كِتابًا فيه: بسم الله الرَّحمن الرَّحيم أمَّا بعدُ، فإنِّي لم أَرَ أَعجبَ مِن ذِهابِ رَأيكِ عنِ الإسلامِ وعَقلِكَ, ومِثلُ الإسلامِ يَجهلُه أَحدٌ؟. ثمَّ سأل عَنِّي, فقِيلَ: له يأتي الله به. فقال: ما مِثلُه جَهِلَ الإسلامَ, ولو كان يجعل نِكايتَهُ مع المسلمين على المشركين كان خيرًا له، ولَقَدَّمْناهُ على غَيرِه. فلما جاءَني كِتابُه نَشَطْتُ للخُروجِ، وزادني رَغبةً في الإسلامِ، وسَرَّني سُؤالُه عَنِّي, فلمَّا أَجمعتُ الخُروجَ إلى رسولِ الله صلى الله عليه وسلم لَقِىيتُ عُثمانَ بنَ طلحةَ فعَرضتُ عليه الإسلامَ فأَسرعَ الإجابةَ، فخرج معي حتى انتهينا إلى الهَدةِ فوَجدْنا عَمرَو بنَ العاصِ بها, فقال: مرحبًا بالقومِ. فقُلنا: وبِكَ. قال: إلى أين مَسيرُكُم؟ قُلنا: الدُّخولُ في الإسلامِ، واتِّباعُ محمَّدٍ صلَّى الله عليه وسلَّم. فقال: وذاك الذي أَقدَمني. فاصْطحَبْنا جميعًا حتَّى دخَلنا المدينةَ, فلَبِسْتُ مِن صالحِ ثِيابي ثمَّ عَمدتُ إلى رسولِ الله صلَّى الله عليه وسلَّم, وقد أُخبِرَ بِنا فَسُرَّ بقُدومِنا, فما زال يَتَبَسَّمُ حين رآني حتَّى وَقفتُ عليه، فسَلَّمتُ عليه بالنُّبُوَّةِ فرَدَّ عليَّ السَّلامَ بوَجْهٍ طَلْقٍ، فقلتُ: إنِّي أَشهدُ أن لا إلَه إلَّا الله، وأنَّك رسولُ الله. فقال الحمدُ لله الذي هَداك، قد كنتُ أَرى لك عَقلًا رَجَوْتُ أن لا يُسْلِمَكَ إلَّا إلى خيرٍ. قلتُ: يا رسولَ الله قد رأيتَ ما كنتُ أشهدُ مِن تلك المواطنِ عليك، فادعُ الله يَغفِرُها لي. فقال صلَّى الله عليه وسلَّم: الإسلامُ يَجُبُّ ما كان قَبلَهُ."},{"id":117,"title":"سَرِيَّةُ غالبِ بنِ عبدِ الله اللَّيثيِّ إلى أَصحابِ بَشيرِ بنِ سعدٍ بفَدَكٍ .","date":["العام الهجري :8","الشهر القمري : صفر","العام الميلادي :629"],"text":"بعَث رسولُ الله صلى الله عليه وسلم إلى مُصابِ أَصحابِ بَشيرِ بنِ سعدٍ بفَدَكٍ سَرِيَّةَ غالبِ بنِ عبدِ الله، في مِائتي رجلٍ؛ فأصابوا مِن بني مُرَّةَ نَعَمًا، وقتلوا منهم قَتْلى."},{"id":118,"title":"سَرِيَّةَ كعبِ بنِ عُميرٍ الأنصاريِّ إلى بني قُضَاعَةَ .","date":["العام الهجري :8","الشهر القمري : ربيع الأول","العام الميلادي :629"],"text":"بعَث رسولُ الله صلى الله عليه وسلم سَرِيَّةَ ذاتِ أطلح بقِيادةِ كعبِ بنِ عُميرٍ الأنصاريِّ في خمسةَ عشرَ رجلًا إلى بني قُضَاعَةَ؛ حيث كانت قد حَشدتْ جُموعًا كَبيرةً للإغارَةِ على المسلمين، فلَقوا العَدُوَّ، فدَعَوْهُم إلى الإسلامِ، فلم يَستَجيبوا لهم، وأَرشَقوهُم بالنَّبْلِ حتَّى قُتِلوا كُلُّهم إلَّا رجلًا واحدًا، فقد ارْتُثَّ مِن بين القَتْلى."},{"id":119,"title":"سَرِيَّةُ شُجاعِ بنِ وَهْبٍ رضِي الله عنه إلى بني هَوازِنَ .","date":["العام الهجري :8","الشهر القمري : ربيع الأول","العام الميلادي :629"],"text":"كانت بنو هَوازِنَ قد مَدَّتْ يدَ المَعونَةِ لأعداءِ المسلمين مِرارًا, فأَرسلَ إليهم رسولُ الله صلى الله عليه وسلم شُجاعَ بنَ وَهْبٍ الأَسديَّ في خمسةٍ وعشرين رجلًا، وهم بالسِّيِّ, ناحيةَ رُكْبَةَ, مِن وراءِ المَعدِن, وهي مِنَ المدينةِ على خمسِ ليالٍ، وأَمرهُ أن يُغِيرَ عليهم, فكان يَسيرُ اللَّيلَ ويكَمُنُ النَّهارَ, حتَّى صَبَّحَهُم وهُم غارون، وقد أَوعزَ إلى أصحابِه ألَّا يُمْعِنوا في الطَّلَبِ، فأصابوا نَعَمًا كَثيرًا وشاءً, ولم يَلقوا كَيْداً, واسْتاقوا ذلك حتَّى قَدِموا المدينةَ, واقْتسَموا الغَنيمةَ, فكانت سهمانهم خمسةَ عشرَ بَعيرًا لِكُلِّ رَجلٍ, وعَدلوا البَعيرَ بِعشرٍ مِنَ الغَنَمِ، وكان مَغيبُهم خمسَ عشرةَ ليلةً."},{"id":120,"title":"غَزوةُ مُؤْتَةَ .","date":["العام الهجري :8","الشهر القمري : جمادى الأولى","العام الميلادي :629"],"text":"بعَث رسولُ الله صلى الله عليه وسلم سَرِيَّةً في ثلاثةِ آلافِ مُقاتلٍ على الجيشِ زيدُ بنُ حارثةَ، فإن أُصيبَ فجَعفرُ بنُ أبي طالبٍ، فإنْ أُصيبَ فعبدُ اللهِ بنُ رَواحةَ، وشَيَّعهُم رسولُ الله صلى الله عليه وسلم ووَدَّعهُم، ثمَّ انْصرَف ونهَضوا، فلمَّا بلغوا مَعانَ مِن أرضِ الشَّامِ، أَتاهُم الخبرُ: أنَّ هِرقلَ مَلِكَ الرُّومِ قد نزل أرضَ بني مآبٍ، -أرضَ البَلقاءِ- في مائةِ ألفٍ مِنَ الرُّومِ، ومائةِ ألفٍ أُخرى مِن نَصارى أهلِ الشَّامِ، فأقام المسلمون في مَعانَ لَيلتينِ، يتَشاوَرون في أمرِ اللِّقاءِ بِعَدُوِّهِم البالغِ مِائتي ألفٍ فقالوا: نَكتُب إلى رسولِ الله صلى الله عليه وسلم نُخبِرُهُ بعَددِ عَدُوِّنا، فيَأمُرنا بأَمرِهِ أو يُمِدُّنا. فقال عبدُ الله بنُ رَواحةَ: يا قومُ، إنَّ الذي تَكرَهون لَلَّتِي خَرجتُم تَطلُبون -يعني الشَّهادةَ- وما نُقاتِلُ النَّاسَ بِعدَدٍ ولا قُوَّةٍ، وما نُقاتِلُهُم إلَّا بهذا الذي أَكرَمَنا الله به، فانْطَلِقوا فهي إحدى الحُسْنَيينِ: إمَّا ظُهورٌ، وإمَّا شَهادةٌ. فَوافقَهُ الجيشُ على هذا الرَّأيِ ونهَضوا، حتَّى إذا كانوا بتُخومِ البَلقاءِ لَقوا بعضَ الجُموعِ التي مع هِرقلَ بالقُربِ مِن قريةٍ يُقالُ لها: مُؤْتَةُ. فاقتَتَلوا، فقُتِلَ زيدُ بنُ حارثةَ، فأخَذ الرَّايةَ جعفرُ بنُ أبي طالبٍ، فقاتَل حتَّى قُطِعَتْ يَمينُه، فأخَذ الرَّايةَ بِيُسْراهُ فقُطِعَتْ، فاحْتضَنَها فقُتِلَ كذلك، فأخَذ عبدُ الله بنُ رَواحةَ الرَّايةَ، وتَرَدَّدَ عنِ النُّزولِ بعضَ التَّرَدُّدِ، ثمَّ صَمَّمَ، فقاتَل حتَّى قُتِلَ، فأخَذ الرَّايةَ ثابتُ بنُ أَقرمَ، وقال: يا مَعشرَ المسلمين، اصْطَلِحوا على رجلٍ منكم. فقالوا: أنت. قال: لا. فاصطَلَح النَّاسُ على خالدِ بنِ الوليدِ، فلمَّا أخَذ الرَّايةَ دافَع القَومَ وحاشى بهِم، ثمَّ انْحازَ وانْحِيزَ عنه، حتَّى انْصرَف بالنَّاسِ، فتَمَكَّنَ مِنَ الانْسِحابِ بمَن معه مِنَ المسلمين، قال خالدُ بنُ الوليدِ: لقد انقْطَعَتْ في يَدي يومَ مُؤْتَةَ تِسعةُ أَسيافٍ فما بَقِيَ في يَدي إلَّا صَفيحةٌ يَمانِيَّةٌ». وهذا يقتضي أنَّهم أثْخَنوا فيهم قَتْلًا، ولو لم يكن كذلك لَما قَدَروا على التَّخَلُّصِ منهم، ولهذا السَّببِ ولِغيرِهِ ذهَب بعضُ المُحقِّقين إلى أنَّ المسلمين قد انتصروا في هذه المعركةِ ولم يُهزَموا. عن أنسٍ رضي الله عنه: أنَّ النَّبيَّ صلى الله عليه وسلم، نَعَى زيدًا، وجعفرًا، وابنَ رَواحةَ للنَّاسِ، قبلَ أن يَأتِيَهُم خَبرُهُم، فقال: «أخَذ الرَّايةَ زيدٌ فأُصيبَ، ثمَّ أخَذ جعفرٌ فأُصيبَ، ثمَّ أخَذ ابنُ رَواحةَ فأُصيبَ، وعَيناهُ تَذْرِفانِ حتَّى أخَذ سيفٌ مِن سُيوفِ الله حتَّى فتَح الله عليهم»."},{"id":121,"title":"غَزوةُ ذاتِ السَّلاسِلِ .","date":["العام الهجري :8","الشهر القمري : جمادى الآخرة","العام الميلادي :629"],"text":"كانت بعدَ غزوة مُؤْتَةَ، وسُمِّيتْ ذاتَ السَّلاسِلِ لأنَّها وقعت بالقُرْبِ مِن ماءٍ يُقالُ له: السَّلْسَلُ. بلَغ النَّبيَّ صلى الله عليه وسلم أنَّ جمعًا مِن قُضاعةَ تَجَمَّعوا وأَرادوا أن يَدنوا مِن أَطرافِ المدينةِ فَدعا النَّبيُّ صلى الله عليه وسلم عَمرَو بنَ العاصِ فعقَد له لِواءً أَبيضًا وبَعثَهُ في ثلاثمائةٍ مِن سَراةِ المُهاجرين والأنصارِ، فكان أَميرُها عَمرَو بنَ العاصِ رضي الله عنه. قال عَمرٌو: بعَث إليَّ رسولُ الله صلى الله عليه وسلم فقال: خُذْ عليك ثِيابَك وسِلاحَك ثمَّ ائْتِني. فأَتيتُه وهو يتَوضَّأُ، فصَعَّد فِيَّ النَّظرَ، ثمَّ طَأْطَأَ، فقال: إنِّي أُريدُ أن أَبعثَكَ على جَيشٍ، فيُسَلِّمَك الله ويُغْنِمَك، وأَرْغَبُ لك مِنَ المالِ رَغبةً صالِحةً، قال: قلتُ: يا رسولَ الله، ما أَسلمتُ مِن أجلِ المالِ، ولكنِّي أَسلمتُ رَغبةً في الإسلامِ، وأن أكونَ مع رسولِ الله صلى الله عليه وسلم، فقال: يا عَمرُو، نِعْمَ المالُ الصَّالحُ للمَرءِ الصَّالحِ). وفي الغَزوةِ سأَلهُ أصحابُه أن يُوقِدوا نارًا فمَنعَهُم فكَلَّموا أبا بكرٍ فكَلَّمهُ في ذلك فقال: لا يُوقِدُ أحدٌ منهم نارًا إلَّا قَذفْتُه فيها. قال: فلَقوا العَدُوَّ فهَزموهُم فأرادوا أن يَتَبَعوهُم فمنَعهُم، فلمَّا انصرَف ذلك الجيشُ ذَكَروا للنَّبيِّ صلى الله عليه وسلم وشَكَوْهُ إليه، فقال: يا رسولَ الله، إنِّي كَرِهتُ أن آذنَ لهم أن يُوقِدوا نارًا فيَرى عَدُوُّهم قِلَّتَهُم، وكَرِهتُ أن يَتْبَعُوهم فيكونُ لهم مَدَدٌ فيَعْطِفوا عليهم. فحمِد رسولُ الله صلَّى الله عليه وسلَّم أَمْرَهُ...). وفيها صلَّى عَمرٌو بالنَّاسِ وهو جُنُبٌ ومعه ماءٌ، لم يَزِدْ على أن غسَل فَرْجَهُ وتَيمَّمَ، فلمَّا قَدِمَ عَمرٌو على رسولِ الله صلى الله عليه وسلم سأَلهُ عن صلاتِه، فأَخبرَهُ فقال: والذي بعثَك بالحقِّ لو اغْتسَلتُ لَمُتُّ، لم أَجِدْ بَردًا قَطُّ مِثلَهُ، وقد قال الله عزَّ وجلَّ:  {وَلَا تَقْتُلُوا أَنْفُسَكُمْ إِنَّ اللَّهَ كَانَ بِكُمْ رَحِيمًا} [النساء: 29]، فضَحِك رسولُ الله صلى الله عليه وسلم، ولم يَقُلْ له شيئًا."},{"id":122,"title":"سَرِيَّةُ أبي عُبيدةَ بنِ الجَرَّاحِ رضِي الله عنه إلى سِيفِ البَحرِ .","date":["العام الهجري :8","الشهر القمري : رجب","العام الميلادي :629"],"text":"بعَث رسولُ اللّه صلَّى اللّه عليه وسلَّم أبا عُبيدةَ بنَ الجَرَّاحِ على رأسِ ثلاثمائةِ رجلٍ إلى سِيفِ البَحرِ, وكان الغَرَضُ مِن هذه السَّرِيَّةِ رَصْدَ عِيرٍ لقُريشٍ، ومُحارَبةَ حَيٍّ مِن جُهينةَ, وزَوَّدَهُم جِرابًا مِن تمرٍ, فجعل أبو عُبيدةَ يَقُوتُهُم إيَّاهُ, حتَّى صار إلى أن يَعُدَّهُ لهم عددًا, حتَّى كان يُعطي كُلَّ رجلٍ منهم كُلَّ يومٍ تمرةً, فقَسَمَها يومًا فنَقصَتْ تمرةٌ عن رجلٍ, فوَجَد فَقْدَها ذلك اليومَ, فلمَّا نَفَدَ ما كان معهم مِنَ الزَّادِ أَكلوا الخَبَطَ وهو وَرَقُ السَّلِمِ, فسُمِّيَ الجيشُ لذلك \"جيشَ الخَبَطِ\"، وأصابَهُم جوعٌ شَديدٌ, فنَحَرَ قيسُ بنُ سعدِ بنِ عُبادةَ -وكان أحدَ جُنودِ هذه السَّرِيَّةِ- ثلاثَ جَزائِرَ، ثمَّ نَحَرَ ثلاثَ جَزائِرَ، ثمَّ نَحَرَ ثلاثَ جَزائِرَ، ثمَّ إنَّ أبا عُبيدةَ نَهاهُ، فأَلقى إليهم البَحرُ دابَّةً يُقالُ لها: العَنْبَرُ، فأكلوا منها عِشرين ليلةً، وادَّهَنوا منه, حتَّى ثابَتْ منه أَجسامُهم، وصَلحتْ، وأخَذ أبو عُبيدةَ ضِلعًا مِن أَضلاعِه فنظَر إلى أَطولِ رجلٍ في الجيشِ وأَطولِ جَملٍ فحُمِلَ عليه ومَرَّ تَحتَهُ، وتَزوَّدوا مِن لَحمِه وَشَائِقَ، فلمَّا قَدِموا المدينةَ، أَتَوْا رسولَ الله صلى الله عليه وسلم فذَكَروا له ذلك، فقال: \"هو رِزقٌ أَخرَجهُ الله لكم، فهل معكم مِن لَحمِه شيءٌ تُطْعِمونا؟). فأَرسلوا إلى رسولِ الله صلى الله عليه وسلم منه فأَكلَهُ\"."},{"id":123,"title":"سَرِيَّةُ أبي قَتادةَ الأَنصاريِّ إلى خَضِرَة .","date":["العام الهجري :8","الشهر القمري : شعبان","العام الميلادي :629"],"text":"بعَث رسولُ الله صلى الله عليه وسلم أبا قَتادةَ بنَ رِبْعِيٍّ رضي الله عنه في سَرِيَّةٍ إلى خَضِرَة؛ وذلك لأنَّ بني غَطَفَانَ كانوا يَحْتَشِدون في خَضِرَة -وهي أرضُ مُحَارِبٍ بِنَجْدٍ- فبعَثهُ صلى الله عليه وسلم في خمسةَ عشرَ رجلًا، فقَتَلَ منهم، وسَبَى وغَنِمَ، وكانت غَيبتُه خمسَ عشرةَ ليلةً."},{"id":124,"title":"سَرِيَّةُ أبي قَتادةَ رضِي الله عنه إلى بَطْنِ إِضَمٍ .","date":["العام الهجري :8","الشهر القمري : رمضان","العام الميلادي :630"],"text":"لمَّا نَقضَتْ قُريشٌ ومَن معها العهدَ الذين الذي بينهم وبين المسلمين في الحُديبيةِ عزَم رسولُ الله صلى الله عليه وسلم على المَسيرِ إليهم، أمَر النَّاسَ بالجِهازِ وأَعلمَهُم أنَّه سائِرٌ لمكَّةَ، وقال: (اللَّهمَّ خُذِ العُيونَ والأَخبارَ عن قُريشٍ حتَّى نَبْغَتَها في بِلادِها). وزِيادةٌ في الإخفاءِ والتَّعمِيَةِ بعَث رسولُ الله صلى الله عليه وسلم سَرِيَّةً قَوامُها ثَمانيةُ رِجالٍ، تحت قِيادةِ أبي قَتادةَ بنِ رِبْعِيٍّ، إلى بَطْنِ إِضَمٍ، فيما بين ذي خَشَبٍ وذي المَروَةِ، على ثلاثةِ بُرُدٍ مِنَ المدينةِ، في أوَّلِ هذا الشَّهرِ الكريمِ؛ لِيَظُنَّ الظَّانُ أنَّه صلى الله عليه وسلم يتَوَجَّهُ إلى تلك النَّاحيةِ، ولِتذهَبَ بذلك الأَخبارُ، وواصلت هذه السَّرِيَّةُ سَيْرَها حتَّى إذا وصلت حيثما أُمِرَتْ بلَغها أنَّ رسولَ الله صلى الله عليه وسلم خرَج إلى مكَّةَ، فسارت إليه حتَّى لَحِقْتُه."},{"id":125,"title":"غَزوةُ فَتحِ مكَّةَ .","date":["العام الهجري :8","الشهر القمري : رمضان","العام الميلادي :630"],"text":"كان سببُها أنَّ المشركين نقَضوا العهدَ الذي بينهم وبين رسولِ الله صلى الله عليه وسلم، فأَغاروا على إحدى القَبائلِ المُحالفةِ للرَّسولِ عليه الصَّلاةُ والسَّلامُ، وهي قَبيلةُ خُزاعةَ، ولمَّا عَلِمَ النَّبيُّ صلى الله عليه وسلم بالأَمرِ أَمَرَ النَّاسَ بالتَّجَهُّزِ دون أن يُخبِرَهُم بوِجْهَتِه، ثمَّ مضى حتَّى نزَل بمَرِّ الظَّهرانِ وهو وادٍ قَريبٌ مِن مكَّةَ. فعنِ ابنِ عبَّاسٍ رضِي الله عنهما: أنَّ النَّبيَّ صلى الله عليه وسلم خرَج في رَمضانَ مِنَ المدينةِ ومعه عشرةُ آلافٍ، وذلك على رأسِ ثمانِ سِنين ونِصفٍ مِن مَقْدَمِه المدينةَ، فسار هو ومَن معه مِنَ المسلمين إلى مكَّةَ، يَصومُ ويَصومون، حتَّى بلَغ الكَدِيدَ، وهو ماءٌ بين عُسْفانَ، وقُدَيْدٍ أَفطَر وأَفطَروا. وكان أبو سُفيانَ قد رَأى جيشَ النَّبيِّ صلى الله عليه وسلم قبلَ دُخولِه مكَّةَ، فهالَهُ ما رَأى، ثمَّ أَسلَم في أثناءِ ذلك، ثمَّ جاء إلى قومِه وصرَخ فيهم مُحذِّرًا لهم بأن لا قِبَلَ لهم بِجيشِ محمَّدٍ صلى الله عليه وسلم، وقال لهم ما قاله عليه الصَّلاةُ والسَّلامُ: مَن دخَل دارَ أبي سُفيانَ فهو آمِن، ومَن أَغلَق عليه دارَهُ فهو آمِن، ومَن دخَل المسجِدَ فهو آمِن. فتَفرَّقَ النَّاسُ إلى دورِهِم وإلى المسجِدِ. وعن عائشةَ رضي الله عنها: أنَّ النَّبيَّ صلى الله عليه وسلم دخَل عامَ الفتحِ مِن كَداءٍ التي بأعلى مكَّةَ. وقد أَهدَر النَّبيُّ صلى الله عليه وسلم دَمَ بعضِ المشركين يومَ الفتحِ، ووجَد عليه الصَّلاةُ والسَّلامُ حولَ البيتِ ثلاثمائةٍ وسِتِّين نُصُبًا، فجعل يَطعنُها بِعودٍ في يَدِه ويقولُ: (جاء الحقُّ وزَهَقَ الباطلُ، جاء الحقُّ، وما يُبْدِئُ الباطلُ وما يُعيدُ). وقد تَفاوَتت الرِّواياتُ في مُدَّةِ إقامتِه صلى الله عليه وسلم عامَ الفتحِ، و الأرجحُ -والله أعلم- أنَّها كانت تِسعةَ عشرَ يومًا."},{"id":126,"title":"سَرِيَّةُ خالدِ بنِ الوليدِ رضِي الله عنه إلى العُزَّى بنَخْلَةَ .","date":["العام الهجري :8","الشهر القمري : رمضان","العام الميلادي :630"],"text":"لمَّا اطْمأَنَّ رسولُ الله صلى الله عليه وسلم بعدَ الفتحِ بعَث خالدَ بنَ الوليدِ إلى العُزَّى لخمسِ ليالٍ بَقِينَ مِن هذا الشَّهرِ الكريمِ لِيَهدِمَها، وكانت بِنَخْلَةَ، وكانت لقُريشٍ وجميعِ بني كِنانةَ, وهي أَعظمُ أَصنامِهم. وكان سَدَنَتُها بني شَيبانَ؛ فخرَج إليها خالدٌ في ثلاثين فارسًا حتَّى انتهى إليها فهَدمَها. ولمَّا رجَع إليها سألهُ رسولُ الله صلى الله عليه وسلم (هل رأيتَ شيئًا؟). قال: لا. قال: (فإنَّك لم تَهدِمْها فارجِعْ إليها فاهْدِمْها). فرجع خالدٌ مُتَغَيِّظًا قد جَرَّدَ سَيفَهُ فخَرجتْ إليه امرأةٌ عُريانةٌ سَوداءُ ناشِرَةُ الرَّأسِ، فجعَل السَّادِنُ يَصيحُ بها، فضربها خالدٌ فجزَلها بِاثْنتَينِ، ثمَّ رجَع إلى رسولِ الله صلى الله عليه وسلم فأخبرَهُ، فقال: (نعم، تلك العُزَّى، وقد أَيِسَتْ أن تُعْبَدَ في بلادِكُم أبدًا)."},{"id":127,"title":"سَرِيَّةُ عَمرِو بنِ العاصِ رضِي الله عنه إلى سُواعٍ، صَنَمِ هُذيلٍ .","date":["العام الهجري :8","الشهر القمري : رمضان","العام الميلادي :630"],"text":"بعَث رسولُ الله صلى الله عليه وسلم عَمرَو بنَ العاصِ إلى سُواعٍ لِيَهدِمَهُ، وسُواعٌ صَنَمٌ لقومِ نوحٍ عليه السَّلامُ، ثمَّ صار بعدَ ذلك لقَبيلةِ هُذيلٍ المُضَريَّةِ, وظَلَّ هذا الوَثَنُ مَنصوبًا تَعبُدهُ هُذيلٌ وتُعَظِّمُهُ, حتَّى إنَّهم كانوا يَحُجُّون إليه حتَّى فُتِحَتْ مكَّةُ ودخلَت هُذيلٌ فيمَن دخَل في دينِ الله أفواجًا، وكان مَوضعُه بِرُهاطٍ على قُرابةِ 150 كيلو مترًا شمالَ شرقيِّ مكَّةَ، فلمَّا انتهى إليه عَمرٌو قال له السَّادِنُ: ما تُريدُ؟ قال: أمَرني رسولُ الله صلَّى الله عليه وسلَّم أن أَهدِمَهُ. قال: لا تَقدِرُ على ذلك. قال: لِمَ ؟ قال تُمْنَعُ. قال: حتَّى الآنَ أنت على الباطلِ؟ وَيْحَكَ فهل يَسمعُ أو يُبصِرُ؟ ثم دَنا فكسَرهُ، وأمَر أصحابَهُ فهدموا بيتَ خَزانَتِهِ فلم يَجِدوا فيه شيئًا، ثمَّ قال للسَّادِنِ: كيف رأيتَ؟ قال: أَسلمتُ لله."},{"id":128,"title":"سَرِيَّةُ خالدِ بنِ الوليدِ رضِي الله عنه إلى بني جَذِيمَةَ .","date":["العام الهجري :8","الشهر القمري : شوال","العام الميلادي :630"],"text":"لمَّا رجَع خالدُ بنُ الوليدِ مِن هَدْمِ العُزَّى بعَثهُ رسولُ الله صلى الله عليه وسلم إلى بني جَذيمَةَ داعِيًا إلى الإسلامِ لا مُقاتِلًا, فخرَج في ثلاثمائةٍ وخمسين رجلًا مِنَ المُهاجرين والأنصارِ وبني سُليمٍ، فانتهى إليهم فدَعاهُم إلى الإسلامِ فلم يُحسِنوا أن يَقولوا: أَسلَمْنا، فجعلوا يَقولون: صَبَأْنا، صَبَأْنا. -فحملها خالد على أنها سُخرية بالإسلام لأن قريشًا كانت تقول لمن أسلم صبأ تعييرا له- فجعَل خالدٌ يَقتُلُهم ويَأْسِرُهُم, ودفَع إلى كُلِّ رجلٍ ممَّن كان معه أَسِيرًا، فأمَر يومًا أن يَقتُلَ كُلُّ رجلٍ أَسِيرَهُ, فأبى ابنُ عُمَرَ وأصحابُه حتَّى قَدِموا على النَّبيِّ صلى الله عليه وسلم فذكَروا له، فرفَع صلى الله عليه وسلم يَديهِ وقال: (اللَّهمَّ إنِّي أَبْرَأُ إليك ممَّا صنَع خالدٌ) مَرَّتين. وكانت بنو سُليمٍ هُم الذين قَتَلوا أَسْراهُم دون المُهاجرين والأنصارِ, وبعَث رسولُ الله صلى الله عليه وسلم علِيًّا, فَوَدَى لهم قَتلاهُم وما ذهَب منهم."},{"id":129,"title":"غزوة الطَّائفِ بعد أن حاصرها المسلمون أربعين ليلة .","date":["العام الهجري :8","الشهر القمري : شوال","العام الميلادي :630"],"text":"بعدَ أن تَعقَّبَ المسلمون فُلولَ الهارِبين مِن هَوازِنَ في أَوْطاسٍ ونَخْلةَ، تَوجَّهوا للقَضاءِ على ثَقيفٍ التي فَرَّتْ مِن حُنينٍ وأَوْطاسٍ، وتَحصَّنتْ بحُصونِها المَنيعَةِ في الطَّائفِ، وفي صَحيحِ مُسلمٍ: أنَّ الرَّسولَ صلى الله عليه وسلم ومَن معه مِنَ المسلمين حاصروا المشركين في الطَّائفِ أربعين ليلةً.عن أبي نَجيحٍ السُّلميِّ قال: حاصَرْنا مع نَبيِّ الله صلَّى الله عليه وسلَّم حِصْنَ الطَّائفِ فسمعتُ رسولَ الله صلَّى الله عليه وسلَّم يقولُ: مَن بلَغ بِسَهْمٍ فَلهُ دَرجةٌ في الجنَّةِ. قال: فبلَغتُ يَومئذٍ سِتَّةَ عشرَ سَهْمًا.....). وقد هرَب مِن ذلك الحِصنِ إلى رسولِ الله صلى الله عليه وسلم ثلاثةٌ وعشرون رجلًا، عن عبدِ الله بنِ عُمَرَ، قال: لمَّا حاصَر رسولُ الله صلَّى الله عليه وسلَّم الطَّائفَ، فلم يَنَلْ منهم شيئًا قال: «إنَّا قافِلون إن شاء الله. فثَقُلَ عليهم، وقالوا: نَذهبُ ولا نَفتَحُه. فقال: «اغْدوا على القِتالِ». فغَدَوْا فأَصابَهم جِراحٌ، فقال: «إنَّا قافِلون غَدًا إن شاء الله». فأَعجبَهُم، فضَحِكَ النَّبيُّ صلى الله عليه وسلم."},{"id":130,"title":"غَزوةُ حُنينٍ (هَوازِنَ) .","date":["العام الهجري :8","الشهر القمري : ذي القعدة","العام الميلادي :630"],"text":"حُنينُ: وادٍ إلى جَنبِ ذي المَجازِ، قريبٌ مِنَ الطَّائفِ، وبينه وبين مكَّةَ بضعةَ عشرَ مِيلًا مِن جِهَةِ الشرائع والسيل الكبير، وقِيلَ سُمِّيَ بِحُنَيْنٍ؛ نِسبَةً إلى رَجلٍ يُدعَى: حُنينَ بنَ قابِثَةَ بنِ مَهْلائِيلَ. وكان النَّبيُّ صلى الله عليه وسلم قد أقامَ بمكَّةَ 19 يومًا، حتَّى جاءَتْ هَوازِنُ وثَقيفٌ فنزلوا بحُنينٍ يُريدون قِتالَ النَّبيِّ صلى الله عليه وسلم، وكانوا قد جمَعوا قبلَ ذلك حين سَمِعوا بمَخرجِ رسولِ الله صلَّى الله عليه وسلَّم مِنَ المدينةِ، وهُم يَظنُّون أنَّه إنَّما يُريدُهم، فلمَّا أَتاهُم أنَّه قد نزَل مكَّةَ، أخَذوا في الاسْتِعدادِ لِمُواجهَتِه، وقد أَرادوها مَوقِعَةً حاسِمةً، فحَشدوا الأموالَ والنِّساءَ والأَبناءَ حتَّى لا يَفِرَّ أَحدُهم ويَترك أهلَهُ ومالَهُ، وكان يَقودُهم مالكُ بنُ عَوفٍ النَّضْريُّ، واسْتنفَروا معهم غَطَفانَ وغيرَها. فاسْتعَدَّ الرَّسولُ صلى الله عليه وسلم لِمُواجَهتِهم، فاسْتَعارَ مِن يَعْلى بنِ أُميَّةَ ثلاثين بَعيرًا وثلاثين دِرْعًا، واسْتَعارَ مِن صَفوانَ بنِ أُميَّةَ مائةَ دِرْعٍ، واسْتعمَل عَتَّابَ بنَ أَسِيدِ بنِ أبي العاصِ أَميرًا على مكَّةَ، وقد ثبَت في الصَّحيحين أنَّ الطُّلقاءَ قد خرَجوا معه إلى حُنينٍ. واسْتقبَل الرَّسولُ صلى الله عليه وسلم بجَيشِه وادِيَ حُنينٍ في عَمايَةِ الصُّبْحِ، وانْحَدروا فيه، وعند دُخولِهم إلى الوادي حَملوا على هَوازِنَ فانْكشَفوا، فأَكَبَّ المسلمون على ما تَركوهُ مِن غَنائِمَ، وبينما هُم على هذه الحالِ اسْتقبَلَتْهُم هَوازِنُ وأَمطَرتْهُم بِوابِلٍ مِنَ السِّهامِ، ولم يكنْ المسلمون يَتوقَّعون هذا فضاقَتْ عليهم الأَرضُ بما رَحُبَتْ، فوَلَّوْا مُدْبِرين لا يَلْوِي أحدٌ على أحدٍ، وانْحازَ الرَّسولُ صلى الله عليه وسلم ذاتَ اليَمينِ وهو يقولُ: (أين النَّاسُ؟ هَلُمُّوا إليَّ، أنا رسولُ الله، أنا رسولُ الله، أنا محمَّدُ بنُ عبدِ الله). وأمَر الرَّسولُ صلى الله عليه وسلم عَمَّهُ العبَّاسَ -وكان جَهْوَرِيَّ الصَّوتِ- أن يُنادِيَ النَّاسَ بالثَّباتِ، وخَصَّ منهم أصحابَ بَيعةِ الرِّضوانِ، فأَسرَعوا إليه، ثمَّ خَصَّ الأَنصارَ بالنِّداءِ، ثمَّ بني الحارثِ بنِ الخَزرجِ، فطاروا إليه قائِلِين: لَبَّيْكَ، لَبَّيْكَ. ودارت المَعركةُ قَويَّةً ضِدَّ هَوازِنَ، وقال الرَّسولُ صلى الله عليه وسلم عندما رأى المَعركةَ تَشْتَدُّ: (هذا حين حَمِيَ الوَطيسُ). ثمَّ أخَذ حَصَياتٍ -أو تُرابا- فرَمى به وُجوهِ الكُفَّارِ وهو يقولُ: (شاهَتِ الوُجوهُ). فما خلَق الله تعالى منهم إنسانًا إلَّا مَلأَ عَينَيْهِ تُرابًا بتلك القَبضةِ، فوَلَّوْا مُدْبِرين، والرَّسولُ صلى الله عليه وسلم يقولُ: (انْهزَموا ورَبِّ محمَّدٍ)، وفي رِوايةٍ أُخرى: (انْهزَموا ورَبِّ الكَعبةِ, انْهزَموا ورَبِّ الكَعبةِ). وقد رُوِيَ: أنَّ قَتْلى بني مالكٍ مِن ثَقيفٍ لِوَحدِها قد بلَغ 70 قَتيلًا، وقُتِلَ بأَوْطاسٍ مِن بني مالكٍ 300، وقُتِلَ خُلَقٌ كَثيرٌ مِن بني نَصرِ بنِ مُعاوِيَةَ ثمَّ مِن بني رِئابٍ، ورُوِيَ: أنَّ سَبْيَ حُنينٍ قد بلَغ 6000 مِنَ النِّساءِ والأَبناءِ. بينما قُتِلَ مِنَ المسلمين أربعةٌ."},{"id":131,"title":"عُمرَةُ الجِعْرانَةِ .","date":["العام الهجري :8","الشهر القمري : ذي القعدة","العام الميلادي :630"],"text":"ثبَت أنَّ النَّبيَّ صلى الله عليه وسلم اعْتمَرَ مِنَ الجِعْرانةِ عامَ حُنينٍ، وهذه العُمرَةُ هي الثَّالثةُ بعدَ عُمرَةِ الحُديبيَةِ وعُمرَةِ القَضاءِ. قال ابنُ حَجَرٍ: فإنَّه صلى الله عليه وسلم أَحرَمَ مِنَ الجِعْرانةِ ودخَل مكَّةَ ليلًا فقَضى أمْرَ العُمرَةِ ثمَّ رجَع ليلًا فأَصبحَ بالجِعْرانةِ كَبائِتٍ. قال إبراهيمُ النَّخَعيُّ: كانوا يَستَحِبُّون أن يَدخلوا مكَّةَ نهارًا ويَخرُجوا منها ليلًا. وعن عطاءٍ: إن شِئْتُم فادْخُلوا ليلًا إنَّكم لَستُم كرسولِ الله صلى الله عليه وسلم، إنَّه كان إمامًا فأَحَبَّ أن يَدخُلَها نهارًا لِيَراهُ النَّاسُ. انتهى. وقَضيَّةُ هذا أنَّ مَن كان إمامًا يُقْتَدى به اسْتُحِبَ له أن يَدخُلَها نهارًا."},{"id":132,"title":"وَفاةُ أمِّ كُلثومٍ بنتِ رسولِ الله صلَّى الله عليه وسلَّم .","date":["العام الهجري :9","العام الميلادي :630"],"text":"هي أمُّ كُلثومٍ بنتُ رسولِ الله صلى الله عليه وسلم- البَضْعَةُ الرَّابعةُ النَّبَوِيَّةُ، أمُّها خَديجةُ بنتُ خُويلدٍ رضي الله عنها، يُقالُ تَزوَّجها عُتَيْبةُ بنُ أبي لَهبٍ ثمَّ فارَقَها، وأَسلَمتْ وهاجَرتْ بعدَ النَّبيِّ صلى الله عليه وسلم، فلمَّا تُوفِّيتْ أُختُها رُقيَّةُ تزَوَّجَ بها عُثمانُ في رَبيعٍ الأوَّلِ سَنةَ ثلاثٍ فلم تَلِدْ له."},{"id":133,"title":"عامُ الوُفودِ .","date":["العام الهجري :9","العام الميلادي :630"],"text":"كان مِن أَبرَزِ نَتائجِ فَتحِ مكَّةَ أن أَخذتْ قَبائلُ العربِ وأَفرادُها يُبادِرون بإسلامِهم؛ لأنَّهم كانوا يَنتظِرون نَتيجةَ الصِّراعِ بين المسلمين وقُريشٍ، فعن عَمرِو بنِ سَلمةَ قال: كُنَّا بماءٍ مَمَرَّ النَّاسِ، وكان يَمُرُّ بِنا الرُّكبانُ فنسألُهم: ما للنَّاسِ، ما للنَّاسِ؟ ما هذا الرَّجلُ؟ فيقولون: يَزعُم أنَّ الله أَرسلَهُ، أَوْحى إليه -أو: أَوْحى الله بكذا- فكنتُ أَحفظُ ذلك الكلامَ، وكأنَّما يُقَرُّ في صدري، وكانتِ العربُ تَلَوَّمُ بإسلامِهم الفَتحَ، فيَقولون: اتْرُكوهُ وقَومَهُ، فإنَّه إن ظهَر عليهم فهو نَبِيٌّ صادِقٌ. فلمَّا كانت وَقعةُ أهلِ الفَتحِ بادَر كُلُّ قومٍ بإسلامِهم، وبَدَرَ أبي قومي بإسلامِهم."},{"id":134,"title":"نزول فريضة الحج .","date":["العام الهجري :9","العام الميلادي :630"],"text":"كان الحَجُّ مَعروفًا قبلَ البعثة، فإبراهيمُ أَذَّنَ في النَّاسِ بالحَجِّ، وحَجَّ موسى وغيرُه مِنَ الأنبياءِ، وبَقِيَ الحَجُّ مَعروفًا ولكن بَدَّلَ فيه المُشركون ما بَدَّلوا، وأَوَّلُ مَن بَدَّلَ عَمرُو بنُ لُحَيٍّ، ثمَّ فرَض الله تعالى الحَجَّ على المسلمين لِمَن اسْتَطاع إليه سَبيلًا، {وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا} [آل عمران: 97]، وبَيَّن الرَّسولُ صلى الله عليه وسلم مَناسِكَهُ بِتَمامِها في حَجَّةِ الوَداعِ في سَنَةِ 10هـ، واخْتُلِف في أيِّ عامٍ فُرِضَ الحَجُّ، قِيلَ: فُرِضَ في سَنَةِ سِتٍّ. وقِيلَ: سَنَةَ سبعٍ. وقِيلَ: سَنَةَ ثَمانٍ. وقِيلَ غيرَ ذلك."},{"id":135,"title":"وَفاةُ النَّجاشِيِّ صاحِبِ الحَبشةِ رضِي الله عنه .","date":["العام الهجري :9","الشهر القمري : رجب","العام الميلادي :630"],"text":"هو أَصْحَمَةُ بنُ أَبْجَرَ مَلِكُ الحَبشةِ، والنَّجاشيُّ لَقبٌ له ولمُلوكِ الحَبشةِ، ومَعْنى: أَصْحَمَةَ: عَطِيَّةُ، وقِيلَ: عَطِيَّةُ الله، وقِيلَ: عَطاءٌ.تَوَلَّى الحُكمَ بعدَ مَوتِ عَمِّهِ، وبعدَ سَنواتٍ مِن حُكمِهِ وانتشر وانْتِشارِ عَدْلِه أَسلمَ في عَهدِ النَّبيِّ صلى الله عليه وسلم، وأَحسنَ إلى المسلمين الذين هاجَروا إلى أَرضِه، قال رسولُ الله صلَّى الله عليه وسلَّم لأَصحابِه عن النَّجاشيِّ: لو خَرجتُم إلى أرضِ الحَبشةِ فإنَّ بها مَلِكًا لا يُظْلَمُ عنده أحدٌ، وهي أرضُ صِدْقٍ، حتَّى يَجعلَ الله لكم فَرَجًا. ولمَّا ماتَ صلَّى عليه النَّبيُّ صلى الله عليه وسلم بالمدينةِ صَلاةَ الغائِبِ، فعن أبي هُريرةَ رضي الله عنه: أنَّ رسولَ الله صلى الله عليه وسلم نَعى لهم النَّجاشيَّ صاحِبَ الحَبشةِ، في اليَومِ الذي مات فيه، وقال: «اسْتَغْفِروا لأَخيكُم». وعن جابرٍ رضي الله عنه: قال النَّبيُّ صلى الله عليه وسلم حين مات النَّجاشيُّ: «مات اليَومَ رَجلٌ صالِحٌ، فقوموا فصَلُّوا على أَخيكُم أَصْحَمَةَ»."},{"id":136,"title":"غَزوةُ تَبوكَ وجَيشُ العُسْرَةِ .","date":["العام الهجري :9","الشهر القمري : رجب","العام الميلادي :630"],"text":"تَبوكُ مَوضِعٌ بين وادي القُرى والشَّامِ، قال أبو موسى الأَشعريُّ رضي الله عنه: (أَرسلَني أَصحابي إلى رسولِ الله صلى الله عليه وسلم أَسأَلُه الحُمْلانَ لهم إذ هُم معه في جَيشِ العُسْرَةِ، وهي غَزوةُ تَبوكَ..). وحديث أبي موسى رضي الله عنه فيه دِلالةٌ على ما كان عليه الصَّحابةُ مِنَ العُسْرِ الشَّديدِ في المالِ والزَّادِ والرَّكائِبِ، كما رَوى مُسلمٌ أيضًا عن أبي هُريرةَ رضي الله عنه ما وقع للمسلمين في طَريقِ هذه الغَزوةِ مِن نَقْصٍ في الزَّادِ حتَّى مَصُّوا النَّوَى وشَرِبوا عليه الماءَ، وفي رِوايةٍ أُخرى لمُسلمٍ: أنَّهم اسْتأذَنوا الرَّسولَ صلى الله عليه وسلم في نَحْرِ مَطاياهُم لِيأكُلوا. وقد قال الله تعالى: {لَقَدْ تَابَ اللَّهُ عَلَى النَّبِيِّ وَالْمُهَاجِرِينَ وَالْأَنْصَارِ الَّذِينَ اتَّبَعُوهُ فِي سَاعَةِ الْعُسْرَةِ} [التوبة: 117]. قال ابنُ كَثيرٍ: فعزَم رسولُ الله صلى الله عليه وسلم على قِتالِ الرُّومِ؛ لأنَّهم أَقربُ النَّاسِ إليه؛ وأَوْلى النَّاسِ بالدَّعوَةِ إلى الحقِّ لقُربِهِم إلى الإسلامِ وأَهلِه، وقد قال الله تعالى: {يَاأَيُّهَا الَّذِينَ آمَنُوا قَاتِلُوا الَّذِينَ يَلُونَكُمْ مِنَ الْكُفَّارِ وَلْيَجِدُوا فِيكُمْ غِلْظَةً وَاعْلَمُوا أَنَّ اللَّهَ مَعَ الْمُتَّقِينَ} [التوبة: 123]. وقد بَيَّنَ صلى الله عليه وسلم وِجْهَةَ هذه الغَزوةِ، فعن مُعاذٍ رضي الله عنه: أنَّ رسولَ الله صلى الله عليه وسلم قال: (سَتأْتون غدًا إن شاء الله عَيْنَ تَبوكَ، وإنَّكم لن تَأْتوها حتَّى يَضْحى النَّهارُ، فمَن جاءَها مِنكم فلا يَمَسَّ مِن مائِها شيئًا حتَّى آتي). والمشهورُ والرَّاجحُ أنَّ جَيشَ تَبوكَ كان ثلاثين ألفًا، ولكنَّ الرَّسولَ صلَّى الله عليه وسلَّم لم يَلْقَ حَربًا مِنَ الأعداءِ، فرجَع إلى المدينةِ مُنتصِرًا بعدَ أن أقامَ بتَبوكَ عِشرين ليلةً."},{"id":137,"title":"وَفاةُ رَأْسِ المُنافقين عبدِ الله بنِ أُبَيٍّ بن ابنِ سَلولَ .","date":["العام الهجري :9","الشهر القمري : ذي القعدة","العام الميلادي :631"],"text":"هو عبدُ الله بنُ أُبَيٍّ بن ابنُ سَلولَ، رَأْسُ المُنافقين، مَرِضَ في ليالٍ بَقِينَ مِن شَوَّالٍ بعدَ أن رجَع رسولُ الله صلى الله عليه وسلم مِن غَزوةِ تَبوكَ, ولمَّا مات اسْتَغفَرَ له رسولُ اللّه صلى الله عليه وسلم، وصلَّى عليه بعدَ أن حاوَلَ عُمَرُ مَنْعَهُ عن الصَّلاةِ عليه، وقد نزَل القُرآنُ بعدَ ذلك بِمُوافَقَةِ عُمَرَ رضي الله عنه، وإنَّما صلَّى عليه رسولُ الله صلى الله عليه وسلم إجراءً له على حُكمِ الظَّاهرِ وهو الإسلامُ؛ ولِما فيه مِن مَصلَحةٍ شَرعيَّةٍ؛ وهو تَأليفُ قُلوبِ قَومِه وتابِعيهِ، فقد كان يَدِينُ له بالوَلاءِ فِئَةٌ كَبيرةٌ مِنَ المُنافقين، فعسى أن يَتأثَّروا ويَرجِعوا عن نِفاقِهم ويَعتبِروا ويُخلِصوا لله ولِرسولِهِ."},{"id":138,"title":"حَجَّةُ أبي بكرٍ الصِّدِّيقِ ونُزولُ سُورةِ بَراءَة .","date":["العام الهجري :9","الشهر القمري : ذي الحجة","العام الميلادي :631"],"text":"بعَث النَّبيُّ صلى الله عليه وسلم أبا بكرٍ أَميرًا على الحَجِّ بعدَ انْسِلاخِ ذي القَعدةِ لِيُقيمَ للمسلمين حَجَّهُم -والنَّاسُ مِن أهلِ الشِّركِ على مَنازِلهم مِن حَجِّهِم- فخرَج أبو بكرٍ رضِي الله عنه ومَن معه مِنَ المسلمين، وقد بعَث عليه الصَّلاةُ والسَّلامُ عَلِيًّا رضي الله عنه بعدَ أبي بكرٍ الصِّدِّيقِ رضي الله عنه لِيكونَ معه، ويَتوَلَّى علِيٌّ بِنَفْسِه إبلاغَ البَراءةِ إلى المشركين نِيابَةً عن رسولِ الله صلى الله عليه وسلم لِكونِهِ ابنَ عَمِّهِ، مِن عَصَبَتِهِ، قال أبو هُريرةَ: بعَثَني أبو بكرٍ في تلك الحَجَّةِ في مُؤَذِّنين يَومَ النَّحْرِ، نُؤَذِّنُ بمِنًى: أن لا يَحُجَّ بعدَ العامِ مُشركٌ، ولا يَطوفَ بالبيتِ عُريانٌ. قال حُميدُ بنُ عبدِ الرَّحمنِ: ثمَّ أَردَفَ رسولُ الله صلى الله عليه وسلم عَلِيًّا، فأَمَرهُ أن يُؤَذِّنَ ببَراءَة. قال أبو هُريرةَ: فأَذَّنَ مَعَنا علِيٌّ في أهلِ مِنًى يَومَ النَّحْرِ: لا يَحُجُّ بعدَ العامِ مُشرِكٌ، ولا يَطوفُ بالبيتِ عُريانٌ. قال حميد بن عبد الرحمن: ثم أردف رسول الله صلى الله عليه وسلم عليا، فأمره أن يؤذن ببراءة."},{"id":139,"title":"تَتابُعُ الوُفودِ إلى النَّبيِّ صلَّى الله عليه وسلَّم .","date":["العام الهجري :10","العام الميلادي :631"],"text":"بَقِيَتِ الوُفودُ تَتابَعُ إلى رسولِ الله صلَّى الله عليه وسلَّم، وكان بينها وَفْدُ نَصارى نَجْرانَ، ومصالحتهم وصالَحَهُم على الجِزْيَةِ، وجعَل لهم ذِمَّةً."},{"id":140,"title":"وَفاةُ إبراهيمَ ابنِ النَّبيِّ صلَّى الله عليه وسلَّم .","date":["العام الهجري :10","العام الميلادي :631"],"text":"إبراهيمُ ابنُ النَّبيِّ صلى الله عليه وسلم، وأمُّهُ مارِيَةُ القِبْطِيَّةُ، وقد كان جَميعُ أَولادِ النَّبيِّ صلى الله عليه وسلم مِن خَديجةَ رضي الله عنها، ما عَدا إبراهيمَ فمِن مارِيَةَ القِبطيَّةِ المِصريَّةِ رضي الله عنها، قال أنسُ بنُ مالكٍ رضي الله عنه: «ما رَأيتُ أحدًا كان أَرحمَ بالعِيالِ مِن رسولِ الله صلى الله عليه وسلم. قال: كان إبراهيمُ مُسْتَرْضِعًا له في عَوالي المَدينةِ، فكان يَنطلِقُ ونحن معه فيَدخُلُ البيتَ وإنَّه لَيُدَخَّنُ، وكان ظِئْرُهُ قَيْنًا، فيَأخُذهُ فيُقَبِّلُهُ، ثمَّ يَرجِع. قال عَمرٌو: فلمَّا تُوفِّيَ إبراهيمُ قال رسولُ الله صلَّى الله عليه وسلَّم: «إنَّ إبراهيمَ ابْنِي، وإنَّه مات في الثَّدْيِ، وإنَّ له لَظِئْرَيْنِ تُكَمِّلانِ رَضاعَهُ في الجنَّةِ». عن المُغيرةِ بنِ شُعبةَ قال: كَسَفتِ الشَّمسُ على عَهدِ رسولِ الله صلَّى الله عليه وسلَّم يَومَ مات إبراهيمُ، فقال النَّاسُ: كَسَفتِ الشَّمسُ لِمَوتِ إبراهيمَ. فقال رسولُ الله صلى الله عليه وسلم: «إنَّ الشَّمسَ والقَمرَ لا يَنْكَسِفانِ لِمَوتِ أَحدٍ ولا لِحَياتِه، فإذا رَأيْتُم فصَلُّوا، وادْعوا الله». عن أبي بَكرةَ قال: خَسَفتِ الشَّمسُ على عَهدِ رسولِ الله صلى الله عليه وسلم فخرَج يَجُرُّ رِداءَهُ حتَّى انْتَهى إلى المسجدِ، وَثابَ النَّاسُ إليه، فصلَّى بهم رَكعتينِ، فانْجَلتِ الشَّمسُ، فقال: «إنَّ الشَّمسَ والقَمرَ آيتانِ مِن آياتِ الله، وإنَّهما لا يَخْسِفانِ لِمَوتِ أَحدٍ، وإذا كان ذاك فصَلُّوا وادْعوا حتَّى يُكْشَفَ ما بكم». وذاك أنَّ ابْنًا للنَّبيِّ صلى الله عليه وسلم مات يُقالُ له: إبراهيمُ. فقال النَّاسُ في ذاك. وُلِدَ له إبراهيمُ بالمدينةِ مِن سُرِّيَّتِهِ مارِيَةَ القِبطيَّةِ، سَنَةَ ثَمانٍ مِن الهِجرةِ، وبَشَّرَهُ به أبو رافعٍ مَولاهُ، فوَهَبَ له عَبدًا، ومات طِفلًا قَبلَ الفِطامِ، واخْتُلِف هل صلَّى عليه أم لا؟ على قَولين."},{"id":141,"title":"حَجَّةُ الوَداعِ وتسمى حَجَّةُ الإسلامِ أو حَجَّةُ البَلاغِ .","date":["العام الهجري :10","العام الميلادي :631"],"text":"سُمِّيَتْ حَجَّةَ الوَداعِ؛ لأنَّه عليه الصَّلاةُ والسَّلامُ وَدَّعَ النَّاسَ فيها، ولم يَحُجَّ بعدَها، وسُمِّيَتْ حَجَّةَ الإسلامِ؛ لأنَّه عليه السَّلامُ لم يَحُجَّ مِنَ المدينةِ غيرَها، وسُمِّيَتْ حَجَّةَ البَلاغِ؛ لأنَّه عليه السَّلامُ بلَّغَ النَّاسَ شَرْعَ الله في الحَجِّ قَولًا وفِعلًا، ولم يكنْ بَقِيَ مِن دَعائِمِ الإسلامِ وقَواعِدِهِ شيءٌ إلَّا وقد بيَّنَهُ عليه السَّلامُ، فلمَّا بيَّنَ لهم شَريعَةَ الحَجِّ ووَضَّحَهُ وشَرحَهُ أَنزلَ الله عزَّ وجلَّ عليه وهو واقِفٌ بِعَرفةَ: {الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِي وَرَضِيتُ لَكُمُ الْإِسْلَامَ دِينًا} [المائدة: 3]. وعندما أَعلنَ الرَّسولُ صلى الله عليه وسلم عَزمَهُ على الحَجِّ في هذا العامِ قَدِمَ المدينةَ بَشَرٌ كَثيرٌ، كُلُّهُم يَلتَمِسُ أن يَأْتَمَّ بِرسولِ الله صلى الله عليه وسلم، ويَعملَ مِثلَ عَملِهِ. وخرَج مِنَ المدينةِ لِخمسٍ بَقِينَ مِن ذي القَعدةِ. وقد وقعَت للنَّبيِّ صلى الله عليه وسلم في مَسيرِهِ هذا ورُجوعِهِ أَحداثٌ كَثيرةٌ."},{"id":142,"title":"خروج الأسود العنسي في اليمن وقتله على يد فيروز الديلمي .","date":["العام الهجري :10","الشهر القمري : ذي الحجة","العام الميلادي :632"],"text":"خرج الأسوَدُ العَنْسيُّ -واسمُه عَبهلةُ بنُ كَعبِ بنِ غَوثٍ- في آخِرِ حياةِ رَسولِ اللهِ صلَّى اللهُ عليه وسلَّم في سَبْعِمائةِ مقاتلٍ، فكَتَب إلى عمَّالِ النَّبيِّ صلَّى اللهُ عليه وسلَّم: أيُّها المتمَرِّدون علينا، أمسِكوا علينا ما أخَذْتُم مِن أرضِنا، ووفِّروا ما جمعتُم؛ فنحن أَولى به، وأنتم على ما أنتم عليه، ثمَّ توجَّه مع مقاتِلِيه إلى نجرانَ فأخَذَها، ثمَّ قَصَد صنعاءَ، فخرج إليه شَهرُ بنُ باذامَ فتقاتلا، فغَلَبه الأسوَدُ وقتَلَه وتزوَّج بامرأةِ شَهرِ بنِ باذامَ، وهي ابنةُ عَمِّ فيروز الدَّيلميِّ، واسمُه آزاذُ، وكانت مؤمنةً باللهِ ورَسولِه صلَّى اللهُ عليه وسلَّم، ومِن الصَّالحاتِ، واحتَلَّ العَنسيُّ صنعاءَ، فذهب معاذُ بنُ جبَلٍ وأبو موسى الأشعريِّ إلى حَضرَموتَ، وانحاز عُمَّالُ رَسولِ الله صلَّى اللهُ عليه وسلَّم إلى الطَّاهِرِ، ورجَعَ عُمَرُ بنُ حرامٍ وخالِدُ بنُ سعيدِ بنِ العاصِ إلى المدينةِ، واستوثقَت اليمَنُ للأسودِ العَنسيِّ، وجَعَل أمرُه يستطيرُ استطارةَ الشَّرارةِ، واشتَدَّ مُلكُه، واستغلظ أمرُه، وارتَدَّ خَلقٌ مِن أهلِ اليَمَنِ، وعامَله المسلمون الذين هناك بالتَّقِيَّةِ فبعث رَسولُ اللهِ صلَّى اللهُ عليه وسلَّم حين بلغَه خَبَرُ الأسودِ العَنسيِّ كِتابَه مع قيسِ بنِ مكشوحٍ يأمرُ فيه المسلمين الذين هناك بمُقاتلةِ العَنْسيِّ ومُصاولتِه، فقام معاذُ بنُ جَبَلٍ بهذا الكتابِ أتمَّ قيامٍ، واتَّفَق معاذُ بنُ جبَلٍ ومَن التَفَّ حولَه مِن أهلِ اليَمَنِ، وقيسُ بنُ عبدِ يغوثَ أميرُ جندِ الأسوَدِ، وفَيروز الدَّيلميُّ؛ على الفتكِ بالأسوَدِ وقَتْلِه، وتعاقدوا عليه، فلمَّا كان الليلُ دَخَلوا عليه البيتَ؛ تقَدَّم إليه فيروز الدَّيلميُّ، وكان الأسوَدُ نائمًا على فراشٍ من حريرٍ، قد غَرِقَ رأسُه في جَسَدِه، وهو سَكْرانُ يَغطُّ، والمرأةُ جالسةٌ عنده، فعاجله وخالَطَه، وهو مِثلُ الجَمَلِ، فأخَذَ رأسَه، فدَقَّ عُنُقَه ووَضَع رُكبتَيه في ظَهْرِه حتى قَتَلَه، وجلس قيسٌ وداذويه وفيروز يأتمرونَ كيف يُعلِمونَ أشياعَهم، فاتَّفَقوا على أنَّه إذا كان الصَّباحُ ينادون بشِعارِهم الذي بينهم وبين المسلمين، فلمَّا كان الصَّباحُ قام أحَدُهم -وهو قيس- على سُورِ الحِصنِ، فنادى بشِعارِهم، فاجتمع المسلِمون والكافِرون حول الحِصنِ، فنادى قيسٌ: أشهَدُ أنَّ محمَّدًا رسولُ اللهِ، وأنَّ عَبهلةَ كذَّابٌ، وألقى إليهم رأسَه، فانهزم أصحابُه، وتَبِعَهم النَّاسُ يأخُذونهم ويرصُدونهم في كلِّ طريقٍ يأسِرونَهم، وظهر الإسلامُ وأهلُه، وتراجَعَ نوَّابُ رسولِ اللهِ صلَّى اللهُ عليه وسلَّم إلى أعمالِهم، واتَّفَقوا على معاذِ بنِ جَبَلٍ يصلِّي بالنَّاسِ، وكتبوا بالخَبَرِ إلى رَسولِ الله صلَّى اللهُ عليه وسلَّم، وكانت مُدَّةُ مُلكِه منذ ظهر إلى أن قُتِلَ ثلاثةُ أشهُرٍ أو أربعةُ أشهرٍ."},{"id":143,"title":"أبو بكر الصديق يتصدي لقتال أهل الردة ومانعي الزكاة .","date":["العام الهجري :11","العام الميلادي :632"],"text":"لَمَّا قُبِضَ رَسولُ اللهِ صلَّى اللهُ عليه وسلَّم ارتدَّت العَرَبُ، واشرأَبَّ النِّفاقُ، وعَظُمَ الخَطْبُ واشتدَّت الحالُ، وأنفذ الصِّديقُ جَيشَ أُسامةَ، فقَلَّ الجندُ عند الصِّدِّيقِ، فطمَعِتَ كثيرٌ من الأعرابِ في المدينةِ، وراموا أن يَهجُموا عليها، فجَعَل الصِّدِّيقُ على أنقابِ المدينةِ حُرَّاسًا يبَيتون بالجُيوشِ حولَها، وجعَلَت وفودُ العَرَبِ تَقدَمُ المدينةَ يُقِرُّونَ بالصَّلاةِ ويمتنعون من أداء الزكاةِ، ومنهم من امتَنَع مِن دَفْعِها إلى الصِّدِّيقِ، وقد تكلَّم الصَّحابةُ مع الصِّدِّيقِ في أن يترُكَهم وما هم عليه مِن مَنْعِ الزَّكاةِ ويتألَّفَهم حتى يتمكَّنَ الإيمانُ في قلوبِهم، ثم هُم بعد ذلك يزكُّونَ، فامتنع الصِّدِّيقُ من ذلك وأباه، فقال عُمَرُ بنُ الخَطَّابِ لأبي بكرٍ: علامَ تقاتِلُ النَّاسَ؟ وقد قال رسولُ اللهِ صلَّى اللهُ عليه وسلَّم: أُمِرتُ أن أقاتِلَ النَّاسَ حتى يَشهَدوا أنْ لا إلهَ إلَّا اللهُ وأنَّ محمَّدًا رسولُ اللهِ، فإذا قالوها عصَمَوا مني دِماءَهم وأموالَهم إلَّا بحَقِّها؟ فقال أبو بكرٍ: واللهِ لو منعوني عَناقًا -وفي روايٍة: عِقالًا- كانوا يؤدُّونه إلى رَسولِ اللهِ صلَّى اللهُ عليه وسلَّم، لأقاتِلَنَّهم على مَنْعِها؛ إنَّ الزكاةَ حقُّ المالِ، واللهِ لأقاتِلَنَّ مَن فَرَّق بين الصَّلاةِ والزكاةِ. قال عُمَرُ: فما هو إلَّا أن رأيتُ اللهَ قد شَرَح صَدْرَ أبي بكرٍ للقِتالِ، فعَرَفْتُ أنَّه الحَقُّ، وقاتلهم الصِّدِّيق رضي الله عنه  حتى لم يَبْقَ بجزيرةِ العَرَبِ إلَّا أهلُ طاعةٍ لله ولرَسولِه، وأهلُ ذِمَّةٍ مِن الصِّدِّيقِ، كأهلِ نجرانَ وما جرى مجراهم، وعامَّةُ ما وقع من هذه الحروبِ كان في أواخِرِ سنةِ إحدى عَشْرةَ وأوائِلِ سنةِ اثنتي عَشْرةَ."},{"id":144,"title":"إرسالُ خالدِ بن الوَليد لِدَعْم عَمليَّات فَتْح العِراق  .","date":["العام الهجري :11","العام الميلادي :632"],"text":"لمَّا انتهى خالدُ بن الوَليد رضِي الله عنه مِن اليَمامَة جاء الأَمْر بالتَّوَجُّهِ للعِراق لِدَعْم المُثَنَّى بن حارِثةَ، فسار خالدٌ إلى الحِيرَةِ والْتَقى بجيشِ المُثَنَّى وجيشِ عِياضِ بن غَنْمٍ بهُرْمُزَ في الأُبُلَّةِ، وقد حَدَثت عِدَّةُ مَعارك في تلك المناطق التي تُعرَف بالمنطقة الشَّرقيَّة التي كانت تحت سَيطرة الفُرْس، وفُتِحَت عِدَّةُ مناطق كالحِيرَةِ والأَنْبارِ ودُومَةِ الجَنْدَلِ والفِراضِ وغيرِها مِن المناطق العِراقيَّة، كما انتصر خالدٌ في عدد مِن المعارك على الفُرْس وحُلفائِهِم مِن مُتَنَصِّرَةِ العَرَبِ."},{"id":145,"title":"خروج أبي بكر إلى ذي القصة (موضع قريب من المدينة المنورة) حين عقد ألوية الأمراء الأحد عشر .","date":["العام الهجري :11","العام الميلادي :632"],"text":"بعد ما جَمَّ جيشُ أسامةَ واستراحوا، ركِبَ الصِّدِّيقُ في المسلمين شاهِرًا سيفَه مسلولًا، من المدينةِ إلى ذي القصَّةِ، وعلي بن أبي طالبٍ يقودُ براحلةِ الصِّدِّيقِ رَضِيَ اللهُ عنهما، فسأله الصَّحابةُ، وألحُّوا عليه أن يرجِعَ إلى المدينةِ، وأن يَبعَثَ لقِتالِ الأعرابِ غيرَه ممَّن يؤمِّرُه من الشُّجعانِ الأبطالِ، فأجابهم إلى ذلك، وعَقَد لهم الألْوِيَةَ لأحَدَ عَشَرَ أميرًا، وذلك لقتال طليحة بن خويلد، ومالك بن نويرة ومسيلمة الكذاب، والعنسي وعُيَينةُ بنُ حِصنٍ وغيرهم من المرتدين، وقد كَتَب لكُلِّ أميرٍ كِتابَ عَهْدِه على حِدَتِه، ففَصَل كلُّ أميرٍ بجُندِه مِن ذي القصَّةِ، ورجع الصِّدِّيقُ إلى المدينةِ."},{"id":146,"title":"قتال خالد بن الوليد طليحة الأسدي ومن التف حوله .","date":["العام الهجري :11","العام الميلادي :632"],"text":"لَمَّا توجَّه خالِدُ مِن ذي القصَّةِ وفارقه الصِّدِّيقُ، واعَدَه أنَّه سيلقاه من ناحيةِ خيبَرَ بمَن معه من الأمراءِ، وأظهروا ذلك ليُرعِبوا الأعرابَ، وأمَرَه أن يذهَبَ أوَّلًا إلى طليحةَ الأسديِّ، ثمَّ يذهَبَ بعده إلى بني تميمٍ، وكان طليحةُ بنُ خُوَيلدٍ في قَومِه بني أسَدٍ، وفي غَطفانَ، وانضَمَّ إليهم بنو عبسٍ وذبيان، وبَعَث إلى بني جديلةَ والغوثِ وطَيِّئ يستدعيهم إليه، وجَعَل خالدُ بن الوليدِ يتأتَّى بطُلَيحةَ ويُرسِلُ إليه الرُّسُلَ ويحَذِّرُه سَفْكَ دماءِ أصحابِه، وطُلَيحةُ يأبى ذلك ووَلَج في طغيانِه، فعندها عزَمَ خالدٌ على حربِه، ووقَفَت أحياءٌ كثيرةٌ من الأعرابِ ينظُرونَ على من تكونُ الدَّائِرةُ، وجاء طُلَيحةُ فيمن معه من قَومِه ومن التَفَّ معهم وانضاف إليهم، وانهزم النَّاسُ عن طُلَيحةَ، فلمَّا جاءه المسلمون ركب على فرسٍ كان قد أعَدَّها له، وأركَبَ امرأتَه النوارَ على بعيرٍ له، ثم َّانهزم بها إلى الشَّامِ، وتفَرَّقَ جمعُه، وقد قَتَل اللهُ طائفةً ممَّن كان معه، وقد كان طُلَيحةُ الأسديُّ ارتَدَّ في حياةِ النبيِّ صلَّى اللهُ عليه وسلَّم، فلمَّا مات رسولُ اللهِ صلَّى اللهُ عليه وسلَّم قام بمؤازرتِه عُيَينةُ بنُ حِصنٍ بعد أن ارتَدَّ عن الإسلامِ، وأسَرَ خالِدٌ عُيَينةَ بنَ حِصنٍ، وبعث به إلى المدينةِ مجموعةً يداه إلى عنُقِه، فدخل المدينةَ وهو كذلك، فجعل الوِلدانُ والغلمانُ يَطعَنونَه بأيديهم، ويقولون: أيْ عَدُوَّ اللهِ، ارتدَدْتَ عن الإسلامِ؟ فيقولُ: واللهِ ما كنتُ آمنتُ قطُّ! فلمَّا وقف بين يَدَيِ الصِّدِّيق ِاستتابه وحَقَن دَمَه، ثمَّ حَسُنَ إسلامُه بعد ذلك، وأمَّا طُلَيحةُ فإنَّه راجَعَ الإسلامَ بعد ذلك أيضًا، وذهب إلى مكَّةَ مُعتَمِرًا أيَّامَ الصِّدِّيقِ، واستحيا أن يواجِهَه مدَّةَ حياتِه، وقد رَجَع فشَهِدَ القِتالَ مع خالدٍ، وكَتَب الصِّدِّيقُ إلى خالدٍ: أنِ استَشِرْه في الحربِ ولا تُؤَمِّرْه."},{"id":147,"title":"قصة سجاح وبني تميم وزواجها من مسيلمة الكذاب .","date":["العام الهجري :11","العام الميلادي :632"],"text":"كانت بنو تميمٍ قد اختَلَفت آراؤُهم أيَّامَ الرِّدَّةِ؛ فمنهم من ارتدَّ ومَنَع الزَّكاةَ، ومنهم من بَعَث بأموالِ الصَّدَقاتِ إلى الصِّدِّيقِ، ومنهم من توقَّف لينظُرَ في أمرِه، فبينما هم كذلك إذ أقبَلَت سَجاحُ بنتُ الحارِثِ بنِ سُوَيدِ بنِ عقفانَ التَّغلِبيَّةُ من الجزيرةِ، وهي من نصارى العَرَبِ، وقد ادَّعَت النبُوَّة، ومعها جنودٌ مِن قَومِها ومن التَفَّ بهم، وقد عزموا على غَزوِ أبي بكرٍ الصِّدِّيقِ، فلمَّا مَرَّت ببلادِ بني تميمٍ دَعَتْهم إلى أمرِها، فاستجاب لها عامَّتُهم، ثمَّ قَصَدَت بجنودِها اليمامةَ؛ لتأخُذَها مِن مُسَيلِمةَ بنِ حَبيبٍ الكَذَّابِ، فهابه قومُها، وقالوا: إنَّه قد استفحَلَ أمرُه وعَظُمَ، فلمَّا سَمِعَ بمَسيرِها إليه خافها على بلادِه، فبَعَث إليها يستأمِنُها ويضمَنُ لها أن يُعطيَها نِصفَ الأرضِ الذي كان لقُرَيشٍ لو عَدَلَتْ، وراسَلَها ليجتَمِعَ بها في طائفةٍ مِن قَوِمه، فركِبَ إليها في أربعينَ مِن قَومِه، وجاء إليها فاجتَمَعا في خيمةٍ، فلما خلا بها وعَرَض عليها ما عَرَض من نِصفِ الأرضِ، وقَبِلَت ذلك، ثمَّ انثَنَت راجعةً إلى بلادِها، وذلك حين بلَغَها دُنُوُّ خالدٍ مِن أرضِ اليمامةِ، فكَرَّت راجعةً إلى الجزيرةِ بَعدَما قَبَضَت من مُسَيلِمةَ نِصفَ خَراجِ أرضِه."},{"id":148,"title":"قتال خالد بن الوليد رضي الله عنه مالك بن نويرة اليربوعي التميمي .","date":["العام الهجري :11","العام الميلادي :632"],"text":"كان مالِكُ بنُ نُوَيرةَ قد صانَعَ سَجاحَ حينَ قَدِمَت من أرضِ الجزيرةِ، فلمَّا اتَّصَلت بمُسَيلِمةَ الكَذَّابِ، ثمَّ ترحَّلَت إلى بلادِها، نَدِمَ مالِكٌ على ما كان من أمرِه، وتلَوَّم في شأنِه، وهو نازِلٌ بمكانٍ يقالُ له: البِطاحُ في نجد، فقَصَدَها خالدٌ بجُنودِه وتأخَّرت عنه الأنصارُ، وقالوا: إنَّا قد قَضَينا ما أمَرَنا به الصِّدِّيقُ، فقال لهم خالِدٌ: إنَّ هذا أمرٌ لا بدَّ مِن فِعْلِه، وإنَّه لم يأتِني فيها كتابٌ، وأنا الأميرُ وإليَّ تَرِدُ الأخبارُ، ولستُ بالذي أجبُرُكم على المسيرِ، وأنا قاصِدٌ البِطاحَ، فسار يومينِ ثمَّ لَحِقَه رسولُ الأنصارِ يَطلُبون منه الانتِظارَ، فلَحِقوا به، فلمَّا وَصَل البِطاحَ وعليها مالِكُ بنُ نُوَيرةَ، بَثَّ خالِدٌ السَّرايا في البِطاحِ يَدْعونَ النَّاسَ، فاستقبَلَه أمراءُ بني تميمٍ بالسَّمعِ والطَّاعة، وبَذَلوا الزكَواتِ، إلَّا ما كان من مالكِ بنِ نُوَيرةَ؛ فإنَّه متحيِّرٌ في أمرِه، مُتَنَحٍّ عن النَّاسِ، فجاءته السَّرايا فأسَروه وأسَروا معه أصحابَه، واختَلَفت السَّرِيةُ فيهم؛ فشَهِدَ أبو قتادةَ -الحارثُ بنُ ربعيٍّ الأنصاريُّ- أنَّهم أقاموا الصَّلاةَ، وقال آخرون: إنَّهم لم يؤذِّنوا ولا صَلَّوا، فيقالُ: إنَّ الأُسارى باتوا في كُبولِهم في ليلةٍ شديدةِ البردِ، فنادى منادي خالدٍ: أنْ أَدْفِئوا أَسْراكم، فظَنَّ القومُ أنَّه أراد القَتلَ، فقتلوهم، وقَتَل ضرارُ بنُ الأزوَرِ مالِكَ بنَ نُوَيرةَ، فلمَّا سَمِعَ الدَّاعية خرجَ وقد فرَغوا منهم، فقال: إذا أراد اللهُ أمرًا أصابه، ودخل خالِدٌ على أبي بكرٍ فاعتَذَر إليه فعَذَره وتجاوزَ عنه ما كان منه في ذلك، ووَدَى مالِكَ بنَ نُوَيرةَ."},{"id":149,"title":"قتال العلاء بن الحضرمي رضي الله عنه أهل البحرين (الساحل الشرقي من الجزيرة العربية) .","date":["العام الهجري :11","العام الميلادي :632"],"text":"كان مِن خَبَرِ أهلِ البَحرين أنَّ رَسولَ اللهِ صلَّى اللهُ عليه وسلَّم كان قد بَعَث العلاءَ بنَ الحَضْرميِّ إلى مَلِكِها؛ المنذِرِ بن ساوى العَبْديِّ، وأسلَمَ على يَدَيه وأقام فيهم الإسلامَ والعَدْلَ، فلمَّا توفِّيَ رسولُ الله صلَّى اللهُ عليه وسلَّم، توفِّي المنذِرُ بعده بقليلٍ، فلما مات المنذِرُ ارتدَّ أهلُ البحرينِ، وملَّكوا عليهم الغَرورَ، وهو المنذِرُ بنُ النُّعمانِ بنِ المنذِرِ. وقال قائِلُهم: لو كان محمَّدٌ نبيًّا ما مات. ولم يَبْقَ بها بلدةٌ على الثَّباتِ سِوى قريةٍ يقالُ لها جواثا من قرى الأحساء، كانت أوَّلَ قريةٍ أقامت الجُمُعةَ مِن أهلِ الرِّدَّةِ وبعث الصِّدِّيقُ رَضِيَ اللهُ عنه إليهم العلاءَ بنَ الحَضْرميِّ، فلمَّا دنا من البحرينِ جاء إليه ثمامةُ بنُ أُثالٍ في محفَلٍ كبيرٍ، وجاء كُلُّ أمراءِ تلك النَّواحي فانضافوا إلى جيشِ العلاءِ بنِ الحَضرميِّ ثمَّ لَمَّا اقتَرَب من جيوشِ المرتدَّةِ -وقد حَشَدوا وجمَعوا خَلقًا عظيمًا- نزل ونزلوا، وباتوا متجاورينَ في المنازِلِ، فبينما المسلِمونَ في الليلِ إذ سَمِع العلاءُ أصواتًا عاليةً في جيشِ المرتدِّينَ، فقال: مَن رجُلٌ يكشِفُ لنا خبَرَ هؤلاء؟ فقام عبدُ اللهِ بنُ حذفٍ، فدخَلَ فيهم فوجَدَهم سُكارى لا يَعقِلون؛ مِن الشَّرابِ، فرجع إليه فأخَبَره، فركب العلاءُ مِن فَورِه والجَيشُ معه، فكَبَسوا أولئك فقَتَلوهم قتلًا عظيمًا، وقَلَّ مَن هَرَب منهم، واستولى على جميعِ أموالِهم وحواصِلِهم وأثقالِهم، فكانت غنيمةً عظيمةً جسيمةً، وكَتَب إلى الصِّدِّيقِ فأعلَمَه بذلك."},{"id":150,"title":"قتال خالد بن الوليد رضي الله عنه مسيلمة الكذاب ووقعة حديقة الموت .","date":["العام الهجري :11","العام الميلادي :632"],"text":"بعث الصِّدِّيقُ خالدَ بنِ الوليدِ إلى قِتالِ مُسَيلِمةَ الكَذَّابِ وقَومِه من بني حَنيفةَ باليمامةِ، وأوعب معه المسلمون، وعلى الأنصارِ ثابتُ بنُ قيسِ بنِ شماسٍ، فسار لا يمُرُّ بأحدٍ مِن المرتدِّين إلَّا نكَّل بهم، وقد اجتاز بخُيولٍ لأصحابِ سَجاحٍ فشَرَّدهم وأمَرَ بإخراجِهم مِن جزيرةِ العَرَبِ، وأردف الصِّدِّيقُ خالِدًا بسَرِّيةٍ لتكونَ رِدءًا له من ورائِه، فلمَّا سَمِع مُسَيلِمةُ بقدومِ خالدٍ عَسكَرَ بمكانٍ يقالُ له عقربا في طَرَفِ اليمامةِ، والريفُ وراء ظهورِهم، ونَدَب النَّاسَ وحَثَّهم، فحَشَد له أهلُ اليمامةِ، فاصطدم المسلِمون والكُفَّارُ، فكانت جولةٌ عظيمة وجَعَلت الصَّحابةُ يتواصَون بينهم ويقولون: يا أصحابَ سُورةِ البَقَرةِ، بَطَل السِّحرُ اليومَ، ودارت رحى المسلمين، وقد مَيَّز خالِدٌ المهاجرينَ من الأنصارِ من الأعرابِ، وكُلُّ بني أبٍ على رايتِهم، يقاتِلون تحتَها، حتى يَعرِفَ النَّاسُ مِن أين يُؤتَون، وصَبَرَت الصَّحابةُ في هذا الموطِنِ صبرًا لم يُعهَدْ مِثْلُه، ولم يزالوا يتقدَّمون إلى نحورِ عَدُوِّهم حتى فتح اللهُ عليهم، ووَلَّى الكُفَّارُ الأدبارَ، ودخل المسلِمونَ الحديقةَ مِن حيطانِها وأبوابِها يقتُلونَ من فيها من المرتَدَّةِ من أهلِ اليمامةِ، حتى خَلَصوا إلى مُسَيلِمةَ، فتقَدَّم إليه وَحشِيُّ بنُ حَربٍ مولى جُبَيرِ بنِ مُطعِمٍ، فرماه بحَرْبتِه فأصابه وخَرَجَت من الجانِبِ الآخَرِ، وسارع إليه أبو دُجانةَ سِماكُ بنُ خَرشةَ، فضَرَبه بالسَّيفِ فسقط، فكان جملةُ مَن قُتِلوا في الحديقةِ وفي المعركةِ قريبًا مِن عَشرةِ آلافِ مُقاتِلٍ. وقيل: أحدٌ وعشرون ألفًا، وقُتِل من المسلمين سِتُّمائةٍ، وقيل: خمسُمائةٍ."},{"id":151,"title":"ردة أهل عمان والمهرة في عهد أبي بكر الصديق رضي الله عنه .","date":["العام الهجري :11","العام الميلادي :632"],"text":"نبَغَ في أهلِ عُمانَ رجُلٌ يقالُ له: ذو التَّاجِ؛ لقيطُ بنُ مالكٍ الأزديُّ، وكان يسَمَّى في الجاهليَّةِ الجلنديَّ، فادَّعى النبُوَّةَ، وتابعه الجَهَلةُ مِن أهلِ عُمانَ، فتغَلَّب عليها وقَهَر جيفرًا وعبادًا وألجأَهما إلى أطرافِها من نواحي الجبالِ والبَحرِ، فبعث جيفرٌ إلى الصِّدِّيقِ فأخبَرَه الخَبَر واستجاشَه، فبعث إليه الصِّدِّيقُ بأميرينِ، وهما حُذَيفةُ بنُ محصنٍ الحِمْيَريَّ، وعَرْفجةُ البارقيُّ من الأزْدِ، حذيفةُ إلى عمانَ، وعَرْفجةُ إلى مهرةَ، وأمرهما أن يجتَمِعَا ويتَّفِقا ويبتَدِئا بعمانَ، وحذيفةُ هو الأميرُ، فإذا ساروا إلى بلادِ مهرةَ فعَرْفجةُ الأميرُ. ثم كتب الصِّدِّيقُ  لخالدِ بن ِالوليدِ بعد أنْ قَهَر مُسَيلِمةَ: لا أرَيَنَّكَ ولا أسمعَنَّ بك إلَّا بعدَ بلاءٍ، وأمَرَه أن يَلحَقَ بحُذَيفةَ وعَرفجةَ إلى عمانَ، وكُلٌّ منكم أميرٌ على جَيْشِه، وحُذَيفةُ ما دمتُم بعمانَ فهو أميرُ النَّاسِ، فإذا فرغتُم فاذهَبوا إلى مهرةَ، فإذا فرغتُم منها فاذهَبْ إلى اليَمَنِ وحَضرَموتَ، فكُنْ مع المهاجرِ بنِ أبي أُمَيَّةَ، ومَن لَقِيتَه مِن المرتدَّةِ بين عمانَ إلى حَضرَموتَ واليَمَنِ، فنَكِّلْ به، فلمَّا وصلوا إليهم كان الفَتحُ والنَّصرُ، فولى المُشرِكون مُدبِرينَ، وركِبَ المسلِمون ظُهورَهم، فقَتَلوا منهم عَشرةَ آلافِ مقاتلٍ وسَبَوا الذَّراريَّ، وأخذوا الأموالَ والسوقَ بحذافيرِها، وبَعَثوا بالخُمُسِ إلى الصِّدِّيقِ -رَضِيَ اللهُ عنه."},{"id":152,"title":"مُصيبَةُ المسلمين الكُبرى بِوَفاةِ رسولِ الله صلَّى الله عليه وسلَّم .","date":["العام الهجري :11","الشهر القمري : ربيع الأول","العام الميلادي :632"],"text":"اشْتَكى رسولُ الله صلى الله عليه وسلم بعدَ عَودتِه مِن حَجَّةِ الوَداعِ، حتَّى اشْتَدَّ وَجَعُهُ وهو في بيت مَيمونَةَ رضي الله عنها، فدَعا نِساءَهُ فاسْتأذَنَهُنَّ في أن يُمَرَّضَ في بيتِ عائشةَ رضي الله عنها، قالت عائشةُ رضي الله عنها: كان النَّبيُّ صلى الله عليه وسلم يقولُ في مَرضِهِ الذي مات فيه: «يا عائشةُ ما أَزالُ أَجِدُ أَلَمَ الطَّعامِ الذي أَكلتُ بِخَيبرَ، فهذا أَوانُ وَجَدْتُ انْقِطاعَ أَبْهَري مِن ذلك السُّمِّ». واسْتغرَقَ مَرضُهُ عشرةَ أيَّامٍ، قال ابنُ حَجَرٍ: (واخْتُلِفَ في مُدَّةِ مَرضِه، فالأكثرُ على أنَّها ثلاثةَ عشرَ يومًا، وقِيلَ بزيادةِ يَومٍ، وقِيلَ بِنَقصِه، وقِيلَ: عشرةُ أيَّامٍ. وبه جزَم سُليمانُ التَّيميُّ في مَغازيهِ، وأَخرَجهُ البَيهقيُّ بإسنادٍ صَحيحٍ). ثمَّ تَوفَّاهُ الله تعالى يَومَ الاثنين في الثَّاني عشر من رَبيعٍ الأوَّلِ، وقد تَمَّ له مِنَ العُمُرِ 63 سَنَةً، وكُفِّنَ عليه الصَّلاةُ والسَّلامُ في ثلاثةِ أَثوابٍ بِيضٍ سَحُولِيَّةٍ مِن كُرْسُفٍ، ليس فيها قَميصٌ ولا عِمامَةٌ، وصلَّى النَّاسُ عليه أَرْسالًا، ودُفِنَ في مكانِ مَوتِهِ في حُجرَةِ عائشةَ رضي الله عنها، وجَزاهُ الله تعالى عن المسلمين خيرَ ما جَزَى نَبِيًّا عن أُمَّتِهِ."},{"id":153,"title":"أبو بكرٍ الصِّدِّيق رضِي الله عنه يَتولَّى الخِلافةَ (بَيْعة السَّقيفَة) .","date":["العام الهجري :11","الشهر القمري : ربيع الأول","العام الميلادي :632"],"text":"توفِّي رسولُ الله صلَّى الله عليه وسلَّم ولم يَنُصَّ على الخليفةِ مِن بعدِه صَراحةً - وإنَّ كانت هناك إشاراتٌ ودِلالاتٌ مِن النَّبيّ صلَّى الله عليه وسلَّم على تَوْلِيَةِ أبي بكرٍ -والله أعلم- ثمَّ اجتمع الأنصارُ في سَقيفَة بني ساعِدة ليُبايعوا رجلًا منهم، وهو سعدُ بن عُبادَة، فحضر المُهاجرون إليهم، وأخبرهم أبو بكرٍ أنَّ هذا الأمْرَ يجب أن يكونَ في قُريش، فهُمْ أوسطُ العرب نَسَبًا ودارًا، ثمَّ رشَّح عُمرَ، أو أبا عُبيدةَ للخِلافة؛ ولكنَّ عُمر أبى إلَّا أنَّ يُبايَع لأبي بكرٍ، مُبَيِّنًا فَضلَه وصُحبتَه للنَّبيِّ صلَّى الله عليه وسلَّم. فبايَعهُ عُمرُ، ثمَّ بايَعهُ أهلُ السَّقيفةِ، ثمَّ بايَعهُ النَّاسُ في اليوم الثَّاني البَيْعةَ العامَّة، أمَّا تَخلُّف علِيّ عن البيعة في السَّقيفَة فكان لانشغالِه بتَجهيزِ وتَكفينِ النَّبيّ صلَّى الله عليه وسلَّم، وأمَّا ما يُقال مِن أنَّه تأخَّر عن البَيْعة حتَّى وَفاة فاطمةَ رضِي الله عنها فليس له مُسْتَنَدٌ صحيح، ويبعد أن يَبقى ستَّة أَشهُر غير مُبايع له وهو الذي أعانه وكان تحت إمْرتِه كلّ تلك الفَترة، وخاصّة في حُروب الرِّدَّةِ، بل إنَّ البيعة الثَّانية من عليٍّ لأبي بكر بعد وفاة فاطمة رضي الله عنهم كانت تأكيدًا للبيعة الأولى وحسمًا لمادة الفتنة."},{"id":154,"title":"بَعْثُ أُسامةَ بن زيدٍ رضِي الله عنه إلى الشَّام .","date":["العام الهجري :11","الشهر القمري : ربيع الأول","العام الميلادي :632"],"text":"كان زيدُ بن حارِثةَ قد اسْتُشْهِدَ في مُؤْتةَ، فلمَّا أراد رسولُ الله صلَّى الله عليه وسلَّم غزوَ تلك الجِهات جَهَّز جيشًا وأَمَّر عليهم أُسامةَ بن زيدِ بن حارِثةَ، وأَمَرهُ أن يَصِلَ إلى البَلْقاء، فتَجَهَّزَ الجيشُ وتَعَبَّأَ، ولكنَّ هذا الجيشَ لم يَنفذْ بسبب وَفاة النَّبيّ صلَّى الله عليه وسلَّم، فلمَّا تَولَّى أبو بكرٍ الخِلافةَ كان أوَّل شيء فعله هو إنفاذ جيشِ أُسامةَ وإرساله كما أراد النَّبيُّ صلَّى الله عليه وسلَّم، ومع أنَّ أبا بكرٍ قد أشاروا عليه بعدم إرساله لكنَّه أَبَى إلَّا إنفاذَ ما كان رسولُ الله صلَّى الله عليه وسلَّم أراد إنفاذَهُ، وشَيَّعَهُم أبو بكرٍ بنفسه ماشيًا، وأوصى الجيشَ، وكان مِن آثار هذا الفِعل مِن أبي بكر دِلالة على بقاء قوَّة المسلمين وارتِفاع معنوياتهم."},{"id":155,"title":"خروج أبي بكر الصديق بالمسلمين لقتال المرتدين الذين غاروا على المدينة وانتصاره عليهم .","date":["العام الهجري :11","الشهر القمري : جمادى الآخرة","العام الميلادي :632"],"text":"لم يَلبَثِ المسلمون بعد تحذيرِ أبي بكرٍ الصِّدِّيقِ لهم من الأعرابِ المرتدِّينَ إلَّا ثلاثًا، حتى طَرَقوا المدينةَ غارةً، وخَلَّفوا نِصفَهم بذي حسى ليكونوا رِدءًا لهم، فأرسَلَ الحَرَسُ إلى أبي بكرٍ يخبرونَه بالغارةِ، فبعث إليهم: أنِ الزَموا مكانَكم، ثمَّ ركِبَ الصِّدِّيقُ في أهلِ المدينةِ وأمراءِ الأنقابِ، إلى مَن حَولَ المدينةِ مِن الأعرابِ الذين أغاروا عليها، فما طَلَع الفَجرُ إلَّا وهم والعَدُوُّ في صعيدٍ واحدٍ، فما سمعوا للمسلمين حِسًّا ولا همسًا، حتى وضعوا فيهم السُّيوفَ، فما طلعت الشَّمسُ حتى ولَّوهم الأدبارَ، وغلبوهم على عامَّةِ ظَهرِهم، وكان أوَّلَ الفَتحِ، وذَلَّ بها المشركون، وعزَّ بها المسلِمون، ووَثَب بنو ذُبيانَ وعَبس على من فيهم من المسلمين فقتلوهم، وفَعَل مَن وراءهم كفِعْلِهم، فحلف أبو بكرٍ ليقتُلَنَّ من كلِّ قبيلةٍ بمن قتلوا من المسلمين وزيادة، فكانت هذه الوقعةُ من أكبرِ العونِ على نصرِ الإسلامِ وأهله، وذلك أنَّه عزَّ المسلمون في كلِّ قبيلةٍ، وذَلَّ الكُفَّارُ في كلِّ قبيلةٍ، ورجع أبو بكرٍ إلى المدينةِ مُؤَيَّدًا منصورًا، سالِمًا غانمًا."},{"id":156,"title":"غزو أبي بكر بني عبس وذبيان في الربذة بالأبرق .","date":["العام الهجري :11","الشهر القمري : رجب","العام الميلادي :632"],"text":"لَمَّا قَدِمَ أسامةُ بنُ زيدٍ مِن بَعْثِه للرُّومِ استخلفه أبو بكرٍ على المدينةِ، وأمره ومن معه أن يُريحوا ظَهْرَهم، ثم ركب أبو بكر في الذين كانوا معه من المسلمين، فقالوا له: لو رجعتَ إلى المدينةِ وأرسلْتَ رجلًا، فقال: واللهِ لا أفعَلُ، ولأواسِيَنَّكم بنفسي، فخرج في تعبئتِه النُّعمانُ وعبدُ اللهِ وسُوَيدُ بنو مُقرنٍ على ما كانوا عليه في الوقعةِ السابقةِ، حتى نزل على أهلِ الربذةِ بالأبرَقِ، وهناك جماعةٌ من بني عَبسٍ وذبيانَ، وطائفةٌ من بني كِنانةَ، فاقتتلوا، فهزم اللهُ الحارِثَ وعَوفًا، وأُخِذ الحُطَيئةُ أسيرًا، فطارت بنو عبسٍ وبنو بكرٍ، وأقام أبو بكرٍ على الأبرَقِ أيَّامًا، وقد غَلَب بني ذُبيان على البلادِ، وقال: حرامٌ على بني ذُبيانَ أن يتمَلَّكوا هذه البلادَ؛ إذ غَنَّمَناها اللهُ، وحمى الأبرَقَ بخيولِ المسلمينَ، وأرعى سائِرَ بلادِ الربذةِ، ولَمَّا فَرَّت عبسٌ وذبيانُ صاروا إلى مؤازرةِ طَلحةَ وهو نازلٌ على بزاخةَ."},{"id":157,"title":"وَفاةُ فاطِمةَ رضِي الله عنها بنتِ رسولِ الله صلَّى الله عليه وسلَّم .","date":["العام الهجري :11","الشهر القمري : شعبان","العام الميلادي :632"],"text":"سَيِّدةُ نِساءِ العالمين في زمانِها، بنتُ سَيِّدِ الخَلْقِ رسولِ الله صلَّى الله عليه وسلَّم أبي القاسم محمَّد بن عبدِ الله بن عبدِ المُطَّلِب بن هاشم بن عبدِ مَناف القُرشيَّة الهاشِميَّة وأمّ الحَسَنَيْنِ. أمّها خديجةُ بنتُ خويلدٍ، وُلِدَتْ قبلَ البعثة بقليلٍ، وتَزوَّجها علِيُّ بن أبي طالبٍ بعدَ بدرٍ، وقِيلَ: بعدَ أُحُدٍ, فوَلدَت له الحسنَ والحُسينَ ومُحسنًا وأمَّ كُلثومٍ وزَينبَ. وهي أصغرُ بناتِ النَّبيّ صلَّى الله عليه وسلَّم، كانت مِن أحبِّ النَّاس إلى رسولِ الله صلَّى الله عليه وسلَّم، ومَناقِبُها غَزيرة، وكانت صابرة دَيِّنَة خَيِّرَة صَيِّنَة قانِعة شاكِرة لله تُوفِّيت بعدَ النَّبيّ صلَّى الله عليه وسلَّم بخَمسة أَشهُر أو نحوها، وهي أوَّل أهلِ النَّبيّ صلَّى الله عليه وسلَّم لُحوقًا به. وأَوْصَتْ في وَفاتِها أن تُغَطَّى، فكانت أوَّل امرأة يُغَطَّى نَعْشُها في الإسلامِ، غَسَّلَها زَوجُها علِيٌّ وأسماءُ بنتُ عُمَيْسٍ وقد كانت تحت أبي بكر رضي الله عنهم، وصَلَّى عليها علِيٌّ، وقِيلَ: العبَّاس، وأَوْصَت أن تُدْفَنَ ليلًا، ففُعل ذلك بها، ونزَل في قبرِها علِيٌّ والعَبَّاسُ، والفَضلُ بن العَبَّاس. انقطع نَسْلُ رسولِ الله صلَّى الله عليه وسلَّم إلَّا منها رضِي الله عنها."},{"id":158,"title":"مَعركةُ ذاتِ السَّلاسِل وهَزيمةُ الفُرْس بقِيادةِ خالدِ بن الوَليد .","date":["العام الهجري :12","الشهر القمري : محرم","العام الميلادي :633"],"text":"قَدِمَ خالدٌ العِراقَ لِمُساندَةِ المُثَنَّى بأَمْرٍ مِن أبي بكرٍ ومعه عشرةُ آلافِ مُقاتِل، ومع المُثَنَّى وأصحابِه ثَمانيةُ آلافٍ، وجعل على مُقَدِّمَتِه المُثَنَّى وبَعدَهُ عَدِيَّ بن حاتم، وجاء خالدٌ بَعدهُما، وواعدهما الحَفِيرَ ليُصادِموا عَدُوَّهُم، وكان ذلك الفَرْجُ أعظمَ فُروجِ فارِسَ وأشدَّها شَوْكةً، وكان صاحبُهُ هُرْمَزَ، وهو سيِّئُ المُجاورةِ للعربِ، فكلُّهم عليه حنق، وكانوا يَضرِبونه مثلًا فيقولون: أَكْفر مِن هُرمُزَ, فلمَّا سمِع أنَّهم تواعدوا الحَفِيرَ، سبَقهُم إليه ونزَل به، وجعَل على مُقدِّمتِه قُباذُ وأَنُوشَجَان، وكانا مِن أولادِ أَرْدَشِير الأكبر، واقترنوا في السَّلاسِل، لذلك سُمِّيَت بذلك، فسمِع بهم خالدٌ، فَمالَ بالنَّاس إلى كاظمةٍ، فسبَقهُ هُرمُزُ إليها، وقَدِم خالدٌ فنزَل على غيرِ ماءٍ فقال له أصحابُه في ذلك: ما تفعل؟ فقال لهم: لعَمْري ليَصيرَنَّ الماءُ لأَصْبَرِ الفريقين. فحطّوا أثقالَهُم، وتَقدَّم خالدٌ إلى الفُرْس فلاقاهُم، وأرسل الله سحابةً فأغدَرَت وراءَ صَفِّ المسلمين، فقَوِيَت قلوبُهم، وخرَج هُرمُز ودعا خالدًا إلى البِرازِ، وأَوْطأ أصحابُه على الغَدْرِ بخالدٍ، فبرَز إليه خالدٌ ومَشى نحوه راجلًا، ونزَل هُرمُز أيضًا وتَضارَبا، فاحتَضنَهُ خالدٌ، وحمَل أصحابُ هُرمُز، فما شَغَلهُ ذلك عن قتلِه، وحمَل القَعْقاعُ بن عَمرٍو فأَزاحَهُم، وانهزم أهلُ فارس ورَكِبَهم المسلمون، وسُمِّيَت الوقعة ذات السَّلاسِل، ونجا قُباذُ وأَنُوشَجَان، وأخَذ خالدٌ سَلَبَ هُرمُز، وكانت قَلنسوتُه بمائة ألف. كان أهلُ فارس يجعلون قَلانِسهم على قدر أحسابِهم فمَن تمَّ شَرفُه فقيمةُ قَلنسوتِه مائةُ ألفٍ، فكان هُرمُز ممَّن تمَّ شَرفُه، وبعَث خالدٌ بالفَتح والأخماسِ إلى أبي بكرٍ."},{"id":159,"title":"أبو بكرٍ الصِّدِّيق رضِي الله عنه يأمُر بجَمْعِ القُرآنِ .","date":["العام الهجري :12","الشهر القمري : محرم","العام الميلادي :633"],"text":"عَهِدَ أبو بكرٍ الصِّدِّيق رضِي الله عنه إلى زيدِ بن ثابتٍ بجَمْعِ نُصوصِ القُرآن وخاصّة بعدَ مَوت عددٍ كبيرٍ من حفظة القرآن في اليَمامةِ، وكان هذا الأمرُ غيرَ مقبول لدى الصَّحابة رضِي الله عنهم في البداية، ولكنَّ الله شرَح صُدورَهم له كما شرَح صدر أبي بكرٍ له، فكَلَّفَ أبو بكرٍ زيدَ بن ثابتٍ بمُهِمَّةِ الكِتابة، فقال لزيدٍ: إنَّك رجلٌ شابٌّ عاقل لا نَتَّهِمك, قد كُنتَ تكتبُ الوَحيَ لرسولِ الله صلَّى الله عليه وسلَّم, فتَتَبَّعْ القُرآن فاجْمَعْهُ. فقلتُ: كيف تفعلون شيئًا لم يفعلْهُ رسولُ الله صلَّى الله عليه وسلَّم؟! قال: هو -والله- خيرٌ. فلم يزل أبو بكرٍ يراجعني حتَّى شرَح الله صدري للذي شرَح له صدرَ أبي بكر وعُمرَ, فكنتُ أتتبَّعُ القُرآن أَجمعُه مِن الرِّقاع والأكتافِ والعُسُبِ وصُدورِ الرِّجالِ. وكان الأمْرُ شديدًا على زيدٍ لكنَّه قام بها خيرَ قِيامٍ، فكان هذا الأمْرُ أوَّلَ جمعٍ للقُرآن، وبَقِيَ المصحفُ عند أبي بكرٍ في خِلافتِه."},{"id":160,"title":"فَتْحُ بَلدةِ أَمْغِيشِيا بقِيادَةِ خالدِ بن الوَليد  .","date":["العام الهجري :12","الشهر القمري : صفر","العام الميلادي :633"],"text":"فتَح المسلمون بقِيادةِ خالدِ بن الوَليد بلدَةَ أَمْغِيشِيا، وكانت مِصْرًا كالحِيرَةِ، وقِيلَ: اسمها منيشيا، وهي تقعُ على نهرِ الفُراتِ، ولم يقع بأَمْغِيشِيا قِتالٌ، وإنَّما هجرها أهلُها بعدَ هزيمةِ الفُرْس في أُلَّيْس، فدخَلها المسلمون فاتحين، وأصابوا فيها ما لم يُصيبوا مِثلَه لأنَّ أهلَها أَعجَلَهُم المسلمون أن يَنقُلوا أموالَهم وأثاثَهم وكِراعَهم وغيرَ ذلك، بلَغ سهمُ الفارسِ ألفا وخمسمائة، سِوى النَّفْلِ الذي نَفَلَهُ أهلُ البَلاءِ, وأَرسَل إلى أبي بكرٍ بالفَتحِ والغَنائمِ والسَّبْيِ، وأَخْرَب أَمْغِيشِيا. فلمَّا بلغ ذلك أبا بكرٍ قال: عجَز النِّساءُ أن يَلِدْنَ مِثلَ خالدٍ."},{"id":161,"title":"وَقعةُ الوَلَجَةِ وهَزيمةُ الفُرْسِ بقِيادةِ خالدِ بن الوَليد\n  .","date":["العام الهجري :12","الشهر القمري : ربيع الأول","العام الميلادي :633"],"text":"قامت وَقعةُ الوَلَجَةِ بين الفُرْس والمسلمين بقيادةِ خالدِ بن الوَليد رضِي الله عنه، والوَلَجَةُ مكان في العِراق، وسُمِّيت المعركة باسمه لوُقوع الأحداثِ فيه, لمَّا وقع الخبرُ بأَرْدَشِير بمُصابِ قارَنَ وأهلِ المَذارِ، جَنَّدَ المَلِكُ جيشًا عظيمًا مِن قبيلةِ بكرِ بن وائلٍ والقبائل الأُخرى المُواليةِ له, تحت قِيادةِ قائدٍ مشهور منهم يُدْعى الأندرزغر, وكان فارِسيًّا مِن مولدي السَّوادِ. وأرسل بهمن جاذُوَيْهِ في إثْرِهْ ليقودَ جُيوشَ المَلِكِ, وحشَرَ الأندرزغر مِن بين الحِيرَةِ وكَسْكَر ومِن عَربِ الضَّاحيَةِ, فلمَّا اجتمع للأندرزغر ما أراد واستتمَّ أَعجبَهُ ما هو فيه، وأَجْمَعَ السَّيْرَ إلى خالدٍ، ولمَّا بلغ خالدًا وهو بالقُرْبِ مِن نهرِ دِجْلة خبرُ الأندرزغر ونزوله الوَلَجَة، نادى بالرَّحيلِ، وخَلَّفَ سُوَيدَ بن مُقَرِّنٍ، وأَمرَهُ بِلُزومِ الحَفِيرِ، وتَقدَّم إلى مَن خَلَّفَ في أَسفلِ دِجْلة، وأَمَرَهُم بالحَذَرِ وقِلَّةِ الغَفْلَةِ، وتَرْك الاغْتِرارِ، وخرج خالدٌ سائرًا في الجُنود نحو الوَلَجَةِ، حتَّى نزَل على الأندرزغر بالوَلَجَةِ، فاقتتَلوا بها قِتالًا شديدًا، حتَّى ظن الفريقان أنَّ الصَّبرَ قد فَرَغَ، واسْتبطَأَ خالدٌ كَمينَهُ، وكان قد وضَع لهم كَمينًا في ناحيتين، عليهم بُسْرُ بن أبي رُهْمٍ، وسعيدُ بن مُرَّةَ العِجْليُّ، فخرَج الكَمينُ في وَجهينِ فانْهزمَت صُفوف الأعاجِم ووَلَّوْا، فأخذَهُم خالدٌ مِن بين أيديهم والكَمينُ مِن خَلفِهم، وكانت الهَزيمةُ كاملةً؛ ففَرَّ الفُرْسُ وفَرَّ العَربُ المُوالون لهم, بعد أن قتَل وأسَر منهم عددًا عظيمًا, ومضى الأندرزغر مُنهزمًا, فمات عَطَشًا في الفَلاةِ, وبذَل خالدٌ الأمانَ للفلَّاحين؛ فعادوا وصاروا أهلَ ذِمَّةٍ, وسَبَى ذراريَّ المُقاتِلة ومَن أَعانَهُم."},{"id":162,"title":"مَعركةُ المَذارِ وهَزيمةُ الفُرْسِ بقِيادةِ خالدِ بن الوَليد\n  .","date":["العام الهجري :12","الشهر القمري : ربيع الأول","العام الميلادي :633"],"text":"كتَب هُرمُز إلى أَرْدَشِير وشِيرَى بخبرِ مَسِيرِ خالدٍ إليه مِن اليَمامةِ، فأَمَدَّهُ بقارَن بن قِرْيانِس، فخرَج قارَنُ مِن المدائن حتَّى إذا انتهى إلى المَذارِ بَلَغَتْهُ الهَزيمةُ، فعَسْكَرَ قارَنُ وفُلولُ الفُرْس بالمَذارِ بالقُربِ مِن نهرِ دِجْلة، واستعمَل على مُجَنِّبَتِهِ قُباذَ وأَنُوشَجان، ولمَّا انتهى الخبرُ إلى خالدٍ عن قارَن قسَمَ الفَيءَ على مَن أفاءَهُ الله عليه، ونَفَّلَ مِن الخُمُسِ ما شاء الله، وبعَثَ ببَقِيَّتِهِ وبالفتحِ إلى أبي بكرٍ. ثمَّ خرَج خالدٌ سائرًا حتَّى نزَل المَذارَ على قارَن في جُموعِه، فالتقَوْا وخالدٌ على تَعْبِيَتِهِ، فاقتتلوا على حَنَقٍ وحَفِيظَةٍ، وخرَج قارَنُ يدعو للبِرازِ، فبرَز له خالدٌ وأبيضُ الرُّكْبان مَعْقِلُ بن الأَعْشى فابْتدَراهُ، فَسَبَقَهُ إليه مَعْقِلٌ فقَتَلَهُ، وقتَل عاصمُ بن عَمرٍو الأَنُوشَجانَ، وقتَل عَدِيُّ بن حاتم قُباذَ, وقُتِلَت فارسٌ مَقتَلةً عظيمةً، فرَكِبَ الفُرْسُ السُّفُنَ، ومنعت المياهُ المسلمين مِن طَلَبِهم، وأقام خالدٌ بالمَذارِ، وسَلَّمَ الأسلابَ لمن سَلَبَها بالغةً ما بَلغَت، وقَسَم الفَيْءَ، ونَفَّلَ مِن الأخماسِ أهلَ البَلاءِ، وبعَث ببَقِيَّةِ الأخماسِ،  وقِيلَ: قُتِلَ ليلةَ المَذارِ ثلاثون ألفًا سِوَى مَن غرَق، ولولا المياهُ لأُتِيَ على آخرِهم، ولم يُفْلِتْ منهم مَن أَفْلَت إلَّا عُراةً وأشباهَ العُراةِ. ثمَّ أخَذ خالدٌ يَسْبِي ذَراريَّ المُقاتِلة ومَن أعانهم، وأَقرَّ الفلَّاحين ومَن أجاب إلى الخَراجِ مِن جميعِ النَّاسِ بعدَ ما دُعوا، وكلُّ ذلك أُخِذَ عَنْوَةً ولكن دُعوا إلى الجزاءِ، فأجابوا وتَراجَعوا، وصاروا أهلَ ذِمَّةٍ، وصارت أرضُهم لهم. وكان في السَّبْيِ حبيبٌ أبو الحسنِ -يعني أبا الحسنِ البَصْريَّ- وكان نَصرانِيًّا."},{"id":163,"title":"فَتْحُ الحِيرَةِ بقِيادةِ خالدِ بن الوَليد  .","date":["العام الهجري :12","الشهر القمري : ربيع الأول","العام الميلادي :633"],"text":"كان الآزاذِبَةُ مَرْزُبان الحِيرَةِ أي حكام الحيرة, فلمَّا أَخرَب خالدٌ أَمْغِيشِيا عَلِم الآزاذبةُ أنَّه غيرُ مَتروكٍ، فأخذ في أَمْرهِ وتَهيَّأ لحربِ خالدٍ، لمَّا تَوجَّه خالدٌ إلى الحِيرَةِ وحمَل الرِّحالَ والأثقالَ في السُّفُنِ أَرسلَ الآزاذبةُ ابنَهُ لِيقطَعَ الماءَ عن السُّفُنِ, فتعَجَّلَ خالدٌ في خَيلٍ نحو ابنِ الأزاذبةِ فلَقِيَهُ على فُراتِ بادِقْلَى، فقتَلهُ وقتَل أصحابَهُ، وسار نحو الحِيرَةِ، فهرَب منه الآزاذبةُ، وكان قد بَلغَهُ مَوتُ أَرْدَشِير وقتلُ ابنِه، فهرَب بغيرِ قِتالٍ، فتَحصَّنَ أهلُ الحِيرَةِ فحصَرهُم في قُصورِهم. دخل خالدٌ الحِيرَةَ، وأَمَر بكلِّ قَصْرٍ رجلًا مِن قُوَّادِه يُحاصِر أهلَهُ ويُقاتِلهم، فعَهِدَ خالدٌ إلى أُمرائِهِ أن يَبدءوا بِدَعوَتِه إحدى ثلاثٍ، فإن قَبِلوا قَبِلوا منهم، وإن أَبَوْا أن يُؤَجِّلوهم يومًا، وقال: لا تُمَكِّنوا عَدُوَّكُم مِن آذانِكُم فيَتربَّصوا بِكُم الدَّوائرَ، ولكن ناجِزوهُم ولا تُرَدِّدوا المسلمين عن قِتالِ عَدُوِّهِم. فلمَّا دَعَوْهُم أَبَوْا إلَّا المُنابذَةِ, فنَشَبَ القِتالُ وأَكثرَ المسلمون القتلَ فيهم، فنادى القِسِّيسون والرُّهْبانُ: يا أهلَ القُصورِ، ما يقتلنا غيرُكم. فنادى أهلُ القُصورِ: يا مَعشرَ العربِ، قد قَبِلْنا واحدةً مِن ثلاثٍ، فادعوا بنا وكُفُّوا عَنَّا حتَّى تُبلِّغونا خالدًا. فخرَج قائدٌ مِن كلِّ قصرٍ، فأُرسلوا إلى خالدٍ، مع كلِّ رجلٍ منهم ثِقَةٌ، لِيُصالح عليه أهلَ الحِصْن، فخلا خالدٌ بأهلِ كلِّ قصرٍ منهم دون الآخرين، وقد حاوَر خالدُ بن الوَليد أحدَ رُؤسائِهم وهو عَمرُو بن عبدِ المَسيحِ ابنُ بُقَيْلَةَ، وكان مع خادمِه كِيسٌ فيه سُمٌّ، فأخَذهُ خالدٌ ونَثَرَهُ في يَدِهِ وقال: لِمَ تَستَصْحِب هذا؟ قال: خشيتُ أن تكونوا على غيرِ ما رأيتُ، فكان الموتُ أحبَّ إليَّ مِن مَكروهٍ أُدْخِلُه على قَومي."},{"id":164,"title":"معركة ألِّيس وهزيمة نصارى العرب والفرس بقيادة خالد بن الوليد .","date":["العام الهجري :12","الشهر القمري : ربيع الأول","العام الميلادي :633"],"text":"لمَّا أصاب خالدٌ يومَ الوَلَجَةِ ما أصاب مِن نَصارى بكرِ بن وائلٍ الذين أعانوا الفُرْسَ غَضِبَ لهم نَصارى قَوْمِهم، فكاتَبوا الفُرْسَ، واجتمعوا على أَلَّيْس وعليهم عبدُ الأسودِ العِجْليُّ وكتَبَ أَرْدَشِير إلى بهمن جاذُوَيْهِ يأمُرهُ بالقُدومِ على نَصارى العربِ بأُلَّيْس، فقَدِمَ بهمن جاذُوَيْهِ جابانَ إليهم، فاجتمع على جابان نَصارى العربِ مِن أهلِ الحِيرَةِ. وكان خالدٌ لمَّا بَلغَهُ تَجَمُّعُ نَصارى بكرٍ وغيرِهم سار إليهم ولا يَشعُرُ بِدُنُوِّ جابان. فلمَّا طلَع جابانُ بأُلَّيْس قالت العَجَمُ له: أَنُعاجِلُهُم أم نغدي النَّاس ولا نُريهِم أَنَّا نَحْفَلُ بهم، ثمَّ نُقاتِلهم؟ فقال جابانُ: إن تَركوكُم فتَهاوَنوا بهم. فعَصَوْهُ وبَسَطوا الطَّعامَ، وانتهى خالدٌ إليهم وحطَّ الأثقالَ، فلمَّا وُضِعت تَوجَّه إليهم، وطلَب مُبارزةَ عبدِ الأسودِ وابنِ أَبْجَرَ ومالكِ بن قيسٍ، فبرَز إليه مالكٌ مِن بينهم، فقَتلَهُ خالدٌ وأَعجَل الأعاجمَ عن طعامِهم. فقال لهم جابانُ: حيث لم تَقدِروا على الأكلِ فسُمُّوا الطَّعامَ، فإن ظَفرتُم فأَيْسَرُ هالِكٍ، وإن كانت لهم هَلكوا بأَكْلِهِ. فلم يفعلوا، واقتتلوا قِتالًا شديدًا، والمشركون يَزيدُهم ثُبوتًا تَوقُّعُهم قُدومِ بهمن جاذُوَيْهِ، فصابَروا المسلمين، فقال خالدٌ: اللَّهمَّ إن هَزمتَهُم فعَلَيَّ أن لا أَسْتَبْقِي منهم مَن أَقدِر عليه حتَّى أُجري مِن دمائهِم نَهرَهُم. فانهزمت فارِسُ فنادى مُنادي خالدٍ: الأُسَراءُ الأُسَراءُ، إلَّا مَن امتنع فاقتلوه. فأقبل بهم المسلمون أُسَراء، ووَكَّل بهم مَن يَضرِب أعناقَهُم يومًا وليلةً. فقال له القَعْقاعُ وغيرُه: لو قتلتَ أهلَ الأرضِ لم تَجْرِ دِماؤهُم، فأَرْسِلْ عليها الماءَ تَبَرَّ يَمينُك، ففعَل فَسالَ النَّهرُ دَمًا عَبيطًا، فلذلك سُمِّيَ نَهْرَ الدَّمِ إلى اليومِ، ووقَف خالدٌ على الطَّعامِ وقال للمسلمين: قد نَفَّلْتُكُموه، فتَعشَّى به المسلمون، وجعَل مَن لم يَرَ الرِّقاقَ يقول: ما هذه الرِّقاقُ البِيضُ؟"},{"id":165,"title":"فَتْحُ الأَنْبارِ في مَعركةِ ذاتِ العُيونِ  بقِيادةِ خالدِ بن الوَليد .","date":["العام الهجري :12","الشهر القمري : ربيع الآخر","العام الميلادي :633"],"text":"رَكِبَ خالدٌ في جُيوشِه بعد فتحِ الحِيرَةِ حتَّى انتهى إلى الأنبارِ وعليها قائدٌ يُقال له: شِيرَزاذ، فأحاط بها خالدٌ، وعليها خندقٌ وحوله أَعرابٌ مِن قَومِهم على دينهم، واجتمع معهم أهلُ أرضِهم، ولمَّا تَواجَه الفَريقانِ أَمَر خالدٌ أصحابَه فَرَشقوهم بالنِّبال حتَّى فَقَأوا منهم ألفَ عَيْنٍ، وسُمِّيَت هذه الغزوة ذات العُيونِ، فراسل شِيرَزاذ خالدًا في الصُّلْحِ، فاشْتَرط خالدٌ أُمورًا فامْتَنع شِيرَزاذ مِن قُبولِها، فتَقدَّم خالدٌ إلى الخندقِ فاسْتَدعى بردايا الأموالِ مِن الإبلِ فذبَحها حتَّى ردَم الخندقَ بها وجاز هو وأصحابُه فوقَها، فلمَّا رأى شِيرَزاذ ذلك أجاب إلى الصُّلحِ على الشُّروط التي اشتَرطها خالدٌ، وسأَله أن يَرُدَّهُ إلى مَأْمَنِهِ فوَفَّى له بذلك، وخرج شِيرَزاذ مِن الأنبارِ وتَسلَّمَها خالدٌ، فنَزَلها واطْمَأنَّ بها، وتَعلَّم الصَّحابةُ ممَّن بها مِن العربِ الكِتابةَ العَربيَّةَ، ثمَّ صالَح خالدٌ أهلَ البَوازِيج وكَلْواذَى."},{"id":166,"title":"وَقعةُ عَيْنِ التَّمْرِ وهَزيمةُ العَربِ المُوالين للفُرْسِ بقِيادةِ خالدِ بن الوَليد .","date":["العام الهجري :12","الشهر القمري : ربيع الآخر","العام الميلادي :633"],"text":"لمَّا فَرَغَ خالدُ بن الوَليد مِن الأنبارِ واسْتَحكَمت له اسْتخلَف على الأنبارِ الزِّبْرِقانَ بن بدرٍ، وقصَد عَيْنَ التَّمْرِ، وبها يَومئذٍ مِهرانُ بن بَهْرامَ جُوبِينَ في جَمْعٍ عظيمٍ مِن العَجَمِ، وعَقَّةُ بن أبي عَقَّةَ في جَمْعٍ عظيمٍ مِن العَرَبِ مِن النَّمِرِ وتَغْلِبَ وإيادٍ ومَن لاقاهُم فلمَّا سمِعوا بخالدٍ قال عَقَّةُ لمِهرانَ: إنَّ العربَ أعلمُ بقِتالِ العربِ، فدَعْنا وخالدً.، قال: صدقتَ، لَعَمْري لأنتم أعلمُ بقِتالِ العربِ، وإنَّكم لَمِثْلِنا في قِتالِ العَجَمِ -فخدَعهُ واتَّقى به- وقال: دُونَكُمُوهُم، وإن احْتجتُم إلينا أَعنَّاكُم. فقالت الأعاجِمُ له: ما حمَلَك على هذا؟ فقال: إن كانت له فهي لكم، وإن كانت الأُخرى لم تَبلُغوا منهم حتَّى تَهِنُوا، فنُقاتِلهم وقد ضَعُفوا. فلَزِمَ مِهرانُ العَيْنَ، ونزَل عَقَّةُ لخالدٍ على الطَّريقِ، فقَدِمَ عليه خالدٌ وهو في تَعبِئَةِ جُنْدِهِ، فعَبَّى خالدٌ جُنْدَهُ وقال لِمُجَنِّبَتَيْهِ: اكْفونا ما عنده، فإنِّي حاملٌ. ووَكَّلَ بِنَفْسِه حَوامِيَ، ثمَّ حمَل وعَقَّةُ يُقيمُ صُفوفَهُ، فاحْتضَنَهُ فأَخذَهُ أسيرًا، وانهزَم صَفُّهُ مِن غيرِ قِتالٍ، فأكثروا فيهم الأَسْرَ، واتَّبَعَهُم المسلمون، ولمَّا جاء الخبرُ مِهرانَ هرَب في جُنْدِه، وترَكوا الحِصْنَ، ولمَّا انتهت فُلَّالُ عَقَّةَ مِن العَربِ والعَجَمِ إلى الحِصْنِ اقتحَموه واعتَصموا به، وأقبَل خالدٌ في النَّاس حتَّى ينزِلَ على الحِصْنِ ومعه عَقَّةُ أَسيرٌ، وعَمرُو بن الصَّعِقِ، وهُم يَرجون أن يكونَ خالدٌ كَمَنْ كان يُغِيرُ مِن العربِ، فلمَّا رَأوه يُحاوِلهم سألوه الأمانَ، فأَبَى إلَّا على حُكمِه، وأَمَر خالدٌ بِعَقَّةَ وكان خَفيرَ القَومِ فضُرِبت عُنقُه لِيُوئسَ الأُسَراء مِن الحياةِ، ولمَّا رآه الأُسَراءُ مَطروحًا على الجِسْرِ يَئسوا مِن الحياةِ، ثمَّ دَعا بعَمرِو بن الصَّعِقِ فضرَب عُنقَه، وضرب أعناقَ أهلِ الحِصْن أجمعين، وسَبَى كلَّ مَن حَوى حِصْنُهم، وغَنِمَ ما فيه، ووجد في بِيعَتِهم أربعين غُلامًا يَتَعلَّمون الإنجيلَ، عليهم بابٌ مُغلقٌ، فكَسرَهُ عنهم، وقال: ما أنتم؟ قالوا: رَهْنٌ، فقَسَمَهم في أهلِ البلاءِ، منهم نُصَيرٌ أبو موسى بن نُصيرٍ، وسِيرينُ أبو محمَّدِ بن سِيرينَ."},{"id":167,"title":"انتصارُ المسلمين في مَعركةِ الحُصَيْدِ  والخَنافِسِ المُصَيَّخِ .","date":["العام الهجري :12","الشهر القمري : شعبان","العام الميلادي :633"],"text":"بعد أن انصرفَ خالدٌ مِن عَيْنِ التَّمْرِ أقام بدُومَة الجَندلِ فظَنَّ الفُرْسُ أنَّه قد غادَر العِراقَ مُتوجِّهًا إلى الجَزيرةِ العربيَّة مع القسم الأكبر مِن قُوَّاتِه، فأرادوا طَرْد قُوَّاتِه مِن العِراق، واستعادَة الأراضي التي فتَحها المسلمون؛ فطَمِع الأعاجمُ، وكاتَبَهم عربُ الجَزيرةِ غضبًا لِعَقَّةَ، فخرَج زرمهر وروزبه يُريدان الأنبارَ، واتَّعدا حُصيدًا والخَنافِسَ، فسمِع  القعقاعُ بن عَمرٍو وهو خَليفةُ خالدٍ على الحِيرَةِ، فأرسل أَعْبَدَ بن فَدَكِيٍّ وأَمَره بالحُصيدِ (وادٍ بين الكوفة والشام)، وأرسَل عُروةَ بن الجَعْدِ البارقيَّ إلى الخَنافِسِ، ورجَع خالدٌ مِن دُومة إلى الحِيرَةِ وهو عازِمٌ على مُصادَمَةِ أهلِ المدائن مَحَلَّةِ كِسرى، لكنَّه كَرِهَ أن يَفعلَ ذلك بغيرِ إذن أبي بكرٍ الصِّدِّيق، وشَغلَه ما قد اجتمع مِن جُيوش الأعاجمِ مع نَصارى الأعرابِ يُريدون حَربَهُ، فبعَث القعقاعَ بن عَمرٍو أميرًا على النَّاس، فالْتَقَوْا بمكانٍ يُقال له: الحُصيد، وعلى العجمِ رجلٌ منهم يُقال له: روزبه، وأَمَدَّهُ أميرٌ آخرٌ يُقال له: زرمهر، فاقتتلوا قِتالًا شديدًا، وهُزِم المشركون وقتَل منهم المسلمون خلقًا كثيرًا، وقَتَل القَعقاعُ بِيَدِهِ زرمهر، وقَتَل رجلٌ يُقال له: عِصْمَةُ بن عبدِ الله الضَّبِّيُّ روزبه. وغَنِمَ المسلمون شيئًا كثيرًا، وهرَب من هرَب مِن العجمِ، فلَجأوا إلى مكان يُقال له: خَنافِس، فسار إليهم أبو ليلى بن فَدَكِيٍّ السَّعديُّ، فلمَّا أحسُّوا بذلك ساروا إلى المُصَيَّخِ، وعندما وصل أبو ليلى إلى الخَنافِس وجدَها خالية مِن الفُرْس، فأقام بها مُدَّةً، ثمَّ أرسل إلى خالدِ بن الوَليد يُنهي إليه أنباءَ استيلائِه على المدينةِ، ويُخبِرهُ بفِرارِ الفُرْس إلى المُصَيَّخ، فلمَّا استقرَّ الفُرْسُ  بالمُصَيَّخ بمن معهم مِن الأعاجم والأعارِب قصَدهم خالدُ بن الوَليد بمَن معه مِن الجُنود، وقَسَّم الجيشَ ثلاث فِرَقٍ، وأغار عليهم ليلًا وهُم نائِمون فأَنامَهُم، ولم يُفْلِت منهم إلَّا اليَسيرُ فما شُبِّهُوا إلَّا بِغَنَمٍ مُصَرَّعَةٍ."},{"id":168,"title":"مَعركةُ الفِراضِ وهَزيمةُ الرُّوم بقِيادةِ خالدِ بن الوَليد .","date":["العام الهجري :12","الشهر القمري : ذي القعدة","العام الميلادي :634"],"text":"سار خالدُ بن الوَليد رضِي الله عنه بجُيوشِه المُجتمعَة إلى الفِراض على تُخوم الشَّام والعِراق والجَزيرة، وتَعاوَن الفُرْسُ والرُّومُ ضِدَّ المسلمين, فأقام هنالك شهرَ رمضانَ مُفْطِرًا لِشُغلِه بالأعداءِ، ولمَّا بلَغ الرُّومَ أمرُ خالدٍ ومَصيرُهُ إلى قُرْبِ بِلادِهم حَمُوا وغَضِبوا وجَمَعوا جُموعًا كثيرةً، ثمَّ ناهَدوا خالدًا فحالت الفُراتُ بينهم، فقالت الرُّومُ لخالدٍ: اعْبُرْ إلينا. وقال خالدٌ للرُّومِ: بل اعْبُروا أنتم. فعَبَرت الرُّومُ إليهم، فاقتتلوا هنالك قِتالًا عظيمًا بليغًا، ثمَّ هزَم الله جُموعَ الرُّومِ وتَمَكَّنَ المسلمون مِن اقْتِفائِهم، فقُتِلَ في هذه المعركةِ مِن الفُرْسِ والرُّومِ والعَربِ المُتَنَصِّرَةِ أكثر مِن مائةِ ألفٍ، وأقام خالدٌ بعدَ ذلك بالفِراضِ عشرةَ أيَّام، ثمَّ رَتَّبَ لرُجوعِ جَيشِه للحِيرَةِ، ثمَّ  اتَّجَه مع بعضِ جُنْدِه للحَجِّ دون عِلْمِ أَحدٍ بهم."},{"id":169,"title":"حَجَّةُ خالدِ بن الوَليد رضِي الله عنه أثناءَ عَودةِ جَيشِه مِن الفِراضِ إلى الحِيرَةِ .","date":["العام الهجري :12","الشهر القمري : ذي القعدة","العام الميلادي :634"],"text":"أقام خالدُ بن الوَليد بالفِراضِ عشرةَ أيَّامٍ، ثمَّ أَذِنَ بالقُفولِ إلى الحِيرَةِ، لِخَمْسٍ بَقِينَ مِن ذي القَعدةِ، وأَمَر عاصمَ بن عَمرٍو أن يَسيرَ في المُقدِّمة، وأَمَر شَجَرةَ بن الأعَزِّ أن يَسيرَ في السَّاقَةِ، وأظهرَ خالدٌ أنَّه يَسيرُ في السَّاقَةِ, ثمَّ انطلق في كَوْكَبَةٍ مِن أصحابِه، وقصَد شَطْرَ المسجدِ الحرامِ، وسار إلى مكَّةَ في طريقٍ لم يُسْلك قبلَهُ قَطُّ، وتَأتَّى له في ذلك أَمرٌ لم يقع لغيرِهِ، فجعَل يَسيرُ مُعْتَسِفًا على غيرِ جادَّةٍ، حتَّى انتهى إلى مكَّةَ فأدرك الحَجَّ, ثمَّ عاد فأدرك أَمْرَ السَّاقَةِ قبلَ أن يَصِلوا الحِيرَةَ، ولم يَعلمْ أبو بكرٍ الصِّدِّيق بذلك أيضًا إلَّا بعدَ ما رجَع أهلُ الحَجِّ مِن المَوْسِم، فبعَث يَعْتِبُ عليه في مُفارقتِه الجيشَ، وأَمرهُ بالذِّهابِ إلى الشَّامِ مُمِدًّا جُموعَ المسلمين."},{"id":170,"title":"وَقعةُ النَّمارِق وهَزيمةُ الفُرْسِ بقِيادةِ أبي عُبيدِ بن مَسعودٍ الثَّقفيِّ .","date":["العام الهجري :13","العام الميلادي :634"],"text":"بعَث رُسْتُم جيشًا لِقِتالِ أبي عُبيدِ بن مَسعودٍ الثَّقفيِّ فالْتَقَى الطَّرفانِ في النَّمارِقِ بين الحِيرَةِ والقَادِسِيَّةِ، وكان على خَيلِ المسلمين المُثَنَّى بن حارِثةَ، فهزَم الفُرْسَ وهَربوا وساروا إلى كَسْكَر فلَحِقَهم  أبو عُبيدٍ  ثمَّ هزَمهم ثانيةً وفَرَّ الفُرْسُ إلى المدائنِ. وجمَع المسلمون الغَنائمَ مِن كَسْكَر، فرَأَوْا مِن الأَطعِمَة شيئًا عظيمًا، فاقْتَسموهُ وجعلوا يُطعِمونه الفلَّاحين، وبَعثوا بخُمُسِه إلى عُمرَ وكتبوا إليه: إنَّ الله أَطعمَنا مَطاعِم كانت الأكاسِرةُ يَحمونها، وأحببنا أن تَرَوْها، ولِتَذكروا إنعامَ الله وإفْضالَه."},{"id":171,"title":"خالدُ بن الوَليد يُشارك في فَتحِ بُلدانِ الشَّام .","date":["العام الهجري :13","العام الميلادي :634"],"text":"كان أبو بكرٍ قد أَمَر خالدَ بن الوَليد بعدَ أن انتهى مِن الفِراض بالانتقالِ إلى الشَّامِ؛ لِمُساندةِ جُيوشِ الفَتحِ هناك، فسار خالدٌ مِن الفِراض حتَّى وصل اليَرْموكَ وجاء كِتابُ عُمَر بعدَ اليَرْموك: أن ابْدَؤوا بِدِمشقَ فإنَّها حِصْنُ الشَّام. ولمَّا وصلت جُيوشُ المسلمين دِمشقَ شَدَّدوا الحِصارَ عليها سبعين يومًا، طَوَّقوها مِن جِهاتِها كُلِّها، ومَنعوا المَدَدَ إليها، فانْكَسرت حَمِيَّتُهم وفُتِحَت المدينةُ بعدَ أن تمَّ احْتِلال الغُوطةِ منعًا للإمدادات، ووُلِّيَ عليها يَزيدُ بن أبي سُفيانَ، ثمَّ سار المسلمون إلى فِحْلٍ، ثمَّ إلى حِمْصَ، ثمَّ إلى قِنَّسْرِينَ واللَّاذِقِيَّةِ وحَلَب."},{"id":172,"title":"إجْلاءُ اليَهودِ والنَّصارى مِن جَزيرةِ العَربِ .","date":["العام الهجري :13","العام الميلادي :634"],"text":"كان الرَّسولُ صلَّى الله عليه وسلَّم قد أَجْلى اليَهودَ مِن المدينة تِباعًا؛ وذلك لِنَقْضِهم العُهود، واسْتِثارتِهم الفِتَن والحُروب، وقد كان النَّبيُّ صلَّى الله عليه وسلَّم قال: (لا يَجتَمِع دِينانِ في أرضِ العَربِ). وكانت اليَهودُ قد اسْتقرَّت في خَيبرَ وما حولها بعدَ جَلائِهم مِن المدينةِ، وبقوا على ذلك حتَّى قام عُمَر بإجلائِهم مِن خَيبرَ إلى الشَّامِ عملًا بحَديثِ النَّبيِّ صلَّى الله عليه وسلَّم، وأمَّا نصارى نجران فقد أجلاهم عمر إلى الشَّام في سنة 17هـ لما كثُر عددُهم وعَظُمَ خطرُهم على معقْل الإسلام."},{"id":173,"title":"أبو بكر الصِّدِّيق رضِي الله عنه يَعْقِدُ أَلْوِيَةَ فَتْح الشَّام بعدَ فَراغِه مِن حُروبِ الرِّدَّةِ .","date":["العام الهجري :13","الشهر القمري : صفر","العام الميلادي :634"],"text":"قام الصِّدِّيقُ أبو بكرٍ رضِي الله عنه بعَقْدِ أربعةِ أَلوِيةٍ لفَتْح بِلادِ الشَّام بعدَ أن فَرَغَ مِن حُروبِ الرِّدَّةِ، وجعَل قِيادَتَها لأبي عُبيدةَ بن الجَرَّاحِ، ووِجْهَتُه حِمْصُ، وعَمرِو بن العاصِ ووِجْهَتُه فِلسطينُ، وشُرَحْبِيلِ بن حَسَنَةَ ووِجْهَتُه الأُرْدُنُّ، ويَزيدَ بن أبي سُفيانَ ووِجْهَتُه دِمشقُ. وقد أَدَّتْ هذه الجُيوشُ دورَها الفعَّالَ في مُقاتلةِ الرُّومِ وانتصروا في مَواقعَ كثيرةٍ، وكان الرُّومُ في جَميعِها أكثرَ عددًا وعُدَّةً."},{"id":174,"title":"مَسيرُ خالدِ بن الوَليد مِن العِراقِ لِدَعْمِ أَجنادِ الشَّامِ وفَتْحُ مَدينةِ بُصْرى .","date":["العام الهجري :13","الشهر القمري : ربيع الأول","العام الميلادي :634"],"text":"لمَّا رأى المسلمون مُطاوَلةَ الرُّومِ لهم بالشَّام اسْتمَدُّوا أبا بكرٍ، فكتَب إلى خالدِ بن الوَليد يأمُرهُ بالمَسيرِ إليهم وبالحَثِّ، وأن يَأخُذَ نِصفَ النَّاس ويَسْتخلِفَ على النِّصفِ الآخرِ المُثَنَّى بن حارِثةَ الشَّيبانيَّ، ولا يَأْخُذَنَّ مَن فيه نَجْدَةٌ إلَّا وَيَتْرك عند المُثَنَّى مِثْلَهُ، وإذا فتَح الله عليهم رجَع خالدٌ وأصحابُه إلى العِراقِ. اتَّجَه خالدٌ مِن العِراقِ إلى الشَّام وفتَح عددًا مِن المُدُنِ، وصالَح بعضَها، وصل شَرقِيَّ جَبَلِ حَوْرانَ، ثمَّ تَدْمُرَ، ثمَّ القَرْيَتينِ مِن أَعمالِ حِمْصَ، ثمَّ قاتَل غَسَّانَ في مَرْجِ راهِطٍ وانتصر عليهم، ثمَّ سار إلى بُصْرى الشَّامِ وكانت أوَّلَ مدينةٍ افتتَحها مِن بِلادِ الشَّامِ حتَّى بلَغ جموع المسلمين في اليرموك، وكان ممَّا مَرَّ به خالدٌ مع جَيْشِهِ مَفازَة بين قُراقِر وسُوَى لا ماءَ فيها ولا كَلَأ، الدَّاخِلُ فيها مَفقودٌ، والخارِجُ منها مَولودٌ، لكنَّ خالدًا استعان بدَليلٍ يُقال له: رافِعُ بن عُميرَةَ الطَّائيُّ، ساعَدهُ على تَجاوُزِ المَفازةِ بسَلامٍ مع جَيشٍ قِوامُه تِسعةُ آلافِ مُقاتلٍ."},{"id":175,"title":"مَعركةُ \"مَرْجِ الصُّفَّرِ\" بين الرُّوم والمسلمين بقِيادةِ خالدِ بن سعيدٍ .","date":["العام الهجري :13","الشهر القمري : جمادى الأولى","العام الميلادي :634"],"text":"وقعت مَعركةُ \"مَرْجِ الصُّفَّرِ\" بين الرُّوم بقِيادةِ ماهان، والمسلمين بقِيادةِ خالدِ بن سعيدٍ، وذلك في بِدايات فتحِ المسلمين لبِلاد الشَّام، حيث أخذ خالدٌ طريقَهُ لِمَرْجِ الصُّفَّرِ للهُجومِ على الرُّومِ ممَّا أَدَّى بقائِدهِم ماهان إلى أن يَنحَدِرَ بجَيشِهِ حتَّى يَستدرِجَ جُيوشَ المسلمين التي اتَّجهَت إلى الجَنوبِ ووصلت إلى مَرْجِ الصُّفَّرِ شرق بُحيرَةِ طَبَرِيَّةَ، واغتنم الرُّومُ على المسلمين الفُرصةَ وأوقعوا بهم الهزيمةَ، وصادَف ماهانُ سعيدَ بن خالدِ بن سعيدٍ في كَتيبةٍ مِن العَسكَرِ فقتَلهم وقتَل سعيدًا في مُقدِّمتِهم، وبلغ خالدًا مَقتلُ ابنِه، ورأى نَفْسَهُ قد أُحيطَ به فخرَج هاربًا في كَتيبةٍ مِن أصحابِه على ظُهورِ الخيلِ والإبلِ، وقد نجَح عِكرِمةُ بن أبي جهلٍ في سَحْبِ بَقِيَّةِ الجيشِ إلى حُدودِ الشَّام، وانتهت المعركةُ بانتصارِ الرُّومِ."},{"id":176,"title":"وَفاةُ أبي بكرٍ الصِّدِّيق رضِي الله عنه .","date":["العام الهجري :13","الشهر القمري : جمادى الآخرة","العام الميلادي :634"],"text":"هو أبو بكرٍ الصِّدِّيق عبدُ الله بن عُثمانَ بن عامرِ بن كعبِ بن سعدِ بن تَيْمِ بن مُرَّةَ بن كعبِ بن لُؤَيٍّ. وهو أحدُ العشرةِ المُبشَّرين بالجنَّةِ، وأوَّلُ الخُلفاءِ الرَّاشِدين، مِن أَوائلِ المُصَدِّقين للنَّبيِّ صلَّى الله عليه وسلَّم والمؤمنين به، بَقِيَ معه في مكَّة حتَّى هاجَر معه فكان صاحِبَه في ذلك، قَدَّمَهُ النَّبيُّ صلَّى الله عليه وسلَّم للصَّلاةِ بالنَّاس في مَرَضِ مَوتِه، أَنفقَ في سبيلِ الله كُلَّ مالِه، كان وَزيرَ النَّبيِّ صلَّى الله عليه وسلَّم وصاحِبَ مَشورَتِهِ، بايَعَهُ المسلمون على الخِلافَةِ بعدَ مَوْتِ النَّبيِّ صلَّى الله عليه وسلَّم كما هو مَذكور، تُوفِّيَ أبو بكرٍ الصِّدِّيق بعدَ أن بَقِيَ خَليفةً مُدَّةَ سَنتين وثلاثةِ أَشهُر وعشرةِ أيَّام، تُوفِّيَ بعدَ أن مَرِضَ، وقد قام خِلالَ هذه المُدَّةِ القصيرةِ بِرَدِّ المُرْتَدِّين وحَرْبِهِم والتي شَمِلَتْ أجزاءَ الجزيرةِ كلَّها، ثمَّ كانت الحُروبُ مع الفُرْسِ والرُّومِ حيث أظهرت قُوَّةَ المسلمين وإمكاناتِهم القِتاليَّة التي لا يُستهان بها، دُفِنَ بجانِبِ النَّبيِّ صلَّى الله عليه وسلَّم في حُجْرَةِ عائشةَ، فكان مع صاحِبِه كما كان معه في الدُّنيا، فجزاهُ الله عن الأُمَّةِ الإسلاميَّةِ خيرًا ورضِي الله عنه وأَرضاهُ."},{"id":177,"title":"عُمرُ بن الخطَّاب رضي الله عنه يَتولَّى الخِلافةَ بعد وفاة أبي بكر رضي الله عنه .","date":["العام الهجري :13","الشهر القمري : جمادى الآخرة","العام الميلادي :634"],"text":"لمَّا مَرِض أبو بكرٍ الصِّدِّيق رضِي الله عنه وأَحَسَّ بِدُنُوِّ أَجَلِه جمَع عددًا مِن الصَّحابة الذين كان النَّبيُّ صلَّى الله عليه وسلَّم يُشاوِرهُم وعرَض عليهم أن يُؤمِّروا رجلًا يَرضَوْنهُ في حَياتِه؛ ولكنَّهم لم يَستقِرُّوا على أَمْرٍ، ثمَّ بدَأ يسألُ النَّاس عن عُمَرَ بن الخطَّاب، ثمَّ استَقرَّ رَأيُه على اسْتِخلاف عُمَرَ، فكتَب بذلك كِتابًا نَصُّهُ: بسم الله الرَّحمن الرَّحيم، هذا ما عَهِدَ أبو بكرٍ بن أبي قُحافةَ إلى المسلمين، أمَّا بعدُ، فإنِّي قد اسْتخلَفتُ عليكم عُمَرَ بن الخطَّاب، ولم آلُكُم خيرًا منه. وقال: اللَّهمَّ إنِّي اسْتخلَفتُ على أهلِك خيرَ أهلِك. وبَلَّغَ بذلك النَّاسَ، ورَضوا به، فكانت تلك خِلافة عُمَرَ رضِي الله عنه."},{"id":178,"title":"مَوقِعةُ الجِسْرِ وهَزيمةُ المسلمين .","date":["العام الهجري :13","الشهر القمري : شعبان","العام الميلادي :634"],"text":"بعدَ أن هُزِمَ الفُرْسُ في النَّمارِق وما بعدَها اجتمعوا إلى رُسْتُم فأرسل جيشًا كثيفًا ومعهم رايةُ كِسرى ورايةُ أفريدون  فالتقوا مع المسلمين وبينهم جِسْرٌ فعَبَر أبو عُبيدِ بن مَسعودٍ الثَّقفيُّ الجِسْرَ إليهم وجَرَت المعركةُ، وكانت فِيَلَةُ الفُرْسِ تُؤذي المسلمين وتُؤذي خُيولَهم، فقُتِل عددٌ مِن قادَةِ المسلمين منهم أبو عُبيدٍ القائدُ، واسْتَحَرَّ القَتلُ في المسلمين فمَضَوْا نحوَ الجِسْر فقَطَعهُ أحدُ المسلمين وقال: قاتِلوا عن دِينِكُم. فاقْتَحَم النَّاسُ الفُراتَ فغَرِقَ ناسٌ كثيرٌ، ثمَّ عقَد المُثَنَّى الجِسْرَ وعَبَر المسلمون واسْتُشْهِد يَومئذٍ مِن المسلمين ألفٌ وثمانمائةٍ، وقِيلَ أربعةُ آلافٍ بين قَتيلٍ وغَريقٍ، وانحاز بالنَّاس المُثَنَّى بن حارِثةَ الشَّيبانيُّ."},{"id":179,"title":"مَوقِعةُ البُوَيْب وانتِصارُ المسلمين بقِيادةِ المُثَنَّى بن حارِثةَ الشَّيبانيِّ .","date":["العام الهجري :13","الشهر القمري : رمضان","العام الميلادي :634"],"text":"بعدَ أن تَوَلَّى المُثَنَّى بن حارِثةَ قِيادةَ المسلمين وكان عُمَر رضِي الله عنه يُمِدُّهُ بالمُقاتلين، الْتَقَى المُثَنَّى مع الفُرْسِ في البُوَيْب قُرْب الكوفةِ، وطلَبَت الفُرْسُ أن يَعبُرَ المسلمون إليهم، أو أن يَعبُروا هُم إليهم، فاختار المُثَنَّى  أن يَعبُر الفُرْسُ فعَبَروا, وجرَت مَعركةٌ عَنيفةٌ هُزِم فيها الفُرْسُ هزيمةً مُنكَرةً، وقُتِلَ منهم الكثيرُ قتلًا أو غَرَقًا في النَّهرِ، وقُتِلَ فيها قائدُ الفُرْسِ مِهرانُ."},{"id":180,"title":"بِناءُ مَدينةِ البَصْرَةِ .","date":["العام الهجري :14","الشهر القمري : ربيع الأول","العام الميلادي :635"],"text":"لمَّا نزَل عُتبةُ بن غَزْوان الخُرَيْبَةَ -مَسالِح الفُرْسِ قَريبة مِن الأُبُلَّةِ- كتب إِلى عُمَر بن الخطَّاب يُعلِمه نُزولَه إيَّاها، وأنَّه لابُدَّ للمسلمين مِن مَنزلٍ يَشْتُون به إذا شَتَوْا، ويَكْنِسون فيه إذا انصرفوا مِن غَزوِهم، فكتب إليه: اجْمَع أصحابَك في مَوضِع واحد وليَكُنْ قريبًا مِن الماء والرَّعْي، واكْتُبْ إِلىَّ بصِفَتِه. فكتب: إليه إنِّي وجدتُ أرضًا كثيرةَ القَصَبَةِ -أي كثيرةَ الحَصَبَةِ- في طَرْفِ البَرِّ إِلى الرِّيفِ، ودونَها مَناقِعُ ماءٍ فيها قَصْباءُ. فلمَّا قرَأ الكِتابَ قال: هذه أرضٌ نَضِرَةٌ، قَريبةٌ مِن المَشارِب والمَراعي والمُحْتَطَب، وكتَب إليه: أن أَنْزِلْها النَّاسَ. فأنزلهم إيَّاها، فكان عُتبةُ هو أوَّل مَن مَصَّرَ البَصْرةَ."},{"id":181,"title":"مَعركةُ اليَرموك وانتِصارُ المسلمين على الرُّوم بقِيادةِ خالدِ بن الوَليد .","date":["العام الهجري :14","الشهر القمري : رجب","العام الميلادي :635"],"text":"كان أبو بكرٍ قد كتَب إلى خالدٍ أن يَلحقَ بالشَّام  لِمُساندةِ أَجنادِ المسلمين، وأَمَدَّ هِرقلُ الرُّومَ بباهان، فطلَع عليهم وقد قَدَّمَ الشَّمامِسَةَ والرُّهْبانَ والقِسِّيسينَ يَحُضُّونهم على القِتالِ، ولمَّا قَدِمَ خالدٌ الشَّامَ أشار على الأُمراءِ أن يَجتمِعوا تحت قِيادةٍ واحدةٍ، فقال لهم: إنَّ تَأْمِيرَ بعضِكم لا يُنْقِصُكم عند الله ولا عند خَليفةِ رسولِ الله صلَّى الله عليه وسلَّم فهَلُمُّوا فَلْنَتَعاوَر الإمارةَ، فليَكُنْ عليها بَعضُنا اليومَ، والآخرُ غدًا، حتَّى يتَأَمَّرَ كُلُّكُم، ودَعوني أَتَوَلَّى أَمْرَكم اليومَ, فأَمَّرُوه. خرَجت الرُّومُ في تَعْبِئَةٍ لم يَرَ الرَّاءون مِثلَها قَطُّ، مِائتي ألفٍ وأربعين ألفًا، منهم ثمانون ألفًا مُقَيَّدٌ بالسَّلاسِل. وخرَج خالدٌ في تَعْبِئَةٍ لم تُعَبِّئْها العَربُ قبلَ ذلك، وكان المسلمون سِتَّة وثلاثين ألفًا. وقِيلَ سِتَّة وأربعين ألفًا, جعلهم خالدٌ في سِتَّة وثلاثين كُرْدُوسا إلى الأربعين كُرْدُوس، شَهِدَ اليَرموك ألفٌ مِن أصحابِ رسولِ الله صلَّى الله عليه وسلَّم، فيهم نحوٌ مِن مِائةٍ مِن أهلِ بدرٍ, وكان أبو سُفيانَ يَسيرُ فيَقِفُ على الكَراديس فيقول: الله الله، إنَّكم ذَادَةُ العَربِ، وأنصارُ الإسلامِ، وإنَّهم ذَادَةُ الرُّومِ وأنصارُ الشِرْكِ! اللَّهمَّ إنَّ هذا يومٌ مِن أيَّامِك، اللَّهمَّ أَنزِلْ نَصرَك على عِبادِك. قال رجلٌ لخالدٍ: ما أكثرَ الرُّومَ وأَقَلَّ المسلمين! فقال خالدٌ: ما أَقَلَّ الرُّومَ وأكثرَ المسلمين! إنَّما تَكْثُرُ الجُنودُ بالنَّصرِ وتَقِلُّ بالخُذلانِ، لا بعددِ الرِّجالِ، والله لوَدِدْتُ أنَّ الأشقرَ -يعني فَرَسَهُ- بَرَأَ مِن تَوَجُّعِه وأنَّهم أَضْعَفُوا في العَدَدِ. خرَج جَرَجَةُ أحدُ قادةِ الرُّومِ حتَّى كان بين الصَّفَّيْنِ، ونادى: لِيَخرُج إليَّ خالدٌ، فخرَج إليه خالدٌ، فوافَقَهُ بين الصَّفَّيْنِ، حتَّى اختلفت أَعناقُ دابَّتَيْهِما، فحاوَرهُ خالدٌ حتَّى دخَل في الإسلامِ وكانت وَهْنًا على الرُّومِ. أَمَّرَ خالدٌ عِكرِمةَ والقَعقاعَ، والْتَحَم النَّاسُ، وتَطارَد الفِرْسانُ وهُم على ذلك إذ قَدِم البَريدُ مِن المدينةِ، بموتِ أبي بكرٍ وتَأْميرِ أبي عُبيدةَ، فأسرَّ خالدٌ الخَبَرَ حتَّى لا يُوهِنَ الجيشَ، وحَمِيَ الوَطيسُ، واشْتَدَّ القِتالُ, وقام عِكرمةُ بن أبي جهلٍ يُنادي: مَن يُبايِع على الموتِ؟ فبايَعَهُ أربعمائة مِن وجوه المسلمين، فقاتلوا حتَّى أُثْبِتُوا جميعًا, فهزَم الله الرُّومَ مع اللَّيلِ، وصعَد المسلمون العَقبةَ، وأصابوا ما في العَسكرِ، وقتَل الله صناديدَهُم ورءوسَهُم وفِرسانَهُم، وقتَل الله أخا هِرقل، وأُخِذَ التَّذارِقُ، وقاتَل جَرَجَةُ قِتالًا شديدًا مع المسلمين، إلى أن قُتِلَ عند آخرِ النَّهارِ، وصلَّى النَّاسُ الأوُلى والعصرَ إيماءً، وتَضَعْضَع الرُّومُ، ونهد خالد بالقلبِ حتَّى كان بين خَيْلِهِم ورَجْلِهم، فانهزم الفِرْسان وتركوا الرَّجَّالةَ. ولمَّا رَأي المسلمون خيلَ الرُّومِ قد تَوجَّهَت للمَهْرَبِ أَفرَجوا لها، فتَفرَّقَت وقُتِلَ الرَّجَّالةُ، واقتحموا في خَندقِهم فاقْتَحَمه عليهم، فعَمِدوا إلى الوَاقُوصَةِ حتَّى هوى فيها المُقتَرِنون وغيرُهم، ثمانون ألفًا مِن المُقْتَرِنين، ودخَل خالدٌ الخَندقَ ونزَل في رِواقِ تَذارِق، وانتهت الهَزيمةُ إلى هِرقل وهو دون مَدينةِ حِمْصَ، فارْتَحَلَ."},{"id":182,"title":"مَعركةُ القادِسِيَّةِ وانتِصارُ المسلمين على الفُرْسِ بقِيادةِ سعدِ بن أبي وقَّاصٍ .","date":["العام الهجري :14","الشهر القمري : شعبان","العام الميلادي :635"],"text":"اجتمَع المسلمون في القادِسيَّة ثلاثون ألفًا بقِيادةِ سعدِ بن أبي وقَّاص بعدَ أن أَمَّرَهُ عُمَر بن الخطَّاب بَدَلَ خالدِ بن الوَليد، مكَث سعدٌ في القادِسيَّة شهرًا يَبُثُّ السَّرايا في كلِّ الجِهاتِ، ويأتي بالغَنائِم، فأَمَّر يزدجردُ رُسْتُمَ على جيشٍ كثيفٍ مِن مائةٍ وعشرين ألفًا، ومِثلِها مِن المَدَدَ، فبعَث سعدٌ إليه مَن يَدعوه للإسلامِ وحاوَل الفُرْسُ أن يغروا المسلمين، فطلبوا إرسالَ أكثرِ مِن رجلٍ فأتاهُم رِبْعِيٌّ، ثمَّ حُذيفةُ بن مِحْصَنٍ، وأخيرًا أتاهُم المُغِيرةُ ولم تنفع في شيءٍ، فبدأ القِتالُ بعدَ الظَّهيرةِ وبَقِيَت المعركةُ ثلاثةَ أيَّام، وفي اليومِ الرَّابع اشْتدَّ أَثَرُ الفِيَلَةِ على المسلمين، ثمَّ في هذا اليومِ هَبَّتْ رِيحٌ شديدةٌ على الفُرْسِ أزالت خِيامَهم فهربوا وقُتِلَ رُستمُ قائدُهم، وتَمَّتْ الهزيمةُ على الفُرْسِ، وقُتِلَ منهم ما لا يُحْصى، ثمَّ ارتحلَ سعدٌ ونزَل غَربيَّ دِجْلة، على نهرِ شير، قُبالةَ مَدائنِ كِسرى، ودِيوانِه المشهورِ، ولمَّا شاهَد المسلمون إيوانَ كِسرى كَبَّروا وقالوا: هذا أبيضُ كِسرى، هذا ما وَعَدَ الله ورسولُه. واسْتُشْهِدَ مِن المسلمين ألفٌ وخمسمائةٍ، وقُتِلَ مِن الفُرْسِ عشرون ألفًا، وغَنِمَ المسلمون الكثيرَ، وقِيلَ: إنَّها كانت في سَنَةِ خمسةَ عشرَ."},{"id":183,"title":"قَتْلُ قائدِ الفُرْسِ رُسْتُم .","date":["العام الهجري :14","الشهر القمري : شعبان","العام الميلادي :635"],"text":"هو رُسْتُم فرخزاد قائدُ الجيشِ الفارسيِّ في عَهدِ آخر مُلوكِ الدَّولةِ السَّاسانيَّةِ يزدجرد الثَّالث أصلُه مِن أَرْمِينيَة، وكان يَخدُم مَلِكَ الفُرْسِ بإخلاصٍ، أرسل يزدجرد الثَّالث القائدَ رُستمَ مُجبِرًا إيَّاه قِيادةَ الجيش الفارسيِّ لِيواجِهَ جُيوشَ المسلمين التي كانت تَخْترِق العِراقَ تَمهيدًا لفتحِ بِلاد فارس، واجَه رُستم المسلمين في القادِسيَّة وفي رابعِ أيَّام القادسيَّة هَبَّتْ رِيحٌ شديدةٌ فرفعَتْ خِيامَ الفُرْس عن أماكنِها, وألْقَت سَريرَ رُستم الذي هو مَنصوب له، وتَقدَّم القَعقاعُ ومَن معه حتَّى عَثروا على سَريرِ رُستم وهُم لا يَرَوْنه مِن الغُبارِ، وكان رُستم قد ترَكه واسْتَظلَّ بِبَغْلٍ, فوقع على رُستم وهو لا يَشعُر به, فأزال مِن ظَهرِه فَقارًا، وهرَب رُستم نحو نهرِ العتيق لِينجوَ بِنفسه, ولكنَّ هِلالَ بن عَلقمةَ التَّميميَّ أدرَكهُ, فأَمْسكَ بِرِجلِه وسَحبَهُ ثمَّ قتَلَه، وصعَد السَّريرَ ثمَّ نادى: قَتلتُ رُستمَ ورَبِّ الكعبةِ، إليَّ، فأطافوا به, وما يرون السرير, وكبَّروا وتَنادوا."},{"id":184,"title":"مَعركةُ أَجْنادِينَ وهَزيمةُ الرُّومِ بقِيادةِ عَمرِو بن العاصِ .","date":["العام الهجري :15","العام الميلادي :636"],"text":"سار عَمرُو بن العاصِ إلى أَجْنادِينَ وهي تقعُ قريبًا مِن الفالوجَةِ ومكانِ عُبورِ فِلَسْطين مِن الجَنوبِ، إذ رابَط فيها الأَرْطَبُون، وكانت قُوَّةٌ للرُّوم في الرَّمْلَة وأخرى في بيتِ المَقدِس، وطال تَأَخُّرُ فَتحِها، وكانت مُراسلات بين الطَّرفينِ حتَّى ذهَب عَمرٌو بنفسه إلى الأرطبون، وكادوا يَقتُلونه ولكنَّه فَطَنَ لهم وخادَعهُم ورجَع سالمًا، ثمَّ حدَث قِتالٌ عظيمٌ يُشْبِهُ يومَ اليَرموكِ حتَّى دخَل المسلمون أَجنادِينَ، ثمَّ تَقدَّموا إلى بيتِ المَقدِس."},{"id":185,"title":"فَتحُ قِنَّسْرِينَ بقِيادةِ خالدِ بن الوَليد .","date":["العام الهجري :15","العام الميلادي :636"],"text":"أرسل أبو عُبيدةَ عامرُ بن الجَرَّاح خالدَ بنَ الوَليد إلى قِنَّسْرِينَ، فلمَّا نزَل الحاضرَ زحَف إليهم الرُّومُ وعليهم مِيناسُ، وكان مِن أعظمِ الرُّومِ بعدَ هِرقل، فاقتتلوا فقُتِلَ مِيناسُ ومَن معه مَقتلةً عظيمةً لم يُقتلوا مِثْلَها، فماتوا على دمٍ واحدٍ، وسار خالدٌ حتَّى نزَل على قِنَّسْرين فتَحصَّنوا منه، فقالوا: لو كنتم في السَّحابِ لحَمَلَنا الله إليكم، أو لأَنْزَلَكُم إلينا، فنَظروا في أَمرِهم ورأوا ما لَقِيَ أهلُ حِمْصَ، فصالَحوهُم على صُلْحِ حِمْصَ، فأبى خالدٌ إلَّا على إخرابِ المدينةِ فأَخرَبها، فعند ذلك دخَل هِرقلُ القُسْطَنْطِينِيَّةَ؛ وسببُه: أنَّ خالدًا وعِياضًا أَدْرَبا إلى هِرقل مِن الشَّام، وأَدْرَب عَمرُو بن مالكٍ مِن الكوفةِ، فخرَج مِن ناحيةِ قَرْقِيسِيا، وأَدْرَبَ عبدُ الله بن المُعْتَمِّ مِن ناحيةِ المَوْصِل ثمَّ رجعوا، فعندها دخَل هِرقلُ القُسطنطينيَّة، وكانت هذه أوَّلَ مَدْرَبَةٍ في الإسلامِ سنةَ خمسَ عشرةَ، وقِيلَ: ستَّ عشرةَ. -أَدْرَبَ في الغَزْوِ أي جاوَز الدَّرْبَ إلى العَدُوِّ-."},{"id":186,"title":"فَتحُ مَدينةِ حِمْصَ بقِيادةِ أبي عُبيدةَ عامرِ بن الجَرَّاحِ .","date":["العام الهجري :15","الشهر القمري : ربيع الآخر","العام الميلادي :636"],"text":"فتَح المسلمون بقِيادةِ أبي عُبيدةَ عامرِ بن الجَرَّاحِ مدينةَ حِمْصَ، بعدَ أن حاصروها حِصارًا شديدًا واضْطَرَّتْ المدينةُ إلى طلبِ الصُّلْحِ، فكتَب المسلمون لأهلِها كِتابًا بالأمانِ على أَنفُسِهم وأموالِهم."},{"id":187,"title":"فَتْحُ بيتِ المَقدِس .","date":["العام الهجري :15","الشهر القمري : جمادى الآخرة","العام الميلادي :636"],"text":"لمَّا فتَح أبو عُبيدةَ الجابِيَةَ مِن أعمالِ دِمشقَ وقِنَّسرينَ وحاصَر أهلَ مَسجدِ إيليا -أي بيت المَقدِس- فأَبَوْا أن يَفتَحوا له، وسَألوه أن يُرْسِلَ إلى صاحِبِه عُمَرَ لِيَقْدُمَ فيكون هو الذي يَتوَلَّى مُصالحَتَهُم، فكتَب بذلك إلى عُمَرَ فاسْتخلفَ علِيَّ بن أبي طالبٍ على المدينةِ, ثمَّ قَدِمَ للشَّامِ, وكتَب إلى أُمراءِ الأجنادِ أن يُوافُوه بالجابِيَةِ ليومٍ سَمَّاهُ لهم في المُجَرَّدَةِ، ويَستخلِفوا على أعمالِهم، وكان أوَّلَ مَن لَقِيَهُ فيها أبو عُبيدةَ, فلمَّا دخَل الجابِيَةَ قال له رجلٌ مِن اليَهودِ: يا أميرَ المؤمنين، إنَّك لا تَرجِع إلى بِلادِك حتَّى يفتحَ الله عليك إيلياء. فبينما عُمَر مُعسكرٌ بالجابِيَةِ فزَع النَّاسُ إلى السِّلاحِ، فقال: ما شَأنُكم؟ فقالوا: ألا ترى إلى الخيلِ والسُّيوفِ؟ فنظَر فإذا جَمْعٌ يلمعون بالسُّيوفِ. فقال عُمَرُ: مُسْتَأْمِنَةً فلا تُراعُوا، فأَمِّنُوهُم. وإذا أهلُ إيلياء، فصالَحهُم على الجِزيةِ, وعلى أن لا يَهْدِمَ كَنائِسَها، ولا يُجْلِيَ رُهْبانَها، ففَتَحوها له، وبَنَى بها مَسجِدًا، وأقام أيَّامًا ثمَّ رجَع إلى المدينةِ."},{"id":188,"title":"دُخولُ عُمَرَ بن الخطَّاب رضِي الله عنه بيت المَقدِس ماشِيًا على قَدَمَيْهِ  .","date":["العام الهجري :15","الشهر القمري : جمادى الآخرة","العام الميلادي :636"],"text":"بعدَ أن كتَب الله النَّصرَ للمسلمين وفتحوا إيليا بيتَ المَقدِس طلَب أهلُه أنَّ يُصالَحوا على صُلحِ أهلِ مُدُنِ الشَّام، وأن يكونَ المُتولِّي للعَقدِ عُمَر بن الخطَّاب، أَبَى بَطْرِيقُها أن يُسَلِّمَ مَفاتيحَ القُدسِ إلَّا للخليفةِ عُمَر بن الخطَّاب، فحضَر عُمَر رضِي الله عنه والقِصَّةُ في دُخولِه مَشهورةً، حيث كان يَتَناوَب على بَعيرٍ مع خادِمِه، فكانت نَوْبَةُ عُمَر المَشْيَ حين وُصولِهم إلى القُدْس، ولم يَرْضَ عُمَر أن يَركبَ بدلًا عن خادِمه مع طَلَبِ الخادِم ذلك، ولم يَأْبَه لتلك الوَجاهات المُزَيَّفَةِ فدَخَلها ماشِيًا، فكان ذلك مِن العَلامات التي زعَم البَطْريقُ أنَّها تكون فيمَن يَسْتَلِم المفاتيحَ، فأخَذها عُمَرُ وصلَّى في بيتِ المَقدِس واتَّخذَهُ مَسجدًا كما كان، ولم يُصَلِّ بالقُرْبِ مِن الصَّخرةِ رغمَ مَشورةِ بعضِهم له بذلك، ثمَّ عقَد الصُّلْحَ مع أهلِها وكتَب بذلك الشُّروطَ المَشهورَةَ بالشُّروطِ العُمَرِيَّةِ."},{"id":189,"title":"بَدْأُ غارات المسلمين على الأَناضُول (تُرْكِيا) بقِيادةِ سُراقةَ بن عَمرٍو وعبدِ الرَّحمن بن رَبيعةَ .","date":["العام الهجري :16","العام الميلادي :637"],"text":"نَدَبَ عُمَرُ بن الخطَّاب سُراقةَ بن عَمرٍو، وعبدَ الرَّحمن بن رَبيعةَ للمَسيرِ إلى بِلادِ البابِ، وهي بِلادُ التُّرْكِ خلفَ بابِ الأبوابِ المعروف بالدَّرْبَنْد، وأَمَدَّهُ عُمَرُ بن الخطَّاب بحَبيبِ بن مَسلمةَ، ولكنَّ شَهْرَيراز مَلِكَ تلك البِلادِ طلَب مِن عبدِ الرَّحمن أن يُمْهِلَهُ ففعَل، كما عَبَّرَ له عن كُرْهِهِ للأَرْمَن والقَبْج الذين يُقيمون حول بِلادِه، وأَعرَب عن نَواياهُ الطَّيِّبَة للمسلمين، وطلَب أن يُعْفوهُ مِن الجِزيَة مُقابل أن يُساعِدَهم في حُروبِهم على الأَرْمَن ومَن حولَهم، فقَبِلَ ذلك سُراقةُ، وأَقَرَّهُ عُمَر على ذلك، فَوَجَّه سُراقةُ أربعةَ جُيوشٍ إلى البِلادِ المُحيطَةِ بأَرْمِينِيَة وفَتَحَها."},{"id":190,"title":"وَفاةُ مارِيا القِبطيَّة رضِي الله عنها  .","date":["العام الهجري :16","الشهر القمري : محرم","العام الميلادي :637"],"text":"هي مارِيا القِبطيَّة، أهداها المُقَوْقِسُ القِبطيُّ للنَّبيِّ صلَّى الله عليه وسلَّم، تَسَرَّى بها النَّبيُّ صلَّى الله عليه وسلَّم، ووَلدَت له إبراهيمَ، فقال: (أَعْتَقَها وَلَدُها)، فلا تُعَدُّ مِن زَوجاتِه صلَّى الله عليه وسلَّم، وبالتَّالي لَيست مِن أُمَّهات المؤمنين، أَنفَق عليها أبو بكرٍ وعُمَر إلى أن تُوفِّيَت في خِلافَتِه وصلَّى عليها بِنفسِه."},{"id":191,"title":"فَتحُ بَهُرَسِيرَ \"المَدائِن الغَربيَّة\" بقِيادةِ سعدِ بن أبي وَقَّاصٍ .","date":["العام الهجري :16","الشهر القمري : صفر","العام الميلادي :637"],"text":"كان انتِصارُ المسلمين في القادِسيَّة دافعًا لهم للاستمرار في زَحْفِهم نحو المدائنِ عاصِمَةِ الفُرْسِ، وسار سعدٌ بجُنودِه حتَّى وصَل إلى بَهُرَسِيرَ \"المدائن الغَربيَّة\" وكانت إحدى حواضِر فارِسَ، فنزَل سعدٌ قريبًا منها، وأرسَل مجموعةً مِن جُنودِه لاستِطلاعِ المَوقِف، وعاد الجُنودُ وهُم يَسوقون أَمامَهم آلافَ الفَلَّاحين، مِن أهلِ تلك المدينةِ. وحينما عَلِمَ شيرزارُ دَهْقانُ -أمير- ساباط بالأَمْرِ أرسَل إلى سعدِ يَطلُب منه إطلاقَ سَراحِ هؤلاء الفَلَّاحين، ويُخبِره أنَّهم ليسوا مُقاتِلين، وإنَّما هُم مُجرَّد مُزارِعين أُجَراء، وأنَّهم لم يُقاتلوا جُنودَه؛ فكتب سعدٌ إلى عُمَر يَعرِض عليه المَوقِف ويَسألُه المَشورةَ: إِنَّا وَرَدْنا بَهُرَسِيرَ بعدَ الذي لَقِينا فيما بين القادِسيَّة وبَهُرَسِيرَ، فلم يأتِ أحدٌ لِقِتالٍ، فبَثَثْتُ الخُيولَ، فجمعتُ الفَلَّاحين مِن القُرى والآجامِ. فأجابه عُمَر: إنَّ مَن أتاكُم مِن الفَلَّاحين إذا كانوا مُقيمين لم يُعينوا عليكم فهو أَمانُهم، ومَن هرَب فأَدركْتُموهُ فشَأنُكم به. فلمَّا جاءهُ خِطابُ عُمَر خَلَّى سعدٌ سَبيلَهُم. وأرسَل سعدٌ إلى الدَّهاقين - رُؤساء المُدُن والأقاليم- يَدعوهُم إلى الإسلامِ، على أن يكونَ لهم ما هُم عليه مِن الإمارةِ والحُكْمِ، أو الجِزْيَة ولهم الذِّمَّةُ والمَنَعَةُ، فدخَل كثيرٌ منهم الإسلامَ لِما وَجدوه مِن سَماحةِ المسلمين وعَدْلِهم مع ما هُم عليه مِن بأسٍ وقُوَّةٍ، ولكنَّ بَهُرَسِيرَ امتنَعَت عنه، وظَنَّ أهلُها أنَّ حُصونَها تَحولُ دون فَتحِ المسلمين لها، فحاصَرها سعدٌ بِجُنودِه طُوالَ شَهرينِ يَرمونَها بالمجانيق، ويَدُكُّونها بالدَّباباتِ التي صنعوها مِن الجُلودِ والأخشابِ، ولكنَّ المدينةَ كانت مُحَصَّنةً فنصَب سعدٌ حولَها عِشرين مَنْجَنيقًا في أماكنَ مُتفرِّقةٍ لِيَشْغَلَهُم ويُصرِفَهم عن مُلاحظَةِ تَقَدُّمِ فِرْسانِه نحو المدينةِ لاقتِحامِها، وأَحَسَّ الفُرْسُ بمُحاولَةِ المسلمين اقْتِحامَ المدينة؛ فخرَج إليهم عددٌ كبيرٌ مِن الجُنودِ الفُرْس لِيُقاتِلوهم ويمنعوهم مِن دُخولِ المدينةِ، وضرَب المسلمون أَرْوَعَ الأمثلةِ في البُطولةِ والفِداءِ، وقُوَّةِ التَّحَمُّلِ والحِرصِ على الشَّهادةِ، وكان القائدُ زُهْرَةُ بن الجويّة واحدًا مِن أولئك الأبطالِ الشُّجْعانِ، استطاع أن يَصِلَ إلى قائدِ الفُرْسِ شهْربَرَاز، فضرَبه بِسَيفِه فقتَله، وما إن رأى جُنودُ الفُرْسِ قائِدَهم يَسقُط على الأرضِ مُضْرَجًا في دِمائِه حتَّى تَمَلَّكَهُم الهَلَعُ والذُّعْرُ، وتَفرَّق جمعُهم، وتتَشتَّت فِرْسانُهم، وظَلَّ المسلمون يُحاصِرون بَهُرَسِيرَ بعدَ أن فَرَّ الجُنودُ والْتَحَقوا بالفَيافِي والجِبالِ، واشْتَدَّ حِصارُ المسلمين على المدينةِ؛ حتَّى اضْطَرَّ أهلُها إلى أكلِ الكِلابِ والقِطَطِ، فأرسَل مَلِكُهم إلى المسلمين يَعرِض الصُّلْحَ على أن يكونَ للمسلمين ما فَتحوهُ إلى دِجْلَة، ولكنَّ المسلمين رَفَضوا وظَلُّوا يُحاصِرون المدينةَ، ويَضرِبونَها بالمجانيق، واسْتَمرَّ الحالُ على ذلك فَترةً مِن الوقتِ، وبَدَتْ المدينةُ هادِئةً يُخَيِّمُ عليها الصَّمتُ والسُّكونُ، وكأنَّهُ لا أثَرَ للحياةِ فيها، فحمَل المسلمون عليها ليلًا، وتَسَلَّقوا أَسوارَها وفَتحوها، ولكنَّ أحدًا لم يَعتَرِضْهُم مِن الجُنودِ، ودخَل المسلمون بَهُرَسِيرَ \"المدائن الغَربيَّة\" فاتحين بعد أن حاصروها زمنًا طويلًا."},{"id":192,"title":"فَتحُ مَدائنِ القُصورِ عاصِمةِ الفُرْسِ بقِيادةِ سعدِ بن أبي وَقَّاص .","date":["العام الهجري :16","الشهر القمري : صفر","العام الميلادي :637"],"text":"عزَم سعدُ بن أبي وَقَّاص أن يَعْبُرَ جَيشُه دِجلَة بالخيلِ، فجمَع النَّاس فحمِد الله وأثنى عليه ثمَّ قال: إنَّ عَدُوَّكُم قد اعْتصَم منكم بهذا البحرِ، فلا تَخْلُصون إليه معه ويَخْلُصون إليكم إذا شاءوا في سُفُنِهم فَيُناوِشُونَكُم، وليس وَراءَكُم شيءٌ تخافون أن تُؤْتَوْا منه، قد كَفاكُم أهلُ الأيَّام وعَطَّلُوا ثُغورَهُم، وقد رأيتُ مِن الرَّأي أن تُجاهِدوا العَدُوَّ قبلَ أن تَحْصُدَكُم الدّنيا، ألا إِنِّي قد عَزمتُ على قَطْعِ هذا البحرِ إليهم. فقالوا جميعًا: عزَم الله لنا ولك على الرُّشْدِ، فافْعَلْ. فندَب النَّاسَ إلى العُبورِ وقال: مَن يَبدأُ ويَحْمي لنا الفِراضَ حتَّى تَتلاحَقَ به النَّاسُ لِكَيْلا يَمنَعوهُم مِن العُبورِ؟ فانْتَدَبَ عاصمُ بن عَمرٍو ذو البَأْسِ، في سِتِّمائةٍ مِن أهلِ النَّجدات لِيَحموا لهم الشَّاطئَ مِن الفُرْسِ حتَّى تَتَلاحقَ الجُنْدُ، ولمَّا رَأى سعدٌ عاصِمًا على الفِراضِ قد مَنَعَها، أَذِنَ للنَّاسِ في الاقتحامِ وقال: قولوا: نَستَعينُ بالله، ونَتوَكَّلُ عليه، حَسبُنا الله ونِعْمَ الوَكيلُ، والله ليَنْصُرَنَّ الله وَلِيَّهُ، وليُظْهِرَنَّ دِينَهُ، وليَهْزِمَنَّ عَدُوَّهُ، لا حولَ ولا قُوَّةَ إلَّا بالله العَلِيِّ العظيمِ. وتَلاحَقَ النَّاسُ في دِجْلة وإنَّهم يَتَحدَّثون كما يَتَحدَّثون في البَرِّ، وطَبَّقوا دِجْلة حتَّى ما يُرى مِن الشَّاطئ شيءٌ. فلمَّا رَأى الفُرْسَ ذلك، وأَتاهُم أَمْرٌ لم يكنْ في حِسابِهم خرَجوا هاربين نحو حُلْوان، وتَركوا في الخَزائنِ مِن الثِّيابِ والمَتاعِ والآنِيَةِ والفُصوصِ والألطافِ ما لا يُدْرَى قِيمتُه، وخَلَّفُوا ما كانوا أَعَدُّوا للحِصارِ مِن البَقر والغَنَم والأطعِمَة، وكان في بيتِ المالِ ثلاثةُ آلافِ ألف ألف ألف، ثلاث مرَّات، وكان أوَّلَ مَن دخَل المدائنَ كَتيبةَ الأهوالِ، وهي كَتيبةُ عاصمِ بن عَمرٍو، ثمَّ كَتيبةُ الخَرْساء، وهي كَتيبةُ القَعقاعِ بن عَمرٍو، فأخذوا في سِكَكِها لا يَلْقون فيها أحدًا يَخْشَوْنَهُ إلَّا مَن كان في القَصرِ الأبيضِ، فأحاطوا بهم ودَعوهم فاستَجابوا على تَأدِيَةِ الجِزيَةِ والذِّمَّةِ، فتَراجَع إليهم أهلُ المدائنِ على مِثلِ عَهدِهم، ليس في ذلك ما كان لآلِ كِسرى، ونزَل سعدٌ القَصرَ الأبيضَ، واتَّخَذ سعدٌ إيوانَ كِسرى مُصَلَّى، ولمَّا دخَل سعدٌ الإيوانَ قرَأ: {كَمْ تَرَكُوا مِنْ جَنَّاتٍ وَعُيُونٍ} [الدخان: 25]...الآيةَ، وصلَّى فيه صَلاةَ الفَتحِ ثماني رَكعاتٍ، ثمَّ جمَع ما في القَصرِ والإيوانِ والدُّورِ مِن الغنائمِ، وكان أهلُ المدائنِ قد نَهبوها عند الهَزيمةِ، وهَربوا في كُلِّ وَجهٍ، فما أَفْلَتَ أحدٌ منهم بشيءٍ إلَّا أَدْرَكَهُم الطَّلَبُ، فأخذوا ما معهم، ورَأَوْا بالمدائنِ قِبابًا تُرْكِيَّةً مَمْلُؤةً سِلالًا مَختومَةً بِرَصاصٍ فحَسَبوها طعامًا، فإذا فيها آنِيَةُ الذَّهبِ والفِضَّةِ."},{"id":193,"title":"بِناءُ أوَّلِ مَسجدٍ في المدائنِ عاصِمَة إمْبراطورِيَّة فارِسَ  .","date":["العام الهجري :16","الشهر القمري : صفر","العام الميلادي :637"],"text":"لمَّا دخَل المسلمون المدائنَ وفتحوها واتَّخذَ سعدُ بن أبي وَقَّاص قَصرَها مَسكنًا جعَل إيوانَها المشهورَ مَسجدًا ومُصَلَّى وتَلَا قولَه تعالى: {كَمْ تَرَكُوا مِنْ جَنَّاتٍ وَعُيُونٍ (25) وَزُرُوعٍ وَمَقَامٍ كَرِيمٍ (26) وَنَعْمَةٍ كَانُوا فِيهَا فَاكِهِينَ (27) كَذَلِكَ وَأَوْرَثْنَاهَا قَوْمًا آخَرِينَ (28) فَمَا بَكَتْ عَلَيْهِمُ السَّمَاءُ وَالْأَرْضُ وَمَا كَانُوا مُنْظَرِينَ} [الدخان: 25 - 29] ثمَّ صلَّى الجُمُعَةَ في الإيوانِ."},{"id":194,"title":"بِدايَةُ التَّاريخِ الهِجْرِيِّ .","date":["العام الهجري :16","الشهر القمري : ربيع الأول","العام الميلادي :637"],"text":"كتَب أبو موسى الأَشعريُّ إلى عُمَر: إنَّه يأتينا منك كُتُبٌ ليس لها تاريخٌ، فجمَع عُمَرُ النَّاسَ للمَشُورَةِ، فقال بعضُهم: أَرِّخْ لِمَبْعَثِ النَّبيِّ صلَّى الله عليه وسلَّم. وقال بعضُهم: لمُهاجرَةِ رسولِ الله صلَّى الله عليه وسلَّم. فقال عُمَرُ: بل نُؤَرِّخُ لمُهاجرَةِ رسولِ الله صلَّى الله عليه وسلَّم، فإنَّ مُهاجَرتَه فَرْقٌ بين الحَقِّ والباطلِ. قاله الشَّعْبِيُّ، وقال مَيمونُ بن مِهْرانَ: وقِيلَ: رُفِعَ إلى عُمَرَ صَكٌّ مَحِلُّهُ شَعبان، فقال: أَيُّ شَعبان؟ أَشَعبان الذي هو آتٍ، أم شَعبان الذي نحن فيه؟ ثمَّ قال لأصحابِ رسولِ الله، صلَّى الله عليه وسلَّم: ضَعوا للنَّاسِ شيئًا يَعرِفونه. فقال بعضُهم: اكْتُبوا على تاريخ الرُّومِ، فإنَّهم يُؤَرِّخون مِن عَهدِ ذي القَرْنينِ. فقال: هذا يَطُول. فقال: اكْتُبوا على تاريخ الفُرْسِ. فقِيلَ: إنَّ الفُرْسَ كُلمَّا قام مَلِكٌ طَرَحَ تاريخَ مَن كان قَبلَهُ. فاجتمع رَأيُهم على أن يَنظروا كم أقام رسولُ الله بالمدينةِ، فوَجدوه عشرَ سِنين، فكتبوا التَّاريخَ مِن هِجرَةِ رسولِ الله صلَّى الله عليه وسلَّم. قال محمَّدُ بن سِيرينَ: قام رجلٌ إلى عُمَر فقال: أَرِّخُوا. فقال عُمَرُ: ما أَرِّخُوا؟ فقال: شيءٌ تَفعلُه الأعاجمُ في شهرِ كذا مِن سَنَةِ كذا. فقال عُمَرُ: حَسَنٌ، فأَرِّخُوا. فاتَّفَقوا على الهِجرَةِ، ثمَّ قالوا: مِن أيِّ الشُّهورِ؟ فقالوا: مِن رَمضان. ثمَّ قالوا: فالمُحَرَّمُ هو مُنْصَرَفُ النَّاسِ مِن حَجِّهِم، وهو شهرٌ حرامٌ. فأَجْمَعوا عليه."},{"id":195,"title":"فَتحُ تَكْريت والمَوْصِل بقِيادةِ عبدِ الله بن المُعْتَمِّ .","date":["العام الهجري :16","الشهر القمري : جمادى الأولى","العام الميلادي :637"],"text":"لمَّا افْتَتَح سعدُ بن أبي وَقَّاص المدائنَ بَلغَه أنَّ أهلَ المَوْصِل قد اجْتَمعوا بِتَكْريت على رَجُلٍ يُقال له: الأنطاق, فكتَب إلى عُمَر بن الخطَّاب بأَمْرِ جَلُولاء، واجْتِماع الفُرْسِ بها, وبأَمْرِ أهلِ المَوْصِل, فكتَب عُمَر في قَضِيَّةِ أهلِ المَوْصِل أن يُعَيِّنَ جيشًا لِحَرْبِهم, ويُؤَمِّرَ عليه عبدَ الله بن المُعْتَمِّ, ففَصَلَ عبدُ الله بن المُعْتَمِّ في خمسةِ آلافٍ مِن المدائنِ, فسار في أربعٍ حتَّى نزَل بِتَكْريت على الأنطاقِ، وقد اجْتَمع إليه جماعةٌ مِن الرُّومِ, ومِن نَصارى العَربِ, مِن إيادٍ, وتَغْلِبَ, والنَّمِرِ, وقد أَحْدَقوا بِتَكْريت, فحاصَرهُم عبدُ الله بن المُعْتَمِّ أربعين يومًا, وزاحَفوهُ في هذه المُدَّةِ أربعةً وعشرين مَرَّةً, ما مِن مَرَّةٍ إلَّا ويَنْتَصِرُ عليهم, وراسَل عبدُ الله بن المُعْتَمِّ مَن هنالك مِن الأَعرابِ, فدَعاهُم إلى الدُّخولِ معه في النُّصْرَةِ, وفَلَّ جُموعَهم, فضَعُفَ جانِبُهُم, وعزَمَت الرُّومُ على الذِّهابِ في السُّفُنِ بأَموالِهم إلى أهلِ البلدِ, فجاءت القُصَّادُ إليه عنهم بالإجابةِ إلى ذلك, فأرسَل إليهم: إن كنتم صادِقين فيما قُلتُم فاشْهَدوا أنَّ لا إلهَ إلَّا الله، وأنَّ محمَّدًا رسولُ الله, وأَقِرُّوا بما جاء مِن عند الله. فرجعت القُصَّادُ إليه بأَنَّهم قد أسلموا, فبعَث إليهم: إن كنتم صادِقين، فإذا كَبَّرْنا وحَمَلْنا على البلدِ اللَّيلةَ فأَمْسِكوا علينا أبوابَ السُّفُنِ, وامْنَعوهُم أن يَركَبوا فيها, واقْتُلوا منهم مَن قَدَرْتُم على قَتلِه, ثمَّ شَدَّ عبدُ الله وأصحابُه, وكَبَّروا تَكبيرةَ رَجُلٍ واحدٍ, وحَمَلوا على البلدِ, فكَبَّرت الأعرابُ مِن النَّاحيةِ الأُخرى, فَحَارَ أهلُ البلدِ, وأخذوا في الخُروجِ مِن الأبوابِ التي تَلِي دِجْلَة, فتَلَقَّتْهُم إيادٌ والنَّمِرُ وتَغْلِبُ, فقَتَلوهُم قتلًا ذَريعًا, وجاء عبدُ الله بن المُعْتَمِّ بأصحابِه مِن الأبوابِ الأُخَرِ, فقتَل جميعَ أهلِ البلدِ عن بَكْرَةِ أَبيهِم ولم يُسْلِم إلَّا مَن أَسلَم مِن الأعرابِ مِن إيادٍ وتَغْلِبَ والنَّمِرِ, وقد كان عُمَرُ عَهِدَ في كِتابِه إذا نُصِروا على تَكْريت أن يَبعَثوا رِبْعِيَّ بن الأفْكَلِ إلى الحِصْنَيْنِ، وهي المَوْصِل سريعًا, فسار إليها كما أَمَرَ عُمَرُ، ومعه سَرِيَّةٌ كثيرةٌ وجماعةٌ مِن الأبطالِ, فسار إليها حتَّى فاجَأَها قبلَ وُصولِ الأخبارِ إليها, فأجابوا إلى الصُّلْحِ, فضُرِبَت عليهم الذِّمَّةُ عن يَدٍ وهُم صاغِرون, ثمَّ قُسِّمَت الأموالُ التي تَحَصَّلت مِن تَكْريت, فبلَغ سَهمُ الفارسِ ثلاثةَ آلافٍ، وسَهمُ الرَّاجِل ألفَ دِرهَم، وبَعَثوا بالأخماسِ مع فُراتِ بن حَيَّانَ, وبالفَتحِ مع الحارِث بن حَسَّانَ, ووَلِيَ إِمْرَةَ حَربِ المَوْصِل رِبْعِيُّ بن الأَفْكَل ووَلِيَ الخَراجَ بها عَرْفَجَةُ بن هَرْثَمَةَ."},{"id":196,"title":"مَوقِعةُ جَلُولاء وهَزيمةُ الفُرْسِ بقِيادةِ هاشمِ بن عُتبةَ بن أبي وَقَّاص .","date":["العام الهجري :16","الشهر القمري : ذي القعدة","العام الميلادي :637"],"text":"بعدَ أن فَرَّ يزدجردُ مِن المدائنِ وسار بِاتِّجاهِ حُلوان، والْتَفَّ مَن الْتَفَّ حولَه خِلالَ مَسيرِه فأَمَّرَ عليهم مِهرانَ وأقاموا بجَلُولاء، وتَحَصَّنوا فيها، وحَفروا الخَنادِقَ حولَها، فبعَث سعدٌ إلى عُمَر يُخبِره بذلك، فأَمَرَهُ أن يُقيمَ بالمدائنِ، ويُرْسِل إليهم هاشمَ بن عُتبةَ بن أبي وَقَّاص، فسار إليهم هاشمٌ وحاصَرهُم، واشْتَدَّ القِتالُ، وكانت النَّجدات تَصِلُ إلى الطَّرفين حتَّى فتَح الله على المسلمين، وقد قتَلوا مِن الفُرْسِ الكثيرَ."},{"id":197,"title":"بناء مدينة الكوفة في خلافة عمر بن الخطاب رضي الله عنه .","date":["العام الهجري :17","العام الميلادي :638"],"text":"لمَّا نزَل المسلمون المدائنَ اجْتَوَوْها فشَكُوا ذلك, فكتَب حُذيفةُ إلى عُمَر: إنَّ العَربَ قد رَقَّتْ بُطونُها، وجَفَّتْ أَعضادُها، وتَغَيَّرَتْ أَلوانُها. وكان مع سعدٍ, فكتَب عُمَرُ إلى سعدٍ: أَخبِرني ما الذي غَيَّرَ أَلوانَ العَربِ ولُحومَهُم؟ فكتَب إليه سعدٌ: إنَّ الذي غَيَّرَهُم وُخومَةُ البِلادِ، وإنَّ العَربَ لا يُوافِقُها إلَّا ما وافَق إِبِلَها مِن البُلدانِ. فكتَب إليه عُمَر: أن ابْعَثْ سَلمانَ وحُذيفةَ رائِدَيْنِ فَلْيَرتادا مَنزِلًا بَرِّيًّا بَحْرِيًّا ليس بيني وبينكم فيه بَحرٌ ولا جِسْرٌ. فأَرسلَهُما سعدٌ، فخرَج سَلمانُ حتَّى أتى الكوفَةَ، وسار حُذيفةُ في شَرقِيِّ الفُراتِ لا يَرضى شيئًا حتَّى أتى الكوفَةَ، وكلُّ رَمْلٍ وحَصْباء مُخْتَلِطَيْنِ فهو كوفةُ، فأَتَيا عليها وفيها ثلاثةُ أَدْيِرَةٍ للنَّصارى، فأَعجبَتْهُما البُقعَةُ، فنَزَلا فَصَلَّيا، ودَعَوا الله تعالى أن يَجعلَها مَنزِلَ الثَّباتِ. فلمَّا رجَعا إلى سعدٍ بالخَبَرِ وقَدِمَ كِتابُ عُمَر إليه أيضًا كتَب سعدٌ إلى القَعقاعِ بن عَمرٍو وعبدِ الله بن المُعْتَمِّ أن يَسْتَخْلِفا على جُنْدِهما ويَحضَرا عنده، ففَعَلا، فارْتَحَل سعدٌ مِن المدائنِ حتَّى نزَل الكوفةَ في المُحَرَّمِ سَنَةَ سبعَ عشرةَ، وكان بين نُزولِ الكوفةِ ووَقعةِ القادِسيَّة سَنَةٌ وشَهرانِ، وكان فيما بين قِيامِ عُمَر واخْتِطاط الكوفةِ ثلاثُ سِنين وثمانيةُ أَشْهُر. ولمَّا نزَلها سعدٌ وكتَب إلى عُمَر: إنِّي قد نزَلتُ بالكوفةِ مَنزِلًا فيما بين الحِيرَةِ والفُراتِ بَرِّيًّا وبَحْرِيًّا، وخَيَّرْتُ المسلمين بينها وبين المدائنِ، فمَن أَعجبَهُ المقامُ بالمدائنِ تَركتُه فيها كالمَسْلَحَةِ. ولمَّا اسْتَقَرُّوا بها عَرَفوا أَنفُسَهُم، ورجَع إليهم ما كانوا فَقَدوا مِن قُوَّتِهم، واسْتَأْذَنَ أهلُ الكوفةِ في بُنيانِ القَصَبِ."},{"id":198,"title":"فَتحُ المسلمين لبلاد الأَهْوازِ بعد أن استولى عليها الهُرمُزان .","date":["العام الهجري :17","العام الميلادي :638"],"text":"بعدَ أن تَغَلَّبَ الهُرمُزانُ على مَنطِقَةِ الأَهْوازِ أصبحَ يُغِيرُ على المناطِقِ التي دانت للمسلمين، فسار إليه جَيْشان مِن المسلمين مِن الكوفةِ ومِن البَصْرَةِ فأَجبَروه على الصُّلْحِ، ثمَّ نَقَضَ الهُرْمُزان الصُّلْحَ فبَرَزَ له المسلمون ثانِيَةً ففَرَّ إلى تُسْتَر فحاصَروهُ فيها فطلَب الصُّلْحَ ثانِيَةً، وكانت الأهوازُ قد فُتِحَتْ ثمَّ نَقَضَ الهُرمُزان الصُّلْحَ ثانيةً، فسَيَّرَ إليه عُمَرُ بن الخطَّاب ثلاثةَ جُيوشٍ فهُزِمَ الهُرمُزان وفَرَّ إلى تُسْتَر، فلَحِقَهُ المسلمون وحاصَروهُ فيها ثانيةً فاضْطَرُّوهُ للاستسلامِ بعدَ فتحِ البلدةِ عَنْوَةً، وأُرْسِلَ الهُرمُزانُ إلى عُمَر بن الخطَّابِ."},{"id":199,"title":"غَزْوُ العَلاءِ بن الحَضْرَميِّ بِلادَ فارِسَ مِن البَحْرَين وفَتحُ إصْطَخْر  .","date":["العام الهجري :17","العام الميلادي :638"],"text":"كان العلاءُ بن الحَضْرَميِّ رضِي الله عنه واليَ البَحْرين، وكان يُسابِق سعدَ بن أبي وَقَّاص في الفَتحِ، فلمَّا كتَب الله النَّصرَ في القادِسيَّة، وكان له الصَّدى الواسعُ أَحَبَّ العَلاءُ أن يكونَ له النَّصرُ على فارِسَ مِن جِهَتِهِ، فنَدَبَ النَّاسَ إلى الجِهادِ، فاجتمَع الجيشُ وعَبَروا البحرَ إلى فارِسَ، ولكن كلّ ذلك دون إذْنِ عُمَر بن الخطَّاب، واتَّجه العَلاءُ إلى إصْطَخْر -مدينة جنوب إيران- وقاتلوا حتَّى انتصروا وفتحوها، ولكنَّ الفُرْسَ قطَعَت طَريقَهُم إلى سُفُنِهم فبَقَوْا مُحاصَرين ممَّا أَدَّى إلى عَزْلِ العَلاءِ، وطلَب منه الالتحاقَ بسعدِ بن أبي وَقَّاص وطلَب مِن عُتبةَ بن غَزْوانَ أن يُنْجِدَ العَلاءَ، فانْتَصَر المسلمون ثمَّ عادوا إلى البَصْرَةِ."},{"id":200,"title":"عُمَر بن الخطَّاب رضي الله عنه يَزيدُ في مساحة المسجدِ النَّبوِيِّ .","date":["العام الهجري :17","العام الميلادي :638"],"text":"لم يَزِدْ أبو بكرٍ الصِّدِّيقُ رضِي الله عنه في عَهدِه بالمسجدِ النَّبوِيِّ الشَّريف لانشغالِه بحُروبِ الرِّدَّةِ، ولكن في عَهدِ عُمَر بن الخطَّاب رضِي الله عنه ضاق المسجدُ بالمُصلِّين لِكثرَةِ النَّاسِ، فقام عُمَر بِشِراءِ الدُّورِ التي حولَ المسجدِ النَّبوِيِّ الشَّريف وأَدخَلها ضِمْنَ المسجدِ، وكانت تَوْسِعَتُه مِن الجِهَةِ الشَّماليَّة والجَنوبيَّة والغَربيَّة. فقد زاد مِن ناحِيَةِ الغَربِ عشرين ذِراعًا، ومِن الجِهَةِ الجَنوبيَّة \"القِبْلَة\" عشرة أَذْرُع، ومِن الجِهَةِ الشَّماليَّة ثلاثين ذِراعًا. ولم يَزِدْ مِن جِهَةِ الشَّرقِ لِوُجودِ حُجُراتِ أُمَّهات المؤمنين رضِي الله عنهم أجمعين. فأصبح طولُ المسجدِ 140 ذِراعًا مِن الشَّمال إلى الجنوب، و120 ذِراعًا مِن الشَّرق إلى الغَرب. وكان بِناءُ عُمَر كبِناءِ النَّبيِّ صلَّى الله عليه وسلَّم، فكانت جُدْرانُه مِن اللَّبِن وأَعمِدَتُه مِن جُذوعِ النَّخيل، وسَقْفُه مِن الجَريدِ بِارتِفاع 11 ذِراعًا، وقد فَرَشَهُ بالحَصْباءِ، والتي أُحْضِرت مِن العَقيقِ. وجعَل له سُتْرَةً بِارتِفاع ذِراعين أو ثلاثة، وتُقَدَّرُ هذه الزِّيادة بحوالي 3300 ذِراعًا مُرَبَّعًا، وجعَل للمَسجِد 6 أبواب: اثنين مِن الجِهَةِ الشَّرقيَّة، واثنين مِن الجِهَةِ الغَربيَّة، واثنين مِن الجِهَة الشَّماليَّة."},{"id":201,"title":"فَتحُ الجَزيرةِ وأَرْمِينِيَة .","date":["العام الهجري :17","الشهر القمري : ذي الحجة","العام الميلادي :639"],"text":"أرسَل سعدُ بن أبي وَقَّاص العَساكِرَ إلى الجَزيرةِ، فخرَج عِياضُ بن غَنْمٍ إليها وفي صُحبَتِه أبو موسى الأشعريُّ, وعُمَرُ بن سعدِ بن أبي وَقَّاص -وهو غُلامٌ صغيرُ السِّنِّ ليس إليه مِن الأمر شيءٌ- وعُثمانُ بن أبي العاصِ، فنزَل الرُّها, فصالَحهُ أهلُها على الجِزيَة, وصالَحَت حَرَّانُ على ذلك, ثمَّ بعَث أبا موسى الأشعريَّ إلى نَصِيبِين, وعُمَرَ بن سعدٍ إلى رَأْسِ العَيْنِ, وسار بنفسه إلى دارا, فافْتُتِحَت هذه البُلدان، وبعَث عُثمانَ بن أبي العاصِ إلى أرْمِينِيَة, فكان عندها شيءٌ مِن قِتالٍ قُتِلَ فيه صَفوانُ بن المُعَطَّلِ السُّلَميُّ, ثمَّ صالَحهُم عُثمانُ بن أبي العاصِ على الجِزيَةِ، على كلِّ أهلِ بيتٍ دينارٌ."},{"id":202,"title":"طاعونُ عِمْواس في الشَّام ووَفاةُ عددٍ مِن المسلمين مُتأَثِّرين به. .","date":["العام الهجري :18","العام الميلادي :639"],"text":"أصاب الشَّامَ في ذلك العام طاعونٌ عامٌّ شديدٌ حَصَد الكثيرَ مِن النَّاسِ، وسُمِّيَ ذلك العامُ بعام عَمْواس مِن شِدَّةِ ما حصَل مِن الموتِ, وقد مات فيه خمسةٌ وعشرون ألفًا, وكان ممَّن تُوفِّيَ فيه أبو عُبيدةَ بن الجَرَّاح، ومعاذ بن جبل، ويَزيدُ بن أبي سُفيانَ، وشُرَحْبِيلُ بن حَسَنَةَ، وغيرُهم كثيرٌ، وعَمْواس هو اسمُ المكان الذي انْتَشَر فيه الطَّاعونُ، وهو مكانٌ قَريبٌ مِن الرَّمْلَةِ في فِلَسطين."},{"id":203,"title":"وَفاةُ أبي عُبيدةَ بن الجَرَّاح رضِي الله عنه .","date":["العام الهجري :18","العام الميلادي :639"],"text":"هو أمينُ الأُمَّةِ عامرُ بن عبدِ الله بن الجَرَّاح رضِي الله عنه، اشْتَهَر بكُنْيَتِه, أبي عُبيدةَ، أحدُ العشرةِ المُبَشَّرين بالجنَّةِ، شَهِدَ بدرًا وأُحُدًا والمَشاهِدَ كُلَّها مع رسولِ الله صلَّى الله عليه وسلَّم، وهو مِن السَّابقين إلى الإسلامِ، وهاجَر إلى الحَبَشةِ وإلى المدينةِ أيضًا، وكان يُدْعى: القويَّ الأمينَ، آخَى النَّبيُّ صلَّى الله عليه وسلَّم بينه وبين أبي طَلحةَ الأنصاريِّ، كان مِن القُوَّادِ الفاتحين زَمَنَ عُمَر، حيث عَيَّنهُ قائدًا لِجُيوشِ الشَّام بعدَ عَزْلِ خالدِ بن الوَليد، وكان عُمَرُ يُجِلُّهُ كثيرًا حتَّى قِيلَ: إنَّ عُمَر قال: لو كان أبو عُبيدةَ حَيًّا لاسْتَخْلَفْتُه, وقال عُمَرُ لأصحابِه يومًا: تَمَنَّوْا. فقال رجلٌ أَتَمَنَّى لو أنَّ لي هذه الدَّارَ مَملوءةٌ ذهبًا انْفقتُه في سَبيلِ الله عزَّ وجلَّ. ثمَّ قال: تَمَنَّوْا. فقال رجلٌ: أَتَمَنَّى لو أنَّها مملوءةٌ لُؤْلُؤًا وزَبَرْجَدًا أو جَوْهرًا أُنْفِقُه في سَبيلِ الله عَزَّ وجلَّ وأَتَصدَّقُ به. ثمَّ قال: تَمَنَّوْا. فقالوا: ما نَدري يا أميرَ المؤمنين. فقال عُمَرُ: أَتَمَنَّى لو أنَّ هذا الدَّارَ مملوءةٌ رِجالًا مِثلَ أبي عُبيدةَ بن الجَرَّاحِ. تُوفِّيَ في طاعون عَمْواس على المشهورِ."},{"id":204,"title":"فَتحُ الرَّيِّ بقِيادةِ نُعَيْمِ بن مُقَرِّن المُزَنيِّ .","date":["العام الهجري :18","العام الميلادي :639"],"text":"خرَج نُعيمُ بن مُقرِّن مِن واج رُوذ في النَّاس إلى دَسْتَبى، فلَقِيَهُ الزَّيْنَبِيُّ أحدُ قادةِ الفُرْسِ بمكان يُقال له: قِها مُسالِمًا ومُخالِفًا لمَلِكِ الرَّيِّ، وقد رأى مِن المسلمين ما رأى، فأقبل مع نُعيمٍ والمَلِكُ يَومئذٍ بالرَّيِّ وهو سِيَاوَخْشُ بن مِهران، فاسْتَمَدَّ أهلَ دَنْباوَنْد وطَبَرِستان وقُومِس وجُرْجان وقال المَلِكُ: قد عَلِمْتُم أنَّ هؤلاء قد حَلُّوا بالرَّيِّ، وإنَّه لا مُقامَ لكم، فاحْتَشِدوا له. فالتقوا مع المسلمين في سَفْحِ جبلِ الرَّيِّ، فاقتتلوا به، وقد دَبَّرَ الزَّيْنَبِيُّ حِيلَةً مع نُعيمٍ حيث أَدْخلَ المدينةَ خيلًا ليلًا، ولم يَشْعُرْ القومُ بهم، وبَيَّتَهُم نُعيمٌ بَياتًا فشَغَلَهُم عن مَدينتِهم، فاقتتلوا وصَبروا له حتَّى سَمِعوا التَّكبيرَ مِن وَرائِهم، ثمَّ إنَّهم انْهَزموا فقَتَلوا منهم مَقتَلةً عظيمةً، وأفاء الله على المسلمين بالرَّيِّ نحوًا مِن فَيْءِ المدائنِ، وصالَح نُعيمُ بن مُقرِّن الزَّيْنَبِيَّ على أهلِ الرَّيِّ ومَرْزَبَهُ عليهم نُعيمٌ، فلم يَزَلْ شرفُ الرَّيِّ في أهلِ الزَّيْنَبِيِّ الأكبرِ، ومنهم شَهْرام وفَرُّخان، وسقط آل بَهْرام، وأخرب نُعيمٌ مَدينَتَهُم، وهي التي يُقال لها: العَتيقَةُ -يعني مدينة الرَّيِّ- وأَمَر الزَّيْنَبِيُّ فبَنَى مدينةَ الرَّيِّ الحديثةَ, وكتَب نُعيمٌ إلى عُمَر بالفَتحِ، وأرسَل له الأخماسَ."},{"id":205,"title":"فَتحُ جُرْجان\nبقِيادةِ سُويدِ بن مُقَرِّنٍ .","date":["العام الهجري :18","العام الميلادي :639"],"text":"سار سُويدُ بن مُقرِّن إلى جُرجان فعَسْكَر بها ببِسْطام، وكتَب إلى مَلِكِ جُرجان، وهو زُرْنان صُول، وكاتَبهُ زُرنان صُول وصالحَه على جُرجان على الجِزيَةِ، وكِفايَة حَربِ جُرجان، وأن يُعينَه سُويدٌ إن غَلَبَ، فأجابَهُ سُويدٌ إلى ذلك، وتَلَقَّاهُ زُرنان صُول قبلَ دُخولِه جُرجان فدخَل معه وعَسْكَر بها حتَّى جَبَى الخَراجَ وسَمَّى فُروجَها، فسدها بترك دِهِسْتان، ورفَع الجِزيَةَ عمَّن قام بِمَنْعِها، وأخَذ الخَراجَ مِن سائر أَهلِها، وكتَب بينهم وبينه كِتابًا."},{"id":206,"title":"عُمَر بن الخطَّاب يُوَلِّي مُعاويةَ بن أبي سُفيانَ على الشَّام خَلَفًا لأبي عُبيدةَ رضي الله عنهم .","date":["العام الهجري :18","العام الميلادي :639"],"text":"بعدَ أن تُوفِّيَ أبو عُبيدةَ بن الجَرَّاح بطاعون عَمْواس، وكان أبو عُبيدةَ القائِدَ العامَّ على جُيوشِ الشَّامِ بعدَ عَزْلِ خالدٍ، فلمَّا تُوفِّيَ عَيَّنَ عُمَرُ بن الخطَّاب بَدَلًا عنه مُعاويةَ بن أبي سُفيانَ الذي أصبحَ أميرًا على بِلادِ الشَّامِ بَقِيَّةَ خِلافَةِ عُمَر، ومُدَّةَ خِلافةِ عُثمانَ."},{"id":207,"title":"مَوقِعةُ عَيْنِ شَمْسٍ بِمِصْرَ وهَزيمةُ الرُّومِ الصَّلِيبيِّين بقِيادةِ عَمرِو بن العاصِ .","date":["العام الهجري :19","العام الميلادي :639"],"text":"حاصَر المسلمون عَيْنَ شَمْسٍ وارْتَقى الزُّبيرُ بن العَوَّام السُّورَ، فلمَّا أَحَسَّ أهلُها بذلك انْطَلَقوا بِاتِّجاهِ البابِ الآخَرِ الذي عليه عَمرُو بن العاصِ؛ ولكنَّ الزُّبيرَ كان قد اخْترقَ البابَ عَنْوَةً ووصَل إلى البابِ الذي عليه عَمرٌو؛ ولكنَّ أهلَ عَيْنِ شَمْسٍ كانوا قد سَبَقوه وصالحوا عَمرًا, وكتَب لهم عَمرٌو كِتابَ أَمانٍ: بسم الله الرحمن الرحيم، هذا ما أعطى عَمرُو بن العاصِ أهلَ مِصْرَ مِن الأمانِ على أَنفُسِهم، ومِلَّتِهِم، وأَموالِهِم، وكَنائِسِهم، وصُلُبِهِم، وبَرِّهِم، وبَحْرِهِم، لا يُدْخَلُ عليهم شيءٌ مِن ذلك، ولا يُنْتَقَصُ، ولا يُساكِنُهم النُّوبَةُ، وعلى أهلِ مِصْرَ أن يُعطوا الجِزيَةَ إذا اجتمعوا على هذا الصُّلْحِ، وانتهت زِيادَةُ نَهْرِهِم فعليهم خمسين ألف ألف، فإن أَبَى أحدٌ منهم أن يُجِيبَ رُفِعَ عنهم مِن الجَزاءِ بِقَدْرِهِم، وذِمَّتُنا ممَّن أَبَى بَريئَةٌ، وإن نَقَصَ نَهْرُهُم مِن غايَتِهِ رُفِعَ عنهم بِقَدْرِ ذلك، ومَن دخَل في صُلْحِهم مِن الرُّومِ والنُّوبَةِ فله مِثلُ ما لهم، وعليه مِثلُ ما عليهم، ومن أَبَى واخْتار الذِّهابَ فهو آمِن حتَّى يَبلُغَ مَأْمَنَهُ، أو يَخرُجَ مِن سُلْطانِنا، على ما في هذا الكِتابِ عَهْدُ الله، وذِمَّةُ رَسولِه، وذِمَّةُ الخَليفةِ أميرِ المؤمنين، وذِمَمُ المؤمنين، وعلى النُّوبَةِ الذين استجابوا أن يُعينوا بكذا وكذا رَأسًا، وكذا وكذا فَرَسًا، على أن لا يُغْزَوْا ولا يُمْنَعُوا مِن تِجارةٍ صادِرَةٍ ولا وارِدَةٍ."},{"id":208,"title":"تَوَغُّلُ جُيوشِ المسلمين في بِلادِ فارِسَ .","date":["العام الهجري :19","العام الميلادي :639"],"text":"بعدَ أن فُتِحَت نَهاوَنْد أَمَرَ عُمَرُ بن الخطَّاب بالانْسِياح في فارِسَ كُلِّها، وأُعْطِيَت الأوامرُ لِسبعَةِ أُمَراء بالتَّوَغُّلِ في أَعماقِ فارِسَ، فسار النُّعمانُ بن مُقَرِّن إلى هَمْدان ففَتَحها، ثمَّ إلى الرَّيِّ \"طِهْران اليوم\" ففَتَحها ثمَّ قُوس فأخَذَها سِلْمًا أخوهُ سُويدٌ، ثمَّ جاءَ هو إلى جُرجان وطَبَرِستان وصالَحوه، ثمَّ بعضِ بِلادِ أَذْرَبِيجان، وأمَّا سُراقةُ بن عَمرٍو فذهَب إلى بابِ الأبوابِ على سَواحلِ بحرِ الخَزَرِ، وسار الأَحْنَفُ بن قيسٍ إلى خُراسان ففتح هَراة عَنْوَةً، ثمَّ إلى مَرْو، ثمَّ بَلْخ حتَّى أصبح الأحنفُ سَيِّدَ خُراسان، واتَّجه عُثمانُ بن أبي العاصِ إلى إصْطَخْر وفتَح جَزيرةَ بَرْكاوان وإصْطَخْر وشِيراز، واتَّجه سارِيةُ بن زنيم وقاتَل بعضَ حُشودِ الفُرْس، وفيها الحادِثةُ المشهورة التي قال فيها عُمَرُ مِن المدينةِ: يا سارِيَةَ، الجَبَلَ. أمَّا عاصمُ بن عَمرٍو سار إلى سِجِسْتان ففتَحها ودخَل زَرَنْج فصالَحُوه بعدَ حِصارٍ طويلٍ، وأمَّا سُهَيل بن عَدِيٍّ ففتَح كَرْمان، وانْطلَق الحكيمُ بن عُميرٍ إلى مُكْران وفتَحها، واتَّجه عُتبةُ بن فَرْقَدٍ إلى شَمالِ غَربِ فارِسَ فافْتَتَحَها."},{"id":209,"title":"أوَّلُ مَن دخَل من المسلمين إلى أرضَ الرُّومِ .","date":["العام الهجري :20","العام الميلادي :640"],"text":"أوَّلُ مَن دخَل أرضَ الرُّومِ أبو بَحْرِيَّةَ عبدُ الله بن قيسٍ، وقِيلَ: أوَّلُ مَن دخَلَها مَيْسرَةُ بن مَسروقٍ العَبْسِيُّ، فسَبَى وغَنِمَ."},{"id":210,"title":"وَفاةُ أُمِّ المؤمنين زَينبَ بنتِ جَحْشٍ رضِي الله عنها .","date":["العام الهجري :20","العام الميلادي :640"],"text":"هي أُمُّ المؤمنين زينبُ بنتُ جَحْشِ بن رِيابِ بن يَعْمُر، أُمُّها أُمَيْمةُ بنتُ عبدِ المُطَّلِب عَمَّةُ النَّبيِّ صلَّى الله عليه وسلَّم، مِن المُهاجِرات، كانت تحت زيدِ بن حارِثَةَ، ثمَّ طَلَّقَها فزَوَّجَها اللهُ تعالى نَبِيَّهُ، وفيها نزَلَت الآياتُ: {وَإِذْ تَقُولُ لِلَّذِي أَنْعَمَ اللَّهُ عَلَيْهِ وَأَنْعَمْتَ عَلَيْهِ أَمْسِكْ عَلَيْكَ زَوْجَكَ وَاتَّقِ اللَّهَ وَتُخْفِي فِي نَفْسِكَ مَا اللَّهُ مُبْدِيهِ وَتَخْشَى النَّاسَ وَاللَّهُ أَحَقُّ أَنْ تَخْشَاهُ فَلَمَّا قَضَى زَيْدٌ مِنْهَا وَطَرًا زَوَّجْنَاكَهَا} [الأحزاب: 37]. كانت كَثيرةُ الخيرِ والصَّدقَةِ، كانت صَناعَ اليَدِ، تَعمَلُ بِيَدِها، وتَتَصَدَّقُ به في سَبيلِ الله، ولمَّا دَخلَت على رسولِ الله صلَّى الله عليه وسلَّم كان اسمُها بَرَّة فسَمَّاها زَيْنَب، ومن وَرَعِها مَوقِفُها مِن عائشةَ في حادِثَةِ الإفْكِ، قالت عائشةُ: سألَ رسولُ الله صلَّى الله عليه وسلَّم زينبَ بنتَ جَحْشٍ عن أَمْرِي ما عَلِمْتِ أو ما رَأَيْتِ؟ قالت: يا رسولَ الله أَحْمِي سَمْعِي وبَصَرِي، والله ما عَلِمْتُ إلَّا خيرًا. قالت عائشةُ: وهي التي كانت تُسامِيني مِن أَزواجِ النَّبيِّ صلَّى الله عليه وسلَّم، فعَصَمَها الله بالوَرَعِ. وكانت أوَّلَ نِساءِ رسولِ الله صلَّى الله عليه وسلَّم لُحوقًا به، كما أخْبَر رسولُ الله صلَّى الله عليه وسلَّم، وصلَّى عليها عُمَرُ بن الخطَّاب، ودخَل قَبْرَها أُسامةُ بن زيدٍ، ومحمَّدُ بن عبدِ الله بن جَحْشٍ، وعبدُ الله بن أبي أَحْمَدَ بن جَحْشٍ، ودُفِنَتْ في البَقيعِ رضِي الله عنها وأرضاها."},{"id":211,"title":"هَلاكُ هِرَقْلَ قَيْصَر الرُّومِ .","date":["العام الهجري :20","العام الميلادي :640"],"text":"هو فلافيوس أغسطس هِرقل إمبراطور الإمبراطوريَّة البِيزَنْطيَّة، مِن أُصولٍ أَرْمِينيَّةٍ, بدأَ صُعودَه إلى السُّلطةِ عام 608م، قاد ثَورةً ناجِحَةً ضِدَّ الإمبراطور فورس الذي تَسَلَّم السُّلطةَ بعدَ خَلْعِ الإمبراطور موريس، ودون شَعبِيَّةٍ تُذْكَر في ظِلِّ القَلاقِل التي عانت منها الإمبراطوريَّة. كان والدُ هِرقل -وهو هِرقل الأكبرُ- قائدًا عَسكرِيًّا ناجحًا، شارَك في حُروبِ الإمبراطور موريس، ويُعتبَر هِرقل مُؤَسِّس السُّلالة الهِراقليَّة التي اسْتَمرَّت بحُكم الإمبراطورية البِيزنطيَّة حتَّى عام 711.  انْتَصر هِرقل على الفُرْس في مَعركةِ نينوى 5 هـ، ثمَّ كانت هَزيمةُ جُيوشهِ على يَدِ المسلمين في مَعركةِ اليَرْموك عام 14 هـ، وقد تَنَبَّأَ هِرقل بانْتِصارات المسلمين، كما في صَحيحِ البُخاريِّ قال هِرقلُ لأبي سُفيانَ قبل أن يُسْلِم: فإن كان ما تقولُ حَقًّا فسَيَمْلِكُ مَوضِعَ قَدَمَيَّ هاتين، وقد كنتُ أَعلمُ أنَّهُ خارِجٌ، لم أَكُنْ أَظُنُّ أنَّهُ منكم، فلو أنِّي أَعْلَمُ أنِّي أَخْلُصُ إليه لتَجَشَّمْتُ لِقاءَهُ، ولو كنتُ عنده لغَسَلْتُ عن قَدَمِهِ.  كاد هِرقلُ أن يُسْلِمَ لكنَّ خَوْفَهُ على مُلكِه منَعهُ عن الإسلامِ، كما وَرَدَ خَبَرُهُ في صَحيحِ البُخاريِّ، قال ابنُ النَّاظُورِ:كان هِرقلُ حَزَّاءً يَنظُر في النُّجومِ، فقال لهم حين سألوهُ: إنِّي رَأيتُ اللَّيلةَ حين نَظرتُ في النُّجومِ مَلِكَ الخِتانِ قد ظهَر، فمَن يَخْتَتِنُ مِن هذه الأُمَّةِ؟ قالوا: ليس يَخْتَتِنُ إلَّا اليَهودُ، فلا يُهِمَّنَّكَ شَأْنُهُم، واكْتُبْ إلى مَدايِنِ مُلْكِك، فيَقْتُلوا مَن فيهم مِن اليَهودِ. فبينما هُم على أَمْرِهِم، أُتِيَ هِرقلُ بِرَجُلٍ أرسَل به مَلِكُ غَسَّانَ يُخْبِرُ عن خَبَرِ رسولِ الله صلَّى الله عليه وسلَّم، فلمَّا اسْتَخْبَرَهُ هِرقلُ قال: اذْهَبوا فانْظُروا أَمُخْتَتِنٌ هو أم لا، فنَظَروا إليه، فحَدَّثوهُ أنَّه مُخْتَتِنٌ، وسألَهُ عن العَربِ، فقال: هم يَخْتَتِنون. فقال هِرقلُ: هذا مُلْكُ هذه الأُمَّةِ قد ظَهَرَ. ثمَّ كتَب هِرقلُ إلى صاحِبٍ له بِرُومِيَةَ، وكان نَظيرَهُ في العِلْمِ، وسار هِرقلُ إلى حِمْصَ، فلم يَرِمْ حِمْصَ حتَّى أَتاهُ كِتابٌ مِن صاحِبهِ يُوافِقُ رأيَ هِرقلَ على خُروجِ النَّبيِّ صلَّى الله عليه وسلَّم، وأنَّهُ نَبِيٌّ، فأَذِنَ هِرقلُ لِعُظماءِ الرُّومِ في دَسْكَرَةٍ له بِحِمْصَ، ثمَّ أَمَرَ بأَبوابِها فغُلِّقَتْ، ثمَّ اطَّلَعَ فقال: يا مَعْشَرَ الرُّومِ، هل لكم في الفَلاحِ والرُّشْدِ، وأن يَثْبُتَ مُلْكُكُم، فتُبايِعوا هذا النَّبيَّ؟ فحَاصُوا حَيْصَةَ حُمُرِ الوَحْشِ إلى الأبوابِ، فوَجدوها قد غُلِّقَتْ، فلمَّا رأى هِرقلُ نَفْرَتَهُم، وأَيِسَ مِن الإيمانِ قال: رُدُّوهُم عَلَيَّ. وقال: إنِّي قلتُ مَقالَتي آنِفًا أَختَبِرُ بها شِدَّتَكُم على دِينِكُم، فقد رَأيتُ. فسَجَدوا له ورَضُوا عنه. هلَك هِرقلُ بعدَ أن هَرِمَ وتَخَلَّى عن قِيادَةِ الجُيوشِ."},{"id":212,"title":"القَحْطُ وعامُ الرَّمادَةِ في الحِجازِ .","date":["العام الهجري :20","الشهر القمري : محرم","العام الميلادي :641"],"text":"كما أصاب الشَّامَ طاعونُ عَمْواس فقد أُصِيبَتْ الحِجازُ بقَحْطٍ شديدٍ جِدًّا وجَفافٍ عامٍّ، وسُمِّيَ ذلك اليومُ بعامِ الرَّمادَةِ، حتَّى طلَب عُمَرُ الغَوْثَ مِن مِصْرَ ومِن الشَّامِ، فأرسل له عامِلَاهُ عليها المَؤونَةَ التي خَفَّفَتْ عن النَّاسِ."},{"id":213,"title":"سُقوطُ حِصْنِ بابِ لِيُون على يَدِ عَمرِو بن العاصِ رضِي الله عنه .","date":["العام الهجري :20","الشهر القمري : ذي الحجة","العام الميلادي :641"],"text":"بعدَ انْتِصار المسلمين في مَوقعةِ عَيْنِ شَمْسٍ مَكَّنَ هذا النَّصرُ مُعسكراتِ المسلمين مِن أن تَشْرُفَ على حِصْن بابِ لِيُون مُباشرةً مِن جِهَتِه الشَّماليَّة والشَّرقيَّة، وكانت أَسوارُ هذا الحِصْن تَضُمُّ مِساحةً تَزيدُ عن السِّتِّين فَدَّانًا, ضرَب المسلمون حِصارًا قَوِيًّا على الحِصْن المَنيعِ، غيرَ عابِئِينَ بِمَجانيق الرُّومِ، تَدفَعُهم حَماسَتُهُم، وحُبُّ الجِهادِ ونَيْلُ الشَّهادةِ في مُهاجَمةِ الحِصْن، والقِيامِ بِسِلسلةٍ مِن المُناوَشات التي كانت نَتائِجُها تُضْعِفُ مَعنوِيَّات المُحاصَرين، ولم يَكَدْ يَمْضي على الحِصار شهرٌ حتَّى دَبَّ اليأسُ في نَفْسِ \"المُقَوْقِس\" حاكمِ مِصْرَ، فأرسَل في طَلَبِ المُفاوَضَةِ والصُّلْحِ، فبعَث عَمرُو بن العاصِ وَفْدًا مِن المُفاوِضين على رَأْسِه عُبادةُ بن الصَّامتِ الذي كُلِّفَ بألَّا يَتَجاوَزَ في مُفاوَضَتِه أُمورًا ثلاثة يَختارُ الرُّومُ واحدةً منها، وهي: الدُّخولُ في الإسلامِ، أو قُبولُ دَفْعِ الجِزيَةِ للمسلمين، أو الاحْتِكامُ إلى القِتالِ، فلم يَقْبَلْ الرُّومُ العَرْضَيْن الأوَّلَيْن، وأَصَرُّوا على مُواصَلَةِ القِتالِ، وحاوَلَ المُقَوْقِسُ أن يَعْقِدَ صُلْحًا مع عَمرٍو بعدَ أن تَيَقَّنَ أنَّه لا قِبَلَ له بِمُواجَهَةِ المسلمين، وآثَرَ الصُّلْحَ وحَقْنَ الدِّماءِ، واخْتار أن يَدْفَعَ الجِزيَةَ للمسلمين، وكتَب شُروطَ الصُّلْحِ، وأَرْسلها إلى هِرقلَ إمبراطور الرُّومِ للمُوافقَةِ عليها، وأَسْرعَ إلى الإسكندريَّة مُغادِرًا الحِصْنَ، وأَردَفَ شُروطَ الصُّلْحِ بِرِسالةٍ إلى هِرقلَ يَعْتَذِرُ فيها لِهِرقلَ عمَّا أَقْدَمَ عليه مِن الصُّلْحِ مع المسلمين، فما كان مِن هِرقلَ إلَّا أن أَرسَل إليه وإلى قادةِ الرُّومِ يُعَنِّفُهُم على تَخاذُلِهِم وتَهاوُنِهِم إزاءَ المسلمين، ولم يكُن لهذا مَعْنًى سِوى رفضِ شُروطِ الصُّلْحِ، اسْتأنفَ المسلمون القِتالَ وشَدَّدوا الحِصارَ بعدَ فشلِ الصُّلْحِ، وفي أثناءِ ذلك جاءت الأنباءُ بوَفاةِ هِرقل ففَتَّ ذلك في عَضُدِ الجُنودِ داخِلَ الحِصْنِ، وزادَهُم يأسًا على يأسٍ، في الوقت الذي صَحَّتْ فيه عَزائمُ المسلمين، وقَوِيَتْ مَعنوِيَّاتُهم، وفي غَمْرَةِ الحِصارِ تَطوَّع الزُّبيرُ بن العوَّام بِتَسَلُّقِ سُورِ الحِصْنِ في ظَلامِ اللَّيلِ، وتَمَكَّنَ بِواسطَةِ سُلَّمٍ وُضِعَ له أن يَصعَدَ إلى أعلى السُّورِ، ولم يَشعُرْ الرُّومُ إلَّا بِتَكبيرةِ الزُّبيرِ تَهُزُّ سُكونَ اللَّيلِ، ولم يَلْبَثْ أن تَبِعَهُ المسلمون يتسابقون على الصُّعودِ، تَسبِقُهُم تَكبيراتُهم المُدَوِّيَةُ فتَنخَلِع لها أفئدةُ الرُّوم التي ملأها اليأسُ، فكانت تلك التَّكبيرات أمضى مِن كلِّ سِلاحٍ قابلهم، حتَّى كان قائد الحِصْن يَعرِض الصُّلْحَ على عَمرٍو ومُغادرةَ الحِصْنِ."},{"id":214,"title":"فَتحُ الإسكندريَّة عاصمةِ مِصْرَ بقِيادةِ عَمرِو بن العاصِ .","date":["العام الهجري :21","العام الميلادي :641"],"text":"لمَّا افتَتَح المسلمون بابَ لِيُون ثمَّ افتَتَحوا قُرى الرِّيفِ فيما بينها وبين الإسكندريَّة قريةً فقريةً، حتَّى انتهوا إلى بَلْهِيب -قرية يُقال لها: الرّيش- أرسل صاحبُ الإسكندريَّة الى عَمرِو بن العاصِ: إنَّني كنتُ أُخرِج الجِزيةَ إلى مَن هو أبغضُ إليَّ منكم: فارِسَ والرُّومِ، فإن أحببتَ الجِزيةَ على أن تَرُدَّ ما سَبَيْتُم مِن أرضي فعلتُ. فكتب عَمرٌو إلى عُمَرَ يَستأذِنهُ في ذلك، ورفعوا الحربَ إلى أن يَرِدَ كِتابُ عُمَرَ، فوَرَدَ الجوابُ مِن عُمَرَ: لَعَمْرِي جِزيةٌ قائمةٌ أَحَبُّ إلينا مِن غَنيمةٍ تُقَسَّم ثمَّ كأنَّها لم تكُن، وأمَّا السَّبْيُ فإن أعطاك مَلِكُهُم الجِزيةَ على أن تُخَيِّروا مَن في أيديكم منهم بين الإسلامِ ودِينِ قَومِه، فمَن اختار الإسلامَ فهو مِن المسلمين، ومَن اختار دِينَ قَومِه فضَعْ عليه الجِزيةَ، وأمَّا مَن تَفَرَّق في البُلدانِ فإنَّا لا نَقدِرُ على رَدِّهِم. فعرَض عَمرٌو ذلك على صاحبِ الإسكندريَّة، فأجاب إليه، فجمعوا السَّبْيَ، واجْتمعَت النَّصارى وخَيَّروهُم واحدًا واحدًا، فمَن اختار المسلمين كَبَّروا، ومَن اختار النَّصارى نَخَروا وصار عليه جِزيةٌ، حتَّى فَرَغوا. وكان مِن السَّبْيِ أبو مَريمَ عبدُ الله بن عبدِ الرَّحمن، فاختار الإسلامَ وصار عَرِّيفَ زُبيدٍ."},{"id":215,"title":"وَقعةُ نَهاوَنْد وانتِصارُ المسلمين بقِيادةِ النُّعمانِ بن مُقرِّن المُزَنِيِّ .","date":["العام الهجري :21","العام الميلادي :641"],"text":"تَجمَّعَ الفُرْسُ في نَهاوَنْد بقِيادةِ ذي الحاجِبِ بعدَ أن ذهبَت أكثرُ مُدُنِهِم، وبَقَوْا فترةً على ذلك لعدمِ سَماحِ عُمَرَ رضِي الله عنه بالانسِياحِ في فارِسَ، ولكن لمَّا كَثُرَ نَقضُ العُهودِ بسببِ تَقَوِّيهِم بمَن بَقِيَ في نَهاوَنْد، شاوَر عُمَرُ المسلمين في أَمْرِ الفُرْسِ المجتمعين في نَهاوَنْد، وكان يُهِمُّ أن يَسيرَ بنفسه لمُلاقاتِهِم، فأشار عليه علِيٌّ: أنِ ابْعَثْ إلى أهلِ الكوفةِ فَلْيَسِرْ ثُلثاهُم، وكذلك تَبعثُ إلى أهلِ البَصرةِ. فقال عُمَرُ أشيروا عَلَيَّ مَن اسْتعمِلُ عليهم؟ فقالوا: أنت أفضلُنا رأيًا وأعلمُنا بأَهلِك. فقال: لأَسْتَعْمِلَنَّ عليهم رجلًا يكونُ لأوَّلِ أَسِنَّةٍ يَلقاها. بعَث عُمَرُ بن الخطَّاب رضِي الله عنه السَّائبَ بن الأقْرَعِ، مَولى ثَقيفٍ -وكان رجلًا كاتبًا حاسبًا- فقال: الْحَقْ بهذا الجيشِ فكُنْ فيهم، فإن فتَح الله عليهم فاقْسِمْ على المسلمين فَيْئَهُم، وخُذْ خُمُسَ الله وخُمُسَ رَسولِه، وإن هذا الجيش أُصِيبَ، فلا أَراكَ، واذْهَبْ في سَوادِ الأرضِ، فبَطْنُ الأرضِ خيرٌ مِن ظَهرِها يَومئذٍ. وبعَث عُمَرُ إلى أهلِ الكوفةِ أن يَمُدُّوا جيشَ المسلمين فسار النُّعمانُ بقُرابةِ ثلاثين ألفًا، ومعه حُذيفةُ بن اليَمانِ، والزُّبيرُ بن العَوَّامِ، والمُغيرةُ بن شُعبةَ، والأشعثُ بن قيسٍ، وعَمرُو بن مَعْدِي كَرِبْ، وابنُ عُمَرَ، حتَّى أَتَوْا نَهاوَنْد فالْتَقوا بالفُرْسِ يومَ الأربعاءِ، فَحَثَّ النُّعمانُ النَّاسَ على القِتالِ، فأشار المُغيرةُ بن شُعبةَ أن يَتَعَجَّلَ الفُرْسَ بالقِتالِ، فقال النُّعمانُ: إنِّي شَهِدْتُ رسولَ الله صلَّى الله عليه وسلَّم إذا لم يُقاتِل أوَّلَ النَّهارِ أَخَّرَ القِتالَ حتَّى تَزولَ الشَّمسُ، وتَهُبَّ الرِّياحُ، وتَحْضُرَ الصَّلاةُ، ويَطِيبَ القِتالُ، ويَنزِلَ النَّصْرُ، فما مَنَعَنِي إلَّا ذلك. ثمَّ دَعا: اللَّهمَّ إنِّي أسألُك أن تُقِرَّ عَيْنِي اليومَ بفَتحٍ يكونُ فيه عِزُّ الإسلامِ، وذُلٌّ يُذَلُّ به الكُفَّارُ، ثمَّ اقْبِضْني إليك بعدَ ذلك على الشَّهادةِ، أَمِّنُوا يَرحمُكُم الله. فأَمَّنُوا وهُم يَبكون، ثمَّ قال النُّعمانُ: إنِّي هازُّ اللِّواءَ ثلاثَ مَرَّاتٍ، فالهَزَّةُ الأُولى فَلْيَقْضِ الرَّجلُ حاجتَهُ ولْيَتوضَّأْ، والهَزَّةُ الثَّانيةُ فَلْيَرْمِ الرَّجلُ ثِيابَهُ وسِلاحَهُ، والهَزَّةُ الثَّالثةُ فاحْمِلُوا ولا يَلْوِي أحدٌ على أحدٍ، فإن قُتِلَ النُّعمانُ فلا يَلْوِي عليه أحدٌ، وإنِّي داعِ الله بدَعوَةٍ فعَزمتُ على امرئٍ إلَّا أَمَّنَ عليها، فقال: اللَّهمَّ ارْزُقْ النُّعمانَ شَهادةً بِنَصْرِ المسلمين وفَتْحٍ عليهم. فأَمَّنَ القومُ، فهَزَّ اللِّواءَ ثلاثَ مَرَّاتٍ وحَمَلَ وحَمَلَ النَّاسُ معه, وكان الأعاجمُ قد شَدُّوا أَنفُسَهُم بالسَّلاسِل لِئلَّا يَفِرُّوا، وحَمَلَ عليهم المسلمون فقاتلوهم، فرُمِيَ النُّعمانُ بِنُشَّابَةٍ فقُتِلَ رَحِمَهُ الله، فَلَفَّهُ أخوهُ سُويدُ بن مُقَرِّن في ثَوبِه، وكَتَمَ قَتْلَهُ حتَّى فتح الله عليهم، ثمَّ دفَع الرَّايةَ إلى حُذيفةَ بن اليَمانِ، وقتَل الله ذا الحاجِبِ قائِدَ الفُرْسِ، وافْتُتِحَت نَهاوَنْد، فلم يكُن للأعاجمِ بعدَ ذلك جَماعةٌ. كُتِبَ إلى عُمَرَ بالفَتحِ مع رجلٍ مِن المسلمين، فلمَّا أتاهُ قال له: أَبْشِر يا أميرَ المؤمنين بفتحِ أَعزَّ الله به الإسلامَ وأَهلَهُ، وأَذَلَّ به الكُفْرَ وأَهلَهُ. قال: فحَمِدَ الله عزَّ وجلَّ، ثمَّ قال: النُّعمانُ بَعَثَكَ؟ قال: احْتَسِبْ النُّعمانَ يا أميرَ المؤمنين. قال: فبَكَى عُمَرُ واسْتَرْجَعَ، قال: ومَن وَيْحك! قال: فُلان وفُلان. حتَّى عَدَّ له ناسًا كثيرًا، ثمَّ قال: وآخرين يا أميرَ المؤمنين لا تَعرِفُهم. فقال عُمَرُ وهو يَبكي: لا يَضُرُّهم ألَّا يَعرِفَهم عُمَرُ، ولكنَّ الله يَعرِفُهم."},{"id":216,"title":"وَفاةُ خالدِ بن الوَليد رضِي الله عنه سَيْفِ الله المَسْلولِ .","date":["العام الهجري :21","العام الميلادي :641"],"text":"هو خالدُ بن الوَليد بن المُغيرةِ بن عبدِ الله بن عَمرِو بن مَحْزومٍ القُرشيُّ المَخْزوميُّ، سَيْفُ الله، أبو سُليمانَ، كان أحدَ أَشرافِ قُريشٍ في الجاهِليَّة، وكان إليه أَعِنَّةُ الخَيلِ في الجاهِليَّة، وشَهِدَ مع كُفَّارِ قُريشٍ الحُروبَ إلى عُمرَةِ الحُديبيةِ، كما ثبَت في الصَّحيحِ: أنَّه كان على خَيلِ قُريشٍ طَلِيعَةً، ثمَّ أَسلَم في سَنةِ سبعٍ بعدَ خَيبرَ، وقِيلَ قَبلَها، أَرسَلهُ أبو بكرٍ إلى قِتالِ أهلِ الرِّدَّةِ فأَبْلَى في قِتالِهم بَلاءً عظيمًا، ثمَّ وَلَّاهُ حَربَ فارِسَ والرُّومِ، فأَثَّرَ فيهم تَأثيرًا شديدًا، وفتَح دِمشقَ، واسْتخلَفهُ أبو بكرٍ على الشَّامِ إلى أن عَزَلَهُ عُمَرُ، وقد قال عنه النَّبيُّ صلَّى الله عليه وسلَّم: (نِعْمَ عبدُ الله وأخو العَشيرَةِ خالدُ بن الوَليدِ، سَيْفٌ مِن سُيوفِ الله سَلَّهُ الله على الكُفَّارِ). وقال خالدٌ عند مَوتِه: ما كان في الأرضِ مِن ليلةٍ أَحَبَّ إليَّ مِن ليلةٍ شَديدةِ الجَليدِ في سَرِيَّةٍ مِن المُهاجرين أُصَبِّحُ بهم العَدُوَّ فعَليكُم بالجِهادِ. مات خالدُ بن الوَليد بمدينةِ حِمْصَ وقِيلَ: تُوفِّيَ بالمدينةِ. فلمَّا تُوفِّيَ خرَج عُمَرُ إلى جِنازَتِه فقال: ما على نِساءِ آلِ الوَليدِ أن يَسْفَحْنَ على خالدٍ دُموعَهُنَّ ما لم يكُن نَقْعًا أو لَقْلَقَةً. قال ابنُ حَجَرٍ وهذا يَدُلُّ أنَّه مات في المدينةِ."},{"id":217,"title":"فَتْحُ هَمَذان والرَّيِّ وقُومِس وجُرْجان وأَذْرَبِيجان بقِيادةِ نُعيمِ بن مُقَرِّن .","date":["العام الهجري :22","العام الميلادي :642"],"text":"بعدَ أن فُتِحَت نَهاوَنْد اطْمَأنَّ عُمَرُ بن الخطَّاب رضِي الله عنه للانْسِياحِ داخِلَ فارِسَ كُلِّها، فأَمَرَ بذلك، وكان ممَّن أُمِرَ بذلك نُعيمُ بن مُقرِّن أخو النُّعمانَ، فسار إلى هَمَذان ففتَحها واسْتخلَف عليها يَزيدَ بن قيسٍ، ثمَّ سار هو باتِّجاهِ الرَّيِّ -موقع طِهْران اليوم-  ففتَحها كذلك، ثمَّ بعَث بأخيه سُويدِ بن مُقرِّن إلى قُومِس فأخذها سِلْمًا، وصالَح أهلَها، وجاء إليه أهلُ جُرْجان وطَبَرِستان وصالَحوهُ، وكان نُعيمٌ قد بعَث وهو بِهَمَذان بُكيرَ بن عبدِ الله إلى أَذْرَبِيجان، ثمَّ أَمَدَّهُ بعبدِ الله بن سِماكِ بن خَرَشَةَ ففتَح بعضَ بِلادِ أَذْرَبِيجان، في حين كان عُتبةُ بن فَرْقَد يَفتحُ البِلادَ مِن الجِهَةِ الثَّانيةِ."},{"id":218,"title":"فَتحُ شَمالِ أفريقيا (بَرْقَة بليبيا وطَرابُلُس الغرب) بقِيادةِ عَمرِو بن العاصِ .","date":["العام الهجري :22","العام الميلادي :642"],"text":"سار عَمرُو بن العاصِ رضِي الله عنه إلى بَرْقَة وصالَح أَهلَها، وأَرسَل عُقبةَ بن نافعٍ إلى زَوِيلَة، واتَّجَه إلى بِلادِ النُّوبَةِ، ثمَّ انْطَلق عَمرٌو إلى طَرابُلُس ففتَحها بعدَ حِصارِ شَهْرٍ، ثمَّ فتَح صبراته وشروس، ثمَّ مَنَعهُ عُمَرُ بن الخطَّاب رضِي الله عنه مِن التَّقَدُّمِ غربًا أكثرَ مِن ذلك."},{"id":219,"title":"وَفاةُ أُمِّ المؤمنين سَوْدَةَ بنتِ زَمْعَةَ رضِي الله عنها .","date":["العام الهجري :23","العام الميلادي :643"],"text":"هي أُمُّ المؤمنين سَوْدَةُ بنتُ زَمْعَةَ بن قيسِ بن عبدِ شَمسِ بن عبدِ وُدٍّ، وأُمُّها الشَّموسُ بنتُ قيسِ بن عَمرِو بن زيدِ بن لَبيدٍ، تَزوَّجها السَّكرانُ بن عَمرِو بن عبدِ شَمسِ بن عبدِ وُدٍّ، وأَسلمَت بمكَّةَ قديمًا وبايَعَت، وأَسلَم زَوجُها السَّكرانُ بن عَمرٍو، وخرَجا جميعًا مُهاجِرين إلى أرضِ الحَبشةِ في الهِجرَةِ الثَّانيةِ، قَدِمَ السَّكرانُ بن عَمرٍو مكَّةَ مِن أرضِ الحَبشةِ ومعه امْرأتُه سَودَةُ بنتُ زَمْعةَ فتُوفِّيَ عنها بمكَّةَ، فلمَّا حَلَّتْ أَرسَل إليها رَسولُ الله صلَّى الله عليه وسلَّم فخَطَبَها فقالت: أَمْرِي إليك يا رسولَ الله. فقال رَسولُ الله: (مُرِي رجلًا مِن قَومِك يُزَوِّجُكِ). فأَمَرَت حاطِبَ بن عَمرِو بن عبدِ شَمسِ بن عبدِ وُدٍّ فزَوَّجَها، فكانت أوَّلَ امْرأةٍ تَزوَّجها رسولُ الله صلَّى الله عليه وسلَّم بعدَ خَديجةَ، وهاجرت إلى المدينةِ، وهي التي وَهَبَت يَومَها إلى عائشةَ بعدَ أن أَسَنَّتْ وكَبِرَتْ، وتُوفِّيَتْ في آخرِ خِلافةِ عُمَرَ بن الخطَّاب رضِي الله عنهُما جميعًا."},{"id":220,"title":"اسْتِشهادُ عُمَرَ بن الخطَّاب رضِي الله عنه .","date":["العام الهجري :23","الشهر القمري : ذي الحجة","العام الميلادي :644"],"text":"أثار فَتحُ بلادِ فارِسَ وتطهيُرها من عبادةِ غيرِ اللهِ عزَّ وجلَّ حِقْدًا مجوسيًّا؛ فحَرَّكوا أصابَعهم، واستطاعوا بقَدَرٍ مِن اللهِ عزَّ وجلَّ أن يَصِلوا إلى خليفةِ المسلمينَ عُمَرَ بنِ الخطَّابِ رضي الله عنه وقتله، بتحريكِ ذلك العِلْجِ المجوسيِّ؛ ليَقضِيَ اللهُ أمرًا كان مفعولًا، فكان قاتله أشقى الخَلقِ بما أقدَمَ عليه، وكان قَتْلُه لعُمَرَ مؤامرةً منه مع غيرِه من المجوسِ الذين جيءَ بهم أَسرى إلى المدينة، وكان هذا المجوسي واسمُه فَيْروز أبو لُؤْلُؤَةَ المَجوسيُّ غُلامًا للمُغيرةِ، بَقِيَ فيها لِعِلْمِهِ بِكثيرٍ مِن الصِّناعاتِ النَّافعةِ للمسلمين، ولكنَّه كان صاحِبَ حِقْدٍ شَديدٍ على عُمَرَ، فهو مَجوسيٌّ خَبيثٌ ظَلَّ يَتَحَيَّنُ الفُرْصَةَ للقضاءِ على عُمَرَ، فجَهَّزَ سِكِّينًا ذا حَدَّيْنِ وطَلَاهُ بالسُّمِّ، وانْتظَر عُمَرَ بن الخطَّاب في صَلاةِ الفَجْرِ، فلمَّا دخَل عُمَرُ في الصَّلاة وكَبَّرَ طَعَنَهُ أبو لُؤلؤةَ سِتَّ طَعَناتٍ في خاصِرَتِه وهرَب بين الصُّفوفِ يَطْعُنُ المُصَلِّين أَمامَهُ حتَّى قام عبدُ الرَّحمنِ بن عَوفٍ فأَلقى عليه بُرْنُسَهُ فلمَّا أَيْقَنَ الخَبيثُ أنَّه مَقبوضٌ طَعَنَ نَفْسَهُ بسِكِّينِه ومات, ومات مِن طَعَناتِه تلك ثلاثةَ عشرَ رجلًا، وأمَّا عُمَرُ فقَدَّمَ عبدَ الرَّحمن بن عَوفٍ للصَّلاةِ بالنَّاسِ، ثمَّ نظروا أَمْرَ عُمَرَ الذي احْتُمِلَ إلى بَيتِه، وجِيءَ له بالطَّبيبِ فسَقاهُ نَبيذًا فخرَج النَّبيذُ مُشْكَلًا، قال: فاسْقُوهُ لَبَنًا. قال: فخرَج اللَّبَنُ مَحْضًا، فقِيلَ له: يا أميرَ المؤمنين، اعْهَدْ. طلَب عُمَرُ مِن ابنِه عبدِ الله أن يَنظُرَ مَن قَتلَهُ؟ فقال له: قتَلَك أبو لُؤلؤةَ غُلامُ المُغيرةِ بن شُعبةَ. قال: الحمدُ لله الذي لم يَجعلْ مَنِيَّتِي بِيَدِ رجلٍ سجَد لله سَجدةً واحِدةً. ثمَّ قال لعبدِ الله، اذْهَبْ إلى عائشةَ فَسَلْها أن تَأذنَ لي أن أُدْفَنَ مع النَّبيِّ صلَّى الله عليه وسلَّم وأبي بكرٍ. بَقِيَ عُمَرُ بعدَها ثلاثةَ أيَّامٍ ثمَّ تُوفِّيَ رضِي الله عنه وأَرضاهُ، وصلَّى عليه صُهيبٌ، ثمَّ دُفِنَ بجانبِ أبي بكرٍ في حُجرَةِ عائشةَ، فكان مع صاحِبَيْهِ كما كان معهُما في الدُّنيا، وهو أحدُ العشرةِ المُبَشَّرين بالجنَّة، وكان قد بَقِيَ خَليفةً عشرَ سنواتٍ وخمسةَ أَشهُرٍ وواحدًا وعشرين يومًا، كانت حافِلةً بالفُتوحاتِ الإسلاميَّة، وبالعَدْلِ المشهورِ، فجَزاهُ الله عن الإسلامِ والمسلمين خيرًا."},{"id":221,"title":"خِلافةُ عُثمانَ بن عفَّانَ رضِي الله عنه  .","date":["العام الهجري :23","الشهر القمري : ذي الحجة","العام الميلادي :644"],"text":"لمَّا طُعِنَ عُمَرُ بن الخطَّاب رضِي الله عنه بسِكِّينٍ مَسمومةٍ وأَيْقَن أنَّه مَيِّتٌ طَلبوا منه أن يَسْتَخْلِفَ كما اسْتخلَفهُ أبو بكرٍ رضِي الله عنه؛ لكنَّه أَبَى ذلك، ولكن جعَل سِتَّةً مِن الصَّحابةِ وكُلُّهُم مِن المُبشَّرين بالجنَّة: عُثمانَ بن عفَّانَ، وعَلِيَّ بن أبي طالبٍ، وعبدَ الرَّحمن بن عَوفٍ، والزُّبيرَ بن العَوَّامِ، وسعدَ بن أبي وَقَّاصٍ، وطَلحةَ بن عُبيدِ الله رضِي الله عنهم، وأَوْصاهُم أن يَختاروا رجلًا منهم يَخْلُفُه بعدَ مَوتِه، فلمَّا مات وصُلِّيَ عليه ودُفِنَ اجتمعوا في بيتِ المِسْوَرِ بن مَخْرَمَةَ، جَمَعَهُم المِقْدادُ بن الأسودِ، وحضَر عبدُ الله بن عُمَرَ كذلك، وتَداوَلُوا بينهم حتَّى قال عبدُ الرَّحمنِ بن عَوفٍ: مَن يَخرُج منها بِنفسِه على أن يُوَلِّيَها أَفضلَكُم؟ فلم يُجِبْ أحدٌ، فقال: هو أنا. يعني أنَّه يَنْسَحِب مِن الخِلافةِ، ولكن يكون أَمْرُ تَعيينِ الخَليفةِ له، فعَمِلَ عبدُ الرَّحمن جُهْدَهُ وسألَ النَّاسَ، حتَّى قِيلَ: إنَّه لم يَترُك حتَّى الصِّغارَ سألَهم: مَن يُولِّيها؟ ظَلَّ كذلك ثلاثةَ أيَّامٍ ثمَّ جَمَعَهُم عبدُ الرَّحمن ثمَّ سألَ عَلِيًّا أنَّ يَسِيرَ سِيرَةَ الخَليفَتين قَبلَهُ، فقال: إنَّه يَعملُ بِعِلْمِه وطاقَتِه. وأمَّا عُثمانُ فأجابَ بالإيجابِ فبايَعَهُ عبدُ الرَّحمن، ثمَّ بايَعَهُ النَّاسُ جميعًا حتَّى علِيُّ بن أبي طالبٍ، وكان طَلحةُ غائبًا عن هذا فلمَّا حضَر بايَع هو كذلك، وقد قِيلَ: إنَّ عبدَ الرَّحمن لمَّا سألَ النَّاسَ كانوا يَكادون يُجْمِعون على عُثمانَ. فكانت تلك قِصَّةَ خِلافتِه رضِي الله عنه وأَرضاهُ."},{"id":222,"title":"المسلمون يَغزون أَذْرَبِيجان وأَرْمِينِيَة بقِيادةِ الوَليدِ بن عُقبةَ .","date":["العام الهجري :24","العام الميلادي :644"],"text":"كان الوَليدَ بن عُقبةَ هو أَميرُ الكوفةِ، فقام بِغَزْوِ أَذْرَبِيجان وأَرْمِينِية بجَيشٍ على مُقدِّمتِه سُليمانُ بن رَبيعةَ، وذلك أنَّ أهلَهُما قد مَنَعوا ما صالَحوا عليه حُذيفةَ بن اليَمانِ أيَّامَ عُمَر بن الخطَّاب، فاضْطَرَّهُم الوَليدُ إلى المُصالَحةِ مَرَّةً أُخرى."},{"id":223,"title":"عَزْلُ عَمرِو بن العاصِ رضِي الله عنه عن وِلايَةِ مِصْرَ .","date":["العام الهجري :25","العام الميلادي :645"],"text":"بعدَ أن تَوَلَّى عُثمانُ بن عفَّانَ الخِلافةَ، وكان عَمرَو بن العاصِ هو أَميرُ مِصْرَ مِن قِبَلِ عُمَر بن الخطَّاب، فَعُيِّنَ بدلًا عنه عبدُ الله بن سعدِ بن أبي السَّرْحِ، عَيَّنَهُ على مِصْرَ وخَراجَها، وأَمَرَهُ كذلك بالانْسِياحِ في أفريقيا والتَّوَغُّلِ فيها واسْتِكمالِ الفُتوحِ."},{"id":224,"title":"المسلمون يُكْمِلون فَتْحَ الشَّام بقِيادةِ حَبيبِ بن مَسلَمةَ .","date":["العام الهجري :25","العام الميلادي :645"],"text":"اسْتُكْمِلت الفُتوحات التي كانت قد بدأت أيَّام عُمَر بن الخطَّاب، أَكمَلها عُثمانُ بن عفَّانَ، فقد غَزا حَبيبُ بن مَسلَمةَ بعضَ أراضي سُوريا التي كانت لا تَزالُ بيَدِ الرُّومِ، فدارَت مَعاركُ على الشَّواطئِ وغيرِها مِن المَناطِق."},{"id":225,"title":"الرُّومُ يُعاوِدون احْتِلالَ الإسكندريَّة والمسلمون يَسْتَرِدُّونَها منهم .","date":["العام الهجري :25","الشهر القمري : ربيع الأول","العام الميلادي :646"],"text":"نقَض الرُّومُ العَهْدَ الذي كان بينهم وبين المسلمين بعدَ أن تَوَلَّى عبدُ الله بن أبي السَّرْحِ وِلايةَ مِصْرَ، فكتَب أهلُ الإسكندريَّة إلى قُسطنطين بن هِرقل وهَوَّنُوا عليه فَتْحَ الإسكندريَّة لِقِلَّةِ الحامِيَةِ مِن المسلمين، فأَنْفَذَ قائِدَهُ مانوبل الأرمنيَّ على رأسِ جيشٍ كَثيفٍ فاسْتَولى عليها، فكتَب عُثمانُ إلى عَمرٍو ووَلَّاهُ الإسكندريَّةَ، فسار عَمرٌو إليهم فبَدأَ القِتالُ في نَقْيُوس، وكانت الدَّوْلَةُ للمسلمين، ثمَّ أَوْقَف الحَربَ عَمرٌو ثمَّ سار إلى الإسكندريَّة وهدَم سُورَها ورجَعت مَرَّةً أُخرى تحت يَدِ المسلمين."},{"id":226,"title":"عُثمانُ بن عفَّانَ رضي الله عنه يأمر بتَوْسيعُ المَسجدِ الحرامِ .","date":["العام الهجري :26","العام الميلادي :646"],"text":"أَمَرَ عُثمانُ بن عفَّانَ رضِي الله عنه بِتَجديدِ أَنْصابِ الحَرمِ، وفيها زاد في المَسجدِ الحَرامِ ووَسَّعَهُ، وابْتاع مِن قَومٍ،  وَأَبَى آخَرون فهَدَم عليهم، ووضَع الأثْمانَ في بيتِ المالِ، فصاحوا بعُثمانَ، فأَمَر بهم فحُبِسُوا، وقال: أتدرون ما جَرَّأَكُم عَلَيَّ؟ ما جَرَّأَكُم عَلَيَّ إلَّا حِلْمِي، قد فعَل هذا بكم عُمَرُ فلم تَصيحوا به. فكَلَّمَهُ فيهم أَميرُ مكَّةَ عبدُ الله بن خالدِ بن أَسِيدٍ فأَطْلَقَهُم."},{"id":227,"title":"وَفاةُ كعبِ بن زُهيرِ بن أبي سُلْمَى رضِي الله عنه .","date":["العام الهجري :26","العام الميلادي :646"],"text":"هو كعبُ بن زُهيرِ بن أبي سُلْمَى المُزَنِيُّ، أبو المُضَرَّبِ, الشَّاعرُ ابنُ الشَّاعرِ، وأَبُوهُ أَشْعَرُ منه، كان كعبٌ في الجاهِليَّة شاعرًا مَعروفًا ولمَّا ظهَر الإسلامُ هَجا النَّبيَّ صلَّى الله عليه وسلَّم وشَبَّبَ بنِساءِ المسلمين، فأَهْدَر النَّبيُّ صلَّى الله عليه وسلَّم دَمَهُ، فجاء مُسْتَأْمِنًا إلى النَّبيِّ صلَّى الله عليه وسلَّم، فأَمَّنَهُ وقَبِلَ منه، فأَنشَدهُ لامِيَّتَهُ المشهورة التي مَطلَعُها: بانَتْ سُعادُ فقلبي اليومَ مَتْبولُ، ويُقالُ: إنَّ النَّبيَّ صلَّى الله عليه وسلَّم أَعطاهُ البُردَةَ التي اشتراها بعدَ ذلك مُعاويةُ مِن بعضِ وَلَدِه فصارت للخُلفاءِ بعدَ ذلك يَتَوارَثُونَها."},{"id":228,"title":"عَزْلُ سعدٍ رضِي الله عنه عن الكوفةِ وتَوْلِيَةُ الوَليدِ بن عُقبةَ  .","date":["العام الهجري :26","العام الميلادي :646"],"text":"كان سعدُ بن أبي وقَّاص أميرًا على الكوفةِ بعدَ أن عُزِلَ عنها المُغيرةُ بن شُعبةَ، ثمَّ عَزَلَ عُثمانُ سعدًا عن الكوفةِ، ووَلَّاها الوَليدَ بن عُقبةَ، وكان سببُ عَزْلِ سعدٍ أنَّه اقْتَرَض مِن ابنِ مَسعودٍ مالًا مِن بيتِ المالِ، فلمَّا تَقاضاهُ به ابنُ مَسعودٍ ولم يَتَيَسَّرْ قَضاؤهُ تَقاوَلا، وجَرَتْ بينهما خُصومةٌ شديدةٌ، فغَضِبَ عليهما عُثمانُ فعَزَلَ سعدًا واسْتعمَل الوَليدَ بن عُقبةَ، وكان عاملًا لِعُمَرَ على عَرَبِ الجَزيرةِ، فلمَّا قَدِمَها أَقبلَ عليه أَهلُها فأَقامَ بها خمسَ سنين وليس على دارهِ بابٌ، وكان فيه رِفْقٌ بِرَعِيَّتِهِ."},{"id":229,"title":"سُقوط طَرابُلُس الغرب في أيدي المسلمين بقِيادةِ عبدِ الله بن أبي السَّرْحِ .","date":["العام الهجري :27","العام الميلادي :647"],"text":"أَمَرَ عُثمانُ عبدَ الله بن سعدِ بن أبي السَّرْحِ أن يَغْزُوَ بِلادَ أفريقيا فإذا افتَتَحها الله عليه فله خُمُسُ الخُمُسِ مِن الغَنيمةِ نَفْلًا، فسار إليها في عشرةِ آلافٍ فافتَتَحها سَهْلَها وجَبَلَها، وقتَل جُرْجِيرَ مَلِكَ الرُّومِ وخَلْقًا كثيرًا مِن أهلِها، ثمَّ اجتمَع أهلُ أفريقيا على الإسلامِ، وحَسُنَتْ طاعتُهم. أخَذ عبدُ الله بن سعدِ خُمُسَ الخُمُسِ مِن الغَنيمةِ، ثمَّ بعَث بخُمُسٍ إلى عُثمانَ، وقَسَّمَ الباقي بين الجيشِ، فأصاب الفارِسُ ثلاثةَ آلافِ دِينارٍ، والرَّاجِلُ ألفَ دِينارٍ. ثمَّ ضرَب عبدُ الله بن أبي السَّرْحِ فُسْطاطًا في مَوضِع القَيْروانِ، ووَفَّدَ وَفْدًا مِن جُندِه لِعُثمانَ، فشَكَوْا عبدَ الله فيما أخَذ، فقال لهم: أنا نَفَّلْتُه, وقد أَمرتُ له بذلك، وذاك إليكم الآن، فإن رَضِيتُم فقد جاز، وإنَّ سَخِطْتُم فهو رَدٌّ. قالوا: فإنَّا نَسْخَطُه. قال: فهو رَدٌّ. وكتَب إلى عبدِ الله بِرَدِّ ذلك واسْتِصْلاحِهم، قالوا: فاعْزِلْهُ عَنَّا، فإنَّا لا نُريدُ أن يَتَأَمَّرَ علينا، وقد وقَع ما وقَع. فكتَب إليه أن اسْتَخْلِفْ على أفريقيا رجلًا ممَّن تَرضى ويَرْضَوْنَ، واقْسِمْ الخُمُسَ الذي كُنتَ نَفَّلْتُكَ في سَبيلِ الله، فإنَّهم قد سَخِطوا النَّفْلَ. ففعَل، ورجَع عبدُ الله بن سعدٍ إلى مِصْرَ وقد فتَح أفريقيا."},{"id":230,"title":"غَزْوُ الأَنْدَلُس في عَهْدِ عُثمانَ بن عفَّانَ بقِيادةِ عبدِ الله بن نافع .","date":["العام الهجري :27","العام الميلادي :647"],"text":"لمَّا افْتُتِحَتْ أفريقيا أَمَرَ عُثمانُ عبدَ الله بن نافعٍ وعبدَ الله بن عبدِ القيسِ أن يَسِيرا إلى الأَندلُس، فغَزاها مِن قِبَلِ البَحرِ، وكتَب عُثمانُ إلى مَن انْتَدَبَ معهما: أمَّا بعدُ فإنَّ القُسطنطينيَّة إنَّما تُفْتَحُ مِن قِبَلِ الأَندلُس. فخَرجوا ومعهم البَرْبَرُ، ففتَح الله على المسلمين وزادَ في سُلطانِ المسلمين مِثل أفريقيا."},{"id":231,"title":"المسلمون يركبون البحر ويفتحون قبرص بقِيادةِ عبدِ الله بن قيسٍ .","date":["العام الهجري :28","العام الميلادي :648"],"text":"كان مُعاويةُ بن أبي سُفيانَ قد أَلَحَّ على عُمَرَ بن الخطَّاب أنَّ يَغْزُوَ البحرَ ولكنَّه أَبَى ذلك، ثمَّ في زمنِ عُثمانَ طلَب ذلك فوافَق عُثمانُ بِشرطِ ألَّا يُجبِرَ أحدًا على ركُوبِ البحرِ؛ بل يُخَيِّرُهُم، مَن أراد الغَزْوَ معه فعَل وإلَّا فَلَا، ففعَل ذلك، واسْتَعْمَل على البحرِ عبدَ الله بن قيسٍ الجاسيَّ، ثمَّ غَزَا قبرصَ وصالَح أهلَها على سبعةِ آلافِ دِينارٍ كلَّ سَنةٍ، وقد ساعَد في ذلك الغَزْوِ أهلُ مِصْرَ بإمْرَةِ ابنِ أبي السَّرْحِ، وكان مُعاويةُ على النَّاسِ جميعًا، وكان بين الغُزاةِ عددٌ مِن الصَّحابةِ ومِن بينهم أُمُّ حَرامٍ زَوجةُ عُبادةَ بن الصَّامِتِ التي تُوفِّيَت في قبرص ودُفِنَتْ فيها، وكان النَّبيُّ صلَّى الله عليه وسلَّم قد بَشَّرَها بأنَّها تكون ممَّن يَغزو البحرَ كالمُلُوكِ على الأَسِرَّةِ."},{"id":232,"title":"تَوْسيعُ المسجدِ النَّبويِّ .","date":["العام الهجري :29","العام الميلادي :649"],"text":"كان بِناءُ المسجدِ النَّبويِّ بالمدينةِ باللَّبِنِ والجَريدِ وأَعمِدَةِ الخشبِ، فزاد فيه عُثمانُ زِيادةً كبيرةً فجَعَله بطُولِ مائةٍ وسِتِّين ذِراعًا، وعَرْضِ مائةٍ  وخمسين ذِراعًا، وجعَل بِناءَهُ مِن الحِجارةِ المَنْقوشَةِ التي كُسِرَتْ بِطريقةٍ مُناسِبةٍ للبِناءِ، وجعَل الأَعمِدةَ مِن حِجارةٍ مع الرَّصاصِ لزِيادةِ القُوَّةِ والتَّحَمُّلِ، وسَقْفَهُ بالسَّاجِ، وجعَل له سِتَّةَ أبوابٍ كما فعَل عُمَرُ بن الخطَّاب رضِي الله عنهما."},{"id":233,"title":"افْتِتاحُ طَبَرِستان بقِيادةِ سعيدِ بن العاصِ .","date":["العام الهجري :30","العام الميلادي :650"],"text":"اسْتَعاد سعيدُ بن العاصِ فَتْحَ طَبَرِستان شمال إيران؛ وذلك أنَّهم كانوا صالَحوا سُويدَ بن مُقرِّن بعدَ أن غَزاهُم قَبلَ ذلك في عَهدِ عُمَر بن الخطَّاب على أن لا يَغْزوها على مالٍ بَذَلَهُ له إصْبَهْبَذُها؛ لكنَّهم نَقَضوا الصَّلْحَ، فَرَكِبَ سعيدُ بن العاصِ في جيشٍ فيه الحسنُ والحسينُ، والعَبادِلَةُ الأربعةُ، وحُذيفةُ بن اليَمانِ، في خلقٍ مِن الصَّحابةِ فسار بهم، فمَرَّ على بُلدانٍ شَتَّى يُصالِحونَهُ على أَموالٍ جَزيلةٍ، حتَّى انتهى إلى بلدِ مُعاملةِ جُرْجان، فقاتَلوه حتَّى احتاجوا إلى صلاةِ الخوفِ."},{"id":234,"title":"نَقْضُ أهلِ جُرْجان العَهد  .","date":["العام الهجري :30","العام الميلادي :650"],"text":"غَزا سعيدُ بن العاصِ جُرجان بعدَ أن نَقَضَ أهلُها عَهْدَهُم مع المسلمين الذي عُقِدَ في عَهدِ عُمَر بن الخطَّاب فافْتَتَحها."},{"id":235,"title":"عَقْدُ الصُّلْحِ بين المسلمين ومَلِكِ النُّوبَةِ .","date":["العام الهجري :31","العام الميلادي :651"],"text":"بعدَ أن انتهى عبدُ الله بن أبي السَّرْحِ مِن قِتالِ الرُّومِ في المغربِ مع ابنِ الزُّبيرِ عاد إلى النُّوبةِ التي كانت هَدَّدَتْ مِصْرَ مِن الجَنوبِ فغَزاهُم مِن جديدٍ، بعدَ أن كان غَزاهُم قَبلَه عَمرُو بن العاصِ، فقاتَل أهلَها قِتالًا شديدًا؛ ولكنَّه لم يَتَمَكَّنَ مِن الفَتْحِ فَهَادَنَ أهلَها وعقَد معهم الصُّلْحَ، وكان فيها بعضُ المُبادلاتِ الاقتِصادِيَّة."},{"id":236,"title":"مَقْتلُ (يَزْدَجِرْد) مَلِكِ السَّاسانِيِّين بالفُرْس وهو بِمَخْبَئِه بمدينةِ (مَرْو) .","date":["العام الهجري :31","العام الميلادي :651"],"text":"هو يَزْدَجِرْد بن شَهْرَيار بن برويز المَجوسيُّ الفارِسيُّ آخِرُ الأكاسِرَةِ مُطلقًا، انهزَم مِن جيشِ عُمَر, فاسْتَولى المسلمون على العِراقِ، وانهزَم هو إلى مَرْو، ووَلَّتْ أيَّامُه، ثمَّ ثار عليه أُمراءُ دَولتِه وقتَلوه، وقِيلَ: هرَب بأُبَّهَتِهِ في جماعةٍ يَسيرةٍ إلى مَرْو، فسأل مِن بعضِ أهلِها مالًا فمَنعوهُ وخافوهُ على أَنفُسِهم، فبعثوا إلى التُّرْكِ يَسْتَفِزُّونَهم عليه، فأَتَوْهُ فقَتلوا أصحابَهُ وهرَب هو حتَّى أَتَى مَنزِلَ رجلٍ يَنْقُر الأَرْحِيَةَ -يعني حِجارةَ الرَّحَى- على شَطٍّ، فأَوى إليه ليلًا، فلمَّا نام قَتَلهُ."},{"id":237,"title":"تَمَرُّدُ أهلِ خُراسان ثمَّ إخْضاعُهم  على يَدِ عبدِ الله بن عامرٍ .","date":["العام الهجري :31","العام الميلادي :651"],"text":"انْتَقَض أهلُ خُراسان (وهي مُوزعة الآنَ بين إيران وأفغانستان وروسيا) على عُثمانَ بن عفَّانَ رضِي الله عنه، فأرسَل إليهم عبدَ الله بن عامرٍ عامِلَه على البَصرَةِ، فاشْتَبَك مع أهالي تلك البِلادِ في مَرْو ونَيْسابور وغيرِها ففتَحها مِن جديدٍ، ثمَّ تَوَجَّه الأحنفُ بن قيسٍ -وهو الذي كان على مُقدِّمةِ جيشِ عبدِ الله بن عامرِ تَوَجَّه- إلى طَخارِستان فحاصرَهُم حتَّى صالَحوه، ولكن انْضَمَّ لهم أهلُ مَرْو الرُّوذ وغيرُهم فاشْتَبكوا مَرَّةً أُخرى فهزَمهُم الأحنفُ ففتَح جُوزجان عَنْوَةً، ثمَّ الطَّالقان صُلْحًا وغيرَها مِن البِلادِ."},{"id":238,"title":"انْتِصارُ المسلمين في مَعركةِ ذاتِ الصَّواري بقِيادةِ عبدِ الله بن أبي السَّرْحِ .","date":["العام الهجري :31","العام الميلادي :651"],"text":"لمَّا أصاب المسلمون مِن أهلِ أفريقيا وقتَلوهُم وسَبوهُم، خرَج قُسطنطين بن هِرقل في جمعٍ لم تَجمَعْ الرُّومُ مِثلَه مُذْ كان الإسلامُ، خرَجوا في خمسمائةِ مَركَبٍ عليهم قُسطنطين بن هِرقل، ورَكِبَ المسلمون البحرَ على غيرِ مِيعادٍ مع الرُّومِ وعليهم عبدُ الله بن سعدِ بن أبي السَّرْحِ أميرُ مِصْرَ حتَّى بلغوا ذاتَ الصَّواري، فلَقوا جُموعَ الرُّومِ في جمعٍ لم يَروا جمعًا مِثلَه قَطُّ, فقال عبدُ الله بن أبي السَّرْحِ: أَشِيروا عَلَيَّ، قالوا: نَنظُر اللَّيلةَ، فبات الرُّومُ يَضرِبون بالنَّواقيس، وبات المسلمون يُصلُّون ويَدعون الله، ثمَّ أصبحوا فقال المسلمون للرُّومِ: إن شِئْتُم فالسَّاحِل حتَّى يَموتَ الأعجلُ مِنَّا ومنكم، وإن شِئْتُم فالبَحر. قال: فنَخَروا نَخرَةً واحدةً وقالوا: الماء. ثمَّ أصبحوا وقد أجمعَ قُسطنطين أن يُقاتِلَ في البَحرِ، فقَرَّبوا سُفُنَهُم، وقَرَّب المسلمون فرَبَطوا السُّفُنَ بعضَها إلى بعضٍ، واقتَتَلوا أشدَّ القِتالِ، ووَثَبَ الرِّجالُ على الرِّجالِ يَضرِبون بالسُّيوفِ على السُّفُنِ، ويَتَواجَئون بالخَناجِر حتَّى رجعَت الدِّماءُ إلى السَّاحلِ تَضرِبها الأمواجُ، وطَرحَت الأمواجُ جُثَثَ الرِّجالِ رُكامًا حتَّى صارت كالجبلِ العظيمِ عند السَّاحلِ، وقُتِلَ مِن الفَريقين خَلْقٌ كثيرٌ، ثمَّ نصَر الله المسلمين فقتَلوا منهم مَقتلةً عظيمةً لم يَنْجُ منهم إلَّا الشَّريدُ، وانهزَم قُسطنطين. وأقام عبدُ الله بذاتِ الصَّواري أيَّامًا بعدَ هَزيمةِ القومِ، ثمَّ أقبلَ راجعًا. قِيلَ: عُرِفَت بذاتِ الصَّواري لأنَّ صَواري السُّفُنِ رُبِطَت ببعضِها بعضًا، سُفُن الرُّومِ وسُفُن المسلمين. وقِيلَ: لِكثرَةِ السُّفُنِ التي شاركت في القِتالِ وكانت كلُّها ذاتَ صَواري كبيرةٍ."},{"id":239,"title":"غَزْوُ مُعاويةَ رضِي الله عنه بِلادَ الرُّومِ .","date":["العام الهجري :32","العام الميلادي :652"],"text":"لمَّا جمَع الله لمُعاويةَ بن أبي سُفيانَ الشَّامَ كلَّها فصار أميرَ الشَّامِ كان يَغزو الرُّومَ كلَّ عامٍ في الصَّيْفِ -وتُسَمَّى الصَّائِفَةَ- فيَفتَح الله على يَديهِ البِلادَ ويَغنَم الكثيرَ حتَّى وصَل عَمُّورِيَة -وهي اليوم في أنقرة- وكان معه مِن الصَّحابةِ عُبادةُ بن الصَّامِتِ، وأبو أيُّوبَ الأنصاريُّ، وأبو ذَرٍّ الغِفاريُّ، وشَدَّادُ بن أَوْسٍ، وغيرُهم وقد فتَح الله لهم مِن البِلادِ الكثيرَ, ثمَّ غَزا مُعاويةُ الرُّومَ حتَّى بلَغ المَضِيقَ مَضِيقَ القُسطنطينيَّة ومعه زوجتُه عاتِكةُ، ويُقالُ: فاطمةُ بنتُ قَرَظَةَ بن عبدِ عَمرِو بن نَوفلِ بن عبدِ مَنافٍ."},{"id":240,"title":"فَتْحُ أَفْغانِسْتان بقِيادةِ أَوْسِ بن ثَعلبةَ والأحنفِ بن قيسٍ .","date":["العام الهجري :32","العام الميلادي :652"],"text":"فتَح أَوْسُ بن ثَعلبةَ أَفغانستان، وتابَع الأحنفُ بن قيسٍ فَتْحَها مِن ناحيةِ بَلَخ بالشَّمالِ،  ثمَّ أغار على كابُل عبدُ الرَّحمن بن محمَّدٍ، وتَمَّ فَتْحُ البِلادِ كلِّها، ثمَّ دخَل سُكَّانُ قُنْدُهار وكابُل في الإسلامِ."},{"id":241,"title":"وَفاةُ عبدِ الله بن مَسعودٍ رضِي الله عنه .","date":["العام الهجري :32","العام الميلادي :652"],"text":"هو عبدُ الله بن مَسعودِ بن غافِلِ بن حَبيبٍ، أحدُ المُكثِرين في الرِّوايةِ عن النَّبيِّ صلَّى الله عليه وسلَّم، قَديمُ الإسلامِ، أوَّلُ مَن جَهَر بالقُرآنِ في مكَّةَ بعدَ النَّبيِّ صلَّى الله عليه وسلَّم،كان في خِدمَةِ النَّبيِّ صلَّى الله عليه وسلَّم حتَّى كان يُعرَفُ في الصَّحابةِ بصاحِبِ السَّوادِ والسِّواكِ، وهاجَر الهِجرَتين جميعًا إلى الحَبشةِ وإلى المدينةِ، وصلَّى إلى القِبْلَتين، كان مِن كِبارِ القُرَّاءِ المعروفين مِن الصَّحابةِ، وفيه قال النَّبيُّ صلَّى الله عليه وسلَّم: (مَن أراد أن يَقرأَ القُرآنَ رَطْبًا كما أُنْزِلَ فَلْيَقرأْهُ على قِراءَةِ ابنِ أُمِّ عَبْدٍ). يعني ابنَ مَسعودٍ، أو كما قال النَّبيُّ صلَّى الله عليه وسلَّم، تُوفِّيَ في المدينةِ ودُفِنَ بالبَقيعِ وصلَّى عليه عُثمانُ، وقِيلَ: بل عَمَّارٌ. وقِيلَ: بل الزُّبيرُ. والله أعلم."},{"id":242,"title":"وَفاةُ عبدِ الرَّحمن بن عَوفٍ رضِي الله عنه  .","date":["العام الهجري :32","العام الميلادي :652"],"text":"هو عبدُ الرَّحمنِ بنُ عَوفِ بن عبدِ عَوفِ بن عبدِ بن الحارِثِ بن زُهْرةَ بن كِلابِ بن مُرَّةَ بن كعبِ بن لُؤَيٍّ، أبو محمَّدٍ. القُرشيُّ الزُهريُّ، أحدُ العشرةِ المُبَشَّرين بالجنَّةِ، أَسلَم قبلَ أن يَدخُلَ الرَّسولُ صلَّى الله عليه وسلَّم دارَ الأرقمِ، وكان أحدَ الثَّمانيةِ الذين سَبَقوا إلى الإسلامِ، وأحدَ الخَمسةِ الذين أسلموا على يَدِ أبي بكرٍ، وأحدَ السَّابقين البَدْرِيِّين، وأحدَ السِّتَّةِ أهلِ الشُّورى، هاجَر إلى الحَبشةِ وإلى المدينةِ، وآخَى رسولُ الله صلَّى الله عليه وسلَّم بينه وبين سعدِ بن الرَّبيعِ، شَهِد المَشاهِدَ كلَّها مع النَّبيِّ صلَّى الله عليه وسلَّم، كان كثيرَ الإنفاقِ في سَبيلِ الله عزَّ وجلَّ في عهدِ النَّبيِّ صلَّى الله عليه وسلَّم وبعدَهُ، تُوفِّيَ في المدينةِ وخَلَّفَ مالًا كثيرًا."},{"id":243,"title":"وَفاةُ العبَّاسِ بن عبدِ المُطَّلِب عَمِّ النَّبيِّ صلَّى الله عليه وسلَّم .","date":["العام الهجري :32","الشهر القمري : رجب","العام الميلادي :653"],"text":"هو العبَّاسُ بن عبدِ المُطَّلِب بن هاشمِ بن عبدِ مَنافٍ، أبو الفَضلِ، عَمُّ النَّبيِّ صلَّى الله عليه وسلَّم، ومِن أكابرِ قُريشٍ في الجاهِليَّةِ والإسلامِ، وجَدُّ الخُلفاءِ العبَّاسيِّين رضِي الله عنه. كان مُحسِنًا لِقومِه، سَديدَ الرَّأيِ، واسعَ العَقلِ، مُولَعًا بإعْتاقِ العَبيدِ، كارِهًا للرِّقِّ، اشْتَرى 70 عبدًا وأَعتَقَهم، وكانت له سِقايةُ الحاجِّ، وعِمارةُ المسجدِ الحرامِ -وهي أن لا يَدَعَ أحدًا يَسُبّ أحدًا في المسجدِ ولا يَقولُ فيه هَجْرًا- أَسلَم قبلَ الهِجرَةِ وكتَم إسلامَه، وأقام بمكَّةَ يَكتُب إلى رسولِ الله صلَّى الله عليه وسلَّم أخبارَ المشركين، ثمَّ هاجَر إلى المدينةِ، وشَهِدَ وَقعةَ \"حُنين\" فكان ممَّن ثبَت حين انْهزَم النَّاسُ، وشَهِدَ فَتحَ مكَّةَ، وعَمِيَ في آخرِ عُمُرِهِ، وكان إذا مَرَّ بعُمَرَ في أيَّام خِلافَتِه تَرَجَّلَ عُمَرُ إجلالًا له، وكذلك عُثمانُ، وكانت وَفاتُه في المدينةِ عن عشرةِ أولادٍ ذُكورٍ سِوَى الإناثِ، وله في كُتُبِ الحديثِ 35 حديثًا تَقريبًا، وإليه تُنْسَبُ الدَّولةُ العبَّاسيَّة التي حَكَمت ما يَزيد عن خمسةِ قُرونٍ."},{"id":244,"title":"وَفاةُ أبي ذَرٍّ رضِي الله عنه .","date":["العام الهجري :32","الشهر القمري : ذي الحجة","العام الميلادي :653"],"text":"هو جُنْدُب بن جُنادة أبو ذَرٍّ الغِفاريُّ كان طُوالًا آدمَ، وكان يَتعبَّدُ قبلَ مَبعثِ رسولِ الله. صلَّى الله عليه وسلَّم، وأَسلمَ بمكَّةَ قديمًا، وقال: كنتُ في الإسلامِ رابعًا. ورجَع إلى بلادِ قومِه فأقام بها حتَّى مَضَتْ بدرٌ وأُحُدٌ والخندقُ، ثمَّ قدِم المدينةَ، كان أبو ذَرٍّ شُجاعًا يَنفَرِد وحدَه فيقطعُ الطَّريقَ ويُغِيرُ على الصِّرْمِ كأنَّه السَّبُعُ، ثمَّ إنَّ الله قذَف في قَلبِه الإسلامَ وسمِع  بالنَّبيِّ صلَّى الله عليه وسلَّم بمكَّةَ فأَتاهُ، تُوفِّيَ أبو ذَرٍّ رضِي الله عنه بالرَّبْذَةِ، وكان قد أَوْصى امْرأَتَه وغُلامَه: إذا مِتُّ فاغْسِلاني, وكَفِّناني, ثمَّ احْمِلاني فَضَعاني على قارعةِ الطَّريقِ، فأوَّلُ رَكْب] يَمُرُّون بكم فقولوا: هذا أبو ذَرٍّ. فلمَّا مات فعلوا به كذلك، فطلَع رَكْبٌ, فما عَلِموا به حتَّى كادت رَكائبهم تَطَأُ سَريرَهُ، فإذا ابنُ مَسعودٍ في رَهْطٍ مِن أهلِ الكوفةِ، فقال: ما هذا؟ فقِيلَ: جِنازةُ أبي ذَرٍّ، فاسْتَهَلَّ ابنُ مَسعودٍ يبكي، ثمَّ غَسَّلوهُ وكَفَّنوهُ وصَلُّوا عليه ودَفَنوه، فلمَّا أرادوا أن يَرتَحِلوا قالت لهم ابنتُه: إنَّ أبا ذَرٍّ يقرأُ عليكم السَّلامَ, وأَقْسَمَ ألَّا تَركبوا حتَّى تَأكُلوا. ففعلوا، وحَمَلوهم حتَّى أَقدَموهُم إلى مكَّةَ، ونَعَوْهُ إلى عُثمانَ رضِي الله عنه فضَمَّ ابنتَه إلى عِيالِه."},{"id":245,"title":"اسْتِعادةُ فَتْحِ قُبرص بقِيادةِ جُنادةَ بن أبي أُميَّةَ .","date":["العام الهجري :33","العام الميلادي :653"],"text":"بعدَ أن فُتِحَت قُبرص نقَضَت مُعاهدةَ الصُّلحِ ممَّا اضْطَرَّ المسلمين لِغَزْوِهِم ثانيةً بِحَمْلَةٍ بَحْرِيَّةٍ يَقودُها هذه المَرَّةِ جُنادةُ بن أبي أُميَّةَ الأَزديُّ، الذي قام بِتأدِيبِهم وإدخالِهم في التَّبَعيَّةِ مَرَّةً أُخرى."},{"id":246,"title":"جَمْعُ القُرآنِ الكريمِ في مُصحَفٍ واحدٍ في عهد عُثمانَ بن عفَّانَ رضي الله عنه .","date":["العام الهجري :33","العام الميلادي :653"],"text":"لمَّا كَثُرَت الفُتوحُ وبالتَّالي كَثُرَ الدَّاخِلون الجُدُدُ في الإسلامِ والمُتعَلِّمون لِكتابِ الله مِن غيرِ العَربِ ظَهرَت بعضُ الاختِلافاتِ في القِراءاتِ، ممَّا خَوَّفَ بعضَ الصَّحابةِ على مُستقبَلِ مِثلِ هذه الخِلافاتِ، فما كان مِن حُذيفةَ بن اليَمانِ رضِي الله عنه إلَّا أن تَوجَّهَ إلى عُثمانَ بن عفَّانَ وطلَب منه أن يُدرِكَ النَّاسَ قبلَ أن يَختلِفوا الاختِلافَ الذي تكونُ فيه فِتْنَتُهم واقْتِتالُهم، فأَمَرَ عُثمانُ بن عفَّانَ بِنَسْخِ القُرآنِ الكريمِ على قِراءَةٍ واحدَةٍ على لُغَةِ قُريشٍ ولَهْجَتِها، وقد كَلَّفَ لذلك عددًا مِن الصَّحابةِ وهُم: زيدُ بن ثابتٍ، وعبدُ الله بن الزُّبيرِ، وسعيدُ بن العاصِ، وعبدُ الرَّحمنِ بن الحارِثِ، فبَدَأوا يَنسَخون المُصحَفَ، وجَمَعوهُ بالاسْتِعانةِ بالمُصحَفِ الذي كان أبو بكرٍ قد جَمعَهُ في عَهدِه، وكان يَومَها عندَ حَفصةَ رضِي الله عنها، فاسْتَلَمه عُثمانُ منها، ثمَّ أَمَر عُثمانُ بنَسْخِ عِدَّةِ نُسَخٍ مِن هذا المُصحَفِ الذي وَحَّدَهُ على قِراءَةٍ واحدَةٍ، وأَمَر بكُلِّ نُسخَةٍ في بلدٍ عند أَميرِها، وأَمَر بِسائِرِ المَصاحِف أن تُحْرَقَ ولا يَبقى منها شيءٌ إلَّا التي جَمَعها ووَحَّدَها، وإلى يَومِنا هذا لا يُعرَفُ إلَّا الرَّسْمُ العُثمانيُّ، يعني الرَّسْمَ الذي أَمَر بجَمْعِه عُثمانُ وأَبقاهُ ونَشَرهُ، وغيرُ هذا الرَّسْمِ العُثمانيِّ يُعتبَرُ شاذًّا لا يُقْرَأُ به ولا يُعَدُّ مِن القُرآنِ فجَزاهُ الله خيرًا."},{"id":247,"title":"بداية فِتنَةِ مَقتَلِ عُثمانَ بن عفَّانَ رضِي الله عنه .","date":["العام الهجري :34","الشهر القمري : شوال","العام الميلادي :655"],"text":"أوَّلُ بَدْءِ نُشوءِ جُذورِ الفِتنَةِ هو بخُروجِ عبدِ الله بن سَبَإٍ يَهوديٍّ مِن صَنْعاءَ، أَظهَرَ الإسلامَ ثمَّ رحَل إلى الكوفةِ والبَصرَةِ والشَّامِ يُحاوِلُ أن يُؤثِّرَ في النَّاسِ؛ لكن لم يَلْقَ تَجاوُبًا حتَّى رحَل إلى مِصْرَ وبدَأ يُشَكِّكُ في عَقيدةِ النَّاسِ، ويَزْعُم عَودةَ النَّبيِّ صلَّى الله عليه وسلَّم، وأنَّه أَحَقُّ بالعَودةِ مِن عيسى صلَّى الله عليه وسلَّم، ثمَّ بدَأ بالدَّعوَةِ لعَلِيِّ بن أبي طالبٍ، فزَعَم أنَّ له الوِصايَةَ، ثمَّ بدَأ بالطَّعْنِ في خِلافةِ عُثمانَ، ثمَّ انْضَمَّ إلى القافِلَةِ بعضُ الذين تَكلَّموا في سعيدِ بن العاصِ أميرِ الكوفةِ، فرَحَلوا للجزيرةِ، وكان عبدُ الله بن سَبَإٍ يُراسِل كلَّ مَن استطاع أن يُؤثِّرَ عليه في الأمْصارِ، وكان عُثمانُ قد اسْتَشار أُمَراءَهُ في هؤلاء المُنحَرِفين، فاسْتَقَرَّ رأيُ عُثمانَ على تَرْكِهِم، حتَّى جاء وفدُ مِصْرَ مُعتَمِرًا وفي نِيَّتِهم مُناقشةُ عُثمانَ وخَلْقُ البَلْبَلَةِ في المدينةِ، وقد كان ذلك أوَّلَ حُدوثِ فِتنَةِ قَتْلِ عُثمانَ بالشَّكْلِ الواضحِ."},{"id":248,"title":"اغْتِيالُ عُثمانَ بن عفَّانَ رضِي الله عنه  .","date":["العام الهجري :35","الشهر القمري : ذي الحجة","العام الميلادي :656"],"text":"بعدَ أن جاءَ وَفدٌ مِن مِصْرَ مُظْهِرين العُمرَةَ، وجاؤوا المدينةَ وناقَشوا عُثمانَ في بعضِ الأَمْرِ وأظْهَروا الشَّكْوى والتَّأَفُّفِ منه حتَّى أَقنَعهُم بما يَراهُ حتَّى خرجوا مِن عندِه راجِعين لمِصْرَ، ثمَّ جاءَ وَفدٌ مِن مِصْرَ وتَواعَدوا مع وَفدِ الكوفةِ ووَفدِ البَصرَةِ في المدينةِ؛ ولكنَّ عددًا مِن الصَّحابةِ على رأسهم عَلِيُّ بن أبي طالبٍ قام بمُواجَهَتِهم قبلَ دُخولِ المدينةِ ممَّا أخافَهُم، فأظهروا الرُّجوعَ إلى أَمْصارِهم، ولكن لم يَلبَثْ أهلُ المدينةِ بعدَ عَودةِ عَلِيٍّ ومَن معه إلَّا وهؤلاء في المدينةِ يُكَبِّرون وقد قاموا بمُحاصَرةِ دارِ عُثمانَ، وزَعَموا أنَّ عُثمانَ بعَث كِتابًا بقَتْلِ وَفدِ مِصْرَ، ورجَع الباقون معهم تَضامُنًا، وكان الحِصارُ في بِدايَتِهِ يَسيرًا، يَخرُج عُثمانُ فيُصلِّي بالنَّاسِ، ويَأتِيهِ مَن يَأتِيهِ مِن الصَّحابةِ، ثمَّ اشْتَدَّ الحِصارُ وأراد الصَّحابةُ في المدينةِ قِتالَ هؤلاء المُنحَرِفين؛ ولكنَّ عُثمانَ أَبَى عليهم ذلك، ولم يُرِدْ أن يَحدُثَ شيءٌ بِسَببِه يكونُ فيه سَفْكٌ للدِّماءِ، واشْتَدَّ الحِصارُ حتَّى مَنعوهُ حتَّى الماءَ، ثمَّ وَصلَت الأخبارُ أنَّ إمْداداتٍ جاءت لِنَجْدَةِ الخَليفةِ، فاسْتعجَلَ المُنحرِفون الأَمْرَ فأرادوا الدُّخولَ على عُثمانَ فمَنَعَهم الحسنُ بن عَلِيٍّ وعبدُ الله بن الزُّبيرِ وغيرُه، فتَسَوَّرُوا الدَّارَ ودَخلوهُ عَنْوَةً فقَتلوا عُثمانَ بن عفَّانَ رضِي الله عنه في دارهِ آمِنًا، وقَتلوا معه غُلامَيْن له، وأُصيبَتْ زَوجتُه نائِلةُ، ونُهِبَتْ الدَّارُ، ونَهَبوا كذلك بيتَ المالِ، وكانت مُدَّةُ خِلافَتِه اثنتي عشرةَ سَنةً إلَّا أيَّامًا، فجَزاهُ الله عن المسلمين خيرَ الجزاءِ، وهو أحدُ العشرةِ المُبَشَّرِين بالجنَّةِ، ذو النُّورَيْنِ، سُمِّيَ بذلك لأنَّه تَزوَّج ابنتي النَّبيِّ صلَّى الله عليه وسلَّم رُقَيَّةَ وأُمَّ كُلثومٍ."},{"id":249,"title":"خِلافةُ عَلِيِّ بن أبي طالبٍ رضِي الله عنه .","date":["العام الهجري :35","الشهر القمري : ذي الحجة","العام الميلادي :656"],"text":"لمَّا قُتِلَ عُثمانُ بن عفَّانَ مَظلومًا في دارهِ بَقِيَ الأمرُ في المدينةِ دون خَليفةٍ، وكان يُديرُها الغافِقِيُّ المِصْريُّ وهو مِن رُؤوسِ الفِتنَةِ هو وأصحابُه، وحاوَلوا تَولِيةَ سعدٍ وابنِ عُمَرَ ولكن لم يَتِمْ لهم الأمرُ، فعرَض الصَّحابةُ الأمرَ على عَلِيِّ بن أبي طالبٍ فرفَض في اليومِ الأوَّلِ، ثمَّ جاءَهُ طَلحةُ والزُّبيرُ وبايَعوهُ في اليومِ الثَّاني، ثمَّ بايَعهُ النَّاسُ إلَّا القَليلَ مِن الصَّحابةِ، وبذلك تَسَلَّمَ أُمورَ الخِلافَةِ رضِي الله عنه وأرضاهُ. وقد وَرَدَ أنَّ عَلِيًّا قال: اللَّهمَّ إنِّي أَبْرَأُ إليك مِن دَمِ عُثمانَ، ولقد طاشَ عَقْلِي يومَ قَتْلِ عُثمانَ، وأَنكرتُ نَفْسِي، وجاؤوني للبَيْعَةِ فقلتُ: والله إنِّي لأسْتَحْيِي مِن الله أن أُبايِعَ قومًا قَتلوا رجلًا قال فيه رسولُ الله صلَّى الله عليه وسلَّم: (إنِّي لأَسْتَحْيِي ممَّن تَسْتَحِي منه الملائكةُ). وإنِّي لأسْتَحِي مِن الله أن أُبايِعَ وعُثمانُ قَتيلٌ في الأرضِ لم يُدْفَنْ بعدُ. فانصرفوا، فلمَّا دُفِنَ رجَع النَّاسُ يسألوني البَيْعَةَ فقلتُ: اللَّهمَّ إنِّي أُشْفِقُ ممَّا أُقْدِمُ عليه، ثمَّ جاءت عَزْمَةٌ فبايَعَت."},{"id":250,"title":"مَوقعةُ الزَّابوقةِ قُبَيْلَ وَقعةِ الجَملِ .","date":["العام الهجري :36","العام الميلادي :656"],"text":"لمَّا جاء أصحابُ الجَملِ إلى البَصرَةِ لِتَأليفِ الكَلِمَةِ والتَّوَصُّلِ بذلك إلى إقامةِ الحَدِّ على قَتَلَةِ عُثمانَ وينظروا في جمعِ طَوائفِ المسلمين، وضَمِّ تَشَرُّدِهِم حتَّى لا يَضْطَرِبوا فيَقتَتِلوا، حَرَّضَ مَن كان بها مِن المُتَأَلِّبِين على عُثمانَ النَّاسَ، وقالوا: اخْرُجوا إليهم حتَّى تَروا ما جاءوا إليه. فبعَث عُثمانُ بنُ حَنيفٍ -والي البَصرَةِ مِن قِبَلِ عَلِيِّ بن أبي طالبٍ- حَكيمَ بنَ جَبَلَةَ العَبديَّ -أحدَ قَتَلَةِ عُثمانَ بن عفَّانَ- لِيمنَعَ أصحابَ الجَملِ مِن دُخولِ البَصرَةِ، فلَقِيَهُم في الزَّابوقَةِ –مَوضِع قَريب مِن البَصرَةِ كانت فيه وَقعةُ الجَملِ في دورِها الأوَّلِ- فقام طَلحةُ ثمَّ الزُّبيرُ يَخْطُبانِ في أَنصارِ المُعَسْكَرَيْنِ، فأَيَّدهُما أصحابُ الجَملِ، ورفَضهُما أصحابُ عُثمانَ بن حَنيفٍ، ثمَّ قامت أُمُّ المؤمنين عائشةُ تَخطُب في المُعَسْكَرَيْنِ، فثبَت معها أَصحابُ الجَملِ، وانحازَت إليها فِرقةٌ مِن أَصحابِ عُثمانَ بن حَنيفٍ، وبَقِيَت فِرقةٌ أُخرى مع ابنِ جَبَلَةَ، واخْتَلف الفَريقان وكَثُرَ بينهما اللَّغَطُ، ثمَّ تَراموا بالحِجارَةِ، فقام حَكيمُ بن جَبلةَ بِتَأْجِيجِ الفِتنَةِ والدَّعوةِ إلى القِتالِ، وأخَذ يَسُبُّ أُمَّ المؤمنين عائشةَ، ويَقتُل كُلَّ مَن أَنكَر عليه مِن الرِّجالِ والنِّساءِ، وكان دُعاةُ أصحابِ الجَملِ يَدعون إلى الكَفِّ عن القِتالِ، فلمَّا لم يَسْتَجِبْ حَكيمُ بن جَبلةَ وأنصارُهُ لدَعْوَى الكَفِّ عن القِتالِ كَرَّ عليهم أصحابُ الجَملِ، فقُتِلَ حكيمُ بن جَبلةَ، ثمَّ اصْطَلح أصحابُ الجَملِ مع عُثمانَ بن حَنيفٍ على أن تَكونَ دارُ الإمارَةِ والمسجدُ الجامعُ وبيتُ المالِ في يَدِ ابنِ حَنيفٍ، ويَنزِل أصحابُ الجَملِ في أيِّ مكانٍ يُريدونَهُ مِن البَصرَةِ، وقِيلَ: إنَّ حَكيمَ بن جَبلةَ قُتِلَ بعدَ هذا الصُّلحِ لمَّا أَظهَر المُعارضةَ."},{"id":251,"title":"مَوقعةُ الجَملِ .","date":["العام الهجري :36","الشهر القمري : جمادى الأولى","العام الميلادي :656"],"text":"بعدَ وَقعةِ الزَّابوقةِ بين الزُّبيرِ وطَلحةَ مع مَن أَرسَلهم عُثمانُ بن حَنيفٍ مِن أهلِ البَصرَةِ بقِيادةِ حَكيمِ بن جَبلةَ سار عَلِيٌّ مِن المدينةِ، وبعَث ابنَه الحسنَ، وعمَّارَ بن ياسرٍ إلى الكوفةِ بين يَديهِ يَسْتَنْفِران النَّاسَ، فخرَج مِن الكوفةِ سِتَّة آلافٍ، قَدِموا على عَلِيٍّ بذي قار، فسار في نحوِ عشرةِ آلافٍ، ثمَّ إنَّه وصَل إلى البَصرَةِ، فالتَقى هو وجيشُ طَلحةَ والزُّبيرِ، فاصْطَفَّ الفَريقان وليس لِطَلحةَ ولا لِعَلِيٍّ رأسي الفَريقين قَصْدٌ في القِتالِ؛ بل لِيَتكَلَّموا في اجْتِماعِ الكَلِمَةِ، أرسَل عَلِيٌّ المقدادَ بن الأسودِ والقَعقاعَ بن عُمَر لِيَتكلَّما مع طَلحةَ والزُّبيرِ، واتَّفقوا على عدمِ القِتالِ، فطَلحةُ والزُّبيرُ ومعهما عائشةُ أُمُّ المؤمنين يَرون أنَّه لا يَجوزُ تَرْكُ قَتَلَةِ عُثمانَ، وكان عَلِيٌّ يَرى أنَّه ليس مِن المَصلحةِ تَتَبُّعُ قَتَلَةِ عُثمانَ الآنَ؛ بل حتَّى تَسْتَتِبَّ الأمورُ، فقَتْلُ قَتَلَةِ عُثمانَ مُتَّفَقٌ عليه مِن الطَّرفين، والاخْتِلافُ إنَّما هو في متى يكونُ تَنفيذُهُ، وبعدَ الاتِّفاقِ نام الجَيشان بخيرِ ليلةٍ، وبات قَتَلَةُ عُثمانَ بِشَرِّ ليلةٍ حتَّى قَرَّروا أن يُنْشِبوا القِتالَ بين الفَريقين, فحمَل القَتَلَةُ على عَسكرِ طَلحةَ والزُّبيرِ، فظَنَّ طَلحةُ والزُّبيرُ أنَّ عَلِيًّا حمَل عليهم، فحمَلوا دَفْعًا عن أَنفُسِهم، فظَنَّ عَلِيٌّ أنَّهم حمَلوا عليه، فحمَل دَفْعًا عن نَفْسِه، فوَقَعت الفِتنةُ بغيرِ اخْتِيارِهم، وحاوَل قادةُ الجَيشين وَقْفَ القِتالِ لكن لم يُفْلِحوا، فكان طَلحةُ يقولُ: يا أيُّها النَّاسُ أَنْصِتوا. وهُم لا يُنْصِتون، فقال: أُفٍّ أُفٍّ فَراشُ نارٍ, وذِبَّانُ طَمَعٍ. وعَلِيٌّ يُحاوِل يَمنعُهم ولا يَردُّون عليه, وعائشةُ راكِبةٌ جَمَلَها: لا قاتَلَت، ولا أَمَرَت بالقِتالِ, وقد أَرسَلت كعبَ بن سُورٍ بمُصحفٍ مَنْشُورٍ بيَدِه يُناشِدُ النَّاسَ أن لا يُرِيقوا دِماءَهُم، فأصابُه سَهْمُ غَرْبٍ فقَتَلهُ، فتَرامى أَوْباشُ الطَّائِفَتين بالنَّبْلِ، وشبَّت نارُ الحربِ، وثارت النُّفوسُ، فالْتَحَموا واشْتَدَّ القِتالُ أمامَ الجَملِ الذي عليه عائشةُ رضِي الله عنها حتَّى عُقِرَ الجَملُ، وقُتِلَ طَلحةُ والزُّبيرُ، وحُمِلَتْ عائشةُ بِهَوْدَجِها إلى دارِ عبدِ الله بن خَلَفٍ، ثمَّ سَيَّرَها عَلِيٌّ إلى مكَّةَ في صُحبَةٍ مِن النِّساءِ، ثمَّ وَلَّي على البَصرَةِ عبدَ الله بن عبَّاسٍ بعدَ أيَّامٍ مِن وَقعةِ الجَملِ. وكان سببَها الأصليَّ هو المطالبةُ بقَتلِ قَتَلَةِ عُثمانَ، وإقامةِ الحَدِّ عليهم، ولم يكُن القِتالُ أصلًا في بالِ أحدٍ مِن الفَريقين، ولكن قَدَّرَ الله وما شاء فَعَلَ، ومَعلومٌ أنَّ طَلحةَ والزُّبيرَ وعَلِيًّا ممَّن شهِد لهم النَّبيُّ صلَّى الله عليه وسلَّم بالجنَّةِ، فرضِي الله عنهم جميعًا وأَرضاهُم."},{"id":252,"title":"وَفاةُ طَلحةَ بن عُبيدِ الله رضِي الله عنه .","date":["العام الهجري :36","الشهر القمري : جمادى الأولى","العام الميلادي :656"],"text":"أبو محمَّدٍ طَلحةُ بن عُبيدِ الله بن عُثمانَ بن عَمرِو بن كعبِ بن سعدِ بن تَيْمِ بن مُرَّةَ بن كعبِ بن لُؤَيٍّ، أُمُّهُ: الصَّعْبَةُ بنتُ الحَضرميِّ، أُختُ العَلاءِ، أَسلمَت وأَسلَم طَلحةُ قديمًا، هو أحدُ العشرةِ المُبَشَّرين بالجنَّةِ، مِن السَّابقين الأوَّلين إلى الإسلامِ، دَعاهُ أبو بكرٍ الصِّدِّيقُ إلى الإسلامِ، آخَى رسولُ الله صلَّى الله عليه وسلَّم بين طَلحةَ وبين أبي أيُّوبَ الأنصاريِّ، أَبْلَى يومَ أُحُدٍ بَلاءًا عظيمًا، ووَقَى رسولَ الله صلَّى الله عليه وسلَّم بِنَفْسهِ فاتَّقَى طَلحةُ بيَدِه عن وَجْهِ رسولِ الله صلَّى الله عليه وسلَّم فأصاب خِنْصَره فَشُلَّتْ، فقال النَّبيُّ صلَّى الله عليه وسلَّم: (أَوْجَبَ طَلحةُ). وفيه قال النَّبيُّ صلَّى الله عليه وسلَّم: (هذا ممَّن قَضى نَحْبَهُ). وقال أيضًا: (مَن سَرَّهُ أن يَنظُرَ إلى رجلٍ يَمشي على الأرضِ قد قَضى نَحْبَهُ فَلْيَنظُرْ إلى طَلحةَ). قُتل يوم الجمل فلمَّا وجَدَهُ عَلِيٌّ بعدَ المعركةِ في القَتْلَى أَجْلَسَهُ ومسَح التُّرابَ عن وَجهِه وقال: عَزيزٌ عَلَيَّ أن أراك مُجَدَّلًا تحت نُجومِ السَّماءِ أبا محمَّدٍ. ثمَّ بكى عَلِيٌّ وقال: وَدِدْتُ أنِّي مِتُّ قبلَ هذا بعشرين سَنةً."},{"id":253,"title":"وَفاةُ الزُّبيرِ بن العَوَّام رضِي الله عنه  .","date":["العام الهجري :36","الشهر القمري : جمادى الأولى","العام الميلادي :656"],"text":"هو أبو عبدِ الله الزُّبيرُ بن العَوَّام بن خويلدِ بن أَسَدِ بن عبدِ العُزَّى بن قُصَيِّ بن كِلابٍ، أحدُ العشرةِ المُبَشَّرين بالجنَّةِ، أُمُّهُ صَفيَّةُ بنتُ عبدِ المُطَّلِب عَمَّةُ رسولِ الله صلَّى الله عليه وسلَّم، كان مِن أوائلِ الذين أسلموا، هاجَر الهِجرتين إلى الحَبشةِ وإلى المدينةِ، آخَى النَّبيُّ صلَّى الله عليه وسلَّم بينه وبين سَلمةَ بن سَلامةَ بن وَقْشٍ، قال فيه النَّبيُّ صلَّى الله عليه وسلَّم: (إنَّ لِكُلِّ نَبِيٍّ حَواريًّا، وحَواريَّ الزُّبيرُ بن العَوَّام). أوَّلُ مَن سَلَّ سَيْفًا في سَبيلِ الله عزَّ وجلَّ، شهِد بدرًا مُعْتَجِرًا بعِمامةٍ صَفراءَ فنزَلت الملائكةُ على سِيماهُ، اشْتُهِرَ الزُّبيرُ بِبَسالَتِه في القِتالِ وشِدَّتِهِ وإقْدامِه حتَّى كأنَّه جيشٌ لوحده، ولم يَتَخلَّفْ عن غَزاةٍ غَزاها رسولُ الله صلَّى الله عليه وسلَّم, وقد قُتِلَ رحمه الله وهو ابن سبعٍ وسِتِّين، وقِيلَ: سِتٍّ وسِتِّين."},{"id":254,"title":"مَوقعةُ صِفِّينَ بين عَلِيٍّ ومُعاويةَ رضِي الله عنهما  .","date":["العام الهجري :37","الشهر القمري : صفر","العام الميلادي :657"],"text":"لمَّا تَسلَّم عَلِيُّ بن أبي طالبٍ الخِلافةَ بدَأ بِعَزْلِ بعضِ العُمَّالِ وأبدَلَهم بآخَرين، وكان ممَّن عزَلَهم مُعاويةُ بن أبي سُفيانَ الذي كان على الشَّامِ, كان رأيُ عَلِيٍّ في قَتلةِ عُثمانَ عدمَ الاسْتِعجالِ في القِصاصِ قبلَ أن يَسْتَتِبَّ الأمرُ ويَقْوَى سُلطانُ الخِلافةِ, وكان مُعاويةُ على رأي أهلِ الجَملِ الاسْتِعجال في الاقْتِصاصِ مِن قَتَلَةِ عُثمانَ، قَرَّرَ عَلِيٌّ عَزْلَ مُعاويةَ عن وِلايةِ الشَّام, ووَلَّى بدلًا عنه سَهلَ بن حَنيفٍ، ولمَّا سار الأخيرُ للشَّامِ رَفَضَهُ أهلُها، وأَبَى مُعاويةُ الانْعِزالَ؛ لأنَّه يَرى أنَّ الأمرَ لم يَسْتَتِبَّ تمامًا لِعَلِيٍّ، وخاصَّةً أنَّ قَتَلَةَ عُثمانَ لا يَزالون يَسرَحون في البِلادِ، فقام عَلِيٌّ بالحَزْمِ وهو لا يَرضى اللِّينَ في مِثل ذلك، فحَرَّك جيشًا إليه وهو على رَأسِهِم؛ ولكنَّه تَحوَّلَ إلى البَصرَةِ بعدَ سَماعِه بخُروجِ طَلحةَ والزُّبيرِ وعائشةَ ومَن معهم، فكانت مَوقعةُ الجَملِ، وبعدَ أن انتهى مِن الجَملِ وبَقِيَ في الكوفةِ فَترةً أرسَل خِلالَها جَريرَ بن عبدِ الله لِمُعاويةَ ليُبايِعَ له، ويُبَيِّنَ له حُجَّةَ عَلِيٍّ في أَمْرِ القَتَلَةِ؛ لكنَّ مُعاويةَ لم يُعْطِ جَوابًا، ثمَّ تَتابَعت الرُّسُلُ ولكن دون جَدوى حتَّى سَيَّرَ عَلِيٌّ الجيشَ، وعَلِمَ مُعاويةُ بذلك فسار بجَيشِه وسَبَقَ إلى صِفِّينَ واسْتَمْكَنَ مِن الماءِ، ولمَّا وصَل عَلِيٌّ طلَب أن يكونَ الماءُ حُرًّا للطَّرَفين فأَبَوْا عليه، فاسْتَطاع أهلُ العِراقِ إزاحَتَهُم عن الماءِ فجعَلهُ عَلِيٌّ رضِي الله عنه حُرًّا للجَميعِ، وبَقِيَ الطَّرفان أيَّامًا دون قِتالٍ، ثمَّ وقَع القِتالُ ودخَل شهرُ مُحَرَّم فتَوقَّفَ الفَريقان عن القِتالِ لَعَلَّهُم يتَصالحون، وكانت السُّفَراءُ بينهم ولكن دون جَدوى، فعَلِيٌّ باقٍ على رَأيِه ومُعاويةُ لا يَستَجيبُ بشيءٍ، ثمَّ عادت المُناوَشاتُ واسْتَمرَّتْ لشهرِ صَفَر، ثمَّ اشْتَدَّ القِتالُ ثلاثةَ أيَّامٍ قُتِلَ فيها عمَّارُ بن ياسرٍ الذي قال فيه النَّبيُّ صلَّى الله عليه وسلَّم: (وَيْحَ عمَّارٍ تَقْتُلُهُ الفِئَةُ الباغِيَةُ). ولمَّا بدأت لَوائحُ الهَزيمةِ تَلوحُ على أهلِ الشَّام اقْتَرحوا التَّحْكيمَ، ثمَّ كُتِبَتْ صَحيفةُ التَّحكيمِ وشهِد عليها رِجالٌ مِن الطَّرَفين، ثمَّ رحَل عَلِيٌّ إلى الكوفةِ ومُعاويةُ إلى الشَّامِ، ثمَّ اجْتَمع المحكمان أبو موسى الأشعريُّ مِن طَرَف عَلِيٍّ وعَمرُو بن العاصِ مِن طَرَف مُعاويةَ، ولكنَّ اجْتِماعَهُما لم يُسْفِرْ عن أيِّ اتِّفاقٍ ممَّا جعَل عَلِيًّا يَتَهَيَّأُ للمَسيرِ ثانِيةً للشَّامِ؛ ولكنَّ أمرَ الخَوارِجِ صرَفهُ عن ذلك."},{"id":255,"title":"مَعركةُ النَّهْرَوان وخُروجُ الخَوارجِ ونَشأَةُ فِكْرِهِم .","date":["العام الهجري :37","الشهر القمري : ربيع الأول","العام الميلادي :657"],"text":"بعد أن اتَّفَقَ فَريقُ عَلِيِّ بن أبي طالبٍ وفَريقُ مُعاويةَ على التَّحْكيمِ بعدَ القِتالِ الذي دارَ في صِفِّينَ وعاد كلُّ فَريقٍ إلى مَكانِه الأوَّلِ، فسار علِيُّ بن أبي طالبٍ عائِدًا إلى الكوفَةِ، وفي الطَّريقِ انْحازَت جَماعةٌ ممَّن لم يكونوا راضِينَ عن التَّحكيمِ وكانوا يَرَوْن أنَّ التَّحْكيمَ فقط لِكتابِ الله لا للرِّجالِ، فانصرفوا إلى حَرُوراءَ وبدأوا يَبُثُّون هذه الفِكرةَ، خارِجِينَ عن عَلِيٍّ مُنابِذِينَ له، فأرسَل إليهم عَلِيٌّ الرُّسُلَ يُناقِشونَهُم لَعلَّهُم يَثُوبون للحَقِّ، وكان مِن أولئك الرُّسُلِ ابنُ عبَّاسٍ، وعاد على يَديهِ قُرابةَ الألفي رجلٍ، ثمَّ سار عَلِيٌّ بِنَفسِه إليهم وحاجَجَهُم فرَجَعوا إلى الكوفةِ، ولكنَّهم بَقَوْا يَقولون: لا حُكْمَ إلَّا لله. وعَلِيٌّ يقولُ: كَلِمَةُ حَقِّ أُرِيدَ بها باطلٌ. ثمَّ لمَّا أراد عَلِيٌّ الخُروجَ للشَّامِ بعدَ فَشَلِ التَّحْكيم، بدأ الخَوارجُ يَتَسلَّلون مِن جَيشِه إلى النَّهْرَوان، فبدأوا بالفَسادِ فقَتَلوا عبدَ الله بن خَبَّابِ بن الأَرَتِّ مع نِسْوَةٍ آخَرين، فأرسَل عَلِيٌّ إليهم رسولًا فقَتلوهُ، ممَّا اضْطَرَّ عَلِيًّا للعَودةِ إليهم ومُقاتَلتِهم، فطلَب منهم تَسْليمَ قَتَلَةِ عبدِ الله فأَبَوْا وتَمَرَّدوا وبدأوا القِتالَ، فحارَبهُم عَلِيٌّ فأبادَهُم في النَّهْرَوان إلَّا اليَسيرَ الذين بَقوا بعدَ ذلك في الكوفةِ والبَصرَةِ يَنشُرون أفكارَهُم وهُم مُتَسَتِّرون."},{"id":256,"title":"مُعاويةُ رضِي الله عنه يَسْتَوْلِي على مِصْرَ .","date":["العام الهجري :38","العام الميلادي :658"],"text":"ازداد مُعاويةُ بنُ أبي سفيانَ رَضِيَ اللهُ عنهما بعد التحكيمِ قُوَّةً، واختلف الناسُ بالعِراقِ على عليٍّ رَضِيَ اللهُ عنه، ولم يَعُدْ له همٌّ إلَّا مِصرُ التي كان يخشاها وأهلَها؛ لقُربِهم منه، فأراد أن يَضُمَّها إليه ، فأرسل إلى مَنْ لم يبايعْ عليًّا ولم يأتَمِرْ بأمرِ نُوَّابِه يخبِرُهم بقُدومِ الجيشِ عليهم سريعًا، وكان واليها من قِبَلِ عليٍّ حينَئذٍ محمَّدَ بنَ أبي بكرٍ، وكان يواجِهُ اضطراباتٍ داخليَّةً بسَبَبِ مُعاويةَ بنِ خَديجٍ ومَسلَمةَ بنِ مُخَلَّدٍ ومَن اعتزلوا معهما؛ إذْ كان أمرُهم يزدادُ قُوَّةً يومًا بعد يومٍ، خاصَّةً بعد صِفِّين، فخرج معاويةُ بنُ خَديجٍ ومَن معه مطالِبينَ بدَمِ عُثمانَ رَضِيَ الله عنه، فلمَّا عَلِمَ أميرُ المؤمنينَ عليٌّ رضي الله عنه بذلك رأى أنَّ محمَّدًا لا تمكِنُه المقاوَمةُ، فولَّى على مصرَ الأشْتَرَ النَّخَعيَّ، فتُوُفِّي في الطَّريقِ، وشَقَّ على محمَّدِ بنِ أبي بكرٍ عَزْلُه، فأرسل إليه عليٌّ رَضِيَ الله عنه يُثبِّتُه عليها، ويأمُره بالصَّبرِ، فلمَّا كانت سنةُ ثمانٍ وثلاثينَ من الهِجرةِ أرسل مُعاويةُ عَمْرَو بنَ العاصِ في ستَّةِ آلافٍ، فسار بهم حتى نزل أدنى مِصرَ، فجاءه مَنْ خالفَ عَلِيًّا وطالب بدَمِ عُثمانَ رَضِيَ الله عنه في عَشرةِ آلافٍ، فكتب محمَّدٌ إلى عليٍّ بالخبَرِ واستمدَّه، فأرسل إليه أن يَضُمَّ شِيعتَه إليه، ويأمُرُه بالصَّبرِ ويَعِدُه بإنفاذِ الجيوشِ إليه، فقام محمَّدٌ في النَّاسِ وندَبَهم إلى الخروجِ معه، فقام معه قليلٌ لم يَصمُدوا أمامَ جُيوشِ الشَّامِ وانْهزموا، ودخل عمرُو بنُ العاصِ رَضِيَ اللهُ عنه الفُسطاطَ، وهرب محمَّدٌ وخرج مُعاويةُ بنُ خَديجٍ يَطلُبُه حتى التقى به فقتَلَه."},{"id":257,"title":"وَفاةُ عبدِ الله بن سَبَإٍ رَأْسِ الطَّائفةِ السَّبَئِيَّةِ .","date":["العام الهجري :38","العام الميلادي :658"],"text":"هو عبدُ الله بن وَهْبٍ  الهَمْدانيُّ السَّبَئِيُّ، وقِيلَ: الحِمْيَريُّ. أصلُه مِن يَهودِ صَنْعاءَ, وقِيلَ: مِن يَهودِ الحِيرَةِ، مَعروفٌ بابنِ السَّوداءِ لأنَّ أُمَّهُ حَبَشيَّةٌ، أَظهرَ الإسلامَ في زَمَنِ عُثمانَ بن عفَّانَ, وقِيلَ: إنَّه رُوميٌّ أَظهرَ الإسلامَ هو وجماعتُه السَّبئيَّةُ بغَرَضِ تَقويضِ الدَّولةِ الإسلاميَّة لصالحِ الدَّولةِ البِيزنْطيَّة. وهو يَختلِفُ عن عبدِ الله بن وَهْبٍ الرَّاسبيِّ رأسِ الخَوارجِ الذي خرَج على عَلِيٍّ, رحَل ابنُ سَبَإٍ إلى الحِجازِ ثمَّ البَصرَةِ ثمَّ الكوفةِ ثمَّ الشَّامِ ثمَّ اسْتَقَرَّ في مِصْرَ، كلّ ذلك يَنشُر بِدعَتَهُ، وجهَر بها وتَقَوَّى في مِصْرَ، كان يقولُ بِرَجْعَةِ النَّبيِّ صلَّى الله عليه وسلَّم كرَجْعَةِ عيسى في آخرِ الزَّمانِ، ثمَّ دَعا إلى عَلِيٍّ وأثار الفِتنَةَ على عُثمانَ، ثمَّ غَلا في عَلِيٍّ وأَظهرَ أنَّه الخليفةُ بعدَ النَّبيِّ صلَّى الله عليه وسلَّم بالوِصايَةِ، ثمَّ قال: إنَّ في عَلِيٍّ جُزْءًا لاهوتِيًّا، وأنَّ هذا الجُزءَ يَتَناسَخ في الأئمَّةِ مِن بعدِ عَلِيٍّ، ثمَّ زعَم أنَّ عَلِيًّا أيضًا يَرْجِع، وأَفْشَلَ مع اتْباعِه المفاوضات بين عَلِيٍّ والصَّحابةِ في الجَملِ وصِفِّينَ، وتَسبَّبوا في نُشوبِ الحَربِ بينهم. يُقال: إنَّ عَلِيًّا نَفاهُ إلى المدائنِ. وذلك أنَّ عَلِيَّ بن أبي طالبٍ لمَّا بَلغَهُ أنَّ ابنَ السَّوداءِ يَنْتَقِصُ أبا بكرٍ وعُمَر دَعا به، ودَعا بالسَّيْفِ وهَمَّ بِقَتلِه، فشفَع فيه أُناسٌ، فقال: والله لا يُساكِنُني في بلدٍ أنا فيه، فسَيَّرَهُ إلى المدائنِ، وقِيلَ: حَرَقَهُ بالنَّارِ فيمَن حرَقَهُم, وقِيلَ: إنَّه اخْتَفى ولم يُعْلَمْ بِخاتِمَتِه."},{"id":258,"title":"تَوْجيهُ مُعاويةَ رضي الله عنه بُسْرَ بن أَرْطاةَ إلى الحِجازِ واليَمنِ .","date":["العام الهجري :40","العام الميلادي :660"],"text":"بعَث مُعاويةُ رضي الله عنه إلى الحِجازِ واليَمنِ بُسْرَ بن أبي أَرْطاةَ القُرشيَّ العامريَّ في جُنودٍ ووصَل عامِلُهُ هذا إلى اليَمنِ فتَنَحَّى عنها عامِلُ عَلِيٍّ عُبيدُ الله بن عبَّاسٍ، وبلَغ عَلِيًّا ذلك فجَهَّزَ إلى اليَمنِ جاريةَ بن قُدامةَ السَّعديَّ فهرب بُسْرُ من اليمن، ثمَّ رجَع عُبيدُ الله إلى اليَمنِ."},{"id":259,"title":"اغْتِيالُ الخَليفةِ عَلِيِّ بن أبي طالبٍ رضي الله عنه .","date":["العام الهجري :40","الشهر القمري : رمضان","العام الميلادي :661"],"text":"انْتدَب ثلاثةٌ مِن الخَوارجِ، وهُم: عبدُ الرَّحمنِ بن مُلْجِمٍ المُراديُّ، والبَرْكُ بن عبدِ الله التَّميميُّ، وعَمرُو بن بكرٍ التَّميميُّ، فاجتمعوا بمكَّةَ، فتَعاهَدوا وتَعاقَدوا لَيَقْتُلَنَّ هؤلاء الثَّلاثةُ: عَلِيَّ بن أبي طالبٍ رضِي الله عنه، مُعاويةَ بن أبي سُفيانَ، وعَمرَو بن العاصِ، ويُريحوا العِبادَ منهم، فقال ابنُ مُلْجِمٍ: أنا لِعَلِيٍّ. وقال البَرْكُ: أنا لِمُعاويةَ، وقال الآخرُ: أنا أَكْفِيكُم عَمْرًا، فتَواثَقوا أن لا يَنكُصوا، واتَّعَدوا بينهم أن يَقَعَ ذلك ليلةَ سبعَ عشرةَ مِن رمضانَ، ثمَّ تَوجَّه كلُّ رجلٍ منهم إلى بلدٍ بها صاحِبُه، فقَدِمَ ابنُ مُلْجِمٍ الكوفةَ، وبَقِيَ ابنُ مُلْجِمٍ في اللَّيلةِ التي عزَم فيها على قَتْلِ عَلِيٍّ يُناجي الأشعثَ بن قيسٍ في مَسجدِه حتَّى طلَع الفجرُ، فقال له الأشعثُ: ضَحِكَ الصُّبحُ، فقام وشَبِيبٌ فأخَذا أَسْيافَهُما، ثمَّ جاءا حتَّى جلَسا مُقابِلَ السُّدَّةِ التي يَخرُج منها عَلِيٌّ، فضرَب عَلِيًّا بسَيْفِه المَسمومِ على رَأسِه، فلمَّا قُتِلَ أَخَذوا عبدَ الرَّحمنِ بن مُلْجِمٍ وعَذَّبوهُ فقَتَلوهُ. وكانت مُدَّةُ خِلافةِ عَلِيٍّ خمسَ سنين، فجَزاهُ الله عن المسلمين خيرًا، ورضِي عنه وأَرضاهُ، وهو أحدُ العشرةِ المُبَشَّرين بالجنَّةِ."},{"id":260,"title":"خِلافةُ الحسنِ بن عَلِيٍّ رضِي الله عنهما .","date":["العام الهجري :40","الشهر القمري : رمضان","العام الميلادي :661"],"text":"بعدَ أن قُتِلَ الخليفةُ الرَّاشدُ عَلِيُّ بن أبي طالبٍ رضِي الله عنه وأَرضاهُ اتَّجهَ أهلُ الكوفةِ إلى الحسنِ بنِ عَلِيٍّ فبايَعوهُ بالخِلافةِ، وكان أوَّلَ مَن بايَعهُ قيسُ بن سعدٍ، وبَقِيَ في الخِلافةِ سِتَّةَ أَشهُرٍ، رأى خِلالَها تَخاذُلَ أصحابِه، فرأى ضَرورةَ اتِّفاقِ الأُمَّةِ فآثَر الصُّلْحَ وتَنازَل لِمُعاويةَ بالخِلافةِ، وسُمِّيَ ذلك العامُ بعامِ الجَماعةِ، وكان كما قال عنه النَّبيُّ صلَّى الله عليه وسلَّم: (ابْنِي هذا سَيِّدٌ، وسَيُصْلِح الله به بين فِئَتَيْنِ عَظيمتَين مِن المسلمين). فجَزاهُ الله خيرًا ورضي الله عنه وأَرضاهُ."},{"id":261,"title":"تَنازُل الحسنِ بن عَلِيٍّ بن أبي طالِب رضي الله عنه عن الخِلافَة .","date":["العام الهجري :41","الشهر القمري : ربيع الأول","العام الميلادي :661"],"text":"لمَّا قتل عَلِيُّ بن أبي طالِب رضي الله عنه بايَع أهلُ الكوفَة الحسنَ بن عَلِيٍّ، وأطاعوه وأحبُّوه, فاشْتَرط عليهم: إنَّكم سامِعون مُطيعون، مُسالِمون مَن سالَمْتُ، مُحارِبون مَن حارَبْتُ. فارتاب به أهلُ العِراق وقالوا: ما هذا لكم بصاحب. فما كان عن قَريب حتَّى طعنوه، فازداد لهم بُغْضًا، وازداد منهم ذُعْرًا، فعند ذلك عرَف تَفرُّقَهُم واخْتِلافَهُم عليه, وكان أهلُ العِراق أشاروا على الحسن أن يَسير إلى الشَّام لمُلاقاة مُعاوِيَة فخرج بهم، ولمَّا بلغ مُعاوِيَةَ ذلك خرَج هو أيضًا بجَيشِه وتَقارَب الجَيشان في مَسْكِن بناحِيَة الأنبارِ، لمَّا رأى الحسنُ الجيشان في مَسْكِن بناحِيَة الأنبار هالَهُ أن تكونَ مَقتلةٌ كبيرةٌ تَسيلُ فيها دِماءُ المسلمين فرَغِب في الصُّلْح، استقبل الحسنُ بن عَلِيٍّ مُعاوِيَةَ بن أبى سُفيان بكَتائِبَ أمثالِ الجِبال، قال عَمرُو بن العاص لمَّا رأى ضَخامةَ الجَيشين: إنِّي لأرى كَتائِبَ لا تُوَلِّي حتَّى تَقْتُلَ أقرانَها. فقال مُعاوِيَةُ: أي عَمرُو، إن قتَل هؤلاء هؤلاء، وهؤلاء هؤلاء، مَن لي بأُمور النَّاس؟ مَن لي بضَيْعَتِهم؟ مَن لي بِنِسائِهم؟ عرَض الحسنُ بن عَلِيٍّ على عبدِ الله بن جَعفَر أَمْرَ الصُّلْح، قال له: إنِّي قد رأيتُ رَأْيًا، وإنِّي أُحِبُّ أن تُتابِعَني عليه. قال: قلتُ: ما هو؟ قال: قد رأيتُ أن أَعْمِدَ إلى المدينة فأنزِلُها، وأُخَلِّيَ بين مُعاوِيَة وبين هذا الحديثِ، فقد طالت الفِتنَةُ، وسُفِكَتْ فيها الدِّماءُ، وقُطِّعَتْ فيها الأرحامُ، وقُطِّعَت السُّبُلُ، وعُطِّلَت الثُّغورُ. فقال ابنُ جَعفَر: جزاك الله عن أُمَّةِ محمَّد خيرًا، فأنا معك، وعلى هذا الحديثِ. فقال الحسنُ: ادْعُ لي الحُسينَ. فبعَث إلى حُسين فأتاهُ، فقال: أي أخي، إنِّي قد رأيتُ رَأْيًا، وإنِّي أُحِبُّ أن تُتابِعَني عليه. قال: ما هو؟ فقَصَّ عليه الذي قال لابنِ جَعفَر، قال الحُسينُ: أُعيذُك بالله أن تُكَذِّبَ عَلِيًّا في قَبرِه، وتُصَدِّقَ مُعاوِيَةَ!. فقال الحسنُ: والله ما أردتُ أَمْرًا قَطُّ إلَّا خالَفتَني إلى غَيرِه، والله لقد هَمَمْتُ أن أَقْذِفَكَ في بيتٍ فأُطَيِّنَهُ عليك حتَّى أقضِيَ أمري. فلمَّا رأى الحُسينُ غَضبَه قال: أَمْرُنا لأَمْرِك تَبَعٌ، فافْعَل ما بَدا لك. فقام الحسنُ فقال: يا أيُّها النَّاسُ، إنِّي كنتُ أَكْرَهَ النَّاسَ لأوَّلِ هذا الحديثِ، وأنا أَصْلحتُ آخرَه، لِذي حَقٍّ أَدَّيْتُ إليه حَقَّهُ أَحَقَّ به مِنِّي، أو حَقٌّ جُدْتُ به لصَلاحِ أُمَّةِ محمَّد صلَّى الله عليه وسلَّم، وإنَّ الله قد وَلَّاك يا مُعاوِيَة هذا الحديثَ لِخيرٍ يَعلمُه عندك، أو لِشَرٍّ يَعلمُه فيك، {وَإِنْ أَدْرِي لَعَلَّهُ فِتْنَةٌ لَكُمْ وَمَتَاعٌ إِلَى حِينٍ} [الأنبياء: 111]. وبهذا التَّنازُل تَحَقَّقَ في الحسنِ ما أَخبَر به النَّبِيُّ صلَّى الله عليه وسلَّم بقولِه: (إنَّ ابني هذا سَيِّدٌ، ولَعلَّ الله أن يُصْلِحَ به بين فِئتَين عَظيمَتين مِن المسلمين). ولمَّا تَمَّ الصُّلْحُ بشُروطِه برَز الحسنُ بين الصَّفَّيْنِ وقال: ما أَحببتُ أنَّ لي أَمْرَ أُمَّةِ محمَّد صلَّى الله عليه وسلَّم على أن يُهْراقَ في ذلك مِحْجَمَةُ دَمٍ. وكان يقول: إنِّي قد اخْتَرتُ ما عند الله، وتَركتُ هذا الأمرَ لمُعاوِيَة. وأمَّا طلبُ الحسنِ لأن تكونَ الخِلافَة له مِن بعدِه فليست صحيحة، قال جُبيرُ بن نُفيرٍ: قلتُ للحسنِ بن عَلِيٍّ: إنَّ النَّاس يَزعُمون أنَّك تُريدُ الخِلافَة. فقال: كانت جَماجِم العرب بِيَدِي يُسالِمون مَن سالمتُ، ويُحارِبون مَن حاربتُ، فتَركتُها ابتغاءَ وجهِ الله، ثمَّ أَبْتَزُّها بِأَتْياسِ أهلِ الحِجازِ!. وجاء في نَصِّ الصُّلْح في إحدى الرِّوايات: بل يكونُ الأمرُ مِن بعدِه شُورى بين المسلمين."},{"id":262,"title":"بِدايةُ حُكم الأُمويِّين في دِمشقَ .","date":["العام الهجري :41","الشهر القمري : ربيع الأول","العام الميلادي :661"],"text":"بعدَ أن تَنازَل الحسنُ بن عَلِيٍّ رضي الله عنه لمُعاوِيَة بالخِلافَة أصبح مُعاوِيَةُ هو الخَليفَةَ الشَّرعيَّ للمسلمين، فكان بذلك أوَّل بِدايَة الدَّولة الأُمويَّة التي كانت عاصمتُها دِمشقَ، ومِن المعلوم أنَّ هذه الدَّولة اسْتَمرَّت إحدى وتِسعين سنة."},{"id":263,"title":"بداية خروج الخَوارِج على مُعاوِيَة رضي الله عنه .","date":["العام الهجري :41","الشهر القمري : ربيع الأول","العام الميلادي :661"],"text":"كان أوَّلَ الخارِجين فَروةُ بن نَوفلٍ الأشجعيُّ، وكان ممَّن اعتزَل قِتالَ عَلِيٍّ والحسنِ وانحاز معه خمسُمائة فارسٍ مِن الخَوارِج إلى شَهْرَزُور، قائلًا: والله ما أدري على أيِّ شيءٍ نُقاتِلُ عَلِيًّا! أرى أن أَنصَرِفَ حتَّى تَتَّضِحَ لي بَصيرَتي في قِتالِه أو أُتابِعُه. فلمَّا سَلَّمَ الحسنُ الأمرَ إلى مُعاوِيَة قالوا: قد جاء الآن ما لا شَكَّ فيه، فسيروا إلى مُعاوِيَة فجاهِدوهُ. فأقبلوا وعليهم فَروةُ بن نَوفلٍ حتَّى حَلُّوا بالنُّخَيْلَةِ عند الكوفَة، فأرسل إليهم مُعاوِيَةُ جَمْعًا مِن أهلِ الشَّام فقاتَلوهُم، فانْهزَم أهلُ الشَّام، فقال مُعاوِيَةُ لأهلِ الكوفَة: والله لا أمانَ لكم عندي حتَّى تَكُفُّوهُم. فخرَج أهلُ الكوفَة فقاتَلوهُم. فقالت لهم الخَوارِج: أليس مُعاوِيَةُ عَدُوَّنا وعَدُوَّكُم؟ دَعُونا حتَّى نُقاتِلَه، فإن أَصَبْنا كُنَّا قد كَفَيْناكُم عَدُوَّكُم، وإن أَصابَنا كنتم قد كَفَيْتُمونا. فقالوا: لابُدَّ لنا مِن قِتالِكُم. فأخَذ بَنُو أَشْجَعَ صاحِبَهُم فَروةَ فحادَثوهُ ووَعَظوهُ فلم يَرْجِعْ، فأخَذوهُ قَهْرًا وأَدْخَلوهُ الكوفَةَ، فاسْتَعْمَل الخَوارِج عليهم عبدَ الله بن أبي الحَوْساءِ، رجلًا مِن طَيِّء، فقاتَلهُم أهلُ الكوفَة فقتَلوهُم, ثمَّ تَمَكَّنَ منه المُغيرةُ بن شُعبةَ والي العِراق وقتَله، وقُتِلَ عبدُ الله بن أبي الحَوْساء الطَّائيُّ الذي تَوَلَّى أمرَ الخَوارِج بعدَه، ثمَّ قُتِلَ حَوْثَرةُ بن وَداعٍ الأسديُّ الذي نَصَّبَهُ الخَوارِج أميرًا عليهم. ثمَّ خرَج أبو مَريم وهو مَوْلًى لِبَني الحارثِ بن كعبٍ، وقد أَحَبَّ أن يُشْرِكَ النِّساءَ معه في الخُروجِ؛ إذ كانت معه امرأتان: \"قَطام وكُحَيْلَة\" فكان يُقالُ لهم: يا أصحاب كُحَيْلَة وقَطام. تَعْيِيرًا لهم، وقد أراد بهذا أن يَسُنَّ خُروجَهُنَّ، فوَجَّهَ إليه المُغيرةُ جابرَ البَجليَّ فقاتَلهُ حتَّى قتَلهُ وانْهزَم أصحابُه. ثمَّ خرَج رجلُ يُقالُ له: أبو لَيْلى، أَسْودُ طَويلُ الجِسْم، وقبلَ أن يُعْلِنَ خُروجَه دخَل مَسجِدَ الكوفَة وأخَذ بعِضادَتَيِ البابِ، وكان في المسجدِ عِدَّةٌ مِن الأشرافِ، ثمَّ صاح بأعلى صَوتِه: لا حُكمَ إلَّا لله، فلم يَعترِضْ له أحدٌ، ثمَّ خرَج وخرَج معه ثلاثون رجلًا مِن الموالي بسَوادِ الكوفَة، فبعَث له المُغيرةُ مَعقِلَ بن قيسٍ الرِّياحيَّ فقَتلَه سنة 42هـ."},{"id":264,"title":"تَوَغُّلُ عُقبةَ بن نافعٍ في أفريقيا .","date":["العام الهجري :42","العام الميلادي :662"],"text":"تَوَغَّلَ عُقبةُ بن نافعٍ في أفريقيا حتَّى فتَح غَدامِسَ ووَدَّانَ وبِلادَ البَرْبَر."},{"id":265,"title":"أوَّلُ مُحاولاتِ فَتْحِ القُسطنطينيَّة .","date":["العام الهجري :43","العام الميلادي :663"],"text":"كان أوَّلَ مَن بدَأ ذلك بُسْرُ بن أَرْطاةَ الذي أَرسلَهُ مُعاوِيَةُ في الشَّاتِيَةِ فوصَل إلى القُسطنطينيَّة ولكن لم تُفْتَحْ."},{"id":266,"title":"الخوارج يختارون المُسْتَوْرِد بن عُلَّفَةَ التَّيميِّ قائداً لهم .","date":["العام الهجري :43","الشهر القمري : شعبان","العام الميلادي :663"],"text":"بَقِيَتْ بَقِيَّةٌ مِن الخَوارِج الذين خرَجوا على عَلِيِّ بن أبي طالِب يومَ النَّهْروان، وهؤلاء بقوا يَبُثُّون أَفكارَهُم في الكوفَة والبَصْرَة وغيرِها، وكان بَدْءُ تَحَرُّكِهِم للخُروجِ سنة 42هـ، عندما بَدأوا يَتَشاوَرون في ذلك، فقد كانت الخَوارِج يَلْقى بعضُهم بعضًا فيُذاكِرون مَصارِعَ إخوتِهم بالنَّهْرِ، فيَتَرَحَّمون عليهم، ويَحُضُّ بعضُهم بعضًا على الخُروجِ للانتِقام مِن حُكَّامِهِم الجائرين، الذين عَطَّلوا الحُدودَ، واسْتَأْثَروا بالفَيْءِ، فاجتمع رأيُهم على ثلاثةِ نَفَرٍ منهم لِتَوَلِّي قِيادَتِهم: المُسْتَوْرِدُ بن عُلَّفَةَ التَّيميُّ، ومُعاذُ بن جويني الطَّائيُّ، وحَيَّانُ بن ظِبْيانَ السُّلَميُّ الذي كان مَنزِلُه مكانًا لاجْتِماعاتِهم، ولكن كُلّ واحدٍ مِن هؤلاء الثَّلاثةِ دفَع تَوَلِّي الخِلافَة عن نَفسِه، وأخيرًا اتَّفقوا على أن يتَولَّاها المستوردُ هذا، وكانوا أربعُمائة شخصٍ، ونادوه: بأميرِ المؤمنين، وكان المستوردُ ناسِكًا، كثيرَ الصَّلاةِ، وله آدابٌ وحِكَمٌ مَأثورة، وقد قام المغيرةُ بن شُعبةَ بسَجْنِ بعضِهم بعدَ أن عَلِمَ نَواياهُم في الخُروجِ عليه أيضًا. فعَلِمَ المستوردُ بن عُلَّفةَ بأمرِ المُغيرةِ، وأنَّه بدَأ يَطلُبهم فَجَهَّزَ جيشًا, ثمَّ اتَّفقوا على أن يكونَ الخُروج في غُرَّةِ شَعبان, ولمَّا عَلِم بذلك المغيرةُ بن شُعبة أرسَل مُديرَ شُرْطَتِه قَبيصَةَ بن الدَّمُون إلى مكانِ اجتماعِهم وهو مَنزِل حيَّان، فأخَذوهم وجاءوا بهم إلى المغيرةِ فأَوْدَعهم السِّجنَ بعد اسْتِجْوابهم وإنكارِهِم أن يكونَ اجتماعُهم لشيءٍ غير مُدارسَةِ كتابِ الله، فأَفرَج عنهم. وراح المستوردُ يُراوِغ في حربِه للمغيرةِ فيخرُج مِن مكانٍ إلى آخرَ؛ حتَّى يُبَدِّدَ جيشَ المغيرةِ، ثمَّ يَلقاهُم وقد تَعِبُوا، فكان إلى أن كانت المعركةُ النِّهائيَّة حيث تبارَز المستوردُ مع مَعقِل فضرَب كُلُّ واحد منهما صاحِبَه فخَرَّا مَيِّتينِ، وهُزِمَت الخَوارِج وقُتِلوا شَرَّ قِتْلَةٍ فلم ينجُ منهم غيرُ خمسة أو سِتَّة."},{"id":267,"title":"وَفاةُ عَمرِو بن العاصِ رضِي الله عنه حاكِمِ مِصْرَ .","date":["العام الهجري :43","الشهر القمري : شوال","العام الميلادي :664"],"text":"هو عَمرُو بن العاصِ بن وائلِ بن هاشِم بن سُعَيْدِ –بالتصغير- بن سهمِ بن عَمرِو بن هُصَيْص بن كعبِ بن لُؤَيٍّ القُرشيُّ السَّهميُّ، أميرُ مِصْرَ، يُكَنَّى أبا عبدِ الله، وأبا محمَّد، أَسلَم قبلَ الفتحِ في صَفَر سنة ثمانٍ، وقِيلَ: بين الحُديبيَة وخيبر، ولمَّا أَسلَم كان النَّبِيُّ صلَّى الله عليه وسلَّم يُقَرِّبُه ويُدْنِيهِ لِمَعرفتِه وشَجاعتِه. ووَلَّاهُ غَزوةَ ذاتِ السَّلاسِل، وأَمَدَّهُ بأبي بكرٍ وعُمَر وأبي عُبيدةَ بن الجَرَّاح، ثمَّ اسْتَعمَله على عمَّان، فمات صلَّى الله عليه وسلَّم وعَمرٌو هو أميرُها، ثمَّ كان مِن أُمراءِ الأجنادِ في الجِهادِ بالشَّام في زمن عُمَر، وهو الذي افتتَح قِنَّسْرين، وصالَح أهلُ حَلَب ومَنْبِج وأَنْطاكِيَة، ووَلَّاهُ عُمَرُ فِلَسْطين، ووُلِيَّ عَمرٌو إمِرَةَ مِصْرَ في زمن عُمَر بن الخطَّاب، وهو الذي افتَتَحها وأبقاهُ عُثمانُ قليلًا ثمَّ عزَلهُ ووَلَّى عبدَ الله بن أبي سَرْحٍ، ثمَّ لم يَزَلْ عَمرٌو بغيرِ إمْرَةٍ إلى أن كانت الفِتنَة بين عَلِيٍّ ومُعاوِيَة، فلَحِقَ بمُعاوِيَة فكان معه يُدَبِّرُ أمْرَهُ في الحربِ إلى أن جَرى أَمْرُ الحَكَمَيْنِ، ثمَّ سار في جيشٍ جَهَّزَهُ مُعاوِيَةُ إلى مِصْرَ فوَلِيَها لمُعاوِيَة مِن صَفَر سنة ثمانٍ وثلاثين إلى أن مات سنة ثلاثٍ وأربعين على الصَّحيح. تُوفِّي وهو ابنُ تِسعين سنة. وفي صحيحِ مُسلمٍ مِن رِواية عبدِ الرَّحمن بن شِماسَةَ قال: فلمَّا حَضَرَت عَمرَو بن العاصِ الوَفاةُ بَكى، فقال له عبدُ الله بن عَمرٍو ابنُه: ما يُبكيكَ؟ فذَكر الحديثَ بطُولِه في قِصَّةِ إسلامِه، وأنَّه كان شديدَ الحياءِ مِن رسولِ الله صلَّى الله عليه وسلَّم لا يَرفَعُ طَرْفَه إليه. وذكَرها ابنُ عبدِ الحَكَم في فُتوحِ مِصْر، وزاد فيها أشياء مِن رِواية ابنِ لَهِيعَةَ."},{"id":268,"title":"أوَّلُ فُتوحِ المسلمين للهِنْدِ .","date":["العام الهجري :44","العام الميلادي :664"],"text":"تَمَّ الفتحُ على يَدِ المُهَلَّب بن أبي صُفْرَةَ حيث بدَأ بِغَزْوِ مُكْران حتَّى وصَل إلى قَنْدابيل، وكسَر العَدُوَّ وسَلِمَ وغَنِمَ. وبه تَعَرَّف أهلُ البِلادِ على الإسلامِ وشَرائِعِه فدخَل منهم عددٌ كبيرٌ في الإسلامِ."},{"id":269,"title":"وَفاةُ أُمِّ المؤمنين أُمِّ حَبيبةَ بنتِ أبي سُفيان رضي الله عنها .","date":["العام الهجري :44","العام الميلادي :664"],"text":"هي رَمْلَةُ بنتُ أبي سُفيان، أُخْتُ مُعاوِيَة، أُمُّها صَفيَّةُ بنتُ أبي العاصِ بن أُمَيَّة، كانت تحت عُبيدِ الله بن جَحشٍ، خرجت معه مُهاجِرة إلى الحَبشةِ ومات زَوجُها هناك، فخطَبها وهي هناك النَّبِيُّ صلَّى الله عليه وسلَّم، وزَوَّجَهُ إيَّاها النَّجاشيُّ وأَصدَقَ عنه، ثمَّ حُمِلَتْ إليه إلى المدينةِ، تُوفِّيَت في المدينةِ في خِلافَة أخيها مُعاوِيَة."},{"id":270,"title":"فَتحُ سُوسَة وتَدمِيرُ قَلعةِ جَلُولاء البِيزَنطِيَّة شمالَ أفريقيا .","date":["العام الهجري :45","العام الميلادي :665"],"text":"كان مُعاوِيَةُ بن خَديجٍ أميرَ أفريقيا، فوُجِّه عبدُ الله بن الزُّبير ففتَح سُوسَة، وأمَّا عبدُ الملك بن مَرْوان فقد اسْتَولى على جَلُولاء ودَمَّرَ قَلعَتها البِيزَنطيَّة."},{"id":271,"title":"وَفاةُ أُمِّ المؤمنين حَفصةَ بنتِ عُمَر رضِي الله عنها .","date":["العام الهجري :45","الشهر القمري : شعبان","العام الميلادي :665"],"text":"هي حَفصَةُ بنتُ عُمَر بن الخطَّاب، أُمُّها زينبُ بنتُ مَظعونِ بن حَبيبِ بن وَهْبٍ، كانت تحت خُنَيْس بن حُذافَة بن قيسِ بن عَدِيٍّ، هاجَرا سَوِيًّا للمدينةِ، ثمَّ تُوفِّي عنها بعدَ بدرٍ فتَزَوَّجَها النَّبِيُّ صلَّى الله عليه وسلَّم، ثمَّ طَلَّقَها تَطليقَة ثمَّ ارْتَجَعَها، أَمَرَهُ جِبريلُ بذلك وقال: (إنَّ الله يَأمُرك أن تُرْجِعَها إنَّها صَوَّامَة قَوَّامَة، وإنَّها زَوجتُك في الجنَّة). توفِّيت في المدينةِ في خِلافَة مُعاوِيَة عام 45 هـ، ودُفِنَت في البَقيعِ رضي الله عنها وأرضاها."},{"id":272,"title":"الخَطيمُ الباهليُّ وسَهْمُ الهُجَيميُّ يتأثرون بفكر الخوارج .","date":["العام الهجري :46","العام الميلادي :666"],"text":"خرَج الخَطيمُ، وهو يَزيدُ بن مالكٍ الباهليُّ، وسَهْمُ بن غالبٍ الهُجَيميُّ فحَكَما؛ فأمَّا سهمٌ فإنَّه خرَج إلى الأهوازِ فحَكَم بها، ثمَّ رجَع فاخْتَفى وطلَب الأمانَ فلم يُؤَمِّنْهُ زيادٌ وطلَبَهُ حتَّى أخذَهُ وقتَلَهُ وصَلَبَهُ على بابهِ، وأمَّا الخَطيمُ فإنَّ زِيادًا سَيَّرَهُ إلى البَحرَيْن ثمَّ أَقْدَمَهُ، وقال لمُسلمِ بن عَمرٍو الباهليِّ -والدِ قُتيبةَ بن مُسلمٍ-: اضْمَنْهُ. فأَبَى، وقال: إن بات خارِجًا عن بَيتِه أَعْلَمْتُكَ، ثمَّ أتاهُ مُسلمٌ فقال له: لم يَبِتْ الخَطيمُ اللَّيلةَ في بَيتِه، فأمَر به فقُتِلَ وأُلْقِيَ في باهِلَةَ."},{"id":273,"title":"عُقبةُ بن نافعٍ يَفتَح شمالَ أفريقيا  .","date":["العام الهجري :49","العام الميلادي :669"],"text":"عَزَل مُعاوِيَةُ بن أبي سُفيان مُعاوِيَةَ بن خَديجٍ عن أفريقيا، واسْتَعمل عليها عُقبةَ بن نافعٍ الفِهْريَّ، وكان مُقِيمًا بِبَرْقَةَ وزَوِيلَةَ مُذْ فتَحها أيَّام عَمرِو بن العاصِ، وله في تلك البِلادِ جِهادٌ وفُتوحٌ. فلمَّا اسْتَعمله مُعاوِيَةُ سَيَّرَ إليه عشرةَ آلاف فارسٍ، فدخَل أفريقيا وانْضافَ إليه مَن أَسلَم مِن البَرْبَر، فكَثُرَ جَمْعُهُ، ووضَع السَّيفَ في أهلِ البِلادِ لأنَّهم كانوا إذا دخَل إليهم أميرٌ أطاعوا وأَظهَر بعضُهم الإسلامَ، فإذا عاد الأميرُ عنهم نَكَثوا وارْتَدَّ مَن أَسلَم، ثمَّ رأى أن يَتَّخِذَ مدينةً يكون بها عَسكرُ المسلمين وأَهلُهُم وأَموالُهم لِيأمَنوا مِن ثَورةٍ تكونُ مِن أهلِ البِلادِ، فقصَد مَوضِعَ القَيْروان، وبَنَى المسجدَ الجامعَ، وبَنَى النَّاسُ مَساجِدَهم ومَساكِنَهم, فأَمِنُوا واطْمَأنُّوا على المَقامِ فثَبَتَ الإسلامُ في تلك البلادِ المفتوحةِ. ثمَّ إنَّ مُعاوِيَة بن أبي سُفيان اسْتَعمل على مِصْر وأفريقيا مَسلَمةَ بن مَخْلَد الأنصاريَّ، فاسْتَعمل مَسلَمةُ على أفريقيا مَوْلًى له يُقالُ له: أبو المُهاجِر، فقَدِم أفريقيا وعزَل عُقبةَ واسْتَخَفَّ به، وسار عُقبةُ إلى الشَّامِ وعاتَبَ مُعاوِيَةَ على ما فَعلَهُ به أبو المُهاجِر، فاعْتَذَر إليه ووَعَدَهُ بإعادتِه إلى عَمَلِه، فتُوفِّي مُعاوِيَةُ ووَلِيَ بعدَه ابنُه يَزيدُ، فاسْتَعمل عُقبةَ بن نافعٍ على البِلادِ سنة اثنتين وسِتِّين، فسار إليها."},{"id":274,"title":"الحِصارُ الأوَّلُ للقُسطنطينيَّة عاصِمَة البِيزَنطيَّنين بقِيادَة سُفيان بن عَوفٍ .","date":["العام الهجري :49","العام الميلادي :669"],"text":"جَهَّزَ مُعاوِيَةُ بن أبي سُفيان جيشًا عظيمًا بَرًّا وبَحْرًا لِغَزْوِ القُسطنطينيَّة، وكان قائدَ الجيشِ سُفيانُ بن عَوفٍ الأزديُّ، وقاد الأُسْطولَ بُسْرُ بن أَرْطاة, وكان في الجيشِ ابنُ عبَّاسٍ، وابنُ عُمَر، وأبو أَيُّوبَ، وابنُ الزُّبيرِ، والحُسينُ بن عَلِيٍّ رضي الله عنهم، انْضَمُّوا إلى هذه الحَملَةِ مُتَمَثِّلينَ أَمامَ أَعيُنِهم قولَ الرَّسولِ: (لَتُفْتَحَنَّ القُسطنطينيَّةُ فَلَنِعْمَ الأميرُ أَميرُها، وَلَنِعْمَ الجيشُ ذلك الجيشُ). آمِلِينَ أن يَتَحَقَّقَ فيهم قولُ الرَّسولِ، فقد ثبَت عن رسولِ الله: (أوَّلُ جيشٍ يَغْزون مَدينةَ قَيْصَر مَغفورٌ لهم). وقام الجيشُ بحِصارِ القُسطنطينيَّة، وجَرَتْ اشْتِباكاتٌ عَديدة بين الطَّرفين خَسِرَ فيها المسلمون الكَثيرَ، وقد جاءَهُم مَدَدٌ مِن الشَّام بقيادةِ يَزيدَ بن مُعاوِيَة ممَّا قَوَّى أَمرَهُم، وتُوفِّي هناك أبو أيُّوبَ ودُفِنَ عند سُورِها؛ ولكن لم يَتِم فتحُها مع شِدَّةِ الحِصارِ وقُوَّتِه؛ وذلك لِمَنَعَةِ المدينةِ، وقُوَّةِ أَسوارِها، ومَكانِها في البَرِّ والبَحرِ، وأُحْرِقَت كثيرٌ مِن سُفُنِ المسلمين."},{"id":275,"title":"وَفاةُ الحسن بن عَلِيِّ بن أبي طالِب رضِي الله عنهما  .","date":["العام الهجري :49","العام الميلادي :669"],"text":"هو أبو محمَّد الحسنُ بن عَلِيِّ بن أبي طالِب الهاشِميُّ القُرشيُّ، المَدنيُّ الشَّهيدُ، سِبْطُ رسولِ الله صلَّى الله عليه وسلَّم ورَيْحانَتُه مِن الدُّنيا, وكان أَكثَرَهُم شَبَهًا بِوَجْهِ رسولِ الله صلَّى الله عليه وسلَّم, وهو سَيِّدُ شَبابِ أهلِ الجنَّة، ابنُ فاطِمةَ بنتِ رسولِ الله صلَّى الله عليه وسلَّم، وأبوهُ أميرُ المؤمنين عَلِيٌّ رضي الله عنه. وُلِدَ الحسنُ رضي الله عنه في نِصف رَمضان سنة 3هـ، حَظِيَ بِرِعايَةِ المُصطفى صلَّى الله عليه وسلَّم ما يَقرُب مِن ثماني سَنوات، وكان النَّبِيُّ صلَّى الله عليه وسلَّم يُحِبُّهُ حُبًّا جَمًّا، وقد تَوَلَّى النَّبِيُّ صلَّى الله عليه وسلَّم تَربيتَه منذ اليومِ الأوَّلِ لوِلادَتِه؛ فسَمَّاهُ الحسنَ، وكان صلَّى الله عليه وسلَّم يُداعِبُه كثيرًا، ويُقبِّلُه ويُعانِقُه حُبًّا له وعَطْفًا عليه. قال عنه صلَّى الله عليه وسلَّم وهو على المِنبَرِ: (ابْنِي هذا سَيِّدٌ، ولَعَلَّ الله أن يُصْلِحَ به بين فِئَتينِ مِن المسلمين). وقد تَحَقَّقَت هذه النُّبوءَةُ بتَنازُلِ الحسنِ رضي الله عنه عن الخِلافَة لمُعاوِيَة رضي الله عنه حَقْنًا لدِماءِ المسلمين، وأَبرَم الصُّلْحَ معه بعدَ بِضعَةِ أَشهُر مِن مُبايَعَتِه للخِلافَة، فكان ذلك فاتحةَ خيرٍ على المسلمين؛ إذ تَوحَّدَت جُهودُهم، وسُمِّيَ عام 41هـ \"عامَ الجَماعةِ\". وقِيلَ: كانت وفاتُه في الثامن من محرم عام 50هـ."},{"id":276,"title":"بِناءُ عُقبةَ بن نافعٍ مَحَطَّةً للجِهادِ اسمُها (القَيْروان) .","date":["العام الهجري :50","العام الميلادي :670"],"text":"بعدَ أن انْتَصر عُقبةُ بن نافعٍ في عِدَّةِ مَواقِع في فُتوحِه في أفريقيا على البَرْبَر رأى أن يَتَّخِذَ مدينةً يكونُ بها عَسكرُ المسلمين وأهلُهم وأموالُهم لِيَأمَنوا مِن ثَورَةٍ تكونُ مِن أهلِ البِلادِ، فقصَد مَوضِعَ القَيْروان، وكان أَجَمَةً مُشتبِكة بها مِن أنواعِ الحيوانِ، فأمَر ببِناءِ المدينةِ، فبُنِيَت، وبَنَى المسجدَ الجامعَ، وبَنَى النَّاسُ مَساجِدَهم ومَساكِنَهم، وكان دُورُها ثلاثة آلاف باعٍ وسِتِّمائة باع، وتَمَّ أَمرُها سنة خمسٍ وخمسين وسَكَنَها النَّاسُ، فكانت كمَحَطَّةٍ دائِمةٍ للمُجاهدين يبقون فيها مع أُسَرِهِم لا يَشْعرون بالغُربَةِ والسَّفَرِ، وتكونُ مُنْطَلَقَهم إلى البِلادِ لِيَفتَحوها. وكان في أثناءِ عِمارَةِ المدينةِ يَغْزو ويُرْسِل السَّرايا فتُغِيرُ وتَنْهَبُ، ودخَل كثيرٌ مِن البَرْبَر في الإسلامِ، واتَّسَعَت خُطَّةُ المسلمين، وقَوِيَ جَنانُ مَن هناك مِن الجُنودِ بمدينةِ القَيْروان، وأَمِنُوا واطْمَأنُّوا على المُقامِ فثَبَتَ الإسلامُ فيها."},{"id":277,"title":"وَفاةُ أُمِّ المؤمنين صَفِيَّة بنتِ حُيَيٍّ رضي الله عنها .","date":["العام الهجري :50","العام الميلادي :670"],"text":"هي صَفِيَّةُ بنتُ حُيَيِّ بن أَخْطَبَ، مِن وَلَدِ هارونَ النَّبِيِّ صلَّى الله عليه وسلَّم، وأُمُّها بَرَّةُ بنتُ سَمَوْأَل أُخْتُ رِفاعةَ، كانت تحت سَلَّامِ بنِ مِشْكَمٍ القُرَظيِّ، ثمَّ خلَف عليها كِنانةُ بن الرَّبيعِ بن أبي الحُقَيْقِ، سَباها النَّبِيُّ صلَّى الله عليه وسلَّم مِن خَيبر وكانت عَروسًا، وأَعْتَقَها وتَزوَّجَها بعدَ مَرجِعِه مِن خَيبر، توفِّيت في المدينةِ ودُفِنت في البَقيعِ رضي الله عنها وأرضاها."},{"id":278,"title":"وَفاةُ سعيدِ بن زيدٍ رضِي الله أَحَدِ العشرةِ المُبَشَّرين بالجنَّة .","date":["العام الهجري :51","العام الميلادي :671"],"text":"هو سعيدُ بن زيدِ بن عَمرِو بن نُفيلٍ، أَحَدُ العشرةِ المُبَشَّرين بالجنَّة، أَسلَم قديمًا قبلَ عُمَرَ، هو وامرأتُه فاطمةُ بنتُ الخطَّاب، وهي كانت سببَ إسلامِ عُمَر، وكان مِن المُهاجرين الأوَّلين، وآخَى رسولُ الله صلَّى الله عليه وسلَّم بينه وبين أُبَيِّ بن كعبٍ، صلَّى عليه عبدُ الله بن عُمَر، ونزَل في قَبرِه هو وسعدُ بن أبي وقَّاصٍ."},{"id":279,"title":"وَفاةُ أُمِّ المؤمنين مَيمونَة بنتِ الحارِث رضِي الله عنها .","date":["العام الهجري :51","العام الميلادي :671"],"text":"هي مَيمونَةُ بنتُ الحارِثِ بن حَزْنِ بن بُجيرِ بن الهُزَمِ، وأُمُّها هِندُ بنتُ عَوفِ بن زُهيرٍ، كانت تحت مَسعودِ بن عَمرِو بن عبدِ نائلٍ الثَّقفيِّ في الجاهليَّة وفارَقَها، ثمَّ خلَف عليها أبو رُهْمِ بن عبدِ العُزَّى بن أبي قيسِ بن عبدِ وُدٍّ فتُوفِّي عنها فتَزوَّجها النَّبِيُّ صلَّى الله عليه وسلَّم في عُمرَةِ القَضاءِ، وهي آخِرُ نِسائِه تَزْوِيجًا، توفِّيت في سَرِفَ قُربَ مكَّة في المكان الذي بَنَى عليها النَّبِيُّ صلَّى الله عليه وسلَّم، وقِيلَ: بل توفِّيت في مكَّة ونُقِلَت إلى سَرِفَ، صلَّى عليها ابنُ عبَّاسٍ."},{"id":280,"title":"زِيادِ بن خِراشٍ العِجْليِّ يلتحق بفكر الخوارج .","date":["العام الهجري :52","العام الميلادي :672"],"text":"خرَج زيادُ بن خِراشٍ العِجليُّ -ثائِرٌ مِن الحَروريَّة على مُعاوِيَة بن أبي سُفيان- في ثلاثمائةِ فارسٍ، فأتى أرضَ مَسْكِن مِن السَّوادِ، فسَيَّرَ إليه زيادُ بن أَبيهِ خَيلًا عليها سعدُ بن حُذيفةَ أو غيرُه، فقَتَلوهم وقد صاروا إلى ماه، ونَشَبَت مَعاركُ انتهَت بقَتلِ زيادٍ العِجليِّ. ثمَّ خرَج على زيادِ بن أَبيهِ أيضًا رجلٌ مِن طَيِّء يُقالُ له: مُعاذ، فأتى نَهْرَ عبدِ الرَّحمن ابنِ أُمِّ الحَكَمِ في ثلاثين رجلًا هذه السَنَةَ، فبعَث إليه زيادٌ مَن قتَلَه وأصحابَهُ، وقِيلَ: بل حَلَّ لِواءَهُ واسْتَأمَنَ. ويُقالُ لهم: أَصحابُ نَهْرِ عبدِ الرَّحمن."},{"id":281,"title":"فَتحُ المسلمين جزيرة رُودِس (من جزر اليونان) .","date":["العام الهجري :53","العام الميلادي :672"],"text":"افتَتَح المسلمون وعليهم جُنادةُ بن أبي أُمَيَّة \"جَزيرةَ رُودِس\" فأقام بها طائفةٌ مِن المسلمين، كانت أشدَّ شيءٍ على الكُفَّار، يَعتَرِضون لهم في البَحرِ ويَقطَعون سَبيلَهم، وكان مُعاوِيَة يَدِرُّ عليهم الأرزاقَ والأُعْطِيات الجَزيلةَ، وكانوا على حَذَرٍ شَديدٍ مِن الفِرنْج، يَبِيتون في حِصْنٍ عَظيمٍ فيه حَوائِجُهم ودَوابُّهُم وحَواصِلُهم، ولهم نَواطِير على البَحرِ يُنذِرونَهُم إن قَدِمَ عَدُوٌّ أو كادَهُم أَحَدٌ، وما زالوا كذلك حتَّى كانت خِلافَة يَزيدَ بن مُعاوِيَة بعدَ أبيهِ، فحَوَّلَهم مِن تلك الجزيرةِ، وقد كانت للمسلمين بها أَموالٌ كثيرةٌ وزِراعاتٌ غَزيرةٌ."},{"id":282,"title":"الحِصارُ الثَّاني للقُسطنطينيَّة .","date":["العام الهجري :54","العام الميلادي :673"],"text":"كان هذا الحِصارُ في هذه المَرَّةِ بقِيادَة فَضالَةَ بن عُبيدٍ الأنصاريِّ، وعلى الأُسْطولِ البَحريِّ عبدُ الله بن قيسٍ الحارثيُّ، وجُنادةُ بن أبي أُمَيَّة، وأمَّا أسطولُ الشَّام فكان بإمْرَةِ يَزيدَ بن شَجَرَة الرُّهاويِّ، ودام هذا الحِصارُ إلى عام 57 هـ، احْتَلُّوا فيها عِدَّةَ جُزُرٍ قريبة كأَرْواد وكزيكوس، واتُّخِذَت قَواعِد عَسكريَّة, ولم تَسْتطِعْ هذه الحَمْلةُ الثَّانية اقْتِحامَ القُسطنطينيَّة بسببِ مَناعَةِ أسوارِها، وما كان يُطْلِقُهُ البِيزَنطيُّون على سُفُنِ الأُسْطولِ الإسلاميِّ مِن نِيران، فانْتَهى الأمرُ بعَقْدِ صُلْحٍ بين المسلمين والبيزَنْطيِّين."},{"id":283,"title":"فتحُ المسلمين جزيرة كَرِيت \"أَقْرِيطِش\" (أكبرُ الجُزُرِ اليُونانيَّة) .","date":["العام الهجري :55","العام الميلادي :674"],"text":"هي أكبرُ الجُزُرِ اليُونانيَّة، وخامسُ أكبرِ جَزيرة في البحرِ الأبيضِ المتوسِّط، وصَل المسلمون إلى كَرِيت في وقتٍ مُبَكِّر، إذ ضرَبوا الحِصارَ عليها ولم يَنتصِف القَرنُ الأوَّلُ الهجريُّ بعدُ؛ ولكنَّهم لم يَتمكَّنوا مِن فَتحِها، إذ أن قُوَّتَهم البَحريَّة لم تكُن قد تكامَلَت بعدُ. رَوَى البَلاذُرِيُّ: غَزا جُنادةُ بن أبي أُمَيَّة أَقْرِيطِش، فلمَّا كان زمن الوَليدِ بن عبدِ الملك فتَح بعضَها ثمَّ أغلق، وغَزاها حُمَيدُ بن مَعْيوفٍ الهَمْدانيُّ في خِلافَة الرَّشيدِ ففتَح بعضَها، وكان المسلمون قد شُغِلوا بالقِتالِ في جَبَهاتٍ أُخرى، مما أعان على بَقاءِ حُكْمِ الرُّومِ في كَرِيت؛ ولكنَّه لم يكُن وَطِيدَ الدَّعائِم للاخْتِلاف في مَذاهِب الدِّين بين الحاكِمين والمَحْكومين."},{"id":284,"title":"غارةُ الأُمَويِّين على بِلاد البَلْقان وفَتحُها جُزئيًّا\n  .","date":["العام الهجري :55","العام الميلادي :674"],"text":"البَلْقان هي شِبه جَزيرة تقَع في الجنوبِ الشَّرقيِّ مِن قارَّة أوروبا، وتَضُمُّ عَديدًامِن بُلدان شرق أوروبا مثل: المجر، رومانيا، يوغسلافيا سابقًا، وبلغاريا. اتَّجهت أَنظارُ المسلمين نحوَ الشَّمال والغربِ حيث الدَّولة الرُّومانيَّة الشَّرقيَّة التي كانت تُغيرُ على المناطقِ الخاضِعة لِسُلطان المسلمين, فرَتَّبَ مُعاوِيَةُ الغَزْوَ إليها بَرًّا وبَحرًا، وجَهَّزَ أُسطولًا بلَغ عددُه 1700 سَفينة، وفتَح عِدَّةِ جِهاتٍ كجزيرةِ رُودِس وبعض الجُزُرِ اليُونانيَّة الأُخرى، كما أَكْثَرَ بَرًّا مِن الصَّوائِف والشَّواتي -حَمَلات الصَّيفِ والشِّتاءِ-"},{"id":285,"title":"وَفاةُ سعدِ بن أبي وقَّاص رضي الله عنه أَحَدِ العشرةِ المُبَشَّرين بالجنَّة  .","date":["العام الهجري :55","العام الميلادي :674"],"text":"هو سعدُ بن أبي وقَّاص مالكِ بن أُهَيْب، الزُّهريُّ القُرشيُّ، صَحابيٌّ مِن أوائلِ مَن دَخلوا في الإسلامِ، وكان في السَّابعة عشر مِن عُمُرهِ، ولم يَسبِقْهُ في الإسلامِ إلَّا أبو بكرٍ، وعَلِيٌّ، وزَيدٌ، وهو أحدُ العَشرةِ المُبَشَّرين بالجنَّة، فكان مِن المُتَقَدِّمين في الإسلامِ، شَهِد المَشاهِدَ كُلَّها، أوَّلُ مَن رَمى بِسَهمٍ في سَبيلِ الله، وله قال النَّبِيُّ صلَّى الله عليه وسلَّم: (ارْمِ سعدُ فِداكَ أبي وأُمِّي). كان مُجابَ الدَّعوَة، وَلِيَ إِمْرَةَ الكوفَة لِعُمَر، لم يَحْضَرْ الجَملَ ولا صِفِّينَ ولا التَّحْكيمَ، قاتَل في سَبيلِ الله، وفتَح الله على يَديهِ الكَثيرَ مِن بِلادِ فارِسَ أيَّام عُمَر، تُوفِّي في العَقيقِ قُرْب المدينةِ، وحُمِلَ إلى البَقيعِ ودُفِنَ فيه، وكان آخرَ المُهاجرين مَوتًا."},{"id":286,"title":"فَتحُ بلاد ما وراءَ النَّهْرِ وإغارةُ سعيدِ بن عُثمان على بُخارى وفَتحُها .","date":["العام الهجري :56","العام الميلادي :675"],"text":"وَلَّى مُعاوِيَةُ بن أبي سُفيان عُبيدَ الله بن زيادٍ على خُراسان فبلَغ بِيكَنْد وأَرْغَم خاتون أَميرَةَ بُخارى على الصُّلْحِ؛ ولكنَّها اسْتَنجدَت بالتُّرْكِ فأرسلوا جيشًا أَلْحَقَ به المسلمون الهَزيمةَ، فأُرْغِمت على طَلَبِ الصُّلْحِ، وكان مُعاوِيَةُ قد وَلَّى سعيدَ بن عُثمان بن عفَّان إمارةَ خُراسان بَدَل عُبيدِ الله فدخَل الجيشُ بُخارى بقِيادَتِه."},{"id":287,"title":"وَفاةُ أُمِّ المؤمنين جُوَيْرِيَة بنتِ الحارِث رضِي الله عنها .","date":["العام الهجري :57","الشهر القمري : ربيع الأول","العام الميلادي :677"],"text":"هي ابنةُ سَيِّدِ بَنِي المُصْطَلِق مِن خُزاعَة، وقَعَت في السَّبْي بعدَ غَزوةِ المُصطَلِق فوقَعَت في سَهْمِ ثابتِ بن قيسٍ، فكاتَبَتْ نَفْسَها ثمَّ أَتَت النَّبِيَّ صلَّى الله عليه وسلَّم تَستَعينُه فعَرَضَ عليها أن يُؤَدِّيَ عنها ويَتَزوَّجها فقَبِلَت، وكانت قبلَ ذلك -يعني قبلَ السَّبْي- تحت صَفوان بن مالكٍ وقد قُتِلَ فيمَن قُتِلَ في الغَزوةِ، ثمَّ لمَّا تَزوَّجها النَّبِيُّ صلَّى الله عليه وسلَّم أَطْلَقَ المسلمون أَسْراهُم مِن بَنِي المُصطلِق بسبَبِها إكرامًا لها حتَّى لا يكونَ أخوالُ المؤمنين سَبايا تحتهم، فكانت مِن أَعظمِ النِّساءِ بَركةً على قَومِها، كانت كثيرةَ التَّعَبُّدِ والذِّكْرِ، توفِّيت بالمدينةِ زمنَ مُعاوِيَة."},{"id":288,"title":"عَزْلُ مَرْوانَ بن الحَكَمِ عن المدينةِ وتَوْلِيةُ الوَليدِ بن عُتبةَ .","date":["العام الهجري :57","الشهر القمري : شوال","العام الميلادي :677"],"text":"عَزَلَ مُعاوِيَةُ رضي الله عنه مَرْوانَ بن الحَكَمِ عن المدينةِ ووَلَّى عليها الوَليدَ بن عُتبةَ بن أبي سُفيان، وهو الذي حَجَّ بالنَّاسِ في هذه السَّنةِ، لأنَّه صارت إليه إمْرَةُ المدينةِ، ولم يَزَلْ عليها والِيًا حتَّى مات مُعاوِيَةُ رضي الله عنه."},{"id":289,"title":"وَفاةُ أُمِّ المؤمنين عائِشةَ رضِي الله عنها .","date":["العام الهجري :58","الشهر القمري : رمضان","العام الميلادي :678"],"text":"هي عائشةُ الصِّدِّيقةُ بنتُ الصِّدِّيق رضي الله عنها، تَزوَّجها رسولُ الله صلَّى الله عليه وسلَّم بعدَ خَديجةَ في مكَّة؛ ولكن لم يَدْخُلْ بها إلَّا في المدينةِ بعدَ الهِجرَةِ، لها مِن الفضائلِ الكثيرُ، نزلت بَراءتُها مِن السَّماءِ بآياتٍ تُتْلَى إلى يومِ القِيامَة، توفِّيت في المدينةِ النَّبَوِيَّةِ وأَوْصَتْ أن تُدْفَنَ ليلًا، وصلَّى عليها أبو هُريرةَ، ونزَل في قَبرِها خمسةٌ ودُفِنَت في البَقيعِ، وكانت مِن أَفْقَهِ النِّساءِ، فجَزاها الله خيرًا عن الإسلامِ والمسلمين ورضي الله عنها وأرضاها، وكانت مِن المُكْثِرين في الرِّاويَةِ عن النَّبِيِّ صلَّى الله عليه وسلَّم، ولها اسْتِدْراكاتٌ على الصَّحابَةِ مَعروفة."},{"id":290,"title":"وَفاةُ أبي هُريرةَ رضي الله عنه .","date":["العام الهجري :59","العام الميلادي :678"],"text":"أَسلَم أبو هُريرةَ سنةَ خَيبرَ، ولَزِمَ النَّبِيَّ صلَّى الله عليه وسلَّم حتَّى وَفاتِه، فكان ذلك ذُخْرًا له، فلا ضَيْرَ أن يكونَ أكثرَ الصَّحابةِ رِوايةً عن رسولِ الله صلَّى الله عليه وسلَّم فهو مِن حُفَّاظِهم، ودَعا له النَّبِيُّ صلَّى الله عليه وسلَّم بالحِفْظِ فقارَبَت الأحاديثُ التي مِن رِوايَتِه إلى خمسةِ آلاف حديثٍ، وقد اخْتُلِف في اسمِه، وكان يدعو الله ألَّا تُدْرِكَه سَنَةُ سِتِّين فتُوفِّي قَبلَها، وصلَّى عليه الوَليدُ بن عُتبةَ بن أبي سُفيان نائبُ المدينةِ، وفي القَوْمِ ابنُ عُمَر، وأبو سعيدٍ الخُدْرِيُّ، وخَلْقٌ مِن الصَّحابَةِ غيرُهم، وكان ذلك عند صلاةِ العصرِ، وكانت وَفاتُه في دارِه بالعَقيقِ، فحُمِلَ إلى المدينةِ فصُلِّيَ عليه، ثمَّ دُفِنَ بالبَقيعِ رحمه الله ورضِي عنه وجَزاهُ عن الإسلام والمسلمين خيرًا."},{"id":291,"title":"وَفاةُ أُمِّ المؤمنين أُمِّ سَلَمةَ رضِي الله عنها .","date":["العام الهجري :59","الشهر القمري : شوال","العام الميلادي :679"],"text":"هي هِندُ بنتُ أبي أُمَيَّة سُهيلِ بن المُغيرَةِ بن عبدِ الله، وأُمُّها عاتِكَةُ بنتُ عامرِ بن رَبيعَة، كانت تحت أبي سَلمةَ عبدِ الله بن عبدِ الأَسَدِ بن هِلالٍ، كانت أوَّلَ مَن هاجَر إلى الحَبشةِ هي وزَوجُها، ويُقالُ أيضًا: إنَّ أُمَّ سَلَمةَ أوَّلُ ظَعينَة هاجَرَت إلى المدينةِ، تَزوَّجها النَّبِيُّ صلَّى الله عليه وسلَّم بعدَ بدرٍ، وقِيلَ: بعدَ أُحُدٍ. وقِصَّتُها يومَ الحُديبيَة حيث أشارَت على النَّبِيِّ صلَّى الله عليه وسلَّم بأن يَحْلِقَ هو ويَنْحَرَ دون أن يُكَلِّمَ أَحَدًا، فلمَّا فعَل تَسارَع الصَّحابةُ إلى فِعْلِ ما كانوا قد أَحْجَموا قبلُ عن فِعْلِه لمَّا أَمرَهُم به النَّبِيُّ صلَّى الله عليه وسلَّم، توفِّيت في المدينةِ، وقيل كانت وفاتها عام 61 للهجرة."},{"id":292,"title":"وَفاةُ مُعاوِيَة بن أبي سُفيان رضي الله عنه .","date":["العام الهجري :60","الشهر القمري : رجب","العام الميلادي :680"],"text":"هو أبو عبدِ الرَّحمن مُعاوِيَةُ بن أبي سُفيان الأُمَويُّ القُرشيُّ، مِن أصحابِ الرَّسول صلى الله عليه وسلم، وأحدُ كُتَّابِ الوَحْي، سادِسُ الخُلفاءِ في الإسلامِ، وأوَّلُ مُلوكِ المسلمين، ومُؤَسِّسُ الدَّولةِ الأُمويَّة في الشَّام، وُلِدَ بمكَّة وتَعَلَّم الكِتابَةَ والحِسابَ، أَسلَم مُعاوِيَةُ رضي الله عنه يومَ الفَتحِ، وقِيلَ: في عُمرَةِ القَضاءِ وكان يَكتُم إسلامَهُ خَوفًا مِن أَبيهِ، وقد اسْتَعمَله رسولُ الله صلَّى الله عليه وسلَّم على كِتابَةِ الوَحْي، واسْتَعمَلَه على الشَّامِ الخُلفاءُ: عُمَرُ، وعُثمانُ، وبَقِيَ على الشَّام في خِلافَة عَلِيٍّ بغَيرِ رِضاهُ، فبَقِيَ كذلك قُرابةَ العِشرين سنة، ثمَّ تَمَّ له الأَمْرُ بعدَ تَنازُلِ الحسنِ بن عَلِيٍّ له، وبَقِيَ خَليفَةً مُدَّةَ تِسعةَ عشرَ عامًا وأَشْهُر، فتَح الله له فيها الكثيرَ مِن البِلادِ، واشْتُهِرَ بالحِكمَةِ في سِياسَتِه للنَّاس، ومُداراتِه لهم، وكان قد عَهِدَ لابنِه يَزيدَ قبلَ مَوتِه، وبعَث في البِلادِ لِيأخُذوا له ذلك، وتُوفِّي في دِمشقَ وصلَّى عليه الضَّحَّاكُ بن قيسٍ، ودُفِنَ فيها، جَزاهُ الله خيرًا عن الإسلام والمسلمين."},{"id":293,"title":"يَزيدُ بن مُعاوِيَة يَتَوَلَّى الخِلافَة الأُمويَّة بعدَ وَفاةِ والِدهِ .","date":["العام الهجري :60","الشهر القمري : رجب","العام الميلادي :680"],"text":"كان مُعاوِيَةُ في عام 50 هـ قد عَهِدَ إليه بالخِلافَة مِن بعدِه، وأخَذ ذلك على النَّاسِ؛ ولكنَّ البعضَ لم يَرْضَ مِثلَ ابنِ عُمَر، وابنِ الزُّبيرِ، وعبدِ الرَّحمن بن أبي بكرٍ، والحُسينِ بن عَلِيٍّ، ثمَّ لمَّا حضَرَت مُعاوِيَةَ الوَفاةُ كان يَزيدُ غائبًا فأَوْصى إليه، ثمَّ لمَّا تُوفِّي بايَعَت الأمصارُ لِيَزيدَ إلَّا مَن ذُكِرَ آنِفًا، وبذلك تَمَّتْ له الخِلافَة، ثمَّ بايَع له ابنُ عُمَرَ، وابنُ عبَّاسٍ، أمَّا ابنُ الزُّبيرِ فخرج إلى مكَّة وحصَل منه ما حصَل، وأمَّا الحُسينُ فلَحِقَهُ أيضًا إلى مكَّة حتَّى خرَج إلى الكوفَةِ وكان فيها ما كان."},{"id":294,"title":"مُراسَلةُ الكوفيِّين الحُسينَ بن عَلِيٍّ رضِي الله عنه ومَسيرُه إليهم .","date":["العام الهجري :60","الشهر القمري : ذي الحجة","العام الميلادي :680"],"text":"بِمُجَرَّد وَفاةِ مُعاوِيَة بن أبي سُفيان سارَع زُعماءُ الكوفَة بالكِتابةِ إلى الحُسين بن عَلِيٍّ رضي الله عنه، وطلبوا منه المَسيرَ إليهم على وَجْهِ السُّرعةِ, فلمَّا تَواتَرت الكُتُبُ إليه مِن جِهَةِ أهل العِراق, وتَكرَّرت الرُّسُلُ بينهم وبينه, وجاءَهُ كِتابُ مُسلِم بن عَقِيلَ بالقُدومِ عليه بأَهْلِه, ثمَّ وقَع في غُبونِ ذلك ما وقَع مِن قَتْلِ مُسلمِ بن عَقِيلَ والحُسينُ لا يَعلَم بشيء مِن ذلك, فعزَم على المَسيرِ إليهم, والقُدومِ عليهم, فاتَّفَق خُروجُه مِن مكَّة أيَّام التَّرويَةِ قبلَ مَقتَلِ مُسلِم بيومٍ واحدٍ, فإنَّ مُسلِمًا قُتِلَ يومَ عَرفَة, ولمَّا اسْتَشعر النَّاسُ خُروجَه أشْفَقوا عليه مِن ذلك, وحَذَّروهُ منه, وأشار عليه ذوو الرَّأي منهم والمَحَبَّةِ له بعَدمِ الخُروجِ إلى العِراق, وأَمَروهُ بالمُقامِ بمكَّة, وذَكَّروهُ ما جَرى لأبيه وأخيه معهم, وكان ممَّن نَهاهُ عن الخُروجِ عبدُ الله بن عبَّاس، وعبدُ الله بن عُمَر، وعبدُ الله بن الزُّبيرِ، وأبو سعيدٍ الخُدريُّ, إلَّا أنَّه أَصَرَّ على الخُروجِ إلى الكوفَة."},{"id":295,"title":"فَتحُ عُقبةَ بن نافعٍ باغايَة وطَنْجَة وأَرَبَة. \n  .","date":["العام الهجري :61","العام الميلادي :680"],"text":"سار عُقبةُ بن نافعٍ بعدَ أن وَلَّاهُ يَزيدُ أفريقيا في عَسكرٍ عَظيمٍ حتَّى دخَل مَدينةَ باغايَة وقد اجْتَمع بها خَلْقٌ كثيرٌ مِن الرُّومِ، فقاتَلوهُ قِتالًا شَديدًا وانْهزَموا عنه، وقَتَلَ فيهم قَتلًا ذَريعًا، وغَنِمَ منهم غَنائمَ كثيرةً، ودخَل المُنْهزِمون المدينةَ وحاصَرهُم عُقبةُ. ثمَّ كَرِهَ المُقامَ عليهم فسار إلى بلاد الزَّابِ، وهي بِلادٌ واسعةٌ فيها عِدَّةُ مُدُنٍ وقُرىً كثيرةٍ، فقصَد مَدينَتَها العُظْمى واسْمُها أَرَبَة، فامْتَنع بها مَن هناك مِن الرُّوم والنَّصارى، وهرَب بعضُهم إلى الجِبالِ، فاقْتَتَل المسلمون ومَن بالمدينةِ مِن النَّصارى عِدَّةَ دَفَعاتٍ، ثمَّ انْهزَم النَّصارى وقُتِلَ كثيرٌ مِن فِرسانِهم، ورحَل إلى تاهرت. فلمَّا بلَغ الرُّومَ خَبرُه اسْتَعانوا بالبَرْبَر فأجابوهم ونَصروهُم، فاجتمعوا في جَمْعٍ كثيرٍ والْتَقوا واقْتَتَلوا قِتالًا شَديدًا، واشْتَدَّ الأمرُ على المسلمين لِكَثرةِ العَدُوِّ، ثمَّ إن الله تعالى نَصرَهُم فانهَزمَت الرُّومُ والبَرْبَر وأَخذَهُم السَّيفُ، وكَثُرَ فيهم القَتلُ، وغَنِمَ المسلمون أَموالَهم وسِلاحَهُم. ثمَّ سار حتَّى نزل على طَنْجَة فَلَقِيَهُ بَطْرِيقٌ مِن الرُّومِ اسمُه يليان، فأَهْدَى له هَدِيَّةً حَسنةً ونزَل على حُكمِه، ثمَّ سأله عن الأندلُسِ فعَظُمَ الأمرُ عليه، فسأله عن البَرْبَر، فقال: هم كَثيرون لا يَعلَم عددَهُم إلَّا الله، وهم بالسُّوسِ الأَدْنى، وهم كُفَّارٌ لم يَدخلوا في النَّصرانيَّة، ولهم بَأسٌ شَديدٌ. فسار عُقبةُ إليهم نحوَ السُّوسِ الأَدْنى، وهي مَغرِبُ طَنْجَة، فانتهى إلى أوائلِ البَرْبَر، فلقوه في جَمعٍ كثيرٍ، فقَتَلَ فيهم قَتلًا ذَريعًا، وبعَث خَيْلَه في كُلِّ مكانٍ هربوا إليه، وسار هو حتَّى وصَل إلى السُّوسِ الأقصى، وقد اجتمع له البَرْبَر في عالمٍ لا يُحْصَى، فلَقِيَهم وقاتَلهُم وهَزمَهُم، وقَتَلَ المسلمون فيهم حتَّى مَلُّوا وغَنِموا منهم وسَبَوْا سَبْيًا كثيرًا، وسار حتَّى بلَغ ماليان ورأى البَحرَ المُحيطَ، فقال: يا رَبِّ، لولا هذا البَحرُ لمَضيْتُ في البِلادِ مُجاهدًا في سَبيلِك. ثمَّ عاد فنَفَرَ الرُّومُ والبَرْبَر عن طَريقِه خَوفًا منه، فلمَّا وصَل إلى مدينة طُبْنَة أَمَرَ أصحابَه أن يَتقدَّموا فَوْجًا فَوْجًا ثِقَةً منه بما نال مِن العَدُوِّ، وأنَّه لم يُبْقِ أحدًا يَخشاهُ، وسار إلى تَهُوذَة لِيَنظُرَ إليها في نَفَرٍ يَسيرٍ، فلمَّا رآه الرُّومُ في قِلَّةٍ طَمِعوا فيه، فأغلقوا بابَ الحِصْنِ وشَتَموهُ وقاتَلوهُ وهو يَدعوهُم إلى الإسلامِ فلم يَقبَلوا منه."},{"id":296,"title":"مَقْتَلُ الحُسينِ بن عَلِيٍّ رضِي الله عنهما في كَرْبَلاء  .","date":["العام الهجري :61","الشهر القمري : محرم","العام الميلادي :680"],"text":"لم يُبايِعْ الحُسينُ بن عَلِيٍّ رضي الله عنه لِيَزيدَ، وبَقِيَ في مكَّة هو وابنُ الزُّبيرِ؛ ولكنَّ أهلَ الكوفَة راسَلوا الحُسينَ لِيَقْدُمَ عليهم لِيُبايِعوهُ ويَنصُروهُ فتكونُ له الخِلافَة، وكان على الكوفَة عُبيدُ الله بن زيادٍ، فبعَث الحُسينُ ابنَ عَمِّهِ مُسلِم بن عَقِيلَ لِيَعلَمَ له صِدْقَ أهلِ الكوفَة، فقَبَضَ عليه ابنُ زيادٍ وقَتَلَهُ، وتَوالَت الكُتُبُ مِن أهلِ الكوفَةِ للحُسينِ لِيَحضُرَ إليهم حتَّى عزَم على ذلك، فناصَحَهُ الكثيرُ مِن الرِّجالِ والنِّساءِ منهم: ابنُ عُمَر، وأخوهُ محمَّدُ بن الحَنَفِيَّةِ، وابنُ عبَّاسٍ، وأبو سَعيدٍ الخُدريُّ وعبدُ الله بن الزُّبيرِ.... ألَّا يَفْعَلَ، وأنَّهم سَيَخْذُلونَه كما خَذلوا أباهُ وأخاهُ مِن قَبلُ؛ لكنَّ قَدَرَ الله سابقٌ فأَبَى إلَّا الذِّهابَ إليهم، فخرَج مِن مكَّة في ذي الحَجَّة، ولمَّا عَلِمَ ابنُ زيادٍ بمَخْرَجِه جَهَّزَ له مَن يُقابِلهُ، فلمَّا قَدِمَ الحُسينُ وقد كان وَصَلَهُ خبرُ مَوتِ مُسلِم وأخيهِ مِن الرَّضاعِ فقال للنَّاس مَن أَحَبَّ أن يَنْصرِفَ فليَنْصَرِفْ، ليس عليه مِنَّا ذِمامٌ. فتَفَرَّقوا يَمينًا وشِمالًا حتَّى بَقِيَ في أصحابِه الذين جاؤوا معه مِن مكَّة، وقابَلَهم الحُرُّ بن يَزيدَ مِن قِبَلِ ابنِ زيادٍ لِيُحْضِرَ الحُسينَ ومَن معه إلى ابنِ زيادٍ؛ ولكنَّ الحُسينَ أَبَى عليه ذلك، فلم يَقْتُلْه الحُرُّ وظَلَّ يُسايِرُهُ حتَّى لا يَدخُلَ الكوفَة، حتَّى كانوا قريبًا مِن نِينَوَى جاء كتابُ ابنِ زيادٍ إلى الحُرِّ أن يُنْزِلَ الحُسينَ بالعَراءِ بغَيرِ ماءٍ، ثمَّ جاء جيشُ عُمَر بن سعدِ بن أبي وقَّاص كذلك للحُسينِ، إمَّا أن يُبايِع، وإمَّا أن يَرى ابنُ زيادٍ فيه رَأيَهُ، وعرَض الحُسينُ عليهم إمَّا أن يَتركوهُ فيَرجِع مِن حيث أَتَى، أو يَذهَب إلى الشَّام فيَضَعُ يَدَهُ في يَدِ يَزيدَ بن مُعاوِيَة، وإمَّا أن يَسيرَ إلى أيِّ ثَغْرٍ مِن ثُغورِ المسلمين فيكون واحدًا منهم، له ما لهم وعليه ما عليهم. فلم يَقْبَلوا منه شيئًا مِن ذلك، وأَرسَل ابنُ زيادٍ طائفةً أُخرى معها كِتابٌ إلى عُمَر بن سعدٍ أن ائْتِ بهم أو قاتِلْهُم، ثمَّ لمَّا كان اليومُ العاشر مِن مُحرَّم الْتَقى الصَّفَّانِ، وذَكَّرَهُم الحُسينُ مَرَّةً أُخرى بكُتُبِهم له بالقُدومِ فأنكروا ذلك، ووَعَظَهُم فأَبَوْا فاقْتَتَلوا قِتالًا شديدًا، ومال الحُرُّ إلى الحُسينِ وقاتَل معه، وكان آخِرَ مَن بَقِيَ مِن أصحابِ الحُسينِ سُويدُ بن أبي المُطاعِ الخَثْعَميُّ، وكان أوَّلَ مَن قُتِلَ مِن آلِ بَنِي أبي طالِبٍ يَومئذٍ عَلِيٌّ الأكبرُ ابنُ الحُسينِ، ومكَث الحُسينُ طويلًا مِن النَّهارِ كُلمَّا انتهى إليه رجلٌ مِن النَّاسِ رجَع عنه وَكَرِهَ أن يَتَوَلَّى قَتْلَهُ وعِظَمَ إثْمِهِ عليه.وكان أصحابُ الحُسينِ يُدافِعون عنه، ولمَّا قُتِلَ أصحابُه لم يَجْرُؤْ أَحَدٌ على قَتْلِه، وكان جيشُ عُمَر بن سعدٍ يَتَدافعون، ويخشى كُلُّ فَردٍ أن يَبُوءَ بِقَتْلِه، وتَمَنَّوْا أن يَسْتَسْلِمَ؛ لكنَّ شِمْرَ بن ذي الجَوْشَنِ صاح في الجُنْدِ: وَيْحَكُم، ماذا تَنتَظِرون بالرَّجُلِ! اقْتُلوهُ، ثَكَلَتْكُم أُمَّهاتُكم. وأَمَرَهُم بِقَتْلِه, فحَمَلوا عليه مِن كُلِّ جانِبٍ، وضَرَبهُ زُرْعَةُ بن شَريكٍ التَّميميُّ, ثمَّ طَعَنَهُ سِنانُ بن أَنَسٍ النَّخَعيُّ واحْتَزَّ رَأسَهُ. ويُقالُ: إنَّ الذي قَتَلَهُ عُروةُ بن بَطَّار التَّغْلِبيُّ وزيدُ بن رُقادٍ الجَنْبِيُّ. ويُقالُ: إنَّ المُتَوَلِّي الإجهازَ عليه شِمْرُ بن ذي الجَوْشَن الضَّبِّيُّ، وحمَل رَأسَهُ إلى ابنِ زيادٍ خَوْلِيُّ بن يَزيدَ الأَصْبَحيُّ. ودُفِنَ الحُسينُ رضي الله عنه وأصحابُه أهلُ الغاضِريَّة مِن بَنِي أَسَدٍ بعدَ قَتلِهم بيَومٍ. قال شيخُ الإسلامِ في قَتلِه رضي الله عنه: قُتِلَ الحُسينُ بن عَلِيٍّ رضِي الله عنهما يومَ عاشوراءَ، قَتَلَتْهُ الطَّائفةُ الظَّالمةُ الباغيةُ، وأَكرَم الله الحُسينَ بالشَّهادةِ، كما أَكرَم بها مَن أَكرَم مِن أهلِ بَيتِه، أَكرَم بها حَمزةَ وجَعفَرًا، وأباه عَلِيًّا، وغَيرَهُم، وكانت شَهادتُه ممَّا رفَع الله بها مَنزِلَتَه، وأَعْلَى دَرَجتَهُ، والمَنازِلُ العاليةُ لا تُنالُ إلَّا بالبَلاءِ، قَتلوهُ مَظلومًا شَهيدًا شَهادةً أَكرَمَهُ الله بها، وأَلْحَقَهُ بأهلِ بَيتِه الطَّيِّبين الطَّاهِرين، وأَهانَ بها مَن ظَلمَهُ واعْتَدى عليه، وأَوْجَبَ ذلك شَرًّا بين النَّاسِ، فصارَت طائِفَة جاهِلَة ظالِمَة: إمَّا مُلْحِدة مُنافِقَة، وإمَّا ضَالَّة غاوِيَة، تُظْهِر مُوالاتِه ومُوالاةِ أهلِ بَيتِه، تَتَّخِذُ يومَ عاشوراء يومَ مَأْتَم وحُزْن ونِياحَة، وتُظْهِر فيه شِعارَ الجاهليَّة مِن لَطْمِ الخُدودِ، وشَقِّ الجُيوبِ، والتَّعَزِّي بِعَزاءِ الجاهليَّة. ومِن كَرامَةِ الله للمؤمنين أنَّ مُصيبةَ الحُسينِ وغَيرِه إذا ذُكِرَت بعدَ طولِ العَهْدِ يُسْتَرْجَعُ فيها، كما أمَرَ الله ورسولُه؛ لِيُعْطَى مِن الأجرِ مِثلُ أَجْرِ المُصابِ يومَ أُصِيبَ بها. وإذا كان الله تعالى قد أَمَرَ بالصَّبْرِ والاحْتِسابِ عند حَدَثان العَهْدِ بالمُصيبَةِ فكيف مع طولِ الزَّمانِ, فكان ما زَيَّنَهُ الشَّيطانُ لأهلِ الضَّلالِ والغِيِّ مِن اتِّخاذِ يومِ عاشوراء مَأتمًا، وما يَصنعون فيه مِن النَّدْبِ والنِّياحَةِ، وإنشادِ قَصائدِ الحُزنِ، ورِوايةِ الأخبارِ التي فيها كَذِبٌ كثيرٌ -والصِّدقُ فيها ليس فيه إلَّا تَجديدُ الحُزنِ- والتَّعَصُّبِ، وإثارةِ الشَّحناءِ والحَرْبِ، وإلقاءِ الفِتَنِ بين أهلِ الإسلامِ؛ والتَّوسُّلِ بذلك إلى سَبِّ السَّابِقين الأوَّلين، وكَثْرَةِ الكَذِبِ والفِتَنِ في الدُّنيا، ولم يَعرِفْ طوائفُ الإسلامِ أكثرَ كَذِبًا وفِتَنًا ومُعاونةً للكُفَّارِ على أهلِ الإسلامِ مِن هذه الطَّائفَةِ الضَّالَّةِ الغاويَةِ، فإنَّهم شَرٌ مِن الخَوارِج المارِقين."},{"id":297,"title":"سُقوطُ مَدينةِ القَيْروان في يَدِ البَرْبَر واسْتِشْهادُ عُقبةَ بن نافع .","date":["العام الهجري :62","العام الميلادي :681"],"text":"لمَّا أُهِينَ كُسيلَةُ البَرْبَريُّ مِن قِبَلِ أبي المُهاجِر قائدِ عُقبةَ بن نافعٍ أَضْمَرَ كُسيلَةُ الغَدْرَ، فلمَّا رأى الرُّومُ قِلَّةَ مَن مع عُقبةَ أرسلوا إلى كُسيلةَ وأَعْلَموه حالَهُ، وكان في عَسكرِ عُقبةَ مُضمِرًا للغَدْرِ، وقد أَعلَم الرُّومَ ذلك وأَطْمَعَهُم، فلمَّا راسَلوهُ أَظهَر ما كان يُضْمِرُهُ وجمَع أهلَهُ وبَنِي عَمِّهِ وقصَد عُقبةَ وانْفَصل عنه ولَحِقَ بالرُّومِ وهاجَم عُقبةَ وجماعتَهُ عند تَهُوذَةَ قُربَ جِبالِ أوراس بالجَزائِر، فكَسَر عُقبةُ والمسلمون أَجفانَ سُيوفِهم وتَقدَّموا إلى البَرْبَر وقاتَلوهُم، فقُتِلَ المسلمون جَميعُهم لم يُفْلِتْ منهم أَحَدٌ، وأُسِرَ محمَّدُ بن أَوْسٍ الأنصاريُّ في نَفَرٍ يَسيرٍ، فخَلَّصَهُم صاحبُ قَفْصَةَ وبعَث بهم إلى القَيْروان. فعزَم زُهيرُ بن قيسٍ البَلَوِيُّ على القِتالِ، فخالَفَهُ حَنَشٌ الصَّنعانيُّ وعاد إلى مِصْرَ، فتَبِعَهُ أكثرُ النَّاسِ، فاضْطَرَّ زُهيرٌ إلى العَوْدِ معهم، فسار إلى بَرْقَة وأقام بها. وأمَّا كُسيلَةُ فاجْتَمع إليه جَميعُ أهلِ أفريقيا، وقصَد أفريقيا وبها أصحابُ الأنفالِ والذَّراريّ مِن المسلمين، فطَلَبوا الأمانَ مِن كُسيلَةَ، فآمَنَهُم ودخَل القَيْروان واسْتَولى على أفريقيا، وأقام بها إلى أن اسْتَعادها المسلمون في عَهْدِ عبدِ الملك بن مَرْوان عامَ 69 هـ."},{"id":298,"title":"غَزْوُ عُقبةَ بن نافعٍ شمال أفريقيا  .","date":["العام الهجري :63","العام الميلادي :682"],"text":"قام أَميرُ أفريقيا عُقبةُ بن نافعٍ باجْتِياح المغربِ كُلِّه مِن أدناهُ إلى أقصاهُ حتَّى بلَغ ساحِلَ المُحيطِ الأطلسي."},{"id":299,"title":"فِتنَةُ عبدِ الله بن الزُّبير رضي الله عنه ضِدَّ الدَّولةِ الأُمويَّة .","date":["العام الهجري :63","العام الميلادي :682"],"text":"كان ابنُ الزُّبيرِ رضي الله عنه رافِضًا بَيْعَة يَزيدَ بن مُعاوِيَة منذ أن حاوَل مُعاوِيَةُ رضي الله عنه أَخْذَ البَيْعَة لابنِه يَزيدَ مِن ابنِ عُمَر والحُسينِ وابنِ الزُّبيرِ، وبعدَ وَفاةِ مُعاوِيَة رضي الله عنه انتقَل ابنُ الزُّبيرِ والحُسينُ بن عَلِيٍّ مِن المدينةِ إلى مكَّة, وبعدَ قَتْلِ الحُسينِ بن عَلِيٍّ رضي الله عنه خلَع عبدُ الله بن الزُّبير عامِلَ يَزيدَ في مكَّة، وقَدَّمَ بدلًا عنه مُصعَبَ بن عبدِ الرَّحمن، ثمَّ ثار النَّاسُ بالمدينةِ وطَردوا والي يَزيدَ ووَلَّوْا عليهم عبدَ الله بن حَنظَلةَ، وحاصروا بني أُمَيَّة في دارِ مَرْوان بن الحَكَمِ، ثمَّ طَردوهُم مِن المدينةِ، ولمَّا وصَل الخبرُ ليَزيدَ أرسَل إليهم جيشًا وكانت وَقعةُ الحَرَّةِ، ثمَّ تابَع الجيشُ إلى مكَّة، وتُوفِّي قائدُهم مُسلمُ بن عُقبةَ في الطَّريقِ، وتَوَلَّى بَعدَهُ الحُصَينُ بن نُميرٍ الذي حاصر مكَّة، وتُوفِّي يَزيدُ أثناءَ ذلك، فلمَّا عَلِمَ بذلك الحُصينُ طلَب مِن ابنِ الزُّبيرِ أن يَسيرَ معه للشَّامِ فيُبايِعهُ فيها؛ لكنَّ ابنَ الزُّبيرِ رفَض فرجَع جيشُ الحُصينِ، ودَعا ابنُ الزُّبيرِ لِنَفسِه بالخِلافَة، فبايَعهُ أهلُ الحِجازِ وأهلُ مِصْرَ، وأمَّا أهلُ البَصْرَة فبايعوا ابنَ زيادٍ، ثمَّ بعدَ مُدَّةٍ اجتمَعَت البَصْرَةُ والكوفَةُ لابنِ الزُّبيرِ واليَمَنُ وخُراسانُ والشَّامُ إلَّا بعضَ المناطقِ."},{"id":300,"title":"الأُمَوِيُّون يَقْتَحِمون المدينةَ النَّبوِيَّةَ (مَعركَةُ الحَرَّةِ) .","date":["العام الهجري :63","الشهر القمري : ذي الحجة","العام الميلادي :683"],"text":"لمَّا بايَع أهلُ المدينةِ لعبدِ الله بن الزُّبيرِ وخَلعوا بَيْعَة يَزيدَ وخَلعوا والِيَهُ في المدينةِ وحاصروا بني أُمَيَّة في دارِ مَرْوان أرسَل إليهم يَزيدُ جيشًا بقِيادَةِ مُسلِم بن عُقبةَ المُرِّيِّ، وكان كبيرًا مريضًا، فلمَّا وصَل المدينةَ حاصَرها مِن طَرْف الحَرَّةِ الشَّرقيَّة مِن طريقِ الكوفَة وقتَها، وأَمْهَلَهُم ثلاثةَ أيَّام لِيَخْلعوا بَيْعَة ابنِ الزُّبيرِ ويَعودوا لِبَيْعَة يَزيدَ، فأبَوْا وخَرجوا إلى الحَرَّةِ مع أَميرِهم عبدِ الله بن حَنظَلةَ الغَسِيلِ، فجَرى فيها قِتالٌ شديدٌ عنيفٌ في الحَرَّةِ، وسُمِّيَت وَقعةَ الحَرَّةِ لذلك، فقُتِلَ الكثيرُ مِن أبناءِ الصَّحابةِ في المدينةِ والأنصارِ وغيرِهم كثير، وكان مِن أَمْرِ جيشِ مُسلِم كذلك أن أباح المدينةَ للجيشِ مُدَّةَ ثلاثةَ أيَّام سَلبوا فيها ما شاءوا مِن المالِ والسِّلاحِ والطَّعامِ، وكانت وَقعةً شَديدةً عَظيمةً وفاجِعَةً مُسيئَةً، وأُكْرِهَ أهلُ المدينةِ ثانيةً على مُبايَعَةِ يَزيدَ."},{"id":301,"title":"وَفاةُ الخَليفةِ الأُمَويِّ يَزيدَ بن مُعاوِيَة .","date":["العام الهجري :64","الشهر القمري : ربيع الأول","العام الميلادي :683"],"text":"هو يَزيدُ بن مُعاوِيَة بن أبي سُفيان الأُمَويُّ القُرشيُّ الدِّمشقيُّ، وُلِدَ في 23 رمضان 26 هـ في خِلافَة عُثمان بن عفَّان رضي الله عنه في قَريةِ الماطِرُون، وأُمُّهُ مَيْسونُ بنتُ بَحْدَل الكَلْبِيَّةُ، طَلَّقَها مُعاوِيَةُ فيما بعدُ. عاش فَترةً مِن حياتِه في البادِيَةِ بين أخوالِه، تَوَلَّى الخِلافَة بعدَ وَفاةِ والدِه في سنة 60 للهِجرَةِ، ولم يُبْقِ مِن مُعارِضي تَوْلِيَتِهِ الخِلافَة غيرَ الحُسينِ بن عَلِيٍّ، وعبدِ الله بن الزُّبيرِ. حدَث في عَهدِه ثلاثةُ حوادِث في سنة 61هـ، وقَعةُ كَرْبَلاء التي قُتِلَ فيها الحُسينُ بن عَلِيٍّ رضي الله عنه بعدَ تَحريضِ شِيعَةِ العِراق له بالخُروجِ إليهم ثمَّ تَخَلّيهم عنه. والثَّاني سنة 63 هـ مُعارضَةُ عبدِ الله بن الزُّبير في الحِجاز، وما تَرَتَّب عليها مِن اسْتِباحَةِ الحَرَمِ واحْتِراقِ الكَعبَةِ. والثَّالث مُعارضَةُ أهلِ المدينةِ سنة 63 هـ على يَزيدَ وخَلْعُ بَيْعَتِه ممَّا أَدَّى إلى حِصارِ المدينةِ ثمَّ اسْتِباحَتِها في وَقعةِ الحَرَّةِ. تُوفِّي يَزيدُ بن مُعاوِيَة أثناءَ حِصارِ الجيشِ لمكَّة، وكان هو في الشَّامِ وقد كان عَهِدَ لابنِه مُعاوِيَة بن يَزيدَ بالخِلافَة مِن بَعدِه, وبعدَ وَفاةِ يَزيدَ بن مُعاوِيَة تَبايَنَت الآراءُ حول شَخْصِيَّتِه. والنَّاسُ فيه طَرَفان ووَسَطٌ، قال شيخُ الإسلامِ ابنُ تَيميةَ: \"إنَّه كان مَلِكًا مِن مُلوكِ المسلمين، له حسنات وسَيِّئات، ولم يُولد إلَّا في خِلافَة عُثمانَ، ولم يكُن كافرًا؛ ولكن جَرى بِسبَبِه ما جَرى مِن مَصرَعِ الحُسينِ، وفعَل ما فعَل بأهلِ الحَرَّةِ، ولم يكُن صاحبًا ولا مِن أوْلِياءِ الله الصَّالحين، وهذا قولُ عامَّةِ أهلِ العَقلِ والعِلْمِ والسُّنَّةِ والجَماعةِ. ثمَّ افْتَرقوا ثلاث فِرَق: فِرْقَة لَعَنَتْهُ، وفِرْقَة أَحَبَّتْهُ، وفِرْقَة لا تَسُبُّهُ ولا تُحِبُّهُ، وهذا هو المنصوصُ عن الإمامِ أحمد، وعليه المُقْتَصِدون مِن أصحابِه وغيرِهم مِن جَميعِ المسلمين."},{"id":302,"title":"احْتِراقُ الكَعبَةِ أثناءَ حِصارِ الأُمَويِّين لابنِ الزُّبيرِ .","date":["العام الهجري :64","الشهر القمري : ربيع الأول","العام الميلادي :683"],"text":"لمَّا رفَض ابنُ الزُّبيرِ البَيْعَة لِيَزيدَ بن مُعاوِيَة وكان بمكَّة المُكرَّمَة سَيَّرَ إليه يَزيدُ بن مُعاوِيَة جيشًا بقِيادَةِ مُسلمٍ؛ ولكنَّ مُسلِمًا تُوفِّي في الطَّريقِ إلى مكَّة فاسْتَلَم بعدَه الحُصينُ بن نُميرٍ فحاصَر مكَّة المُكرَّمَة، وكان ابنُ الزُّبيرِ اتَّخَذَ المسجدَ حِصْنًا له ووضَع فيه الخِيامَ لِتَحميهِ وجُنْدَهَ مِن ضَرباتِ المَنْجنيق، واسْتَمرَّ الحِصارُ إلى أن احْتَرقَت الكَعبةُ قبلَ أن يأتِيَ نَعْيُ يَزيدَ بن مُعاوِيَة بتِسْعَةٍ وعِشرين يومًا، واخْتُلِف في مَن كان سبَبًا في احْتِراقِ الكَعبةِ. كان أصحابُ ابنُ الزُّبيرِ يُوقِدون حولَ الكَعبَةِ، فأَقْبَلَت شَرَرَةٌ هَبَّتْ بها الرِّيحُ فاحْتَرَقَت كِسْوَةُ الكَعْبَةِ، واحْتَرقَ خَشَبُ البيتِ. قال أحدُ أصحابِ ابنِ الزُّبيرِ يُقالُ له عَوْنٌ: ما كان احْتِراقُ الكَعبَةِ إلَّا مِنَّا, وذلك أنَّ رجلًا مِنَّا كان هو وأصحابه يوقدون في خِصاصٍ لهم حولَ البيتِ, فأَخَذَ نارًا في رُمْحِه فيه نِفْطٌ, وكان يومَ ريحٍ, فطارت منها شَرارةٌ, فاحْتَرَقت الكَعبةُ حتَّى صارت إلى الخشبِ, وقِيلَ: إن رجلًا مِن أهلِ الشَّام لمَّا جنَّ اللَّيلُ وضَع شَمْعَةً في طَرْف رُمْحِه, ثمَّ ضرَب فَرَسه ثمَّ طعَن الفُسْطاطَ فالْتَهب نارًا, والكَعبةُ يَومئذٍ مُؤَزَّرَة بالطَّنافِس, وعلى أَعْلاها الحَبِرَةُ, فطارت الرِّيحُ باللَّهَبِ على الكعبةِ فاحْتَرَقت. فلم يكُن حَرْقُ الكَعبةِ مَقصودًا مِن أَحَدِ الطَّرَفينِ؛ بل إنَّ احْتِراقَها جاء نَتيجةً لِحَريقِ الخِيامِ المُحيطةِ بها مع اشْتِدادِ الرِّيحِ, فهذا رجلٌ مِن أهلِ الشَّام لمَّا احْتَرَقت الكَعبةُ نادى على ضِفَّةِ زَمْزَم بقوله: هلَكَ الفَريقانِ والذي نَفْسِ محمَّدٍ بِيَدِهِ."},{"id":303,"title":"مُعاوِيَةُ بن يَزيدَ يَتَوَلَّى الخِلافَة ثمَّ يَترُكها شُورى للمسلمين  .","date":["العام الهجري :64","الشهر القمري : ذي القعدة","العام الميلادي :684"],"text":"بعدَ أن تُوفِّي يَزيدُ وكان قد عَهِدَ بالخِلافَة لابنِه مُعاوِيَة، وكان شَابًّا مَريضًا، وكان ناسِكًا صالِحًا مُتَعبِّدًا لم تَدُمْ خِلافتُه بالنَّاس سِوى اليَسيرِ، ولم يُرِدْ الخِلافَةَ وقد عَلِمَ أنَّه ليس لها بأهلٍ، واعْتَزَل النَّاسَ وقال: إنَّه لم يَجِدْ للنَّاس مَن يَخلُفُه كما خَلَّفَ أبو بكرٍ للنَّاس عُمَرَ بن الخطَّاب، ولا وجَد في النَّاسِ سِتَّةً مِن أهلِ الشُّورى يكون الأمرُ بينهم كما وجَد عُمَرُ بن الخطَّاب للنَّاس أهلَ الشُّورى، فترَك الأمرَ للنَّاس يَختارون مَن شاءوا، واعْتَزَلهم حتَّى تُوفِّي."},{"id":304,"title":"تَوَلِّي ابنِ الزُّبيرِ الخِلافَة بعدَ مُعاوِيَة بن يَزيدَ  .","date":["العام الهجري :64","الشهر القمري : ذي القعدة","العام الميلادي :684"],"text":"لمَّا مات يَزيدُ بن مُعاوِيَة أَقْلَع جَيشُه عن مكَّة، وهم الذين كانوا يُحاصِرون ابنَ الزُّبيرِ وهو عائِذٌ بالبيتِ، فلمَّا رجَع حُصينُ بن نُميرٍ السَّكونيُّ بالجيشِ إلى الشَّام بعدَ أن عرَض الحُصينُ على ابنِ الزُّبيرِ أن يُبايِعَه بالخِلافَة شَرْطَ أن يَأتِيَ معهم للشَّامِ؛ لكنَّ ابنَ الزُّبيرِ رفَض الذِّهابَ إلى الشَّام, كان يَزيدُ قد أَوْصى بالخِلافَة لابنِه مُعاوِيَة؛ لكنَّه لم يكُن راغِبًا فيها فترَكَها وجعَلَها شُورى للمسلمين. اسْتَفْحَل أَمْرُ ابنِ الزُّبير بالحِجازِ وما والاها، وبايَعَهُ النَّاسُ في العِراق وما يَتْبَعُه إلى أقصى مَشارِق دِيارِ الإسلامِ، وفي مِصْرَ وما يَتْبَعُها إلى أقصى بِلادِ المغربِ، وبايَعَت الشَّامُ أيضًا إلَّا بعضَ جِهاتٍ منها، ففي دِمشقَ بايَع الضَّحَّاكُ بن قيسٍ الفِهرىُّ لابنِ الزُّبيرِ، وفي حِمْص بايَع النُّعمانُ بن بَشيرٍ، وفي قِنَّسْرين زُفَرُ بن الحارثِ الكِلابيُّ، وفي فِلَسْطين بايَع ناتِلُ بن قيسٍ، وأَخرَج منها رَوْحَ بن زِنْباع الجُذاميَّ، ولم يكُن رافضًا بَيْعَة ابنِ الزُّبيرِ في الشَّام إلَّا مِنطقةُ البَلْقاءِ وفيها حَسَّان بن مالكِ بن بَحْدَل الكَلبيُّ. وقد كان الْتَفَّ على عبدِ الله بن الزُّبيرِ جَماعةٌ مِن الخَوارِج يُدافِعون عنه، منهم نافعُ بن الأزرقِ، وعبدُ الله بن إباض، وجَماعةٌ مِن رُؤوسهم, فلمَّا اسْتَقَرَّ أَمْرهُ في الخِلافَة قالوا فيما بينهم: إنَّكم قد أَخْطأتُم لأنَّكم قاتَلتُم مع هذا الرَّجُلِ ولم تَعْلَموا رَأيَه في عُثمان بن عفَّان -وكانوا يَنْتَقِصون عُثمانَ- فاجْتَمَعوا إليه فسألوه عن عُثمانَ فأجابهم فيه بما يَسُوؤهُم، فعند ذلك نَفَرُوا عنه وفارقوه وقَصَدوا بِلادَ العِراق وخُراسان، فتَفَرَّقوا فيها. صَرَّح العديدُ مِن العُلماءِ والمُؤَرِّخِين بأنَّ بَيْعَة ابنِ الزُّبير بَيْعَة شَرْعِيَّةٌ، وأنَّه أَوْلى بها مِن مَرْوان بن الحكمِ, فيَروِي ابنُ عبدِ البَرِّ، عن مالكٍ أنَّه قال: إنَّ ابنَ الزُّبيرِ كان أفضل مِن مَرْوان وكان أَوْلى بالأمرِ منه، ومِن ابنِه عبدِ المَلِك. ويقولُ ابنُ كثيرٍ عن ابنِ الزُّبيرِ: ثمَّ كان هو الإمام بعدَ مَوتِ مُعاوِيَة بن يَزيدَ لا مَحالَة، وهو أَرْشَدُ مِن مَرْوان بن الحكمِ، حيث نازَعَهُ بعدَ أن اجْتَمَعت الكَلِمَةُ عليه، وقامَت البَيْعَة له في الآفاقِ، وانْتَظَم له الأمرُ، والله أعلم."},{"id":305,"title":"إِعادَةُ بِناءِ الكَعبَةِ على قَواعِد إبراهيمَ على يَدِ عبدِ الله بن الزُّبيرِ رضي الله عنه .","date":["العام الهجري :64","الشهر القمري : ذي القعدة","العام الميلادي :684"],"text":"لمَّا احْتَرَقت الكَعبةُ حين غَزا أهلُ الشَّامِ عبدَ الله بن الزُّبير أيَّام يَزيدَ تَرَكها ابنُ الزُّبير يُشَنِّع بذلك على أهلِ الشَّام، فلمَّا مات يَزيدُ واسْتَقَرَّ الأمرُ لابنِ الزُّبير شرَع في بِنائِها، فأَمَر بِهَدْمِها حتَّى أُلْحِقَت بالأرضِ، وكانت قد مالت حيطانُها مِن حِجارَةِ المَنْجنيقِ، وجَعَل الحَجَرَ الأسودَ عنده، وكان النَّاسُ يَطوفون مِن وراءِ الأساسِ، وضرَب عليها السُّورَ وأدخل فيها الحِجْرَ، واحْتَجَّ بأنَّ رسولَ الله صلَّى الله عليه وسلَّم قال لعائشةَ: (لولا حَدَثانُ عَهْدِ قَومِك بالكُفْرِ لرَدَدْتُ الكَعبةَ على أساسِ إبراهيمَ، وأَزيدُ فيها الحِجْرَ). فحفَر ابنُ الزُّبير فوجَد أساسًا أمثال الجِمالِ، فحَرَّكوا منها صَخرةً فبَرِقَت بارِقَة، فقال: أَقِرُّوها على أساسِها وبِنائِها، وجعَل لها بابَيْنِ يُدْخَل مِن أحدِهما ويُخْرَج مِن الآخر."},{"id":306,"title":"مَرْوانُ بن الحكمِ يَتَوَلَّى أُمورَ الخِلافَة الأُمويَّة .","date":["العام الهجري :64","الشهر القمري : ذي الحجة","العام الميلادي :684"],"text":"لمَّا بُويِعَ لابنِ الزُّبير بالخِلافَة، وقَدِمَ الحُصينُ بن نُميرٍ ومَن معه إلى الشَّام أَخْبَرَ مَرْوانَ بما كان بينه وبين ابنِ الزُّبير، وقال له ولِبَنِي أُمَيَّة: نَراكُم في اخْتِلاطٍ فأقيموا أَميرَكُم قبلَ أن يَدخُلَ عليكم شامَكُم، فتكون فِتنَة عَمْياء صَمَّاء. وكان مِن رَأْيِ مَرْوان أن يَسيرَ إلى ابنِ الزُّبير فيُبايِعهُ بالخِلافَة، فقَدِمَ ابنُ زيادٍ مِن العِراق وبَلغَهُ ما يَريدُ مَرْوانُ أن يَفعلَ، فقال له: قد اسْتَحْيَيْتُ لك مِن ذلك، أنت كبيرُ قُريشٍ وسَيِّدُها تَمضي إلى أبي خُبَيبٍ فتُبايِعهُ -يعني ابنَ الزُّبير- فقال: ما فات شيءٌ بعدُ. فقام معه بنو أُمَيَّة ومواليهم وتَجمَّع إليه أهلُ اليَمنِ فسار إلى دِمشقَ وهو يقول: ما فات شيءٌ بعدُ، فقَدِمَ دِمشقَ وجَهَّزَ جُيوشًا لِيُثَبِّتوا له البَيْعَة فثَبَّتَ حُكْمَهُ بالشَّامِ, ثمَّ أرسَل جيشًا آخرَ للعِراق لِيأخُذ له البَيْعَة. ولكن لم تَدُمْ مُدَّةُ حُكمِه طويلًا، فقد تُوفِّي بعدَ تِسعَة أَشْهُر."},{"id":307,"title":"وَقعةُ مَرْج راهِط بين مروان بن الحكم والضحاك بن قيس .","date":["العام الهجري :64","الشهر القمري : ذي الحجة","العام الميلادي :684"],"text":"لمَّا بايَع النَّاسُ مَرْوانَ سار مِن الجابِيَة إلى مَرْج راهِط قريبا من دمشق وبها الضَّحَّاك بن قيسٍ ومعه ألفُ فارسٍ، وكان قد اسْتَمَدَّ الضَّحَّاكُ النُّعمانَ بن بَشيرٍ وهو على حِمْص فأَمَدَّهُ حَبيبَ بن ذي الكِلاعِ، واسْتَمَدَّ أيضًا زُفَرَ بن الحارثِ وهو على قِنَّسْرين فأَمَدَّهُ بأهلِ قِنَّسْرين، وأَمَدَّهُ ناتِل بأهلِ فِلَسْطين، فاجتمعوا عنده، واجتمع على مَرْوان كَلْبٌ وغَسَّانُ, والسَّكاسِك والسَّكون، وتَحارَب مَرْوانُ والضَّحَّاكُ بمَرْج راهِط عِشرين ليلةً، واقْتَتَلوا قِتالًا شَديدًا، فقُتِلَ الضَّحَّاكُ، قَتلَهُ دِحْيَةُ بن عبدِ الله، وقُتِلَ معه ثمانون رجلًا مِن أشرافِ أهلِ الشَّام، وقُتِلَ أهلُ الشَّام مَقتلَةً عَظيمةً، وقُتِلَت قَيسٌ مَقتلةً لم يُقْتَلُ مِثلُها في مَوطِن قَطُّ، وكان فيمَن قُتِلَ هانىءُ بن قَبيصةَ النُّمَيْريُّ سَيِّدُ قومِه، كان مع الضَّحَّاك، قَتلَهُ وازِعُ بن ذُؤالَة الكَلبيُّ، ولمَّا انْهزَم النَّاسُ مِن المَرْج لَحِقوا بأَجنادِهِم، فانتهى أهلُ حِمْص إليها وعليها النُّعمانُ بن بَشيرٍ، فلمَّا بَلغَهُ الخَبرُ خرَج هَربًا ليلًا ومعه امرأتُه نائِلةُ بنتُ عُمارةَ الكَلبيَّة وثَقَلُهُ وأوَّلادُه، فتَحَيَّرَ لَيلَتَهُ كُلَّها، وأصبَح أهلُ حِمْص فطلبوه، وكان الذي طَلبَهُ عَمرُو بن الجَلِيِّ الكَلاعيُّ، فقَتلَهُ ورَدَّ أهلَه والرَّأسَ معه، وجاءَت كَلْبٌ مِن أهلِ حِمْص فأخذوا نائِلةَ وولدَها معها، ولمَّا بَلغَت الهَزيمةُ زُفَرَ بن الحارثِ الكِلابيَّ بقِنَّسْرين هرَب منها فلَحِقَ بقَرْقِيسِيا وعليها عِياضٌ الحَرَشِيُّ، وكان يَزيدُ وَلَّاهُ إيَّاها، وهرَب ناتِلُ بن قيسٍ الجُذاميُّ عن فِلَسْطين فلَحِقَ بابنِ الزُّبيرِ بمكَّة، واسْتَعمَل مَرْوانُ بعده على فِلَسْطين رومَ بن زِنْباع، واسْتَوْثَق الشَّامُ لمَرْوان واسْتَعمَل عُمَّالَه عليها."},{"id":308,"title":"ضَمُّ مَرْوان بن الحكمِ أرضَ مِصْرَ إلى خلافته .","date":["العام الهجري :64","الشهر القمري : ذي الحجة","العام الميلادي :684"],"text":"لمَّا اسْتَقَرَّ الشَّامُ لمَرْوان بن الحكمِ سار إلى مِصْرَ, فقَدِمَها وعليها عبدُ الرَّحمن بن جَحْدَم القُرشيُّ يَدعو إلى ابنِ الزُّبير، فخرَج إلى مَرْوان فيمَن معه، وبعَث مَرْوانُ عَمرَو بن سعيدٍ مِن وَرائِه حتَّى دخَل مِصْرَ، فقِيلَ لابنِ جَحْدَم ذلك، فرجَع وبايَع النَّاسُ مَرْوانَ ورجَع إلى دِمشقَ."},{"id":309,"title":"مَقْتَلُ نافعِ بن الأزرقِ (زَعيمُ طائفة الأزارِقَة) .","date":["العام الهجري :65","الشهر القمري : جمادى الآخرة","العام الميلادي :685"],"text":"هو نافعُ بن الأزرقِ مِن بَنِي حَنيفةَ زَعيمُ الأزارِقَة، المشهور بمُساءَلة ابنِ عبَّاس, وممَّا يُذكَر عن ابتداءِ ظُهورهِ أنَّه اجْتَمع بالخَوارِج الذين يَرون رَأيَه وطلَب إليهم أن يَنضمُّوا إلى ابنِ الزُّبيرِ لمُقاتَلةِ جُيوشِ أهلِ الشَّام الذين حاصروا مكَّة، قائلًا لهم مِن خُطبةٍ له: وقد جَرَّدَ فيكم السُّيوفَ أهلُ الظُّلْمِ، وأوَّلوا العَداءَ والغَشْمَ، وهذا مَن ثار بمكَّة، فاخْرُجوا بِنَا نَأْتِ البيتَ ونَلْقَ هذا الرَّجُل، فإن يكُن على رَأْيِنا جاهَدْنا معه العَدُوَّ، وإن يكُن على غيرِ رَأْيِنا دافَعْنا عن البيتِ ما اسْتَطعنا، ونَظَرْنا بعدَ ذلك في أُمورِنا. فأطاعوهُ وخرَجوا إلى مكَّة، وقاتَلو مع ابنِ الزُّبير جيشَ الشَّام, ثمَّ امْتَحنوا ابنَ الزُّبير، ولمَّا تَبَيَّنَ لهم خِلافُه لِرَأْيِهم خرَجوا عنه سنة 64هـ، فخرَجوا مِن مكَّة إلى جِهتَيْنِ: جِهَةٍ إلى البَصْرَة، أَمَّروا عليهم نافعَ بن الأزرق, وجِهَةٍ إلى اليَمامَةِ ووَلَّوْا عليهم أبا طالوت، ثمَّ خَلَعوه ووَلَّوْا عليهم نَجْدَةَ بن عامرٍ. أقام نافعُ بن الأزرق بالبَصْرَة إلى أن خَشِيَ مِن أهلِها، فخرَج إلى الأهوازِ وتَبِعَهُ أتباعُه إلى هناك. وقد اسْتَقَرَّ الأمرُ بنافعٍ ومَن معه في الأهواز، فغَلَبوا عليها و على كَوْرِها وما وَراءَها مِن بُلدانِ فارِسَ وكِرْمان في أيَّام عبدِ الله بن الزُّبير، وقَتَلوا عُمَّاله بهذه النَّواحِي، إلى أن قُتِلَ نافعٌ عندما اشْتَدَّت المعركةُ بينه وبين جيشِ أهلِ البَصْرَة بقِيادَةِ مُسلِم بن عُبيسِ بن كُرَيزِ بن ربَيْعَة في ناحِيَة الأهوازِ الذي جَهَّزَهُ عامِلُ البَصْرَة مِن قِبَلِ عبدِ الله بن الزُّبير عبدُ الله بن الحارثِ الخُزاعيُّ."},{"id":310,"title":"عبدُ المَلِك بن مَرْوان يَتَوَلَّى الخِلافَة الأُمويَّة .","date":["العام الهجري :65","الشهر القمري : رمضان","العام الميلادي :685"],"text":"لمَّا غلَب مَرْوانُ بن الحكمِ على الشَّام وما حَولَها عَهِدَ بالخِلافَة لابْنَيْهِ عبدِ المَلِك ثمَّ مِن بعدِه عبدِ العزيزِ، فاسْتلَم عبدُ الملك زِمامَ الأُمورِ التي كانت بِيَدِ والدِه ولكن لم تَتِمَّ له الأمورُ كُلُّها؛ لأنَّ بعضَ المناطقِ ما زالت تَدينُ بالخِلافَة لابنِ الزُّبير."},{"id":311,"title":"وَفاةُ عبدِ الله بن عَمرِو بن العاصِ رضِي الله عنه .","date":["العام الهجري :65","الشهر القمري : ذي الحجة","العام الميلادي :685"],"text":"هو أحدُ المُكْثِرين في الرِّاويةِ عن النَّبِيِّ صلَّى الله عليه وسلَّم، أَسلَم قبلَ أبيهِ، وكان فاضِلًا عالِمًا، قَرَأَ القُرآنَ والكُتُبَ المُتَقدِّمة، واسْتأذَنَ النَّبِيَّ صلَّى الله عليه وسلَّم في أن يَكتُبَ عنه، فأَذِنَ له، شَهِدَ صِفِّينَ مع مُعاوِيَة طاعةً لوالِدِه، إذ كان النَّبِيُّ صلَّى الله عليه وسلَّم قال له: (أَطِعْ أباكَ). اخْتُلِف كثيرًا في زمنِ وَفاتِه ومَكانِ وَفاتِه، وذلك للاختلافِ في عُمُرهِ يومَ وَفاتِه."},{"id":312,"title":"حرَكةُ المُختارِ الثَّقَفيِّ .","date":["العام الهجري :66","العام الميلادي :685"],"text":"هو المُختارُ بن أبي عُبيدٍ الثَّقفيُّ، وكان في الكوفَة، وكان يَدعو إلى إمامةِ المَهْدِيِّ محمَّدِ بن عَلِيٍّ المعروف بابنِ الحَنَفِيَّةِ، فسارت وَراءَهُ جَماعةٌ منها جَماعةٌ كانت مع سُليمان بن صُرَدٍ رضي الله عنه، الذين لَقَّبُوا أَنفُسَهم بالتَّوَّابِينَ، لِيُكَفِّرُوا عن خُذْلانِهم للحُسينِ بن عَلِيٍّ رضي الله عنه في كَرْبَلاء, ولكنَّ ابنَ الحَنفيَّة لم يكُن يَعلَم بأَمرِهِم فضلًا عن أن يَرْضى بِفعلِهم."},{"id":313,"title":"عبدُ الملك بن مَرْوان يبدأ ببِناءِ قُبَّةِ الصَّخرَةِ في بيتِ المَقْدِس .","date":["العام الهجري :66","العام الميلادي :685"],"text":"بدَأ عبدُ الملك بن مَرْوان في بِناءِ مَسجِد قُبَّةِ الصَّخرَةِ في بيتِ المَقْدِس. وقِيلَ: إنَّ عبدَ الملك بن مَرْوان حين قَرَّرَ بِناءَ قُبَّةٍ عالِيَةٍ تُغَطِّي الصَّخرَةَ رصَد لِبِنائِها خَراجَ مِصْرَ لِسَبْعِ سِنين، وحين أُنْفِقَت هذه الأموالُ على البِناءِ بَقِيَ منها مائةُ ألفِ دِينارٍ، فأَمَر عبدُ الملك بن مَرْوان أن يُصْنَعَ بها صَفائِح ذَهَبيَّة تُكْسَى بها القُبَّةُ مِن الخارجِ."},{"id":314,"title":"مَقْتَلُ المُختارِ الثَّقفيِّ .","date":["العام الهجري :67","الشهر القمري : رمضان","العام الميلادي :687"],"text":"بدَأ المُختارُ بن أبي عُبيدٍ الثَّقفيُّ بالدَّعوَةِ لابنِ الحَنَفيَّة ظاهرًا؛ ولكنَّه تَبَيَّنَ أنَّه يدعو لِنَفسِه، فقد كَوَّنَ حوله جيشًا قاتَل فيه عُبيدَ الله بن زيادٍ، وكان المُختارُ يُصانِع ابنَ الزُّبير حينًا لِيَتَقَوَّى به على جُيوشِ عبدِ الملك بن مَرْوان، وحصلت مَعركةٌ بين جَيشِه وجَيشِ الشَّام عند نَهْرِ الحازر، قُتِلَ فيها ابنُ زيادٍ، والحُصينُ بن نُميرٍ، وشُرَحْبيل بن زيادٍ، ثمَّ حصل اقْتِتال بين المُختارِ وبين مُصعَبِ بن الزُّبير، والْتَقى الطَرَفان وهُزِمَ المُختارُ وتَراجَع إلى الكوفَةِ، وقُتِلَ فيها وانْتَهت فِتْنَتُه بذلك."},{"id":315,"title":"وَفاةُ عبدِ الله بن عبَّاس رضِي الله عنهما .","date":["العام الهجري :68","العام الميلادي :687"],"text":"هو حَبْرُ الأُمَّةِ، وهو أحدُ المُكْثِرين مِن الرِّوايَةِ عن النَّبِيِّ صلَّى الله عليه وسلَّم، شَهِدَ مع عَلِيٍّ الجَملَ وصِفِّينَ، وكان والِيًا له على الكوفَة، كُفَّ بَصَرُهُ في آخِرِ عُمُرهِ، وكان في مكَّة ثمَّ انْتَقل إلى الطَّائِف، وتُوفِّي فيها وهو ابنُ واحدٍ وسبعين سنة، ودُفِنَ فيها."},{"id":316,"title":"عِصْيانُ الجَراجِمَة بالشَّام .","date":["العام الهجري :69","العام الميلادي :688"],"text":"لمَّا امْتَنع عَمرُو بن سعيدِ بن العاصِ على عبدِ الملك خرَج أيضًا قائدٌ مِن قُوَّادِ الضَّواحي في جبلِ اللُّكَّامِ وتَبِعَهُ خَلْقٌ كثيرٌ مِن الجَراجِمَة (نسبة لقبيلة جرجم)، والأَنباطِ (مجموعة من العرب ينتمون إلى نبط بن ‘سماعيل)، وآباقِ عَبيدِ المسلمين، وغَيرِهم، ثمَّ سار إلى لُبنان، فلمَّا فرَغ عبدُ الملك مِن عَمرِو بن سعيدِ أَرسَل إلى هذا الخارِج فبَذَل له كُلَّ جُمُعةٍ ألفَ دِينارٍ، فرَكَن إلى ذلك ولم يُفسِد في البِلادِ، ثمَّ وضَع عليه عبدُ الملك سُحيمَ بن المُهاجِر، فتَلَطَّفَ حتَّى وصَل إليه مُتَنَكِّرًا فأظهَر له مُمالأتَه وذَمَّ عبدَ الملك وشَتَمَه ووَعَدهُ أن يَدُلَّهُ على عَوْراتِه، وما هو خيرٌ له مِن الصُّلْح. فوَثِقَ به. ثمَّ إنَّ سُحيمًا عَطَفَ عليه وعلى أَصحابِه وهم غَارُون غافِلون بجيشٍ مع مَوالي عبدِ الملك وبَنِي أُمَيَّة وجُنْدٍ مِن ثِقاتِ جُنْدِهِ وشُجْعانِهم كان أَعَدَّهم بمكانٍ خَفِيٍّ قريبٍ وأَمَر فنُودِي: مَن أتانا مِن العَبيدِ -يعني الذين كانوا معه- فقَتَل الخارِجَ ومَن أعانَهُ مِن الرُّومِ، وقُتِلَ نَفَرٌ مِن الجَراجِمَة والأنباط، ونادَى المُنادِي بالأمانِ فيمَن لَقِيَ منهم، فتَفَرَّقوا في قُراهُم، وسُدَّ الخَلَلُ، وعاد سُحيمُ بن المُهاجِر إلى عبدِ الملك، ووَفَّى للعَبيدِ."},{"id":317,"title":"وَقعةُ ممش قريبًا مِن القَيْروان وانْتِصارُ المسلمين .","date":["العام الهجري :69","العام الميلادي :688"],"text":"عَيَّنَ عبدُ الملك بن مَرْوان زُهيرَ بن قيسٍ أَميرًا على أفريقيا، وأَمَدَّهُ بالمالِ والرِّجالِ لِيَتَوَجَّهَ بجيشٍ إلى القَيْروان لاسْتِردادِها، حيث كانت مع الرُّومِ فاسْتَولوا عليها مع كُسَيلةَ البَرْبَريِّ، والْتَقى الطَّرَفان في مَوقِع ممش قُرْبَ القَيْروان، وحصل القِتالُ وانْتَصر زُهيرٌ وقَتَلَ كُسيلَةَ ثمَّ عاد إلى بَرْقَة، فكانت الرُّومُ قد أغارَت عليه بِحَمْلَةٍ بَحْريَّةٍ فقاتَلهُم وكان فيها مَصرعُه رحمه الله."},{"id":318,"title":"انْقِلابُ عَمرِو بن سعيدٍ على عبدِ الملك بن مَرْوان\n  .","date":["العام الهجري :69","العام الميلادي :688"],"text":"أقام عبدُ الملك بن مَرْوان بدِمشقَ بعدَ رُجوعِه مِن قِنَّسْرين ما شاء الله أن يُقيمَ، ثمَّ سار يُريدُ قَرْقِيسِيا وبها زُفَرُ بن الحارثِ الكِلابيُّ، وكان عَمرُو بن سعيدٍ مع عبدِ الملك، فلمَّا بلَغ بُطْنانَ حَبيبٍ رجَع عَمرٌو ليلًا ومعه حُميدُ بن حُرَيثٍ الكَلبيُّ، وزُهيرُ بن الأَبْرَدِ الكَلبيُّ، فأَتى دِمشقَ وعليها عبدُ الرَّحمن بن أُمِّ الحكمِ الثَّقفيُّ قد اسْتَخلَفَهُ عبدُ الملكِ، فلمَّا بَلغهُ رُجوعُ عَمرِو بن سعيدٍ هرَب عنها، ودَخلَها عَمرٌو فغَلَب عليها وعلى خَزائِنِه، وهَدَم دارَ ابنِ أُمِّ الحكمِ، واجتمع النَّاسُ إليه فخَطَبهم ونَهاهُم ووَعَدهُم، فأصبح عبدُ الملكِ وقد فَقَدَ عَمرًا، فسَألَ عنه فأُخْبِرَ خَبرُه، فرجَع إلى دِمشقَ فقاتَلهُ أيَّامًا، وكان عَمرٌو إذا أُخْرِج حُميدُ بن حُرَيثٍ على الخيلِ أَخرَج إليه عبدُ الملك سُفيانَ بن الأَبْرَدِ الكَلبيَّ، وإذا أُخْرِج عَمرٌو زُهيرُ بن الأبردِ أَخرَج إليه عبدُ الملك حسَّانَ بن مالكِ بن بَحْدَل. ثمَّ إنَّ عبدَ الملك وعَمرًا اصْطَلحا وكَتَبا بينهما كِتابًا وآمَنَهُ عبدُ الملك، فخرَج عَمرٌو في الخيلِ إلى عبدِ الملك فأَقبَل حتَّى أَوْطَأ فَرَسَهُ أَطْنابَ عبدِ الملكِ فانْقَطَعت وسَقَط السُّرادِق، ثمَّ دخَل على عبدِ الملك فاجْتَمَعا، ودخَل عبدُ الملك دِمشقَ يومَ الخميسِ، فلمَّا كان بعدَ دُخولِ عبدِ الملك بأربعةِ أيَّام أَرسَل إلى عَمرٍو: أنِ ائْتِنِي. فلمَّا كان العِشاءُ لَبِسَ عَمرٌو دِرْعًا ولَبِسَ عليها القُباءَ وتَقَلَّدَ سَيْفَهُ، ودخل عَمرٌو فرَحَّبَ به عبدُ الملك فأَجْلَسَهُ معه على السَّريرِ وجعَل يُحادِثُه طَويلًا، ثمَّ أَوْثَقَهُ وأَمَر بِقَتلِه، ثمَّ تَوَلَّى قَتْلَهُ بِنَفسِه فذَبَحهُ."},{"id":319,"title":"مَقتَلُ مُصعَبِ بن الزُّبير .","date":["العام الهجري :71","الشهر القمري : جمادى الآخرة","العام الميلادي :690"],"text":"لمَّا تَمَكَّنَ عبدُ الملك مِن الشَّام أراد أن يَضُمَّ لها العِراقَ، وقد قِيلَ: إن أَهلَها كاتَبوا عبدَ الملك لِيَسيرَ إليهم، وكانت العِراقُ مع ابنِ الزُّبير وواليها مُصعَبُ أَخوهُ، فسار إليه بِنَفسِه فلمَّا عَلِمَ مُصعبٌ بذلك سار إليه ومعه إبراهيمُ بن الأَشْتَرِ، وكان على المَوصِل والجزيرةِ، فلمَّا حضَر عنده جَعلَه على مُقدِّمَتِه وسار حتَّى نزل باجُمَيرَى، وهي قريبٌ مِن أَوانا، وهي مِن مَسْكِن، فعَسْكَرَ هناك، وسار عبدُ الملك وعلى مُقدِّمتِه أخوه محمَّدُ بن مَرْوان، وخالدُ بن عبدِ الله بن خالدِ بن أُسَيْدٍ، فلمَّا تَدانَى العَسْكرانِ أَرسَل عبدُ الملك إلى مُصعَبٍ رجلًا مِن كَلْبٍ وقال له: أَقْرِئْ ابنَ أُختِك السَّلامَ -وكانت أُمُّ مُصعَبٍ كَلبيَّةً- وقُلْ له يَدَعُ دُعاءَهُ إلى أَخيهِ، وأَدَعُ دُعائي إلى نَفْسي، ويَجْعَل الأمرَ شُورى. فقال له مُصعَبٌ: قُلْ له السَّيفَ بيننا. فقَدَّمَ عبدُ الملك أخاهُ محمَّدًا، وقَدَّمَ مُصعَبٌ إبراهيمَ بن الأشْتَرِ، فالْتَقيا فتَناوَش الفَريقانِ فقُتِلَ صاحِبُ لِواءِ محمَّدٍ، وجعَل مُصعَبٌ يَمُدُّ إبراهيمَ، فأزال محمَّدًا عن مَوقِفِه، فوَجَّهَ عبدُ الملك عبدَ الله بن يَزيدَ إلى أخيهِ محمَّدٍ، فاشْتَدَّ القِتالُ، فقُتِلَ مُسلِم بن عَمرٍو الباهليُّ والدُ قُتيبَة، وهو مِن أصحابِ مُصعَبٍ، وتَقَدَّمَ أهلُ الشَّام فقاتَلهم مُصعَبٌ ثمَّ عرَض عبدُ الملك الأمانَ على مُصعَبٍ فأَبَى وبَقِيَ يُقاتِلُهم، ثمَّ إنَّ كثيرًا خَذلوا مُصعبًا، وقِيلَ: لم يَبْقَ معه سِوى أربعةٍ، وكَثُرَت الجِراحاتُ بمُصْعَب فضَرَبهُ رجلٌ -يُقالُ له: عبيدُ الله بن زيادِ بن ظِبْيان التَّميميُّ- فقَتلَهُ وحمَل رَأسَهُ إلى عبدِ الملك."},{"id":320,"title":"وَقعَةٌ عَظيمةٌ بين المُهَلَّب بن أبي صفرة والخَوارِج .","date":["العام الهجري :72","العام الميلادي :691"],"text":"كان المُهَلَّب يُحارِب الأزارِقَة، فجَعلَهُ عبدُ المَلِك بن مَرْوان على خَراجِ الأهوازِ ومَعونَتِها، وسَيَّرَ أخاهُ عبدَ العزيز بن عبدِ الله إلى قَتْلِ الخَوارِج، وسَيَّرَ معه مُقاتِلَ بن مِسْمَع، فخَرَجا يَطلُبان الأزارِقَة، فأتت الخَوارِج مِن ناحِيَة كِرْمان إلى دارِ أبجرد، فأَرسَل قَطَرِيُّ بن الفُجاءَةِ المازنيُّ مع صالحِ بن مُخارِق تسعَمائة فارِسٍ، فأقبلَ يَسيرُ بهم حتَّى اسْتَقْبَل عبدَ العزيز وهو يَسيرُ مَهْلًا على غيرِ تَعْبِيَةٍ، فانْهزَم بالنَّاسِ، ونزَل مُقاتِلُ بن مِسْمَع فقاتَل حتَّى قُتِلَ، وانْهزَم عبدُ العزيز إلى رامَهُرْمُز، فأمَرَ عبدُ الملك أن يَسيرَ إليهم المُهَلَّبُ، وكتَبَ إلى بِشْرِ بن مَرْوان أن يَنْفُذَ له خمسةُ آلافِ رجلٍ، وجاءت الأزارِقةُ إلى الأهوازِ، وسار خالدٌ والمُهَلَّبُ وغيرُهم إليهم، وبقوا عِشرين ليلةً ثمَّ زَحَف خالدٌ إليهم بالنَّاسِ، فرأوا أَمْرًا هالَهُم مِن كَثْرَةِ النَّاسِ، فكَثُرَتْ عليهم الخَيْلُ وزَحَفت إليهم، فانْصَرفوا كأنَّهم على حامِيَةٍ وهُم مُوَلُّون لا يَرَوْن طاقةً بِقَتْلِ جَماعةِ النَّاسِ. فأَرسَل خالدٌ داودَ بن قَحْذم في آثارِهم، وانْصَرف خالدٌ إلى البَصْرَة، وسار عبدُ الرَّحمن إلى الرَّيِّ، وأقام المُهَلَّبُ بالأهوازِ، وكتَب خالدٌ إلى عبدِ الملك بذلك، وبعَث بِشْرٌ عَتَّابَ بن وَرْقاء في أربعةِ آلافِ فارِسٍ مِن أهلِ الكوفَةِ، فساروا حتَّى لَحِقوا داودَ فاجتمعوا، ثمَّ اتَّبَعوا الخَوارِجَ حتَّى هَلَكَتْ خُيولُ عامَّتِهم وأصابَهُم الجوعُ والجُهْدُ، ورجَع عامَّةُ الجَيْشَيْنِ مُشاةً إلى الأهوازِ."},{"id":321,"title":"عبدُ الملك بن مَرْوان يُسَيطِر على العِراق .","date":["العام الهجري :72","العام الميلادي :691"],"text":"تَمَّ ذلك لِعبدِ الملك بن مَرْوان بعدَ أن قَتَلَ مُصعَبَ بن الزُّبير ومَن معه، فانْتَهى بذلك حُكمُ عبدِ الله بن الزُّبير على العِراق، وانْضَمَّت لِعبدِ الملك ووَلَّاها خالدَ بن عبدِ الله القَسْرِيَّ."},{"id":322,"title":"مَقْتَلُ ابنِ الزُّبير رضي الله عنه بعد أن حاصره الحجاج بن يوسف .","date":["العام الهجري :72","الشهر القمري : ذي الحجة","العام الميلادي :692"],"text":"سَيَّرَ عبدُ الملك بن مَرْوان الحَجَّاج بن يوسُف الثَّقفيَّ إلى عبدِ الله بن الزُّبير رضي الله عنه، وبعَث معه له أمانًا إنْ هو أطاعَ، فبَقِيَ الحَجَّاج مُدَّةً في الطَّائفِ يَبعَثُ البُعوثَ تُقاتِل ابنَ الزُّبير وتَظْفَرُ عليه. فكتَب الحَجَّاجُ إلى عبدِ الملك يُخبِرُه: بأنَّ ابنَ الزُّبير قد كَلَّ وتَفَرَّق عنه أَصحابُه, ويَسْتَأذِنُه بمُحاصَرةِ الحَرَمِ ثمَّ دُخولِ مكَّة، فأَمَدَّهُ عبدُ الملك بطارِقِ الذي كان يُحاصِر المدينةَ، ولمَّا حَصَرَ الحَجَّاجُ ابنَ الزُّبير نَصَبَ المَنْجَنيقَ على أبي قُبَيْسٍ ورَمَى به الكَعبةَ، وكان عبدُ الملك يُنْكِر ذلك أيَّامَ يَزيدَ بن مُعاوِيَة، ثمَّ أَمَرَ به، وحَجَّ ابنُ عُمَرَ رضِي الله عنهما تلك السَّنةَ فأَرسَل إلى الحَجَّاجِ: أنِ اتَّقِ الله، واكْفُفْ هذه الحِجارةَ عن النَّاسِ؛ فإنَّك في شَهْرٍ حَرامٍ وبَلَدٍ حَرامٍ، وقد قَدِمَت وُفودُ الله مِن أَقطارِ الأرضِ لِيُؤَدُّوا فَريضةَ الله ويَزْدادوا خيرًا، وإنَّ المَنْجنيق قد منعهم عن الطَّوافِ، فاكْفُفْ عن الرَّمْيِ حتَّى يَقْضوا ما يجب عليهم بمكَّة. فبَطَّلَ الرَّمْيَ حتَّى عاد النَّاسُ مِن عَرَفات وطافوا وسَعَوْا، ولم يَمْنَعْ ابنُ الزُّبير الحاجَّ مِن الطَّوافِ والسَّعْيِ، فلمَّا فرَغوا مِن طَوافِ الزَّيارةِ نادَى مُنادِي الحَجَّاجِ: انْصَرِفوا إلى بِلادِكم، فإنَّا نَعودُ بالحِجارَةِ على ابنِ الزُّبيرِ المُلْحِدِ. فأصاب النَّاسَ بعد ذلك مَجاعةٌ شديدةٌ بسَببِ الحِصارِ، فلمَّا كان قُبَيْلَ مَقْتَلِه تَفَرَّقَ النَّاسُ عنه، وخَرجوا إلى الحَجَّاجِ بالأمانِ، خرَج مِن عنده نحو عشرةِ آلاف، وكان ممَّن فارَقَه ابْناهُ حَمزةُ وخُبيبٌ، وأَخَذا لِأَنْفُسِهما أَمانًا، فقال عبدُ الله لابْنِه الزُّبيرِ: خُذْ لِنَفسِك أمانًا كما فعل أَخَواك، فَوَالله إنِّي لأُحِبُّ بَقاءَكُم. فقال: ما كنتُ لِأَرْغَبَ بِنَفسِي عنك. فصَبَر معه فقُتِلَ وقاتَلهم قِتالًا شديدًا، فتَعاوَرُوا عليه فقَتَلوهُ يومَ الثُلاثاءِ مِن جُمادَى الآخِرة وله ثلاثٌ وسبعون سَنةً، وتَوَلَّى قَتْلَهُ رجلٌ مِن مُرادٍ، وحمَل رَأسَهُ إلى الحَجَّاج، وبعَث الحَجَّاجُ بِرَأسِه، ورَأسِ عبدِ الله بن صَفوان، ورَأسِ عُمارةَ بن عَمرِو بن حَزْمٍ إلى المدينةِ، ثمَّ ذهَب بها إلى عبدِ الملك بن مَرْوان، وأخَذ جُثَّتَهُ فصَلَبَها على الثَّنِيَّةِ اليُمْنَى بالحُجُونِ، ثمَّ بعدَ أن أَنْزَلَهُ الحَجَّاجُ عن الخَشبةِ بعَث به إلى أُمِّه، فغَسَّلَتْهُ، فلمَّا أَصابَهُ الماءَ تَقَطَّعَ، فغَسَّلَتْهُ عُضْوًا عُضْوًا فاسْتَمْسَك، وصلَّى عليه أخوه عُروةُ، فَدَفَنَتْهُ."},{"id":323,"title":"الانْتِهاءُ مِن بِناءِ مَسجِد قُبَّةِ الصَّخرَةِ .","date":["العام الهجري :73","العام الميلادي :692"],"text":"في هذه السَّنةِ انْتُهِيَ مِن بِناءِ مَسجِد قُبَّةِ الصَّخرَةِ في بيتِ المَقْدِس والذي كان عبدُ الملك قد أمر به في سَنةِ 66 هـ."},{"id":324,"title":"وَفاةُ أسماءَ بنتِ أبي بكرٍ الصِّدِّيق رضِي الله عنهما .","date":["العام الهجري :73","العام الميلادي :692"],"text":"هي ذاتُ النِّطاقَيْنِ، وهي زَوجةُ الزُّبير، ووالدةُ عبدِ الله بن الزُّبير، وكانت قد شَهِدَت اليَرْموك مع زَوجِها وابْنِها، بَقِيَت في مكَّة بعدَ أن طَلَّقَها الزُّبيرُ في عَهْدِ عُثمان بن عفَّان، وكانت قد عَمِيَت رضي الله عنها وبَلَغت المائةَ سَنةٍ مِن عُمُرِها، وخَبرُها مع الحَجَّاج مشهور بشأنِ ابْنِها عبدِ الله، وقد تُوفِّيت بعدَ مَقْتَلِ ابْنِها بِشَهرين، وكانت مِن آخرِ المُهاجِرات موتًا، فرضِي الله عنها وعن أَبِيها وابْنِها."},{"id":325,"title":"ثَورةُ الخَوارِج في البَحْرَين .","date":["العام الهجري :73","العام الميلادي :692"],"text":"في عَهدِ عبدِ الملك بن مَرْوان ثار الخَوارِجُ في البَحرينِ بزَعامَةِ عبدِ الله بن قيسٍ المعروف بأبي فُدَيْكِ, وأَخرَجَهم منها المُغيرةُ بن المُهَلَّب بن أبي صُفْرَة بعدَ مَعركةٍ قُتِلَ فيها أبو فُدَيكٍ."},{"id":326,"title":"وَفاةُ عبدِ الله بن الزُّبير .","date":["العام الهجري :73","الشهر القمري : جمادى الآخرة","العام الميلادي :692"],"text":"هو أميرُ المؤمنين عبدُ اللهِ بنُ الزُّبَير بنِ العوَّام بن خُوَيلد بن أسد بن عبد العُزَّى بن قُصَي بن كلِاب بن مُرَّة: أبو بكر، وأبو خُبَيب القرشيُّ الأَسديُّ المكيُّ، ثم المدنيُّ, أحد الأعلام، كان عبدُ الله أول مولودٍ للمهاجرين بالمدينةِ, وُلِدَ سنة اثنتين، وقيل: السنة الأولى من  الهجرة, ولَمَّا بلغ سبع سنين جاء ليبايِعَ النبيَّ صلَّى الله عليه وسلَّم، فتبسَّم النبيُّ صلى الله عليه وسلم حين رآه مُقبِلًا، ثم بايَعَه. له رواية أحاديثَ، وهو من صِغار الصَّحابة، وإن كان كبيرًا في العِلمِ والشَّرفِ والجهادِ والعبادةِ، وقد روى عن أبيه وجَدِّه لأمه الصِّدِّيق، وأمِّه أسماءَ، وخالتِه عائشةَ، وعن عُمَر وعُثمان، وغيرِهم، وحدث عنه: أخوه عُروةُ الفقيهُ، وابناه: عامرٌ وعَبَّاد، وابنُ أخيه: محمد بن عروة، وكان فارسَ قُريشٍ في زمانه، وله مواقِفُ مشهودة. أدرك ابنُ الزبير من حياةِ رسول الله صلى الله عليه وسلم ثمانيةَ أعوام وأربعة أشهر, وكان ملازمًا لبيت رسول الله؛ لكونِه من آله، فكان يتردَّدُ إلى بيت خالته عائشةَ, وفي يوم اليرموك أركب الزبيرُ وَلَده عبد الله فرسًا وهو ابن عشر سنين، ووكل به رجلًا، شَهِدَ يوم الجمَلِ مع خالته، كما شهد فتح المغرب، وغزوَ القُسطنطينية. كان معاوية رضي الله عنه في عهدِه إذا لقي ابنَ الزبير يقول: مرحبًا بابنِ عَمَّةِ رسول الله صلى الله عليه وسلم، وابنِ حواريِّ رسولِ الله، لما توفي يزيدُ بويعُ ابنُ الزبير بالخِلافةِ سنة 64هـ، فحكم الحِجازَ واليمن ومصر والعراق وخراسان، وبعضَ الشام، ولم يستوسق له الأمر، ومن ثم لم يَعُدَّه بعض العلماء في أمراء المؤمنين، وعَدَّ دولتَه زمَنَ فُرقة، فإنَّ مروان غلب على الشامِ ثم مصر، وقام بعد مَصرَعِه ابنُه عبد الملك بن مروان، وحاربَ ابنَ الزُّبير، فلم يزَلْ يحاربه حتى ظَفِر به, فأخذ العراقَ، ثم أرسل الحجَّاجَ إلى مكة وأخذها مِن ابن الزبير بعد أن خذله من كان معه خِذلانًا شديدًا، وجعلوا يتسلَّلون إلى الحَجَّاج، وجعل الحجَّاج يَصيح: أيها الناسُ, علامَ تقتُلون أنفُسَكم? من خرج إلينا فهو آمِنٌ, لكم عهدُ الله وميثاقُه، ورَبِّ هذه البِنيةِ لا أغدِرُ بكم، ولا حاجةَ في دمائكم. قتله الحجَّاجُ ثم صَلَبه، وكان آدم نحيفًا, ليس بالطويلِ, بين عينيه أثرُ السجود, فغسَّلَتْه والدته أسماءُ بنت أبي بكر بعد ما تقَطَّعت أوصاله، فحنَّطَتْه وكفَّنَتْه، وصَلَّت عليه، وجعلت فيه شيئًا حين رأته يتفسَّخُ إذا مسَّتْه, ثم حملته فدفنته بالمدينة في دار صفيةَ أم المؤمنين. قال عروة بن الزبير: لم يكن أحدٌ أحَبَّ إلى عائشة بعد رسول الله من أبي بكرٍ، وبعدَه ابنُ الزبير، وإذا ذُكِرَ ابن الزبير عند ابن عباس، قال: (قارئٌ لكتاب الله, عفيفٌ في الإسلام, أبوه الزُّبَير، وأمُّه أسماء، وجَدُّه أبو بكر، وعَمَّته خديجةُ، وخالته عائشةُ، وجدَّتُه صفية)، وكان عمرُو بن دينار يقول: (ما رأيت مُصليًّا قطُّ أحسَنَ صلاةً من عبد الله بن الزبير، وكان يسمى حمامةَ المسجِدِ)."},{"id":327,"title":"الحَجَّاجُ بن يوسُف يُعيدُ بِناءَ الكَعبةِ إلى ما كانت عليه في عَهدِ قُريش .","date":["العام الهجري :74","العام الميلادي :693"],"text":"كان عبدُ الله بن الزُّبير أعاد بِناءَ الكَعبةِ بعدَ أن تَخَرَّبَت في الحِصارِ الأوَّل الذي قادهُ الحُصينُ بن نُميرٍ مِن قِبَلِ يَزيدَ بن مُعاوِيَة على قَواعِدها القديمة، وجعَل لها بَابَيْنِ كما وصَف النَّبِيُّ صلَّى الله عليه وسلَّم، ثمَّ عادَت وتَضَرَّرت الكَعبةُ في الحِصارِ الثَّاني الذي قادهُ الحَجَّاجُ بن يوسُف الذي اسْتَعمل كذلك المَنْجنيقَ، ممَّا أَدَّى إلى هَدْمِ أَجزاءٍ مِن الكَعبةِ، وبعدَ أن قَتَلَ الحَجَّاجُ ابنَ الزُّبير وسَيْطَر على مكَّة كتَب إلى الخليفةِ عبدِ الملك بن مَرْوان: أنَّ ابنَ الزُّبير قد زاد في البيتِ ما ليس فيهِ، وقد أَحدَث فيه بابًا آخرَ، فأمَرَ عبدُ الملك بن مَرْوان الحَجَّاجَ بن يوسُف أن يُعيدَ بِناءَ الكَعبةِ إلى ما كانت عليه في عَهدِ قُريشٍ، وذلك لِعَدمِ عِلْمِ عبدِ الملك بحَديثِ عائشةَ رضي الله عنها في رَغْبَةِ النَّبِيِّ صلَّى الله عليه وسلَّم في إعادةِ بِناءِ الكَعبةِ على قَواعِد إبراهيمَ, فهَدَم الحَجَّاجُ منها سِتَّةَ أَذْرُع وبَناها على أساسِ قُريشٍ، وسَدَّ البابَ الغَربيَّ وسَدَّ ما تحت عَتَبَةِ البابِ الشَّرقيِّ لارتفاعِ أربعةِ أَذْرُع، ووضَع مِصْراعانِ يُغْلِقان البابَ."},{"id":328,"title":"وَفاةُ عبدِ الله بن عُمَر رضِي الله عنهما .","date":["العام الهجري :74","العام الميلادي :693"],"text":"هو أبو عبدِ الرَّحمن عبدُ الله بن عُمَر بن الخَطَّاب العَدَويُّ القُرشيُّ المَكِّيُّ ثمَّ المَدنيُّ، صَحابيٌّ جَليلٌ، وابنُ ثاني خُلفاءِ المُسلمين عُمَر بن الخَطَّاب، وعالِمٌ مِن عُلماءِ الصَّحابةِ، لُقِّبَ بِشَيخِ الصَّحابةِ رضي الله عنه، أَسْلَمَ قَديمًا مع أَبيهِ ولم يَبلُغ الحُلُمَ، وهاجَرا وعُمُرُهُ عشرُ سِنين، وقد اسْتُصْغِر يومَ أُحُدٍ، فلمَّا كان يومُ الخَندقِ أَجازَهُ وهو ابنُ خمسَ عشرةَ سَنة فشَهِدَها وما بعدها، وهو شَقيقُ حَفصةَ بنتِ عُمَر أُمِّ المؤمنين، أُمُّهُما زينبُ بنتُ مَظْعون أُختُ عُثمان بن مَظْعون، وكان عبدُ الله بن عُمَر رِبْعَةً مِن الرِّجال، آدَمَ له جُمَّةٌ تَضرِب إلى مَنْكِبَيْهِ، جَسِيمًا, وهو أَحدُ المُكْثِرين في الرِّوايَةِ عن الرَّسولِ صلَّى الله عليه وسلَّم، عُرِضَتْ عليه الخِلافَةُ بعدَ مَوتِ يَزيدَ بن مُعاوِيَة فأبى ذلك حتَّى لا يُقْتَلَ بِسَبَبِه أَحدٌ تَوَجَّهَ للمَدينةِ بعدَ الحَرَّةِ وبَقِيَ فيها إلى مَقْدَمِ الحَجَّاج. كان عبدُ الله بن عُمَر حَريصًا كُلَّ الحِرْصِ على أن يَفْعَلَ ما كان الرَّسولُ صلَّى الله عليه وسلَّم يَفعلُه، فيُصَلِّي في ذاتِ المكانِ، ويَدعو قائمًا كالرَّسولِ الكريمِ صلَّى الله عليه وسلَّم، وكان صاحِبَ عِبادَةٍ منذ صِغَرِهِ، وكان ينامُ في المَسجِد. قال عنه صلَّى الله عليه وسلَّم: (نِعْمَ الرَّجلُ عبدُ الله، لو كان يُصَلِّي مِن اللَّيلِ). فصار لا ينامُ مِن اللَّيلِ إلَّا قليلًا إلى أن مات، وكان إذا صلَّى مِن اللَّيلِ، قال لِمَولاهُ نافع: أَسْحَرْنا؟ -يعني: هل دَخَلْنا في وَقتِ السَّحَرِ- فيقول: لا. ثمَّ يُصلِّي، فيقولُ: أَسْحَرْنا؟ حتَّى يقولُ: نعم. فيُوتِرُ، هكذا يُصلِّي سائِرَ اللَّيلِ، وكان يُغْفِي إغْفاءةَ الطَّائرِ، ينامُ نَوْمَةً يَسيرةً. تُوفِّي بمكَّة وهو ابنُ أربعٍ وثمانين سَنَة، وكان ابنُ عُمَر يُسابِق الحَجَّاجَ في الحَجِّ إلى الأماكنِ التي يَعلَم أنَّ رسولَ الله يَسْلُكُها، فَعَزَّ ذلك على الحَجَّاجِ، وكان ابنُ عُمَر قد أَوْصى أن يُدْفَنَ في اللَّيلِ، فلم يُقدَرْ على ذلك مِن أجلِ الحَجَّاج, ودُفِنَ بذي طُوى في مَقْبَرةِ المُهاجِرين، وصلَّى عليه الحَجَّاجُ نَفسُه، فرضِي الله عن ابنِ عُمَر وأَرضاهُ وجَزاهُ عن الإسلامِ والمسلمين خيرًا."},{"id":329,"title":"وَفاةُ جابرِ بن عبدِ الله رضِي الله عنه .","date":["العام الهجري :74","العام الميلادي :693"],"text":"هو جابرُ بن عبدِ الله بن حَرامٍ الأنصاريُّ، أَحدُ المُكْثِرين في الرِّوايةِ عن النَّبِيِّ صلَّى الله عليه وسلَّم، شَهِدَ العَقَبَة الثَّانيَة مع أَبيهِ، فكان آخرَ مَن تُوفِّي في المدينةِ مِن أَصحابِ العَقَبَة، عَمِيَ في آخرِ عُمُرهِ، لم يَسْتَطِع أن يَشْهَدَ بدرًا ولا أُحُدًا، فلمَّا اسْتُشْهِد أبوهُ في أُحُدٍ لم يَتَخلَّفْ بعدها عن مَشهَدٍ بعدَ ذلك، تُوفِّي في المدينةِ سَنَة أربعٍ وسبعين، وقِيلَ: سبع وسبعين. وقِيلَ غيرَ ذلك، وصلَّى عليه أَبانُ بن عُثمان، وكان أميرَ المدينةِ، وكان عُمُرهُ أربعًا وتِسعين سَنَة."},{"id":330,"title":"فَتْحُ حَسَّان بن النُّعمان الغَسَّانيِّ قَرْطاجَنَّة .","date":["العام الهجري :74","العام الميلادي :693"],"text":"لمَّا قُتِلَ ابنُ الزُّبير واجتَمَع المسلمون على عبدِ الملك بن مَرْوان جَهَّزَ جيشًا كبيرًا واستَعْمل عليهم وعلى أفريقيا حسَّانَ بن النُّعمان الغَسَّانيَّ وسَيَّرَهُم إليها، فلم يَدخُلْ أفريقيا قَطُّ جَيشٌ مِثلُه، فلمَّا وَرَدَ القَيْروان تَجَهَّزَ منها وسار إلى قَرْطاجَنَّة، وكان صاحبُها أعظمَ مُلوكِ أفريقيا، ولم يكُن المسلمون قَطُّ حارَبوها، فلمَّا وصَل إليها رأى بها مِن الرُّومِ والبَرْبَر مالا يُحْصَى كَثْرةً، فقَتَلهم وحَصَرهُم، وقَتَلَ منهم كثيرًا، فلمَّا رأوا ذلك اجتَمَع رأيُهم على الهَربِ، فرَكِبُوا في مَراكِبِهم وسار بعضُهم إلى صِقِلِّيَّة، وبعضُهم إلى الأندلُس، ودخَلَها حَسَّانُ بالسَّيفِ فسَبَى ونَهَبَ وقَتَلَهم قَتلًا ذَريعًا، وأَرسَل الجُيوشَ فيما حَولَها، فأَسرَعوا إليه خَوفًا، فأَمَرَهم فهَدَموا مِن قَرْطاجَنَّة ما قَدَروا عليه، ثمَّ بَلَغَهُ أنَّ الرُّومَ والبَرْبَر قد أجمعوا له في شَطْفُورَة وبَنْزَرْت، وهما مَدِينتان، فسار إليهم وقاتَلَهم ولَقِيَ منهم شِدَّةً وقُوَّةً، فصَبَر لهم المسلمون، فانْهَزَمت الرُّومُ، وكَثُرَ القَتْلُ فيهم، واسْتَولوا على بِلادِهم، ولم يَترُكْ حَسَّانُ مَوضِعًا مِن بِلادِهِم إلَّا وَطِئَهُ، وخافَهُ أهلُ أفريقيا خَوفًا شَديدًا، ولجأ المُنْهَزِمون مِن الرُّومِ إلى مَدينةِ باجَة فتَحَصَّنوا بها، وتَحَصَّن البَرْبَر بمدينةِ بُونَة، فعاد حَسَّانُ إلى القَيْروان لأنَّ الجِراحَ قد كَثُرَت في أصحابِه، فأقام بها حتَّى صَحُّوا. وبعدَ ضَرْبِ الرُّومِ الْتَفَت حَسَّانُ إلى زَعامَةِ البَرْبَر، فقال: دُلُّونِي على أَعظمِ مَن بَقِيَ مِن مُلوكِ أفريقيا؟ فدَلُّوه على امْرأةٍ تَملِكُ البَرْبَر وتُعرَف بالكاهِنَة، والْتَقى حَسَّانُ بن النُّعمان بالكاهِنَة عند نَهْرٍ يُدْعَى نِينِي أو مِسْكِيانَة على مَرحلَةٍ مِن باغاي ومَجَّانَة، فانْتَصَرت الكاهِنَةُ وقُتِلَ مِن المسلمين خَلْقٌ كثيرٌ، وانْسَحَب حَسَّانُ إلى قابِس. وقامت الكاهِنَةُ بالهَيْمَنَةِ على المغربِ كُلِّهِ بعدَ حَسَّان، وقالت: إنَّ العربَ إنَّما يَطلُبون مِن أفريقيا المدائنَ والذَّهَبَ والفِضَّةَ، ونحن إنَّما نُريدُ منها المَزارِعَ والمَراعي، فلا نَرى لكم إلَّا خَرابَ بِلادِ أفريقيا كُلِّها. حتَّى ييأسَ منها العربُ فلا يكونُ لهم رُجوعٌ إليها إلى آخِر الدَّهْرِ, واسْتَجاب لها قَومُها مِن جُراوَة الذين كان يَغْلُب عليهم الطَّابعُ البَدَويُّ، فذهبوا إلى كُلِّ ناحِيَة يَقطَعون الشَّجرَ، ويَهدِمون الحُصونَ, فكانت أفريقيا مِن طرابلس إلى طَنْجَة ظِلًّا وقُرَىً مُتَّصِلة فأَخْرَجت جَميعَ ذلك، وقد أَضَرَّ هذا التَّخريبُ بالبرانس والأفارِقةِ حتَّى أَلجأَهُم إلى الفِرارِ وطَلَبِ المُساعدَةِ، وخرَج يَومئذٍ مِن النَّصارى والأفارِقة خَلْقٌ كثيرٌ مُسْتَغِيثين ممَّا نزَل بهم مِن الكاهِنَة، فيتَفَرَّقوا على الأندلُس وسائرِ الجُزُرِ البَحْريَّة, ومَلَكَت الكاهِنَةُ أفريقيا، وأَساءَت السِّيرةَ في أَهلِها وظَلَمَتْهُم."},{"id":331,"title":"الحَجَّاجُ بن يوسُف يَحكُم العِراقَ  .","date":["العام الهجري :75","العام الميلادي :694"],"text":"حَكَم الحَجَّاجُ بن يوسُف بعدَ أن قَضى على ابنِ الزُّبيرِ، حَكَم الحِجازَ كُلَّها ثمَّ وَلَّاهُ عبدُ الملك أَمْرَ العِراق بدلًا مِن خالدِ بن عبدِ الله القَسْريِّ، فصارت العِراق للحَجَّاج، وخُطْبَتُهُ فيها مشهورة، فأَمْسَك زِمامَ الأُمورِ فيها بِشِدَّةٍ فدانَتْ له وخَضَعت."},{"id":332,"title":"إجْلاء الخَوارِج عن رامَهُرْمُز وقَتْل عبدِ الرَّحمن بن مخنف\n  .","date":["العام الهجري :75","الشهر القمري : رمضان","العام الميلادي :695"],"text":"بعَث الحَجَّاجُ كِتابًا إلى المُهَلَّب وعبدِ الرَّحمن بن مِخْنَف يأمرُهما بِمُناهَضة الخَوارِج، فزَحَفوا إليهم وقاتلوهم شيئًا مِن قِتالٍ، فانْهَزمت الخَوارِج كأنَّهم على حامِيَة، ولم يكُن منهم قِتالٌ، وساروا حتَّى نَزلوا كازَرُون، وسار المُهَلَّبُ وابنُ مِخْنَف حتَّى نزلوا بهم، وخَنْدَقَ المُهَلَّبُ على نَفسِه، وقال لابن مِخْنَف: إن رأيتَ أن تُخَنْدِقَ عليك فافْعَل. فقال أصحابُه: نحن خَنْدَقْنا سُيوفَنا, فأتى الخَوارِجُ المُهَلَّبَ لِيُبَيِّتُوه فوجدوه قد تَحَرَّزَ، فمالوا نحو ابن مِخْنَف فوجدوه لم يُخَنْدِق فقاتلوه فانهزم عنه أصحابُه، فنزَل فقاتَل في أُناسٍ مِن أصحابِه, فقُتِلَ وقُتِلوا حوله كُلُّهم."},{"id":333,"title":"ضَرْبُ العُمْلَة الإسلامِيَّة .","date":["العام الهجري :76","العام الميلادي :695"],"text":"وكان سَبَب ضَرْبها أنَّ عبدَ الملك بن مَرْوان كتَب في صُدورِ الكُتُبِ إلى الرُّوم: \"قل هو الله أحد\" وذَكَر النَّبِيَّ صلَّى الله عليه وسلَّم، مع التَّاريخ، فكَتَب إليه مَلِكُ الرُّوم: إنَّكم قد أَحْدَثْتُم كذا وكذا، فاتركوه وإلَّا أتاكُم في دَنانيرنا مِن ذِكْرِنا نَبِيَّكم ما تَكرهُون. فعَظُم ذلك عليه. فأحضر خالدَ بن يَزيدَ بن مُعاوِيَة فاسْتَشارهُ فيه، فقال: حَرِّمْ دَنانيرَهُم واضْرِب للنَّاس سِكَّةً فيها ذِكْر الله تعالى. فضَرَب الدَّنانيرَ والدَّراهِمَ. ثمَّ إنَّ الحَجَّاج ضَرَب الدَّراهِم ونَقَش فيها: \"قل هو الله أحد\" فكَرِهَ النَّاسُ ذلك لِمَكان القُرآن؛ لأنَّ الجُنُبَ والحائضَ يَمَسُّها، ونَهى أن يَضرِب أحدٌ غيرُه."},{"id":334,"title":"اسْتِعادَة البَرْبَر قَرْطاجَنَّة مِن المسلمين .","date":["العام الهجري :76","العام الميلادي :695"],"text":"كانت هناك في جِبال أُوراس كاهِنَة مُطاعَة مِن قِبَل البَرْبَر فانْطَلق إليها حسَّانُ بن النُّعمان لِقِتالِها، وحَصَل قِتالٌ شديدٌ هُزِمَ فيه المسلمون، ووَصَل الخبرُ لعبدِ الملك فأَمَر بالانتظار حتَّى يأتيهم الأمرُ؛ ولكنَّ الرُّوم لمَّا عَلِموا بالأمرِ ساروا بأُسْطُولِهم إلى قَرْطاجَنَّة بإمْرَةِ البَطْريق يُوحَنَّا فتَمكَّن مِن دُخولِها وقسا على المسلمين ممَّا اضْطَرَّهم للهُروب للقُرى المُجاورة."},{"id":335,"title":"ثَورة الخَوارِج في طَبَرِستان بقِيادَة قَطَريِّ بن الفُجاءَة .","date":["العام الهجري :77","العام الميلادي :696"],"text":"ثار الخَوارِجُ في طَبَرِستان بِزَعامَة قَطَريِّ بن الفُجاءَة فأَرسَل الحَجَّاجُ جَيْشًا بقِيادَة سُفيان بن الأبردِ فقاتَلهُ, فانْفَضَّ عنه أصحابُه وسَقَطَ في شِعْبٍ مِن الشِّعابِ فاغْتالهُ عِلْجٌ مِن أهلِ طَبَرِستان وأَرسَل رأسَه إلى الحَجَّاج."},{"id":336,"title":"الأُمَوِيُّون يُخْمِدون فِتنَة شَبيب بن يَزيد الخارجي بالعِراق .","date":["العام الهجري :77","العام الميلادي :696"],"text":"كَثُرَت فِتَنُ الخَوارِج والحُروب معهم وازداد أمرُهم قُوَّةً، فقد بايعوا لِشَبيب بن يَزيد بعدَ صالِح بن مُسَرِّحٍ، وكان شَبيب قد هَزَمَ جيشَ الحَجَّاج ثمَّ هَرَب شَبيب إلى المدائن وقَوِيَ أمرُه حتَّى سار إليه الحَجَّاجُ بِنَفسِه كما سَيَّرَ عبدُ الملك جيشًا مِن الشَّام إليه والتَقى الطَّرفان في مَقتلةٍ عظيمة قُتِلَ فيها الكثيرُ مِن أصحابِ شَبيب، ممَّا اضْطَرَّهُ للهُروب إلى ناحِيَة جِسْرٍ على نهرِ دُجَيْل بالأهواز، فكَبا جَوادُ شَبيب فسَقَطَ في النَّهرِ وغَرِقَ مِن كَثرَةِ الحَديدِ عليه، فكانت هذه بِمَثابَةِ إخْماد فِتْنَتِهِم في العِراق."},{"id":337,"title":"فَتْح المسلمين إرْقِيلِيَّة في بلاد الروم .","date":["العام الهجري :78","العام الميلادي :697"],"text":"كانت هذه الغَزوة مِن أَعظَم الغَنائم للمسلمين ببِلاد الرُّوم حيث افْتَتحوا إرْقِيليَّة، وكان الجيش أثناء رُجوعِهم أصابَهم مَطَرٌ عظيمٌ وثَلْجٌ وبَرْدٌ، فأُصِيبَ بِسَببِه ناسٌ كثيرٌ."},{"id":338,"title":"اسْتِعادَة البِيزنطيِّين قَرْطاجَنَّة (جنوب شرق أسبانيا) .","date":["العام الهجري :78","العام الميلادي :697"],"text":"كان لِسُقوط قَرْطاجَنَّة بِيَدِ المسلمين أثرٌ بالغٌ على البِيزنطيِّين، ووجدوا في خُروج حسَّان مِن أفريقيا بعدَ هَزيمتِه على يَدِ الكاهنة مَلِكَة البَرْبَر والفَوضى التي عَمَّت البلادَ بِسَبب سِياسَة الكاهنة التَّخريبيَّة مَجالًا لِإعادَة نُفوذِهم في الشَّمال الإفريقي، فجَهَّز الإمبراطور لِيونتوس الذي خَلَفَ جستنيان الثاني حَملةً كبيرةً بِقيادة البَطْريق يُوحَنَّا إلى أفريقيا وأَعَدَّ أُسطولًا كبيرًا لِنَقْل الجُنْد إليها، فتَمَكَّنَت القُوَّة البِيزنطيَّة مِن اسْتِعادَة قَرْطاجَنَّة، دون مُقاوَمة، واضْطَرَّ أبو صالح نائبُ حسَّان عليها أن يَنسحِب منها مع مَن كان معه مِن المسلمين، ودَخَلها البَطريقُ يُوحَنَّا, وأقام حسَّان في مِنطقَة طرابلس قُرْبَ سُرْت في المكان المُسَمَّى قُصور حسَّان خمسَ سِنين."},{"id":339,"title":"الحَجَّاج يرسل جيشا إلى مَلِك التُّرْك لِتَمَرُّدِه بِعَدم دَفْع الجِزْية .","date":["العام الهجري :79","العام الميلادي :698"],"text":"أَرْسَل الحَجَّاجُ إلى رتبيل مَلِك التُّرْك جيشًا بِقِيادة والي سجستان عُبيد الله بن أبي بَكْرة، وأَمَره أن يَتوغَّل في بلاد رتبيل وأن يَدُكَّ حُصونَهم وقِلاعَهم، تأديبًا لترتبيل لتَمَرُّدِه بِعَدم دَفْع الجِزْية أحيانًا، أو اسْتِغلال اضْطِرابات المسلمين، فتَمَكَّن عُبيد الله مِن هَزيمة رتبيل واجْتِياح بِلادِه وغَنِمَ غنائمَ كثيرة؛ ولكنَّ رتبيل أَخَذ في التَّقَهْقُر فأَطْمَع المسلمين في اللِّحاق به حتَّى وصلوا قريبًا مِن مَدينتِه العُظمى، عند ذاك بدأ التُّرْك يُغْلِقون على المسلمين الطُّرُق والشِّعاب وحَصروهُم وقُتِلَ عامَّة جَيْش المسلمين، وقُتِلَ عُبيد الله بن أبي بَكْرة."},{"id":340,"title":"نِهايَة الوُجود البِيزنطي في شَمال أفريقيا .","date":["العام الهجري :81","العام الميلادي :700"],"text":"بعدَ أن هُزِمَ المسلمون أمامَ البَرْبَر وتَسَلَّط البِيزنطيُّون على قَرْطاجَنَّة بَقِيَ حَسَّان بن النُّعمان في قُصور حَسَّان حتَّى أتاهُ المَدَدُ مِن عبدِ الملك وأَمَرَهُ بالتَّحَرُّك، فتَحَرَّك حَسَّان إلى الكاهِنَة ومَن معها فتَقابَلوا في قابِس وتَغَلَّب عليها حَسَّان وتَمَّ سَيْرُه إلى باقي أنحاءِ أفريقيا."},{"id":341,"title":"بِناء مَدينَة تُونُس الإسلامِيَّة في شَمالِ أفريقيا .","date":["العام الهجري :81","العام الميلادي :700"],"text":"قام الأميرُ حَسَّان بن النُّعمان بِبِناء مَدينَة تُونُس وبَنَى بها الجامِعَ المعروف بجامِع الزَّيْتُونة، كما أنشأ دارًا لِصِناعَة الأساطيل، فكانت أوَّل قاعِدَة حَربِيَّة في المَغرِب، كما قام بِتَدوِين الدَّواوِين، وضَرب الدَّنانِير والدَّراهِم العَربِيَّة."},{"id":342,"title":"وَفاة مُحمَّد بن الحَنَفِيَّة .","date":["العام الهجري :81","الشهر القمري : صفر","العام الميلادي :700"],"text":"هو محمَّد بن عَلِيٍّ بن أبي طالِب، أُمُّهُ خَوْلَةُ بِنتُ جَعفَر مِن بني حَنِيفَة مِن سَبْيِ اليَمامَة، نُسِبَ إليها تَمييزًا له عن أَخَوَيْهِ الحسن والحُسين وَلَدَي فاطِمَة رضي الله عنهم أجمعين، كانت الشِّيعَة في زَمانِه تَتَغالى فيه، وتَدَّعِي إمامَتَه، وأوَّل مَن دَعا إلى ذلك المُخْتار الثَّقَفِيُّ، ولَقَّبُوه بالمَهْدِيِّ، ويَزعُمون أنَّه لم يَمُت، كان أحدَ الأبطال الشُّجْعان، وكان كثيرَ العِلْم والوَرَع، تُوفِّي في المدينة ودُفِنَ في البَقيع كما قال وَلدُه عبدُ الله، وله خَمْسٌ وسُتُّون سَنَة."},{"id":343,"title":"بِدايَة فِتنَة عبدِ الرَّحمن بن الأشعث  .","date":["العام الهجري :81","الشهر القمري : ذي الحجة","العام الميلادي :701"],"text":"لمَّا بُعِثَ عبدُ الرَّحمن بن محمَّد بن الأشعث على الجيشِ إلى بِلادِ رتبيل فدَخَلها وأَخَذ منها الغَنائِمَ والحُصونَ كَتَب إلى الحَجَّاج يُعَرِّفُه ذلك، وأنَّ رَأْيَه أن يَتْرُكوا التَّوَغُّلَ في بِلادِ رتبيل حتَّى يَعرِفوا طَريقَها ويَجْبُوا خَراجَها، فكَتَب إليه الحَجَّاجُ أن يَتَوَغَّلَ ويَسْتَمِرَّ في الحَربِ؛ ولكنَّ ذلك لم يَرُق لِعبدِ الرَّحمن، فحَرَّضَ النَّاسَ وبَيَّنَ لهم خُطورَة التَّوَغُّلِ، وأنَّ الحَجَّاج إنَّما يُريد أن يُقاتِلَ بِهِما مهما كانت النَّتائِج، فَرَضوا بِقَوْلِ ابنِ الأشعثِ وثاروا معه ضِدَّ الحَجَّاجِ، فصَالَح رتبيل على أنَّه إن اسْتَطاع أن يُزيلَ الحَجَّاج فليس على رتبيل شيءٌ مِن الخَراجِ، وإن هُزِمَ فعليه مَنْعُه، فسار ابنُ الأشعث بالجُنودِ الذين معه مُقْبِلًا مِن سجستان إلى الحَجَّاج لِيُقاتِلَه ويَأخُذ منه العِراقَ."},{"id":344,"title":"وَقْعَة الزَّاوِيَة بين أهلِ الشَّامِ وابنِ الأشعث .","date":["العام الهجري :82","العام الميلادي :701"],"text":"لمَّا سَمِعَ الحَجَّاجُ بِتَمَرُّدِ ابنِ الأشعث جَهَّزَ جُيوشًا وطَلَب مِن عبدِ الملك إمْدادَه فكان ذلك، ثمَّ الْتَقى الطَّرَفان في تُسْتَر واقْتَتَلوا قِتالًا شَديدًا فهَزَمَهُم ابنُ الأشعث ودَخَل البَصْرَةَ فبايَعَهُ أهلُها، وكان ذلك في ذي الحجَّة، ثمَّ في أواخر مُحَرَّم حصَل قِتالٌ شديدٌ آخر انْهزَم فيه أيضًا أصحابُ الحَجَّاج، فحمَل سُفيانُ بن الأبرد الكَلْبِيُّ على المَيْمَنَةِ التي لِعبدِ الرَّحمن فهَزَمها، وانْهزَم أهلُ العِراق وأقبلوا نحو الكوفَة مع عبدِ الرَّحمن، وقُتِلَ منهم خَلْقٌ كثيرٌ، ولمَّا بلَغ عبدُ الرَّحمن الكوفَة تَبِعَهُ أهلُ القُوَّةِ وأصحابُ الخَيْلِ مِن أهلِ البَصْرَة، واجتمع مَن بَقِيَ في البَصْرَة مع عبدِ الرَّحمن بن عبَّاس بن رَبيعَة بن الحارث بن عبدِ المُطَّلِب فبايَعُوه، فقاتَل بهم الحَجَّاجَ خَمْسَ ليالٍ أشدَّ قِتالٍ رآه النَّاسُ، ثمَّ انْصَرف فلَحِقَ بابنِ الأشعث ومعه طائفةٌ مِن أهلِ البَصْرَة، وهذه الوقعة تُسَمَّى: يومَ الزَّاوِيَة، اسْتَبْسَلَ فيها القُرَّاءُ -وهُم العُلَماء- وكان عليهم جَبَلَةُ بن زُحَر فنادَى فيهم: أيُّها النَّاس، ليس الفِرار مِن أَحَدٍ بأقْبَح منه منكم، فقاتِلُوا عن دِينِكم ودُنياكُم. وقال سعيدُ بن جُبير نحو ذلك، وقال الشَّعْبِيُّ: قاتِلُوهم على جَوْرِهِم، واسْتِذْلالِهِم الضُّعَفاء، وإماتَتِهِم الصَّلاة. ثمَّ حَمَلَت القُرَّاءُ على جيشِ الحَجَّاجِ حَمْلَةً صادِقَة، فبَدَّعُوا فيهم، وكان ابنُ الأشعث يُحَرِّض النَّاسَ على القِتال، فلمَّا رأى ما النَّاس فيه أَخَذ مَن اتَّبَعَه وذَهَب إلى الكوفَة، فبايَعَه أهلُها. ثمَّ إنَّ عبدَ الملك عرَض على أهلِ العِراق أن يَخْلَعَ الحَجَّاج ويَعودوا كما كانوا حَقْنًا للدِّماء فأبوا لمَّا رأوا بأَنفُسِهم قُوَّةً وكَثْرَةً وخلعوا عبدَ الملك أيضًا فخَلَّى بين الحَجَّاجِ وبينهم."},{"id":345,"title":"وَفاة المُهَلَّب بن أبي صُفْرَة .","date":["العام الهجري :82","الشهر القمري : ذي الحجة","العام الميلادي :702"],"text":"هو المُهَلَّب بن أبي صُفْرَة ظالم، أبو سَعيد الأَزْدِيُّ، الأميرُ البَطَل، قائدُ الكَتائِب أحدُ أَشْرافِ أهلِ البَصْرَةِ، ووُجَهائِهِم ودُهاتِهِم وأَجْوادِهِم وكُرَمائِهِم، وُلِدَ عامَ الفَتْح، نَزَل المُهَلَّبُ البَصْرَة وغَزا في أيَّام مُعاوِيَة أرضَ الهِنْد سنةَ أربع وأربعين، ووَلِيَ الجزيرةَ لابنِ الزُّبير سنةَ ثمانٍ وسِتِّين، ثمَّ وَلِيَ حَربَ الخَوارِج أوَّلَ دَولةِ الحَجَّاج، وقَتَل منهم في وَقعةٍ واحدة أربعةَ آلاف وثمانمائة، فعَظُمَت مَنزِلتُه عندَ الحَجَّاج, وكان فاضلًا شُجاعًا كريمًا، وله كلامٌ حسن، منه: نِعْمَ الخَصْلَة السَّخاء، تَسْتُر عَورةَ الشَّريف، وتَلْحَق خَسِيسَة الوَضِيع، وتُحَبِّب المَزْهُود فيه. وقال: يُعْجِبُني في الرَّجُل خَصْلَتان: أن أرى عَقْلَه زائِدًا على لِسانِه، ولا أرى لِسانَه زائدًا على عَقْلِه. تُوفِّي المُهَلَّبُ غازيًا بِمَرْو الرُّوذ، وعُمُرهُ سِتَّة وسبعون سنة رَحِمَه الله، وكان مِن الشُّجْعان، وله مَواقِف حَميدة، وغَزَوات مَشْهورة في التُّرْك والأَزارِقَة وغَيرهِم مِن أنواعِ الخَوارِج، وجَعَل الأمرَ مِن بَعدِه لِوَلَدِه يَزيدَ بن المُهَلَّب على إِمْرَةِ خُراسان، فأَمْضَى له ذلك الحَجَّاجُ وعبدُ الملك بن مَرْوان."},{"id":346,"title":"وَقعَة دَيْر الجَماجِم ونِهايَة فِتنَة ابنِ الأشعث .","date":["العام الهجري :83","العام الميلادي :702"],"text":"اسْتُهِلَّ هذا العام والنَّاسُ مُتَواقِفون لِقتال الحَجَّاج وأصحابه بِدَيْرِ قُرَّة، وابنُ الأشعث وأَصحابُه بِدَيْرِ الجَماجِم، والمُبارَزة في كُلِّ يَومٍ بينهم واقِعَة، وفي غالبِ الأيَّامِ تكون النُّصْرَة لأهلِ العِراق على أهلِ الشَّام، إذا حصَل له ظَفَرٌ في يوم مِن الأيَّام يَتقدَّم بجَيشِه إلى نَحْرِ عَدُوِّهِ، وكان له خِبرَةٌ بالحربِ، وما زال ذلك دَأْبُه ودَأْبُهم حتَّى أَمَر بالحَمْلَةِ على كَتيبةِ القُرَّاء; لأنَّ النَّاس كانوا تَبَعًا لهم، وهُم الذين يُحَرِّضُونهم على القِتال، والنَّاس يَقْتَدُون بهم، فصَبَر القُرَّاء لِحَمْلَةِ جَيشِه، ثمَّ جمَع الحَجَّاجُ الرُّماةَ مِن جَيشِه وحَمَل بهم على كَتيبةِ القُرَّاء، وما انْفَكَّ حتَّى قَتَل منهم خَلْقًا كثيرًا، ثمَّ حَمَل على جَيشِ ابن الأشعث فانْهَزَم أصحابُ ابن الأشعث وذَهَبوا في كُلِّ وَجْهٍ، وهَرَب ابنُ الأشعث ومَن معه إلى بلادِ رتبيل مَلِك التُّرْك فأَكْرَمَهُم, كان الحَجَّاجُ يومَ ظَهَرَ على ابن الأشعث بِدَيْرِ الجَماجِم نادَى مُنادِيه في النَّاس: مَن رَجَع فهو آمِن، ومَن لَحِقَ بِقُتَيْبَة بن مُسلِم بالرَّيِّ فهو آمِن. فلَحِقَ به خَلْقٌ كثيرٌ ممَّن كان مع ابنِ الأشعثِ، فأَمَّنَهم الحَجَّاجُ، ومَن لم يَلْحَق به شَرَعَ الحَجَّاجُ في تَتَبُّعِهِم، فقَتَل منهم خَلْقًا كثيرًا."},{"id":347,"title":"الحَجَّاجُ بن يوسُف يبدأ ببِناء مَدينة واسِط في العراق .","date":["العام الهجري :83","العام الميلادي :702"],"text":"قام الحَجَّاجُ بن يوسُف الثَّقفيُّ بعدَ أن اسْتَتَبَّ له العِراق ببِناء مَدينة واسِط، وسُمِّيَت بذلك لتَوَسُّطِها بين البَصْرَة والكوفَة، وجَعَلَها مَعْقَلَهُ وقاعِدَةَ حُكْمِه، وأَسْكَنَها الجُنْدَ الشَّامِيَّ العَربيَّ وأَتْراكَ ما بين النَّهْرَيْنِ الذين قَدِموا أَسْرَى حَرْبٍ أو مَنْفِيِّين أو مِن تِلْقاءِ أَنْفُسِهم فأَضْحَت قاعِدَة للعِراق."},{"id":348,"title":"اسْتِيلاء الأُمَويِّين على جُزُرِ دَهْلَك وتَطْهِيرها مِن القَراصِنَة (جزر إرتريا) .","date":["العام الهجري :83","العام الميلادي :702"],"text":"جُزُر أرخبيل دَهْلَك: مُدُن حَبَشِيَّة ساحِلِيَّة في البَحرِ الأحمر، وبها أكثر مِن مائتي جَزيرَة، وهي عبارة عن جُزُر صَحراوِيَّة بتُرْبَتِها الصَّلْبَة وقِلَّةِ مِياهِها العَذْبَة, لَعِبَت هذه الجُزُر دَوْرًا هامًّا كنُقْطَةِ تَجَمُّعٍ وانْطِلاقٍ للهِجْرات العَربِيَّة القَديمَة المُتَّجِهَة صَوْبَ ساحِل أفريقيا, وعن طَريقِها كان يَتِمُّ نَقْل التِّجارَة واسْتِقبالها, ثمَّ أصبحت جُزُر دَهْلَك مَرْكَزًا للقَراصِنَة الذين كانوا يُهَدِّدُون المِلاحَة, وبَدَأوا بِغاراتٍ على سَواحِل المسلمين، وهَدَّدوا بِتَدْمِير مَكَّة، فَجَرَّدَ أُمَراءُ الأُمَويِّين حَمَلَات تَمَكَّنُوا مِن الاسْتِيلاء عليها وتَطْهِيرها مِن القَراصِنَة، وبعَد الفَتْحِ الإسلاميِّ ازْدَهرت جُزُر دَهْلَك حتَّى كان لها شأنٌ كبيرٌ شَجَّعَ المسلمين على اسْتِيطانِها وتَعْميرِها، كما أصبحت مَوْطِنًا للتِّجارَةِ وطَلَبِ الرِّزْق، أو لاتِّخاذِ مَوْطِنٍ جديدٍ هَرَبًا مِن الحُروبِ والمَجاعات، فَنَقَل هؤلاء إليها الحَضارَة والعِلْم حتَّى أصبحت مَرْكَزَ إِشْعاعٍ لِتَعليم فِقْه الدِّين واللُّغَة، ووَفَد إليها طُلَّاب العِلْم مِن مُخْتَلَف أَنْحاء مَنْطِقة شَمال أفريقيا، كما اتَّخَذَها بَعضُ الخُلَفاء المسلمين مَنْفًى للمَغْضُوب عليهم كَنَوْعٍ مِن العِقاب، وبالذَّاتِ الشُّعَراء الذين عُرِفوا في شِعْرِهِم بالمُجون والتَّشْبِيب بالنِّساء؛ وذلك لِبُعْدِها عن الجَزيرَةِ العَربيَّة ولِشِدَّةِ حَرِّها، وقد عَنِيَ سَلاطِينُ دَهْلَك بعِمارَةِ المَساكِن، والقُصُورِ، ومَنابِر المَساجِد، ومَداخِل القُصُور، والنُّقوش الكِتابِيَّة بالخَطِّ الكوفيِّ."},{"id":349,"title":"فَتْحُ يَزيد بن المُهَلَّب قَلْعَة نَيْزَك بِباذَغِيس .","date":["العام الهجري :84","العام الميلادي :703"],"text":"فَتَحَ يَزيدُ بن المُهَلَّب قَلْعَةَ نَيْزَك، وكان يَزيد قد وَضَع على نَيْزَك العُيونَ، فلمَّا بَلَغَهُ خُروجُ نَيْزَك عنها سار إليها فحاصَرَها فمَلَكَها وما فيها مِن الأموال والذَّخائِر، وكانت مِن أَحْصَن القِلاعِ في زَمانِها، وكان نَيْزَك إذا رآها سَجَدَ لها تَعْظِيمًا لها، كَتَبَ يَزيدُ بن المُهَلَّب إلى الحَجَّاجِ بالفَتْحِ: أَنَّا لَقِينَا العَدُوَّ فمَنَحَنا اللهُ أَكْتافَهُم، فقَتَلْنَا طائِفَة، وأَسَرْنا طائِفَة، ولَحِقَت طائِفَة بِرُؤوسِ الجِبال وعَراعِر الأَوْدِيَة، وأَهْضام الغِيطان وأَثْناء الأَنْهار."},{"id":350,"title":"فَتْحُ عبدِ الله بن عبدِ الملك المَصِّيصَة في بلاد الروم .","date":["العام الهجري :84","العام الميلادي :703"],"text":"غَزا عبدُ الله بن عبدِ الملك الرُّومَ ففَتَح المَصِّيصَة وبَنَى حِصْنَها، ووَضَع بها ثلاثمائة مُقاتِل مِن ذَوِي البَأْسِ، ولم يكُن المسلمون سَكَنوها قبلَ ذلك، وبَنَى مَسجِدَها."},{"id":351,"title":"غَزْوُ محمَّدِ بن مَرْوان أرمينية .","date":["العام الهجري :84","العام الميلادي :703"],"text":"قام محمَّدُ بن مَرْوان وهو أَميرُ الجَزيرَة بِغَزْوِ أرمينية وحَرْقِ كَنَائِسِهِم، وتُسَمَّى هذه السَّنَة بِسَنَةِ الحَرْق."},{"id":352,"title":"وَفاةُ عِمْران بن حِطَّان الخارجيِّ .","date":["العام الهجري :84","العام الميلادي :703"],"text":"هو عِمْرانُ بن حِطَّان بن ظَبْيان، السَّدُوسيُّ البَصريُّ، نَشَأ في البَصْرَة، حَدَّثَ عن عائِشَة، وأبي موسى الأشعريِّ، وابن عَبَّاس، ورَوَى عنه ابنُ سِيرين، وقَتادَة، ويحيى بن أبي كَثير. كان مِن أَهلِ السُّنَّةِ والجَماعَة، فتَزَوَّج امْرأَةً مِن الخَوارِج حَسَنَةً جَميلةً جِدًّا فأَحَبَّها، وكان هو دَمِيمُ الشَّكْل، فأَرادَ أن يَرُدَّها إلى السُّنَّةِ فأَبَتْ، فَارْتَدَّ معها إلى مَذْهَبِها. وقد كان مِن الشُّعراء المُطْبِقِين، وهو القائِلُ في قَتْلِ عَلِيٍّ وقاتِلِه:يا ضَرْبَةً مِن تَقِيٍّ ما أراد بها... إلَّا لِيَبْلُغَ مِن ذي العَرْشِ رِضْوانا إنِّي لأَذْكُرُه يومًا فَأَحْسَبُه... أَوْفَى البَرِيَّةِ عندَ الله مِيزاناأَكْرِم بِقَوْمٍ بُطون الطَّيْر قَبْرُهم... لم يَخْلِطُوا دِينهم بَغْيًا وعُدْواناوقد رَدَّ عليه بَعضُ العُلَماء في أَبياتِه المُتَقَدِّمة في قَتْلِ عَلِيٍّ رضي الله عنه بأبياتٍ على قافِيَتِها ووَزْنِها:بَل ضَرْبَةً مِن شَقِيٍّ ما أراد بها... إلَّا لِيَبْلُغَ مِن ذي العَرْشِ خُسْراناإنِّي لأَذْكُرُه يومًا فأَحْسَبُه... أَشْقَى البَرِيَّةِ عندَ الله مِيزانا"},{"id":353,"title":"إِنْشاء حَسَّان بن النُّعْمان جامِع الزَّيْتونَة بالقَيْرَوان .","date":["العام الهجري :84","العام الميلادي :703"],"text":"بعدَ فَتْحِ تُونُس اقْتَضَتْ الحاجَةُ لِبِناءِ مَسجِد للصَّلاة ونَشْر الدِّين الإسلاميِّ بين أهالي تُونُس، بَنَي أوَّلَ مَسجِد فيها الشَّيْخُ الأمينُ حَسَّان بن النُّعْمان الغَسَّانيُّ فاتِحُ تُونُس وقَرْطاجَنَّة، وسُمِّيَ بـ (جامِع الزَّيْتونَة) لأنَّ مَوْقِعَه كانت به شَجَرَة زَيْتون عندَ صَوْمَعَة كان يَتَعَبَّد فيها راهِبٌ نَصْرانيٌّ، وقِيلَ: إنَّ السَّبَب في تَسْمِيَتِه بهذا الاسم هو لِكَثْرَةِ شَجَر الزَّيْتون بالقُرْبِ مِن مَكان الجامِع عندَ بِنائِه، ثمَّ في سنة 116هـ قام والي أفريقيا الأميرُ عُبيدُ اللّه بن الحَبْحاب بِتَوْسِعَة وإِعْمار الجامِع، وأَحْكَم وَضْعَه على أساسٍ فَخْمٍ، وزاد في ضَخامَتِه. وفي سنة 250هـ بَنَى أبو إبراهيم أحمدُ الأَغْلَبِيُّ في عَهْدِ الخَليفَة المُسْتَعين باللّه قُبَّةَ الجامِع. وفي سنة 381هـ قام أبو الفَتْح المَنْصور بن أبي الفُتُوح يُوسُف بن زِيرِي ثاني مُلوك الصَّنْهاجِيِّين بِتَرْمِيم قُبَّةِ بَهْوِ الجامِع. وفي سنة 747هـ في أيَّام محمَّد المُسْتَنْصِر بن أبي زكريَّا زُوِّدَ الجامِع بالماءِ عن طَريقِ بِناء قَناطِر، وقام أُمَراءُ الشِّيعَة المَهْدِيَّة وبَنُو حَفْص سَلاطين تُونُس بالاهْتِمام بهذا الجامِع، وكان الانْتِهاء من العَمَل به في عَهْد الحاكِم الأغلبيِّ زِيادَة اللّه الثَّاني. وفي سنة 1312هـ /1894م بُنِيَت مِئْذَنَة الجامِع مَكانَ المِئْذَنَة القَديمَة مِن قِبَلِ المُهَنْدِس سُليمان النيقرو. وفي سنة 1357هـ /1939م حَصَل آخِرُ تَرْمِيم للجامِع."},{"id":354,"title":"وَفاةُ عبدِ الرَّحمن بن الأشعث .","date":["العام الهجري :84","العام الميلادي :703"],"text":"هو عبدُ الرَّحمن بن محمَّد بن الأشعث بن قَيْس الكِنْدِيُّ، أَميرُ سِجِسْتان كان قائدًا أُمَوِيًّا مِن أهلِ الكوفَة وأَشرافِها، بَدَأ عبدُ الرَّحمن كَأَيِّ قائِدٍ لِبَنِي أُمَيَّةَ، وضَمَّ عددًا كبيرًا مِن البُلدان لِصالِح الدَّولَةِ الأُمويَّة، ولم تكُن أسباب خُروجِه دِينيَّة على الإطلاق. وُلِدَ عبدُ الرَّحمن في الكوفَة في بَيتٍ مِن أَشرافِها، فأَبُوه محمَّدُ بن الأشعث، أَحَدُ وُجوهِ كِنْدَة. كانت عِلاقَةُ الحَجَّاج بن يوسُف به سَيِّئَةً للغايَةِ، وكان الحَجَّاج كلمَّا رأى عبدَ الرَّحمن قال: يالِخُيَلائِه! أنظُر إلى مِشْيَتِه، والله لهَمَمْتُ أن أَضرِب عُنُقَه. فلمَّا انْهَزَم ابنُ الأشعث وَفَرَّ إلى رتبيل مَلِك التُّرْك كَتَب الحَجَّاجُ إلى رتبيل يَقول له: والله الذي لا إله إلَّا هو، لَئِن لم تَبْعَث إِلَيَّ بابنِ الأشعثِ لَأَبْعَثَنَّ إلى بِلادِك ألفَ ألفَ مُقاتِل، ولَأُخَرِّبَنَّها. فلمَّا تَحَقَّق الوَعيدُ مِن الحَجَّاج اسْتَشار في ذلك بعضَ الأُمراء فأشار عليه بِتَسليم ابن الأشعث إليه قبل أن يُخَرِّب الحَجَّاجُ دِيارَه، ويأخذ عامَّة أَمْصارِه، فأرسَل إلى الحَجَّاج يَشترِط عليه أن لا يُقاتِل عشرَ سِنين، وأن لا يُؤَدِّي في كُلِّ سَنة منها إلَّا مِائَة ألف مِن الخَراجِ، فأجابه الحَجَّاجُ إلى ذلك، وقِيل: إنَّ الحَجَّاج وَعَدَه أن يُطلِق له خَراجَ أَرضِه سبعَ سِنين، فعند ذلك غَدَر رتبيل بابن الأشعث، فقَبَضَ عليه وعلى ثلاثين مِن أَقرِبائِه فَقَيَّدَهم في الأَصفادِ، وبَعَث بهم مع رُسُلِ الحَجَّاج إليه، فلمَّا كانوا بِبَعضِ الطَّريق بِمَكان يُقالُ له: الرُّخَّج، صَعَد ابنُ الأشعث وهو مُقَيَّد بالحَديدِ إلى سَطْحِ قَصْرٍ، ومعه رجل مُوكل به; لِئَلَّا يَفِرَّ، وألقى نَفْسَه مِن ذلك القَصْر، وسَقَطَ معه المُوكل به فماتا جَميعًا، فعَمَد الرَّسول إلى رأسِ ابن الأشعثِ فاحْتَزَّهُ، وقَتَل مَن معه مِن أصحابِ ابن الأشعث، وبَعَث بِرُؤوسِهم إلى الحَجَّاج، فأَمَرَ فَطِيفَ بِرَأْسِه في العِراق، ثمَّ بَعَثَه إلى أميرِ المؤمنين عبدِ الملك فَطِيفَ بِرَأْسِه في الشَّام، ثمَّ بَعَث به إلى أَخيهِ عبدِ العزيز بِمِصْرَ فَطِيفَ بِرَأْسِه هُنالِك، ثمَّ دَفَنوا رَأْسَه بِمِصْرَ وجُثَّتَه بالرُّخَّج, وقِيلَ إنَّه مات عامَ 85 هـ. قال عنه ابنُ كثير: \"والعَجَبُ كُلُّ العَجَب مِن هؤلاء الذين بايَعُوه بالإمارَةِ وليس مِن قُريشٍ، وإنَّما هو كِنْدِيٌّ مِن اليَمَن، وقد اجْتَمَع الصَّحابَةُ يومَ السَّقِيفَة على أنَّ الإمارَة لا تكون إلَّا في قُريشٍ، واحْتَجَّ عليهم الصِّدِّيقُ بالحديث في ذلك، حتَّى إنَّ الأنصار سألوا أن يكون منهم أَميرٌ مع أَميرِ المُهاجرِين فأَبَى الصِّدِّيقُ عليهم ذلك. فكيف يَعْمِدون إلى خَليفَة قد بُويِعَ له بالإمارةِ على المسلمين مِن سِنين فيَعْزِلونه وهو مِن صُلْبِيَّةِ قُريشٍ ويُبايِعون لِرَجُلٍ كِنْدِيٍّ بَيْعَةً لم يَتَّفِق عليها أَهلُ الحَلِّ والعَقْدِ؟! ولهذا لمَّا كانت هذه زَلَّة وفَلْتَة نَشَأ بِسَبَبِها شَرٌّ كَبيرٌ هَلَكَ فيه خَلْقٌ كَثيرٌ، فإنَّا لله وإنَّا إليه راجِعُون\"."},{"id":355,"title":"فَتْحُ المُفَضَّل بن المُهَلَّب باذغيس .","date":["العام الهجري :85","العام الميلادي :704"],"text":"ثمَّ لمَّا وَلِيَ المُفَضَّل بن المُهَلَّب خُراسان غَزَا باذغيس ففَتَحَها وأصاب مَغنمًا فقَسَّمَه، فأصاب كُلُّ رَجُلٍ ثماني مائة. ثمَّ غَزَا آخرون وشومان فغَنِمَ وقَسَّمَ ما أصاب، ولم يكُن للمُفَضَّل بيتُ مَالٍ، كان يُعطِي النَّاس كُلمَّا جاء شيءٌ، وإن غَنِمَ شَيئًا قَسَّمَه بينهم."},{"id":356,"title":"بَيْعَة عبدِ المَلِك بن مروان لِوَلَدَيْهِ الوَليد ثمَّ سُليمان .","date":["العام الهجري :85","الشهر القمري : ربيع الأول","العام الميلادي :704"],"text":"أراد عبدُ الملك بن مَرْوان أن يَخْلَع أخاه عبدَ العزيز مِن وِلايَة العَهْد ويُبايِع لابنِه الوَليد بن عبدِ الملك، فنَهاهُ عن ذلك قَبِيصَةُ بن ذُؤَيْب وقال: لا تَفعَل؛ فإنَّك تَبْعَث على نَفْسِك صَوتَ عَارٍ، ولَعَلَّ الموتَ يأتيه فتَسْتَريح منه. فَكَفَّ عنه ونَفْسُه تُنازِعُه إلى خَلْعِه. فدَخَل عليه رَوْحُ بن زِنْباع، وكان أَجَلَّ النَّاس عند عبدِ الملك، فقال: يا أميرَ المؤمنين، لو خَلعتَه ما انْتَطَح فيه عَنْزان، وأنا أوَّلُ مَن يُجيبُك إلى ذلك. قال: نُصْبِح إن شاء الله. ونام رَوْحٌ عند عبدِ الملك، فدَخَل عليهما قَبيصةُ بن ذُؤَيب وهُما نائِمان، وكان عبدُ الملك قد تَقَدَّم إلى حُجَّابِه أن لا يَحْجِبوا قَبيصةَ عنه، وكان إليه الخاتَم والسِّكَّة، تَأتيهِ الأخبارُ والكُتُبُ قبلَ عبدِ الملك، فلمَّا دَخَل سَلَّم عليه، قال: آجَرَك الله في أَخيك عبدِ العزيز. قال: وهل تُوفِّي؟ قال: نعم. فاسْتَرْجَع عبدُ الملك، ثمَّ أقْبَل على رَوْح، فقال: كَفانا الله ما كُنَّا نُريد، وكان ذلك مُخالِفًا لك يا قَبيصة. فقال قَبيصةُ: يا أميرَ المؤمنين، إنَّ الرَّأْي كُلَّه في الأَناةِ، فقال عبدُ الملك: ورُبَّما كان في العَجَلة خَيْرٌ كَثيرٌ، رَأيتَ أَمْرَ عَمرِو بن سَعيد، ألم تكُن العَجَلَةُ فيه خيرًا مِن الأَناةِ؟ وكانت وَفاةُ عبدِ العزيز في جُمادَى الأُولى في مِصْرَ، فضَمَّ عبدُ الملك عَمَلَه إلى ابنه عبدِ الله بن عبدِ الملك ووَلَّاه مِصْرَ. فلمَّا مات عبدُ العزيز قال أهلُ الشَّام: رُدَّ على أَميرِ المؤمنين أَمْرُهُ. فلمَّا أَتَى خَبَرُ مَوْتِه إلى عبدِ الملك أَمَر النَّاسَ بالبَيْعَة لابْنَيْهِ الوَليد وسُليمان، فبايَعوا، وكَتَبَ بالبَيْعَة لهما إلى البُلْدان."},{"id":357,"title":"غَزْوُ قُتيبَة بن مُسلِم أَرض التُّرْك .","date":["العام الهجري :86","العام الميلادي :704"],"text":"قَدِمَ قُتيبةُ خُراسان أميرًا عليها للحَجَّاج، فقَدِمَها والمُفَضَّل يَعرِض الجُنْدَ للغَزَاةِ، فخَطَب قُتيبةُ النَّاسَ وحَثَّهُم على الجِهاد، ثمَّ عَرَضَهم وسَارَ، وجَعَل بِمرو على حَرْبِها إياس بن عبدِ الله بن عَمرٍو، وعلى الخَراجِ عُثمان السعيدي. فلمَّا كان بالطَّالقان أتاهُ دَهاقِين بَلْخ وساروا معه، فقَطَع النَّهْر، فتَلَقَّاه مَلِكُ الصَّغَانِيَان بِهَدايا ومَفاتِيح مِن ذَهَبٍ، ودَعاهُ إلى بِلادِه فمضى معه، فسَلَّمَها إليه لأنَّ ملك آخْرُونَ وشُومان كان يُسيءُ جِوارَه. ثمَّ سَارَ قُتيبةُ منها إلى آخْرُون وشُومان، وهما مِن طخارستان، فصالَحَهُ مَلِكُهُما على فِدْيَة أَدَّاها إليه فَقَبِلَها قُتيبةُ ثمَّ انْصَرف إلى مرو واسْتَخْلف على الجُنْدِ أَخاهُ صالحَ بن مُسلِم، ففَتَح صالحٌ بعدَ رُجوعِ قُتيبةَ كاشان وأورشت، وهي مِن فَرْغانَة، وفَتَح أخشيكت، وهي مدينة فَرْغانَة القديمة، وكان معه نَصرُ بن سِيار فأَبْلَى يَومئذٍ بلاءً حسنًا."},{"id":358,"title":"غَزْوُ مَسْلَمة بن عبدِ الملك بِلاد الرُّوم وهَلَاك ملكها .","date":["العام الهجري :86","العام الميلادي :704"],"text":"غَزَا مَسلَمةُ بن عبدِ الملك الرُّومَ فقَتَل منهم عددًا كبيرًا بسوسنة مِن ناحِيَة المَصِّيصة وفَتَح حُصونًا. وقِيلَ: إنَّ الذي غَزَا في هذه السَّنَة هِشامُ بن عبدِ الملك ففَتَح حِصْنَ بولق، وحِصْن الأخرم، وحِصْن بولس وقمقم، وقَتَل مِن المُتَعَرِّبَة نحوًا مِن ألفِ مُقاتِل وسَبَى ذُرِّيَّتَهم ونِساءَهم."},{"id":359,"title":"وَفاةُ الخَليفَة عبدِ الملك بن مَرْوان .","date":["العام الهجري :86","الشهر القمري : شوال","العام الميلادي :705"],"text":"هو عبدُ الملك بن مَرْوان بن الحَكَم بن أبي العاصِ بن أُمَيَّة، أبو الوَليد الأُمَويُّ أَميرُ المؤمنين، وُلِدَ سنة سِتٍّ وعشرين بالمدينة, شَهِدَ الدَّارَ –يعني يومَ مَقْتَل عُثمان-مع أبيه، وله عَشْرُ سِنين، وهو أوَّلُ مَن سَارَ بالنَّاس في بِلاد الرُّوم سنة ثنتين وأربعين، وكان أَميرًا على أهلِ المدينة وله سِتَّ عَشرةَ سنة، وَلَّاهُ إيَّاها مُعاوِيَةُ، وكان يُجالِس الفُقَهاء والعُلَماء والعُبَّاد والصُّلَحاء, بُويِعَ بالخِلافَة في سنة خَمس وسِتِّين في حَياةِ أبيهِ، في خِلافَة ابن الزُّبير، وبَقِيَ على الشَّامِ ومِصْرَ مُدَّة سَبْعِ سِنين، وابن الزُّبير على باقي البِلاد ثمَّ اسْتَقَلَّ بالخِلافَة على سائِر البِلاد والأقاليم بعدَ مَقْتَل ابنِ الزُّبير، وقد كان عبدُ الملك قبلَ الخِلافَة مِن العُبَّاد الزُّهَّاد الفُقَهاء المُلازِمين للمَسجِد، التَّالِين للقُرآن، وكان رِبْعَةً مِن الرِّجال أَقْرَب إلى القِصَر. قال عنه نافعٌ: رَأيتُ المدينةَ وما فيها شَابٌّ أَشَدُّ تَشْميرًا، ولا أَفْقَهُ ولا أَقْرَأُ لِكِتابِ الله مِن عبدِ الملكِ بن مَرْوان. قال عبدُ الملك: كُنتُ أُجالِس بَرِيرَةَ قبلَ أن أَلِيَ هذا الأَمْرَ، فكانت تَقولُ: يا عبدَ الملك، إنَّ فِيكَ خِصالًا، وإنَّك لَجَدِيرٌ أن تَلِيَ أَمْرَ هذه الأُمَّةِ، فاحْذَر الدِّماء ; فإنِّي سَمِعْتُ رَسولَ الله صلَّى الله عليه وسلَّم يقول: ((إنَّ الرَّجُلَ لَيُدْفَع عن بابِ الجَنَّة أن يَنْظُرَ إليها على مِحْجَمَةٍ مِن دَمٍ يُريقُه مِن مُسلِم بِغيرِ حَقٍّ. كان فُقَهاء المَدينة أَربعَة: سَعيدُ بن المُسَيِّب، وعُرْوَةُ، وقَبيصَةُ بن ذُؤَيْب، وعبدُ الملك بن مَرْوان قبلَ أن يَدخُل في الإمارة. لم يَزَلْ عبدُ الملك مُقيمًا بالمدينة حتَّى كانت وَقْعَة الحَرَّةِ، واسْتَولى ابنُ الزُّبير على بِلادِ الحِجازِ، وأَجْلَى بَنِي أُمَيَّة منها، فقَدِمَ مع أَبيهِ الشَّامَ، ثمَّ لمَّا صارَت الإمارةُ مع أَبيهِ وبايَعه أهلُ الشَّام أَقامَ في الإمارةِ تَسعةَ أَشهُر، ثمَّ عَهِدَ إليه بالإمارةِ مِن بَعدِه. بُويِعَ عبدُ الملك بالخِلافَة في مُسْتَهَلِّ رَمضانَ سنة خَمسٍ وسِتِّين، واجْتَمع النَّاسُ عليه بعدَ مَقتلِ ابنِ الزُّبير سنة ثلاث وسَبعين. كان عبدُ الملك له إقْدامٌ على سَفْكِ الدِّماء، وكان عُمَّالُه على مَذهَبِه; منهم الحَجَّاجُ، والمُهَلَّبُ، وغيرُهم، وكان حازِمًا فَهِمًا فَطِنًا، سَائِسًا لِأُمُور الدُّنيا، لا يَكِلُ أَمْرَ دُنياهُ إلى غَيرِه، وكان عبدُ الملك يقول: أَخافُ المَوتَ في شَهْرِ رَمضان، فيه وُلِدْتُ وفيه فُطِمْتُ وفيه جَمَعْتُ القُرآنَ، وفيه بايَعَ لِيَ النَّاسُ، فمات في النِّصف مِن شَوَّال حين أَمِنَ الموتَ في نَفسِه. وكان عُمُرُهُ سِتِّين سنة، وقِيلَ: ثلاثًا وسِتِّين سنة. وكانت خلافَتُه مِن لَدُن قَتْلِ ابنِ الزُّبير ثلاث عَشرةَ سنةً وأربعة أَشهُر إلَّا سبع ليالٍ، وقِيلَ: وثلاثة أَشهُر وخمسة عَشرَ يومًا. ودُفن خارِجَ بابِ الجابِيَة. صلَّى عليه ابنُه الوَليدُ ووَلِيَ عَهْدَهُ مِن بَعدِه."},{"id":360,"title":"الوَليد بن عبدِ الملك يَتَوَلَّى الخِلافَة .","date":["العام الهجري :86","الشهر القمري : شوال","العام الميلادي :705"],"text":"لمَّا دُفِنَ عبدُ الملك بن مَرْوان انْصَرَف الوَليدُ عن قَبرِه فدَخَل المَسجِد وصَعَد المِنْبَر واجْتَمع إليه النَّاسُ فخَطَبَهم وقال: إنَّا لله وإنَّا إليه راجِعون، والله المُستعان على مُصِيبتِنا لِمَوتِ أَميرِ المؤمنين، والحمدُ لله على ما أَنْعَمَ علينا مِن الخِلافَة، قوموا فبايِعُوا، فكان أوَّلَ مَن عَزَّى نَفْسَه وهَنَّأَهَا؛ وكان أوَّلَ مَن قام لِبَيْعَتِه عبدُ الله بن هَمَّام السَّلُولِيُّ."},{"id":361,"title":"وَضْعُ أُسُسِ بِناءِ المَسجِد الأُمَويِّ الجامِع بِدِمَشْق .","date":["العام الهجري :87","العام الميلادي :705"],"text":"شَرَعَ الخَليفةُ الوَليدُ بن عبدِ الملك بن مَرْوان في بِناءِ جامِع دِمَشق الأُمَويِّ؛ وكان نِصْفُه كَنيسةَ النَّصارَى، وعلى ذلك صَالَحَهم أبو عُبيدةَ بن الجَرَّاح؛ فقال لهم الوَليدُ: إنَّا قد أَخَذنا كَنيسةَ مَريمَ عَنْوَةً فأَنَا أَهْدِمُها، فَرَضوا بِهَدْمِ هذه الكَنيسَة وإبْقاء كَنيسَة مَريم؛ والمِحْراب الكبير هو مكان بابِ الكَنيسَة."},{"id":362,"title":"تَوَلِّي عُمَرَ بن عبدِ العزيز إِمارَة المدينة .","date":["العام الهجري :87","العام الميلادي :705"],"text":"عَيَّنَ الوَليدُ بن عبدِ الملك عُمَرَ بنَ عبدِ العزيز على إِمارَةِ المَدينَة بعدَ أن عَزَلَ هِشامَ بن إسماعيلَ عن وِلَايَتِها، ثمَّ ضَمَّ إليه وِلايَةَ الطَّائِف سنة 91هـ، وبذلك صار وَالِيًا على الحِجازِ كُلِّها, وكانت إمارتُه عليها أربعَ سِنين غير شَهرٍ أو نَحوِه، فقَدِمَها وَالِيًا وثَقَلُه على ثلاثين بَعِيرًا، فنَزَل دارَ مَرْوان، وجَعَل يَدخُل عليه النَّاسُ فيُسَلِّمون، فلمَّا صلَّى الظُّهْرَ دَعَا عَشرةً مِن الفُقَهاء الذين في المدينة: عُرْوَةَ بن الزُّبير، وأبا بَكْر بن سُليمان بن أبي خَيْثَمَة، وعُبيدَ الله بن عبدِ الله بن عُتْبَة بن مَسْعود، وأبا بَكْر بن عبدِ الرَّحمن بن الحارِث، وسُليمان بن يَسار، والقاسِم بن محمَّد، وسالِم بن عبدِ الله بن عُمَرَ، وعبدَ الله بن عُبيدِ الله بن عُمَرَ، وعبدَ الله بن عامِر بن ربِيعَة، وخارِجَة بن زَيدٍ، فدَخَلُوا عليه، فقال لهم: إنَّما دَعَوْتُكم لِأَمْرٍ تُؤْجَرُون عليه, وتَكُونون فيه أَعوانًا على الحَقِّ، لا أُريدُ أن أَقْطَعَ أَمْرًا إلَّا بِرَأْيِكم، أو بِرَأْيِ مَن حَضَر منكم، فإن رَأيتُم أَحدًا يَتَعَدَّى, أو بَلَغَكُم عن عامِلٍ لي ظُلْمٌ، فأُحَرِّجُ اللهَ على مَن بَلغَهُ ذلك إلَّا بَلَّغَنِي. فخَرجُوا يَجْزُونَهُ خَيْرًا وافْتَرقوا."},{"id":363,"title":"غَزْوُ قُتيبةَ بن مُسلِم لِبِيكَنْد (أَدْنَى مَدائِن بُخارَى) .","date":["العام الهجري :87","العام الميلادي :705"],"text":"غَزَا قُتيبةُ بِيكَنْد وهي أَدْنَى مَدائِن بُخارَى إلى النَّهْر، فلمَّا نَزَل بهم اسْتَنْصَروا الصُّغْدَ واسْتَمَدُّوا مَن حَولهم، فأَتوهم في جَمْعٍ كَثيرٍ وأَخَذوا الطُّرُقَ على قُتيبَة، فلم يَنْفَذ لِقُتيبَة رَسولٌ ولم يَصِل إليه خَبَرٌ شَهْرَيْنِ، وأَبطأَ خَبرُه على الحَجَّاج فأَشفَق على الجُنْدِ فأَمَر النَّاس بالدُّعاء لهم في المَساجِد وهُم يَقْتَتِلُون كُلَّ يومٍ. وكان لِقُتيبةَ عَيْنٌ مِن العَجَمِ يُقالُ له: تَنْدُر، فأَعطاهُ أهلُ بُخارَى مَالًا لِيَرُدَّ عنهم قُتيبة، فأَتاه فقال له سِرًّا مِن النَّاس: إنَّ الحَجَّاج قد عُزِلَ وقد أَتَى عامِل إلى خُراسان فلو رَجَعْتَ بالنَّاس كان أَصْلَح. فأَمَر به فقُتِلَ خَوفًا مِن أن يَظهَر الخَبَرُ فيَهْلك النَّاس، ثمَّ أَمَرَ أَصحابَه بالجِدِّ في القِتال فقَاتَلهم قِتالًا شَديدًا، فانْهَزَم الكُفَّارُ يُريدون المدينةَ وتَبِعَهم المسلمون قَتْلًا وأَسْرًا كيف شَاؤُوا، وتَحَصَّنَ مَن دَخَل المدينةَ بها، فوَضَع قُتيبةُ الفَعَلَةَ لِيَهْدِمَ سُورَها، فَسَألُوه الصُّلْحَ فصَالَحَهم واسْتَعْمَل عليه عامِلًا وارْتَحَل عنهم يُريد الرُّجوعَ, فلمَّا سَارَ خَمسةَ فَراسِخ نَقَضُوا الصُّلْحَ, وقَتَلوا العامِلَ ومَن معه، فرَجَع قُتيبةُ فنَقَبَ سُورَهم فسَقَطَ فَسألوه الصُّلْحَ فلم يَقبَل، ودَخَلها عَنْوَةً وقَتَل مَن كان بها مِن المُقاتِلَة، وأصابوا فيها مِن الغَنائِم والسِّلاح وآنِيَة الذَّهَب والفِضَّة ما لا يُحْصَى، ولا أصابوا بخُراسان مِثلَه، فقَوِيَ المسلمون، ووَلِيَ قَسْمَ الغَنائِم عبدُ الله بن وَأْلَان العَدَوِيُّ أَحَدُ بَنِي نلكان، وكان قُتيبةُ يُسَمِّيه الأَمين ابن الأَمين، فإنَّه كان أَمِينًا. فلمَّا فَرَغ قُتيبةُ مِن فَتْح بِيكَنْد رَجَع إلى مَرْو."},{"id":364,"title":"الوليد بن عبد الملك يُدْخِل حُجْرَةَ عائِشَة رَضِيَ الله عنها في المَسجِد النبوي .","date":["العام الهجري :88","العام الميلادي :706"],"text":"كَتَبَ الوَليدُ إلى عُمَرَ بن عبدِ العزيز في رَبيعٍ الأوَّل يَأمُره بِإدْخال حُجَرِ أَزواجِ النَّبِيِّ صلَّى الله عليه وسلَّم في مَسجِد رَسولِ الله صلَّى الله عليه وسلَّم، وأن يَشتَرِي ما في نَواحِيه حتَّى يكون مِائَتَي ذِراع في مِائَتَي ذِراع، ويَقول له: قَدِّم القِبْلَةَ إن قَدَرْتَ، وأنت تَقْدِر لِمَكان أَخوالِك، وإنَّهم لا يُخالِفُونك، فمَن أَبَى منهم فقَوِّمُوا مُلْكَهُ قِيمَةَ عَدْلٍ واهْدِم عليهم وادْفَع الأثمانَ إليهم، فإنَّ لك في عُمَرَ وعُثمان أُسْوَةً. فأَحْضَرَهُم عُمَرُ وأَقْرَأَهم الكِتابَ، فأجابوه إلى الثَّمَنِ، فأَعطاهُم إِيَّاهُ، وأَخَذوا في هَدْمِ بُيوتِ أَزْواجِ رَسولِ الله صلَّى الله عليه وسلَّم، وبَنَى المَسْجِدَ، وقَدِمَ عليهم الفَعَلَةُ مِن الشَّام، أَرْسَلَهم الوَليدُ، وبَعَثَ الوَليدُ إلى مَلِك الرُّوم يُعْلِمُه أنَّه قد هَدَمَ مَسجِدَ النَّبِيِّ صلَّى الله عليه وسلَّم لِيُعَمِّرَهُ، فبَعَث إليه مَلِكُ الرُّومِ مِائَة ألف مِثْقال ذَهَب، ومِائَة عامِل، وبَعَثَ إليه مِن الفُسَيْفِسَاء بِأَربعين جَمَلًا، فبَعَثَ الوَليدُ بذلك إلى عُمَرَ بن عبدِ العزيز، وحَضَر عُمَرُ ومعه النَّاسُ فوَضَعوا أَساسَه وابْتَدَأوا بِعِمارَتِه."},{"id":365,"title":"مَعرَكة حِصْن الطُّوانَة وهَزيمَة الرُّوم بِشَمال الشَّام بِقِيادَة مَسلمَة بن عبدِ الملك .","date":["العام الهجري :88","العام الميلادي :706"],"text":"غَزَا مَسلمةُ بن عبدِ الملك والعَبَّاس بن الوَليد بن عبدِ الملك بِلادَ الرُّومِ، وكان الوَليدُ قد كَتَبَ إلى صاحِب أرمينية يَأمُره أن يَكتُب إلى مَلِك الرُّوم يعرفه أن الخَزَر وغيرهم مِن مُلوك جِبال أرمينية قد اجتمعوا على قَصْدِ بِلادِه، ففَعَل ذلك، وقَطَعَ الوَليدُ البَعْثَ على أهلِ الشَّام إلى أرمينية وأَكْثَرَ وأَعْظَمَ جِهازَهُ، وساروا نحو الجَزيرَة ثمَّ عَطَفوا منها إلى بَلَدِ الرُّوم فاقْتَتَلوا هُم والرُّوم، فانْهَزَم الرُّومُ ثمَّ رَجَعوا فانْهَزَم المسلمون، فبَقِيَ العَبَّاس في نَفَرٍ، منهم ابنُ مُحَيْرِيز الجُمَحِيُّ، فقال العَبَّاسُ: أين أهلُ القُرآن الذين يُريدون الجَنَّة؟ فقال ابنُ مُحَيْرِيز: نَادِهِمْ يَأْتُوك. فنَادَى العَبَّاسُ: يا أهلَ القُرآن! فأَقْبَلوا جَميعًا، فهَزَمَ اللهُ الرُّومَ حتَّى دَخَلوا طُوانَة، وحَصَرَهم المسلمون، وفَتَحوها في جُمادَى الأُولى. كما غَزَا مَسلمةُ بن عبدِ الملك الرُّومَ أيضًا ففَتَحَ ثَلاثَة حُصونٍ: أَحَدها حِصْن قُسْطَنْطِين وغَزَالَة وحِصْن الأَخْرم، وقَتَل مِن المُسْتَعْرِبَة نَحوًا مِن ألف، وأَخَذ الأَموال."},{"id":366,"title":"الأمويون يتوغلون في بلاد الروم ويفتتحون عَمُّورِية وهِرْقَلَة وقَمُونِيَة .","date":["العام الهجري :89","العام الميلادي :707"],"text":"غَزَا مَسلمةُ والعَبَّاس بن الوَليد بن عبدِ الملك الرُّومَ، فافْتَتَح مَسلمةُ حِصْنَ سُورِيَة، وافْتَتَح العَبَّاسُ مَدينَة أذرولية، ثمَّ إنَّ مَسلمةَ قَصَد عَمُّورِيَة فلَقِيَ بها جَمْعًا مِن الرُّوم كثيرًا فهَزَمَهم وافْتَتَح هِرْقَلَة وقَمُونِيَة، وغَزَا العَبَّاس الصَّائِفَة مِن ناحِيَة البَذَنْدُون."},{"id":367,"title":"غَزْوُ محمَّد بن القاسِم بِلاد السِّنْد .","date":["العام الهجري :89","العام الميلادي :707"],"text":"سَارَ محمَّدُ بن القاسِم بن محمَّد بن الحَكَم بِأَمْرٍ مِن الحَجَّاج بِجَيْشٍ مُجَهَّزٍ بالكامِل إلى مُكْران فأَقام بها أيَّاما ثمَّ أَتَى قَنَّزْبُور ففَتَحَها، ثمَّ سَارَ إلى أَرمائِيل ففَتَحَها، ثمَّ سَارَ إلى الدَّيْبُل فقَدِمَها يومَ جُمُعَة، ووافَتْهُ سُفُنٌ كان حَمَلَ فيها الرِّجالَ والسِّلاحَ والأَداةَ فخَنْدَقَ حين نَزَل الدَّيْبُل, وكان بالدَّيْبُل بُدٌّ عَظيمٌ عليه دَقَلٌ عَظيمٌ وعلى الدَّقَلِ رَايةٌ حَمراء إذا هَبَّت الرِّيحُ أَطافَت بالمَدينة، وكانت تَدور، والبُدُّ صَنَمٌ في بِناء عَظيمٍ تحتَ مَنارَةٍ عَظيمةٍ مُرتَفِعَة، وفي رَأسِ المَنارَة هذا الدَّقَل، وكُلُّ ما يُعْبَد فهو عندهم بُدٌّ. فحَصَرها وطال حِصارُها، فرَمَى الدَّقَل بِحَجَر العَرُوس فكَسَرَه، فتَطَيَّر الكُفَّارُ بذلك، ثمَّ إنَّ محمَّد أَتَى ونَاهَضَهُم وقد خَرَجوا إليه فهَزَمَهم حتَّى رَدَّهُم إلى البَلَدِ وأَمَرَ بالسَّلالِيم فنُصِبَت وصَعَد عليها الرِّجالُ، وكان أوَّلَهم صُعودًا رَجُلٌ مِن مُراد مِن أَهلِ الكوفَة، ففُتِحَت عَنْوَة وقَتَّلَ فيها ثَلاثَةَ أيَّام، وهَرَب عامِلُ ذاهر عنها وأَنزَلها محمَّدٌ أَربعةَ آلافٍ مِن المسلمين، وبَنَى جامِعَها وسَارَ عنها إلى البِيرُون، وكان أَهلُها بَعَثوا إلى الحَجَّاج فصالَحوه، فلَقوا محمَّدًا بالمِيرَةِ وأَدخَلوه مَدينَتَهم، وسَارَ عنها وجَعَل لا يَمُرُّ بمدينة إلَّا فَتَحَها حتَّى عَبَرَ نَهْرًا دون مِهْران، فأَتاهُ أَهلُ سَرْبَيْدِس فصالَحوه، ووَظَّفَ عليهم الخَراجَ وسَارَ عنهم إلى سَهْبان ففَتَحَها، ثمَّ سَارَ إلى نَهْرِ مِهْران فنَزَل في وسَطَهِ، وبَلَغ خَبرُه ذاهر فاسْتَعَدَّ لِمُحارَبَتِه وبَعَثَ جَيْشًا إلى سَدُوسْتان، فطَلَبَ أَهلُها الأَمانَ والصُّلْحَ، فآمَنَهُم ووَظَّفَ عليهم الخَراجَ، ثمَّ عَبَرَ محمَّدُ مهران مما يَلِي بِلادَ راسِل الملك على جِسْر عقده وذاهِر مُسْتَخِفٍّ به، فلَقِيَه محمَّد والمسلمون وهو على فِيلٍ وحَولَه الفِيَلَةُ، ومعه التَّكاكِرَة، فاقتتلوا قِتالًا شديدًا لم يُسمَع بِمثلِه، وتَرَجَّلَ ذاهر فقُتِلَ عند المَساءِ، ثمَّ انْهَزَم الكُفَّار وقَتَلَهم المسلمون كيف شاؤوا، فغَلَبَ محمَّدٌ على بِلادِ السِّنْدِ وفَتَحَ مدينةَ راوَرَ عَنْوةً ثمَّ سار إلى بِرْهَمِناباذ العَتيقَة، وهي على فَرْسَخَيْنِ مِن المَنْصُورة، ولم تكُن المَنْصُورة يَومئذٍ، كان مَوْضِعُها غَيْضَةً، وكان المُنْهَزِمون مِن الكُفَّار بها، فقاتَلوه ففَتَحَها محمَّدٌ عَنْوةً وقَتَل بها بَشَرًا كَثيرًا وخُرِّبَت. وسَارَ يُريدُ الرُّورَ وبَغْرورَ فلَقِيَه أهلُ ساوَنْدَرَى فطَلَبوا الأمانَ فأَعطاهُم إيَّاهُ واشْتَرَط عليهم ضِيافَة المسلمين، ثمَّ أَسلَم أَهلُها بعدَ ذلك. ثمَّ تَقدَّم إلى بِسْمَد وصالَح أَهلَها، ووَصَل إلى الرُّور، وهي مِن مدائن السِّنْدِ على جَبَل، فحَصَرَهم شُهورًا فصالَحوه، وسارَ إلى السِّكَّة ففَتَحَها، ثمَّ قَطَع نَهرَ بَياس إلى المُلْتان فقاتَلَه أَهلُها وانْهَزَموا، فحَصَرَهم محمَّدٌ فجاءَه إِنسانٌ ودَلَّهُ على قَطعِ الماء الذي يَدخُل المَدينَة فقَطَعَه، فعَطِشوا فأَلْقوا بِأَيديهم ونَزَلوا على حُكمِه، فقَتَل المُقاتِلَة وسَبَى الذُّرِّيَّة وسَدَنَة البُدِّ."},{"id":368,"title":"تَوْلِيَة موسى بن نُصَير غَزْو بِلادِ المَغرِب  .","date":["العام الهجري :89","العام الميلادي :707"],"text":"كان موسى بن نُصَير ذا رَأْيٍ وتَدْبيرٍ وحَزْمٍ و خِبْرَةٍ بالحَرْبِ، فوَلَّاهُ عبدُ العزيز بن مَرْوان والي مِصْر على أفريقيا خَلَفًا لِحَسَّان بن النُّعْمان في خِلافَة الوَليدِ بن عبدِ الملك بن مَرْوان، فعَمِل موسى بن نُصَير على تَثْبيت دَعائِم الإسلام في إقليم أفريقيا، الذي ارْتَدَّ أَهلُه عن الإسلام أَكثرَ مِن مَرَّة؛ فاسْتَطاع موسى أن يُخْمِد ثَوْرات البَرْبَر المُتَعاقِبَة، ويُعيد فَتْحَ المَناطِق التي كان البَرْبَر قد انْتَزَعوها مِن المسلمين بعدَ فَتحِها أوَّلَ مَرَّةٍ، كما شَرَع موسى في بِناءِ دارِ صِناعَة قُرْبَ قَرْطاجَنَّة لِبِناءِ أُسْطولٍ قَوِيٍّ لِحِمايَة الثُّغور. ثمَّ توَجَّه موسى بن نُصَير ناحِيَة المَغرِب فافْتَتَح بِلادًا كَثيرةً جِدًّا."},{"id":369,"title":"إخماد موسى بن نصير ثورات البَرْبَر نهائيا  .","date":["العام الهجري :89","العام الميلادي :707"],"text":"لمَّا وَصَل موسى إلى أفريقيا وبها صالِحٌ الذي اسْتَخْلَفَه حَسَّانُ على أفريقيا، وكان البَرْبَر قد طَمِعوا في البِلاد بعدَ مَسير حَسَّان عنها، فلمَّا وَصَل موسى عَزَل صالِحًا، وبَلَغَه أنَّ بأَطْرافِ البِلادِ قومًا خارجِين عن الطَّاعَة، فوَجَّه إليه ابنَه عبدَ الله فقاتَلَهم فظَفَر بهم، وسَبَى منهم ألفَ رَأسٍ، وسَيَّرَه في البَحرِ إلى جَزيرَة مَيُورْقَة، فنَهَبَها وغَنِمَ منها ما لا يُحْصَى وعاد سالِمًا، فوَجَّه ابنَه هارونَ إلى طائِفَة أُخرى فظَفَر بهم وسَبَى منهم نحوَ ذلك، وتَوَجَّه هو بِنَفسِه إلى طائِفَة أُخرى فغَنِمَ نحوَ ذلك، فبَلَغ الخُمُسُ سِتِّين ألف رَأسٍ مِن السَّبْيِ، ولم يَذكُر أَحَدٌ أنَّه سَمِعَ بِسَبْيٍ أَعظَم مِن هذا. ثمَّ قام موسى بن نُصَير بإخْلاءِ ما تَبَقَّى مِن قَواعِد للبِيزَنطيِّين على شَواطِئ تُونُس كما اسْتَعاد المَناطِق التي كان البَرْبَر قد انْتَزَعوها من المسلمين بعدَ فَتْحِها أوَّلَ مَرَّةَ، واهْتَمَّ موسى بِنَشرِ الإسلام بين البَرْبَر ومُسالَمَتِهم واسْتِمالَة رُؤوسِهم، لِيَضْمَن ألَّا يَنْزَعوا للثَّوْرَةِ مُجدَّدًا، فانْضَمَّ إلى جَيشِه الآلافُ منهم بعدَ إسلامِهِم."},{"id":370,"title":"فَتْحُ عبدِ الله بن موسى جَزائِر البِلْيار وطَنْجَة .","date":["العام الهجري :89","العام الميلادي :707"],"text":"وَجَّه موسى ابنَه عبدَ الله لِغَزْو جُزُر البِلْيار، فافْتَتَح مَيورْقَة ومَنورْقَة وإيبيزا وأَدْخَلَها تحتَ حُكْم الدَّولة الأُمَويَّة، كما أَرسَل حَمَلات لِغَزْو سِرْدانِيَة وصِقِلِّيَّة، عادَت مُحَمَّلَة بالغَنائِم. كما اسْتَطاع فَتْحَ طَنْجَة، ولم يُبْقِ بذلك في المَغرِب الأقصى سِوَى سَبْتَة التي كانت تحت حُكْم يُولْيان القُوطي, واسْتَعمَل مَولاهُ طارِقَ بن زِياد على طَنْجَة."},{"id":371,"title":"غَزْو قُتيبَة بن مُسلِم بِلاد الصُّغْد ومُحاوَلَة فَتْح مَدينَة بُخارَى .","date":["العام الهجري :89","العام الميلادي :707"],"text":"غَزَا قُتيبَةُ بن مُسلِم بِلادَ الصُّغْد ونَسَف وكِشّ وقد لَقِيَه هنالك خَلْقٌ مِن الأَتراك فظَفَر بهم فقَتَلَهم، وسارَ إلى بُخارَى فلَقِيَه دونها خَلْقٌ كَثيرٌ مِن التُّرْك فقاتَلَهم يَوْمَين ولَيْلَتين عندَ مَكانٍ يُقالُ له خَرْقان وظَفَر بهم, ثمَّ قَصَد قُتيبةُ وَرْدانَ خُذاه مَلِك بُخارَى فقاتَلَه وَرْدان قِتالًا شَديدًا فلم يَظْفَر به قُتيبةُ، فرَجَع عنه إلى مَرْو فجاءَهُ البَريدُ بكِتابِ الحَجَّاج يُعَنِّفُه على الفِرار والنُّكول عن أَعداءِ الإسلام، وكَتَب إليه أن يَبْعَث بِصُورَة هذا البَلَد يعني بُخارَى، فبَعَث إليه بِصُورَتِها، فكَتَب إليه: أن ارْجِع إليها وتُبْ إلى الله مِن ذَنْبِك وائْتِها مِن مكان كذا وكذا، ورُدَّ وَرْدانَ خُذاه، وإيَّاكَ والتَّحْوِيط، ودَعْنِي وبُنَيَّات الطَّريق."},{"id":372,"title":"فَتْحُ قُتيبَة بن مُسلِم بُخارَى .","date":["العام الهجري :90","العام الميلادي :708"],"text":"سارَ قُتيبةُ بن مُسلِم إلى بُخارَى مَرَّةً أُخرى, فأَرسَل مَلِكُها يَسْتَنْصِر مَن حَولَه، ولكنَّ قُتيبةَ اسْتَطاع فَتْحَها هذه المَرَّة، ولمَّا فَتَحَها اسْتَأْذَنه نَيْزَك طَرْخان في الرُّجوع إلى بِلادِه -وكان نَيْزَك قد أَسلَم وسُمِّيَ بعبدِ الله- فأَذِنَ له، فرَجَع إلى طُخارِستان، فعَصى وكاتَبَ مَن حَولَه، وجَمَع الجُموعَ، فزَحَف إليه قُتيبةُ، وانْتَصَر عليهم بعدَ قِتالٍ شَديدٍ وحَرْبٍ يَشيبُ لها الوَليد، وذلك أنَّ مُلوكَهم كانوا قد اتَّعَدوا مع نَيْزَك في العام الماضي أن يَجْتَمِعوا ويُقاتِلُوا قُتيبةَ، وأن لا يُوَلُّوا عن القِتال حتَّى يُخْرِجوا العَربَ مِن بِلادِهم، فاجْتَمَعوا اجْتِماعًا هائِلًا لم يَجْتَمِعوا مِثلَه في مَوْقِف، فكَسَرَهُم قُتيبةُ وقَتَلَ منهم أُمَمًا كَثيرَة، وَرَدَّ الأُمورَ إلى ما كانت عليه، ثمَّ لا يَزال يَتَتَبَّع نَيْزَك خان مَلِكَ التُّركِ الأَعظَم مِن إقْليم، إلى إقْليم، ومِن كَوْرَة إلى كَوْرَة، ومِن رِسْتاق إلى رِسْتاق، ولم يَزَل ذلك دَأْبُه حتَّى حَصَرَه في قَلعَةٍ هنالك شَهرَين مُتَتابِعَين، حتَّى نَفَذَ ما عند نَيْزَك خان مِن الأَطْعِمَة، وأَشرَف هو ومَن معه على الهَلاكِ، فبَعَث إليه قُتيبَة مَن جاء به مُسْتَأْمِنًا مَذْمومًا مَخْذولًا، فسَجَنَه عنده ومَن معه, فاسْتَشار قُتيبةُ الأُمَراء في قَتْلِه، فاخْتَلَفوا عليه، فقائِلٌ يقول: اقْتُلْهُ. وقائِلٌ يقول: لا تَقْتُلْهُ. فقال له بَعضُ الأُمَراء: إنَّك أَعْطَيْتَ اللهَ عَهْدًا أنَّك إن ظَفَرت به لتَقْتُلَنَّه، وقد أَمْكَنَك اللهُ منه، فقال قُتيبةُ: والله إن لم يَبْقَ مِن عُمُري إلَّا ما يَسَعُ ثلاثَ كَلِمَات لأَقْتُلَنَّه، ثمَّ قال: اقْتُلوه. فقُتِل، جَزاءَ غَدْرِه ونَقْضِه الصُّلْحَ."},{"id":373,"title":"غَزْو موسى بن نُصَير جَزيرَتي مَيُورْقَة ومَنُورْقَة .","date":["العام الهجري :91","الشهر القمري : محرم","العام الميلادي :709"],"text":"افتتح موسى بن نصير جزيرتي مَيُورْقَة ومَنُورْقَة، وهما جَزيرَتان في البَحر بين جَزيرَة صِقِلِّيَّة وجَزيرَة الأَندَلُس؛ وتُسَمَّى هذه الغزوة غَزوَة الأَشْراف لِكَثرَة الأَشْراف الذين كانوا بها مِن أَشْراف العَرَب."},{"id":374,"title":"طَريف بن مالِك يُمَهِّد لِفَتح الأَندَلُس .","date":["العام الهجري :91","الشهر القمري : رمضان","العام الميلادي :710"],"text":"كانت بِدايَة فَتْح الأَندَلُس بأن يُولْيان حاكِم الجَزيرَة الخَضْراء غَضِبَ مِن لُذْريق (رُودْريغُو) مَلِك الأَندَلُس فاتَّفَق مع موسى بن نُصَير على أن يَدُلَّه على عَوْراتِهم ويُدْخِلَه الأَندَلُس, فكَتَب موسى إلى الوَليد يَسْتَأْذِنُه في غَزْو الأَندَلُس, فكَتَب إليه الوَليدُ: خُضْها بِالسَّرايا، ولا تُغَرِّر بالمسلمين في بِحْرٍ شَديدِ الأَهوال. فكَتَب إليه موسى: إنَّه ليس بِبَحْرٍ مُتَّسِع، وإنَّما هو خَليجٌ يَبِينُ ما وَراءَه. فكَتَب إليه الوَليدُ: أن اخْتَبِرْها بالسَّرايا، وإن كان الأَمْرُ على ما حَكَيْتَ. فبَعَث موسى رَجُلًا مِن مَوالِيه يُقالُ له طَريف بن مالِك أبو زُرْعَة في أربعمائة رَجُل ومعهم مائة فَرَسٍ، وهو أوَّلُ مَن دَخَل الأَندَلُس مِن المسلمين، فسار في أربع سَفائِن، فخَرَج في جَزيرَة بالأَندَلُس، سُمِّيَت جَزيرَة طَريف لِنُزولِه فيها، ثمَّ أَغارَ على الجَزيرَة الخَضْراء، فأَصابَ غَنيمَةً كَثيرَة، ورَجَع سالمَّا. فلمَّا رأى النَّاسُ ذلك تَسَرَّعوا إلى الغَزْو."},{"id":375,"title":"غَزْوُ قُتيبةَ بن مُسلِم سِجِسْتان .","date":["العام الهجري :92","العام الميلادي :710"],"text":"غَزَا قُتيبةُ بن مُسلِم سِجِسْتان، وأَراد قَصْدَ رتبيل الأعظَم، فلمَّا نَزَل قُتيبةُ سِجِسْتان أَرسَل رتبيل إليه رُسُلًا بالصُّلْح، فقَبِلَ ذلك وانْصَرف واسْتَعمَل عليهم عبدَ رَبِّه بن عبدِ الله اللَّيْثِيَّ."},{"id":376,"title":"غَزْوُ موسى بن نُصَير جَزيرَة سَرْدانِيَة .","date":["العام الهجري :92","العام الميلادي :710"],"text":"جَزيرَة في بَحرِ الرُّوم، وهي مِن أَكبَر الجَزائِر ما عَدا جَزيرَة صِقِلِّيَّة وأَقْرِيطِش، وهي كَثيرَة الفَواكِه، ولمَّا فَتَح موسى بِلادَ الأَندَلُس سَيَّرَ طائِفَةً مِن عَسكَرِه في البَحرِ إلى هذه الجَزيرَة فدَخَلوها، وعَمَدَ النَّصارى إلى ما لهم مِن آنِيَة ذَهَب وفِضَّة فأَلْقوا الجَميعَ في المِيناء الذي لهم، وجعلوا أَموالَهم في سَقْفٍ بَنوه للبَيْعَة العُظمى التي لهم تحت السَّقْف الأوَّل، وغَنِمَ المسلمون فيها ما لا يُحَدُّ ولا يُوصَف."},{"id":377,"title":"انْتِصار المسلمين على الأَسْبان في مَوقِعَة وادِي لَكَّة (شَذُونَة) .","date":["العام الهجري :92","الشهر القمري : رمضان","العام الميلادي :711"],"text":"بعدَ نَجاح غَزوَة طَريف بن مالِك بَعَث موسى بن نُصَير مَولاهُ على طَنْجَة طارِقَ بن زِياد في سَبعةِ آلاف مُقاتِل فسار فنَزَل في جَبَل مُنِيف يُعرَف إلى اليومِ بِجَبَلِ طارِق، ثمَّ دَخَل الجَزيرَة الخَضْراء ثمَّ تابَع مَسيرِه ومعه يُولْيان يَدُلُّه على طُرُق الأَندَلُس, ولمَّا بَلَغ لُذْرِيق (رودريغو) غَزْو طارِق بِلاده عَظُمَ ذلك عليه، وكان غائِبًا في غَزاتِه، فرَجَع منها وطارِق قد دَخَل بلاده، فجَمَع له جَمْعًا يُقالُ بَلَغ مائةَ ألف، فلمَّا بَلَغ طارِقًا الخَبَرُ كَتَب إلى موسى يَسْتَمِدُّه ويُخْبِرُه بما فَتَح، وأنَّه زَحَف إليه مَلِكُ الأندَلُس بما لا طاقةَ له به. فبَعَث إليه بخمسةِ آلاف، فتَكامَل المسلمون اثني عَشر ألفًا، ومعهم يُولْيان يَدُلُّهم على عَوْرَةِ البِلادِ، ويَتَجَسَّس لهم الأَخبارَ. فأَتاهُم لُذْرِيق في جُنْدِه، فالْتَقوا على نَهرِ لَكَّة مِن أَعمالِ شَذُونَة لِلَيْلَتَيْنِ بَقِيَتا مِن رَمضان سنة اثنتين وتِسعين، واتَّصَلت الحَرْبُ ثَمانِيَة أيَّام، فانْهَزموا وهَزَم اللهُ لُذْرِيق ومَن معه، وغَرِقَ لُذْرِيق في النَّهرِ، وسار طارِق إلى مَدينَة إسْتِجَة مُتَّبِعًا لهم، فلَقِيَه أَهلُها ومعهم مِن المُنهزِمين خَلْقٌ كَثيرٌ، فقاتَلوه قِتالًا شَديدًا، ثمَّ انْهَزَم أَهلُ الأندَلُس ولم يَلْقَ المسلمون بعدَها حَربًا مِثلَها. ونَزَل طارِق على عَيْن بينها وبين مَدينَة إسْتِجَة أَربعَة أَميال فسُمِّيَت عَيْن طارِق إلى الآن. لمَّا سَمِعَت القُوط بهاتين الهَزِيمَتَين قَذَف الله في قُلوبِهم الرُّعْبَ. فَرَّقَ طارِقُ بن زِياد جَيْشَه لِفَتْح المُدُن مِن مَدينَة إسْتِجَة، فبَعَث جَيْشًا إلى قُرْطُبَة، وجَيْشًا إلى غَرْناطَة، وجَيْشًا إلى مالَقَة، وجَيْشًا إلى تُدْمِير، وسار هو ومُعظَم الجَيْش إلى جَيَّان يُريدُ طُلَيْطُلَة، فلمَّا بَلَغَها وَجَدَها خالِيَة فَضَمَّ إليها اليَهودَ، وتَرَك معهم رِجالًا مِن أَصحابِه، ثمَّ مَضَى إلى مَدينَة ماية، فغَنِمَ منها ورَجَع إلى طُلَيْطُلة في سنة ثلاث وتِسعين. وقِيلَ: اقْتَحَم أَرضَ جِلِّيقِيَّة، فخَرَقَها حَتَّى انْتَهى إلى مَدينَة إِسْتَرْقَة، وانْصَرَف إلى طُلَيْطُلَة، ووافَتْهُ جُيوشُه التي وَجَّهَها مِن إسْتِجَة بعدَ فَراغِهم مِن فَتْحِ تلك المُدُن التي سَيَّرَهم إليها."},{"id":378,"title":"فتح قتيبة بن مسلم سمرقند .","date":["العام الهجري :93","العام الميلادي :711"],"text":"أَمَر قُتيبَة بن مُسلِم أخاه عبدَ الرحمن بالسَّيْرِ إلى الصُّغْد (سَمَرْقَنْد) وكانوا قد نَكَثوا العَهْد, ثمَّ لَحِقَ قُتيبةُ بِأَخيهِ فبَلَغَها بعدَه بثلاثٍ أو أَربَع، وقَدِمَ معه أَهلُ خَوارِزْم وبُخارَى فقاتَلَه أَهلُ الصُّغْد شَهْرًا مِن وَجْهٍ واحِد وهُم مَحْصورون، وخاف أَهلُ الصُّغْد طُولَ الحِصار فكَتَبوا إلى مَلِك الشَّاش وخاقان وأَخْشاد فَرْغانَة لِيُعينوهم، فلمَّا عَلِمَ بذلك قُتيبةُ أَرسَل إليهم سِتِّمائة يُوافونَهُم في الطَّريق فقَتَلوهُم ومَنعوهُم مِن نُصْرَتِهم ولمَّا رَأَى الصُّغْد ذلك انْكَسَروا، ونَصَبَ قُتيبةُ عليهم المَجانِيقَ فَرَماهُم وثَلِمَ ثُلْمَةً، فلمَّا أَصبَح قُتيبةُ أَمَر النَّاسَ بالجِدِّ في القِتالِ، فقاتَلوهُم واشْتَدَّ القِتالُ، وأَمَرهُم قُتيبةُ أن يَبْلُغوا ثُلْمَةَ المَدينَة، فجَعَلوا التِّرَسَةَ على وُجوهِهم وحَمَلوا فبَلَغوها ووَقَفوا عليها، ورَماهُم الصُّغْد بالنِّشابِ فلم يَبْرَحوا، فأَرسَل الصُّغْد إلى قُتيبةَ فقالوا له: انْصَرِف عَنَّا اليومَ حتَّى نُصالِحَك غَدًا. فقال قُتيبةُ: لا نُصالِحُهم إلَّا ورِجالُنا على الثُّلْمَة. وقِيلَ: بل قال قُتيبةُ: جَزَعَ العَبيدُ، انْصَرِفوا على ظَفَرِكُم. فانْصَرَفوا فصالَحَهم مِن الغَدِ على ألفي ألف ومائتي ألف مِثْقال في كُلِّ عامٍ، وأن يُعْطوه تلك السَّنَة ثلاثينَ ألف فارِس، وأن يُخْلُوا المَدينَة لِقُتيبةَ فلا يكون لهم فيها مُقاتِل، فيَبْنِي فيها مَسجِدًا ويَدخُل ويُصَلِّي ويَخْطُب ويَتَغَدَّى ويَخْرُج، فلمَّا تَمَّ الصُّلْحُ وأَخْلوا المَدينةَ وبَنوا المَسجِدَ دَخَلَها قُتيبةُ في أَربعَة آلاف انْتَخَبَهم، فدَخَل المَسجِد فصَلَّى فيه وخَطَب وأَكَل طَعامًا، ثمَّ أَرسَل إلى الصُّغْد: مَن أَراد مِنكم أن يَأخُذ مَتاعَه فَلْيَأْخُذ فإنِّي لَسْتُ خارِجًا منها، ولَستُ آخُذ منكم إلَّا ما صالَحْتُكم عليه، غيرَ أنَّ الجُنْدَ يُقيمون فيها. وقِيلَ: إنَّه شَرَطَ عليهم في الصُّلْحِ مائة ألف فارِس، وبُيوت النِّيران، وحِلْيَة الأَصْنام، فقَبَضَ ذلك، وأُتِيَ بالأصنامِ فكانت كالقَصْرِ العَظيمِ وأَخَذَ ما عليها وأَمَر بها فأُحْرِقَت. فجاءه غَوْزَك فقال: إنَّ شُكْرَكَ عَلَيَّ واجِبٌ، لا تَتَعَرَّض لهذه الأَصنامِ فإنَّ منها أَصنامًا مَن أَحْرَقَها هَلَكَ. فقال قُتيبةُ: أنا أَحْرِقُها بِيَدِي، فدَعَا بالنَّارِ فكَبَّر ثمَّ أَشْعَلَها فاحْتَرَقَت، فوجدوا مِن بَقايا مَسامِير الذَّهَب خَمسين ألف مِثْقال."},{"id":379,"title":"موسى بن نُصَير يَأْمُر بالتَّوَقُّف عن التَّوَغُّل في بِلادِ الأندَلُس .","date":["العام الهجري :93","العام الميلادي :711"],"text":"بعدَ أن تَوَغَّل طارِقُ بن زِياد في الأَندَلُس وفَتَحَ الله على يَديهِ ما شاء الله كَتَبَ بذلك إلى موسى بن نُصَير فأَمَرَهُ أن يَبْقى مَكانَه حتَّى يَأتِيَه."},{"id":380,"title":"موسى بن نُصَير يستأنف فُتوحات بَقِيَّة مُدُن الأَندَلُس .","date":["العام الهجري :93","العام الميلادي :711"],"text":"كان موسى بن نُصَير قد غَضِبَ على مَولاهُ طارِق بِسَبَب تَوَغُّلِه في أَرضِ العَدُوِّ, فاسْتَخْلَف على أفريقيا ابنَه عبدَ الله بن موسى، ثمَّ دَخَل الأَندَلُس وبَقِيَ فيها سَنتَيْنِ يَفتَح البُلْدان ويَغْنَم حتَّى صارت الأَندَلُس تحت سَيْطَرَتِه, عَبَرَ موسى إلى الأَندَلُس في جَمْعٍ كَثيرٍ قِوامُه ثَمانِيَة عشر ألفًا، فتَلَقَّاهُ طارِق وتَرَضَّاهُ، فرَضِيَ عنه وقَبِلَ عُذْرَه وسَيَّرَهُ إلى طُلَيْطُلَة، وهي مِن عِظام بِلادِ الأَندَلُس، وهي مِن قُرْطُبَة على عِشرين يومًا، ففَتَحَها ثمَّ فَتَحَ المُدَنَ التي لم يَفتَحها طارِق كشَذونَة، وقَرْمونَة، وإشْبِيلِيَة، ومارِدَة."},{"id":381,"title":"وَفاةُ أَنَس بن مالِك رَضِيَ الله عنه .","date":["العام الهجري :93","العام الميلادي :711"],"text":"هو أَحَدُ المُكْثِرين مِن الرِّواية عن النَّبِيِّ صلَّى الله عليه وسلَّم، وليس بِغَريبٍ فهو خادِمُ النَّبِيِّ صلَّى الله عليه وسلَّم، دَعَا له النَّبِيُّ صلَّى الله عليه وسلَّم بِطُولِ العُمُر والبَرَكَة في المالِ والوَلَدِ، فكان له الكَثيرُ مِن الأوَّلادِ زادوا على المائة، وقِيلَ: كان له بُستانٌ يُثْمِرُ مَرَّتَيْنِ في السَّنَة. وكان سَكَنَ البَصْرَةَ وبَقِيَ فيها إلى أن تُوفِّي فيها، وهو آخِرُ الصَّحابَة مَوْتًا فيها، وكان قد آذاهُ الحَجَّاجُ فكَتَبَ إلى عبدِ الملك يَشْتَكِيه فكَتَبَ عبدُ الملك إلى الحَجَّاجِ فاعْتَذَر له وأَحسَن إليه، فرَضِيَ اللهُ عن أَنَسٍ خادِم النَّبِيِّ صلَّى الله عليه وسلَّم وأَرْضاهُ."},{"id":382,"title":"الوَليد بن عبد الملك يعزل عُمَر بن عبدِ العزيز عن وِلايَة المَدينَة .","date":["العام الهجري :93","الشهر القمري : شوال","العام الميلادي :712"],"text":"كان سَبَب ذلك أنَّ عُمَر بن عبدِ العزيز كَتَبَ إلى الوَليد يُخْبِرُه عن أَهلِ العِراق أنَّهم في ضَيْمِ وضِيقٍ مع الحَجَّاجِ مِن ظُلْمِه وغَشْمِه، فسَمِع بذلك الحَجَّاجُ فكَتَبَ إلى الوَليد: إنَّ عُمَر ضَعيف عن إِمْرَةِ المَدينَة، وإنَّ جماعَة مِن أَهلِ الشِّقاق مِن أهلِ العِراق قد لَجَأوا إلى المَدينَة ومَكَّة، وهذا وَهْنٌ وضَعْفٌ في الوِلايَة، فاجْعَل على الحَرَمَيْنِ مَن يَضْبُط أَمْرَهُما. فكَتَبَ الوَليدُ إلى الحَجَّاج: أن أَشِرْ عَلَيَّ بِرَجُلينِ. فكَتَب إليه يُشِيرُ عليه بعُثمان بن حَيَّان، وخالِد بن عبدِ الله، فوَلَّى خالِدًا مَكَّة، وعُثمانَ المَدينَة، وعَزَل عُمَر بن عبدِ العزيز، فخَرَج عُمَرُ بن عبدِ العزيز مِن المَدينَة في شَوَّال فنَزَلَ السُّويْداء، وقَدِمَ عُثمانُ بن حَيَّان المَدينَة لِلَيْلَتَيْنِ بَقِيَتا مِن شَوَّال مِن هذه السَّنَة."},{"id":383,"title":"وَفاةُ أبي بَكْرِ بن عبدِ الرَّحمن أَحَد الفُقَهاء السَّبعَة في المَدينَة .","date":["العام الهجري :94","العام الميلادي :712"],"text":"هو أبو بَكْرِ بن عبدِ الرَّحمن بن الحارِث بن هِشام أَحَد الفُقَهاء السَّبعَة بالمَدينَة، كان ثِقَةً، فَقِيهًا، عالِمًا سَخِيًّا، كَثيرَ الحَديثِ، حَدَّث عن عَدَدٍ مِن الصَّحابَة كأَبيهِ، وعائِشَةَ، وأبي هُريرَةَ، وعَمَّارِ بن ياسِر، وغَيرِهم، جَمَعَ العِلْمَ والعَمَل والشَّرَف، وكان ممَّن خَلَفَ أَباهُ في الجَلالَة، كان يُقالُ له: رَاهِب قُريشٍ. لِكَثْرَةِ صَلاتِه، وكان مَكْفوفًا كَثيرَ الصَّوْم، تُوفِّي في المَدينَة."},{"id":384,"title":"فَتْحُ قُتيبةَ بن مُسلِم كابُل .","date":["العام الهجري :94","العام الميلادي :712"],"text":"بعدَ أن غَزَا قُتيبةُ بن مُسلِم الشَّاش وفَرْغانَة، وفَرَغَ مِن الصُّغْد، وفَتَحَ سَمَرْقَنْد، خاض بِلادَ التُّرْك يَفتَح فيها حتَّى وَصَل إلى كابُل فحاصَرَها وافْتَتَحَها، وقد لَقِيَه المُشرِكون في جُموعٍ هائِلَة مِن التُّرْك فقاتَلَهم قُتيبةُ عندِ خُجَنْدَة فكَسَرَهم مِرارًا وظَفَر بهم، وأَخَذ البِلادَ منهم، وقَتَل منهم خَلْقًا وأَسَر آخَرِين وغَنِمَ أَموالًا كَثيرةً جِدًّا."},{"id":385,"title":"وَفاةُ زَيْنِ العابِدِين عَلِيِّ بن الحُسين .","date":["العام الهجري :94","العام الميلادي :712"],"text":"هو عَلِيّ زَيْنُ العابِدِين بن الحُسين بن عَلِيِّ بن أبي طالِب، أُمُّهُ بِنتُ يَزْدَجِرْد آخِر مُلوك فارِس، مِن الفُقَهاء الحُفَّاظ كان مَضْرَب المَثَلِ في الحِلْمِ والوَرَعِ والجُودِ والتَّواضُع، مَدَحَهُ الفَرزدَقُ بالقَصيدَة المَشهورَة التي مَطلعُها: هذا الذي تَعرِف البَطحاءُ وَطأتَهُ والبَيتُ يَعرِفُه والحِلُّ والحَرَمُ، تُوفِّي في أوَّلِ هذه السَّنَة يعني سَنَة 94هـ، وصُلِّيَ عليه بالبَقيعِ ودُفِنَ فيه، فرَحِمَه اللهُ رَحمةً واسِعَة، وجَزاهُ الله عن المسلمين خيرًا."},{"id":386,"title":"وَفاةُ عُرْوَة بن الزُّبير أَحَد الفُقَهاء السَّبعَة في المَدينَة .","date":["العام الهجري :94","العام الميلادي :712"],"text":"هو عُروَة بن الزُّبير بن العَوَّام، أَحَد الفُقَهاء السَّبعَة في المَدينَة، كان عالِمًا كَريمًا، رَوَى الحَديثَ عن كَثيرٍ مِن الصَّحابَة، تَفَقَّه على خالَتِه عائِشَة رَضِيَ الله عنها، انْتَقَل إلى البَصْرَة ثمَّ إلى مِصْرَ ثمَّ عاد إلى المَدينَة وتُوفِّي فيها، وهو الذي أُصِيبَت رِجْلُهُ بِمَرَضِ الآكال (الغرغرينا) فنُشِرَت وقُطِعَت وهو يَقرأُ القُرآن، وتُوفِّي له بِنَفْسِ اليَومِ أَحَبُ أوَّلادِه، فما تَسَخَّطَ ولا تَضَجَّرَ رَحِمَه الله تعالى."},{"id":387,"title":"وَفاةُ سَعيد بن المُسَيِّب أَحَد الفُقَهاء السَّبعَة في المَدينَة .","date":["العام الهجري :94","الشهر القمري : جمادى الأولى","العام الميلادي :713"],"text":"هو أَحَدُ الفُقَهاء السَّبْعة في المَدينَة (ومنهم مَن يَعُدُّ بَدَلَهُ سالِمَ بن عبدِ الله بن عُمَرَ)، سَيِّد التَّابِعين، جَمَع بين الحَديثِ والفِقْهِ والوَرَعِ والزُّهْدِ، رَوَى مَراسِيل عن النَّبِيِّ صلَّى الله عليه وسلَّم كَثيرةً، كان الحَسَنُ البَصريُّ إذا أُشْكِلَ عليه شَيءٌ كَتَبَ إليه يَسألُه، كان يَحفَظ أَحكامَ عُمَرَ بن الخَطَّاب وأَقْضِيَتَهُ، كان مَهِيبًا عند الخُلَفاء، تَعَرَّض للأَذَى بسَببِ البَيْعَة بِوِلايَة العَهْد للوَليد بن عبدِ الملك، وضُرِبَ بِسَببِ ذلك بالسِّياطِ، وتُوفِّي في المَدينَة رَحِمَه الله تعالى وجَزاهُ عن المسلمين خيرًا."},{"id":388,"title":"مَقْتَل سَعيد بن جُبَير .","date":["العام الهجري :94","الشهر القمري : رمضان","العام الميلادي :713"],"text":"هو سَعيدُ بن جُبَير بن هِشام الأَسَدِيُّ الوالِبِيُّ مَوْلاهُم الكوفيُّ، أبو محمَّد، كان وِعاءًا مِن أَوْعِيَة العِلْم, قال خُصَيف: كان أَعْلَمَهم بالقُرآن مُجاهِد، وأَعْلَمَهم بالحَجِّ عَطاء، وأَعْلَمَهم بالحَلال والحَرام طاووس، وأَعْلَمَهم بالطَّلاق سَعيد بن المُسَيِّب، وأَجْمَعَهم لِهذه العُلوم سَعيد بن جُبير. لقد مات سَعيد بن جُبَير وما على ظَهْر الأرضِ رَجُل إلَّا يَحتاجُ إلى عِلْمِ سَعيد, وكان ابنُ جُبَير يقول بعدَ أن تَخَفَّى عن الحَجَّاج: (وَدِدْتُ لو أنَّ النَّاس أَخَذوا ما عِندي مِن العِلْم فإنَّه ممَّا يُهِمُّني). كان سَبَبَ قَتْلِ الحَجَّاج لابنِ جُبَير خُروجُه مع عبدِ الرَّحمن بن محمَّد بن الأشعث، وكان الحَجَّاج قد جَعَله على عَطاء الجُنْد حين وَجَّه ابنَ الأشعث إلى مَلِك التُّرْك رتبيل لِقِتالِه، فلمَّا خَلَعَ ابنُ الأَشعث الحَجَّاجَ كان سَعيدُ بن جُبَير فيمَن خَلَعَ، فلمَّا هُزِمَ ابنُ الأشعث ودَخَل بِلادَ رتبيل هَرَب سَعيد بن جُبَير إلى أَصْبَهان، فكَتَب الحَجَّاجُ إلى عامِلِهِ بِأَخْذِ سَعيد بن جُبَير، فخَرَج العامِل مِن ذلك بأن أَرسَل إلى سَعيد يُعَرِّفُه ذلك ويَأمُره بمُفارَقَتِه، فسارَ عنه فأَتَى أَذْرَبِيجان فطالَ عليه القِيامُ فاغْتَمَّ بها، وقد تَخَفَّى ابنُ جُبَير عن الحَجَّاج اثنا عَشَر سَنَةً، كان يَحُجُّ ويَعْتَمِر في كُلِّ سَنَةٍ فَتْرَةَ تَخفِّيه إلى أن خرج في مكَّة, فكان بها إلى أن وَلِيَها خالدُ بن عبد الله القَسري، فأشار مَن أشار على سَعيد بالهَرَب منها، فقال سَعيدٌ: والله لقد اسْتَحْيَيْتُ مِن الله، مم أَفِرُّ، ولا مَفَرَّ مِن قَدَرِهِ. فأَرسلَه خالدٌ القَسري إلى الحَجَّاج، ثمَّ إنَّ الحَجَّاج قَتَلَه، وقِصَّتُه مَشهورَة، ولم يَبْقَ الحَجَّاج بعدَ قَتلِه كَثيرًا، وكان يقول بعدَ ذلك: مالي ولابنِ جُبَير. فرَحِمَ الله سَعيدَ بن جُبَير."},{"id":389,"title":"المسلمون يَفْتَحون بِلادَ السِّنْد .","date":["العام الهجري :95","العام الميلادي :713"],"text":"لمَّا مات الحَجَّاجُ بن يُوسُف كان محمَّد بن القاسِم بالمُلْتان، فأتاهُ خَبَرُ وَفاتِه، فرَجَع إلى الرُّور والبَغْرور، وكان قد فَتَحَهُما، فأَعْطَى النَّاسَ، ووَجَّهَ إلى البَيْلَمان جَيْشًا فلم يُقاتِلوا وأَعطوا الطَّاعَةَ، وسَألَه أَهلُ سُرَشْت، وهي مَغْزَى أَهلِ البَصْرَة، وأَهلُها يَقطَعون في البَحرِ، ثمَّ أَتَى محمَّدٌ الكَيْرَجَ فخَرَج إليه دَوْهَر فقاتَلَه فانْهَزَم دَوْهَر وهَرَب، وقِيلَ: بل قُتِلَ. ونَزَل أَهلُ المَدينَة على حُكْم محمَّدٍ فقَتَل وسَبَى."},{"id":390,"title":"وَفاةُ الحَجَّاجِ بن يُوسُف الثَّقَفي .","date":["العام الهجري :95","الشهر القمري : رمضان","العام الميلادي :714"],"text":"هو أبو محمَّد الحَجَّاجُ بن يُوسُف الثَّقَفي، قائِدٌ أُمَوِيٌّ، داهِيَة، سَفَّاك، خَطِيب، وُلِدَ وَنَشأَ في الطَّائِف، وانْتَقَل إلى الشَّام فلَحِقَ بِرَوْحِ بن زِنْباع نائِب عبدِ الملك بن مَرْوان فكان في عِدادِ شُرْطَتِه، ثمَّ ما زال يَظهَر حتَّى قَلَّدَهُ عبدُ الملك أَمْرَ عَسْكَرِهِ, ثمَّ أَصبَح والِيًا على العِراق مِن قِبَل عبدِ الملك بن مَرْوان، أَصلَح البِلادَ في العِراق واعْتَنَى بها، وازْدَهَرَت في عَصرِه التِّجارَة والصِّناعَة، وكان مَعروفًا بالظُّلْمِ، وسَفْكِ الدِّماء، وانْتِقاص السَّلَف، وتَعَدِّي حُرُماتِ الله بأَدْنَى شُبْهَة، وقد أَطْبَقَ أَهلُ العِلْم بالتَّارِيخ والسِّيَر على أَنَّه كان مِن أَشَدِّ النَّاس ظُلْمًا، وأَسْرَعِهم للدَّمِ الحَرامِ سَفْكًا، ولم يَحفَظ حُرْمَةَ رَسولِ الله صلَّى الله عليه وسلَّم في أَصحابِه، ولا وَصِيَّتَه في أَهلِ العِلْم والفَضْل والصَّلاح مِن أَتْباعِ أَصحابِه.  وكان جَبَّارًا عَنيدًا. قالت أَسماءُ بِنتُ أبي بَكْرٍ رضي الله عنها للحَجَّاجِ: إنَّ رَسولَ الله صلَّى الله عليه وسلَّم حَدَّثَنا «أنَّ في ثَقِيفٍ كَذَّابًا ومُبِيرًا». فأمَّا الكَذَّابُ فقد رَأَيْناهُ -تَعْنِي المُخْتار- وأمَّا المُبِيرُ فأَنت هو. والمُبِيرُ: المُهْلِك، الذي يُسْرِف في إِهْلاكِ النَّاس. نَشأَ الحَجَّاجُ شابًّا لَبِيبًا فَصيحًا بَليغًا حافِظًا للقُرآن، وكان يُكْثِر تِلاوَةَ القُرآن، ويَتَجَنَّب المَحارِم، ولم يَشْتَهِر عنه شَيءٌ مِن التَّلَطُّخ بالفُروج، وإن كان مُتَسَرِّعًا في سَفْكِ الدِّماءِ، كان فيه سَماحَةً بإعطاءِ المالِ لِأَهلِ القُرآن، فكان يُعطي على القُرآن كَثيرًا، ولمَّا مات لم يَتْرُك فيما قِيلَ إلَّا ثلاثمائة دِرْهَم. بَلَغَ ما قَتَل الحَجَّاجُ صَبْرًا مائة ألف وعشرين ألف، قال عنه الذهبي: \"نَسُبُّهُ ولا نُحِبُّه؛ بل نُبْغِضُه في الله؛ فإنَّ ذلك مِن أَوْثَقِ عُرَى الإيمان, وله حَسَنات مَغْمورة في بَحْرِ ذُنوبِه، وأَمْرُهُ إلى الله. وله تَوْحِيد في الجُمْلَة، ونُظَراء مِن ظَلَمَةِ الجَبابِرَة والأُمَراء\" لمَّا حَضَرتُه الوَفاةُ اسْتَخْلَف على الصَّلاةِ ابنَه عبدَ الله، واسْتَخْلَف على حَربِ الكوفَة والبَصْرَة يَزيدَ بن أبي كَبْشَة، وعلى خَراجِهِما يَزيدَ بن أبي مُسلِم، فأَقَرَّهُما الوَليدُ بعدَ مَوتِه، ولم يُغَيِّر أَحَدًا مِن عُمَّالِ الحَجَّاج."},{"id":391,"title":"غَزْوُ قُتيبةَ بن مُسلِم بِلاد الصِّين وفرض الجِزْيَة على مَلِكِها .","date":["العام الهجري :96","العام الميلادي :714"],"text":"غَزَا قُتيبةُ بن مُسلِم كاشْغَر, وهي أَدْنَى مَدائِن الصِّين، وحَمَل مع النَّاسِ عِيالَهُم لِيَضَعَهُم في سَمَرْقَنْد فلمَّا بَلَغ النَّهْرَ اسْتَعمَل رَجُلًا مِن مَوالِيه يُقالُ له الخَوارِزْمي على مَقْطَع النَّهْر، وقال: لا يَجُوزَنَّ أَحَدٌ إلَّا بِجَوازٍ منه، ومَضَى إلى فَرْغانَة، وأَرسَل مَن يُسَهِّل له الطَّريقَ إلى كاشْغَر، وبَعَث جَيْشًا مع كَبيرِ بن فُلان إلى كاشْغَر، فغَنِمَ وسَبَى سَبْيًا، فخَتَمَ أَعْناقَهُم، وأَوْغَل حتَّى بَلَغ قَرِيبَ الصِّين، ثمَّ بَعَث قُتيبةُ إلى مَلِك الصِّين رُسُلًا يَتَهَدَّدُه ويَتَوَعَّدُه ويُقْسِم بالله لا يَرجِع حَتَّى يَطَأَ بِلادَه ويَخْتِم مُلوكَهُم وأَشْرافَهُم، ويَأخُذ الجِزْيَةَ منهم أو يَدخُلوا في الإسلام. فكَتَب إليه مَلِكُ الصِّين: أن ابْعَث إِلَيَّ رَجُلًا شَريفًا يُخْبِرُني عنكم وعن دِينِكُم. فانْتَخَب قُتيبةُ عَشرةً لهم جَمالٌ وأَلْسُن وبَأْسٌ وعَقْلٌ وصَلاحٌ، فأَمَر لهم بِعُدَّةٍ حَسَنَة، ومَتاعٍ حَسَن مِن الخَزِّ والوَشْي وغَيرِ ذلك، وخُيولٍ حَسَنَة، وكان منهم هُبيرَةُ بن مُشَمْرِج الكِلابي، فقال لهم: إذا دَخَلْتُم عليه فأَعْلِموه أَنِّي قد حَلَفْتُ أَنِّي لا أَنْصَرِف حَتَّى أَطَأَ بِلادَهم، وأَخْتِم مُلوكَهُم وأَجْبِي خَراجَهُم. سار الوَفْدُ وعليهم هُبيرَة، فلمَّا دَخَلوا على المَلِك وَجَدوا مَمْلَكَة عَظِيمَة حَصِينَة ذاتَ أَنهارٍ وأَسواقٍ وحُسْنٍ وبَهاءٍ، فدَخَلوا عليه في قَلْعَة عَظِيمَة حَصِينَة، بِقَدْرِ مَدينَةٍ كَبيرَة، فقال المَلِكُ لِتُرْجُمانِه: قُل لهم: ما أنتم؟ وما تُريدون؟ فقالوا: نحن رُسُل قُتيبةَ بن مُسلِم، وهو يَدعوك إلى الإسلامِ، فإن لم تَفعَل فالجِزْيَة، فإن لم تَفعَل فالحَرْب, فأَعطَى الجِزْيَة فقَبِلَها منه قُتيبةُ."},{"id":392,"title":"وَفاةُ إِبراهيمَ النَّخَعِيِّ .","date":["العام الهجري :96","العام الميلادي :714"],"text":"هو إِبراهيمُ بن يَزيدَ بن قَيسٍ النَّخَعِيُّ، فَقِيهُ العِراق وأَحَدُ الأئِمَّة المَشهورين، تابِعِيٌّ أَدرَك عَددًا مِن الصَّحابَة لكن لا يُعرَف له سَماعٌ عنهم، وأَخَذ عن كِبارِ التَّابِعين، تَزَعَّمَ مَدرَسةَ ابنِ مَسعودٍ في الكوفَة، حيث أَخَذ عن خالِه الأَسوَدِ بن يَزيدَ تِلميذ ابنِ مَسعود، وعن عَلْقَمَة، ومَسروق، وعبدِ الرَّحمن بن عبدِ الله بن مَسعود، وعليه تَتَلْمَذ حَمَّادُ بن سُليمان شَيخُ أبي حَنيفَة، وتَأَثَّر به وبِفِقْهِهِ أبو حَنيفَة، كان مُفْتِي أَهلِ الكوفَة هو والشَّعْبِيّ في زَمانِهِما، وكان رَجُلًا صالِحًا، فَقِيهًا، مُتَوَقِّيًا، قَليلَ التَّكَلُّف، كان سعيدُ بن جُبَير يقول: أَتَسْتَفْتُوني وفِيكُم إِبراهيمُ. وكان الشَّعْبِيُّ يقول: والله ما تَرَكَ بَعدَه مِثلَه، تُوفِّي وهو ابنُ تِسْعٍ وأَربعين سَنَة. وقِيلَ: ابنُ نَيْفٍ وخَمسين سَنَة."},{"id":393,"title":"وفاةُ الوليد بن عبد الملك وتولِّي أخيه سليمان الخِلافَة .","date":["العام الهجري :96","العام الميلادي :714"],"text":"توفي الوليد بن عبدالملك في هذا العام وتولَّى أخوه سليمان من بعده الخلافة وبُويع له في اليوم الذي توفِّي فيه الوليد، وكان قويًا كريمًا محبوبًا."},{"id":394,"title":"تَمَرُّد قُتيبةَ بن مُسلِم الباهِلِي  .","date":["العام الهجري :96","العام الميلادي :714"],"text":"لمَّا أَرادَ الوَليدُ بن عبدِ المَلِك أن يَنْزِع أَخاهُ سُليمان مِن وِلايَة العَهْد ويَجعَل بَدَلَه ابنَه عبدَ العَزيز، أَجابَه إلى ذلك الحَجَّاجُ وقُتيبةُ على ما تَقَدَّم، فلمَّا مات الوَليدُ ووَلِيَ سُليمانُ خافَهُ قُتيبةُ، وخاف أن يُوَلِّي سُليمانُ يَزيدَ بن المُهَلَّب خُراسان، فكَتَب قُتيبةُ إلى سُليمانَ كِتابًا يُهَنِّئُه بالخِلافَة، ويَذكُر بَلاءَهُ وطاعَتَه لِعبدِ الملك والوَليدِ، وأنَّه له على مِثلِ ذلك إن لم يَعْزِله عن خُراسان، وكَتَب إليه كِتابًا آخَر يُعلِمه فيه فُتوحَه ونِكايَتَه، وعِظَمَ قَدْرِهِ عند مُلوكِ العَجَم وهَيْبَتَه في صُدورِهِم، وعِظَمَ صَوْلَتِه فيهم، ويَذُمُّ أَهلَ المُهَلَّب ويَحلِف بالله لَئِن اسْتَعمَل يَزيدَ على خُراسان لَيَخْلَعَنَّه. وكَتَب كِتابًا ثالِثًا فيه خَلْعُه، ثمَّ أَعلَن قُتيبةُ خَلْعَ سُليمان، ثمَّ صار بينه وبين قُوَّادِ جُيوشِه خِلافٌ، فقام وَكيعُ بن حَسَّان التَّميمي بِقَتْلِه وقَتَلَ معه أَحَدَ عشر مِن أَهلِ بَيتِه."},{"id":395,"title":"تَكامُل بِناء الجامِع الأُمَوِيِّ .","date":["العام الهجري :96","العام الميلادي :714"],"text":"كان الوَليدُ بن عبدِ الملك قد بَدَأَ بِتَأْسِيس البِناء للمَسجِد الأُمَوي في 87هـ إلى أن اكْتَمَل بِناؤُه في هذه السَّنَة, وكان أَصْلُ مَوضِع هذا الجامِع قَديمًا مَعْبَدًا بَنَتْهُ اليُونان الكُلْدَانِيُّون الذين كانوا يُعَمِّرون دِمَشْق، وهُم الذين وَضَعوها وعَمَّروها أوَّلًا، فَهُم أوَّلُ مَن بَناها، وقد كانوا يَعبدون الكَواكِب السَّبعَة المُتَمَيِّزَة، ثمَّ إنَّ النَّصارَى حَوَّلوا بِناءَ هذا المَعْبَد الذي هو بِدِمَشق مُعَظَّمًا عند اليُونان فجَعَلوه كَنيسَةَ يُوحَنَّا، وكان المسلمون والنَّصارَى يَدخُلون هذا المَعْبَد مِن بابٍ واحِد، وهو باب المَعْبَد الأَعلى مِن جِهَة القِبْلَة، مَكانَ المِحْراب الكَبير الذي في المَقْصورَة اليومَ، فيَنْصَرِف النَّصارَى إلى جِهَة الغَربِ إلى كَنيسَتِهم، ويَأخُذ المسلمون يَمْنَةً إلى مَسجِدِهم، ولا يَستَطيع النَّصارَى أن يَجْهَروا بِقِراءَة كِتابِهِم، ولا يَضْرِبوا بِناقُوسِهِم، إِجلالًا للصَّحابَة ومَهابَةً وخَوْفًا، ثمَّ قام الوَليدُ بِتَوسيعِها آخِذًا القِسْمَ النَّصراني وحَوَّلَه إلى مَسجِد كما هو معروف اليوم، وأَنْفَق في ذلك الأَموالَ الكَثيرَة جِدًّا، واسْتَعمَل العُمَّال والبَنَّائِين المَهَرَة, والمَقصود أنَّ الجامِع الأُمَوي لمَّا كَمُلَ بِناؤُه لم يكُن على وَجْهِ الأَرضِ بِناءٌ أَحْسَن منه، ولا أَبْهَى ولا أَجْمَل منه، بحيث إنَّه إذا نَظَر النَّاظِرُ إليه أو إلى جِهَةٍ منه أو إلى بُقْعَةٍ أو مَكانٍ منه تَحَيَّر فيها نَظَرُهُ لِحُسْنِه وجَمالِه، ولا يَمَلُّ نَاظِرُهُ؛ بل كُلمَّا أَدْمَنَ النَّظَرَ بانَت له أُعْجوبَة ليست كالأُخرَى."},{"id":396,"title":"وَفاةُ قُتيبةَ بن مُسلِم الباهِلِي .","date":["العام الهجري :96","العام الميلادي :714"],"text":"هو الأَميرُ أبو حَفْص قُتيبةُ بن مُسلِم بن عَمرِو بن حُصَين بن رَبيعَة الباهلي، أَحَدُ الأَبطال والشُّجْعان، ومِن ذَوِي الحَزْمِ والدَّهاءِ والرَّأْيِ والغَنَاءِ، كان مِن سادات الأُمَراء وخِيارِهم، وكان مِن القادَة النُّجَباء الكُبَراء، والشُّجْعان وذَوِي الحُروبِ والفُتوحات السَّعيدَة والآراء الحَميدَة، وهو الذي فَتَح خَوارِزْمَ وبُخارَى، وسَمَرْقَنْد، وكانوا قد نَقَضوا وارْتَدُّوا، ثمَّ إنَّه افْتَتَح فَرْغانَة، وبِلادَ التُّرْك، وقد هَدَى الله على يَديهِ خَلْقًا لا يُحصِيهم إلَّا الله، فأَسلَموا ودانوا لله عَزَّ وجَلَّ، وفَتَح مِن البِلادِ والأقاليم الكِبار والمُدُن العِظام شَيْئًا كَثيرًا، والله سُبحانَه لا يُضَيِّع سَعْيَهُ ولا يُخَيِّب تَعَبَه وجِهادَه, وكانت وَفاتُه بِفَرْغانَه مِن أَقصى بِلادِ خُراسان، كان قُتيبَة يَفتَح في بِلادِ المَشرِق, وموسى بن نُصيَر يَفتَح في بِلادِ المَغرِب، فجَزاهُما الله خيرًا، فكِلاهُما فَتَح مِن الأقاليم والبُلْدان شَيْئًا كَثيرًا، كان فيمَن قُتِلَ أَبوهُ مع مُصعَب بن الزُّبير، وكانت وِلايتُه على خُراسان عَشر سِنين، وله رِوايَة عن عِمْران بن حُصَين، وأبي سَعيدٍ الخُدْرِيِّ. لمَّا بَلَغَه مَوتُ الوَليد نَزَعَ الطَّاعَة، فاخْتَلَفَ عليه جَيْشُه، وقام عليه وَكيعُ بن حَسَّان التَّميمي وأَلَّبَ عليه، ثمَّ شَدَّ عليه في عَشرة مِن فُرْسان تَميم فقَتَلوه, وكان عُمُرُهُ ثَمانِيًا وأربعين سَنَة، وقد سَبَق له مِن الأعمال الصَّالِحَة ما قد يُكَفِّر الله به سَيِّئاته، ويُضاعِف به حَسَناته، والله يُسامِحه ويَعفُو عنه، ويَتَقَبَّل منه ما كان يُكابِده مِن مُناجَزة الأعداء."},{"id":397,"title":"الأمويون يبدأون بتَجْهيز الجُيوش لِغَزْو القُسطنطينيَّة .","date":["العام الهجري :97","العام الميلادي :715"],"text":"جَهَّزَ سُليمانُ بن عبدِ الملك أَميرُ المؤمنين أَخاهُ مَسلمَة بن عبدِ الملك لِغَزْوِ القُسطنطينيَّة وَراء الجَيْش الذين هُم بها، فسار إليها ومعه جَيْشٌ عَظيمٌ."},{"id":398,"title":"وَفاةُ موسى بن نُصَير .","date":["العام الهجري :97","العام الميلادي :715"],"text":"هو أبو عبدِ الرَّحمن موسى بن عبدِ الرَّحمن بن زَيْدٍ اللَّخْمِيُّ، صاحِبُ فُتوحات الغَربِ، يُقالُ: إنَّه كان أَعْرَجًا. قِيلَ: أَصلُه مِن عَيْنِ التَّمْرِ، وقِيلَ: هو مَوْلًى لِبَنِي أُمَيَّة، وقِيلَ: لامْرَأَةٍ مِن لَخْمٍ وُلِدَ بِقَريَةِ كفرتُوثا مِن قُرَى الجَزيرَة, كان شُجاعًا مِقْدامًا جَوادًا، أَحَد قادَة الدَّولَة الأُمَويَّة، وَلَّاهُ مُعاوِيَةُ بن أبي سُفيان غَزْوَ البَحرِ، فغَزَا قُبْرُص وبَنَى بها حُصونًا ثمَّ غَزَا غَيرَها؛ وطالَت أيَّامُه وفَتَح الفُتوحات العَظيمَة بِبِلادِ المَغرِب، وغَنِمَ منها أَموالًا لا تُعَدُّ ولا تُوصَف، وله بها مَقامات مَشهورَة هائِلَة، واسْتَطاع أن يُنْهِي نَزَعات البَرْبَر المُتَوالِيَة للخُروج على حُكْم الأُمَويِّين. أَرسَلَ مَوْلاهُ طارِقَ بن زِياد لِفَتْحِ الأندَلُس،ثمَّ شارَكَهُ في إتمام فَتحِها, وهي بِلاد ذات مُدُن وقُرَى ورِيف، فسَبَى منها ومِن غَيرِها خَلْقًا كَثيرًا، وغَنِمَ أَموالًا جَزيلةً، مِن الذَّهَب والجَواهِر النَّفِيسَة والدَّوابِّ والغِلْمان والنِّساء الحِسان شَيْئًا لا يُحْصَى ولا يُعَدُّ، حتَّى قِيلَ: إنَّه لم يُسْبِ أَحَدٌ مِثلَه مِن الأعداء، وأَسلَم أَهلُ المَغرِب على يَديهِ، وبَثَّ فيهم الدِّينَ والقُرآنَ، وكان إذا سار إلى مَكانٍ تُحْمَل الأَموالُ معه على العَجَلِ لِكَثْرَتِها وعَجْزِ الدَّوابِّ عنها. كان موسى بن نُصَير هذا يَفتَح في بِلادِ المَغرِب، وقُتيبَة يَفتَح في بِلادِ المَشرِق، فجَزاهُما الله خيرًا، فكِلاهُما فَتَح مِن الأقاليم والبُلْدان شَيْئًا كَثيرًا."},{"id":399,"title":"حِصارُ مَسلمَة بن عبدِ الملك للقُسطنطينيَّة \n  .","date":["العام الهجري :98","العام الميلادي :716"],"text":"أَمَرَ سُليمانُ بن عبدِ الملك أَخاهُ مَسلمَة بالسَّيْرِ إلى القُسطنطينيَّة وألَّا يَعود حتَّى يَفتَحها، فَجَهَّزَهُ بمائةٍ وعشرين ألفًا في البَرِّ، ومائةٍ وعشرين ألفًا مِن المُقاتِلَة في البَحْرِ، وأَخرَج لهم الأُعْطِيات، وأَنفَق فيهم الأَموالَ الكَثيرَة، وأَعلَمَهم بِغَزْوِ القُسطنطينيَّة والإقامَة عليها إلى أن يَفتَحوها، ولمَّا اجْتَمَع العَساكِر عند سُليمان أَمَّرَ عليهم أَخاه مَسلمَة، وكان معه داودُ بن سُليمان بن عبدِ الملك, فسار الجَيْش إلى أن نَزلُوا على القُسطنطينيَّة فحاصَرَها عامًا كامِلًا فشَتَوْا وصافُوا بها، حتَّى عَرَضَ أَهلُها الجِزْيَةَ على مَسلمَة، فأَبَى إلَّا أن يَفتَحها عَنْوَةً, وبَقوا مُحاصِرين القُسطنطينيَّة دون جَدْوَى إلى أن تُوفِّيَ سُليمان بن عبدِ الملك في العاشِر مِن صَفَر سَنَة 99هـ، وتَوَلَّى عُمَرُ بن عبدِ العزيز الخِلافَةَ، فعادوا إلى الشَّامِ دون أن يَفتَحوا القُسطنطينيَّة."},{"id":400,"title":"فَتْحُ يَزيدَ بن المُهَلَّب طَبَرِسْتان  .","date":["العام الهجري :98","العام الميلادي :716"],"text":"لمَّا فَتَح يَزيدُ بن المُهَلَّب قُهِسْتان وجُرْجان طَمِعَ في طَبَرِسْتان أن يَفْتَحها، فَعَزَم على أن يَسيرَ إليها، فاسْتَعمَل عبدَ الله بن المُعَمَّر اليَشْكُرِيَّ على السَّاسان وقُهِسْتان، وخَلَّفَ معه أَربعةَ آلاف، ثمَّ أَقبَل إلى أَدانِي جُرجان مما يَلِي طَبَرِسْتان، فاسْتَعمَل على أَيْذُوسا راشِدَ بن عَمرٍو، وجَعَلَه في أَربعةِ آلاف، ودَخَل بِلادَ طَبَرِسْتان، فأَرسَل إليه الإِصْبَهْبَذ صاحِبُها يَسألُه الصُّلْحَ وأن يَخرُج مِن طَبَرِسْتان، فأَبَى يَزيدُ، ورَجَا أن يَفْتَتِحَها، ووَجَّه أَخاهُ أبا عُيَينَة مِن وَجْهٍ، وابنَه خالدَ بن يَزيدَ مِن وَجْهٍ، وأبا الجَهْم الكَلْبِيَّ مِن وَجْهٍ، وقال: إذا اجْتَمعتُم فأَبُو عُيينَة على النَّاس. فسار أبو عُيينَة وأقام يَزيدُ مُعَسْكِرًا, واسْتَجاش الإصْبَهْبَذ أَهلَ جِيلان والدَّيْلَم، فأَتوه فالْتَقوا في سَفْحِ جَبلٍ، فانْهَزَم المشركون في الجَبلِ، فاتَّبَعهُم المسلمون حتَّى انْتَهوا إلى فَمِ الشِّعْبِ، فدَخلَه المسلمون وصَعَد المشركون في الجَبلِ واتَّبَعَهم المسلمون يَرومُون الصُّعود، فرَماهُم العَدُوُّ بالنِّشابِ والحِجارَةِ، فانْهَزَم أبو عُيينَة والمسلمون يَركَب بَعضُهم بَعضًا، يَتَساقَطون في الجَبلِ حتَّى انْتَهوا إلى عَسْكَرِ يَزيدَ، وكَفَّ عَدُوُّهم عن اتِّباعِهم، وخافَهُم الإصْبَهْبَذ، فكان أَهلُ جُرجان ومُقَدِّمُهم المَرْزبان يَسأَلُهم أن يُبَيِّتُوا مَن عندهم مِن المسلمين، وأن يَقطَعوا عن يَزيدَ المادَّةَ والطَّريقَ فيما بينه وبين بِلادِ الإسلام، ويَعِدُهم أن يُكافِئَهم على ذلك، فثاروا بالمسلمين، فقَتَلوهُم أَجمعين وهُم غارُون في لَيلةٍ، وقُتِلَ عبدُ الله بن المُعَمَّر وجَميعُ مَن معه فلم يَنْجُ منهم أَحَدٌ، وكَتَبوا إلى الإصْبَهْبَذ بِأَخْذِ المَضايِق والطُّرُق. وبَلَغ ذلك يَزيدَ وأَصحابَه فعَظُمَ عليهم وهالَهُم، وفَزِعَ يَزيدُ إلى حَيَّان النَّبَطِي وقال له: لا يَمنَعك ما كان مِنِّي إليك مِن نَصيحَة المسلمين، وقد جاءَنا عن جُرجان ما جاءَنا، فاعْمَل في الصُّلْح. فقال: نعم. فأَتَى حَيَّانُ الإصْبَهْبَذ فقال: أنا رَجُلٌ منكم، وإن كان الدِّينُ فَرَّقَ بيني وبينكم، فأنا لكم ناصِح، فأنت أَحَبُّ إِلَيَّ مِن يَزيدَ، وقد بَعَث يَسْتَمِدُّ وأَمْدادُه منه قَريبَة، وإنَّما أصابوا منه طَرَفًا، ولست آمَن أن يأتيك مَن لا تقوم له، فأَرِحْ نَفسَك وصالِحْه، فإن صالَحتَه صَيَّرَ حَدَّهُ على أَهلِ جُرجان بِغَدْرِهِم وقَتْلِهم أَصحابَه. فصالَحَهُ على سَبعمائة ألف، وقِيلَ: خَمسمائة ألف، وأربعمائة وَقْرِ زَعْفَران، أو قِيمتِه مِن العَيْنِ، وأَربعمائة رَجُلٍ، على كُلِّ رَجُلٍ منهم تُرْسٌ وطَيْلَسان، ومع كُلِّ رَجُل جامٌ مِن فِضَّة وخِرْقَة حَرير وكُسْوَة. ثمَّ رَجَع حَيَّانُ إلى يَزيدَ، فقال: ابْعَث مَن يَحْمِل صُلْحَهُم. فقال: مِن عندهم أو مِن عندنا؟ قال: مِن عندهم. وكان يَزيد قد طابت نَفسُه أن يُعطِيَهم ما سَأَلوا ويَرجِع إلى جُرجان، فأَرسَل إلى يَزيد مَن يَقبِض ما صالَحَهم عليه حَيَّان."},{"id":401,"title":"فَتْحُ يَزيد بن المُهَلَّب جُرجان الفَتْح الأوَّل .","date":["العام الهجري :98","العام الميلادي :716"],"text":"كان سُليمان بن عبدِ الملك كُلَّما فَتَح قُتيبةُ بن مُسلِم فَتْحًا في عَهدِ الوَليد يقول لِيَزيد بن المُهَلَّب: ألا تَرَى إلى ما يَفتَح الله على قُتيبَة؟ فيقول يَزيدُ: ما فَعَلَت جُرجان التي قَطَعَت الطَّريقَ، وأَفْسَدت قُومِس ونَيْسابور. ويقول أَيضًا: هذه الفُتوح لَيسَت بِشَيءٍ، الشَّأنُ هي جُرجان. فلمَّا وَلَّاهُ سُليمانُ خُراسانَ لم يكن لِيَزيد هِمَّة غَير جُرجان، فسار إليها في مائةِ ألف مِن أَهلِ الشَّام والعِراق وخُراسان سِوَى المَوالِي والمُتَطَوِّعَة، ولم تكُن جُرجان يَومئذٍ مَدينَة إنَّما هي جِبالُ ومَخارِم وأَبواب يقوم الرَّجُلُ على بابٍ منها فلا يُقْدِم عليه أَحَدٌ. فابْتَدَأَ بقُهِسْتان فحاصَرَها، وكان ذلك، فإذا هُزِمُوا دَخَلوا الحِصْنَ. فخَرَجوا ذات يَومٍ وخَرَج إليهم النَّاسُ فاقْتَتَلوا قِتالًا شديدًا، فحَمَل محمَّدُ بن سَبْرَة على تُرْكِيٍّ قد صَدَّ النَّاسَ عنه فاخْتَلَفا ضَرْبَتينِ، فثَبُتَ سَيفُ الترُّكي في بَيْضَة ابنِ أبي سَبْرَة، وضَرَبَه ابنُ أبي سَبْرَة فقَتَلَه، ورَجَع وسَيفُه يَقطُر دَمًا وسَيفُ الترُّكي في بَيْضَتِه، فنَظَر النَّاسُ إلى أَحسَن مَنظَرٍ رَأَوْهُ. وخَرَج يَزيدُ بعدَ ذلك يَومًا يَنظُر مَكانًا يَدخُل منه عليهم، وكان في أربعمائة مِن وُجوهِ النَّاسِ وفُرسانِهم، فلم يَشعروا حتَّى هَجَم عليهم التُّركُ في نحو أربعةِ آلاف فقاتَلوهُم ساعَة، وقاتَلَ يَزيدُ قِتالًا شديدًا، فسَلِمُوا وانْصَرَفوا، وكانوا قد عَطِشُوا، فانْتَهوا إلى الماءِ فشَرِبوا، ورَجَع عنهم العَدُوُّ. ثمَّ إنَّ يَزيدَ أَلَحَّ عليهم في القِتال وقَطَع عنهم المَوادَّ حتَّى ضَعُفوا وعَجَزوا. فأَرسَل صُول دِهْقان قُهِسْتان إلى يَزيدَ يَطلُب منه أن يُصالِحَه ويُؤَمِّنَه على نَفسِه وأَهلِه ومالِه لِيَدفَع إليه المَدينَة بما فيها، فصالَحَه ووَفَّى له، ودَخَل المَدينَة فأَخَذ ما كان فيها مِن الأَموالِ والكُنوزِ والسَّبْيِ ما لا يُحصَى، وقَتَل أَربعةَ عَشر ألف تُرْكِي صَبْرًا، وكَتَب إلى سُليمان بن عبدِ الملك بذلك، ثمَّ خَرَج حتَّى أَتَى جُرجان، وكان أَهلُ جُرجان قد صالَحَهم سَعيدُ بن العاص، وكانوا يَجْبُون أَحيانًا مائة ألف، وأَحيانًا مائتي ألف، وأَحيانًا ثلاثمائة ألف، ورُبَّما أَعطوا ذلك ورُبَّما مَنَعوه، ثمَّ امْتَنَعوا وكَفَروا فلم يُعْطوا خَراجًا، ولم يَأْتِ جُرجانَ بعدَ سَعيدٍ أَحَدٌ ومَنَعوا ذلك الطَّريق، فلم يكُن يَسلُك طَريقَ خُراسان أَحَدٌ إلَّا على فارِس وكَرْمان. وبَقِيَ أَمرُ جُرجان كذلك حتَّى وَلِيَ يَزيدُ خُراسان وأَتاهُم فاسْتَقبَلوه بالصُّلْح وزادوه وهابوه، فأَجابَهم إلى ذلك وصالَحَهم. وقد أَصابَ يَزيدُ بجُرجان تاجًا فيه جَوْهَر، فقال: أَتَرَوْنَ أَحدًا يَزهَد في هذا؟ قالوا: لا. فدَعا محمَّد بن واسِع الأزدي فقال: خُذْ هذا التَّاجَ. قال: لا حاجَة لي فيه. قال: عَزَمْتُ عليك. فأَخَذه، فأَمَر يَزيدُ رَجُلًا يَنظُر ما يَصنَع به، فلَقِيَ سائِلًا فدَفَعَه إليه، فأَخَذ الرَّجُلَ السَّائِلَ وأَتَى به يَزيدَ وأَخبَره، فأَخَذ يَزيدُ التَّاجَ وعَوَّضَ السَّائِلَ مالًا كَثيرًا."},{"id":402,"title":"فَتْحُ يَزيد بن المُهَلَّب جُرجان الفَتْح الثَّاني .","date":["العام الهجري :98","العام الميلادي :716"],"text":"كان يَزيدُ فَتَح جُرجان وقُهِسْتان ثمَّ غَدَر أَهلُ جُرجان، فلمَّا صالَح يَزيدُ إصْبَهْبَذ صاحِبَ طَبَرِسْتان سار إلى جُرجان، وعاهَد الله تعالى لَئِن ظَفَر بهم لا يَرفَع السَّيفَ حتَّى يَطحَن بِدِمائِهم، ويَأكُل مِن ذلك الطَّحِين. فأَتاها فحَصَرهم يَزيدُ فيها سَبعةَ أَشهُر، وهُم يَخرُجون إليه في الأيَّام فيُقاتِلونَه ويَرجِعون, فبَيْنَا هُم على ذلك إذ خَرَج رَجَلٌ مِن عَجَم خُراسان يَتَصَيَّد، وقِيلَ: رَجُل مِن طَيِّء، فأَبْصَر وَعْلًا في الجَبلِ، ولم يَشعُر حتَّى هَجَم على عَسكَرِهم، فرَجَع كأنَّه يُريدُ أَصحابَه، وجَعَل يَخْرِق قَباءَه ويَعقِد على الشَّجَرِ عَلامات، فأَتَى يَزيدُ فأَخبرَه، فضَمَنَ له يَزيدُ دِيَةً إن دَلَّهُم على الحِصْن، فانْتَخَب معه ثلاثمائة رَجُل، واسْتَعمَل عليهم ابنَه خالدَ بن يَزيدَ، وقال له: إن غُلِبْتَ على الحَياةِ فلا تُغْلَبَنَّ على المَوتِ، وإيَّاك أن أراك عندي مَهْزومًا. وضَمَّ إليه جَهْمَ بن زَحْر، وقال للرَّجُل: مَتَى تَصِلون؟ قال: غَدًا العَصرَ. قال يَزيدُ: سأَجْهَدُ على مُناهَضَتِهم عند الظُّهْر. فساروا فلمَّا كان الغَدُ وَقْتَ الظُّهْر أَحْرَق يَزيدُ كُلَّ حَطَب كان عندهم، فصار مِثل الجِبال مِن النِّيران، فنَظَر العَدُوُّ إلى النِّيران فهالَهُم ذلك فخَرجوا إليهم، وتَقدَّم يَزيدُ إليهم فاقْتَتلوا، وهَجَم أَصحابُ يَزيدَ الذين ساروا على عَسْكَرِ التُّرك قبلَ العَصرِ وهُم آمِنون مِن ذلك الوَجْهِ، ويَزيدُ يُقاتِلُهم مِن هذا الوَجْهِ، فما شَعَروا إلَّا بالتَّكْبيرِ مِن وَرائِهم، فانْقَطَعوا جَميعًا إلى حِصْنِهم، ورَكِبَهم المسلمون فأَعْطوا بِأَيدِيهم، ونَزَلوا على حُكْم يَزيد، وسَبَى أَهلَها وغَنِمَ ما فيها، وقَتَل مُقاتِلَتَهم، وصَلَبَهم فَرْسَخَيْنِ إلى يَمينِ الطَّريقِ ويَسارِه، وقاد منهم اثني عَشر ألفًا إلى وادي جُرجان وقال: مَن طَلَبَهم بِثَأْرٍ فلْيُقْتَل. فكان الرَّجُل مِن المسلمين يَقتُل الأَربعَة والخَمسَة، وأَجرَى الماءَ على الدَّمِ وعليه أَرْحاء لِيَطْحَنَ بِدِمائِهم لِيُبِرَّ يَمينَه، فطَحَنَ وخَبَزَ وأَكَل، وقِيلَ: قَتَل منهم أَربعينَ ألفًا, وبَنَى مَدينَة جُرجان، ولم تكُن بُنِيت قبلَ ذلك مَدينةً، ورَجَع إلى خُراسان، واسْتَعمَل على جُرجان جَهْم بن زَحْر الجُعفي، وكَتَب إلى سُليمان بالفَتْح يُعَظِّمُه ويُخبِره أنَّه قد حَصَل عنده مِن الخُمُس ستُّمائة ألف ألف، فقال له كاتِبُه المُغيرَة بن أبي قُرَّة مَوْلَى بَنِي سَدوس لا تَكتُب تَسمِيَةَ المالِ، فإنَّك مِن ذلك بين أَمرَيْنِ، إمَّا اسْتَكْثَرَهُ فأَمَرَك بِحَمْلِه، وإمَّا سَمَحَت نَفْسُه لك به فأَعطاكَه، فتَكَلَّف الهَدِيَّة، فلا يَأتِيه مِن قِبَلِك شَيءٌ إلَّا اسْتَقَلَّهُ، فكأَنِّي بك قد اسْتَغْرَقْتَ ما سَمَّيْتَ ولم يَقَع منه مَوْقِعًا، ويَبْقَى المالُ الذي سَمَّيْتَ مُخَلَّدًا في دَواوينِهم، فإن وَلِيَ والٍ بعدَه أَخَذَك به، وإن وَلِيَ مَن يَتَحامَل عليك لم يَرْضَ بأَضعافِه، ولكن اكتُب فَسَلْهُ القُدومَ، وشافِهْهُ بما أَحبَبتَ فهو أَسْلَم. فلم يقبل منه وأَمضَى الكِتابَ، وقِيلَ: كان المَبلَغ أربعة آلاف ألف."},{"id":403,"title":"وَفاةُ عُبيدِ الله بن عبدِ الله بن مَسعودٍ أَحَد الفُقَهاء السَّبعَة في المَدينَة .","date":["العام الهجري :98","العام الميلادي :716"],"text":"هو عُبيدُ الله بن عبدِ الله بن عُتْبَة بن مَسعودٍ أَحَدُ الفُقَهاء السَّبعَة بالمَدينَة، مُفْتِي المَدينَة وعالِمُها، حَدَّثَ عن ابنِ عَبَّاس ولازَمَهُ طَويلًا، وعن عائِشَةَ، وأبي هُريرةَ، وغَيرِهم، وهو مُعَلِّم عُمَر بن عبدِ العزيز، كان يُطيلُ الصَّلاةَ ولا يُعَجِّلُها لِأَحَدٍ."},{"id":404,"title":"وَفاةُ خارِجَة بن زَيدٍ أَحَد الفُقَهاء السَّبعَة في المَدينَة .","date":["العام الهجري :99","العام الميلادي :717"],"text":"هو خارِجَة بن زَيدِ بن ثابِت، أَحَد الفُقَهاء السَّبعَة بالمَدينَة، رَوَى عن أَبيهِ وعن غيره مِن الصَّحابَة، قال مُصعَبُ بن الزُّبير: كان خارِجَة بن زَيدٍ، وطَلحَة بن عبدِ الله بن عَوْف في زَمانِهِما يُسْتَفْتَيان، ويَنتَهِي النَّاسُ إلى قَولِهِما، ويَقْسِمان المَواريثَ بين أَهلِها مِن الدُّورِ والنَّخيل والأَموال، ويَكْتُبان الوَثائِقَ للنَّاسِ."},{"id":405,"title":"وَفاةُ الخَليفَة سُليمان بن عبدِ الملك .","date":["العام الهجري :99","الشهر القمري : صفر","العام الميلادي :717"],"text":"هو سُليمان بن عبدِ الملك بن مَرْوان بن الحَكَم بن أبي العاص بن أُمَيَّة بن عبدِ شَمس القُرشيُّ الأُمَويُّ، أبو أَيُّوب. كان مَولِده بالمدينة في بني جَذيلَة، وهو الخَليفَة الأُمَوي السَّابِع، ويُعَدُّ مِن خُلفاء بني أُمَيَّة الأقوِياء, وُلِدَ بدِمشق عام 54هـ ووَلِيَ الخِلافَة بعدَ أَخيه الوَليد  عام 96هـ. ومُدَّة خِلافَتِه لا تَتَجاوز السَّنَتيْنِ وسَبعَة شُهور. كان النَّاس في دِمشق يُسَمُّونه مُفتاحَ الخَير، ذَهَبَ عنهم الحَجَّاجُ، فوَلِيَ سُليمان، أَحَبَّهُ النَّاسُ وتباركوا به، أَشاعَ العَدلَ، وأَنصفَ كُلَّ مَن وَقَف بِبابِه، كان فَصيحًا, ويَتَّصِفُ بالجَمالِ والوَقارِ، عَظيم الخِلْقَة، طَويل القامَة، أَبيض الوَجْه، مَقْرون الحاجِبَيْنِ، فصيحًا بليغًا، عَمِلَ في فَترةِ تَوْلِيَةِ الخِلافَة كُلَّ ما فيه مَصلحَة النَّاس، وحافَظَ على اتِّساع وقُوَّة الدَّولة الأُمويَّة، واهْتَمَّ بِكُلِّ ما يَعْنِي النَّاس، أَطلَق الأَسْرَى، وأَخلَى السُّجونَ، وأَحسَن مُعاملَة الجَميعَ، فكَسَب مَحَبَّتَهم، وكان مِن أَعدَل خُلفاء بني أُمَيَّة والمسلمين، واسْتَخْلَف عُمَرَ بن عبدِ العزيز مِن بَعدِه. مُحِبًّا للغَزْوِ، فَتَحَ في عَهدِه جُرجان وطَبَرِسْتان، وجَهَّزَ جَيشًا كَبيرًا مِن سَواحِل الشَّامِ بقِيادَة أَخيهِ مَسلمَة ومعه ابنُه داود، وسَيَّرَهُ في السُّفُن لِحِصارِ القُسطنطينيَّة، وسار سُليمان بن عبدِ الملك مع الحَمْلَة حتَّى بَلَغ دابِق، وعَزَم أن لا يَعود منها حتَّى تُفتَح القُسطنطينيَّة أو يموت، فمات مُرابِطًا في دابِق شَمالَ مَدينَة حَلَب."},{"id":406,"title":"عُمَر بن عبدِ العزيز يَتَوَلَّى الخِلافَة الأُمَويَّة .","date":["العام الهجري :99","الشهر القمري : صفر","العام الميلادي :717"],"text":"لمَّا قَرُبَت وَفاةُ سُليمان كان يُريد أن يَعْهَد لِوَلَدِهِ داود؛ لكنَّ رَجاء بن حَيْوَة صَرَفَهُ عن ذلك، فسَأَلَهُ عن عُمَر بن عبدِ العزيز فأَثْنَى رَجاءُ عليه، فجَعَل سُليمانُ الأَمْرَ لِعُمَر بن عبدِ العزيز، ثمَّ لِيَزيد بن عبدِ الملك بَعدَهُ، فكان لِرَجاء الفَضْل في إحْكام ذلك بعدَ مَوتِ سُليمان، فقرأ عليهم كِتابَ سُليمان بعدَ أن أَخَذَ البَيْعَةَ على الكِتابِ منهم، ثمَّ أَجْلَس عُمَرَ بن عبدِ العزيز على المِنْبَر بعدَ أن صَلَّى عُمَرُ على سُليمان، ثمَّ انْتَقل إلى دارِ الخِلافَة بعدَ أن فَرَغَت مِن أَهلِ سُليمان وبايَعَه كذلك عبدُ العزيز بن الوَليد، وبذلك تَمَّت له الخِلافَةُ."},{"id":407,"title":"بداية نشأة الدَّعْوَة العَبَّاسِيَّة .","date":["العام الهجري :100","العام الميلادي :718"],"text":"وَجَّهَ محمَّدُ بن عَلِيِّ بن عبدِ الله بن عَبَّاس الدُّعاة في الآفاق، وكان سَبَب ذلك أنَّ أبا هاشِم عبدَ الله بن محمَّد بن الحَنَفِيَّة سار للشَّام إلى سُليمان بن عبدِ الملك، فلمَّا أَكرَمَه وقَضَى حَوائِجَه، ورَأَى مِن عِلْمِه وفَصاحَتِه ما حَسَدهُ عليه وخافه، فلمَّا أَحَسَّ أبو هاشِم بالشَّرِّ قَصَدَ الحُمَيْمَة مِن أَرضِ الشَّراةِ بالأردن، وبها محمَّدُ بن عَلِيِّ بن عبدِ الله بن عَبَّاس، فنَزَل عليه وأَعْلَمَه أنَّ هذا الأَمْرَ صائِرٌ إلى وَلَدِه، وعَرَّفَه ما يَعمَل، وكان محمَّدُ بن عَلِيٍّ رَجُلًا طَموحًا، فحَمَل فِكْرَةَ إِزالَة مُلْكِ بني أُمَيَّة، وبَدَأ يَعمَل على تَنفيذِها. كان أبو هاشِم عبدُ الله بن محمَّد بن الحَنَفِيَّة قد أَعلَم شِيعَتَه مِن أَهلِ خُراسان والعِراق عند تَرَدُّدِهِم إليه أنَّ الأمرَ صائِرٌ إلى وَلَدِ محمَّد بن عَلِيِّ بن عبدِ الله بن عَبَّاس، وأَمَرَهم بِقَصْدِه بَعدَهُ. فلمَّا مات أبو هاشِم قَصَدوا محمَّدًا وبايَعوهُ، وعادوا فدَعوا النَّاسَ إليه، فأَجابوهُم, وكان الذين سَيَّرَهُم إلى الآفاق جَماعةً، وأَمَرَهُم بالدُّعاء إليه وإلى أَهلِ بَيتِه، فلَقوا مَن لَقوا، ثمَّ انْصَرفوا بكُتُبِ مَن اسْتَجاب لهم إلى محمَّد بن عَلِيٍّ، فدَفَعوها إلى مَيْسَرة، فبَعَثَ بها مَيسَرةُ إلى محمَّدِ بن عَلِيِّ بن عبدِ الله بن عَبَّاس، فاخْتار أبو محمَّد الصَّادِق لِمحمَّدِ بن عَلِيٍّ اثْنَي عَشَر رَجُلًا نُقَباء، واخْتَار سَبعين رَجُلًا، وكَتَب إليهم محمَّدُ بن عَلِيٍّ كِتابًا ليكون لهم مِثالًا وسِيرَةً يَسِيرون بها."},{"id":408,"title":"خُروجُ بِسْطام اليَشْكُرِيِّ على عُمَر بن عبدِ العزيز  .","date":["العام الهجري :100","العام الميلادي :718"],"text":"خَرجَت خارِجَة مِن الحَرورِيَّة بالعِراق، يَتَزَعَّمُهم شَوْذَب واسْمُه بِسْطام مِن بَنِي يَشْكُر في ثمانين فارِسًا أَكثرُهم مِن رَبيعَة، فبَعَث أَميرُ المؤمنين عُمَرُ بن عبدِ العزيز إلى عبدِ الحَميدِ نائِب الكوفَة يَأمُرهُ بأن يَدعوهم إلى الحَقِّ، ويَتَلَطَّف بِهم، ولا يُقاتِلهم حتَّى يُفسِدوا في الأَرضِ، فلمَّا فَعَلوا ذلك بَعَث إليهم جَيْشًا فكَسَرهُم الحَرورِيَّةُ، فبَعَث عُمَرُ إليه يَلومُه على جَيْشِه، وقد أَرسَل عُمَرُ إلى بِسْطام يَقولُ له: ما أَخْرَجَك عَلَيَّ؟ فإن كُنتَ خَرجتَ غَضَبًا لله فأنا أَحَقُّ بذلك مِنك، ولستَ أَوْلى بذلك مِنِّي، وهَلُمَّ أُناظِرُك; فإن رَأيتَ حَقًّا اتَّبَعْتَه، وإن أَبْدَيْتَ حَقًّا نَظَرْنا فيه. فبَعَث طائِفَةً مِن أَصحابِه إليه، فاخْتارَ منهم عُمَرُ رَجُلين فسَأَلهُما: ماذا تَنْقِمون؟ فقالا: جَعْلَكَ يَزيد بن عبدِ الملك مِن بَعدِك. فقال: إنِّي لم أَجْعَله أَبَدًا، وإنَّما جَعلَه غَيْري. قالا: فكيف تَرْضَى به أَمينًا للأُمَّةِ مِن بَعدِك؟ فقال: أَنْظِرْني ثَلاثَة. فيُقال: إنَّ بَنِي أُمَيَّة دَسَّتْ إليه سُمًّا فقَتَلوه; خَشْيَةَ أن يَخرُج الأَمرُ مِن أَيديهِم. فلمَّا مات عُمَرُ أراد عَبدُ الحَميد بن عبدِ الرحمن أن يَحْظَى عند يَزيد بن عبدِ الملك، فكَتَب إلى محمَّدِ بن جَريرٍ يَأمُرُه بمُحارَبَة شَوْذَب وأَصحابِه، فبَرَزَ له شَوْذَب فاقْتَتَلوا، وأُصِيبَ مِن الخَوارِج نَفَرٌ، وأَكثَروا في أَهلِ الكوفَة القَتْل، فوَلُّوا مُنْهَزِمين والخَوارِجُ في أَكتافِهم حتَّى بَلَغوا أَخْصاص الكوفَة، فأَقَرَّ يَزيدُ عبدَ الحَميد على الكوفَة، ووَجَّهَ مِن قِبَلِهِ تَميمَ بن الحُباب في أَلْفَيْنِ فقَتَلوه وهَزَموا أَصحابَه، فوَجَّهَ إليهم نَجْدَةَ بن الحَكَم الأَزْدِي في جَمْعٍ، فقَتَلوه وهَزَموا أَصحابَه، فبَعَث آخَر في أَلْفَيْنِ فقَتَلوه، فأَنْفَذَ يَزيدُ أَخاهُ مَسلمةَ بن عبدِ الملك، فنَزَل الكوفَة، ودَعا سَعيدَ بن عَمرٍو الحَرَشِي، فعَقَدَ له على عَشرَة آلافٍ ووَجَّهَهُ، فقال لأَصحابِه: مَن كان يُريدُ الله عَزَّ وجَلَّ فقد جاءَتْهُ الشَّهادَة، ومَن كان إنَّما خَرَج للدُّنيا فقد ذَهبَت الدُّنيا منه. فكَسَروا أَغْمادَ سُيوفِهِم وحَمَلوا على الخَوارِج حتَّى طَحَنوهُم وقَتَلوا شَوْذَبًا."},{"id":409,"title":"تَوَلِّي السَّمْح بن مالِك الخَوْلاني الأَنْدَلُس  .","date":["العام الهجري :100","العام الميلادي :718"],"text":"لمَّا وَلِيَ عُمَرُ بن عبدِ العزيز الخِلافَةَ اسْتَعمَل على الأَندَلُس السَّمْحَ بن مالِك الخَوْلاني خَلَفًا للحُرِّ بن عبدِ الرَّحمن الثَّقَفي لِمَا رَأَى مِن أَمانَتِه ودِيانَتِه, وأَمَره أن يُمَيِّز أَرضَها، ويُخرِج منها ما كان عَنْوَةً ويَأخُذ منها الخُمُسَ، ويَكتُب إليه بِصِفَة الأَندَلُس. فقَدِمَها السَّمْحُ، وفَعَل ما أَمَره عُمَرُ، وعَهِدَ إليه بإجْلاءِ المسلمين مِن الأَندَلُس خَشيَةً مِنه على أَرواحِهم، إلَّا أنَّ السَّمْح حين نَزَل الأَندَلُس واطَّلَع على أَحوالِها، طَمْأَنَ الخَليفةَ إلى قُوَّةِ حالِ المسلمين في الأَندَلُس. أَصلَح السَّمْحُ قَنْطَرَةَ قُرْطُبة على نَهرِ الوادي الكَبير, ونَظَّمَ البِلادَ ثمَّ تَوَجَّه لِفَتْحِ ما وَراءَ جِبالِ البرانس، ودَخَل فَرنسا واسْتُشْهِدَ فيها بعدَ مَعركَة تولوز عام 102هـ."}]
